// Regras com matchIds identificam quem jogou somente nos mapas confirmados;
// elas não autorizam cadastrar a conta como alternativa global dessa pessoa.
// Sem matchIds, a coexistência de TODAS as contas descritas ativa a regra.
function sharedAccountOverrides(matchPuuids, matchId = null) {
  const overrides = new Map();
  for (const rule of SHARED_ACCOUNT_RULES) {
    if (rule.matchIds && !rule.matchIds.includes(matchId)) continue;
    const accounts = Object.keys(rule.accounts);
    if (!accounts.every((account) => matchPuuids.has(account))) continue;
    for (const account of accounts) overrides.set(account, rule.accounts[account]);
  }
  return overrides;
}

function assertOnePersonPerMatch(players, matchId, sourcePath) {
  const seenById = new Map();
  for (const player of players) {
    const previous = seenById.get(player.id);
    if (previous) {
      throw new Error(
        `${sourcePath || matchId || "partida"}: as contas ${previous.handle} e ${player.handle} resolvem para a ` +
          `mesma pessoa (${player.nick}). Se foi conta emprestada, descreva o par em SHARED_ACCOUNT_RULES dizendo ` +
          `quem estava em cada conta; se são pessoas diferentes, separe as contas nas colunas "puuid N" de ` +
          `dados_excel/players.xlsx.`,
      );
    }
    seenById.set(player.id, player);
  }
}

function normalizeMatchPlayer(player, roundAgg, metadata, personOverride = null) {
  const registered = personOverride || resolveRegisteredPlayer(player, metadata);
  const agentMeta = resolveAgentMeta(player.characterId, metadata);
  const rounds = player.stats?.roundsPlayed || roundAgg.rounds || 0;
  const kills = player.stats?.kills || 0;
  const deaths = player.stats?.deaths || 0;
  const assists = player.stats?.assists || 0;
  const score = player.stats?.score || 0;
  const damage = roundAgg.damage;
  const adr = rounds ? damage / rounds : 0;
  const acs = rounds ? score / rounds : 0;
  const kd = deaths ? kills / deaths : kills;
  const kpr = rounds ? kills / rounds : 0;
  const dpr = rounds ? deaths / rounds : 0;
  const apr = rounds ? assists / rounds : 0;
  const kastRounds = roundAgg.kastRounds || 0;
  const kastFrac = rounds ? kastRounds / rounds : 0;
  const kast = kastFrac * 100;
  const kastLegacyRounds = roundAgg.kastLegacyRounds ?? kastRounds;
  const kastLegacyFrac = rounds ? kastLegacyRounds / rounds : 0;
  const kastLegacy = kastLegacyFrac * 100;
  const impactTotal = roundAgg.impactTotal || 0;
  const impactRound = rounds ? impactTotal / rounds : 0;
  const impactTotalLegacy = roundAgg.impactTotalLegacy ?? impactTotal;
  const impactRoundLegacy = rounds ? impactTotalLegacy / rounds : 0;
  const headshotTotal = roundAgg.headshots + roundAgg.bodyshots + roundAgg.legshots;

  const output = {
    // id = identidade da pessoa (une contas alternativas via metadata);
    // puuid = conta Riot usada nesta partida (chave para roundResults brutos).
    id: registered ? registered.puuid || `registered-${slugify(registered.name)}` : player.puuid,
    puuid: player.puuid,
    nick: registered?.name || player.gameName || "Jogador",
    apiNick: player.gameName || "Jogador",
    tagLine: player.tagLine || "",
    handle: `${player.gameName || "Jogador"}#${player.tagLine || ""}`,
    registered: Boolean(registered) && !registered?.unconfirmedAccount,
    currentTeam: registered?.currentTeam || "",
    teamHistory: registered?.teamHistory || [],
    nickHistory: registered?.nickHistory || [],
    photo: registered?.photo || "",
    teamColor: player.teamId,
    agentId: player.characterId,
    agentSlug: agentMeta.slug,
    agent: agentMeta.name,
    agentClass: agentMeta.role,
    agentIcon: agentMeta.icon,
    rounds,
    roundWins: roundAgg.roundWins || 0,
    roundLosses: roundAgg.roundLosses || 0,
    kills,
    deaths,
    assists,
    score,
    damage,
    adr,
    acs,
    kd,
    kpr,
    dpr,
    apr,
    kast,
    kastFrac,
    kastRounds,
    kastLegacy,
    kastLegacyFrac,
    kastLegacyRounds,
    impactTotal,
    impactRound,
    impactTotalLegacy,
    impactRoundLegacy,
    adjustedRoundSwingTotalPp: roundAgg.adjustedRoundSwingTotalPp ?? impactTotal,
    eKillPoints: roundAgg.eKillPoints ?? kills,
    eDeathPoints: roundAgg.eDeathPoints ?? deaths,
    eDamageTotal: roundAgg.eDamageTotal ?? damage,
    eKastPoints: roundAgg.eKastPoints ?? kastRounds,
    tradedDeaths: roundAgg.tradedDeaths || 0,
    failedTradeDeaths: roundAgg.failedTradeDeaths || 0,
    tradeKills: roundAgg.tradeKills || 0,
    tradeDenials: roundAgg.tradeDenials || 0,
    savedLossRounds: roundAgg.savedLossRounds || 0,
    survivedWinRounds: roundAgg.survivedWinRounds || 0,
    multiKillPoints: roundAgg.multiKillPoints || 0,
    firstKills: roundAgg.firstKills,
    firstDeaths: roundAgg.firstDeaths,
    oneKills: roundAgg.oneKills || 0,
    twoKills: roundAgg.twoKills || 0,
    threeKills: roundAgg.threeKills || 0,
    fourKills: roundAgg.fourKills || 0,
    fiveKills: roundAgg.fiveKills || 0,
    headshots: roundAgg.headshots,
    bodyshots: roundAgg.bodyshots,
    legshots: roundAgg.legshots,
    hs: headshotTotal ? (roundAgg.headshots / headshotTotal) * 100 : 0,
    abilityCasts: player.stats?.abilityCasts || {},
  };
  return applyRaatingFields(output);
}

function aggregateMatchPlayerRoundStats(players, roundResults, metadata) {
  const sideByPuuid = new Map();
  const rosters = { Blue: new Set(), Red: new Set() };
  const stats = new Map();

  for (const player of players) {
    if (player.isObserver || !["Blue", "Red"].includes(player.teamId) || !player.puuid) continue;
    sideByPuuid.set(player.puuid, player.teamId);
    rosters[player.teamId].add(player.puuid);
    stats.set(player.puuid, emptyPlayerRoundStats());
  }

  for (const round of roundResults) {
    const playerStats = round.playerStats || [];
    const armorExtraByPuuid = new Map();
    const ecoBucketByPuuid = new Map();
    const damageByVictim = new Map();
    const damageByReceiver = new Map();
    const participants = new Set();
    const killsCountRound = new Map();
    const assistantSet = new Set();
    const victimsSet = new Set();
    const events = [];
    const eventsSeen = new Set();

    for (const row of playerStats) {
      const puuid = row.puuid;
      if (!puuid || !sideByPuuid.has(puuid)) continue;
      participants.add(puuid);
      armorExtraByPuuid.set(puuid, armorExtraHp(row.economy?.armor));
      ecoBucketByPuuid.set(puuid, RaaRatingCore.ecoBucket(row.economy?.loadoutValue));

      for (const damage of row.damage || []) {
        const receiver = damage.receiver;
        const amount = Number(damage.damage || 0);
        if (!receiver || amount <= 0 || !sideByPuuid.has(receiver)) continue;
        if (receiver === puuid || sideByPuuid.get(receiver) === sideByPuuid.get(puuid)) continue;

        incrementNestedNumber(damageByVictim, receiver, puuid, amount);
        addNestedSetValue(damageByReceiver, receiver, puuid);

        const agg = stats.get(puuid);
        agg.headshots += Number(damage.headshots || 0);
        agg.bodyshots += Number(damage.bodyshots || 0);
        agg.legshots += Number(damage.legshots || 0);
      }

      const kills = row.kills || [];
      killsCountRound.set(puuid, (killsCountRound.get(puuid) || 0) + kills.length);
      for (const kill of kills) {
        const time = kill.timeSinceRoundStartMillis;
        if (time === null || time === undefined) continue;
        const victim = String(kill.victim || "");
        let killer = String(kill.killer || "");
        if (!victim || !sideByPuuid.has(victim)) continue;
        if (!killer || !sideByPuuid.has(killer)) killer = "";
        const key = `${Number(time)}|${killer}|${victim}`;
        if (eventsSeen.has(key)) continue;
        eventsSeen.add(key);
        const assistants = (kill.assistants || []).map(String).filter((item) => sideByPuuid.has(item));
        events.push({ time: Number(time), killer, victim, assistants });
        victimsSet.add(victim);
        assistants.forEach((assistant) => assistantSet.add(assistant));
      }
    }

    for (const puuid of participants) {
      const agg = stats.get(puuid);
      agg.rounds += 1;
      if (round.winningTeam === sideByPuuid.get(puuid)) agg.roundWins += 1;
      else if (["Blue", "Red"].includes(round.winningTeam)) agg.roundLosses += 1;
    }

    events.sort((a, b) => a.time - b.time);
    for (const event of events) {
      event.ecoMultiplier = RaaRatingCore.ecoMultiplier(
        metadata.raatingContext?.ecoModel,
        ecoBucketByPuuid.get(event.killer),
        ecoBucketByPuuid.get(event.victim),
      );
    }
    applyFirstDuelStats(events, stats, sideByPuuid);
    applyEffectiveDamage(damageByVictim, armorExtraByPuuid, events, stats, ecoBucketByPuuid, metadata.raatingContext?.ecoModel);
    applyEcoKillDeathStats(events, stats);
    applyRoundSwingStats(events, participants, round, stats, sideByPuuid, rosters, metadata);
    applyKastStats(events, participants, killsCountRound, assistantSet, victimsSet, damageByReceiver, stats, sideByPuuid, round.winningTeam);
    applyMultiKillStats(participants, killsCountRound, stats);
  }

  return stats;
}

function emptyPlayerRoundStats() {
  return {
    rounds: 0,
    roundWins: 0,
    roundLosses: 0,
    damage: 0,
    eDamageTotal: 0,
    eKillPoints: 0,
    eDeathPoints: 0,
    eKastPoints: 0,
    headshots: 0,
    bodyshots: 0,
    legshots: 0,
    firstKills: 0,
    firstDeaths: 0,
    kastRounds: 0,
    kastLegacyRounds: 0,
    impactTotal: 0,
    impactTotalLegacy: 0,
    adjustedRoundSwingTotalPp: 0,
    tradedDeaths: 0,
    failedTradeDeaths: 0,
    tradeKills: 0,
    tradeDenials: 0,
    savedLossRounds: 0,
    survivedWinRounds: 0,
    multiKillPoints: 0,
    oneKills: 0,
    twoKills: 0,
    threeKills: 0,
    fourKills: 0,
    fiveKills: 0,
  };
}

function armorExtraHp(armorId) {
  const key = String(armorId || "").trim().toUpperCase();
  if (Object.hasOwn(ARMOR_EXTRA_HP, key)) return ARMOR_EXTRA_HP[key];
  return key ? 50 : 0;
}

function incrementNestedNumber(map, key, nestedKey, amount) {
  if (!map.has(key)) map.set(key, new Map());
  const nested = map.get(key);
  nested.set(nestedKey, (nested.get(nestedKey) || 0) + amount);
}

function addNestedSetValue(map, key, value) {
  if (!map.has(key)) map.set(key, new Set());
  map.get(key).add(value);
}

function applyFirstDuelStats(events, stats, sideByPuuid) {
  if (!events.length) return;
  const firstTime = events[0].time;
  for (const event of events) {
    if (event.time !== firstTime) break;
    if (event.killer && stats.has(event.killer)) stats.get(event.killer).firstKills += 1;
    if (event.victim && sideByPuuid.has(event.victim) && stats.has(event.victim)) stats.get(event.victim).firstDeaths += 1;
  }
}

function applyEffectiveDamage(damageByVictim, armorExtraByPuuid, events, stats, ecoBucketByPuuid, ecoModel) {
  const killerOfVictim = new Map();
  const killerTime = new Map();
  for (const event of events) {
    if (!event.victim || !event.killer) continue;
    const previous = killerTime.get(event.victim);
    if (previous === undefined || event.time > previous) {
      killerTime.set(event.victim, event.time);
      killerOfVictim.set(event.victim, event.killer);
    }
  }

  for (const [victim, byAttacker] of damageByVictim.entries()) {
    const rawTotal = [...byAttacker.values()].reduce((sum, value) => sum + value, 0);
    if (rawTotal <= 0) continue;
    const cap = 100 + (armorExtraByPuuid.get(victim) ?? 50);
    let over = rawTotal - cap;
    const effective = new Map(byAttacker);

    if (over > 0) {
      let last = killerOfVictim.get(victim);
      if (!last || !effective.has(last)) {
        last = [...effective.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
      }
      if (last) {
        const take = Math.min(over, effective.get(last) || 0);
        effective.set(last, Math.max(0, (effective.get(last) || 0) - take));
        over -= take;
      }
      if (over > 0) {
        for (const [attacker, value] of [...effective.entries()].sort((a, b) => b[1] - a[1])) {
          if (attacker === last || over <= 0) continue;
          const take = Math.min(over, value);
          effective.set(attacker, Math.max(0, value - take));
          over -= take;
        }
      }
    }

    for (const [attacker, damage] of effective.entries()) {
      if (damage > 0 && stats.has(attacker)) {
        const ecoMultiplier = RaaRatingCore.ecoMultiplier(ecoModel, ecoBucketByPuuid?.get(attacker), ecoBucketByPuuid?.get(victim));
        const adjustedDamage = damage * RaaRatingCore.reducedEcoMultiplier(ecoMultiplier, 0.5);
        stats.get(attacker).damage += damage;
        stats.get(attacker).eDamageTotal += adjustedDamage;
      }
    }
  }
}

function applyEcoKillDeathStats(events, stats) {
  for (const event of events) {
    const multiplier = RaaRatingCore.finiteNumber(event.ecoMultiplier, 1);
    if (event.killer && stats.has(event.killer)) stats.get(event.killer).eKillPoints += multiplier;
    if (event.victim && stats.has(event.victim)) stats.get(event.victim).eDeathPoints += multiplier;
  }
}

function applyRoundSwingStats(events, participants, round, stats, sideByPuuid, rosters, metadata) {
  const alive = {
    Blue: new Set(rosters.Blue),
    Red: new Set(rosters.Red),
  };
  const roundSwing = new Map([...participants].map((puuid) => [puuid, 0]));
  const legacySwing = new Map([...participants].map((puuid) => [puuid, 0]));
  const addSwing = (map, puuid, amount) => {
    if (!puuid || !map.has(puuid)) return;
    map.set(puuid, map.get(puuid) + amount);
  };

  for (const event of events) {
    const victim = event.victim;
    if (!victim || !sideByPuuid.has(victim)) continue;

    const victimSide = alive.Blue.has(victim) ? "Blue" : alive.Red.has(victim) ? "Red" : "";
    if (!victimSide) continue;
    const enemySide = victimSide === "Blue" ? "Red" : "Blue";
    const deathSwing = deltaDeathPp(metadata, alive[victimSide].size, alive[enemySide].size);
    addSwing(roundSwing, victim, deathSwing);
    addSwing(legacySwing, victim, deathSwing);

    const killer = event.killer;
    if (killer && sideByPuuid.has(killer) && stats.has(killer)) {
      const killerSide = sideByPuuid.get(killer);
      const killerEnemySide = killerSide === "Blue" ? "Red" : "Blue";
      const killSwing = deltaKillPp(metadata, alive[killerSide].size, alive[killerEnemySide].size);
      addSwing(roundSwing, killer, killSwing);
      addSwing(legacySwing, killer, killSwing);
    }

    alive[victimSide].delete(victim);
  }

  const winningTeam = ["Blue", "Red"].includes(round.winningTeam) ? round.winningTeam : "";
  if (winningTeam) {
    const losingTeam = winningTeam === "Blue" ? "Red" : "Blue";
    const winnerAlive = alive[winningTeam];
    const loserAlive = alive[losingTeam];
    const winnerParticipants = [...participants].filter((puuid) => sideByPuuid.get(puuid) === winningTeam);
    const loserParticipants = [...participants].filter((puuid) => sideByPuuid.get(puuid) === losingTeam);
    const winnerCreditTargets = (winnerAlive.size ? [...winnerAlive] : winnerParticipants).filter((puuid) => roundSwing.has(puuid));
    const loserDebitTargets = (loserAlive.size ? [...loserAlive] : loserParticipants).filter((puuid) => roundSwing.has(puuid));
    const residual = Math.max(0, (1 - stateWinRate(metadata, winnerAlive.size, loserAlive.size)) * 100);
    if (residual > 0 && winnerCreditTargets.length && loserDebitTargets.length) {
      const credit = residual / winnerCreditTargets.length;
      const debit = residual / loserDebitTargets.length;
      winnerCreditTargets.forEach((puuid) => addSwing(roundSwing, puuid, credit));
      loserDebitTargets.forEach((puuid) => addSwing(roundSwing, puuid, -debit));
    }
  }

  const total = [...roundSwing.values()].reduce((sum, value) => sum + value, 0);
  if (Math.abs(total) > 1e-6 && roundSwing.size) {
    const correction = total / roundSwing.size;
    for (const puuid of roundSwing.keys()) addSwing(roundSwing, puuid, -correction);
  }

  for (const [puuid, value] of roundSwing.entries()) {
    if (!stats.has(puuid)) continue;
    stats.get(puuid).impactTotal += value;
    stats.get(puuid).adjustedRoundSwingTotalPp += value;
  }
  for (const [puuid, value] of legacySwing.entries()) {
    if (stats.has(puuid)) stats.get(puuid).impactTotalLegacy += value;
  }
}

function applyKastStats(events, participants, killsCountRound, assistantSet, victimsSet, damageByReceiver, stats, sideByPuuid, winningTeam) {
  const deathsByVictim = new Map();
  const deathTimeByVictim = new Map();
  const tradeKillEvents = new Set();
  const tradedDeaths = new Set();
  const failedTradeDeaths = new Set();
  const kastEcoMultipliers = new Map();
  const addKastMultiplier = (puuid, multiplier) => {
    if (!puuid || !stats.has(puuid)) return;
    if (!kastEcoMultipliers.has(puuid)) kastEcoMultipliers.set(puuid, []);
    kastEcoMultipliers.get(puuid).push(RaaRatingCore.reducedEcoMultiplier(multiplier, 0.35));
  };

  for (const event of events) {
    if (!event.victim) continue;
    if (!deathsByVictim.has(event.victim)) deathsByVictim.set(event.victim, []);
    deathsByVictim.get(event.victim).push(event);
    const current = deathTimeByVictim.get(event.victim);
    if (current === undefined || event.time < current) deathTimeByVictim.set(event.victim, event.time);
    if (event.killer) addKastMultiplier(event.killer, event.ecoMultiplier);
    for (const assistant of event.assistants || []) addKastMultiplier(assistant, event.ecoMultiplier);
  }

  for (const [victim, deaths] of deathsByVictim.entries()) {
    const victimSide = sideByPuuid.get(victim);
    for (const death of deaths) {
      const involved = new Set();
      if (death.killer) involved.add(death.killer);
      for (const assistant of death.assistants || []) involved.add(assistant);
      (damageByReceiver.get(victim) || new Set()).forEach((attacker) => involved.add(attacker));

      const validInvolved = [...involved].filter((item) => sideByPuuid.has(item) && sideByPuuid.get(item) !== victimSide);
      if (!validInvolved.length) continue;

      const tradeLimit = death.time + TRADE_WINDOW_MS;
      let tradedBy = "";
      for (const event of events) {
        if (event.time <= death.time) continue;
        if (event.time > tradeLimit) break;
        if (sideByPuuid.get(event.killer) === victimSide && validInvolved.includes(event.victim)) {
          tradedBy = event.killer;
          tradeKillEvents.add(event);
          break;
        }
      }

      if (tradedBy) {
        tradedDeaths.add(victim);
        addKastMultiplier(victim, death.ecoMultiplier);
        if (stats.has(victim)) stats.get(victim).tradedDeaths += 1;
        if (stats.has(tradedBy)) stats.get(tradedBy).tradeKills += 1;
      } else if (teamHasAliveMateAfter(victim, victimSide, death.time, participants, sideByPuuid, deathTimeByVictim)) {
        failedTradeDeaths.add(victim);
        if (stats.has(victim)) stats.get(victim).failedTradeDeaths += 1;
      }
    }
  }

  for (const event of events) {
    if (!event.killer || !event.victim || !stats.has(event.killer)) continue;
    const killerSide = sideByPuuid.get(event.killer);
    const victimSide = sideByPuuid.get(event.victim);
    if (!killerSide || !victimSide || killerSide === victimSide) continue;
    const tradeLimit = event.time + TRADE_WINDOW_MS;
    const victimTeamCanTrade = [...participants].some((puuid) => {
      if (puuid === event.victim || sideByPuuid.get(puuid) !== victimSide) return false;
      const deathTime = deathTimeByVictim.get(puuid);
      return deathTime === undefined || deathTime > event.time;
    });
    if (!victimTeamCanTrade) continue;
    const killerWasTraded = events.some((candidate) => {
      if (candidate.time <= event.time || candidate.time > tradeLimit) return false;
      return candidate.victim === event.killer && sideByPuuid.get(candidate.killer) === victimSide;
    });
    if (!killerWasTraded && !tradeKillEvents.has(event)) stats.get(event.killer).tradeDenials += 1;
  }

  for (const puuid of participants) {
    const side = sideByPuuid.get(puuid);
    const killCond = (killsCountRound.get(puuid) || 0) > 0;
    const assistCond = assistantSet.has(puuid);
    const survivedCond = !victimsSet.has(puuid);
    const survivedWinCond = survivedCond && side === winningTeam;
    const savedLossCond = survivedCond && ["Blue", "Red"].includes(winningTeam) && side !== winningTeam;
    const tradedCond = tradedDeaths.has(puuid);
    if (survivedWinCond) {
      stats.get(puuid).survivedWinRounds += 1;
      addKastMultiplier(puuid, 1);
    }
    if (savedLossCond) stats.get(puuid).savedLossRounds += 1;
    if (killCond || assistCond || survivedCond || tradedCond) stats.get(puuid).kastLegacyRounds += 1;
    if (killCond || assistCond || survivedWinCond || tradedCond) {
      stats.get(puuid).kastRounds += 1;
      const multipliers = kastEcoMultipliers.get(puuid) || [];
      stats.get(puuid).eKastPoints += multipliers.length ? Math.max(...multipliers) : 1;
    }
  }
}

function teamHasAliveMateAfter(victim, victimSide, time, participants, sideByPuuid, deathTimeByVictim) {
  return [...participants].some((puuid) => {
    if (puuid === victim || sideByPuuid.get(puuid) !== victimSide) return false;
    const deathTime = deathTimeByVictim.get(puuid);
    return deathTime === undefined || deathTime > time;
  });
}

function applyMultiKillStats(participants, killsCountRound, stats) {
  for (const puuid of participants) {
    const kills = killsCountRound.get(puuid) || 0;
    if (kills === 1) stats.get(puuid).oneKills += 1;
    if (kills === 2) stats.get(puuid).twoKills += 1;
    if (kills === 3) stats.get(puuid).threeKills += 1;
    if (kills === 4) stats.get(puuid).fourKills += 1;
    if (kills >= 5) stats.get(puuid).fiveKills += 1;
    stats.get(puuid).multiKillPoints += RaaRatingCore.multiKillPointsForKills(kills);
  }
}

function stateWinRate(metadata, allies, enemies) {
  if (allies <= 0) return 0;
  if (enemies <= 0) return 1;
  return Number(metadata.stateWinratesByKey?.get(`${allies}v${enemies}`) ?? 0.5);
}

function deltaKillPp(metadata, allies, enemies) {
  return (stateWinRate(metadata, allies, enemies - 1) - stateWinRate(metadata, allies, enemies)) * 100;
}

function deltaDeathPp(metadata, allies, enemies) {
  return (stateWinRate(metadata, allies - 1, enemies) - stateWinRate(metadata, allies, enemies)) * 100;
}

function applyRaatingFields(row) {
  const applied = RaaRatingCore.applyRatingFields(row);
  return applyRaatingAliases(applied);
}

function applyRaatingAliases(row) {
  row.opening_kills = Number(row.firstKills ?? row.opening_kills ?? 0);
  row.opening_deaths = Number(row.firstDeaths ?? row.opening_deaths ?? 0);
  row.fk_fd_diff = row.opening_kills - row.opening_deaths;
  row.multi_kill_rounds = Number(row.twoKills || 0) + Number(row.threeKills || 0) + Number(row.fourKills || 0) + Number(row.fiveKills || 0);
  return row;
}

function calculateMatchTeamStats(roundResults, teamA, teamB, playerTeamByPuuid) {
  const teamByColor = {
    [teamA.color]: teamA.id,
    [teamB.color]: teamB.id,
  };
  const rows = {
    [teamA.id]: emptyTeamRoundStats(),
    [teamB.id]: emptyTeamRoundStats(),
  };

  for (const round of roundResults) {
    const winnerId = teamByColor[round.winningTeam];
    const loserColor = round.winningTeam === "Red" ? "Blue" : "Red";
    const loserId = teamByColor[loserColor];
    const winnerRole = round.winningTeamRole;
    const loserRole = winnerRole === "Attacker" ? "Defender" : "Attacker";
    if (winnerId) {
      rows[winnerId].roundWins += 1;
      rows[winnerId][winnerRole === "Attacker" ? "attackWins" : "defenseWins"] += 1;
      rows[winnerId][winnerRole === "Attacker" ? "attackRounds" : "defenseRounds"] += 1;
    }
    if (loserId) {
      rows[loserId][loserRole === "Attacker" ? "attackRounds" : "defenseRounds"] += 1;
    }
    if (round.roundNum === 0 || round.roundNum === 12) {
      if (winnerId) rows[winnerId].pistolWins += 1;
      if (teamA.id) rows[teamA.id].pistolRounds += 1;
      if (teamB.id) rows[teamB.id].pistolRounds += 1;
    }

    // Quem atacou sai do lado do vencedor: o arquivo nao diz o lado do perdedor.
    const atacante = winnerRole === "Attacker" ? winnerId : loserId;
    const defensor = winnerRole === "Attacker" ? loserId : winnerId;
    if (atacante && (round.roundNum === 0 || round.roundNum === 12)) {
      rows[atacante].pistolAttackRounds += 1;
      if (winnerRole === "Attacker") rows[atacante].pistolAttackWins += 1;
    }
    if (round.bombPlanter || Number(round.plantRoundTime) > 0) {
      if (atacante) {
        rows[atacante].plants += 1;
        if (winnerRole === "Attacker") rows[atacante].plantWins += 1;
        const site = `plant${String(round.plantSite || "").toUpperCase()}`;
        if (site in rows[atacante]) rows[atacante][site] += 1;
      }
      if (defensor) {
        rows[defensor].plantsAgainst += 1;
        if (winnerRole !== "Attacker") rows[defensor].retakes += 1;
      }
    }

    const kills = (round.playerStats || []).flatMap((item) => item.kills || []);
    if (kills.length) {
      const firstKill = kills.slice().sort((a, b) => a.timeSinceRoundStartMillis - b.timeSinceRoundStartMillis)[0];
      const killerTeamId = playerTeamByPuuid.get(firstKill.killer);
      if (killerTeamId) rows[killerTeamId].firstKills += 1;
    }
  }

  return rows;
}

function emptyTeamRoundStats() {
  return {
    roundWins: 0,
    attackWins: 0,
    attackRounds: 0,
    defenseWins: 0,
    defenseRounds: 0,
    pistolWins: 0,
    pistolRounds: 0,
    firstKills: 0,
    // Retake e round com bomba plantada que a defesa venceu.
    plants: 0,
    plantWins: 0,
    plantsAgainst: 0,
    retakes: 0,
    plantA: 0,
    plantB: 0,
    plantC: 0,
    pistolAttackWins: 0,
    pistolAttackRounds: 0,
  };
}

function aggregateTeams(matches, metadata) {
  const byId = new Map();
  for (const match of matches) {
    const sides = [
      { team: match.teamA, opponent: match.teamB },
      { team: match.teamB, opponent: match.teamA },
    ];
    for (const side of sides) {
      const row = ensureTeam(byId, side.team);
      const won = match.winnerId === row.id;
      row.matches += 1;
      row.wins += won ? 1 : 0;
      row.losses += won ? 0 : 1;
      row.roundsWon += side.team.score;
      row.roundsLost += side.opponent.score;
      row.roundDiff += side.team.score - side.opponent.score;
      row.maps.set(match.mapName, updateCount(row.maps.get(match.mapName), won));
      row.opponents.set(side.opponent.id, updateCount(row.opponents.get(side.opponent.id), won));

      const observedPlayers = match.players.filter((player) => player.teamColor === side.team.color);
      for (const player of observedPlayers) {
        if (!row.players.has(player.id)) row.players.set(player.id, player.handle);
      }

      const roundStats = match.teamStats[row.id] || emptyTeamRoundStats();
      row.attackWins += roundStats.attackWins;
      row.attackRounds += roundStats.attackRounds;
      row.defenseWins += roundStats.defenseWins;
      row.defenseRounds += roundStats.defenseRounds;
      row.pistolWins += roundStats.pistolWins;
      row.pistolRounds += roundStats.pistolRounds;
      row.firstKills += roundStats.firstKills;
    }
  }

  for (const registeredTeam of metadata.teams) {
    ensureTeam(byId, {
      id: registeredTeam.id,
      name: registeredTeam.displayName,
      tag: registeredTeam.tag,
      shortTag: teamTag(registeredTeam.id),
      registered: true,
    });
  }

  return [...byId.values()]
    .map((team) => {
      team.winRate = pctValue(team.wins, team.matches);
      team.points = team.wins * 3 + team.roundDiff / 10;
      team.mapStats = [...team.maps.entries()]
        .map(([name, row]) => ({ name, wins: row.wins, matches: row.matches, winRate: pctValue(row.wins, row.matches) }))
        .sort((a, b) => b.winRate - a.winRate || b.matches - a.matches);
      team.opponentStats = [...team.opponents.entries()]
        .map(([id, row]) => ({ id, wins: row.wins, matches: row.matches, losses: row.matches - row.wins, winRate: pctValue(row.wins, row.matches) }))
        .sort((a, b) => b.matches - a.matches || b.winRate - a.winRate);
      team.lineup = [...team.players.entries()].map(([id, handle]) => ({ id, handle }));
      team.attackWinRate = pctValue(team.attackWins, team.attackRounds);
      team.defenseWinRate = pctValue(team.defenseWins, team.defenseRounds);
      team.pistolWinRate = pctValue(team.pistolWins, team.pistolRounds);
      return team;
    })
    .sort((a, b) => b.points - a.points || b.winRate - a.winRate || b.roundDiff - a.roundDiff);
}

function ensureTeam(map, side) {
  if (!map.has(side.id)) {
    map.set(side.id, {
      id: side.id,
      name: side.name,
      tag: side.tag,
      sourceTag: side.tag || side.id,
      shortTag: side.shortTag || teamTag(side.id),
      registered: Boolean(side.registered),
      colors: teamColors(side.id),
      matches: 0,
      wins: 0,
      losses: 0,
      roundsWon: 0,
      roundsLost: 0,
      roundDiff: 0,
      points: 0,
      players: new Map(),
      maps: new Map(),
      opponents: new Map(),
      attackWins: 0,
      attackRounds: 0,
      defenseWins: 0,
      defenseRounds: 0,
      pistolWins: 0,
      pistolRounds: 0,
      firstKills: 0,
    });
  }
  return map.get(side.id);
}

function updateCount(row = { wins: 0, matches: 0 }, won) {
  return {
    wins: row.wins + (won ? 1 : 0),
    matches: row.matches + 1,
  };
}

const RAATING_AGGREGATE_FIELDS = [
  "roundWins",
  "roundLosses",
  "eKillPoints",
  "eDeathPoints",
  "eDamageTotal",
  "eKastPoints",
  "kastLegacyRounds",
  "impactTotalLegacy",
  "adjustedRoundSwingTotalPp",
  "tradedDeaths",
  "failedTradeDeaths",
  "tradeKills",
  "tradeDenials",
  "savedLossRounds",
  "survivedWinRounds",
  "multiKillPoints",
  "oneKills",
  "twoKills",
  "threeKills",
  "fourKills",
  "fiveKills",
];

function emptyRaatingAggregateFields() {
  return Object.fromEntries(RAATING_AGGREGATE_FIELDS.map((field) => [field, 0]));
}

function addRaatingAggregateFields(row, player) {
  for (const field of RAATING_AGGREGATE_FIELDS) {
    row[field] = Number(row[field] || 0) + Number(player?.[field] || 0);
  }
}

function emptyPlayerStatTotals() {
  return {
    matches: 0,
    rounds: 0,
    kills: 0,
    deaths: 0,
    assists: 0,
    score: 0,
    damage: 0,
    firstKills: 0,
    firstDeaths: 0,
    kastRounds: 0,
    impactTotal: 0,
    ...emptyRaatingAggregateFields(),
    headshots: 0,
    bodyshots: 0,
    legshots: 0,
  };
}

function addPlayerMatchTotals(row, player) {
  row.matches += 1;
  row.rounds += player.rounds;
  row.kills += player.kills;
  row.deaths += player.deaths;
  row.assists += player.assists;
  row.score += player.score;
  row.damage += player.damage;
  row.firstKills += player.firstKills;
  row.firstDeaths += player.firstDeaths;
  row.kastRounds += player.kastRounds;
  row.impactTotal += player.impactTotal;
  addRaatingAggregateFields(row, player);
  row.headshots += player.headshots;
  row.bodyshots += player.bodyshots;
  row.legshots += player.legshots;
}

function finalizePlayerStatRow(row) {
  row.acs = row.rounds ? row.score / row.rounds : 0;
  row.adr = row.rounds ? row.damage / row.rounds : 0;
  row.kpr = row.rounds ? row.kills / row.rounds : 0;
  row.dpr = row.rounds ? row.deaths / row.rounds : 0;
  row.apr = row.rounds ? row.assists / row.rounds : 0;
  row.kd = row.deaths ? row.kills / row.deaths : row.kills;
  row.kastFrac = row.rounds ? row.kastRounds / row.rounds : 0;
  row.kast = row.kastFrac * 100;
  row.impactRound = row.rounds ? row.impactTotal / row.rounds : 0;
  row.impactRoundLegacy = row.rounds ? Number(row.impactTotalLegacy || 0) / row.rounds : 0;
  row.kastLegacyFrac = row.rounds ? Number(row.kastLegacyRounds || 0) / row.rounds : row.kastFrac;
  row.kastLegacy = row.kastLegacyFrac * 100;
  applyRaatingFields(row);
  const shots = row.headshots + row.bodyshots + row.legshots;
  row.hs = shots ? (row.headshots / shots) * 100 : 0;
  return row;
}

// Stats do jogador restritas aos mapas jogados por uma equipe específica
// (perfil da equipe). Sem passagem registrada, retorna uma linha zerada.
function playerStatsForTeam(player, teamId) {
  const stint = (player?.teamStats || []).find((row) => row.teamId === teamId);
  return stint || finalizePlayerStatRow({ teamId, ...emptyPlayerStatTotals() });
}

function aggregatePlayers(matches, teams, metadata) {
  const teamByObservedPlayer = new Map();
  teams.forEach((team) => team.lineup.forEach((player) => teamByObservedPlayer.set(player.id, team.id)));

  const byId = new Map();
  const teamTotalsByRow = new Map();
  for (const match of matches) {
    for (const player of match.players) {
      const teamId = match.teamA.color === player.teamColor ? match.teamA.id : match.teamB.id;
      const row = ensurePlayer(byId, player, teamId);
      addPlayerMatchTotals(row, player);
      let rowTeamTotals = teamTotalsByRow.get(row);
      if (!rowTeamTotals) teamTotalsByRow.set(row, (rowTeamTotals = new Map()));
      let stint = rowTeamTotals.get(teamId);
      if (!stint) rowTeamTotals.set(teamId, (stint = emptyPlayerStatTotals()));
      addPlayerMatchTotals(stint, player);
      row.teams.set(teamId, (row.teams.get(teamId) || 0) + 1);
      row.agents.set(player.agentSlug || player.agent, updateAgentBucket(row.agents.get(player.agentSlug || player.agent), player));
      row.maps.set(match.mapName, updateStatBucket(row.maps.get(match.mapName), player.rating, player.acs, player.rounds));
      row.events.set(match.eventId, updateStatBucket(row.events.get(match.eventId), player.rating, player.acs, player.rounds));
      row.recent.push({ matchId: match.id, rating: player.rating, acs: player.acs, kills: player.kills, deaths: player.deaths, assists: player.assists });
    }
  }

  for (const registeredPlayer of metadata.players) {
    const existingPlayer = findAggregatedPlayerForMetadata(byId, registeredPlayer);
    if (existingPlayer) {
      mergeRegisteredPlayerMetadata(existingPlayer, registeredPlayer);
      continue;
    }
    ensurePlayer(byId, playerFromMetadata(registeredPlayer), registeredPlayer.currentTeam);
  }

  const players = [...byId.values()]
    .map((player) => {
      const observedTeamId = [...player.teams.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] || teamByObservedPlayer.get(player.id);
      player.observedTeamId = observedTeamId || "";
      player.teamId = player.currentTeam || observedTeamId || "";
      // O handle saiu da partida mais recente, com o nome que a conta tinha
      // naquele dia. Se a Riot já disse como essa MESMA conta se chama hoje
      // (metadata.currentRiotIds, de ferramentas/riot/AtualizaNicks.py), o
      // perfil mostra o nome de hoje; as partidas seguem com o nome da época.
      // O `nick` (título e endereço do perfil) não muda.
      const currentRiotId = currentRiotIdForPlayer(player, metadata);
      if (currentRiotId) player.handle = currentRiotId;
      finalizePlayerStatRow(player);
      player.teamStats = [...(teamTotalsByRow.get(player)?.entries() || [])]
        .map(([teamId, stint]) => finalizePlayerStatRow({ teamId, ...stint }))
        .sort((a, b) => b.matches - a.matches || b.rounds - a.rounds);
      player.agentStats = [...player.agents.values()]
        .map((agent) => ({ ...agent, rate: pctValue(agent.rounds, player.rounds) }))
        .sort((a, b) => b.rounds - a.rounds);
      player.mapStats = [...player.maps.entries()]
        .map(([name, bucket]) => ({ name, rating: bucket.rounds ? bucket.rating / bucket.rounds : bucket.rating / bucket.matches, acs: bucket.rounds ? bucket.acs / bucket.rounds : bucket.acs / bucket.matches, matches: bucket.matches }))
        .sort((a, b) => b.rating - a.rating);
      player.eventStats = [...player.events.entries()]
        .map(([eventId, bucket]) => ({ eventId, rating: bucket.rounds ? bucket.rating / bucket.rounds : bucket.rating / bucket.matches, acs: bucket.rounds ? bucket.acs / bucket.rounds : bucket.acs / bucket.matches, matches: bucket.matches }))
        .sort((a, b) => b.matches - a.matches);
      player.recent = player.recent.slice(-6).reverse();
      return player;
    })
    .sort((a, b) => Number(b.matches > 0) - Number(a.matches > 0) || Number(officialRatingValue(b) || 0) - Number(officialRatingValue(a) || 0) || b.kills - a.kills || a.nick.localeCompare(b.nick));
  assignPlayerRouteSlugs(players);
  return players;
}

function currentRiotIdForPlayer(player, metadata) {
  const riotIds = metadata?.currentRiotIds;
  if (!riotIds) return "";
  // accounts[0] é a conta da partida mais recente; sem partida, a principal.
  const account = player.accounts?.[0]?.puuid || player.puuid || player.id;
  return riotIds[account] || "";
}

function findAggregatedPlayerForMetadata(playersById, registeredPlayer) {
  if (registeredPlayer.puuid && playersById.has(registeredPlayer.puuid)) return playersById.get(registeredPlayer.puuid);
  const metadataKeys = new Set(playerMetadataLookupKeys(registeredPlayer));
  if (!metadataKeys.size) return null;
  return [...playersById.values()].find((player) => playerLookupKeys(player).some((key) => metadataKeys.has(key))) || null;
}

function mergeRegisteredPlayerMetadata(player, registeredPlayer) {
  player.registered = true;
  player.nick = registeredPlayer.name || player.nick;
  player.currentTeam = registeredPlayer.currentTeam || player.currentTeam || "";
  player.teamHistory = uniqueValues([...(player.teamHistory || []), ...(registeredPlayer.teamHistory || [])]);
  player.nickHistory = uniqueValues([...(player.nickHistory || []), ...(registeredPlayer.nickHistory || [])]);
  player.photo = player.photo || registeredPlayer.photo || "";
}

function playerLookupKeys(player) {
  return [player?.nick, player?.apiNick, player?.handle, ...(player?.nickHistory || [])]
    .map(normalizeNameKey)
    .filter(Boolean);
}

function uniqueValues(values) {
  return [...new Set(values.filter(Boolean))];
}

function assignPlayerRouteSlugs(players) {
  const used = new Set();
  for (const player of players) {
    const base = playerRouteSlugBase(player);
    let routeSlug = base;
    let suffix = 2;
    while (used.has(routeSlug)) {
      routeSlug = `${base}-${suffix}`;
      suffix += 1;
    }
    used.add(routeSlug);
    player.routeSlug = routeSlug;
  }
}

function playerRouteSlugBase(player) {
  return slugify(player?.nick || String(player?.handle || "").split("#")[0] || player?.apiNick || player?.id || "player") || "player";
}

function playerFromMetadata(player) {
  return {
    id: player.puuid || `registered-${slugify(player.name)}`,
    puuid: player.puuid || "",
    nick: player.name,
    apiNick: "",
    tagLine: "",
    handle: player.nickHistory?.[0] || player.name,
    registered: true,
    currentTeam: player.currentTeam || "",
    teamHistory: player.teamHistory || [],
    nickHistory: player.nickHistory || [],
    photo: player.photo || "",
    teamColor: "",
    agentId: "",
    agentSlug: "",
    agent: "",
    agentClass: "",
    agentIcon: "",
    rounds: 0,
    kills: 0,
    deaths: 0,
    assists: 0,
    score: 0,
    damage: 0,
    adr: 0,
    acs: 0,
    kpr: 0,
    dpr: 0,
    apr: 0,
    kd: 0,
    kast: 0,
    kastFrac: 0,
    kastRounds: 0,
    kastLegacy: 0,
    kastLegacyFrac: 0,
    kastLegacyRounds: 0,
    impactTotal: 0,
    impactRound: 0,
    impactTotalLegacy: 0,
    impactRoundLegacy: 0,
    rating: 0,
    raating_1: 0,
    raating_3: 0,
    rating_version: "raa3",
    sample_status: "LOW",
    ...emptyRaatingAggregateFields(),
    firstKills: 0,
    firstDeaths: 0,
    headshots: 0,
    bodyshots: 0,
    legshots: 0,
    hs: 0,
    abilityCasts: {},
  };
}

function ensurePlayer(map, player, teamId) {
  if (!map.has(player.id)) {
    map.set(player.id, {
      id: player.id,
      puuid: player.puuid,
      nick: player.nick,
      apiNick: player.apiNick || "",
      tagLine: player.tagLine,
      handle: player.handle,
      registered: Boolean(player.registered),
      currentTeam: player.currentTeam || "",
      teamHistory: player.teamHistory || [],
      nickHistory: player.nickHistory || [],
      photo: player.photo || "",
      teamId,
      accounts: [],
      teams: new Map(),
      agents: new Map(),
      maps: new Map(),
      events: new Map(),
      recent: [],
      ...emptyPlayerStatTotals(),
    });
  } else if (player.registered) {
    const row = map.get(player.id);
    // Não sobrescreve handle/tagLine: as partidas iteram da mais recente para a
    // mais antiga, então o handle registrado na criação já é o "nick atual".
    row.nick = player.nick || row.nick;
    row.registered = true;
    row.currentTeam = player.currentTeam || row.currentTeam;
    row.teamHistory = player.teamHistory || row.teamHistory;
    row.nickHistory = player.nickHistory || row.nickHistory;
    row.photo = player.photo || row.photo;
  }
  const row = map.get(player.id);
  if (player.puuid && !row.accounts.some((account) => account.puuid === player.puuid)) {
    row.accounts.push({ puuid: player.puuid, handle: player.handle || "" });
  }
  return row;
}

function applyTeamMetadata(teams, players, metadata, teamProfiles) {
  // O elenco da equipe vem da planilha por NOME ("Filiceta"), e o historico de
  // nick guarda o handle inteiro ("filiceta#2107"). Um normaliza para
  // `filiceta` e o outro para `filiceta2107`, entao um jogador que troca de nick
  // perdia o vinculo e o card virava "Perfil em atualizacao" - o site passava a
  // tratar a mesma pessoa como dois perfis. Indexar tambem o nick SEM a tag
  // faz a troca se resolver sozinha ate a planilha ser atualizada.
  //
  // O nome cadastrado tem prioridade sobre handles e historico. JV usa
  // jotave#081, mas JotaVe#2511 e outro jogador no elenco da CEUB.
  const playersByName = new Map();
  const indexa = (chave, player) => {
    const key = normalizeNameKey(chave);
    if (key && !playersByName.has(key)) playersByName.set(key, player);
  };
  for (const player of players) {
    indexa(player.nick, player);
  }
  for (const player of players) {
    indexa(player.handle, player);
    indexa(String(player.handle || "").split("#")[0], player);
  }
  for (const player of players) {
    for (const antigo of player.nickHistory || []) {
      indexa(antigo, player);
      indexa(String(antigo).split("#")[0], player);
    }
  }

  for (const team of teams) {
    const registered = metadata.teamsById.get(team.id);
    const manualProfile = compactProfileOverride(teamProfiles.teams[team.id] || {});
    const metadataProfile = {
      state: registered?.state || "",
      stateName: registered?.stateName || "",
      flag: registered?.stateFlag || "",
      logo: registered?.logo || "",
      org: registered?.org || "",
      orgTag: registered?.orgTag || "",
      stateRegion: registered?.stateRegion || "",
      socials: registered?.socials || {},
    };
    const profile = {
      ...teamProfiles.defaults,
      ...metadataProfile,
      ...manualProfile,
      socials: {
        ...(teamProfiles.defaults.socials || {}),
        ...(metadataProfile.socials || {}),
        ...(manualProfile.socials || {}),
      },
      trophies: manualProfile.trophies || metadataProfile.trophies || teamProfiles.defaults.trophies || [],
      rankingHistory: manualProfile.rankingHistory || metadataProfile.rankingHistory || teamProfiles.defaults.rankingHistory || [],
      lineupHistory: manualProfile.lineupHistory || metadataProfile.lineupHistory || teamProfiles.defaults.lineupHistory || [],
    };
    team.registered = Boolean(registered);
    if (registered?.succeeds) team.succeeds = registered.succeeds;
    team.name = registered?.displayName || team.name;
    if (Array.isArray(registered?.colors) && registered.colors.length === 2) {
      team.colors = registered.colors.slice();
    }
    team.sourceTag = registered?.tag || team.sourceTag || team.id;
    team.shortTag = team.shortTag || teamTag(team.id);
    team.org = registered?.org || "";
    team.orgTag = registered?.orgTag || "";
    team.logo = profile.logo;
    team.profile = profile;
    team.observedLineup = team.lineup;
    team.rosterKnown = Boolean(registered?.lineupRegistered || registered?.lineup?.length);
    team.currentLineup = (registered?.lineup || []).map((slot) => {
      const player = playersByName.get(normalizeNameKey(slot.name));
      return {
        slot: slot.slot,
        name: slot.name,
        playerId: player?.id || "",
        role: slot.role || "",
      };
    });
  }
}

function compactProfileOverride(value) {
  if (Array.isArray(value)) return value.length ? value : undefined;
  if (!value || typeof value !== "object") return isEmptyProfileOverride(value) ? undefined : value;
  const output = {};
  for (const [key, item] of Object.entries(value)) {
    const resolved = compactProfileOverride(item);
    if (resolved !== undefined && resolved !== "") output[key] = resolved;
  }
  return Object.keys(output).length ? output : {};
}

function isEmptyProfileOverride(value) {
  const text = String(value || "").trim();
  return !text || text === "Estado não informado";
}

function updateStatBucket(bucket = { matches: 0, rounds: 0, rating: 0, acs: 0 }, rating, acs, rounds = 1) {
  const weight = Math.max(0, Number(rounds || 0)) || 1;
  return {
    matches: bucket.matches + 1,
    rounds: Number(bucket.rounds || 0) + weight,
    rating: bucket.rating + Number(rating || 0) * weight,
    acs: bucket.acs + Number(acs || 0) * weight,
  };
}

function updateAgentBucket(bucket, player) {
  return {
    slug: player.agentSlug || player.agent,
    name: player.agent,
    icon: player.agentIcon || "",
    role: player.agentClass || "",
    picks: (bucket?.picks || 0) + 1,
    rounds: (bucket?.rounds || 0) + player.rounds,
  };
}

function aggregateMaps(matches, teams) {
  const byName = new Map();
  for (const match of matches) {
    if (!byName.has(match.mapName)) {
      byName.set(match.mapName, {
        id: match.mapId,
        name: match.mapName,
        icon: match.mapIcon || "",
        apiMapId: match.apiMapId || "",
        matches: 0,
        rounds: 0,
        teams: new Map(),
        agents: new Map(),
      });
    }
    const row = byName.get(match.mapName);
    row.matches += 1;
    row.rounds += match.rounds;
    for (const side of [match.teamA, match.teamB]) {
      row.teams.set(side.id, updateCount(row.teams.get(side.id), match.winnerId === side.id));
    }
    for (const player of match.players) {
      row.agents.set(player.agentSlug || player.agent, updateAgentBucket(row.agents.get(player.agentSlug || player.agent), player));
    }
  }

  return [...byName.values()]
    .map((map) => {
      map.teamStats = [...map.teams.entries()]
        .map(([teamId, row]) => ({ teamId, wins: row.wins, matches: row.matches, winRate: pctValue(row.wins, row.matches) }))
        .sort((a, b) => b.winRate - a.winRate || b.matches - a.matches);
      map.agentStats = [...map.agents.values()]
        .map((agent) => ({ ...agent, rate: pctValue(agent.picks, map.matches * 2) }))
        .sort((a, b) => b.picks - a.picks || b.rounds - a.rounds);
      map.colors = mapColors(map.name);
      return map;
    })
    .sort((a, b) => b.matches - a.matches);
}

function aggregateWeapons(matches) {
  const byId = new Map();
  for (const match of matches) {
    const playersByPuuid = new Map(match.players.map((player) => [player.puuid, player]));
    for (const round of match.roundResults || []) {
      for (const row of round.playerStats || []) {
        for (const kill of row.kills || []) {
          const damage = kill.finishingDamage || {};
          const weaponId = String(damage.damageItem || "").toLowerCase();
          if (damage.damageType !== "Weapon" || !weaponId) continue;
          const weapon = ensureWeaponBucket(byId, weaponId);
          const killer = playersByPuuid.get(String(kill.killer || ""));
          weapon.kills += 1;
          weapon.secondaryKills += damage.isSecondaryFireMode ? 1 : 0;
          weapon.matchIds.add(match.id);
          weapon.maps.add(match.mapName);
          if (killer) {
            const playerBucket = weapon.players.get(killer.id) || { id: killer.id, name: killer.nick, kills: 0 };
            playerBucket.kills += 1;
            weapon.players.set(killer.id, playerBucket);
          }
        }
      }
    }
  }

  const totalKills = [...byId.values()].reduce((sum, weapon) => sum + weapon.kills, 0);
  return [...byId.values()]
    .map((weapon) => {
      const topPlayer = [...weapon.players.values()].sort((a, b) => b.kills - a.kills || a.name.localeCompare(b.name))[0] || null;
      return {
        id: weapon.id,
        name: weapon.name,
        kills: weapon.kills,
        killShare: pctValue(weapon.kills, totalKills),
        matches: weapon.matchIds.size,
        maps: weapon.maps.size,
        secondaryKills: weapon.secondaryKills,
        topPlayer,
      };
    })
    .sort((a, b) => b.kills - a.kills || a.name.localeCompare(b.name));
}

function ensureWeaponBucket(map, id) {
  if (!map.has(id)) {
    map.set(id, {
      id,
      name: weaponName(id),
      kills: 0,
      secondaryKills: 0,
      matchIds: new Set(),
      maps: new Set(),
      players: new Map(),
    });
  }
  return map.get(id);
}

function weaponName(id) {
  return WEAPON_NAMES[String(id || "").toLowerCase()] || `Arma ${String(id || "").slice(0, 8)}`;
}

function aggregateEvents(events, matches, matchSeries, loadedFiles, duplicateFiles, failedFiles) {
  return events.map((event) => {
    const override = TOURNAMENT_OVERRIDES[event.id] || {};
    const rawEvent = { ...event, ...override };
    const eventMatches = matches.filter((match) => match.eventId === event.id);
    const eventSeries = matchSeries.filter((series) => series.eventId === event.id);
    const teams = new Set(eventMatches.flatMap((match) => [match.teamA.id, match.teamB.id]));
    const players = new Set(eventMatches.flatMap((match) => match.players.map((player) => player.id)));
    const dates = eventMatches.map((match) => match.startedAt).filter(Boolean).sort((a, b) => a - b);
    const explicitStart = parseEventTimestamp(rawEvent.startsAt ?? rawEvent.startAt ?? rawEvent.startTime ?? rawEvent.startDate);
    const explicitEnd = parseEventTimestamp(rawEvent.endsAt ?? rawEvent.endAt ?? rawEvent.endTime ?? rawEvent.endDate);
    const start = explicitStart || dates[0] || null;
    const end = explicitEnd || dates[dates.length - 1] || null;
    const colors = eventColorPair(rawEvent);
    return {
      ...rawEvent,
      matches: eventSeries.length,
      mapGames: eventMatches.length,
      teams: override.teams ? [...override.teams] : [...teams],
      players: [...players],
      maps: override.mapPool ? [...override.mapPool] : [...new Set(eventMatches.map((match) => match.mapName))],
      start,
      end,
      logo: rawEvent.logo || rawEvent.logoPath || rawEvent.icon || "",
      mark: rawEvent.mark || eventAcronym(rawEvent.name || rawEvent.id),
      colors,
      sourceFiles: loadedFiles.filter((file) => file.eventId === event.id).length,
      duplicateFiles: duplicateFiles.length,
      failedFiles: failedFiles.length,
      status: rawEvent.status || eventStatus(start, end),
    };
  });
}

function parseEventTimestamp(value) {
  if (!value) return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  const parsed = Date.parse(value);
  return Number.isNaN(parsed) ? null : parsed;
}

function eventStatus(start, end) {
  const now = Date.now();
  if (end && now > end) return "Finalizado";
  if (start && now < start) return "Em andamento";
  return "Em andamento";
}

function renderLoading() {
  updateDocumentTitle();
  // O database.json tem ~13 MB comprimidos. Numa conexao lenta a espera e longa
  // o bastante para valer dizer o que esta acontecendo, em vez de "Carregando".
  const message = state.error
    ? `
      <div class="boot-state boot-error" role="alert">
        <strong>Não foi possível carregar os dados das partidas.</strong>
        <p>${escapeHtml(state.error.message || "A conexão falhou no meio do download.")}</p>
        <button type="button" class="boot-retry" onclick="window.location.reload()">Tentar de novo</button>
      </div>
    `
    : `
      <div class="boot-state" role="status" aria-live="polite">
        <strong>Carregando o histórico de partidas</strong>
        <p>São alguns megabytes de dados. Na primeira visita costuma demorar mais; depois fica em cache.</p>
      </div>
    `;
  Shell(message, { skipSearch: true });
}

function Shell(content, options = {}) {
  const { section } = route();
  const searchValue = escapeHtml(state.search);
  const sectionSlide = panelSlideSnapshot("site-sections", {
    selector: ".main",
    scope: "site",
    key: section,
    order: navItems.map(([key]) => key),
  });
  app.innerHTML = `
    <div class="app-shell">
      <header class="topbar">
        <div class="topbar-inner">
          <a class="brand" href="#/home" aria-label="${SITE_NAME}">
            <img class="brand-wordmark so-tema-escuro" src="${SITE_WORDMARK_SRC}" alt="" loading="eager" decoding="async" />
            <img class="brand-wordmark so-tema-claro" src="${SITE_WORDMARK_CLARO_SRC}" alt="" loading="lazy" decoding="async" />
            <span class="sr-only">${SITE_NAME}</span>
          </a>
          <nav class="nav" aria-label="Navegação principal">
            ${navItems.map(([key, label]) => `<a class="nav-link ${section === key ? "active" : ""}"${section === key ? ` aria-current="page"` : ""} href="#/${key}">${label}</a>`).join("")}
            <a class="nav-link" href="/cartas/">Cartinhas</a>
            <span class="nav-indicator" aria-hidden="true"></span>
          </nav>
          <div class="global-search">
            <input id="global-search" type="search" placeholder="Buscar time, jogador, campeonato, partida ou mapa" autocomplete="off" role="combobox" aria-expanded="false" aria-controls="search-results" aria-autocomplete="list" aria-label="Buscar no site" value="${searchValue}" ${options.skipSearch ? "disabled" : ""} />
            <span class="search-token">/</span>
            <div id="search-results" class="search-results ${state.searchOpen ? "open" : ""}" role="listbox" aria-label="Resultados da busca"></div>
            <span id="search-status" class="sr-only" role="status" aria-live="polite"></span>
          </div>
          ${window.Auth ? window.Auth.slotHtml() : ""}
        </div>
      </header>
      <main class="main">${ligarFasesDaEpoca(content)}</main>
      <footer class="footer">
        <div class="footer-inner vp-rodape">
          <a class="footer-logo-link" href="#/home" aria-label="${SITE_NAME}">
            <img class="footer-logo so-tema-escuro" src="${SITE_LOGO_SRC}" alt="" loading="lazy" decoding="async" />
            <img class="footer-logo so-tema-claro" src="${SITE_LOGO_CLARO_SRC}" alt="" loading="lazy" decoding="async" />
          </a>
          <span class="vp-rodape-texto">Estatísticas do cenário universitário brasileiro de VALORANT.</span>
          <nav class="vp-rodape-links" aria-label="Rodapé"><a href="#/matches">Partidas</a><a href="#/events">Eventos</a><a href="#/ranking">Ranking</a><a href="#/news">Notícias</a></nav>
        </div>
      </footer>
    </div>
  `;
  if (!options.skipSearch) bindSearch();
  syncNavIndicator();
  playPanelSlide(sectionSlide);
}

// A linha do header e um elemento so, que anda da aba anterior para a atual no
// mesmo tempo do slide do conteudo. Sem posicao anterior (primeiro render, F5,
// volta de uma pagina fora do menu) ela so aparece no lugar certo, sem viajar.
function syncNavIndicator(animate = true) {
  const nav = document.querySelector(".nav");
  const indicator = nav?.querySelector(".nav-indicator");
  if (!nav || !indicator) return;
  const active = nav.querySelector(".nav-link.active");
  if (!active) {
    indicator.style.opacity = "0";
    navIndicatorGeometry = null;
    return;
  }
  const navBox = nav.getBoundingClientRect();
  const activeBox = active.getBoundingClientRect();
  const next = {
    x: Math.round(activeBox.left - navBox.left),
    y: Math.round(activeBox.bottom - navBox.top - NAV_INDICATOR_HEIGHT),
    width: Math.round(activeBox.width),
  };
  const from = (animate && navIndicatorGeometry) || next;
  navIndicatorGeometry = next;
  indicator.style.transition = "none";
  indicator.style.opacity = "1";
  indicator.style.width = `${from.width}px`;
  indicator.style.transform = `translate3d(${from.x}px, ${from.y}px, 0)`;
  if (from === next) return;

  let started = false;
  const start = () => {
    if (started) return;
    started = true;
    indicator.style.transition = "";
    indicator.style.width = `${next.width}px`;
    indicator.style.transform = `translate3d(${next.x}px, ${next.y}px, 0)`;
  };
  requestAnimationFrame(start);
  setTimeout(start, 32);
}

function render() {
  if (!state.ready) return renderLoading();
  normalizeCanonicalRoute();
  updateDocumentTitle();
  const { section, id } = route();
  const routeKey = currentRouteKey();
  const routeChanged = routeKey !== state.routeKey;
  state.routeKey = routeKey;
  // Uma pagina no painel de audiencia e uma chave de rota, e a chave ja
  // inclui a aba: #/teams/x/roster e #/teams/x/stats contam separado, sem
  // evento proprio. Trocar so o filtro nao chega aqui como rota nova - a
  // query fica fora da chave de proposito, e o filtro sobe como evento
  // pelo pushFilterState().
  if (routeChanged) trackPageview();
  // Cada navegacao avisa os comentarios: e assim que eles sabem que a pessoa
  // saiu da pagina e, na volta, buscam a conversa de novo (comments.js).
  window.Comments?.novaRender?.();
  // Na pagina de um campeonato, a equipe que trocou de nome aparece com o escudo
  // da epoca (teamLogo le isto), como o nome que ja vem do teamNames do evento.
  state.eventoDaPagina = eventosDaRota(section, id);
  // O perfil de uma fase antiga liga isto em renderTeamDetail; qualquer outra pagina o desliga.
  state.faseDaPagina = null;
  const pages = {
    home: renderHomeCompact,
    matches: renderMatchesCompact,
    events: renderEventsPage,
    tournaments: renderEventsPage,
    players: renderPlayersCompact,
    ranking: renderRankingPage,
    rankings: renderRankingPage,
    teams: renderTeamsCompact,
    maps: renderMapsCompact,
    u: (username) => window.Profile.renderProfilePage(username),
    news: (slug) => window.News.renderNews(slug),
    forum: (id) => window.Threads.renderThreads(id),
  };
  (pages[section] || renderHomeCompact)(id);
  ajustarTextosVariaveis();
  syncTopbarHeight();
  scrollToRouteTop(routeChanged);
  restoreFilterFocus();
}

function normalizeCanonicalRoute() {
  const canonicalHash = canonicalHashForRoute(route());
  if (!canonicalHash || canonicalHash === currentRouteKey()) return;
  if (window.history?.replaceState) window.history.replaceState(null, "", canonicalHash);
  else window.location.replace(canonicalHash);
}

function canonicalHashForRoute(currentRoute) {
  // /stats e o indice /maps sairam em 29/08/2026. Redireciono em vez de dar
  // 404 porque /stats esteve na navegacao e pode estar em link salvo. So o
  // indice cai aqui: #/maps/<id> tem id e segue para a pagina do mapa.
  if (currentRoute.section === "stats") return "#/home";
  // O forum nasceu em #/threads (07/11) e mudou de endereco em 08/11. Aviso de
  // resposta e link salvo ainda apontam para la: a thread e a query vem junto.
  if (currentRoute.section === "threads") return window.location.hash.replace(/^#\/threads/, "#/forum");
  if (currentRoute.section === "maps" && !currentRoute.id) return "#/home";
  if (currentRoute.section !== "players" || !currentRoute.id) return "";
  const player = playerById(currentRoute.id);
  if (!player?.routeSlug) return "";
  const canonicalHash = playerHref(player, currentRoute.tab);
  return canonicalHash === currentRouteKey() ? "" : canonicalHash;
}

// Equipes: a Camisa em pe das Equipes Participantes, uma por equipe cadastrada, ou
// a lista em tiras como a de Jogadores. Filtro, ordem e visualizacao vivem na URL.
function renderTeamsCompact(id) {
  if (id) return renderTeamDetail(id);
  applyTeamListFiltersFromQuery(routeQuery());
  const { contagem, lista } = resultadoDasEquipes();
  Shell(`
    <section class="vp-lista-pagina vp-equipes">
      <header class="vp-sec">
        <h1>Equipes</h1>
        <p class="lista-contagem" role="status" aria-live="polite">${contagem}</p>
      </header>
      <div class="vp-jg-filtros vp-eqs-filtros">${filtrosDasEquipes()}</div>
      <div data-equipe-resultado>${lista}</div>
    </section>
  `);
  bindListaDeEquipes();
}

function teamListFiltersToQuery() {
  const p = new URLSearchParams();
  if (state.teamListQuery) p.set("q", state.teamListQuery);
  if (state.teamListEstado) p.set("estado", state.teamListEstado);
  if (state.teamListInativas) p.set("inativas", "1");
  if (state.teamListOrdem && state.teamListOrdem !== "ranking") p.set("ordem", state.teamListOrdem);
  if (state.teamListInversa) p.set("inverter", "1");
  if (state.teamListVer === "lista") p.set("ver", "lista");
  return p;
}

function applyTeamListFiltersFromQuery(p) {
  state.teamListQuery = p.get("q") || "";
  const estado = String(p.get("estado") || "").toUpperCase();
  state.teamListEstado = state.db.teams.some((team) => team.profile?.state === estado) ? estado : "";
  state.teamListInativas = p.get("inativas") === "1";
  const ordem = p.get("ordem");
  state.teamListOrdem = TEAM_LISTA_ORDENS.some((item) => item.id === ordem) ? ordem : "ranking";
  state.teamListInversa = p.get("inverter") === "1";
  state.teamListVer = p.get("ver") === "lista" ? "lista" : "quadrados";
}

function filtrosDasEquipesAtivos() {
  return Boolean(state.teamListQuery || state.teamListEstado || state.teamListInativas);
}

// O dia do ultimo jogo, pela mesma conta da regra de inatividade do ranking.
function teamUltimoJogo(team) {
  if (state.teamUltimoJogoCache?.db !== state.db) {
    const datas = rankingDatasDeJogo(state.db.matches, allMatchSeries());
    state.teamUltimoJogoCache = { db: state.db, porEquipe: new Map([...datas].map(([teamId, lista]) => [teamId, lista[lista.length - 1] || 0])) };
  }
  return state.teamUltimoJogoCache.porEquipe.get(team.id) || 0;
}

function teamListRankLabel(team) {
  const valida = teamValidRank(team);
  if (valida) return `#${valida}`;
  return rankingIsInactive(team.ranking) ? "inativa" : "prov";
}

function teamListGrupo(team) {
  if (teamValidRank(team)) return 0;
  return rankingIsInactive(team.ranking) ? 2 : 1;
}

function teamListSigla(team) {
  const profile = team.profile || {};
  const sigla = profile.orgTag || team.orgTag || profile.org || team.org || "";
  return /n[aã]o informad/i.test(sigla) ? "" : sigla;
}

// Texto inteiro em nome, tag e instituicao; as letras na ordem, como em Jogadores,
// so em nome e tag: numa instituicao por extenso "usp" acharia quase todas.
function equipeCasaBusca(team, busca) {
  const curtos = [team.name, team.sourceTag, team.tag, team.shortTag].filter(Boolean).map(normalize);
  const longos = [teamListSigla(team), team.profile?.org, team.org].filter(Boolean).map(normalize);
  const inteiro = [...curtos, ...longos].some((texto) => texto.includes(busca));
  const letras = curtos.some((texto) => {
    let achadas = 0;
    for (const letra of texto) if (letra === busca[achadas]) achadas += 1;
    return achadas === busca.length;
  });
  return { inteiro, letras };
}

function equipesFiltradas({ ignorarEstado = false, inativas = state.teamListInativas } = {}) {
  const busca = normalize(state.teamListQuery).trim();
  const linhas = state.db.teams
    .filter((team) => inativas || !rankingIsInactive(team.ranking))
    .filter((team) => ignorarEstado || !state.teamListEstado || team.profile?.state === state.teamListEstado)
    .map((team) => ({ team, casa: busca ? equipeCasaBusca(team, busca) : null }))
    .filter((linha) => !linha.casa || linha.casa.inteiro || linha.casa.letras);
  const porNome = (a, b) => String(a.name || "").localeCompare(String(b.name || ""), "pt-BR", { numeric: true, sensitivity: "base" });
  const posicao = (team) => teamValidRank(team) || teamOverallRank(team) || 9999;
  const porRanking = (a, b) => teamListGrupo(a) - teamListGrupo(b) || posicao(a) - posicao(b) || porNome(a, b);
  const sinal = state.teamListInversa ? -1 : 1;
  const comparar = {
    ranking: (a, b) => sinal * porRanking(a, b),
    ultimo: (a, b) => sinal * (teamUltimoJogo(b) - teamUltimoJogo(a)) || porRanking(a, b),
    nome: (a, b) => sinal * porNome(a, b),
    mapas: (a, b) => sinal * (Number(b.matches || 0) - Number(a.matches || 0)) || porRanking(a, b),
    estado: (a, b) => sinal * String(a.profile?.state || "￿").localeCompare(String(b.profile?.state || "￿"), "pt-BR") || porRanking(a, b),
  };
  const ordem = comparar[state.teamListOrdem] || comparar.ranking;
  linhas.sort((a, b) => ordem(a.team, b.team));
  // Quem tem o texto inteiro vem antes de quem so tem as letras espalhadas.
  if (busca) linhas.sort((a, b) => Number(b.casa.inteiro) - Number(a.casa.inteiro));
  return linhas.map((linha) => linha.team);
}

function resultadoDasEquipes() {
  const equipes = equipesFiltradas();
  const totalDePaginas = Math.max(1, Math.ceil(equipes.length / TEAM_LISTA_PAGINA));
  const pagina = Math.min(paginaDaLista(routeQuery()), totalDePaginas);
  const inicio = (pagina - 1) * TEAM_LISTA_PAGINA;
  const visiveis = equipes.slice(inicio, inicio + TEAM_LISTA_PAGINA);
  const quadrados = state.teamListVer !== "lista";
  return {
    contagem: visiveis.length ? `Mostrando ${inicio + 1} a ${inicio + visiveis.length} de ${equipes.length} equipes.` : "Nenhuma equipe.",
    lista: `
      ${quadrados ? ordemDasEquipes() : cabecalhoDasEquipes()}
      ${
        visiveis.length
          ? quadrados
            ? `<div class="vp-eq-grade vp-eqs-grade">${visiveis.map(quadradoDaEquipe).join("")}</div>`
            : `<div class="vp-jg-lista vp-eqs-lista">${visiveis.map(linhaDaEquipe).join("")}</div>`
          : equipesVazio()
      }
      ${paginacaoDaLista("teams", pagina, totalDePaginas, teamListFiltersToQuery())}
    `,
  };
}

// Quem procura uma equipe antiga com as inativas escondidas precisa saber que ela existe.
function equipesVazio() {
  const escondidas = state.teamListInativas ? 0 : equipesFiltradas({ inativas: true }).length;
  if (escondidas) return `<p class="empty-state">Nenhuma equipe ativa com esses filtros. ${escondidas === 1 ? "1 equipe inativa aparece" : `${escondidas} equipes inativas aparecem`} em Mostrar inativas.</p>`;
  return `<p class="empty-state">Nenhuma equipe com esses filtros. Tire um filtro para ver mais.</p>`;
}

function estadosDasEquipes() {
  const contagem = new Map();
  equipesFiltradas({ ignorarEstado: true }).forEach((team) => {
    const uf = team.profile?.state;
    if (uf) contagem.set(uf, { uf, nome: team.profile.stateName || uf, flag: team.profile.flag || "", n: (contagem.get(uf)?.n || 0) + 1 });
  });
  if (state.teamListEstado && !contagem.has(state.teamListEstado)) {
    const team = state.db.teams.find((item) => item.profile?.state === state.teamListEstado);
    contagem.set(state.teamListEstado, { uf: state.teamListEstado, nome: team?.profile?.stateName || state.teamListEstado, flag: team?.profile?.flag || "", n: 0 });
  }
  return [...contagem.values()].sort((a, b) => a.uf.localeCompare(b.uf, "pt-BR"));
}

function bandeiraDoEstado(flag, uf) {
  return flag ? `<img class="state-flag" src="${escapeHtml(assetPath(flag))}" alt="" loading="lazy" onerror="this.remove()" />` : "";
}

function filtrosDasEquipes() {
  const estado = state.teamListEstado;
  const botaoVer = (ver, rotulo, icone) => {
    const ativo = (state.teamListVer === "lista") === (ver === "lista");
    return `<button type="button" data-equipe-ver="${ver}" aria-pressed="${ativo}" title="${rotulo}" aria-label="${rotulo}">${icone}</button>`;
  };
  return `
    <input id="team-list-query" class="vp-jg-busca" type="search" placeholder="Buscar equipe ou instituição" aria-label="Buscar equipe ou instituição" autocomplete="off" value="${escapeHtml(state.teamListQuery)}" />
    <details class="filter-dropdown player-team-dropdown vp-eqs-estado-filtro">
      <summary>${filterIcon()}<span>Estado</span><strong>${escapeHtml(estado || "Todos")}</strong>${chevronIcon()}</summary>
      <div class="filter-dropdown-body">
        <div class="vp-eqs-ufs">
          <button type="button" data-equipe-estado="" aria-pressed="${!estado}">Todos</button>
          ${estadosDasEquipes().map((item) => `<button type="button" data-equipe-estado="${escapeHtml(item.uf)}" aria-pressed="${item.uf === estado}" title="${escapeHtml(item.nome)}">${bandeiraDoEstado(item.flag)}<span>${escapeHtml(item.uf)}</span><small>${item.n}</small></button>`).join("")}
        </div>
      </div>
    </details>
    <label class="ranking-details-toggle">
      <input type="checkbox" data-equipe-inativas ${state.teamListInativas ? "checked" : ""} />
      <span>Mostrar inativas</span>
    </label>
    <button type="button" class="vp-jg-toggle" data-equipe-limpar ${filtrosDasEquipesAtivos() ? "" : "hidden"}>Limpar filtros</button>
    <span class="vp-eqs-ver" role="group" aria-label="Visualização">
      ${botaoVer("quadrados", "Quadrados", `<svg viewBox="0 0 16 16" aria-hidden="true"><rect x="1" y="1" width="6" height="6"/><rect x="9" y="1" width="6" height="6"/><rect x="1" y="9" width="6" height="6"/><rect x="9" y="9" width="6" height="6"/></svg>`)}
      ${botaoVer("lista", "Lista", `<svg viewBox="0 0 16 16" aria-hidden="true"><rect x="1" y="2" width="14" height="3"/><rect x="1" y="7" width="14" height="3"/><rect x="1" y="12" width="14" height="3"/></svg>`)}
    </span>
  `;
}

function setaDaOrdemDasEquipes(chave) {
  if (state.teamListOrdem !== chave) return "";
  const descendo = chave === "ultimo" || chave === "mapas";
  return descendo !== state.teamListInversa ? "↓" : "↑";
}

function ordemDasEquipes() {
  return `
    <div class="vp-eqs-ordem" role="group" aria-label="Ordem das equipes">
      <span>Ordenar por</span>
      ${TEAM_LISTA_ORDENS.map((ordem) => {
        const ativa = state.teamListOrdem === ordem.id;
        const seta = setaDaOrdemDasEquipes(ordem.id);
        return `<button type="button" class="vp-jg-toggle" data-equipe-ordem="${ordem.id}" aria-pressed="${ativa}">${escapeHtml(ordem.rotulo)}${seta ? ` <i aria-hidden="true">${seta}</i>` : ""}</button>`;
      }).join("")}
    </div>
  `;
}

function cabecalhoDasEquipes() {
  const coluna = (chave, rotulo, classe = "") => {
    const ativa = state.teamListOrdem === chave;
    const seta = setaDaOrdemDasEquipes(chave);
    return `<button type="button" class="${classe}${ativa ? " ativa" : ""}" data-equipe-ordem="${chave}" aria-pressed="${ativa}">${rotulo}${seta ? ` <i aria-hidden="true">${seta}</i>` : ""}</button>`;
  };
  return `
    <div class="vp-jg-cabeca vp-eqs-cabeca">
      ${coluna("nome", "Equipe")}
      ${coluna("ranking", "Ranking", "num")}
      ${coluna("estado", "Estado", "num")}
      ${coluna("ultimo", "Último jogo", "num")}
      ${coluna("mapas", "Mapas", "num")}
    </div>
  `;
}

// Sem logo, o quadrado fica so com as cores (escolha do dono, 06/11/2026).
function quadradoDaEquipe(team) {
  const ultimo = teamUltimoJogo(team);
  const uf = team.profile?.state || "";
  const sigla = teamListSigla(team);
  return `
    <a class="vp-slide vp-eq vp-eqs" href="#/teams/${escapeHtml(team.id)}" style="${escapeHtml(teamPlateStyle(team))}" title="${escapeHtml(team.name)}">
      <span class="vp-slide-campo"><i></i></span>
      <b class="vp-eq-atual${teamValidRank(team) ? "" : " vp-eqs-texto"}">${escapeHtml(teamListRankLabel(team))}</b>
      ${uf ? `<b class="vp-eqs-uf">${escapeHtml(uf)}</b>` : ""}
      <span class="vp-eq-logo">${teamLogo(team.id, "large")}</span>
      <span class="vp-eq-txt">
        <strong>${escapeHtml(team.name)}</strong>
        ${sigla ? `<small>${escapeHtml(sigla)}</small>` : ""}
        ${ultimo ? `<small class="vp-eqs-ultimo"><span>Último jogo </span>${escapeHtml(formatShortDate(ultimo))}</small>` : ""}
      </span>
    </a>
  `;
}

function linhaDaEquipe(team) {
  const ultimo = teamUltimoJogo(team);
  const profile = team.profile || {};
  const instituicao = teamInstitutionLabel(team);
  return `
    <a class="vp-slide vp-jg-linha vp-eqs-linha" href="#/teams/${escapeHtml(team.id)}" style="${escapeHtml(teamPlateStyle(team))}">
      <span class="vp-slide-campo"><i></i></span>
      <span class="vp-eqs-logo">${teamLogo(team.id, "large")}</span>
      <span class="vp-jg-nome"><strong>${escapeHtml(team.name)}</strong>${/n[aã]o informad/i.test(instituicao) ? "" : `<small class="vp-eqs-inst">${escapeHtml(instituicao)}</small>`}${teamListSigla(team) ? `<small class="vp-eqs-sigla">${escapeHtml(teamListSigla(team))}</small>` : ""}</span>
      <span class="vp-jg-numero vp-eqs-rank${teamValidRank(team) ? "" : " vp-eqs-texto"}">${escapeHtml(teamListRankLabel(team))}</span>
      <span class="vp-eqs-estado">${bandeiraDoEstado(profile.flag)}<span>${escapeHtml(profile.state || "-")}</span></span>
      <span class="vp-eqs-data">${ultimo ? escapeHtml(formatShortDate(ultimo)) : "-"}</span>
      <span class="vp-jg-numero vp-eqs-mapas" data-rotulo="mapas">${escapeHtml(String(team.matches || 0))}</span>
    </a>
  `;
}

// A busca troca so o resultado, como em Jogadores: recriar o campo focado a cada
// tecla inverteria o texto digitado.
function atualizarBuscaDeEquipes() {
  const q = teamListFiltersToQuery().toString();
  window.history.replaceState(null, "", `#/teams${q ? `?${q}` : ""}`);
  const { contagem, lista } = resultadoDasEquipes();
  document.querySelector(".vp-equipes .lista-contagem").textContent = contagem;
  document.querySelector("[data-equipe-resultado]").innerHTML = lista;
  document.querySelector("[data-equipe-limpar]").hidden = !filtrosDasEquipesAtivos();
  bindResultadoDasEquipes();
}

function bindResultadoDasEquipes() {
  document.querySelectorAll("[data-equipe-ordem]").forEach((botao) => {
    botao.addEventListener("click", () => {
      const chave = botao.dataset.equipeOrdem;
      state.teamListInversa = state.teamListOrdem === chave ? !state.teamListInversa : false;
      state.teamListOrdem = chave;
      pushFilterState("teams", teamListFiltersToQuery(), `[data-equipe-ordem="${chave}"]`);
    });
  });
  document.querySelectorAll(".vp-equipes .vp-paginas a").forEach((link) => {
    link.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "instant" }));
  });
}

function bindListaDeEquipes() {
  bindResultadoDasEquipes();
  document.getElementById("team-list-query")?.addEventListener("input", (event) => {
    state.teamListQuery = event.target.value;
    atualizarBuscaDeEquipes();
  });
  document.querySelector("[data-equipe-inativas]")?.addEventListener("change", (event) => {
    state.teamListInativas = event.currentTarget.checked;
    pushFilterState("teams", teamListFiltersToQuery(), "[data-equipe-inativas]");
  });
  document.querySelectorAll("[data-equipe-estado]").forEach((botao) => {
    botao.addEventListener("click", () => {
      state.teamListEstado = botao.dataset.equipeEstado || "";
      pushFilterState("teams", teamListFiltersToQuery(), ".vp-eqs-estado-filtro summary");
    });
  });
  document.querySelectorAll("[data-equipe-ver]").forEach((botao) => {
    botao.addEventListener("click", () => {
      state.teamListVer = botao.dataset.equipeVer === "lista" ? "lista" : "quadrados";
      pushFilterState("teams", teamListFiltersToQuery(), `[data-equipe-ver="${state.teamListVer}"]`);
    });
  });
  document.querySelector("[data-equipe-limpar]")?.addEventListener("click", () => {
    state.teamListQuery = "";
    state.teamListEstado = "";
    state.teamListInativas = false;
    pushFilterState("teams", teamListFiltersToQuery(), "#team-list-query");
  });
}

// O indice /maps saiu em 29/08/2026 junto com /stats. A pagina de UM mapa
// continua viva: ela e ligada pelo placar da partida, pela aba de mapas do
// campeonato e pela pagina do jogador.
function renderMapsCompact(id) {
  if (id) return renderMapDetail(id);
  return renderNotFound("Recurso");
}

// A home em trilhos, como HLTV e vlr.gg: tres colunas desde o topo. Na
// esquerda, os melhores da semana e o ranking; no meio, as partidas por dia e a
// atividade; na direita, noticias e campeonatos. Abaixo de 1180px o trilho da
// direita desce, e abaixo de 760px fica uma coluna so, na ordem do que mais
// importa (ver placar.css).
function renderHomeCompact() {
  const events = listaDeCampeonatos(sortedEvents("recent")).slice(0, HOME_EVENT_LIMIT);
  const topTeams = state.db.teams.slice(0, HOME_RANKING_LIMIT);
  const recentMatches = allMatchSeries().slice().sort(compareSeriesDateDesc).slice(0, HOME_RECENT_MATCH_LIMIT);
  const partidasPorDia = listaPorDia(recentMatches);
  Shell(`
    <h1 class="sr-only">${SITE_NAME}</h1>
    <div class="vp-home">
      <div class="vp-trilho vp-trilho-esq">
        ${weekHighlights()}
        <section class="ranking-panel vp-s-ranking">
          ${panelTitle("Ranking")}
          <div class="vp-placa vp-placa-rk">${topTeams.map(compactRankingRow).join("")}</div>
          ${panelFooterLink("ranking", "Ranking completo")}
        </section>
        ${window.Threads ? window.Threads.painelHome() : ""}
      </div>
      <div class="vp-trilho vp-trilho-meio">
        <section class="vp-s-partidas">
          ${panelTitle("Últimas partidas", "matches", "Ver todas")}
          ${recentMatches.length ? partidasPorDia : `<div class="empty-state">Nenhuma partida registrada ainda.</div>`}
        </section>
      </div>
      <div class="vp-trilho vp-trilho-dir">
        ${window.News ? window.News.blocoTrilho() : ""}
        <section class="events-panel vp-s-campeonatos">
          ${panelTitle("Campeonatos", "events", "Ver todos")}
          <div class="vp-placa vp-placa-ev">${events.map(eventListRow).join("")}</div>
        </section>
      </div>
    </div>
  `);
  bindHomeRankingPanel();
  bindEventCovers(".events-panel", ".vp-evrow");
  bindWeekCarousel();
}

function renderMatchesCompact(id) {
  if (id) return renderMatchDetail(id);
  // a URL e a fonte da verdade do filtro: query ausente significa sem filtro
  applyMatchFiltersFromQuery(routeQuery());
  ensureResultFilterDefaults();
  const filtered = filteredMatches();
  const limite = limiteDaLista(routeQuery());
  Shell(`
    <div class="results-layout vp-partidas">
      <div class="vp-partidas-esq">
        ${matchFilterSidebar()}
        ${mesesDoResumo()}
      </div>
      <section class="vp-lista-pagina full-list-panel results-panel">
        <header class="vp-sec"><h1>Partidas</h1>${contagemDaLista(Math.min(limite, filtered.length), filtered.length, "partidas")}</header>
        <div class="result-list">${listaDeResultados(filtered, limite)}</div>
        ${verMaisBotao("matches", Math.min(limite, filtered.length), filtered.length, matchFiltersToQuery())}
      </section>
      ${resumoDasPartidas(filtered)}
    </div>
  `);
  bindMatchFilters();
  bindResultDayToggles();
  bindResumoDasPartidas();
}

// O resumo ao lado da lista de partidas: os mapas do que esta filtrado. Os meses
// ficam embaixo dos filtros porque sao um filtro de data. Sem jogadores aqui de
// proposito: eles ficam para a futura pagina de stats. Com um mapa ou uma equipe
// filtrados, ele vira o assunto da pagina e ganha o cartao Camisa. Os dois juntos
// dividem um cartao so, o do mapa, com os numeros daquela equipe.
// Mapa e mes filtram ao clicar, e por isso cada um ignora o proprio filtro (ver
// filteredMatches): com Lotus marcado, as outras barras continuam ali para pular
// de mapa em mapa, em vez de sumirem.
function resumoDasPartidas(filtered) {
  return `
    <aside class="vp-resumo" aria-label="Resumo das partidas filtradas">
      ${cartaoDoMapa(filtered) || cartaoDaEquipe(filtered)}
      ${sectionHead("Mapas jogados")}
      ${mapasDoResumo()}
    </aside>
  `;
}

// Vitorias e derrotas da equipe dentro do filtro: somar um mapa ou um mes muda o
// placar. Com duas equipes nao ha um assunto so, entao nao ha cartao.
function cartaoDaEquipe(filtered, team = state.matchTeams.length === 1 ? teamById(state.matchTeams[0]) : null) {
  if (!team || !filtered.length) return "";
  const vitorias = filtered.filter((series) => series.winnerId === team.id).length;
  const derrotas = filtered.filter((series) => series.loserId === team.id).length;
  const taxa = Math.round((vitorias / Math.max(1, vitorias + derrotas)) * 100);
  const placar = `${vitorias}-${derrotas}`;
  const logo = assetPath(team.profile?.logo || team.logo || "");
  const quantas = `${filtered.length} ${filtered.length === 1 ? "partida" : "partidas"}`;
  return plateCard({
    classe: `vp-slide vp-camisa-equipe${placar.length > 4 ? " vp-valor-longo" : ""}`,
    team,
    href: `#/teams/${encodeURIComponent(team.id)}`,
    nome: team.sourceTag || team.tag || team.name,
    figura: logo ? `<span class="vp-camisa-logo"><img src="${escapeHtml(logo)}" alt="" onerror="this.parentElement.remove()" /></span>` : "",
    rotulo: "Neste filtro",
    tag: `${taxa}% de vitórias`,
    valor: placar,
    apoio: quantas,
    atributos: ` aria-label="${escapeHtml(`${team.name}: ${vitorias} ${vitorias === 1 ? "vitória" : "vitórias"} e ${derrotas} ${derrotas === 1 ? "derrota" : "derrotas"} em ${quantas}`)}"`,
  });
}

// Soma o teamStats dos mapas do filtro: de uma equipe, ou das duas de cada mapa.
// Com as duas, cada round entra uma vez em attackRounds e uma em defenseRounds,
// entao as taxas continuam sendo por round.
function somaDoMapa(filtered, mapId, teamId) {
  const soma = { ...emptyTeamRoundStats(), mapas: 0, vitorias: 0, derrotas: 0 };
  filtered.forEach((series) => {
    (series.maps || []).filter((match) => match.mapId === mapId).forEach((match) => {
      const linhas = teamId ? [match.teamStats?.[teamId]] : Object.values(match.teamStats || {});
      if (!linhas.every(Boolean)) return;
      soma.mapas += 1;
      if (teamId && match.winnerId === teamId) soma.vitorias += 1;
      if (teamId && match.loserId === teamId) soma.derrotas += 1;
      linhas.forEach((linha) => {
        Object.keys(emptyTeamRoundStats()).forEach((campo) => {
          soma[campo] += Number(linha[campo]) || 0;
        });
      });
    });
  });
  return soma;
}

function taxaInteira(parte, total) {
  return total ? Math.round((parte / total) * 100) : 0;
}

// O cartao do mapa. Sozinho, ele fala do mapa: ataque e defesa somam 100 e o pistol
// vem por lado. Com uma equipe, os numeros passam a ser dela, e ataque e defesa
// deixam de ser complementares.
function mapaCamisa(map, soma, team, nota, atributos = "") {
  const ataque = taxaInteira(soma.attackWins, soma.attackRounds);
  const defesa = team ? taxaInteira(soma.defenseWins, soma.defenseRounds) : 100 - ataque;
  const emenda = ataque + defesa ? Math.round((ataque / (ataque + defesa)) * 100) : 50;
  const art = mapArtAttrs(map);
  const arte = art ? `<img src="${escapeHtml(art.src)}" data-fallback="${escapeHtml(art.fallback)}" alt="" onerror="mapArtError(this)" />` : "";
  const nome = team ? `${team.sourceTag || team.tag || team.name} em ${map.name}` : map.name;
  const quantos = `${soma.mapas} ${soma.mapas === 1 ? "mapa" : "mapas"}`;
  const apoio = team ? `${soma.vitorias}-${soma.derrotas} em ${quantos}` : `${quantos}, ${soma.attackRounds} rounds`;
  const plantados = soma.plantA + soma.plantB + soma.plantC;
  const sites = ["A", "B", "C"]
    .filter((site) => soma[`plant${site}`])
    .map((site) => `${site} <b>${taxaInteira(soma[`plant${site}`], plantados)}%</b>`)
    .join(", ");
  const pistolAtaque = taxaInteira(soma.pistolAttackWins, soma.pistolAttackRounds);
  const linhas = [
    ["Pistol", team ? `<b>${taxaInteira(soma.pistolWins, soma.pistolRounds)}%</b> de vitórias` : `<b>${pistolAtaque}%</b> ataque, <b>${100 - pistolAtaque}%</b> defesa`],
    ["Plants", `<b>${taxaInteira(soma.plants, soma.attackRounds)}%</b> dos rounds`],
    ["Retakes", `<b>${taxaInteira(soma.retakes, soma.plantsAgainst)}%</b> dos plants`],
    ...(team ? [["Depois de plantar", `<b>${taxaInteira(soma.plantWins, soma.plants)}%</b> de vitórias`]] : []),
    ...(sites ? [["Sites", sites]] : []),
  ];
  return `
    <section class="vp-mapa-resumo" aria-label="Dados de ${escapeHtml(nome)}"${atributos}>
      <a class="vp-mapa-camisa" href="#/maps/${encodeURIComponent(map.id)}" style="--ataque:${emenda}" aria-label="${escapeHtml(`${nome}: ${ataque}% no ataque e ${defesa}% na defesa`)}">
        <span class="vp-mapa-peca vp-mapa-atk">${arte}</span>
        <span class="vp-mapa-peca vp-mapa-def">${arte}</span>
        <span class="vp-mapa-topo"><strong title="${escapeHtml(nome)}"><span class="nome-rolante">${escapeHtml(nome)}</span></strong><small>${escapeHtml(apoio)}</small><small>${escapeHtml(nota)}</small></span>
        <span class="vp-mapa-lado vp-mapa-lado-a"><b>${ataque}%</b><small>Ataque</small></span>
        <span class="vp-mapa-lado vp-mapa-lado-d"><b>${defesa}%</b><small>Defesa</small></span>
      </a>
      <dl class="vp-mapa-dados">
        ${linhas.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${valor}</dd></div>`).join("")}
      </dl>
    </section>
  `;
}

function cartaoDoMapa(filtered) {
  const map = state.matchMaps.length === 1 ? mapById(state.matchMaps[0]) : null;
  if (!map) return "";
  const team = state.matchTeams.length === 1 ? teamById(state.matchTeams[0]) : null;
  const soma = somaDoMapa(filtered, map.id, team?.id);
  return soma.mapas ? mapaCamisa(map, soma, team, "Neste filtro") : "";
}

function mapasDoResumo() {
  const contagem = new Map();
  filteredMatches({ ignorar: "mapas" }).forEach((series) => {
    (series.mapNames || []).filter(Boolean).forEach((nome) => contagem.set(nome, (contagem.get(nome) || 0) + 1));
  });
  return barrasDosMapas(contagem, state.matchMaps, "data-resumo-mapa");
}

// Cada linha e o mapa em cinza, com a arte colorida revelada ate a popularidade.
function barrasDosMapas(contagem, marcados, atributo) {
  const linhas = [...contagem.entries()].sort((a, b) => b[1] - a[1]);
  if (!linhas.length) return "";
  const maior = linhas[0][1];
  const todos = !marcados.length;
  return `
    <section class="vp-resumo-bloco" aria-label="Mapas jogados">
      <div class="vp-rm-lista">
        ${linhas
          .map(([nome, vezes]) => {
            const map = mapByName(nome);
            const art = mapBannerSrc(nome);
            const marcado = Boolean(map) && !todos && marcados.includes(map.id);
            const fora = Boolean(map) && !todos && !marcado;
            return `
              <button type="button" class="vp-rm${fora ? " vp-rm-fora" : ""}" ${map ? `${atributo}="${escapeHtml(map.id)}"` : "disabled"} aria-pressed="${marcado}" style="--parte:${(vezes / maior).toFixed(4)}">
                <span class="vp-rm-arte">${art ? ["vp-rm-cinza", "vp-rm-cor"].map((classe) => `<img class="${classe}" src="${escapeHtml(art.src)}" data-fallback="${escapeHtml(art.fallback)}" alt="" loading="lazy" onerror="mapArtError(this)" />`).join("") : ""}</span>
                <span>${escapeHtml(nome)}</span>
                <b>${vezes}</b>
              </button>
            `;
          })
          .join("")}
      </div>
    </section>
  `;
}

function mesDoResumo(valor) {
  const data = new Date(valor);
  return data.getFullYear() * 12 + data.getMonth();
}

function rotuloDoMes(indice, curto = false) {
  const data = new Date(Math.floor(indice / 12), indice % 12, 1);
  const mes = data.toLocaleDateString("pt-BR", { month: "short" }).replace(".", "");
  return curto ? `${mes} ${String(data.getFullYear()).slice(2)}` : `${mes} de ${data.getFullYear()}`;
}

// O eixo vem do banco inteiro, e nao do que esta filtrado: as barras ficam no
// mesmo lugar quando o filtro muda, e mes sem partida continua no eixo.
function mesesDoResumo() {
  const datas = allMatchSeries().map((series) => series.sortAt || series.startedAt).filter(Boolean);
  if (!datas.length) return "";
  const primeiro = mesDoResumo(Math.min(...datas));
  const ultimo = mesDoResumo(Math.max(...datas));
  const contagem = new Map();
  filteredMatches({ ignorar: "datas" }).forEach((series) => {
    const mes = mesDoResumo(series.sortAt || series.startedAt);
    contagem.set(mes, (contagem.get(mes) || 0) + 1);
  });
  const meses = Array.from({ length: ultimo - primeiro + 1 }, (_, i) => primeiro + i);
  const maior = Math.max(1, ...contagem.values());
  const pico = meses.reduce((melhor, mes) => ((contagem.get(mes) || 0) > (contagem.get(melhor) || 0) ? mes : melhor), meses[0]);
  const marcado = mesMarcadoNoFiltro();
  const destaque = marcado ?? pico;
  const leitura = contagem.size ? `${contagem.get(destaque) || 0} em ${rotuloDoMes(destaque)}` : "Nenhuma partida";
  return `
    <section class="vp-resumo-bloco vp-meses" aria-label="Partidas por mês">
      <h3>Partidas por mês <span data-resumo-leitura data-padrao="${escapeHtml(leitura)}">${escapeHtml(leitura)}</span></h3>
      <div class="vp-rt${marcado === null ? "" : " vp-rt-marcado"}">
        ${meses
          .map((mes) => {
            const vezes = contagem.get(mes) || 0;
            const rotulo = `${vezes} em ${rotuloDoMes(mes)}`;
            return `<button type="button" class="vp-rt-mes" data-resumo-mes="${mes}" data-rotulo="${escapeHtml(rotulo)}" aria-label="${escapeHtml(rotulo)}" aria-pressed="${marcado === mes}" style="--altura:${(vezes / maior).toFixed(4)}"><i></i></button>`;
          })
          .join("")}
      </div>
      <div class="vp-rt-eixo"><span>${escapeHtml(rotuloDoMes(primeiro, true))}</span><span>${escapeHtml(rotuloDoMes(ultimo, true))}</span></div>
    </section>
  `;
}

function diasDoMes(indice) {
  const ano = Math.floor(indice / 12);
  const mes = indice % 12;
  const texto = (data) => `${data.getFullYear()}-${String(data.getMonth() + 1).padStart(2, "0")}-${String(data.getDate()).padStart(2, "0")}`;
  return { de: texto(new Date(ano, mes, 1)), ate: texto(new Date(ano, mes + 1, 0)) };
}

// O mes so conta como marcado quando o filtro de data e exatamente aquele mes:
// um intervalo digitado a mao nao acende barra nenhuma.
function mesMarcadoNoFiltro() {
  if (!state.matchDateFrom || !state.matchDateTo) return null;
  const mes = mesDoResumo(dateInputToStart(state.matchDateFrom));
  const { de, ate } = diasDoMes(mes);
  return state.matchDateFrom === de && state.matchDateTo === ate ? mes : null;
}

function bindResumoDasPartidas() {
  const pagina = document.querySelector(".vp-partidas");
  const resumo = pagina?.querySelector(".vp-resumo");
  if (!resumo) return;
  resumo.style.setProperty("--resumo-altura", `${resumo.offsetHeight}px`);
  const leitura = pagina.querySelector("[data-resumo-leitura]");
  const mostrar = (texto) => {
    if (leitura) leitura.textContent = texto;
  };
  pagina.addEventListener("click", (event) => {
    const mapa = event.target.closest("[data-resumo-mapa]");
    const mes = event.target.closest("[data-resumo-mes]");
    if (mapa) {
      const id = mapa.dataset.resumoMapa;
      const soEle = state.matchMaps.length === 1 && state.matchMaps[0] === id;
      state.matchMaps = soEle ? [] : [id];
      pushFilterState("matches", matchFiltersToQuery(), `[data-resumo-mapa="${id}"]`);
    }
    if (mes) {
      const indice = Number(mes.dataset.resumoMes);
      const { de, ate } = diasDoMes(indice);
      const jaMarcado = mesMarcadoNoFiltro() === indice;
      state.matchDateFrom = jaMarcado ? "" : de;
      state.matchDateTo = jaMarcado ? "" : ate;
      pushFilterState("matches", matchFiltersToQuery(), `[data-resumo-mes="${indice}"]`);
    }
  });
  ["mouseover", "focusin"].forEach((tipo) => {
    pagina.addEventListener(tipo, (event) => {
      const mes = event.target.closest("[data-resumo-mes]");
      if (mes) mostrar(mes.dataset.rotulo);
    });
  });
  ["mouseout", "focusout"].forEach((tipo) => {
    pagina.addEventListener(tipo, (event) => {
      if (event.target.closest("[data-resumo-mes]")) mostrar(leitura?.dataset.padrao || "");
    });
  });
}

const LISTA_PAGINA = 50;

function limiteDaLista(p, padrao = LISTA_PAGINA) {
  const bruto = Number.parseInt(p.get("limite") || "", 10);
  if (!Number.isFinite(bruto) || bruto <= 0) return padrao;
  return Math.min(bruto, 5000);
}

// Agrupa por dia para a data sair de dentro de cada linha e virar marco de
// rolagem. Sem isso, "16 de ago de 2026" aparecia 419 vezes.
function agruparPorDia(series) {
  const grupos = [];
  let atual = null;
  series.forEach((item) => {
    const chave = dayKey(item.sortAt || item.startedAt);
    if (!atual || atual.chave !== chave) {
      atual = { chave, rotulo: formatDate(item.sortAt || item.startedAt, "date"), itens: [] };
      grupos.push(atual);
    }
    atual.itens.push(item);
  });
  return grupos;
}

function chevronIcon() {
  return `<svg class="result-day-mark" viewBox="0 0 12 12" width="12" height="12" aria-hidden="true" focusable="false"><path d="M3 4.5 6 8l3-3.5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

// Os campeonatos que aconteceram no dia, sem repetir. Medido no banco: o dia
// mais cheio tem 3 e a mediana e 1, entao cabem todos - nao precisa de "+2".
function eventosDoDia(itens) {
  const vistos = new Set();
  const eventos = [];
  for (const item of itens) {
    const id = item.eventId;
    if (!id || vistos.has(id)) continue;
    vistos.add(id);
    const evento = state.db.tournaments.find((row) => row.id === id);
    if (evento) eventos.push(evento);
  }
  return eventos;
}

// As partidas no formato da home: o dia como rotulo solto e as linhas do dia
// numa lista so. Sem o botao de abrir e fechar dia da lista de #/matches, que
// so faz sentido numa lista longa. `kd` traz o abate e morte de um jogador.
function listaPorDia(series, options = {}) {
  return agruparPorDia(series)
    .map((grupo) => `<p class="vp-dia">${escapeHtml(grupo.rotulo)}</p><div class="vp-lista">${grupo.itens.map((item) => matchResultRow(item, { when: "hour", ...(options.kd ? { kd: options.kd(item) } : {}) })).join("")}</div>`)
    .join("");
}

function listaDeResultados(filtered, limite) {
  if (!filtered.length) return `<div class="empty-state">Nenhuma partida encontrada com esses filtros.</div>`;
  return agruparPorDia(filtered.slice(0, limite))
    .map((grupo) => {
      const aberto = !state.diasFechados.has(grupo.chave);
      const painelId = `dia-${safeDomId(grupo.chave)}`;
      const quantas = `${grupo.itens.length} ${grupo.itens.length === 1 ? "partida" : "partidas"}`;
      return `
        <section class="result-day-group" data-result-day="${escapeHtml(grupo.chave)}">
          <h2 class="result-day">
            <button class="result-day-toggle" type="button" data-result-day-toggle aria-expanded="${aberto}" aria-controls="${painelId}">
              <span class="result-day-name">
                <span class="result-day-label">${escapeHtml(grupo.rotulo)}</span>
                ${chevronIcon()}
              </span>
              <span class="result-day-events">${eventosDoDia(grupo.itens).map((evento) => eventLogo(evento, "tiny")).join("")}</span>
              <span class="result-day-count">${escapeHtml(quantas)}</span>
            </button>
          </h2>
          <div class="result-day-rows" id="${painelId}" ${aberto ? "" : "inert"}>
            <div class="result-day-rows-inner">
              <div class="vp-lista">${grupo.itens.map((item) => matchResultRow(item, { when: "hour" })).join("")}</div>
            </div>
          </div>
        </section>
      `;
    })
    .join("");
}

// Alterna sem re-renderizar: o estado vira classe e atributo no lugar. Assim o
// foco fica no botao que a pessoa acabou de apertar, o que uma re-render
// perderia - e a lista de /partidas tem 50 linhas para reconstruir a toa.
function bindResultDayToggles() {
  document.querySelectorAll("[data-result-day-toggle]").forEach((botao) => {
    botao.addEventListener("click", () => {
      const grupo = botao.closest(".result-day-group");
      const painel = grupo?.querySelector(".result-day-rows");
      const chave = grupo?.dataset.resultDay || "";
      if (!grupo || !painel || !chave) return;
      const fechando = botao.getAttribute("aria-expanded") === "true";
      botao.setAttribute("aria-expanded", String(!fechando));
      painel.toggleAttribute("inert", fechando);
      if (fechando) state.diasFechados.add(chave);
      else state.diasFechados.delete(chave);
      // A varredura de texto cortado poda subarvores `inert`, entao o que
      // estava fechado nunca foi medido. Abriu, mede agora.
      if (!fechando) ajustarTextosVariaveis(painel);
    });
  });
}

function verMaisBotao(section, mostrando, total, params) {
  if (mostrando >= total) return "";
  const proximo = new URLSearchParams(params);
  proximo.set("limite", String(mostrando + LISTA_PAGINA));
  const restante = total - mostrando;
  const passo = Math.min(LISTA_PAGINA, restante);
  return `<a class="lista-ver-mais" href="#/${section}?${proximo.toString()}">Ver mais ${passo} de ${restante} restantes</a>`;
}

function contagemDaLista(mostrando, total, rotulo) {
  return `<p class="lista-contagem" role="status" aria-live="polite">Mostrando ${mostrando} de ${total} ${rotulo}.</p>`;
}

function matchFilterSidebar() {
  return `
    <aside class="match-filter-sidebar" aria-label="Filtros de resultados">
      <header class="vp-sec">
        <h2>Filtros</h2>
        ${matchFiltersToQuery().toString() ? `<button type="button" class="vp-sec-more vp-filtros-limpar" data-match-filter="reset">Limpar filtros</button>` : ""}
      </header>
      <div class="vp-filtros">
      <details class="filter-dropdown" data-filter-group="bestOf"${resultFilterOpenAttr("bestOf")}>
        <summary><span>Melhor de</span><strong>${matchBestOfLabel()}</strong>${chevronIcon()}</summary>
        <div class="filter-dropdown-body">
          <div class="filter-button-grid best-of-grid">
            ${MELHOR_DE_OPCOES.map((value) => filterPill("bestOf", value, `MD${value}`, state.matchBestOfs.includes(value))).join("")}
          </div>
        </div>
      </details>
      <details class="filter-dropdown" data-filter-group="maps"${resultFilterOpenAttr("maps")}>
        <summary><span>Mapa</span><strong>${mapFilterSummary()}</strong>${chevronIcon()}</summary>
        <div class="filter-dropdown-body">
          <div class="filter-option-stack map-filter-options">
            ${state.db.maps.map(mapFilterButton).join("")}
          </div>
        </div>
      </details>
      <details class="filter-dropdown" data-filter-group="tournaments"${resultFilterOpenAttr("tournaments")}>
        <summary><span>Campeonato</span><strong>${tournamentFilterSummary()}</strong>${chevronIcon()}</summary>
        <div class="filter-dropdown-body">
          ${ordemDeCampeonatoControle()}
          <div class="filter-option-stack event-filter-options" data-event-options>
            ${campeonatosDoFiltro().map(eventFilterButton).join("")}
          </div>
        </div>
      </details>
      <details class="filter-dropdown" data-filter-group="datas"${resultFilterOpenAttr("datas")}>
        <summary><span>Data</span><strong>${escapeHtml(dateFilterSummary())}</strong>${chevronIcon()}</summary>
        <div class="filter-dropdown-body">
          <label class="filter-date-field">
            <span>De</span>
            <input class="filter-control" type="date" data-match-date="from" value="${escapeHtml(state.matchDateFrom)}" max="${escapeHtml(state.matchDateTo || "")}" />
          </label>
          <label class="filter-date-field">
            <span>Até</span>
            <input class="filter-control" type="date" data-match-date="to" value="${escapeHtml(state.matchDateTo)}" min="${escapeHtml(state.matchDateFrom || "")}" />
          </label>
        </div>
      </details>
      <details class="filter-dropdown" data-filter-group="teams"${resultFilterOpenAttr("teams")}>
        <summary><span>Equipe</span><strong>${teamFilterSummary()}</strong>${chevronIcon()}</summary>
        <div class="filter-dropdown-body">
          <input id="match-team-query" class="filter-control team-filter-search" type="search" placeholder="Buscar equipe" value="${escapeHtml(state.matchTeamQuery)}" autocomplete="off" />
          <div class="team-filter-options" data-team-options>
            ${matchTeamOptionsHtml()}
          </div>
        </div>
      </details>
      </div>
    </aside>
  `;
}

const LISTA_SEP = ",";

// So entra na URL o que difere do padrao: link curto para o caso comum.
function matchFiltersToQuery() {
  const p = new URLSearchParams();
  const todosMapas = state.db.maps.map((m) => m.id);
  const todosEventos = visibleTournaments().map((e) => e.id);
  // Serializa o lado mais curto, e so o que esta marcado: nada marcado nao entra
  // na URL. Marcar 11 de 12 mapas vira "sem-mapas=lotus" em vez de listar os 11.
  // `md` guarda a mesma chave de antes de o filtro virar multipla escolha, e
  // continua legivel do jeito antigo: um link salvo com `?md=3` cai em lerSelecao
  // como a lista de um item so, que e exatamente o que ele queria dizer.
  escreverSelecao(p, "md", state.matchBestOfs, MELHOR_DE_OPCOES);
  escreverSelecao(p, "mapas", state.matchMaps, todosMapas);
  escreverSelecao(p, "eventos", state.matchTournaments, todosEventos);
  if (Array.isArray(state.matchTeams) && state.matchTeams.length) p.set("equipes", state.matchTeams.join(LISTA_SEP));
  if (state.matchDateFrom) p.set("de", state.matchDateFrom);
  if (state.matchDateTo) p.set("ate", state.matchDateTo);
  return p;
}

function escreverSelecao(p, chave, selecionados, todos) {
  if (!Array.isArray(selecionados) || !selecionados.length) return;
  const fora = todos.filter((id) => !selecionados.includes(id));
  if (fora.length && fora.length < selecionados.length) p.set("sem-" + chave, fora.join(LISTA_SEP));
  else p.set(chave, selecionados.join(LISTA_SEP));
}

function lerSelecao(p, chave, todos) {
  const validos = new Set(todos);
  const lista = (v) => (v || "").split(LISTA_SEP).filter((id) => validos.has(id));
  if (p.has("sem-" + chave)) {
    const fora = new Set(lista(p.get("sem-" + chave)));
    return todos.filter((id) => !fora.has(id));
  }
  if (p.has(chave)) return lista(p.get(chave));
  return null;
}

function applyMatchFiltersFromQuery(p) {
  // resetResultFilters tambem fecha os <details> e limpa a busca de equipe;
  // preservar as duas aqui, senao a cada clique o dropdown se fecha e o botao
  // clicado some da tela, e a lista filtrada volta para as 98 equipes - medido:
  // buscar "caap" mostra 4 opcoes, e o clique devolvia 98 e esticava a pagina
  // em 893px debaixo do ponteiro.
  //
  // A busca fica fora da URL de proposito, como o estado de aberto/fechado: ela
  // e ajuda para achar a equipe, nao filtro do resultado - quem filtra e a
  // selecao, e essa ja viaja em `equipes`.
  const aberto = state.resultFilterOpen;
  const buscaDeEquipe = state.matchTeamQuery;
  // A ordem da lista de campeonatos e preferencia de leitura, nao filtro: ela
  // atravessa o Reset pelo mesmo motivo que a busca de equipe atravessa.
  const ordemDeCampeonato = state.matchTournamentOrder;
  resetResultFilters();
  if (aberto) state.resultFilterOpen = aberto;
  state.matchTeamQuery = buscaDeEquipe;
  state.matchTournamentOrder = ordemDeCampeonato;
  const lista = (chave) => (p.get(chave) || "").split(LISTA_SEP).filter(Boolean);
  const formatos = lerSelecao(p, "md", MELHOR_DE_OPCOES);
  if (formatos) state.matchBestOfs = formatos;
  const mapas = lerSelecao(p, "mapas", state.db.maps.map((m) => m.id));
  if (mapas) state.matchMaps = mapas;
  const eventos = lerSelecao(p, "eventos", visibleTournaments().map((e) => e.id));
  if (eventos) state.matchTournaments = eventos;
  if (p.has("equipes")) {
    const validos = new Set(state.db.teams.map((t) => t.id));
    state.matchTeams = lista("equipes").filter((id) => validos.has(id));
  }
  if (p.get("de")) state.matchDateFrom = p.get("de");
  if (p.get("ate")) state.matchDateTo = p.get("ate");
}

function playerFiltersToQuery() {
  const p = new URLSearchParams();
  if (state.playerQuery) p.set("q", state.playerQuery);
  if (state.playerTeam && state.playerTeam !== "all") p.set("equipe", state.playerTeam);
  if (state.playerComEquipe) p.set("atual", "1");
  if (state.playerOrdem && state.playerOrdem !== "mapas") p.set("ordem", state.playerOrdem);
  if (state.playerOrdemInversa) p.set("inverter", "1");
  return p;
}

function applyPlayerFiltersFromQuery(p) {
  state.playerQuery = p.get("q") || "";
  state.playerTeam = p.get("equipe") || "all";
  state.playerComEquipe = p.get("atual") === "1";
  state.playerOrdem = p.get("ordem") || "mapas";
  state.playerOrdemInversa = p.get("inverter") === "1";
}

// Escreve o filtro no hash. O hashchange existente re-renderiza, entao Back
// desfaz um filtro por vez em vez de sair da pagina.
function pushFilterState(section, params, focoSeletor) {
  state.filterFocus = focoSeletor || null;
  // Os treze pontos que mexem em filtro passam todos por aqui, entao o
  // evento mora neste ponto unico em vez de em cada botao.
  trackFiltro(section, params);
  const q = params.toString();
  const alvo = "#/" + section + (q ? "?" + q : "");
  if (window.location.hash === alvo) {
    render();
    return;
  }
  window.location.hash = alvo;
}

// Depois de re-renderizar, o foco voltava para <body> e a segunda desmarcacao
// exigia re-tabular desde o logo.
// A topbar e sticky e tem altura variavel (211px no celular, onde a navegacao
// quebra em duas linhas). Publicar a altura real permite que o cabecalho de dia
// gruda logo abaixo dela em vez de sumir por tras.
function syncTopbarHeight() {
  const topbar = document.querySelector(".topbar");
  if (!topbar) return;
  const altura = Math.round(topbar.getBoundingClientRect().height);
  document.documentElement.style.setProperty("--topbar-h", altura + "px");
}

function restoreFilterFocus() {
  const sel = state.filterFocus;
  if (!sel) return;
  state.filterFocus = null;
  const alvo = document.querySelector(sel);
  if (alvo) alvo.focus({ preventScroll: true });
}

function ensureResultFilterDefaults() {
  if (!Array.isArray(state.matchBestOfs)) state.matchBestOfs = [];
  if (!Array.isArray(state.matchMaps)) {
    state.matchMaps = state.matchMap && state.matchMap !== "all" ? [state.matchMap] : [];
  }
  if (!Array.isArray(state.matchTournaments)) {
    state.matchTournaments = state.matchTournament && state.matchTournament !== "all" ? [state.matchTournament] : [];
  } else {
    const visibleIds = new Set(visibleTournaments().map((event) => event.id));
    state.matchTournaments = state.matchTournaments.filter((eventId) => visibleIds.has(eventId));
  }
  if (!Array.isArray(state.matchTeams)) {
    state.matchTeams = state.matchTeam && state.matchTeam !== "all" ? [state.matchTeam] : [];
  }
}

function resultFilterOpenAttr(key) {
  return state.resultFilterOpen?.[key] ? " open" : "";
}

function filterIcon() {
  return `<span class="filter-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false"><path d="M4 5h16l-6 7v5l-4 2v-7L4 5z"></path></svg></span>`;
}

function resetIcon() {
  return `<span class="filter-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false"><path d="M3 12a9 9 0 1 0 3-6.7"></path><path d="M3 4v6h6"></path></svg></span>`;
}

// Mesmo padrao dos outros resumos: fechado, a gaveta diz o que esta valendo.
function dateFilterSummary() {
  const de = formatShortDate(dateInputToStart(state.matchDateFrom));
  const ate = formatShortDate(dateInputToEnd(state.matchDateTo));
  if (de && ate) return `${de} - ${ate}`;
  if (de) return `A partir de ${de}`;
  if (ate) return `Até ${ate}`;
  return "Todas";
}

function matchBestOfLabel() {
  const selecionados = Array.isArray(state.matchBestOfs) ? state.matchBestOfs : [];
  if (!selecionados.length || selecionados.length === MELHOR_DE_OPCOES.length) return "Todos";
  // Sao no maximo tres, entao a gaveta fechada diz quais - "2 formatos" seria
  // uma contagem onde cabe a resposta.
  return MELHOR_DE_OPCOES.filter((valor) => selecionados.includes(valor)).map((valor) => `MD${valor}`).join(", ");
}

// A gaveta de campeonato abre com 16 nomes. Em ordem alfabetica se acha o que
// se procura pelo nome; em ordem de data se ve primeiro o que ainda esta
// acontecendo. As duas leituras sao legitimas e nenhuma serve para as duas
// perguntas, por isso viraram um botao em vez de uma escolha nossa.
function campeonatosDoFiltro() {
  if (state.matchTournamentOrder === "recentes") return sortedEvents("end");
  return visibleTournaments()
    .slice()
    .sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), "pt-BR", { numeric: true, sensitivity: "base" }));
}

function ordemDeCampeonatoControle() {
  return `
    <div class="filter-sort-row" role="group" aria-label="Ordem dos campeonatos">
      <span class="filter-sort-label">Ordenar por</span>
      ${ORDENS_DE_CAMPEONATO.map((ordem) => {
        const ativo = state.matchTournamentOrder === ordem.id;
        return `<button type="button" class="filter-sort-button ${ativo ? "active" : ""}" data-tournament-order="${escapeHtml(ordem.id)}" aria-pressed="${ativo ? "true" : "false"}">${escapeHtml(ordem.rotulo)}</button>`;
      }).join("")}
    </div>
  `;
}

function mapFilterSummary() {
  return selectedFilterSummary(state.matchMaps, state.db.maps, "mapa", "mapas", "Todos", "Todos");
}

function tournamentFilterSummary() {
  return selectedFilterSummary(state.matchTournaments, visibleTournaments(), "campeonato", "campeonatos", "Todos", "Todos");
}

function teamFilterSummary() {
  return selectedFilterSummary(state.matchTeams, state.db.teams, "equipe", "equipes", "Todas", "Todas");
}

function selectedFilterSummary(selectedIds, items, singular, plural, emptyLabel, allLabel) {
  const selected = Array.isArray(selectedIds) ? selectedIds : [];
  if (!selected.length) return emptyLabel;
  if (selected.length === items.length) return allLabel;
  if (selected.length === 1) {
    const item = items.find((row) => row.id === selected[0]);
    return escapeHtml(item?.name || item?.tag || singular);
  }
  return `${selected.length} ${plural}`;
}

// Com a marca de selecao, como mapa e campeonato: o filtro passou a ser
// marca/desmarca cada um, e tres pastilhas acesas sem marca ainda leem como
// "escolha uma".
function filterPill(filter, value, label, active) {
  return `<button type="button" class="filter-pill ${active ? "active" : ""}" data-match-filter="${escapeHtml(filter)}" data-value="${escapeHtml(value)}" aria-pressed="${active ? "true" : "false"}"><span class="filter-check" aria-hidden="true"></span><span>${escapeHtml(label)}</span></button>`;
}

function mapFilterButton(map) {
  const art = mapArtAttrs(map);
  const active = state.matchMaps.includes(map.id);
  return `
    <button type="button" class="filter-banner map-filter-button ${active ? "active" : ""}" data-match-filter="map" data-value="${escapeHtml(map.id)}" aria-pressed="${active ? "true" : "false"}">
      ${art ? `<img src="${escapeHtml(art.src)}" data-fallback="${escapeHtml(art.fallback)}" alt="" loading="lazy" onerror="mapArtError(this)" />` : ""}
      <span class="filter-check" aria-hidden="true"></span>
      <span class="filter-banner-label">${escapeHtml(map.name)}</span>
    </button>
  `;
}

function eventFilterButton(event) {
  const active = state.matchTournaments.includes(event.id);
  return `
    <button type="button" class="filter-event-button ${active ? "active" : ""}" data-match-filter="tournament" data-value="${escapeHtml(event.id)}" aria-pressed="${active ? "true" : "false"}">
      <span class="filter-check" aria-hidden="true"></span>${eventLogo(event, "tiny")}<span>${escapeHtml(event.name)}</span>
    </button>
  `;
}

function matchTeamOptionsHtml() {
  const query = normalize(state.matchTeamQuery);
  const teams = state.db.teams
    .filter((team) => !query || normalize(`${team.name} ${team.sourceTag || team.tag} ${team.org || ""}`).includes(query))
    .sort((a, b) => a.name.localeCompare(b.name, "pt-BR", { sensitivity: "base" }));
  return `
    ${
      teams.length
        ? teams.map(teamFilterButton).join("")
        : `<div class="empty-state compact-empty">Nenhuma equipe encontrada.</div>`
    }
  `;
}

function teamFilterButton(team) {
  const active = state.matchTeams.includes(team.id);
  return `
    <button type="button" class="team-filter-button ${active ? "active" : ""}" data-match-filter="team" data-value="${escapeHtml(team.id)}" aria-pressed="${active ? "true" : "false"}">
      <span class="filter-check" aria-hidden="true"></span>${teamLogo(team.id)}<strong>${escapeHtml(team.name)}</strong>
    </button>
  `;
}

function renderEventsPage(id) {
  if (id) return renderTournamentDetail(id);
  applyEventFiltersFromQuery(routeQuery());
  const events = eventsFiltrados();
  const total = listaDeCampeonatos(visibleTournaments()).length;
  Shell(`
    <section class="vp-lista-pagina full-list-panel vp-eventos">
      <header class="vp-sec"><h1>Eventos</h1>${contagemDaLista(events.length, total, "campeonatos")}</header>
      ${eventFilterBar()}
      ${eventTableHead()}
      <div class="event-list large">${events.length ? events.map(eventDirectoryRow).join("") : `<p class="empty-state">Nenhum campeonato com esses filtros. Tire um filtro para ver mais.</p>`}</div>
    </section>
  `);
  bindEventTable();
  bindEventCovers(".vp-eventos .event-list", ".event-row-rich");
}

function renderPlayersCompact(id) {
  if (id) return renderPlayerDetail(id);
  applyPlayerFiltersFromQuery(routeQuery());
  const { contagem, lista } = resultadoDosJogadores();
  Shell(`
    <section class="vp-lista-pagina vp-jogadores">
      <header class="vp-sec">
        <h1>Jogadores</h1>
        <p class="lista-contagem" role="status" aria-live="polite">${contagem}</p>
      </header>
      <div class="vp-jg-filtros">${filtrosDosJogadores()}</div>
      <div data-jogador-resultado>${lista}</div>
    </section>
  `);
  bindPlayerFilters();
  bindListaDeJogadores();
}

function resultadoDosJogadores() {
  const players = filteredPlayers();
  const totalDePaginas = Math.max(1, Math.ceil(players.length / LISTA_PAGINA));
  const pagina = Math.min(paginaDaLista(routeQuery()), totalDePaginas);
  const inicio = (pagina - 1) * LISTA_PAGINA;
  const visiveis = players.slice(inicio, inicio + LISTA_PAGINA);
  return {
    contagem: visiveis.length ? `Mostrando ${inicio + 1} a ${inicio + visiveis.length} de ${players.length} jogadores.` : "Nenhum jogador.",
    lista: `
      ${visiveis.length ? `${cabecalhoDosJogadores()}<div class="vp-jg-lista">${visiveis.map(linhaDoJogador).join("")}</div>` : `<p class="empty-state">Nenhum jogador com esses filtros. Tire um filtro para ver mais.</p>`}
      ${paginacaoDaLista("players", pagina, totalDePaginas, playerFiltersToQuery())}
    `,
  };
}

// A busca troca so o resultado: recriar a pagina a cada tecla destruiria o campo
// em que a pessoa esta digitando. O replaceState nao dispara hashchange e nao
// enche o historico, e tirar `pagina` do hash devolve a lista para a primeira.
function atualizarBuscaDeJogadores() {
  const q = playerFiltersToQuery().toString();
  window.history.replaceState(null, "", `#/players${q ? `?${q}` : ""}`);
  const { contagem, lista } = resultadoDosJogadores();
  document.querySelector(".vp-jogadores .lista-contagem").textContent = contagem;
  document.querySelector("[data-jogador-resultado]").innerHTML = lista;
  document.querySelector("[data-jogador-limpar]").hidden = !filtrosDosJogadoresAtivos();
  bindResultadoDosJogadores();
}

function paginaDaLista(p) {
  const bruto = Number.parseInt(p.get("pagina") || "", 10);
  return Number.isFinite(bruto) && bruto > 0 ? bruto : 1;
}

// Primeira, ultima e as vizinhas da atual: com 23 paginas, listar todas nao
// caberia no celular. As reticencias so entram quando pulam mais de uma pagina.
function paginasVisiveis(pagina, total) {
  const paginas = [...new Set([1, pagina - 1, pagina, pagina + 1, total])].filter((n) => n >= 1 && n <= total).sort((a, b) => a - b);
  return paginas.flatMap((n, i) => {
    const anterior = paginas[i - 1];
    if (!anterior || n - anterior === 1) return [n];
    return n - anterior === 2 ? [n - 1, n] : [null, n];
  });
}

function paginacaoDaLista(section, pagina, total, params, chave = "pagina") {
  if (total <= 1) return "";
  const href = (n) => {
    const proxima = new URLSearchParams(params);
    if (n > 1) proxima.set(chave, String(n));
    const texto = proxima.toString();
    return `#/${section}${texto ? `?${texto}` : ""}`;
  };
  return `
    <nav class="vp-paginas" aria-label="Páginas da lista">
      ${pagina > 1 ? `<a href="${href(pagina - 1)}">Anterior</a>` : ""}
      ${paginasVisiveis(pagina, total).map((n) => (n === null ? `<span aria-hidden="true">...</span>` : `<a href="${href(n)}"${n === pagina ? ` aria-current="page"` : ""}>${n}</a>`)).join("")}
      ${pagina < total ? `<a href="${href(pagina + 1)}">Próxima</a>` : ""}
    </nav>
  `;
}

function filtrosDosJogadoresAtivos() {
  return Boolean(state.playerQuery || state.playerTeam !== "all" || state.playerComEquipe);
}

function filtrosDosJogadores() {
  return `
    <input id="player-query" class="vp-jg-busca" type="search" placeholder="Buscar jogador" aria-label="Buscar jogador" value="${escapeHtml(state.playerQuery)}" />
    ${playerTeamDropdown()}
    <label class="ranking-details-toggle">
      <input type="checkbox" data-jogador-atual ${state.playerComEquipe ? "checked" : ""} />
      <span>Com equipe atual</span>
    </label>
    <button type="button" class="vp-jg-toggle" data-jogador-limpar ${filtrosDosJogadoresAtivos() ? "" : "hidden"}>Limpar filtros</button>
  `;
}

function cabecalhoDosJogadores() {
  const coluna = (chave, rotulo, descendo, classe = "") => {
    const ativa = state.playerOrdem === chave;
    const seta = ativa ? (descendo !== Boolean(state.playerOrdemInversa) ? "↓" : "↑") : "";
    return `<button type="button" class="${classe}${ativa ? " ativa" : ""}" data-jogador-ordem="${chave}" aria-pressed="${ativa}">${rotulo}${seta ? ` <i aria-hidden="true">${seta}</i>` : ""}</button>`;
  };
  return `
    <div class="vp-jg-cabeca">
      ${coluna("nome", "Jogador", false)}
      ${coluna("equipe", "Equipe", false)}
      <span>Agentes</span>
      <span>Função</span>
      ${coluna("eventos", "Eventos", true, "num")}
      ${coluna("mapas", "Mapas", true, "num")}
    </div>
  `;
}

// Quem esta sem equipe veste as cores da ultima, com o nome dela em "Ultima:".
function linhaDoJogador(player) {
  const atual = playerPrimaryTeam(player);
  const team = atual || teamById(player.teamId);
  const nomeDaEquipe = atual?.name || (team ? `Última: ${team.name}` : "Sem equipe");
  const funcao = playerDominantRole(player);
  return `
    <a class="vp-slide vp-jg-linha" href="${playerHref(player)}" style="${escapeHtml(teamPlateStyle(team))}">
      <span class="vp-slide-campo"><i></i></span>
      ${playerFigure(player, team, "vp-slide-foto")}
      <span class="vp-jg-nome"><strong>${escapeHtml(playerDirectoryName(player))}</strong><small>${escapeHtml(playerCurrentNick(player))}</small></span>
      <span class="vp-jg-equipe${atual ? "" : " sem-atual"}">${team ? teamLogo(team.id, "tiny") : ""}<span>${escapeHtml(nomeDaEquipe)}</span></span>
      <span class="vp-jg-agentes">${(player.agentStats || []).slice(0, 3).map(agentMiniIcon).join("")}</span>
      <span class="vp-jg-funcao">${funcao ? `${roleMiniIcon(funcao)}<span>${escapeHtml(funcao.label)}</span>` : "-"}</span>
      <span class="vp-jg-numero" data-rotulo="eventos">${(player.eventStats || []).length}</span>
      <span class="vp-jg-numero" data-rotulo="mapas">${escapeHtml(String(player.matches || 0))}</span>
    </a>
  `;
}

function bindResultadoDosJogadores() {
  document.querySelectorAll("[data-jogador-ordem]").forEach((botao) => {
    botao.addEventListener("click", () => {
      const chave = botao.dataset.jogadorOrdem;
      state.playerOrdemInversa = state.playerOrdem === chave ? !state.playerOrdemInversa : false;
      state.playerOrdem = chave;
      pushFilterState("players", playerFiltersToQuery(), `[data-jogador-ordem="${chave}"]`);
    });
  });
  // Trocar de pagina nao troca de rota, entao a rolagem nao volta sozinha.
  document.querySelectorAll(".vp-paginas a").forEach((link) => {
    link.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "instant" }));
  });
}

function bindListaDeJogadores() {
  bindResultadoDosJogadores();
  document.querySelector("[data-jogador-atual]")?.addEventListener("change", (event) => {
    state.playerComEquipe = event.currentTarget.checked;
    pushFilterState("players", playerFiltersToQuery(), "[data-jogador-atual]");
  });
  document.querySelector("[data-jogador-limpar]")?.addEventListener("click", () => {
    state.playerQuery = "";
    state.playerTeam = "all";
    state.playerComEquipe = false;
    pushFilterState("players", playerFiltersToQuery());
  });
}

function playerTeamDropdown() {
  return `
    <details class="filter-dropdown player-team-dropdown">
      <summary>${filterIcon()}<span>Equipe</span><strong>${playerTeamFilterSummary()}</strong>${chevronIcon()}</summary>
      <div class="filter-dropdown-body">
        <div class="filter-option-stack player-team-options">
          <input id="player-team-query" class="filter-control team-filter-search" type="search" placeholder="Buscar equipe" aria-label="Buscar equipe" autocomplete="off" />
          <div class="player-team-lista" data-player-team-options>${playerTeamOptionsHtml()}</div>
        </div>
      </div>
    </details>
  `;
}

function playerTeamOptionsHtml(busca = "") {
  const query = normalize(busca);
  const teams = sortedTeamsByName(state.db.teams)
    .filter((team) => !query || normalize(`${team.name} ${team.sourceTag || team.tag} ${team.org || ""}`).includes(query));
  if (!query) return [null, ...teams].map(playerTeamOptionButton).join("");
  return teams.length ? teams.map(playerTeamOptionButton).join("") : `<div class="empty-state compact-empty">Nenhuma equipe encontrada.</div>`;
}

function playerTeamFilterSummary() {
  if (state.playerTeam === "all") return "Todos os times";
  const team = teamById(state.playerTeam);
  return escapeHtml(team?.name || "Equipe");
}

function playerTeamOptionButton(team) {
  const value = team?.id || "all";
  const active = state.playerTeam === value;
  const label = team?.name || "Todos os times";
  const visual = team ? teamLogo(team.id, "tiny") : `<span class="team-logo clean-logo tiny logo-empty" aria-hidden="true"></span>`;
  return `
    <button type="button" class="team-filter-button player-team-option ${active ? "active" : ""}" data-player-team-filter="${escapeHtml(value)}" aria-pressed="${active ? "true" : "false"}">
      <span class="filter-check" aria-hidden="true"></span>${visual}<strong>${escapeHtml(label)}</strong>
    </button>
  `;
}

function sortedTeamsByName(teams) {
  return teams.slice().sort((a, b) => String(a.name || a.tag || a.id || "").localeCompare(String(b.name || b.tag || b.id || ""), "pt-BR", { numeric: true, sensitivity: "base" }));
}


// Glossario unico das metricas. Serve a pagina /stats e as dicas dos
// cabecalhos do placar, para a definicao nao divergir entre os dois lugares.
// Conferido em raating-core.js e no agregador do app.js.
const METRIC_GLOSSARY = [
  {
    key: "rating",
    term: "rAAting 3.0",
    short: "Nota geral do jogador. 1.00 é o desempenho mediano do cenário.",
    long: "Nota geral do jogador no cenário universitário. 1.00 é o desempenho mediano: metade dos jogadores fica acima, metade abaixo. Cada 0,28 acima ou abaixo equivale a um intervalo interquartil de distância dessa mediana, e a escala é travada entre 0,30 e 1,80.",
  },
  { key: "acs", term: "ACS", short: "Pontuação de combate da partida dividida pelos rounds jogados.", long: "Average Combat Score: a pontuação de combate registrada na partida, dividida pelos rounds jogados." },
  { key: "adr", term: "ADR", short: "Dano causado por round jogado.", long: "Average Damage per Round: dano total causado dividido pelos rounds jogados." },
  { key: "kast", term: "KAST", short: "Percentual de rounds com abate, assistência, sobrevivência em round vencido ou morte trocada.", long: "Percentual de rounds em que o jogador teve pelo menos uma destas: abate, assistência, morte trocada pelo time, ou sobreviveu a um round vencido. Sobreviver a um round perdido (o \u0022save\u0022) não conta aqui." },
  { key: "kd", term: "K/D", short: "Abates divididos por mortes.", long: "Abates divididos por mortes." },
  { key: "kpr", term: "KPR", short: "Abates por round jogado.", long: "Abates por round jogado." },
  { key: "dpr", term: "DPR", short: "Mortes por round jogado. Aqui, menor é melhor.", long: "Mortes por round jogado. É a única métrica desta lista em que um número menor é melhor." },
  { key: "apr", term: "APR", short: "Assistências por round jogado.", long: "Assistências por round jogado." },
  { key: "swing", term: "Swing/R", short: "Quanto o jogador move a chance de vitória do round, em pontos percentuais.", long: "Round Swing por round: quanto as ações do jogador movem a probabilidade de o time vencer o round, medido em pontos percentuais. É zero-sum entre os dois times, então o que um ganha o outro perde." },
  { key: "hs", term: "HS%", short: "Percentual de acertos na cabeça.", long: "Percentual dos acertos que foram na cabeça." },
  { key: "fk", term: "FK", short: "First Kill: primeiro abate do round.", long: "First Kill: quantas vezes o jogador abriu o round com o primeiro abate." },
  { key: "fd", term: "FD", short: "First Death: primeira morte do round.", long: "First Death: quantas vezes o jogador foi o primeiro a cair no round." },
  { key: "fkfd", term: "FK-FD", short: "Saldo entre primeiros abates e primeiras mortes.", long: "Saldo de abertura: primeiros abates menos primeiras mortes. Positivo significa que o jogador abriu mais rounds do que perdeu." },
  { key: "fkpr", term: "FKPR", short: "Primeiros abates por round.", long: "First Kills por round jogado." },
  { key: "fdpr", term: "FDPR", short: "Primeiras mortes por round.", long: "First Deaths por round jogado." },
  { key: "mks", term: "MKs", short: "Rounds com mais de um abate.", long: "Quantidade de rounds em que o jogador conseguiu mais de um abate." },
  { key: "plusminus", term: "+/-", short: "Abates menos mortes.", long: "Saldo simples: abates menos mortes." },
  { key: "kdd", term: "K:D", short: "Abates divididos por mortes.", long: "Abates divididos por mortes." },
  { key: "mk", term: "MK/R", short: "Multi-kills por round.", long: "Rounds com mais de um abate, ponderados pelo tamanho do multi-kill e divididos pelos rounds jogados." },
];

const METRIC_GLOSSARY_BY_TERM = new Map(METRIC_GLOSSARY.map((item) => [item.term, item]));

function metricHint(label) {
  return METRIC_GLOSSARY_BY_TERM.get(label)?.short || "";
}

function avg(values) {
  const filtered = values.filter((value) => Number.isFinite(value));
  return filtered.length ? filtered.reduce((sum, value) => sum + value, 0) / filtered.length : 0;
}

function renderRankingPage(teamId = route().id || "") {
  const routeTeamId = rankingRouteTeamId(teamId);
  if (routeTeamId) ensureRankingScopeIncludesTeam(routeTeamId);
  const scope = state.rankingScope === "all" ? "all" : "valid";
  const rows = rankingRowsForScope(state.db.teams, scope);
  const snapshot = selectedRankingSnapshot();
  const aba = rankingRouteTab();
  const semanaMatches = rankingWeekMatches(snapshot);
  Shell(`
    <section class="vp-ranking${state.rankingResumo ? " com-resumo" : ""}">
      <div class="vp-lista-pagina ranking-full-panel">
        <header class="vp-sec">
          <h1>Ranking</h1>
          <span class="lista-contagem" data-ranking-count>${escapeHtml(aba === "partidas" ? rankingWeekMatchesSummary(semanaMatches, snapshot) : rankingScopeSummary(scope))}</span>
        </header>
        <div class="ranking-page-toolbar">
          <div class="ranking-toolbar-context">
            <label class="ranking-version-picker">
              <span>Semana</span>
              <select data-ranking-version aria-label="Semana do ranking">
                ${rankingVersionOptions(snapshot)}
              </select>
            </label>
          </div>
          ${rankingTabSwitch(aba, semanaMatches.length)}
          <label class="ranking-details-toggle ranking-resumo-botao">
            <input type="checkbox" data-ranking-resumo ${state.rankingResumo ? "checked" : ""} />
            <span>Resumo da semana</span>
          </label>
          ${aba === "partidas" ? "" : `<div class="ranking-toolbar-actions"><div class="ranking-toolbar-actions-inner">
            <label class="ranking-details-toggle">
              <input type="checkbox" data-ranking-score-details ${state.rankingShowDetails ? "checked" : ""} />
              <span>Detalhes da nota</span>
            </label>
            <div class="ranking-scope-switch" data-scope="${scope}" role="group" aria-label="Equipes do ranking">
              <button type="button" data-ranking-scope="valid" aria-pressed="${scope === "valid"}" class="${scope === "valid" ? "active" : ""}">Válidas</button>
              <button type="button" data-ranking-scope="all" aria-pressed="${scope === "all"}" class="${scope === "all" ? "active" : ""}">Todas</button>
            </div>
          </div></div>`}
        </div>
        ${aba === "partidas" ? rankingWeekMatchesSection(semanaMatches) : rankingAccordion(rows, scope, state.rankingShowDetails)}
      </div>
      <aside class="vp-resumo" data-ranking-trilho aria-label="Resumo do ranking">
        ${trilhoDoRanking(snapshot, rankingLider(snapshot))}
      </aside>
    </section>
  `);
  bindRankingVersionPicker();
  bindRankingTabSwitch();
  bindTrilhoDoRanking();
  bindResumoDoRanking();
  if (state.rankingListaEntra) {
    document.querySelector(".ranking-accordion, .ranking-week-matches")?.classList.add(state.rankingListaEntra);
    state.rankingListaEntra = "";
  }
  if (aba === "partidas") {
    bindResultDayToggles();
    return;
  }
  animarEntradaDasAcoes();
  bindRankingScopeToggle();
  bindRankingScoreDetailsToggle();
  bindRankingSortHeaders();
  bindRankingAccordion();
  openRankingRouteTeam(routeTeamId);
}

// A aba viaja na query, como todo filtro deste site: trocar de aba nao e mudar
// de pagina, entao o Back desfaz um passo e a rolagem nao pula para o topo.
// Trocar de aba re-renderiza a pagina inteira, entao o grupo da direita nasce
// ja ausente e nao teria como animar a saida - o elemento que deveria encolher
// nem existe mais quando o novo DOM chega. A saida acontece ANTES do
// pushFilterState: anima, espera, e so entao troca a rota. Na volta e o
// contrario - a rota troca na hora e a animacao de entrada roda no elemento
// recem-criado, marcado por rankingAnimarEntrada.
const RANKING_ABA_MS = 220;

function bindRankingTabSwitch() {
  document.querySelectorAll("[data-ranking-tab]").forEach((button) => {
    button.addEventListener("click", () => {
      const params = routeQuery();
      const lista = document.querySelector(".ranking-accordion, .ranking-week-matches");
      if (button.dataset.rankingTab !== "partidas") {
        params.delete("aba");
        state.rankingAnimarEntrada = true;
        state.rankingListaEntra = "vp-entra-esquerda";
        lista?.classList.remove("vp-entra-direita");
        lista?.classList.add("vp-sai-direita");
        window.setTimeout(() => pushFilterState("ranking", params), RANKING_ABA_MS);
        return;
      }
      params.set("aba", "partidas");
      state.rankingListaEntra = "vp-entra-direita";
      lista?.classList.remove("vp-entra-esquerda");
      lista?.classList.add("vp-sai-esquerda");
      const acoes = document.querySelector(".ranking-toolbar-actions");
      if (acoes) fecharAcoesDoRanking(acoes);
      // setTimeout e nao transitionend: em aba oculta o compositor nao avanca a
      // transicao e o evento nunca chega - a troca de aba ficaria presa.
      window.setTimeout(() => pushFilterState("ranking", params), RANKING_ABA_MS);
    });
  });
}

// A largura anima em pixel e nao em `fr`. Medido antes de trocar: numa grade de
// uma coluna indo de 1fr a 0fr, metade do caminho do `fr` ja era 5% da largura
// em pixel - o bloco sumia num salto e arrastava um rastro. Em pixel a curva
// vale o que promete, e a largura de partida e medida, nao chutada.
// No desktop a barra e uma linha e o bloco sai encolhendo para a direita; no
// celular ela empilha e o bloco e uma faixa larga - encolher a largura ali
// espremeria os controles em vez de recolhe-los. O eixo sai do proprio layout.
function eixoDasAcoes(acoes) {
  const barra = acoes.closest(".ranking-page-toolbar");
  if (!barra) return "width";
  // Empilhado, o bloco ocupa a barra inteira - encolher a largura ali
  // espremeria os controles em vez de recolhe-los. A comparacao sai do layout
  // e nao de um breakpoint repetido aqui.
  return acoes.offsetWidth >= barra.clientWidth - 1 ? "height" : "width";
}

function fecharAcoesDoRanking(acoes) {
  const eixo = eixoDasAcoes(acoes);
  acoes.style[eixo] = `${eixo === "height" ? acoes.offsetHeight : acoes.offsetWidth}px`;
  void acoes.offsetWidth; // forca o reflow para haver de onde interpolar
  acoes.style[eixo] = "0px";
  acoes.classList.add("oculto");
}

// Anima a volta do grupo da direita. O elemento acaba de nascer com a largura
// natural, entao ela e medida primeiro, o bloco vai a zero e so no quadro
// seguinte volta - sem os dois quadros o navegador nao tem de onde interpolar.
function animarEntradaDasAcoes() {
  if (!state.rankingAnimarEntrada) return;
  state.rankingAnimarEntrada = false;
  const acoes = document.querySelector(".ranking-toolbar-actions");
  if (!acoes) return;
  const eixo = eixoDasAcoes(acoes);
  const medida = eixo === "height" ? acoes.offsetHeight : acoes.offsetWidth;
  acoes.style[eixo] = "0px";
  acoes.classList.add("oculto");
  // Reflow sincrono em vez de requestAnimationFrame: em aba de fundo o rAF nao
  // dispara, e como o estado inicial aqui e "escondido", o callback que nunca
  // roda deixaria os controles invisiveis para sempre. Lendo offsetWidth o
  // navegador ja tem de onde interpolar, e se a transicao nao rodar o bloco
  // simplesmente aparece na hora - falha para o lado visivel.
  void acoes.offsetWidth;
  acoes.style[eixo] = `${medida}px`;
  acoes.classList.remove("oculto");
  // Solta a medida fixa no fim: presa em pixel, o bloco pararia de responder a
  // redimensionamento de janela.
  window.setTimeout(() => {
    acoes.style[eixo] = "";
  }, RANKING_ABA_MS);
}

function rankingRouteTeamId(teamId) {
  const value = String(teamId || "").trim();
  return value && teamById(value) ? value : "";
}

function ensureRankingScopeIncludesTeam(teamId) {
  const ranking = selectedRankingSnapshot()?.byTeamId?.[teamId] || teamById(teamId)?.ranking;
  if (ranking && !rankingIsValid(ranking)) state.rankingScope = "all";
}

function rankingRowsForScope(teams, scope) {
  const snapshot = selectedRankingSnapshot();
  const rows = (snapshot?.teams || [])
    .map((ranking) => ({ team: teamById(ranking.id), ranking, snapshot }))
    .filter((row) => row.team && rankingRowExistsInSnapshot(row.ranking));
  const sorted = scope === "all"
    ? rows.slice().sort((a, b) => (a.ranking.overallRank || 9999) - (b.ranking.overallRank || 9999) || b.ranking.score - a.ranking.score || a.team.name.localeCompare(b.team.name))
    : rows.filter((row) => rankingIsValid(row.ranking)).sort((a, b) => (a.ranking.validRank || 9999) - (b.ranking.validRank || 9999) || b.ranking.score - a.ranking.score || a.team.name.localeCompare(b.team.name));
  return applyRankingSort(sorted.map((row, index) => ({ ...row, displayRank: index + 1, defaultIndex: index })));
}

function rankingRowExistsInSnapshot(ranking) {
  const matches = Number(ranking?.matches || 0);
  if (!Number.isFinite(matches) || matches <= 0) return false;
  // Equipe inativa nao aparece nem em "Todas": esse escopo so soma as provisorias.
  if (rankingIsInactive(ranking)) return false;
  return true;
}

function rankingExistingSnapshotTeams(snapshot = selectedRankingSnapshot()) {
  return (snapshot?.teams || []).filter(rankingRowExistsInSnapshot);
}

function latestRankingSnapshot() {
  return state.db?.rankingSnapshots?.[0] || null;
}

function selectedRankingSnapshot() {
  const snapshots = state.db?.rankingSnapshots || [];
  if (!snapshots.length) return null;
  const selected = snapshots.find((snapshot) => snapshot.id === state.rankingVersionId);
  return selected || snapshots[0];
}

function previousRankingSnapshot(snapshot = selectedRankingSnapshot()) {
  const snapshots = state.db?.rankingSnapshots || [];
  const cutoffAt = Number(snapshot?.cutoffAt || 0);
  if (!cutoffAt) return null;
  return snapshots
    .filter((item) => Number(item.cutoffAt || 0) < cutoffAt)
    .sort((a, b) => Number(b.cutoffAt || 0) - Number(a.cutoffAt || 0))[0] || null;
}

function applyRankingSort(rows) {
  const sort = state.rankingSort || {};
  if (!sort.key || sort.direction === "default") return rows;
  const direction = sort.direction === "asc" ? "asc" : "desc";
  return rows.slice().sort((a, b) => {
    const compared = compareRankingSortValues(rankingSortValue(a, sort.key), rankingSortValue(b, sort.key));
    if (compared !== 0) return direction === "desc" ? -compared : compared;
    return a.defaultIndex - b.defaultIndex;
  });
}

function rankingSortValue(row, key) {
  const team = row.team;
  const ranking = row.ranking || team.ranking || {};
  const blocks = ranking.blocks || {};
  const values = {
    rank: row.displayRank,
    team: team.name || team.sourceTag || team.id || "",
    score: ranking.score ?? team.rankingScore ?? team.points,
    competitive: blocks.competitive,
    achievements: blocks.achievements,
    recentForm: blocks.recentForm,
    rosterStrength: blocks.rosterStrength,
    status: rankingStatusLabel(ranking),
  };
  return values[key] ?? "";
}

function compareRankingSortValues(a, b) {
  const numericA = Number(a);
  const numericB = Number(b);
  if (Number.isFinite(numericA) && Number.isFinite(numericB)) return numericA - numericB;
  return String(a || "").localeCompare(String(b || ""), "pt-BR", { sensitivity: "base", numeric: true });
}

function rankingCanonicalPosition(ranking) {
  const rank = Number(ranking?.canonicalRank ?? ranking?.validRank);
  return Number.isFinite(rank) && rank > 0 ? rank : null;
}

function rankingPositionChange(row) {
  const team = row.team || row;
  const snapshot = row.snapshot || latestRankingSnapshot();
  const ranking = row.ranking || snapshot?.byTeamId?.[team.id] || team.ranking || {};
  const currentRank = rankingCanonicalPosition(ranking);
  if (!currentRank) {
    return { label: "-", className: "muted", title: "Equipe ainda não entrou no ranking válido." };
  }

  const previousSnapshot = previousRankingSnapshot(snapshot);
  if (!previousSnapshot) {
    return { label: "-", className: "muted", title: "Sem semana anterior para comparação." };
  }

  const previousRank = rankingCanonicalPosition(previousSnapshot.byTeamId?.[team.id]);
  if (!previousRank) {
    return { label: "NOVO", className: "new", title: "Entrou no ranking válido nesta semana." };
  }

  const delta = previousRank - currentRank;
  if (delta > 0) {
    return { label: `+${delta}`, className: "up", title: `Subiu ${delta} ${delta > 1 ? "posições" : "posição"} desde a semana passada.` };
  }
  if (delta < 0) {
    const amount = Math.abs(delta);
    return { label: String(delta), className: "down", title: `Caiu ${amount} ${amount > 1 ? "posições" : "posição"} desde a semana passada.` };
  }
  return { label: "-", className: "even", title: "Manteve a posição da semana passada." };
}

function rankingPositionChangeLabel(row) {
  return rankingPositionChangeBadge(row, "rank-change-cell");
}

function rankingPositionChangeBadge(row, baseClass = "rank-change-cell") {
  const change = rankingPositionChange(row);
  return `<span class="${escapeHtml(`${baseClass} ${change.className}`)}" title="${escapeHtml(change.title)}">${escapeHtml(change.label)}</span>`;
}

function rankingScopeSummary(scope) {
  const snapshot = selectedRankingSnapshot();
  const snapshotTeams = rankingExistingSnapshotTeams(snapshot);
  const total = snapshotTeams.length || state.db.teams.filter((team) => Number(team.matches || 0) > 0).length;
  const validCount = snapshotTeams.length ? snapshotTeams.filter(rankingIsValid).length : state.db.teams.filter((team) => Number(team.matches || 0) > 0 && teamIsRankingValid(team)).length;
  const minimumMatches = state.db.rankingMinimumMatches || 9;
  // Devolvia "" no escopo "Apenas válidos", que e o padrao da pagina: o slot da
  // esquerda da barra nascia vazio e os 721px de controle ficavam sozinhos
  // contra 617px de vao. O texto e o contrapeso, e ele tem informacao real.
  if (scope === "all") return `${total} equipes, ${validCount} válidas, mínimo de ${minimumMatches} partidas`;
  return `${validCount} equipes válidas, mínimo de ${minimumMatches} partidas`;
}

// "25 Agosto 2026" e "25 ago 2026". formatDate() devolveria "25 de agosto de
// 2026" - os dois "de" so alongam. formatToParts monta dia, mes e ano soltos.
function formatShortDate(value, mes = "short") {
  // `new Date(null)` nao e invalido: e a epoca, e voltava "31 dez 1969" para
  // campo de data vazio. NaN sozinho nao cobre isso.
  if (value === null || value === undefined || value === "") return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const partes = new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: mes, year: "numeric" })
    .formatToParts(date)
    .filter((parte) => ["day", "month", "year"].includes(parte.type))
    .map((parte) => parte.value.replace(".", ""));
  if (mes === "long" && partes[1]) partes[1] = partes[1].charAt(0).toUpperCase() + partes[1].slice(1);
  return partes.join(" ");
}

// O `label` que vem no snapshot diz "Semana de 25 de ago de 2026". Sobra a data
// de corte, que e o que identifica a versao do ranking.
function rankingVersionLabel(snapshot) {
  const fim = Number(snapshot?.cutoffAt || 0);
  if (!fim) return snapshot?.label || "";
  return formatShortDate(fim, "long");
}

// A janela que a versao cobre: do corte anterior ate o corte desta. Sem
// anterior (a semana mais antiga da lista), sete dias antes.
function rankingWeekWindow(snapshot = selectedRankingSnapshot()) {
  const fim = Number(snapshot?.cutoffAt || 0);
  if (!fim) return null;
  const anterior = previousRankingSnapshot(snapshot);
  return { inicio: Number(anterior?.cutoffAt || 0) || fim - 7 * DAY_MS, fim };
}

// As partidas que entraram nesta versao do ranking: as que aconteceram dentro
// da janela. E o mesmo recorte que /partidas faria filtrando por data.
function rankingWeekMatches(snapshot = selectedRankingSnapshot()) {
  const janela = rankingWeekWindow(snapshot);
  if (!janela) return [];
  return allMatchSeries()
    .filter((series) => {
      const at = Number(series.startedAt || 0);
      return at > janela.inicio && at <= janela.fim;
    })
    .sort(compareSeriesDateDesc);
}

function rankingRouteTab() {
  return routeQuery().get("aba") === "partidas" ? "partidas" : "ranking";
}

function rankingVersionOptions(selectedSnapshot) {
  const snapshots = state.db?.rankingSnapshots || [];
  return snapshots
    .map((snapshot) => `<option value="${escapeHtml(snapshot.id)}" ${snapshot.id === selectedSnapshot?.id ? "selected" : ""}>${escapeHtml(rankingVersionLabel(snapshot))}</option>`)
    .join("");
}

// O meio da barra e a porta para a segunda aba: as partidas que entraram nesta
// versao do ranking. Sem partidas na janela o botao continua la, desabilitado -
// "nenhuma" tambem e resposta, e sumir com o botao mexeria no equilibrio da
// barra a cada troca de semana.
function rankingTabSwitch(aba, total) {
  if (aba === "partidas") {
    return `<button class="ranking-tab-switch" type="button" data-ranking-tab="ranking">Voltar ao ranking</button>`;
  }
  return `<button class="ranking-tab-switch" type="button" data-ranking-tab="partidas" ${total ? "" : "disabled"}>${rotuloDasNovasPartidas(total)}</button>`;
}

function rotuloDasNovasPartidas(total) {
  if (!total) return "Nenhuma partida nova nesta semana";
  return `<span>Ver ${total} ${total > 1 ? "novas partidas" : "nova partida"}</span>${chevronIcon()}`;
}

// Reusa a lista de /partidas inteira em vez de montar uma parecida:
// listaDeResultados ja agrupa por dia com contagem no cabecalho e passa
// { when: "hour" } para a linha mostrar so o horario. A classe
// `full-list-panel` nao e decoracao - sao 17 regras no styles.css penduradas
// nela que ligam a arte do mapa, a coluna de meta e o logo do campeonato, com
// variantes responsivas. Copiar isso a mao seria manter duas verdades.
function rankingWeekMatchesSection(matches) {
  if (!matches.length) {
    return `<div class="empty-state">Nenhuma partida entrou nesta versão do ranking.</div>`;
  }
  const params = routeQuery();
  params.set("aba", "partidas");
  const limite = limiteDaLista(routeQuery());
  const mostrando = Math.min(limite, matches.length);
  return `
    <div class="full-list-panel ranking-week-matches">
      <div class="result-list">${listaDeResultados(matches, limite)}</div>
      ${verMaisBotao("ranking", mostrando, matches.length, params)}
    </div>
  `;
}

// O trilho e opcional: por padrao a lista fica sozinha, centralizada, e "Resumo da
// semana" abre o trilho no lugar em que ele esta na home e em #/matches. Cartao
// Camisa e trajetoria falam da mesma equipe: a lider da semana, ou a aberta na
// lista. Os destaques sao da semana inteira.
// Na primeira montagem da pagina o DOM ainda e o da tela anterior: quem chama
// passa a lider, e a equipe da rota entra depois por openRankingRouteTeam.
function trilhoDoRanking(snapshot = selectedRankingSnapshot(), foco = equipeEmFoco(snapshot)) {
  return `
    <div class="vp-ranking-cartao" data-ranking-cartao>${cartaoDoRanking(foco)}</div>
    ${trajetoriaDaEquipe(foco)}
    ${destaquesDaSemana(snapshot)}
    ${comoANotaEFeita()}
  `;
}

function equipeEmFoco(snapshot = selectedRankingSnapshot()) {
  const aberta = document.querySelector(".ranking-accordion-item.open")?.dataset.rankingTeamId;
  const ranking = aberta ? snapshot?.byTeamId?.[aberta] : null;
  const team = ranking ? teamById(aberta) : null;
  return team ? { team, ranking, snapshot } : rankingLider(snapshot);
}

function rankingPorPosicao(snapshot) {
  return rankingExistingSnapshotTeams(snapshot)
    .filter((ranking) => rankingCanonicalPosition(ranking))
    .sort((a, b) => rankingCanonicalPosition(a) - rankingCanonicalPosition(b));
}

function rankingLider(snapshot) {
  const ranking = rankingPorPosicao(snapshot)[0];
  const team = ranking ? teamById(ranking.id) : null;
  return team && rankingCanonicalPosition(ranking) === 1 ? { team, ranking, snapshot } : null;
}

function semanasDoRanking() {
  return (state.db?.rankingSnapshots || []).slice().sort((a, b) => Number(a.cutoffAt || 0) - Number(b.cutoffAt || 0));
}

// Semanas seguidas na lideranca, contadas para tras a partir da semana escolhida.
function semanasNaLideranca(snapshot, teamId) {
  const semanas = semanasDoRanking();
  let indice = semanas.findIndex((semana) => semana.id === snapshot?.id);
  let total = 0;
  while (indice >= 0 && rankingPorPosicao(semanas[indice])[0]?.id === teamId) {
    total += 1;
    indice -= 1;
  }
  return total;
}

function movimentoDaEquipe(row) {
  const mudanca = rankingPositionChange(row);
  const quantas = Math.abs(Number(mudanca.label)) || 0;
  const posicoes = `${quantas} ${quantas === 1 ? "posição" : "posições"}`;
  if (mudanca.className === "up") return `Subiu ${posicoes}`;
  if (mudanca.className === "down") return `Caiu ${posicoes}`;
  if (mudanca.className === "new") return "Entrou nesta semana";
  return mudanca.className === "even" ? "Manteve a posição" : "";
}

function cartaoDoRanking(row) {
  if (!row) return "";
  const { team, ranking, snapshot } = row;
  const posicao = rankingCanonicalPosition(ranking);
  const semanas = posicao === 1 ? semanasNaLideranca(snapshot, team.id) : 0;
  const nota = fmt(ranking.score ?? team.rankingScore ?? team.points, 1);
  const logo = assetPath(team.profile?.logo || team.logo || "");
  const partidas = Number.isFinite(Number(ranking.matches)) ? Number(ranking.matches) : team.matches;
  const rotulo = posicao === 1 ? "Líder do ranking" : posicao ? `${posicao}º no ranking` : rankingStatusLabel(ranking);
  return plateCard({
    classe: `vp-slide vp-camisa-equipe${nota.length > 4 ? " vp-valor-longo" : ""}`,
    team,
    href: `#/teams/${encodeURIComponent(team.id)}`,
    nome: team.sourceTag || team.tag || team.name,
    figura: logo ? `<span class="vp-camisa-logo"><img src="${escapeHtml(logo)}" alt="" onerror="this.parentElement.remove()" /></span>` : "",
    rotulo,
    tag: semanas > 1 ? `há ${semanas} semanas` : semanas ? "Nova líder" : movimentoDaEquipe(row),
    valor: nota,
    apoio: `${partidas} partidas`,
    atributos: ` aria-label="${escapeHtml(`${team.name}: ${rotulo}, nota ${nota}`)}"`,
  });
}

// Cartao e trajetoria trocam juntos quando uma equipe abre ou fecha na lista.
function trocarCartaoDoRanking() {
  const lugar = document.querySelector("[data-ranking-cartao]");
  if (!lugar) return;
  const foco = equipeEmFoco();
  lugar.innerHTML = cartaoDoRanking(foco);
  ajustarTextosVariaveis(lugar);
  const grafico = document.querySelector("[data-ranking-trajetoria]");
  if (grafico) grafico.outerHTML = trajetoriaDaEquipe(foco);
  const trilho = document.querySelector("[data-ranking-trilho]");
  trilho?.style.setProperty("--resumo-altura", `${trilho.scrollHeight}px`);
}

// Doze semanas da equipe em foco, ate a escolhida e duas alem dela, para dar para
// andar nos dois sentidos clicando no proprio grafico. A escala e a da propria
// equipe, do melhor ao pior lugar dela na janela, com folga de uma posicao em
// cada ponta e no minimo 4 de altura: sem o minimo, quem oscila entre 30 e 31
// pareceria subir e descer o grafico inteiro.
const RANKING_GRAFICO_SEMANAS = 12;
const RANKING_GRAFICO_ALTURA_MINIMA = 4;

function escalaDaTrajetoria(posicoes) {
  const validas = posicoes.filter(Boolean);
  const melhor = Math.min(...validas);
  const pior = Math.max(...validas);
  const topo = Math.max(1, melhor - 1);
  const base = Math.max(pior + 1, topo + RANKING_GRAFICO_ALTURA_MINIMA);
  return { melhor, pior, y: (posicao) => 6 + ((posicao - topo) / (base - topo)) * 88 };
}

function curvaDaEquipe(posicoes, y) {
  const passo = 100 / (posicoes.length - 1);
  let caminho = "";
  posicoes.forEach((posicao, i) => {
    if (!posicao) return;
    const x = i * passo;
    const antes = posicoes[i - 1];
    if (!antes) {
      caminho += `M${x.toFixed(2)} ${y(posicao).toFixed(2)}`;
      return;
    }
    const meio = (x - passo / 2).toFixed(2);
    caminho += `C${meio} ${y(antes).toFixed(2)} ${meio} ${y(posicao).toFixed(2)} ${x.toFixed(2)} ${y(posicao).toFixed(2)}`;
  });
  return caminho;
}

function leituraDaSemana(semana, posicao) {
  return `${posicao ? `${posicao}º` : "Fora da lista"} em ${formatShortDate(semana.cutoffAt)}`;
}

function trajetoriaDaEquipe(foco) {
  const snapshot = foco?.snapshot || selectedRankingSnapshot();
  const team = foco?.team;
  const semanas = semanasDoRanking();
  const indice = semanas.findIndex((semana) => semana.id === snapshot?.id);
  const fim = Math.min(semanas.length - 1, indice + 2);
  const janela = indice < 0 ? [] : semanas.slice(Math.max(0, fim - RANKING_GRAFICO_SEMANAS + 1), fim + 1);
  const posicoes = team ? janela.map((semana) => rankingCanonicalPosition(semana.byTeamId?.[team.id])) : [];
  const titulo = team ? `Trajetória da ${team.sourceTag || team.tag || team.name}` : "Trajetória";
  if (!team || janela.length < 2 || posicoes.filter(Boolean).length < 2) {
    const aviso = team ? `${team.name} ainda não tem duas semanas na lista.` : "Nenhuma equipe na lista nesta semana.";
    return `
      <section class="vp-resumo-bloco vp-bump-bloco" data-ranking-trajetoria aria-label="Trajetória no ranking">
        <h3>${escapeHtml(titulo)}</h3>
        <p class="vp-nota-regras">${escapeHtml(aviso)}</p>
      </section>
    `;
  }
  const passo = 100 / (janela.length - 1);
  const { melhor, pior, y } = escalaDaTrajetoria(posicoes);
  const atual = janela.indexOf(snapshot);
  const leitura = leituraDaSemana(snapshot, posicoes[atual]);
  const marcas = melhor === pior ? [melhor] : [melhor, pior];
  return `
    <section class="vp-resumo-bloco vp-bump-bloco" data-ranking-trajetoria aria-label="${escapeHtml(`${titulo}, ${leitura}`)}" style="--team-line:${escapeHtml(teamLineColor(team.id))}">
      <h3>${escapeHtml(titulo)} <span data-ranking-leitura data-padrao="${escapeHtml(leitura)}">${escapeHtml(leitura)}</span></h3>
      <div class="vp-bump-placa">
        <div class="vp-bump" data-ranking-grafico>
          ${marcas.map((posicao) => `<span class="vp-bump-pos" style="top:${y(posicao).toFixed(2)}%">${posicao}º</span><i class="vp-bump-guia" style="top:${y(posicao).toFixed(2)}%"></i>`).join("")}
          <i class="vp-bump-marca" style="left:${(atual * passo).toFixed(2)}%"></i>
          <svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">
            <path d="${curvaDaEquipe(posicoes, y)}" />
          </svg>
          ${posicoes[atual] ? `<i class="vp-bump-ponto" style="left:${(atual * passo).toFixed(2)}%;top:${y(posicoes[atual]).toFixed(2)}%"></i>` : ""}
          <div class="vp-bump-semanas" style="left:${(-passo / 2).toFixed(2)}%;right:${(-passo / 2).toFixed(2)}%">
            ${janela
              .map((semana, i) => {
                const rotulo = leituraDaSemana(semana, posicoes[i]);
                return `<button type="button" data-ranking-semana="${escapeHtml(semana.id)}" data-rotulo="${escapeHtml(rotulo)}" aria-label="${escapeHtml(`${rotulo}. Ver o ranking dessa semana`)}" aria-pressed="${semana === snapshot}"></button>`;
              })
              .join("")}
          </div>
        </div>
      </div>
      <div class="vp-rt-eixo"><span>${escapeHtml(formatShortDate(janela[0].cutoffAt))}</span><span>${escapeHtml(formatShortDate(janela[janela.length - 1].cutoffAt))}</span></div>
    </section>
  `;
}

// Quem mais subiu e quem mais caiu na semana: nome, variacao e posicao, sem
// frase de explicacao (pedido do dono em 07/11).
function destaquesDaSemana(snapshot) {
  const anterior = previousRankingSnapshot(snapshot);
  if (!anterior) return "";
  const linhas = rankingPorPosicao(snapshot)
    .map((ranking) => {
      const antes = rankingCanonicalPosition(anterior.byTeamId?.[ranking.id]);
      const agora = rankingCanonicalPosition(ranking);
      const team = teamById(ranking.id);
      return antes && team ? { team, agora, delta: antes - agora } : null;
    })
    .filter((linha) => linha?.delta);
  const subida = linhas.filter((linha) => linha.delta > 0).sort((a, b) => b.delta - a.delta || a.agora - b.agora)[0];
  const queda = linhas.filter((linha) => linha.delta < 0).sort((a, b) => a.delta - b.delta || a.agora - b.agora)[0];
  const itens = [subida && destaqueDaSemana("Maior subida", subida), queda && destaqueDaSemana("Maior queda", queda)].filter(Boolean);
  return `
    <section class="vp-resumo-bloco vp-movimentos vp-destaques" aria-label="Destaques da semana">
      <h3>Destaques da semana</h3>
      ${itens.length ? `<div class="vp-destaques-placa">${itens.join("")}</div>` : `<p class="vp-nota-regras">Nenhuma equipe mudou de posição nesta semana.</p>`}
    </section>
  `;
}

function destaqueDaSemana(rotulo, { team, agora, delta }) {
  return `
    <a class="vp-destaque pintura-de-equipe" href="#/ranking/${escapeHtml(team.id)}" ${teamAccentStyle(team)}>
      <small>${escapeHtml(rotulo)}</small>
      ${teamLogo(team.id)}
      <strong title="${escapeHtml(team.name)}">${escapeHtml(team.name)}</strong>
      <span class="vp-destaque-posicao"><span class="vp-rk-delta ${delta > 0 ? "up" : "down"}">${delta > 0 ? `+${delta}` : delta}</span><b>${agora}º</b></span>
    </a>
  `;
}

// Cada categoria abre a propria explicacao, uma de cada vez. Botao e grade de
// 0fr a 1fr, como o painel da lista, e nao <details>: a abertura animada do
// details (interpolate-size) so existe no Chrome. Os numeros saem do
// ranking-weights.json, como a nota.
function comoANotaEFeita() {
  const pesos = state.db?.rankingWeights || {};
  const meiaVida = Number(pesos.halfLives?.matches) || 150;
  const janela = Number(pesos.recentWindowDays) || 60;
  const vida = Math.round((Number(pesos.achievements?.lifetimeDays) || 304) / 30.4);
  const categorias = [
    ["Desempenho", 70, `Vitórias, força dos adversários e margem de rounds. Um jogo perde metade do peso a cada ${meiaVida} dias.`],
    ["Conquistas", 15, `Pontos por colocação em campeonatos. Zeram em ${vida} meses.`],
    ["Forma recente", 10, `Desempenho nos últimos ${janela} dias.`],
    ["rAAting 3.0 dos jogadores", 5, "rAAting 3.0 dos jogadores da formação."],
  ];
  return `
    <section class="vp-resumo-bloco vp-nota-bloco" aria-label="Como a nota é feita">
      <h3>Como a nota é feita</h3>
      <div class="vp-rk-soma" style="--team-line:var(--ink)" aria-hidden="true">${categorias.map(([, peso]) => `<i style="--w:${peso}%"></i>`).join("")}</div>
      <div class="vp-nota-categorias">
        ${categorias.map(([nome, peso, texto], indice) => `
          <div class="vp-nota-categoria">
            <button type="button" data-nota-categoria aria-expanded="false" aria-controls="ranking-categoria-${indice}"><span>${escapeHtml(nome)}</span><b>${peso}%</b>${chevronIcon()}</button>
            <div class="vp-nota-explica" id="ranking-categoria-${indice}" inert><div><p>${escapeHtml(texto)}</p></div></div>
          </div>`).join("")}
      </div>
    </section>
  `;
}

function atualizarTrilhoDoRanking() {
  const trilho = document.querySelector("[data-ranking-trilho]");
  if (!trilho) return;
  const snapshot = selectedRankingSnapshot();
  trilho.innerHTML = trilhoDoRanking(snapshot);
  const seletor = document.querySelector("[data-ranking-version]");
  if (seletor && snapshot) seletor.value = snapshot.id;
  ajustarTextosVariaveis(trilho);
  trilho.style.setProperty("--resumo-altura", `${trilho.scrollHeight}px`);
}

// Troca so a classe, sem re-renderizar: a lista desliza enquanto o trilho abre. O
// estado fica em state, como a semana, o escopo e os detalhes desta pagina.
function bindResumoDoRanking() {
  document.querySelector("[data-ranking-resumo]")?.addEventListener("change", (event) => {
    state.rankingResumo = event.currentTarget.checked;
    document.querySelector(".vp-ranking")?.classList.toggle("com-resumo", state.rankingResumo);
    const trilho = document.querySelector("[data-ranking-trilho]");
    if (!state.rankingResumo || !trilho) return;
    ajustarTextosVariaveis(trilho);
    trilho.style.setProperty("--resumo-altura", `${trilho.scrollHeight}px`);
  });
}

function bindTrilhoDoRanking() {
  const pagina = document.querySelector(".vp-ranking");
  const trilho = pagina?.querySelector("[data-ranking-trilho]");
  if (!trilho) return;
  trilho.style.setProperty("--resumo-altura", `${trilho.scrollHeight}px`);
  // Uma categoria aberta por vez. Ela muda a altura do trilho, e o `top` do
  // sticky depende dela: a medida e a do fim da abertura.
  trilho.addEventListener("click", (event) => {
    const botao = event.target.closest("[data-nota-categoria]");
    if (!botao) return;
    const abrir = botao.getAttribute("aria-expanded") !== "true";
    trilho.querySelectorAll("[data-nota-categoria]").forEach((outro) => {
      const aberto = outro === botao && abrir;
      outro.setAttribute("aria-expanded", String(aberto));
      document.getElementById(outro.getAttribute("aria-controls"))?.toggleAttribute("inert", !aberto);
    });
    window.setTimeout(() => trilho.style.setProperty("--resumo-altura", `${trilho.scrollHeight}px`), RANKING_ABA_MS + 20);
  });
  // O timeout sozinho mediu no meio da abertura quando a pagina estava lenta
  // (998px contra 1082px reais): o fim da transicao confirma a medida.
  trilho.addEventListener("transitionend", (event) => {
    if (event.target.matches(".vp-nota-explica")) trilho.style.setProperty("--resumo-altura", `${trilho.scrollHeight}px`);
  });
  const mostrar = (texto) => {
    const leitura = trilho.querySelector("[data-ranking-leitura]");
    if (leitura) leitura.textContent = texto ?? leitura.dataset.padrao;
  };
  // Trocar a semana redesenha a lista fechada. A equipe que estava aberta volta
  // aberta, sem rolar: quem clica na trajetoria dela continua olhando para ela.
  trilho.addEventListener("click", (event) => {
    const semana = event.target.closest("[data-ranking-semana]");
    if (!semana) return;
    const id = semana.dataset.rankingSemana;
    const aberta = document.querySelector(".ranking-accordion-item.open")?.dataset.rankingTeamId;
    state.rankingVersionId = id;
    updateRankingVersionView();
    const item = aberta ? document.querySelector(`.ranking-accordion-item[data-ranking-team-id="${CSS.escape(aberta)}"]`) : null;
    if (item) {
      setRankingAccordionItem(item, true);
      trocarCartaoDoRanking();
    }
    document.querySelector(`[data-ranking-semana="${id}"]`)?.focus({ preventScroll: true });
  });
  ["mouseover", "focusin"].forEach((tipo) => {
    trilho.addEventListener(tipo, (event) => {
      const semana = event.target.closest("[data-ranking-semana]");
      if (semana) mostrar(semana.dataset.rotulo);
    });
  });
  ["mouseout", "focusout"].forEach((tipo) => {
    trilho.addEventListener(tipo, (event) => {
      if (event.target.closest("[data-ranking-semana]")) mostrar();
    });
  });
}

function rankingAccordion(rows, scope = "valid", showDetails = false) {
  return `
    <div class="ranking-accordion" data-ranking-accordion data-status-visible="${scope === "all"}" data-details-visible="${showDetails}">
      <div class="ranking-accordion-head">
        ${rankingSortHeader("rank", "#")}
        <span class="rank-change-head" aria-hidden="true"></span>
        ${rankingSortHeader("team", "Equipe")}
        ${rankingSortHeader("score", "Nota", "numeric ranking-score-head")}
        <span class="ranking-lineup-head optional">Lineup</span>
        ${rankingSortHeader("competitive", "Desempenho", "numeric optional ranking-detail-cell")}
        ${rankingSortHeader("achievements", "Conquistas", "numeric optional ranking-detail-cell")}
        ${rankingSortHeader("recentForm", "Forma", "numeric optional ranking-detail-cell")}
        ${rankingSortHeader("rosterStrength", "rAAting 3.0", "numeric optional ranking-detail-cell")}
        ${rankingSortHeader("status", "Status", "ranking-status-cell")}
        <span></span>
      </div>
      <div class="ranking-accordion-rows" data-ranking-rows>
        ${rankingAccordionRows(rows)}
      </div>
    </div>
  `;
}

function rankingSortHeader(key, label, extraClass = "") {
  const sort = state.rankingSort || {};
  const active = sort.key === key && sort.direction !== "default";
  const direction = active ? sort.direction : "default";
  const title = direction === "desc" ? "Ordenado decrescente" : direction === "asc" ? "Ordenado crescente" : "Ordenação padrão";
  return `
    <button class="ranking-sort-header ${extraClass} ${active ? "active" : ""}" type="button" data-ranking-sort="${escapeHtml(key)}" data-sort-direction="${direction}" aria-label="${escapeHtml(`${label}: ${title}`)}" title="${escapeHtml(title)}">
      <span>${escapeHtml(label)}</span>
      <i aria-hidden="true">${direction === "desc" ? "↓" : direction === "asc" ? "↑" : ""}</i>
    </button>
  `;
}

function rankingAccordionRows(rows) {
  return rows.length ? rows.map(rankingAccordionItem).join("") : `<div class="empty-state">Nenhuma equipe válida ainda. Mostre "Todas" para ver as equipes provisórias.</div>`;
}

function rankingAccordionItem(row) {
  const team = row.team || row;
  const ranking = row.ranking || team.ranking || {};
  const cutoffAt = row.snapshot?.cutoffAt || selectedRankingSnapshot()?.cutoffAt || Date.now();
  const displayRank = row.displayRank || teamValidRank(team) || teamOverallRank(team) || "-";
  const blocks = ranking.blocks || {};
  const matchesCount = Number.isFinite(Number(ranking.matches)) ? Number(ranking.matches) : team.matches;
  const panelId = `ranking-detail-${safeDomId(team.id)}`;
  return `
    <article class="ranking-accordion-item" data-ranking-team-id="${escapeHtml(team.id)}">
      <button class="ranking-accordion-button pintura-de-equipe" type="button" data-ranking-toggle aria-expanded="false" aria-controls="${panelId}" ${teamAccentStyle(team)}>
        <span class="rank-cell${displayRank === 1 ? " rank-lider" : ""}">${displayRank}</span>
        ${rankingPositionChangeLabel(row)}
        <span class="ranking-team-cell">${teamLogo(team.id)}<span><strong>${escapeHtml(team.name)}</strong><small>${escapeHtml(team.sourceTag || team.tag || team.id)} - ${matchesCount} partidas</small></span></span>
        <span class="numeric ranking-score-cell">${fmt(ranking.score ?? team.rankingScore ?? team.points, 1)}</span>
        <span class="ranking-lineup-inline optional">${rankingInlineLineup(team, cutoffAt)}</span>
        <span class="numeric optional ranking-detail-cell" data-label="Desempenho">${fmt(blocks.competitive, 1)}</span>
        <span class="numeric optional ranking-detail-cell" data-label="Conquistas">${fmt(blocks.achievements, 1)}</span>
        <span class="numeric optional ranking-detail-cell" data-label="Forma">${fmt(blocks.recentForm, 1)}</span>
        <span class="numeric optional ranking-detail-cell" data-label="rAAting 3.0">${fmt(blocks.rosterStrength, 1)}</span>
        <span class="ranking-status-cell">${rankingStatusChip(team, ranking)}</span>
        <span class="ranking-toggle-mark" aria-hidden="true">+</span>
      </button>
      <div id="${panelId}" class="ranking-dropdown" aria-hidden="true" inert>
        <div class="ranking-dropdown-inner">
          ${rankingTeamPreviewPanel(team, cutoffAt)}
          <div class="ranking-detail-dropdown" aria-hidden="true" inert>
            ${rankingExplanationPanel(team, ranking, cutoffAt)}
          </div>
        </div>
      </div>
    </article>
  `;
}

function rankingStatusLabel(ranking) {
  if (rankingIsInactive(ranking)) return "Inativo";
  return ranking?.provisional ? "Provisório" : "Validado";
}

function rankingStatusChip(team, ranking = team.ranking) {
  const label = rankingStatusLabel(ranking);
  return `<span class="${label === "Validado" ? "chip green" : "chip"}">${label}</span>`;
}

// A formacao vestida nas duas cores da equipe: a mesma faixa da capa da pagina da
// equipe, menor. Escolhida pelo dono em 07/11 entre fotos soltas, esta faixa e um
// cartao Camisa por jogador.
function rankingLineupFaixa(team, lineup) {
  const jogadores = lineup.map((entry) => {
    const player = playerById(entry.playerId || entry.id);
    return teamCapaJogador(team, { ...entry, name: player?.nick || entry.name || entry.handle }, player);
  });
  return `<div class="vp-slide vp-capa-fotos vp-rk-faixa" style="${escapeHtml(teamPlateStyle(team))};--n:${jogadores.length}"><span class="vp-slide-campo"><i></i></span>${jogadores.join("")}</div>`;
}

function rankingTeamPreviewPanel(team, cutoffAt = null) {
  const lineup = rankingLineupEntries(team, cutoffAt);
  return `
    <div class="ranking-team-preview">
      ${lineup.length ? rankingLineupFaixa(team, lineup) : `<div class="ranking-lineup"><div class="empty-state">Equipe sem lineup atual cadastrada.</div></div>`}
      <div class="ranking-team-actions vp-rk-acoes">
        <button class="vp-rk-acao" type="button" data-ranking-details aria-expanded="false">Detalhes do ranking${chevronIcon()}</button>
        <a class="vp-rk-acao" href="#/teams/${team.id}">Perfil da equipe</a>
      </div>
    </div>
  `;
}

// Na semana atual, a escolha manual de titulares tem prioridade. Sem escolha
// manual, as cinco series mais recentes indicam a formacao em destaque.
// Reservas declarados nao ocupam uma vaga nessa formacao.
// Semanas anteriores mantem a lineup que jogou naquela semana.
function rankingLineupEntries(team, cutoffAt = null) {
  const cutoff = Number(cutoffAt);
  if (Number.isFinite(cutoff) && cutoff < currentRankingCutoff()) return rankingObservedLineupAt(team, cutoff);
  const roster = teamActiveRoster(team);
  if (roster.length) return rankingRosterTopFive(team, roster);
  // Equipe sem elenco cadastrado: mantem o observado nas partidas como fallback.
  if (Number.isFinite(cutoff)) return rankingObservedLineupAt(team, cutoff);
  return (team.observedLineup || team.lineup || []).slice(0, 5);
}

function currentRankingCutoff() {
  return Number(latestRankingSnapshot()?.cutoffAt) || rankingTuesdayStartOnOrBefore(Date.now());
}

function rankingObservedLineupAt(team, cutoffAt) {
  const observed = rankingLineupEntriesForMatches(team, state.db?.matches || [], cutoffAt);
  return observed.length ? observed : rankingProfileLineupAt(team, cutoffAt);
}

function rankingRosterTopFive(team, roster = teamActiveRoster(team)) {
  const candidates = roster.filter((entry) => entry.role !== "reserva" && entry.role !== "comissao");
  const recent = teamRecentRosterCounts(team);
  return candidates
    .map((entry, index) => ({ entry, index, explicit: entry.role === "titular", recent: recent.get(entry.playerId) || 0, matches: rosterEntryTeamMatches(entry, team.id) }))
    .sort((a, b) => Number(b.explicit) - Number(a.explicit) || b.recent - a.recent || b.matches - a.matches || a.index - b.index)
    .slice(0, 5)
    .sort((a, b) => a.index - b.index)
    .map((row) => row.entry);
}

function teamRecentRosterCounts(team) {
  const counts = new Map();
  const recentSeries = (state.db?.matchSeries || [])
    .filter((series) => series.teamA?.id === team.id || series.teamB?.id === team.id)
    .sort((a, b) => Number(b.startedAt || b.sortAt || 0) - Number(a.startedAt || a.sortAt || 0))
    .slice(0, 5);
  for (const series of recentSeries) {
    const players = new Set();
    for (const match of series.maps || []) {
      for (const player of match.players || []) {
        if (player.teamId === team.id && player.id) players.add(player.id);
      }
    }
    for (const id of players) counts.set(id, (counts.get(id) || 0) + 1);
  }
  return counts;
}

function rosterEntryTeamMatches(entry, teamId) {
  const player = entry.playerId ? playerById(entry.playerId) : null;
  if (!player) return 0;
  return Number(playerStatsForTeam(player, teamId)?.matches || 0);
}

function rankingProfileLineupAt(team, cutoffAt) {
  const history = team.profile?.lineupHistory || [];
  const cutoffDay = new Date(cutoffAt).toISOString().slice(0, 10);
  const segment = history
    .filter((row) => String(row.from || "") <= cutoffDay)
    .sort((a, b) => Number(b.lastSeenAt || Date.parse(b.to || b.from || 0)) - Number(a.lastSeenAt || Date.parse(a.to || a.from || 0)))[0];
  if (!segment) return [];
  return (segment.players || [])
    .filter((player) => !player.firstSeenAt || player.firstSeenAt <= cutoffDay)
    .slice(0, 5);
}

function rankingLineupEntriesForMatches(team, matches, cutoffAt) {
  const buckets = new Map();
  for (const match of matches || []) {
    const startedAt = Number(match.startedAt || 0);
    if (startedAt && startedAt > cutoffAt) continue;
    if (match.teamA?.id !== team.id && match.teamB?.id !== team.id) continue;
    for (const player of match.players || []) {
      if (player.teamId !== team.id) continue;
      const id = player.id;
      if (!id) continue;
      const bucket = buckets.get(id) || { id, playerId: id, name: player.nick || player.handle || id, handle: player.handle || player.nick || id, rounds: 0, matches: 0, lastSeen: 0 };
      bucket.name = player.nick || bucket.name;
      bucket.handle = player.handle || bucket.handle;
      bucket.rounds += Number(player.rounds || match.rounds || 0);
      bucket.matches += 1;
      bucket.lastSeen = Math.max(bucket.lastSeen, startedAt || 0);
      buckets.set(id, bucket);
    }
  }
  return [...buckets.values()]
    .sort((a, b) => b.lastSeen - a.lastSeen || b.rounds - a.rounds || b.matches - a.matches || String(a.name).localeCompare(String(b.name)))
    .slice(0, 5);
}

function rankingInlineLineup(team, cutoffAt = null) {
  const names = rankingLineupEntries(team, cutoffAt)
    .map((entry) => {
      const player = playerById(entry.playerId || entry.id);
      return player?.nick || entry.name || entry.handle || "";
    })
    .filter(Boolean)
    .slice(0, 5);
  return names.length ? escapeHtml(names.join(" · ")) : `<span class="muted">Sem lineup até esta semana</span>`;
}


// "Detalhes do ranking" no desenho da Placa: a nota solta no topo e, ao lado,
// a nota desmontada numa barra so (cada fatia e valor do bloco x peso, entao o
// comprimento total e a propria nota). Embaixo, os blocos em linhas e os
// numeros de apoio soltos, cada um com uma barra fina. Tudo na cor da equipe:
// vermelho e marca, nunca dado. As explicacoes continuam no hover.
function rankingExplanationPanel(team, rankingOverride = null, cutoffAt = null, { recolhido = false } = {}) {
  const ranking = rankingOverride || team.ranking || {};
  const blocks = ranking.blocks || {};
  const components = ranking.components || {};
  const sos = ranking.sos || {};
  const recent = ranking.recent || {};
  const roster = ranking.roster || {};
  const minimumMatches = state.db?.rankingMinimumMatches || 9;
  const score = rankingSafeScore(ranking.score ?? team.rankingScore ?? team.points);
  const matchesCount = Number.isFinite(Number(ranking.matches)) ? Number(ranking.matches) : team.matches;
  const partes = [
    ["Desempenho", blocks.competitive, 70, "Mede desempenho coletivo através dos resultados, qualidade dos adversários e dominância."],
    ["Conquistas", blocks.achievements, 15, "Soma os pontos de cada colocação em campeonatos encerrados; das classificatórias da UNIVAVÁ, conta só a de maior pontuação. Cada ponto perde valor em linha reta até zerar em 10 meses. A equipe com mais pontos vale 100, e as demais, a proporção dela."],
    ["Forma recente", blocks.recentForm, 10, "Desempenho em uma janela de 60 dias, meia-vida de 30 dias."],
    ["rAAting 3.0 jogadores", blocks.rosterStrength, 5, "Usa o rAAting 3.0 individual da formação, com as partidas de cada jogador por qualquer equipe, mais a estabilidade do core e a profundidade."],
  ];
  const fatia = (valor, peso) => Math.round(((rankingSafeScore(valor) * peso) / 100) * 100) / 100;
  const secao = (titulo, legenda, corpo, extra = "") => `<section class="vp-rk-secao${extra}"><h3>${escapeHtml(titulo)}<small>${escapeHtml(legenda)}</small></h3>${corpo}</section>`;
  const detalhes = `
      <div class="vp-rk-colunas">
        ${secao("Composição da nota", "valor do bloco x peso", partes.map(([label, valor, peso, dica]) => rankingBlocoLinha(label, valor, peso, dica)).join(""))}
        ${secao(
          "Por dentro do desempenho",
          "o motor do ranking",
          `${rankingBlocoLinha("Modelos estatísticos", components.statisticalModels, 66.7, "Combina Colley, Massey, Elo final, Elo com margem, TrueSkill, PageRank, Bradley-Terry-Poisson e PCA.")}
          ${rankingBlocoLinha("Força dos adversários", components.strengthOfSchedule, 22.2, "SOS (Strength of Schedule) geral considera todos os adversários; SOS de vitórias destaca quem foi batido.")}
          ${rankingBlocoLinha("Dominância", components.dominance, 11.1, "Mede controle do placar pela margem relativa de rounds.")}
          <div class="vp-rk-dados">
            ${rankingDado("SOS geral", sos.general, "Strength of Schedule: força média de todos os adversários enfrentados.")}
            ${rankingDado("SOS vitórias", sos.wins, "Força média dos adversários vencidos. Vitórias fortes sobem mais.")}
            ${rankingDado("Amostra", matchesCount, `${ranking.provisional ? `Provisório: menos de ${minimumMatches} partidas.` : "Amostra mínima validada."}`, 0, Math.max(12, minimumMatches))}
          </div>`,
        )}
        ${secao("Modelos estatísticos", "leituras independentes", rankingModelGrid(ranking.models || {}))}
        ${secao(
          "Momento e rAAting 3.0",
          "forma recente e lineup",
          `<div class="vp-rk-dados">
            ${rankingDado("Partidas recentes", recent.matches ?? 0, "Quantidade de jogos na janela de 60 dias.", 0, 8)}
            ${rankingDado("Desempenho ajustado", recent.adjustedPerformance, "Resultado recente ajustado pela força do adversário e margem.")}
            ${rankingDado("Dominância recente", recent.dominance, "Controle de placar na janela recente.")}
            ${rankingDado("rAAting individual", roster.individualRating, "rAAting 3.0 dos jogadores por esta equipe, ajustado pelo nível dos adversários.")}
            ${rankingDado("Estabilidade core", roster.coreStability, "Quanto do core atual aparece nos jogos recentes da equipe.")}
            ${rankingDado("Profundidade", roster.depth, "Quantidade de jogadores com volume suficiente pela equipe.")}
          </div>`,
        )}
      </div>
      ${secao("Conquistas", "pontos dos últimos 10 meses", rankingAchievementSummary(ranking.achievements || [], ranking.blocks?.achievements), " vp-rk-conquistas")}
  `;
  return `
    <div class="vp-rk-detalhes" style="--team-line:${teamLineColor(team.id)}">
      <div class="vp-rk-topo">
        <div class="vp-rk-nota-bloco ${rankingTooltipClass()}" tabindex="0" data-tooltip="${rankingTooltipText("A nota final mistura desempenho coletivo, conquistas, momento recente e rAAting 3.0 dos jogadores. Todos os blocos já chegam normalizados em 0-100.")}">
          <b class="vp-rk-nota-final">${fmt(score, 1)}</b>
          <small>nota final</small>
        </div>
        <div class="vp-rk-formula">
          <p>70% desempenho, 15% conquistas, 10% forma recente e 5% rAAting 3.0 dos jogadores.</p>
          <div class="vp-rk-soma" aria-hidden="true">${partes.map(([label, valor, peso]) => `<i style="--w:${fatia(valor, peso)}%" title="${escapeHtml(`${label}: ${fmt(fatia(valor, peso), 1)}`)}"></i>`).join("")}</div>
          <div class="vp-rk-soma-legenda">${partes.map(([label, valor, peso]) => `<span><i></i>${escapeHtml(label)} <b>${fmt(fatia(valor, peso), 1)}</b></span>`).join("")}</div>
        </div>
      </div>
      ${recolhido ? `<details class="vp-nota-calculo"><summary>Ver como a nota é calculada</summary>${detalhes}</details>` : detalhes}
    </div>
  `;
}

// Um bloco da nota numa linha: nome, a conta (valor x peso) e a barra do valor.
function rankingBlocoLinha(label, value, weight, tooltip) {
  const score = rankingSafeScore(value);
  const contribution = (score * weight) / 100;
  return `
    <div class="vp-rk-linha ${rankingTooltipClass()}" tabindex="0" data-tooltip="${rankingTooltipText(tooltip)}">
      <span class="vp-rk-linha-nome">${escapeHtml(label)}</span>
      <span class="vp-rk-linha-conta">${fmt(score, 1)} × ${weight}% = ${fmt(contribution, 1)}</span>
      <span class="vp-rk-barra"><i style="--w:${score}%"></i></span>
    </div>
  `;
}

// Um numero de apoio solto: o valor grande, o nome embaixo e a barra fina.
function rankingDado(label, value, tooltip, digits = 1, max = 100) {
  const numeric = Number.isFinite(Number(value)) ? Number(value) : 0;
  const percent = clamp((numeric / Math.max(1, max)) * 100, 0, 100);
  return `
    <div class="vp-rk-dado ${rankingTooltipClass()}" tabindex="0" data-tooltip="${rankingTooltipText(tooltip)}">
      <b>${fmt(numeric, digits)}</b>
      <span>${escapeHtml(label)}</span>
      <span class="vp-rk-barra"><i style="--w:${Math.round(percent * 10) / 10}%"></i></span>
    </div>
  `;
}

function rankingModelGrid(models) {
  const order = ["colley", "massey", "eloFinal", "eloMargin", "trueSkill", "pageRankWins", "bradleyTerryPoisson", "pcaCorrigido"];
  const entries = order.filter((key) => Object.hasOwn(models, key)).map((key) => [key, models[key]]);
  if (!entries.length) return `<div class="empty-state">Modelos indisponíveis para esta equipe.</div>`;
  return `
    <div class="vp-rk-dados vp-rk-modelos">
      ${entries.map(([key, value]) => rankingDado(rankingModelLabel(key), value, rankingModelTooltip(key))).join("")}
    </div>
  `;
}

function rankingModelLabel(key) {
  const labels = {
    colley: "Colley",
    massey: "Massey",
    eloFinal: "Elo final",
    eloMargin: "Elo margem",
    trueSkill: "TrueSkill",
    pageRankWins: "PageRank",
    bradleyTerryPoisson: "BT-Poisson",
    pcaCorrigido: "PCA corrigido",
  };
  return labels[key] || key;
}

function rankingModelTooltip(key) {
  const labels = {
    colley: "Modelo de vitórias e derrotas.",
    massey: "Modelo linear que olha diferença de rounds e oposição enfrentada.",
    eloFinal: "Elo cronológico usando apenas resultado final.",
    eloMargin: "Elo cronológico com bônus por margem de rounds.",
    trueSkill: "Estimativa bayesiana aproximada de habilidade com incerteza reduzida ao jogar mais.",
    pageRankWins: "Rede de vitórias: bater times fortes transfere mais força.",
    bradleyTerryPoisson: "Modelo probabilístico que mistura chance de vitória e placar em rounds.",
    pcaCorrigido: "Componente principal dos modelos.",
  };
  return labels[key] || "Modelo estatístico normalizado em 0-100.";
}

// Todo resultado soma (desde 22/09/2026), entao a lista mostra todas as
// campanhas que ainda valem ponto. Colocacao de 0 ponto ou ja vencida fica de fora,
// e tambem a classificatoria que perdeu para outra do mesmo grupo (`bestOfGroup`),
// que o ranking-core entrega com 0 ponto.
function rankingAchievementSummary(achievements, blockScore) {
  const scoring = achievements.filter((row) => Number(row.score) > 0);
  if (!scoring.length) {
    return `<p class="vp-rk-vazio ${rankingTooltipClass()}" tabindex="0" data-tooltip="${rankingTooltipText("A nota de conquistas é a proporção dos pontos da equipe sobre a equipe que mais pontuou. Sem pontos nos últimos 10 meses, ela fica em zero.")}"><b>${fmt(blockScore ?? 0, 1)}</b> sem pontos em campeonatos dos últimos 10 meses</p>`;
  }
  return `
    <div class="vp-rk-conquista-lista">
      ${scoring.map((row) => rankingAchievementCard(row)).join("")}
    </div>
  `;
}

function rankingAchievementCard(row) {
  const event = rankingTournamentForAchievement(row);
  const base = Number(row.basePoints);
  const decay = Number(row.decay);
  // Classificatoria de grupo nao zera nos proprios 10 meses: vence junto com a
  // primeira do grupo, na data que o ranking-core entrega em `expiresAt`.
  const expiry = row.group && row.expiresAt
    ? `Das classificatórias do mesmo campeonato, conta só a de maior pontuação, e todas deixam de contar em ${formatShortDate(row.expiresAt)}.`
    : "Zera 10 meses depois.";
  const tooltip =
    Number.isFinite(base) && Number.isFinite(decay)
      ? `A colocação vale ${fmt(base, 0)} pontos. Com o tempo desde o fim do campeonato, conta ${fmt(decay * 100, 0)}% hoje. ${expiry}`
      : "Pontos da colocação, já descontado o tempo desde o fim do campeonato.";
  return `
    <span class="vp-rk-conquista ${rankingTooltipClass()}" tabindex="0" data-tooltip="${rankingTooltipText(tooltip)}">
      ${eventLogo(event, "small")}
      <span class="vp-rk-conquista-nome"><strong>${escapeHtml(event.name || row.eventId || "Campeonato")}</strong><small>${escapeHtml(rankingPlacementLabel(row.placementLabel || row.range || row.placement))}</small></span>
      <b>${fmt(row.score, 1)}<small>pts</small></b>
    </span>
  `;
}

function rankingTournamentForAchievement(row) {
  const event = state.db?.tournaments.find((item) => item.id === row.eventId);
  if (event) return event;
  return {
    id: row.eventId || "evento",
    name: row.eventName || row.eventId || "Campeonato",
    logo: row.eventLogo || "",
    mark: eventAcronym(row.eventName || row.eventId || "EV"),
  };
}

function rankingPlacementLabel(value) {
  const text = String(value || "").trim();
  const normalized = normalize(text);
  // Campanha de conquista so existe em campeonato encerrado, e ali "Classificado"
  // e o resultado de quem avancou (ver placementIsQualified).
  if (placementIsQualified(text)) return "Classificado";
  if (["em andamento", "em disputa"].includes(normalized)) return "Em andamento";
  if (normalized === "eliminado" || normalized === "eliminada") return "Eliminado";
  const range = text.match(/(\d+)\D+(\d+)/);
  if (range) return `${range[1]}º-${range[2]}º lugar`;
  const ordinal = text.match(/^(\d+)(?:st|nd|rd|th)$/i);
  if (ordinal) return `${ordinal[1]}º lugar`;
  const placement = Number(value);
  if (!Number.isFinite(placement)) return "Colocação não informada";
  return `${placement}º lugar`;
}

function placementRangeFromValue(value) {
  const text = String(value || "").trim();
  const range = text.match(/(\d+)\D+(\d+)/);
  if (range) return { start: Number(range[1]), end: Number(range[2]), explicit: true };
  const single = text.match(/\d+/);
  if (single) return { start: Number(single[0]), end: Number(single[0]), explicit: false };
  return { start: 0, end: 0, explicit: false };
}

function placementRawValue(row) {
  return row?.placementLabel || row?.range || row?.placementRange || row?.placement || row?.place || "";
}

function placementIsOngoing(value) {
  const normalized = normalize(value);
  return ["em andamento", "classificado", "classificada", "em disputa"].includes(normalized);
}

function normalizePlacementRowsForDisplay(rows = []) {
  const normalized = rows.map((row, index) => {
    const raw = placementRawValue(row);
    const range = placementRangeFromValue(raw);
    return {
      ...row,
      range: String(row.range || row.placementLabel || raw),
      placementStart: range.start,
      placementEnd: range.end,
      explicitRange: range.explicit,
      originalIndex: index,
    };
  });
  const groups = new Map();
  normalized.forEach((row) => {
    const plainNumeric = row.range === String(row.placement || row.place || row.placementStart);
    if (!row.placementStart || row.explicitRange || !plainNumeric) return;
    const key = String(row.placementStart);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(row);
  });
  for (const group of groups.values()) {
    if (group.length <= 1) continue;
    const start = group[0].placementStart;
    const end = start + group.length - 1;
    group.forEach((row) => {
      row.range = `${start}-${end}`;
      row.placementEnd = end;
    });
  }
  return normalized;
}

function tournamentConfiguredPlacementRows(eventId) {
  return normalizePlacementRowsForDisplay(state.db?.rankingWeights?.tournaments?.[eventId]?.placements || []);
}

function tournamentTeamPlacementRow(event, teamId) {
  const rows = event.placements?.length ? normalizePlacementRowsForDisplay(event.placements) : tournamentConfiguredPlacementRows(event.id);
  return rows.find((row) => (row.id || row.teamId) === teamId) || null;
}

function tournamentTeamEliminatedRow(event, teamId) {
  const rows = [...(event.eliminated || []), ...(event.swiss?.eliminated || [])];
  return rows.find((row) => (row.id || row.teamId) === teamId) || null;
}

// "Classificado" NAO e colocacao faltando. Numa fase eliminatoria encerrada
// (JUBS Fase inicial, UNIVAVA Classificatorias) esse e o resultado: a equipe
// avancou. Ate 30/08/2026 ele caia no mesmo balde de "em andamento" e a aba de
// campeonatos dizia "Colocação não informada" para uma campanha 7-0 - o dado
// estava na planilha o tempo todo, o rotulo e que o descartava.
function placementIsQualified(value) {
  return ["classificado", "classificada"].includes(normalize(value));
}

function placementResultFromRow(row, event, fallback = "") {
  const raw = placementRawValue(row) || fallback;
  const nota = row?.note || row?.reason || "";
  if (placementIsQualified(raw)) {
    return { placement: 0, placementLabel: "Classificado", placementStatus: "qualified", placementNote: nota };
  }
  if (placementIsOngoing(raw)) {
    return eventIsDone(event)
      ? { placement: 0, placementLabel: "Colocação não informada", placementStatus: "unknown", placementNote: nota }
      : { placement: 0, placementLabel: "Em andamento", placementStatus: "ongoing", placementNote: nota };
  }
  const range = placementRangeFromValue(raw);
  return {
    placement: range.start || Number(row?.placement || 0) || 0,
    placementLabel: rankingPlacementLabel(raw),
    placementStatus: range.start ? "defined" : "unknown",
    placementNote: nota,
  };
}

function teamEventPlacementResult(teamId, event, achievement = null) {
  if (achievement?.placementLabel || achievement?.range || achievement?.placement) {
    return placementResultFromRow(achievement, event);
  }
  const official = tournamentTeamPlacementRow(event, teamId);
  if (official) return placementResultFromRow(official, event);
  const eliminated = tournamentTeamEliminatedRow(event, teamId);
  if (eliminated) return placementResultFromRow(eliminated, event, "Eliminado");
  // Campeonato agendado nao esta "em andamento": ate 30/08/2026 a Etapa
  // Presencial do JUBS, marcada para comecar no dia seguinte, aparecia com
  // resultado "Em andamento" ao lado do selo "Agendado".
  if (eventStatusClass(event?.status) === "scheduled") {
    return { placement: 0, placementLabel: "A começar", placementStatus: "scheduled", placementNote: "" };
  }
  if (!eventIsDone(event)) return { placement: 0, placementLabel: "Em andamento", placementStatus: "ongoing", placementNote: "" };
  return { placement: 0, placementLabel: "Colocação não informada", placementStatus: "unknown", placementNote: "" };
}

function rankingSafeScore(value) {
  return clamp(Number.isFinite(Number(value)) ? Number(value) : 50, 0, 100);
}

function rankingTooltipClass() {
  return "has-ranking-tooltip";
}

function rankingTooltipText(value) {
  return escapeHtml(value || "");
}

function bindRankingScopeToggle() {
  document.querySelectorAll("[data-ranking-scope]").forEach((button) => {
    button.addEventListener("click", () => {
      const scope = button.dataset.rankingScope === "all" ? "all" : "valid";
      if (state.rankingScope === scope) return;
      state.rankingScope = scope;
      updateRankingScopeView(scope);
    });
  });
}

function bindRankingVersionPicker() {
  document.querySelector("[data-ranking-version]")?.addEventListener("change", (event) => {
    state.rankingVersionId = event.currentTarget.value || "";
    updateRankingVersionView();
  });
}

function bindRankingScoreDetailsToggle() {
  document.querySelector("[data-ranking-score-details]")?.addEventListener("change", (event) => {
    state.rankingShowDetails = Boolean(event.currentTarget.checked);
    updateRankingDetailsVisibility(state.rankingShowDetails);
  });
}

// Os dois caminhos que trocam as linhas sem re-renderizar a pagina (semana e
// escopo) precisam mexer nos mesmos tres lugares. Quando o resumo de movimento
// entrou, ele ficou de fora dos dois e a barra continuava dizendo "5 subiram"
// depois de trocar para uma semana com 14 quedas. Um helper so, para o proximo
// campo da barra nao repetir o esquecimento.
function updateRankingToolbarSummaries(scope) {
  const count = document.querySelector("[data-ranking-count]");
  if (count) count.textContent = rankingScopeSummary(scope);
  const botao = document.querySelector('[data-ranking-tab="partidas"]');
  if (!botao) return;
  const total = rankingWeekMatches().length;
  botao.innerHTML = rotuloDasNovasPartidas(total);
  botao.disabled = !total;
}

// Quantas partidas entraram e de que janela - o contrapeso da esquerda quando a
// aba de partidas esta aberta.
function rankingWeekMatchesSummary(matches, snapshot) {
  const janela = rankingWeekWindow(snapshot);
  const total = matches.length;
  const quantas = `${total} ${total === 1 ? "partida" : "partidas"}`;
  if (!janela) return quantas;
  return `${quantas}, de ${formatShortDate(janela.inicio)} a ${formatShortDate(janela.fim)}`;
}

function updateRankingVersionView() {
  const rowsRoot = document.querySelector("[data-ranking-rows]");
  if (!rowsRoot) {
    renderRankingPage();
    return;
  }
  const scope = state.rankingScope === "all" ? "all" : "valid";
  const rows = rankingRowsForScope(state.db.teams, scope);
  rowsRoot.innerHTML = rankingAccordionRows(rows);
  updateRankingToolbarSummaries(scope);
  atualizarTrilhoDoRanking();
}

function updateRankingDetailsVisibility(showDetails) {
  const accordion = document.querySelector("[data-ranking-accordion]");
  if (!accordion) {
    renderRankingPage();
    return;
  }
  if (!showDetails && ["competitive", "achievements", "recentForm", "rosterStrength"].includes(state.rankingSort?.key)) {
    state.rankingSort = { key: "", direction: "default" };
    updateRankingSortView();
  }
  accordion.dataset.detailsVisible = String(showDetails);
}

function updateRankingScopeView(scope) {
  const switcher = document.querySelector(".ranking-scope-switch");
  const accordion = document.querySelector("[data-ranking-accordion]");
  const rowsRoot = document.querySelector("[data-ranking-rows]");
  if (!switcher || !accordion || !rowsRoot) {
    renderRankingPage();
    return;
  }

  switcher.dataset.scope = scope;
  switcher.querySelectorAll("[data-ranking-scope]").forEach((button) => {
    const active = button.dataset.rankingScope === scope;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  if (scope !== "all" && state.rankingSort?.key === "status") {
    state.rankingSort = { key: "", direction: "default" };
    updateRankingSortIndicators();
  }
  accordion.dataset.statusVisible = String(scope === "all");
  accordion.dataset.detailsVisible = String(state.rankingShowDetails);
  window.clearTimeout(state.rankingScopeUpdateTimer);
  state.rankingScopeUpdateTimer = window.setTimeout(() => {
    const rows = rankingRowsForScope(state.db.teams, scope);
    rowsRoot.innerHTML = rankingAccordionRows(rows);
    updateRankingToolbarSummaries(scope);
    trocarCartaoDoRanking();
  }, 170);
}

function bindRankingSortHeaders() {
  document.querySelectorAll("[data-ranking-sort]").forEach((button) => {
    button.addEventListener("click", () => {
      cycleRankingSort(button.dataset.rankingSort || "");
      updateRankingSortView();
    });
  });
}

function cycleRankingSort(key) {
  if (!key) return;
  const current = state.rankingSort || { key: "", direction: "default" };
  if (current.key !== key || current.direction === "default") {
    state.rankingSort = { key, direction: "desc" };
  } else if (current.direction === "desc") {
    state.rankingSort = { key, direction: "asc" };
  } else {
    state.rankingSort = { key: "", direction: "default" };
  }
}

function updateRankingSortView() {
  const rowsRoot = document.querySelector("[data-ranking-rows]");
  if (!rowsRoot) {
    renderRankingPage();
    return;
  }
  rowsRoot.innerHTML = rankingAccordionRows(rankingRowsForScope(state.db.teams, state.rankingScope === "all" ? "all" : "valid"));
  updateRankingSortIndicators();
  trocarCartaoDoRanking();
}

function updateRankingSortIndicators() {
  const sort = state.rankingSort || { key: "", direction: "default" };
  document.querySelectorAll("[data-ranking-sort]").forEach((button) => {
    const active = button.dataset.rankingSort === sort.key && sort.direction !== "default";
    const direction = active ? sort.direction : "default";
    const icon = button.querySelector("i");
    const label = button.querySelector("span")?.textContent || "Coluna";
    const title = direction === "desc" ? "Ordenado decrescente" : direction === "asc" ? "Ordenado crescente" : "Ordenação padrão";
    button.classList.toggle("active", active);
    button.dataset.sortDirection = direction;
    button.setAttribute("title", title);
    button.setAttribute("aria-label", `${label}: ${title}`);
    if (icon) icon.textContent = direction === "desc" ? "↓" : direction === "asc" ? "↑" : "";
  });
}

function bindRankingAccordion() {
  const root = document.querySelector("[data-ranking-accordion]");
  root?.addEventListener("click", (event) => {
    const detailsButton = event.target.closest("[data-ranking-details]");
    if (detailsButton) {
      const item = detailsButton.closest(".ranking-accordion-item");
      if (!item) return;
      const open = !item.classList.contains("details-open");
      setRankingDetailsOpen(item, open);
      return;
    }

    const button = event.target.closest("[data-ranking-toggle]");
    if (!button) return;
    const item = button.closest(".ranking-accordion-item");
    if (!item) return;
    const shouldOpen = !item.classList.contains("open");
    root.querySelectorAll(".ranking-accordion-item.open").forEach((openItem) => setRankingAccordionItem(openItem, false));
    setRankingAccordionItem(item, shouldOpen);
    trocarCartaoDoRanking();
  });
}

function openRankingRouteTeam(teamId) {
  if (!teamId) return;
  const root = document.querySelector("[data-ranking-accordion]");
  const item = [...document.querySelectorAll("[data-ranking-team-id]")]
    .find((element) => element.dataset.rankingTeamId === teamId);
  if (!root || !item) return;
  root.querySelectorAll(".ranking-accordion-item.open").forEach((openItem) => setRankingAccordionItem(openItem, false));
  setRankingAccordionItem(item, true);
  trocarCartaoDoRanking();
  window.requestAnimationFrame(() => {
    item.scrollIntoView({ block: "center", behavior: "smooth" });
  });
}

function setRankingAccordionItem(item, open) {
  item.classList.toggle("open", open);
  item.querySelector("[data-ranking-toggle]")?.setAttribute("aria-expanded", String(open));
  const painel = item.querySelector(".ranking-dropdown");
  painel?.setAttribute("aria-hidden", String(!open));
  // aria-hidden esconde da leitura de tela mas NAO tira do tab order: com 44
  // sanfonas fechadas eram 1609 controles focaveis dentro de caixas de altura
  // zero. inert remove as duas coisas de uma vez.
  if (painel) painel.inert = !open;
  if (open && painel) ajustarTextosVariaveis(painel);
  if (!open) setRankingDetailsOpen(item, false);
}

function setRankingDetailsOpen(item, open) {
  item.classList.toggle("details-open", open);
  item.querySelector("[data-ranking-details]")?.setAttribute("aria-expanded", String(open));
  const detalhe = item.querySelector(".ranking-detail-dropdown");
  detalhe?.setAttribute("aria-hidden", String(!open));
  if (detalhe) detalhe.inert = !open;
  if (open && detalhe) ajustarTextosVariaveis(detalhe);
}

function safeDomId(value) {
  return String(value || "").replace(/[^a-z0-9_-]+/gi, "-");
}

const pendingMatchDetailRequests = new Map();

function ensureMatchDetails(matches) {
  for (const match of matches) {
    if (!match.detailPending || !match.sourcePath || pendingMatchDetailRequests.has(match.id)) continue;
    const request = loadJson(match.sourcePath)
      .then((raw) => {
        match.roundResults = officialRoundResults(raw);
      })
      .catch((error) => {
        console.error(`Falha ao carregar detalhes da partida ${match.id}`, error);
      })
      .then(() => {
        match.detailPending = false;
        pendingMatchDetailRequests.delete(match.id);
        render();
      });
    pendingMatchDetailRequests.set(match.id, request);
  }
}

function renderMatchDetail(id) {
  const db = state.db;
  const match = db.matches.find((item) => item.id === id);
  if (!match) return renderNotFound("Partida");
  const series = matchSeries(match);
  const aggregateMode = route().tab === "all" && (series.length > 1 || normalizeMatchItem(match).officialResultNote);
  const selectedMatches = aggregateMode ? series : [match];
  const pendingDetail = selectedMatches.filter((item) => item.detailPending);
  if (pendingDetail.length) {
    ensureMatchDetails(pendingDetail);
    return Shell(`<div class="empty-state">Carregando detalhes da partida...</div>`);
  }
  const viewPlayers = aggregateMode ? aggregateMatchPlayers(selectedMatches) : hydrateMatchPlayers(match.players);
  const teamAViewPlayers = viewPlayers.filter((player) => player.teamId === match.teamA.id);
  const teamBViewPlayers = viewPlayers.filter((player) => player.teamId === match.teamB.id);
  const teamAPlayers = sortedScoreboardPlayers(match, match.teamA, teamAViewPlayers);
  const teamBPlayers = sortedScoreboardPlayers(match, match.teamB, teamBViewPlayers);
  const teamALineupPlayers = defaultScoreboardPlayers(teamAViewPlayers).slice(0, 5);
  const teamBLineupPlayers = defaultScoreboardPlayers(teamBViewPlayers).slice(0, 5);
  const mvp = viewPlayers.slice().sort((a, b) => Number(officialRatingValue(b) || 0) - Number(officialRatingValue(a) || 0) || Number(playerSwingPerRound(b) || 0) - Number(playerSwingPerRound(a) || 0))[0];
  const event = db.tournaments.find((item) => item.id === match.eventId);
  const score = matchDisplayScore(match, selectedMatches, aggregateMode);
  const scoreboardMode = matchScoreboardMode();
  const scoreboardColumnsList = scoreboardColumns(scoreboardMode);
  const mapSlide = panelSlideSnapshot("match-maps", {
    selector: ".match-tab-panel",
    scope: match.seriesKey,
    key: aggregateMode ? "all" : match.id,
    order: ["all", ...series.map((item) => item.id)],
  });
  // No agregado, o topo mostra os rounds somados da serie; num mapa so, o nome
  // dele e a duracao.
  const roundsA = selectedMatches.reduce((sum, item) => sum + scoreForTeamInMatch(item, match.teamA.id), 0);
  const roundsB = selectedMatches.reduce((sum, item) => sum + scoreForTeamInMatch(item, match.teamB.id), 0);
  const heroDetalhe = aggregateMode ? `${roundsA} - ${roundsB} rounds` : `${match.mapName}, ${formatDuration(match.durationMillis)}`;
  const lados = [
    { team: match.teamA, players: teamAPlayers, side: "a" },
    { team: match.teamB, players: teamBPlayers, side: "b" },
  ];
  // Quem pode ir para o historico: a lineup primeiro (o padrao e o primeiro
  // dela) e depois qualquer outro jogador da tabela, como um reserva.
  const escolhiveisA = [...teamALineupPlayers, ...teamAPlayers];
  const escolhiveisB = [...teamBLineupPlayers, ...teamBPlayers];
  const compareKey = lineupCompareKey(match);
  const selection = ensureLineupCompareSelection(compareKey, escolhiveisA, escolhiveisB);
  Shell(`
    <section class="match-page vp-partida">
      <h1 class="sr-only">${escapeHtml(match.teamA.name)} ${score.a} x ${score.b} ${escapeHtml(match.teamB.name)}</h1>
      ${matchMapTabs(match, series, aggregateMode)}

      <header class="vp-hero-partida">
        ${matchHeroMeta(match, event, score, aggregateMode)}
        <div class="vp-hero-placar">
          ${matchHeroBanners(selectedMatches)}
          ${placarHeroLado(match.teamA, "a")}
          <div class="vp-hero-score">
            ${placarHeroNumeros(score.a, score.b)}
            <small>${escapeHtml(heroDetalhe)}</small>
          </div>
          ${placarHeroLado(match.teamB, "b")}
        </div>
      </header>

      <div class="match-tab-panel">
        ${aggregateMode ? "" : `<section class="vp-s-rounds" aria-label="Rounds">${roundTimeline(match)}</section>`}
        ${comparativoFaixa(match, selectedMatches)}
        <section class="vp-s-sb" aria-label="Scoreboard">
          <header class="vp-sb-modo">
            <div class="match-scoreboard-mode-switch vp-modo" data-scoreboard-mode="${escapeHtml(scoreboardMode)}" role="group" aria-label="Modo do scoreboard">
              <button type="button" data-match-scoreboard-mode="standard" aria-pressed="${scoreboardMode === "standard"}" class="${scoreboardMode === "standard" ? "active" : ""}">Padrão</button>
              <button type="button" data-match-scoreboard-mode="advanced" aria-pressed="${scoreboardMode === "advanced"}" class="${scoreboardMode === "advanced" ? "active" : ""}">Avançado</button>
            </div>
          </header>
          ${placarScoreboard(match, lados, scoreboardColumnsList, { compareKey, selection })}
        </section>
        <div class="vp-partida-baixo">
          ${matchMvpCard(mvp, selectedMatches.length)}
          ${matchLineupsSecao(compareKey, selection, match.teamA, teamALineupPlayers, match.teamB, teamBLineupPlayers, escolhiveisA, escolhiveisB)}
        </div>
      </div>
      ${window.Comments ? window.Comments.shell("match", match.seriesKey) : ""}
    </section>
  `);
  bindScoreboardSort();
  bindLineupCompare();
  // Pela SERIE, nao pelo mapa: cada mapa tem id proprio na rota, entao usar
  // match.id espalharia a conversa de uma serie de tres mapas por tres threads
  // diferentes, e trocar de aba faria os comentarios sumirem.
  window.Comments?.montar("match", match.seriesKey);
  playPanelSlide(mapSlide);
}

function matchHeroMeta(match, event, score, aggregateMode) {
  return `
    <div class="vp-hero-meta">
      ${matchTournamentLink(event)}
      <span>${escapeHtml(matchSeriesScopeLabel(match, aggregateMode))}${aggregateMode ? `, ${escapeHtml(score.label)}` : ""}</span>
      <span>${escapeHtml(formatDate(match.startedAt, "time"))}</span>
      ${match.gameVersion ? `<span>Patch ${escapeHtml(patchLabel(match.gameVersion))}</span>` : ""}
      ${TOURNAMENT_OVERRIDES[match.eventId]?.seriesResults?.[String(Number(match.seriesCode))]?.note ? `<span>${escapeHtml(TOURNAMENT_OVERRIDES[match.eventId].seriesResults[String(Number(match.seriesCode))].note)}</span>` : ""}
    </div>
  `;
}

function matchSeriesScopeLabel(match, aggregateMode) {
  const series = `Série ${match.seriesCode || match.code || "-"}`;
  return aggregateMode ? series : `${series}, Jogo ${match.mapNumber || 1}`;
}

function matchTournamentLink(event) {
  if (!event) return `<span class="match-event-link"><span>Campeonato</span></span>`;
  return `
    <a class="match-event-link" href="#/tournaments/${event.id}">
      ${eventLogo(event, "small")}
      <span>${escapeHtml(event.name)}</span>
    </a>
  `;
}

function matchSeries(match) {
  return state.db.matches
    .filter((item) => item.seriesKey === match.seriesKey)
    .sort((a, b) => (a.mapNumber || 1) - (b.mapNumber || 1) || a.startedAt - b.startedAt);
}

function matchDisplayScore(match, selectedMatches, aggregateMode) {
  if (!aggregateMode) {
    return { a: match.teamA.score, b: match.teamB.score, label: match.mapName };
  }
  const score = seriesMapScore(selectedMatches, match.teamA.id, match.teamB.id);
  return {
    a: score.a,
    b: score.b,
    label: seriesFormatLabel(selectedMatches, score),
  };
}

// As abas de mapa: uma faixa cortada em diagonal, como as linhas de partida.
// Cada aba traz o placar do mapa e o escudo de quem venceu, entao o bloco que
// repetia os mapas e placares embaixo delas saiu.
function matchMapTabs(match, series, aggregateMode) {
  const showSeriesSummary = series.length > 1 || normalizeMatchItem(match).officialResultNote;
  const placar = seriesMapScore(series, match.teamA.id, match.teamB.id);
  return `
    <nav class="vp-abas-mapa" aria-label="Mapas da série">
      ${
        showSeriesSummary
          ? `<a class="vp-aba vp-aba-serie ${aggregateMode ? "active" : ""}" href="#/matches/${match.id}/all"${aggregateMode ? ' aria-current="page"' : ""}><span class="vp-aba-nome">Série</span><span class="vp-aba-placar">${placar.a}-${placar.b}</span></a>`
          : ""
      }
      ${series
        .map((item, index) => {
          const asset = matchMapAsset(item);
          const ativo = !aggregateMode && item.id === match.id;
          return `<a class="vp-aba ${ativo ? "active" : ""}" href="#/matches/${item.id}"${ativo ? ' aria-current="page"' : ""}>${asset.src ? `<img class="vp-aba-arte" src="${escapeHtml(asset.src)}" data-fallback="${escapeHtml(asset.fallback)}" alt="" loading="lazy" onerror="mapArtError(this)" />` : ""}<span class="vp-aba-nome"><small>${item.mapNumber || index + 1}</small>${escapeHtml(item.mapName)}</span><span class="vp-aba-placar">${item.winnerId ? teamLogo(item.winnerId, "tiny") : ""}${scoreForTeamInMatch(item, match.teamA.id)}-${scoreForTeamInMatch(item, match.teamB.id)}</span></a>`;
        })
        .join("")}
    </nav>
  `;
}

function matchHeroBanners(matches) {
  return `<div class="vp-hero-artes" aria-hidden="true">${matches
    .map((item) => {
      const asset = matchMapAsset(item);
      return `<i>${asset.src ? `<img src="${escapeHtml(asset.src)}" data-fallback="${escapeHtml(asset.fallback)}" alt="" loading="lazy" onerror="mapArtError(this)" />` : ""}</i>`;
    })
    .join("")}</div>`;
}

function matchMapAsset(match) {
  const map =
    mapById(match.mapId) ||
    mapByName(match.mapName) ||
    state.db?.maps.find((item) => normalizeNameKey(item.name) === normalizeNameKey(match.mapName)) ||
    {};
  const art = mapArtAttrs(map, match.mapIcon);
  return {
    name: map.name || match.mapName || "Mapa",
    src: art ? art.src : "",
    fallback: art ? art.fallback : "",
  };
}

function scoreForTeamInMatch(match, teamId) {
  if (match.teamA.id === teamId) return match.teamA.score;
  if (match.teamB.id === teamId) return match.teamB.score;
  return 0;
}

// A linha do tempo em blocos: primeiro tempo, segundo tempo e prorrogacao.
// Lado a lado ela se le como uma linha so, com o intervalo marcado pelo vao, e
// no celular cada bloco cabe na largura da tela: nada rola de lado.
function roundTimeline(match) {
  const rounds = match.roundResults || [];
  const blocos = [rounds.slice(0, 12), rounds.slice(12, 24), rounds.slice(24)].filter((bloco) => bloco.length);
  return `
    <div class="round-timeline vp-rounds">
      ${blocos
        .map(
          (bloco) => `
        <div class="vp-rounds-bloco" style="--rounds:${bloco.length}">
          <div class="round-row numbers"><span></span>${bloco.map((round) => `<span>${round.roundNum + 1}</span>`).join("")}</div>
          ${roundTimelineTeam(match, match.teamA, bloco)}
          ${roundTimelineTeam(match, match.teamB, bloco)}
        </div>`,
        )
        .join("")}
    </div>
  `;
}

function roundTimelineTeam(match, team, rounds) {
  return `
    <div class="round-row">
      <strong class="round-team-label">${teamLogo(team.id, "round-mini")}<span>${escapeHtml(team.sourceTag || team.tag || team.shortTag || "")}</span></strong>
      ${rounds
        .map((round) => {
          const won = round.winningTeam === team.color;
          const sideClass = won ? roundSideClass(round) : "";
          return `<span class="round-cell ${won ? `won ${sideClass}` : ""}" title="${escapeHtml(roundRoundTitle(round))}">${won ? roundResultIcon(round) : ""}</span>`;
        })
        .join("")}
    </div>
  `;
}

function roundRoundTitle(round) {
  const side = round.winningTeamRole === "Attacker" ? "Ataque" : round.winningTeamRole === "Defender" ? "Defesa" : round.winningTeamRole || "";
  return [round.roundResult || "", side].filter(Boolean).join(" - ");
}

function roundSideClass(round) {
  return round.winningTeamRole === "Attacker" ? "side-attack" : round.winningTeamRole === "Defender" ? "side-defense" : "";
}

function roundResultIcon(round) {
  const icon = roundResultIconPath(round);
  const label = roundResultLabel(round);
  return icon ? `<img src="${escapeHtml(icon)}" alt="${escapeHtml(label)}" loading="lazy" onerror="this.remove()" />` : `<span>${escapeHtml(label.slice(0, 1))}</span>`;
}

function roundResultIconPath(round) {
  const code = String(round.roundResultCode || round.roundResult || "").toLowerCase();
  if (code.includes("defuse")) return "assets/rounds-icons/defuse.webp";
  if (code.includes("detonate") || code.includes("bomb")) return "assets/rounds-icons/boom.webp";
  if (code.includes("timer")) return "assets/rounds-icons/time.webp";
  return "assets/rounds-icons/elim.webp";
}

function roundResultLabel(round) {
  const code = String(round.roundResultCode || round.roundResult || "").toLowerCase();
  if (code.includes("defuse")) return "Defuse";
  if (code.includes("detonate") || code.includes("bomb")) return "Spike";
  if (code.includes("timer")) return "Tempo";
  return "Eliminação";
}

function hydrateMatchPlayers(players) {
  return players.map((player) => ({
    ...player,
    agentList: player.agentList?.length ? player.agentList : [{ slug: player.agentSlug, name: player.agent, icon: player.agentIcon, role: player.agentClass, rounds: player.rounds }],
  }));
}

function aggregateMatchPlayers(matches) {
  const byId = new Map();
  for (const match of matches) {
    for (const player of match.players) {
      if (!byId.has(player.id)) {
        byId.set(player.id, {
          ...player,
          matches: 0,
          maps: 0,
          score: 0,
          rounds: 0,
          kills: 0,
          deaths: 0,
          assists: 0,
          damage: 0,
          firstKills: 0,
          firstDeaths: 0,
          kastRounds: 0,
          impactTotal: 0,
          ...emptyRaatingAggregateFields(),
          headshots: 0,
          bodyshots: 0,
          legshots: 0,
          agents: new Map(),
        });
      }
      const row = byId.get(player.id);
      row.matches += 1;
      row.maps += 1;
      row.score += player.score;
      row.rounds += player.rounds;
      row.kills += player.kills;
      row.deaths += player.deaths;
      row.assists += player.assists;
      row.damage += player.damage;
      row.firstKills += player.firstKills;
      row.firstDeaths += player.firstDeaths;
      row.kastRounds += player.kastRounds;
      row.impactTotal += player.impactTotal;
      addRaatingAggregateFields(row, player);
      row.headshots += player.headshots;
      row.bodyshots += player.bodyshots;
      row.legshots += player.legshots;
      row.teamId = player.teamId || row.teamId;
      row.teamTag = player.teamTag || row.teamTag;
      const agentKey = player.agentSlug || player.agent;
      const existing = row.agents.get(agentKey) || { slug: player.agentSlug, name: player.agent, icon: player.agentIcon, role: player.agentClass, rounds: 0 };
      existing.rounds += player.rounds;
      row.agents.set(agentKey, existing);
    }
  }

  return [...byId.values()].map(finalizeAggregatePlayer);
}

function finalizeAggregatePlayer(player) {
  player.acs = player.rounds ? player.score / player.rounds : 0;
  player.adr = player.rounds ? player.damage / player.rounds : 0;
  player.kpr = player.rounds ? player.kills / player.rounds : 0;
  player.dpr = player.rounds ? player.deaths / player.rounds : 0;
  player.apr = player.rounds ? player.assists / player.rounds : 0;
  player.kd = player.deaths ? player.kills / player.deaths : player.kills;
  player.kastFrac = player.rounds ? player.kastRounds / player.rounds : 0;
  player.kast = player.kastFrac * 100;
  player.impactRound = player.rounds ? player.impactTotal / player.rounds : 0;
  player.impactRoundLegacy = player.rounds ? Number(player.impactTotalLegacy || 0) / player.rounds : 0;
  player.kastLegacyFrac = player.rounds ? Number(player.kastLegacyRounds || 0) / player.rounds : player.kastFrac;
  player.kastLegacy = player.kastLegacyFrac * 100;
  const shots = player.headshots + player.bodyshots + player.legshots;
  player.hs = shots ? (player.headshots / shots) * 100 : 0;
  applyRaatingFields(player);
  player.agentList = [...player.agents.values()].sort((a, b) => b.rounds - a.rounds);
  const topAgent = player.agentList[0];
  player.agent = topAgent?.name || player.agent;
  player.agentSlug = topAgent?.slug || player.agentSlug;
  player.agentIcon = topAgent?.icon || player.agentIcon;
  player.agentClass = topAgent?.role || player.agentClass;
  return player;
}

const SCOREBOARD_STANDARD_COLUMNS = [
  {
    key: "rating",
    col: "rating",
    label: "rAAting 3.0",
    summaryLabel: "rAAting 3.0",
    summaryTitle: "rAAting média dos jogadores, ponderada por rounds.",
    headingClass: "rating-heading",
    aggregate: "weighted",
    value: (player) => officialRatingValue(player),
    format: (value) => formatScoreboardNumber(value),
    cellFormat: (player) => playerRating(player),
    tone: (value) => ratingTone(value),
    cellTone: (player) => playerRatingTone(player),
    cellClass: "rating-cell",
    title: (player) => ratingBreakdownTooltip(player),
  },
  { key: "acs", col: "acs", label: "ACS", aggregate: "weighted", value: (player) => player.acs, format: (value) => formatScoreboardNumber(value, 0) },
  { key: "kills", col: "k", label: "K", value: (player) => player.kills, format: (value, average) => formatScoreboardNumber(value, average ? 1 : 0) },
  { key: "deaths", col: "d", label: "D", value: (player) => player.deaths, format: (value, average) => formatScoreboardNumber(value, average ? 1 : 0) },
  { key: "assists", col: "a", label: "A", value: (player) => player.assists, format: (value, average) => formatScoreboardNumber(value, average ? 1 : 0) },
  { key: "diff", col: "diff", label: "+/-", aggregate: "total", value: (player) => player.kills - player.deaths, format: (value, average) => (average ? formatScoreboardSignedDecimal(value) : formatScoreboardSigned(value)), tone: (value) => signedTone(value) },
  { key: "kast", col: "kast", label: "KAST", aggregate: "weighted", value: (player) => player.kast, format: (value) => formatScoreboardPercent(value) },
  { key: "adr", col: "adr", label: "ADR", aggregate: "weighted", value: (player) => player.adr, format: (value) => formatScoreboardNumber(value, 0) },
  { key: "swing", col: "swing", label: "Swing/R", headingClass: "case-heading", aggregate: "weighted", value: (player) => playerSwingPerRound(player), format: (value) => formatScoreboardSignedDecimal(value), tone: (value) => directionalTone(value) },
  { key: "multiKills", col: "mks", label: "MKs", value: (player) => playerMultiKillRounds(player), format: (value, average) => formatScoreboardNumber(value, average ? 1 : 0) },
  { key: "firstKills", col: "fk", label: "FK", value: (player) => player.firstKills, format: (value, average) => formatScoreboardNumber(value, average ? 1 : 0) },
  { key: "firstDeaths", col: "fd", label: "FD", value: (player) => player.firstDeaths, format: (value, average) => formatScoreboardNumber(value, average ? 1 : 0) },
  { key: "fkFdDiff", col: "fk-fd", label: "FK-FD", aggregate: "total", value: (player) => player.firstKills - player.firstDeaths, format: (value, average) => (average ? formatScoreboardSignedDecimal(value) : formatScoreboardSigned(value)), tone: (value) => signedTone(value) },
];

const SCOREBOARD_ADVANCED_COLUMNS = [
  SCOREBOARD_STANDARD_COLUMNS[0],
  { key: "kill_rating", col: "kill-rating", label: "KillRating", short: "Kill", grupo: "Componentes do rAAting", aggregate: "weighted", value: (player) => metricValue(player, "kill_rating"), format: (value) => formatScoreboardNumber(value) },
  { key: "damage_rating", col: "damage-rating", label: "DamageRating", short: "Dano", grupo: "Componentes do rAAting", aggregate: "weighted", value: (player) => metricValue(player, "damage_rating"), format: (value) => formatScoreboardNumber(value) },
  { key: "round_swing_rating", col: "round-swing-rating", label: "RoundSwingRating", short: "Swing", grupo: "Componentes do rAAting", aggregate: "weighted", value: (player) => metricValue(player, "round_swing_rating"), format: (value) => formatScoreboardNumber(value) },
  { key: "survival_rating", col: "survival-rating", label: "SurvivalRating", short: "Sobrev.", grupo: "Componentes do rAAting", aggregate: "weighted", value: (player) => metricValue(player, "survival_rating"), format: (value) => formatScoreboardNumber(value) },
  { key: "kast_rating", col: "kast-rating", label: "KASTRating", short: "KAST", grupo: "Componentes do rAAting", aggregate: "weighted", value: (player) => metricValue(player, "kast_rating"), format: (value) => formatScoreboardNumber(value) },
  { key: "multi_kill_rating", col: "multi-kill-rating", label: "MultiKillRating", short: "Multi", grupo: "Componentes do rAAting", aggregate: "weighted", value: (player) => metricValue(player, "multi_kill_rating"), format: (value) => formatScoreboardNumber(value) },
  { key: "ekpr", col: "ekpr", label: "eKPR", grupo: "Ajustado por economia", aggregate: "weighted", value: (player) => metricValue(player, "ekpr"), format: (value) => formatScoreboardNumber(value) },
  { key: "edpr", col: "edpr", label: "eDPR", grupo: "Ajustado por economia", aggregate: "weighted", value: (player) => metricValue(player, "edpr"), format: (value) => formatScoreboardNumber(value) },
  { key: "eadr", col: "eadr", label: "eADR", grupo: "Ajustado por economia", aggregate: "weighted", value: (player) => metricValue(player, "eadr"), format: (value) => formatScoreboardNumber(value, 0) },
  { key: "ekast", col: "ekast", label: "eKAST", grupo: "Ajustado por economia", aggregate: "weighted", value: (player) => metricValue(player, "ekast"), format: (value) => formatScoreboardPercent(value) },
  { key: "mk_per_r", col: "mk-r", label: "MK/R", aggregate: "weighted", value: (player) => metricValue(player, "mk_per_r"), format: (value) => formatScoreboardNumber(value) },
  { key: "swing", col: "swing", label: "Swing/R", headingClass: "case-heading", aggregate: "weighted", value: (player) => playerSwingPerRound(player), format: (value) => formatScoreboardSignedDecimal(value), tone: (value) => directionalTone(value) },
];

// No celular o scoreboard e uma linha por jogador com K, D, A e rAAting (como a
// HLTV), entao ele e sempre o padrao: os componentes do avancado nao cabem ali,
// e a chave Padrao/Avancado some no CSS.
function matchScoreboardMode() {
  if (window.matchMedia?.("(max-width: 640px)").matches) return "standard";
  return state.matchScoreboardMode === "advanced" ? "advanced" : "standard";
}

function scoreboardColumns(mode = matchScoreboardMode()) {
  return mode === "advanced" ? SCOREBOARD_ADVANCED_COLUMNS : SCOREBOARD_STANDARD_COLUMNS;
}

function scoreboardColgroup(columns = scoreboardColumns()) {
  const colNames = ["player", "agents", ...columns.map((column) => column.col)];
  return `<colgroup>${colNames.map((name) => `<col class="score-col-${name}" />`).join("")}</colgroup>`;
}

// O avancado tem treze colunas de numero. Para caber na largura da pagina sem
// rolar, o cabecalho usa o nome curto ("Kill", e nao "KillRating") e uma linha
// de cima diz de que familia ele e. O nome completo fica no rotulo de
// acessibilidade e o significado no title, como no padrao.
function scoreboardHeader(boardKey, columns = scoreboardColumns()) {
  const grupos = [];
  for (const column of columns) {
    const ultimo = grupos[grupos.length - 1];
    if (ultimo && ultimo.nome === (column.grupo || "")) ultimo.tamanho += 1;
    else grupos.push({ nome: column.grupo || "", tamanho: 1 });
  }
  const linhaDeGrupos = grupos.some((grupo) => grupo.nome)
    ? `<tr class="vp-sb-grupos"><th colspan="2"></th>${grupos.map((grupo) => (grupo.nome ? `<th colspan="${grupo.tamanho}" scope="colgroup">${escapeHtml(grupo.nome)}</th>` : `<th colspan="${grupo.tamanho}"></th>`)).join("")}</tr>`
    : "";
  return `
    ${linhaDeGrupos}
    <tr>
      <th>Jogador</th>
      <th>Agentes</th>
      ${columns.map((column) => scoreboardHeaderCell(boardKey, column)).join("")}
    </tr>
  `;
}

function scoreboardHeaderCell(boardKey, column) {
  // Com as duas equipes numa tabela so, a chave leva as duas ("a|b"); a seta
  // segue a primeira, que anda junto com a segunda.
  const current = state.matchScoreboardSort?.[String(boardKey).split("|")[0]];
  const active = current?.key === column.key;
  const direction = active ? current.direction : "";
  const indicator = direction === "asc" ? "^" : direction === "desc" ? "v" : "";
  const className = ["numeric", column.headingClass || "", active ? "sorted" : ""].filter(Boolean).join(" ");
  const nextLabel = direction === "asc" ? "decrescente" : direction === "desc" ? "padrão" : "crescente";
  return `
    <th class="${escapeHtml(className)}" aria-sort="${direction === "asc" ? "ascending" : direction === "desc" ? "descending" : "none"}">
      <button type="button" class="score-sort-button" data-board-key="${escapeHtml(boardKey)}" data-scoreboard-sort="${escapeHtml(column.key)}" aria-label="Ordenar por ${escapeHtml(column.label)}: ${nextLabel}" title="${escapeHtml(metricHint(column.label))}">
        <span>${escapeHtml(column.short || column.label)}</span><i aria-hidden="true">${escapeHtml(indicator)}</i>
      </button>
    </th>
  `;
}

function scoreboardTeamAverages(players, columns = scoreboardColumns()) {
  return columns.map((column) => {
    const value = scoreboardTeamMetricValue(players, column);
    const tone = column.tone?.(value) || "";
    const className = ["vlr-board-metric", tone].filter(Boolean).join(" ");
    const title = column.summaryTitle ? ` title="${escapeHtml(column.summaryTitle)}"` : "";
    return `<td class="${escapeHtml(className)}" data-col="${escapeHtml(column.key)}" data-label="${escapeHtml(column.short || column.label)}"${title}><small>${escapeHtml(column.summaryLabel || column.label)}</small><strong>${escapeHtml(formatScoreboardColumnValue(column, value, true))}</strong></td>`;
  }).join("");
}

function scoreboardTeamMetricValue(players, column) {
  if (!players.length) return 0;
  if (column.aggregate === "total") {
    return players.reduce((sum, player) => sum + Number(column.value(player) || 0), 0);
  }
  if (column.aggregate === "weighted") {
    return weightedAverage(players, column.value, (player) => Number(player.rounds || 0));
  }
  return avg(players.map((player) => column.value(player)));
}

function weightedAverage(rows, valueFn, weightFn) {
  const totals = rows.reduce(
    (acc, row) => {
      const value = Number(valueFn(row));
      const weight = Number(weightFn(row));
      if (!Number.isFinite(value) || !Number.isFinite(weight) || weight <= 0) return acc;
      acc.value += value * weight;
      acc.weight += weight;
      return acc;
    },
    { value: 0, weight: 0 },
  );
  return totals.weight ? totals.value / totals.weight : 0;
}

function signedDecimal(value, digits = 1) {
  if (value > 0) return `+${fmt(value, digits)}`;
  if (value < 0) return `-${fmt(Math.abs(value), digits)}`;
  return fmt(0, digits);
}

function scoreboardBoardKey(match, team) {
  const tab = route().tab || "map";
  return `${match.id}:${tab}:${matchScoreboardMode()}:${team.id}`;
}

function defaultScoreboardPlayers(players) {
  return players.slice().sort((a, b) => Number(officialRatingValue(b) || 0) - Number(officialRatingValue(a) || 0) || Number(playerSwingPerRound(b) || 0) - Number(playerSwingPerRound(a) || 0) || a.nick.localeCompare(b.nick));
}

function sortedScoreboardPlayers(match, team, players) {
  const defaultPlayers = defaultScoreboardPlayers(players);
  const current = state.matchScoreboardSort?.[scoreboardBoardKey(match, team)];
  const column = scoreboardColumns().find((item) => item.key === current?.key);
  if (!column || !current?.direction) return defaultPlayers;
  const direction = current.direction === "asc" ? 1 : -1;
  return defaultPlayers
    .map((player, index) => ({ player, index }))
    .sort((a, b) => {
      const valueA = Number(column.value(a.player) || 0);
      const valueB = Number(column.value(b.player) || 0);
      if (valueA !== valueB) return (valueA - valueB) * direction;
      return a.index - b.index;
    })
    .map((row) => row.player);
}

function cycleScoreboardSort(boardKey, key) {
  const current = state.matchScoreboardSort?.[boardKey];
  if (!state.matchScoreboardSort) state.matchScoreboardSort = {};
  if (!current || current.key !== key) {
    state.matchScoreboardSort[boardKey] = { key, direction: "asc" };
    return;
  }
  if (current.direction === "asc") {
    state.matchScoreboardSort[boardKey] = { key, direction: "desc" };
    return;
  }
  delete state.matchScoreboardSort[boardKey];
}

function bindScoreboardSort() {
  const page = document.querySelector(".match-page");
  page?.addEventListener("click", (event) => {
    const modeButton = event.target.closest("[data-match-scoreboard-mode]");
    if (modeButton) {
      setMatchScoreboardMode(modeButton.dataset.matchScoreboardMode);
      return;
    }
    const button = event.target.closest("[data-scoreboard-sort]");
    if (!button) return;
    String(button.dataset.boardKey).split("|").forEach((chave) => cycleScoreboardSort(chave, button.dataset.scoreboardSort));
    renderMatchDetail(route().id);
  });
}

function setMatchScoreboardMode(mode) {
  const next = mode === "advanced" ? "advanced" : "standard";
  if (state.matchScoreboardMode === next) return;
  state.matchScoreboardMode = next;
  renderMatchDetail(route().id);
}

function formatScoreboardColumnValue(column, value, average = false) {
  return column.format ? column.format(value, average) : formatScoreboardNumber(value, average ? 1 : 0);
}

function formatScoreboardNumber(value, digits = 2) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? fmt(numeric, digits) : "-";
}

function formatScoreboardPercent(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? pct(numeric) : "-";
}

function formatScoreboardSigned(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? signed(numeric) : "-";
}

function formatScoreboardSignedDecimal(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? signedDecimal(numeric) : "-";
}

function scoreboardRow(player, columns = scoreboardColumns(), escolha = null) {
  const marca = escolha?.compareKey
    ? ` class="vp-sb-jogador${escolha.escolhido ? " vp-escolhido" : ""}" tabindex="0" data-lineup-key="${escapeHtml(escolha.compareKey)}" data-lineup-side="${escapeHtml(escolha.side)}" data-lineup-player="${escapeHtml(player.id)}"`
    : "";
  return `
    <tr${marca}>
      <td>${entityLink("players", player.id, player.nick)}<br><span class="tiny">${escapeHtml(playerMatchHandle(player))}</span></td>
      <td>${agentStack(player)}</td>
      ${columns.map((column) => scoreboardCell(player, column)).join("")}
    </tr>
  `;
}

function scoreboardCell(player, column) {
  const value = column.value(player);
  const tone = column.cellTone?.(player) || column.tone?.(value, player) || "";
  const className = ["numeric", column.cellClass || "", tone].filter(Boolean).join(" ");
  const title = column.title?.(player);
  const titleAttr = title ? ` title="${escapeHtml(title)}" tabindex="0"` : "";
  const display = column.cellFormat ? column.cellFormat(player, value) : formatScoreboardColumnValue(column, value, false);
  // data-label e o rotulo do numero no celular, onde a linha vira um bloco e o
  // cabecalho de colunas fica longe demais para ser lido.
  return `<td class="${escapeHtml(className)}" data-col="${escapeHtml(column.key)}" data-label="${escapeHtml(column.short || column.label)}"${titleAttr}>${escapeHtml(display)}</td>`;
}

function playerMatchHandle(player) {
  const nick = player.apiNick || player.nick || "Jogador";
  if (player.tagLine) return `${nick}#${player.tagLine}`;
  return player.handle || nick;
}

function agentStack(player) {
  const agents = (player.agentList?.length ? player.agentList : [{ slug: player.agentSlug, name: player.agent, icon: player.agentIcon, role: player.agentClass }]).slice(0, 4);
  return `<span class="agent-stack">${agents.map(agentMiniIcon).join("")}</span>`;
}

function agentMiniIcon(agent) {
  const label = displayAgentName(agent.name, agent.slug).slice(0, 2).toUpperCase();
  const image = agent.icon ? `<img src="${escapeHtml(assetPath(agent.icon))}" alt="${escapeHtml(agent.name || label)}" loading="lazy" onerror="this.remove()" />` : "";
  return `<span class="agent-mini" title="${escapeHtml(agent.name || label)}"><span>${escapeHtml(label)}</span>${image}</span>`;
}

function roleMiniIcon(role) {
  const info = role || { label: "Classe", icon: "", rounds: 0 };
  const title = `${info.label}${info.rounds ? ` - ${info.rounds} rounds` : ""}`;
  const image = info.icon ? `<img src="${escapeHtml(assetPath(info.icon))}" alt="${escapeHtml(info.label)}" loading="lazy" onerror="this.remove()" />` : "";
  const fallback = image ? "" : `<span>${escapeHtml(info.label.slice(0, 2).toUpperCase())}</span>`;
  return `<span class="role-mini" title="${escapeHtml(title)}">${fallback}${image}</span>`;
}

function roleDisplayInfo(role) {
  const key = normalizeRoleKey(role);
  if (key && ROLE_ICONS[key]) return { ...ROLE_ICONS[key], key };
  const label = displayEntityName(role || "Classe");
  return { key: "", label: label || "Classe", icon: "" };
}

function rolePill(role, extra = "") {
  const info = roleDisplayInfo(role);
  return `<span class="role-pill ${escapeHtml(extra)}">${roleMiniIcon(info)}<span>${escapeHtml(info.label)}</span></span>`;
}

function playerDominantRole(player) {
  const agents = player.agentList?.length
    ? player.agentList
    : player.agentStats?.length
      ? player.agentStats
    : [{ role: player.agentClass, rounds: player.rounds, name: player.agent, slug: player.agentSlug }];
  const roles = new Map();
  agents.forEach((agent, index) => {
    const key = normalizeRoleKey(agent.role || agent.agentClass || "");
    if (!key) return;
    const current = roles.get(key) || { ...ROLE_ICONS[key], key, rounds: 0, firstIndex: index };
    current.rounds += Number(agent.rounds || 0);
    roles.set(key, current);
  });
  return [...roles.values()].sort((a, b) => b.rounds - a.rounds || a.firstIndex - b.firstIndex)[0] || null;
}

function normalizeRoleKey(value) {
  const key = slugify(value);
  if (["controller", "controlador", "controladora"].includes(key)) return "controlador";
  if (["duelist", "duelista"].includes(key)) return "duelista";
  if (["initiator", "iniciador", "iniciadora"].includes(key)) return "iniciador";
  if (["sentinel", "sentinela"].includes(key)) return "sentinela";
  return "";
}

function lineupScalePlayers(playersA, playersB) {
  const fallbackPlayers = [...playersA.slice(0, 5), ...playersB.slice(0, 5)].map(lineupHistoricalPlayer);
  const historicalPlayers = (state.db?.players || []).filter((player) => Number(player.matches || 0) > 0);
  return [...historicalPlayers, ...fallbackPlayers];
}

function lineupCompareKey(match) {
  return `${match.id}:${route().tab || "map"}`;
}

function ensureLineupCompareSelection(compareKey, playersA, playersB) {
  if (!state.matchLineupCompare) state.matchLineupCompare = {};
  const current = state.matchLineupCompare[compareKey] || {};
  const fallback = {
    a: playersA[0]?.id || "",
    b: playersB[0]?.id || "",
  };
  const selection = {
    a: playersA.some((player) => player.id === current.a) ? current.a : fallback.a,
    b: playersB.some((player) => player.id === current.b) ? current.b : fallback.b,
  };
  state.matchLineupCompare[compareKey] = selection;
  return selection;
}

function lineupStatScales(players) {
  return Object.fromEntries(lineupStatRows().map((row) => [row.key, lineupSingleStatScale(row, players)]));
}

function lineupSingleStatScale(row, players) {
  const values = players.map((player) => Number(row.value(player))).filter((value) => Number.isFinite(value));
  const min = values.length ? Math.min(...values) : 0;
  const max = values.length ? Math.max(...values) : 0;
  return { min, max };
}

function lineupMetricLevel(value, scale) {
  const numeric = Number(value) || 0;
  const min = Number(scale?.min || 0);
  const max = Number(scale?.max || 0);
  if (max <= min) return 64;
  return Math.round(clamp(((numeric - min) / (max - min)) * 100, 8, 100));
}

function lineupStatRows() {
  return [
    { key: "rating", label: "rAAting 3.0", value: (player) => officialRatingValue(player) || 0, format: (value, player) => playerRating(player) },
    { key: "acs", label: "ACS", value: (player) => player.acs || 0, format: (value) => fmt(value, 0) },
    { key: "kd", label: "K/D", value: (player) => player.kd || 0, format: (value) => fmt(value) },
    { key: "kast", label: "KAST", value: (player) => player.kast || 0, format: (value) => pct(value) },
    { key: "adr", label: "ADR", value: (player) => player.adr || 0, format: (value) => fmt(value, 0) },
    { key: "impactRound", label: "Swing/R", value: (player) => playerSwingPerRound(player) || 0, format: (value) => signedDecimal(value) },
    { key: "hs", label: "HS%", value: (player) => player.hs || 0, format: (value) => pct(value) },
    { key: "matches", label: "Partidas", value: (player) => player.matches || 0, format: (value) => fmt(value, 0) },
  ];
}

function lineupHistoricalPlayer(player) {
  const historical = playerById(player.id);
  if (!historical) return { ...player, matches: player.matches ?? 1 };
  return {
    ...historical,
    matchPlayer: player,
    agentList: player.agentList?.length ? player.agentList : historical.agentStats || historical.agentList || [],
    teamTag: player.teamTag || historical.teamTag,
  };
}

function bindLineupCompare() {
  const page = document.querySelector(".match-page");
  if (!page) return;
  const escolher = (alvo) => {
    const key = alvo.dataset.lineupKey;
    const side = alvo.dataset.lineupSide;
    const playerId = alvo.dataset.lineupPlayer;
    if (!key || !side || !playerId) return;
    if (!state.matchLineupCompare) state.matchLineupCompare = {};
    state.matchLineupCompare[key] = {
      ...(state.matchLineupCompare[key] || {}),
      [side]: playerId,
    };
    renderMatchDetail(route().id);
  };
  page.addEventListener("click", (event) => {
    const alvo = event.target.closest("[data-lineup-player]");
    if (!alvo) return;
    // O nick na linha do scoreboard e link para o jogador: ali o clique navega.
    if (alvo.tagName === "TR" && event.target.closest("a")) return;
    escolher(alvo);
  });
  page.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    const alvo = event.target.closest("tr[data-lineup-player]");
    if (!alvo || event.target !== alvo) return;
    event.preventDefault();
    escolher(alvo);
  });
}

function playerPortrait(player) {
  const src = playerPhotoSrc(player);
  const classes = `player-portrait${player?.photo ? "" : " fallback"}`;
  return `<span class="${escapeHtml(classes)}"><img src="${escapeHtml(src)}" alt="${escapeHtml(player?.nick || "Jogador")}" loading="lazy" onerror="playerPhotoError(this)" /></span>`;
}

// "Rank 10" para a ponta de cada equipe no topo e nas lineups; equipe fora do
// ranking valido fica com o rotulo que o site ja usa para ela.
function placarRankRotulo(teamId) {
  const cadastro = teamById(teamId);
  if (!cadastro) return "";
  const rank = String(teamShortRankLabel(cadastro) || "");
  return rank.startsWith("#") ? `Rank ${rank.slice(1)}` : rank;
}

// Uma ponta do placar da serie: a equipe do seu lado, pintada com a cor dela.
// O placar grande do topo: quem venceu em verde, quem perdeu apagado, e no
// empate (mapa em andamento) os dois ficam na cor normal.
function placarHeroNumeros(a, b) {
  const classe = (valor, contra) => (Number(valor) > Number(contra) ? ' class="vp-venceu"' : Number(valor) < Number(contra) ? ' class="vp-perdeu"' : "");
  return `<span class="vp-hero-numeros"><b${classe(a, b)}>${escapeHtml(a)}</b><i>:</i><b${classe(b, a)}>${escapeHtml(b)}</b></span>`;
}

function placarHeroLado(team, side) {
  const rotulo = placarRankRotulo(team.id);
  return `<a class="vp-hero-lado vp-lado-${side}" href="#/teams/${escapeHtml(team.id)}" style="--team-line:${teamLineColor(team.id)}">${teamLogo(team.id, "large")}<span><strong>${escapeHtml(team.name)}</strong>${rotulo ? `<small>${escapeHtml(rotulo)}</small>` : ""}</span></a>`;
}

// A barra espelhada do comparativo e do historico: o valor de cada lado e o
// rotulo no meio em cima, e embaixo uma barra que cresce do centro para cada
// lado, na cor de cada equipe. O maior valor fica aceso; o menor, a meia luz.
function espelhoLinha({ label, valorA, valorB, fracA = "", fracB = "", larguraA = 0, larguraB = 0, maiorA = false, maiorB = false, corA = TEAM_LINE_SEM_COR, corB = TEAM_LINE_SEM_COR }) {
  return `
    <div class="vp-espelho">
      <span class="vp-espelho-v vp-espelho-a${maiorA ? " vp-maior" : ""}">${escapeHtml(valorA)}${fracA ? `<small>${escapeHtml(fracA)}</small>` : ""}</span>
      <span class="vp-espelho-rotulo">${escapeHtml(label)}</span>
      <span class="vp-espelho-v vp-espelho-b${maiorB ? " vp-maior" : ""}">${fracB ? `<small>${escapeHtml(fracB)}</small>` : ""}${escapeHtml(valorB)}</span>
      <span class="vp-espelho-barras" aria-hidden="true"><span style="--team-line:${corA}"><i class="${maiorA ? "vp-maior" : ""}" style="--w:${Math.round(clamp(Number(larguraA) || 0, 0, 100))}%"></i></span><span style="--team-line:${corB}"><i class="${maiorB ? "vp-maior" : ""}" style="--w:${Math.round(clamp(Number(larguraB) || 0, 0, 100))}%"></i></span></span>
    </div>
  `;
}

// O comparativo virou faixa logo abaixo das abas de mapa: e resumo do que esta
// selecionado (a serie ou o mapa), e cada equipe fica do mesmo lado em que
// aparece no placar. As barras usam a cor de cada equipe, nao o vermelho.
function comparativoFaixa(match, selectedMatches = [match]) {
  const linhas = (team) => {
    const stats = aggregateTeamStatsForMatches(selectedMatches, team.id);
    const ganhos = selectedMatches.reduce((sum, item) => sum + scoreForTeamInMatch(item, team.id), 0);
    const total = selectedMatches.reduce((sum, item) => sum + Number(item.teamA.score || 0) + Number(item.teamB.score || 0), 0);
    return [
      ["Rounds", ganhos, total],
      ["Ataque", stats.attackWins, stats.attackRounds],
      ["Defesa", stats.defenseWins, stats.defenseRounds],
      ["Pistols", stats.pistolWins, stats.pistolRounds],
    ];
  };
  const a = linhas(match.teamA);
  const b = linhas(match.teamB);
  const corA = teamLineColor(match.teamA.id);
  const corB = teamLineColor(match.teamB.id);
  return `
    <section class="vp-comparativo" aria-label="Comparativo">
      ${a
        .map(([label, ganhosA, totalA], i) => {
          const [, ganhosB, totalB] = b[i];
          const pa = pctValue(ganhosA, totalA);
          const pb = pctValue(ganhosB, totalB);
          return espelhoLinha({ label, valorA: pct(pa), valorB: pct(pb), fracA: `${ganhosA}/${totalA}`, fracB: `${ganhosB}/${totalB}`, larguraA: pa, larguraB: pb, maiorA: pa > pb, maiorB: pb > pa, corA, corB });
        })
        .join("")}
    </section>
  `;
}

// As duas equipes numa tabela so, com o cabecalho de colunas uma vez. O
// cabecalho ordena as duas pela mesma coluna (data-board-key leva as duas
// chaves). Cada equipe e um tbody que abre com a linha dela, pintada com a cor
// e com as medias; clicar num jogador escolhe quem vai para o historico.
function placarScoreboard(match, lados, columns = scoreboardColumns(), escolha = {}) {
  const chaves = lados.map(({ team }) => scoreboardBoardKey(match, team));
  const modeClass = columns === SCOREBOARD_ADVANCED_COLUMNS ? "scoreboard-advanced" : "scoreboard-standard";
  return `
    <div class="vp-sb-wrap">
      <table class="vp-sb match-scoreboard ${escapeHtml(modeClass)}">
        ${scoreboardColgroup(columns)}
        <thead>${scoreboardHeader(chaves.join("|"), columns)}</thead>
        ${lados
          .map(
            ({ team, players, side }) => `
          <tbody style="--team-line:${teamLineColor(team.id)}">
            <tr class="vp-sb-equipe"><th colspan="2" scope="rowgroup"><span class="vp-sb-equipe-nome">${teamLogo(team.id)}<strong>${escapeHtml(team.name)}</strong><small>${escapeHtml(team.sourceTag || team.tag || "")}</small></span></th>${scoreboardTeamAverages(players, columns)}</tr>
            ${players.map((player) => scoreboardRow(player, columns, { compareKey: escolha.compareKey, side, escolhido: escolha.selection?.[side] === player.id })).join("")}
          </tbody>`,
          )
          .join("")}
      </table>
    </div>
  `;
}

// Lineups e historico sao uma secao so: as fotos das duas equipes lado a lado
// e, logo embaixo, as barras dos dois jogadores escolhidos. Clicar numa foto
// (ou numa linha do scoreboard, para chegar num reserva) troca quem aparece.
function matchLineupsSecao(compareKey, selection, teamA, lineupA, teamB, lineupB, escolhiveisA = lineupA, escolhiveisB = lineupB) {
  return `
    <section class="vp-s-lineups">
      ${sectionHead("Lineups")}
      ${matchLineupBands(compareKey, selection, teamA, lineupA, teamB, lineupB)}
      <div class="vp-historico">${matchLineupDuel(selection, teamA, escolhiveisA, teamB, escolhiveisB)}</div>
    </section>
  `;
}

// As lineups lado a lado, com a foto solta e o icone da funcao. Clicar numa
// foto escolhe o jogador do historico.
function matchLineupBands(compareKey, selection, teamA, playersA, teamB, playersB) {
  const banda = (team, players, side) => {
    const rotulo = placarRankRotulo(team.id);
    return `
      <section class="vp-banda" style="--team-line:${teamLineColor(team.id)}" aria-label="${escapeHtml(team.name)}">
        <div class="vp-banda-cab">${teamLogo(team.id)}<strong>${escapeHtml(team.name)}</strong>${rotulo ? `<small>${escapeHtml(rotulo)}</small>` : ""}</div>
        <div class="vp-banda-fotos">${players
          .slice(0, 5)
          .map((player) => {
            const ativo = selection?.[side] === player.id;
            return `<button type="button" class="vp-quem" data-lineup-key="${escapeHtml(compareKey)}" data-lineup-side="${side}" data-lineup-player="${escapeHtml(player.id)}" aria-pressed="${ativo}">${playerPortrait(lineupHistoricalPlayer(player))}<span class="vp-quem-nome">${roleMiniIcon(playerDominantRole(player))}<span>${escapeHtml(player.nick)}</span></span></button>`;
          })
          .join("")}</div>
      </section>
    `;
  };
  return `<div class="vp-lineups">${banda(teamA, playersA, "a")}${banda(teamB, playersB, "b")}</div>`;
}

// O historico dos dois escolhidos: media de todas as partidas de cada um, em
// barras espelhadas. A barra mostra onde cada um esta na escala dos jogadores
// da partida, a mesma escala do comparativo de antes.
function matchLineupDuel(selection, teamA, playersA, teamB, playersB) {
  const escolhidoA = playersA.find((player) => player.id === selection?.a) || playersA[0];
  const escolhidoB = playersB.find((player) => player.id === selection?.b) || playersB[0];
  if (!escolhidoA || !escolhidoB) return `<div class="empty-state">Selecione jogadores dos dois lados para comparar.</div>`;
  const left = lineupHistoricalPlayer(escolhidoA);
  const right = lineupHistoricalPlayer(escolhidoB);
  const scales = lineupStatScales([...lineupScalePlayers(playersA, playersB), left, right]);
  const corA = teamLineColor(teamA.id);
  const corB = teamLineColor(teamB.id);
  const cabeca = (team, historical, matchPlayer, side) => `<a class="vp-duelo-quem vp-duelo-${side}" href="${playerHref(matchPlayer)}"><strong>${escapeHtml(historical.nick || matchPlayer.nick)}</strong><small>${escapeHtml(team.sourceTag || team.tag || "")}</small></a>`;
  return `
    <div class="vp-duelo">
      <div class="vp-duelo-cab">${cabeca(teamA, left, escolhidoA, "a")}<span class="vp-duelo-titulo">Histórico, média de todas as partidas</span>${cabeca(teamB, right, escolhidoB, "b")}</div>
      <div class="vp-duelo-barras">${lineupStatRows()
        .map((row) => {
          const va = Number(row.value(left)) || 0;
          const vb = Number(row.value(right)) || 0;
          return espelhoLinha({ label: row.label, valorA: row.format(va, left), valorB: row.format(vb, right), larguraA: lineupMetricLevel(va, scales[row.key]), larguraB: lineupMetricLevel(vb, scales[row.key]), maiorA: va > vb, maiorB: vb > va, corA, corB });
        })
        .join("")}</div>
    </div>
  `;
}

// O melhor da partida usa o mesmo cartao do jogador da semana (plateCard),
// parado, e as quatro estatisticas de apoio numa linha embaixo.
function matchMvpCard(player, mapCount) {
  if (!player) return `<section class="vp-s-mvp">${sectionHead("Melhor da partida")}<div class="empty-state">Sem jogadores para calcular MVP.</div></section>`;
  const team = teamById(player.teamId);
  const tag = team?.sourceTag || team?.tag || player.teamTag || "";
  return `
    <section class="vp-s-mvp">
      ${sectionHead("Melhor da partida")}
      ${plateCard({
        classe: "vp-slide vp-mvp",
        team,
        href: playerHref(player),
        nome: player.nick,
        figura: playerFigure(lineupHistoricalPlayer(player), team, "vp-slide-foto"),
        rotulo: mapCount > 1 ? "Melhor da série" : "Melhor do mapa",
        tag,
        valor: playerRating(player),
        apoio: `rAAting 3.0, ${player.rounds || 0} rounds`,
      })}
      <div class="vp-mvp-stats"><span><small>ACS</small><b>${escapeHtml(fmt(player.acs, 0))}</b></span><span><small>KAST</small><b>${escapeHtml(pct(player.kast))}</b></span><span><small>ADR</small><b>${escapeHtml(fmt(player.adr, 0))}</b></span><span><small>Swing/R</small><b>${escapeHtml(`${signedDecimal(playerSwingPerRound(player))} pp`)}</b></span></div>
    </section>
  `;
}

function playerRating(player) {
  if (Object.prototype.hasOwnProperty.call(player || {}, "matches") && Number(player.matches || 0) <= 0) return "---";
  const rating = officialRatingValue(player);
  return Number.isFinite(rating) ? fmt(rating) : "-";
}

function playerRatingTone(player) {
  if (Object.prototype.hasOwnProperty.call(player || {}, "matches") && Number(player.matches || 0) <= 0) return "";
  return ratingTone(officialRatingValue(player));
}

function ratingTone(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "";
  if (numeric >= 1.25) return "perf-strong";
  if (numeric >= 1.15) return "perf-good";
  if (numeric >= 1.05) return "perf-positive";
  if (numeric < 0.85) return "perf-danger";
  if (numeric < 0.95) return "perf-bad";
  return "perf-neutral";
}

function signedTone(value) {
  const numeric = Number(value || 0);
  if (numeric >= 10) return "perf-strong";
  if (numeric >= 5) return "perf-good";
  if (numeric > 0) return "perf-positive";
  if (numeric <= -10) return "perf-danger";
  if (numeric <= -5) return "perf-bad";
  if (numeric < 0) return "perf-negative";
  return "perf-neutral";
}

function directionalTone(value) {
  const numeric = Number(value || 0);
  if (numeric > 0) return "perf-positive";
  if (numeric < 0) return "perf-negative";
  return "perf-neutral";
}

function metricValue(row, key, fallbackKey = "") {
  if (Object.prototype.hasOwnProperty.call(row || {}, key)) {
    const value = Number(row?.[key]);
    if (Number.isFinite(value)) return value;
  }
  if (fallbackKey && Object.prototype.hasOwnProperty.call(row || {}, fallbackKey)) {
    const fallback = Number(row?.[fallbackKey]);
    if (Number.isFinite(fallback)) return fallback;
  }
  return NaN;
}

function officialRatingValue(player) {
  const primary = metricValue(player, "raating_3");
  if (Number.isFinite(primary)) return primary;
  if (player?.rating_version && player.rating_version !== "raa3") return NaN;
  return metricValue(player, "rating");
}

function playerSwingPerRound(player) {
  return metricValue(player, "adjusted_swing_percent", "impactRound");
}

function playerMultiKillRounds(player) {
  const roundCount = Number(player?.multi_kill_rounds);
  if (Number.isFinite(roundCount) && roundCount > 0) return roundCount;
  const counted = Number(player?.twoKills || 0) + Number(player?.threeKills || 0) + Number(player?.fourKills || 0) + Number(player?.fiveKills || 0);
  if (counted > 0) return counted;
  const points = Number(player?.multiKillPoints ?? player?.multi_kill_points);
  return Number.isFinite(points) ? points : 0;
}

function formatMaybeMetric(row, key, digits = 2, fallbackKey = "") {
  const value = metricValue(row, key, fallbackKey);
  return Number.isFinite(value) ? fmt(value, digits) : "-";
}

function formatMaybePercent(row, key, fallbackKey = "") {
  const value = metricValue(row, key, fallbackKey);
  return Number.isFinite(value) ? pct(value) : "-";
}

function formatMaybeSwing(row) {
  const value = playerSwingPerRound(row);
  return Number.isFinite(value) ? `${signedDecimal(value)} pp` : "-";
}

function sampleStatusChip(player) {
  if (!player || isOfficialRatingSample(player) || Number(player.matches || 0) <= 0) return "";
  return `<span class="chip low-sample-chip" title="Fora do ranking oficial: menos de ${RaaRatingCore.SAMPLE_MIN_ROUNDS} rounds jogados.">baixa amostra</span>`;
}

function ratingFormulaText(separator = "\n") {
  return [
    "rAAting 3.0 =",
    "25% Kills",
    "+ 15% Dano",
    "+ 4% Multi-kills",
    "+ 33% Round Swing",
    "+ 15% Sobrevivência",
    "+ 8% KAST",
  ].join(separator);
}

function ratingBreakdownTooltip(player) {
  return [
    `rAAting 3.0: ${playerRating(player)}`,
    "",
    "Composição:",
    `KillRating: ${formatMaybeMetric(player, "kill_rating")}`,
    `DamageRating: ${formatMaybeMetric(player, "damage_rating")}`,
    `RoundSwingRating: ${formatMaybeMetric(player, "round_swing_rating")}`,
    `SurvivalRating: ${formatMaybeMetric(player, "survival_rating")}`,
    `KASTRating: ${formatMaybeMetric(player, "kast_rating")}`,
    `MultiKillRating: ${formatMaybeMetric(player, "multi_kill_rating")}`,
    "",
    ratingFormulaText("\n"),
  ].join("\n");
}

function patchLabel(version) {
  const match = String(version || "").match(/release-([0-9.]+)/i);
  return match?.[1] || version || "-";
}

function renderTournamentDetail(id) {
  // O id do campeonato abre o Geral; o de uma etapa abre a mesma pagina com a etapa
  // marcada na faixa. Os links antigos (todos de etapa) continuam valendo.
  const campeonatoGeral = campeonatoPorId(id);
  const etapa = campeonatoGeral ? null : visibleTournaments().find((item) => item.id === id);
  if (!campeonatoGeral && !etapa) return renderNotFound("Campeonato");
  const campeonato = campeonatoGeral || campeonatoDaEtapa(etapa);
  const event = campeonatoGeral ? eventoDoGeral(campeonatoGeral) : etapa;
  // O topo de uma etapa usa o agregado (nome, datas, status, capa): montar o Geral
  // inteiro so para o topo custava a colocacao e um ranking historico por abertura.
  const cabeca = campeonatoGeral ? event : campeonato || event;
  const matches = matchSeriesForEvent(event.id);
  const standings = tournamentStandingsRows(event, matches);
  const activeTab = tournamentActiveTab();
  // Dentro de um campeonato, trocar de etapa (ou ir ao Geral) tambem desliza: o
  // escopo e o campeonato e a chave e etapa + aba, na ordem da faixa.
  const paginas = campeonato ? [campeonato.id, ...campeonato.etapas.map((item) => item.id)] : [event.id];
  const tabTransition = panelSlideSnapshot("tournament-tabs", {
    selector: ".tournament-tab-panel",
    scope: campeonato ? campeonato.id : event.id,
    key: `${event.id}|${activeTab}`,
    order: paginas.flatMap((pagina) => TOURNAMENT_TAB_KEYS.map((aba) => `${pagina}|${aba}`)),
  });
  Shell(`
    <article class="tournament-hub">
      <div class="vp-camp-cabeca">
        ${tournamentHero(cabeca)}
        ${campeonato ? tournamentEtapasNav(event, campeonato, activeTab) : ""}
        ${tournamentTabNav(event, activeTab)}
      </div>
      <div class="tournament-tab-panel">
        ${tournamentTabContent(event, matches, standings, activeTab)}
      </div>
      ${window.Comments ? window.Comments.shell("event", event.id) : ""}
    </article>
  `);
  window.Comments?.montar("event", event.id);
  if (activeTab === "overview") {
    bindTournamentBracketPreview(event, matches);
    bindTournamentTeamPreview(event, matches);
    bindVisaoGeralDoCampeonato();
  } else if (activeTab === "jogos") {
    bindJogosDoCampeonato();
  } else if (activeTab === "estatisticas" || activeTab === "agentes") {
    bindTournamentStatsControls(event.id);
    bindEstatisticasDoCampeonato();
  } else if (activeTab === "mapas") {
    bindMapasDoCampeonato();
  }
  playPanelSlide(tabTransition);
}

const TOURNAMENT_TAB_KEYS = ["overview", "jogos", "estatisticas", "mapas", "agentes"];

function tournamentActiveTab() {
  const tab = route().tab === "composicoes" ? "agentes" : route().tab || "overview";
  return TOURNAMENT_TAB_KEYS.includes(tab) ? tab : "overview";
}

// Trocar de aba/secao re-renderiza a pagina inteira, entao o conteudo que esta
// saindo e guardado antes do Shell para o slide ter os dois lados (mesma
// transicao do line-up da equipe, onde os dois paineis vivem juntos no DOM).
// <details> abre e fecha na hora; a animacao roda na altura do corpo do filtro,
// entao o toggle nativo e substituido por um controlado.
function bindFilterDropdownMotion() {
  document.addEventListener("click", (clickEvent) => {
    const summary = clickEvent.target.closest?.(".filter-dropdown > summary");
    const details = summary?.parentElement;
    const body = details?.querySelector(":scope > .filter-dropdown-body");
    if (!summary || !body) return;
    clickEvent.preventDefault();
    if (details.dataset.motion === "running") return;
    details.dataset.motion = "running";
    const opening = !details.open;
    if (opening) details.open = true;
    body.style.overflow = "hidden";
    body.style.height = `${opening ? 0 : body.scrollHeight}px`;

    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      body.style.height = "";
      body.style.overflow = "";
      body.style.transition = "";
      delete details.dataset.motion;
      if (!opening) details.open = false;
    };
    body.addEventListener("transitionend", (motionEvent) => {
      if (motionEvent.target === body && motionEvent.propertyName === "height") finish();
    });
    setTimeout(finish, PANEL_SLIDE_MS * 3);

    let started = false;
    const start = () => {
      if (started || done) return;
      started = true;
      body.style.transition = `height ${PANEL_SLIDE_MS}ms ease`;
      body.style.height = `${opening ? body.scrollHeight : 0}px`;
    };
    requestAnimationFrame(start);
    setTimeout(start, 32);
  });
}

function panelSlideSnapshot(group, { selector, scope, key, order = [] }) {
  const previous = panelSlideViews[group];
  panelSlideViews[group] = { scope, key };
  if (!previous || previous.scope !== scope || previous.key === key) return null;
  const panel = document.querySelector(selector);
  if (!panel || !panel.firstChild) return null;
  return {
    selector,
    html: panel.innerHTML,
    height: Math.round(panel.getBoundingClientRect().height),
    forward: panelSlideOrderIndex(order, key) > panelSlideOrderIndex(order, previous.key),
  };
}

// Chave fora da ordem conhecida (ex.: pagina de detalhe) conta como "mais para
// dentro": entrar desliza para frente e voltar desliza para tras.
function panelSlideOrderIndex(order, key) {
  const index = order.indexOf(key);
  return index >= 0 ? index : order.length;
}

function playPanelSlide(snapshot) {
  const panel = snapshot ? document.querySelector(snapshot.selector) : null;
  if (!panel || !panel.firstChild) return;
  const incoming = document.createElement("div");
  incoming.className = "panel-slide";
  // Move os nos (em vez de copiar o HTML) para nao perder os listeners ja ligados.
  while (panel.firstChild) incoming.appendChild(panel.firstChild);
  const outgoing = document.createElement("div");
  outgoing.className = "panel-slide";
  outgoing.innerHTML = snapshot.html;
  applyPanelSlideLayout(panel, [outgoing, incoming]);
  const track = document.createElement("div");
  track.className = "panel-slide-track";
  track.append(...(snapshot.forward ? [outgoing, incoming] : [incoming, outgoing]));
  panel.classList.add("panel-sliding");
  panel.style.height = `${snapshot.height}px`;
  panel.appendChild(track);
  track.style.transform = snapshot.forward ? "translateX(0)" : "translateX(-50%)";

  let done = false;
  const finish = () => {
    if (done) return;
    done = true;
    while (incoming.firstChild) panel.appendChild(incoming.firstChild);
    track.remove();
    panel.classList.remove("panel-sliding");
    panel.style.height = "";
  };
  track.addEventListener("transitionend", (animationEvent) => {
    if (animationEvent.target === track && animationEvent.propertyName === "transform") finish();
  });
  setTimeout(finish, PANEL_SLIDE_MS * 3);

  // rAF da o frame certo para o transform inicial "pegar"; o timeout cobre o caso
  // de a aba do navegador estar em segundo plano, onde o rAF nao roda.
  let started = false;
  const start = () => {
    if (started || done) return;
    started = true;
    track.classList.add("animating");
    track.style.transform = snapshot.forward ? "translateX(-50%)" : "translateX(0)";
    // A altura de origem veio do bounding box (com padding), entao a de destino
    // tambem precisa somar o padding do painel para nao saltar no fim.
    panel.style.height = `${incoming.scrollHeight + panelVerticalPadding(panel)}px`;
  };
  requestAnimationFrame(start);
  setTimeout(start, 32);
}

function panelVerticalPadding(panel) {
  const style = typeof getComputedStyle === "function" ? getComputedStyle(panel) : null;
  if (!style || style.boxSizing !== "border-box") return 0;
  return (parseFloat(style.paddingTop) || 0) + (parseFloat(style.paddingBottom) || 0);
}

// Cada lado do slide precisa se comportar como o painel original, senao o
// conteudo perde o grid/gap enquanto a animacao roda.
function applyPanelSlideLayout(panel, slides) {
  const style = typeof getComputedStyle === "function" ? getComputedStyle(panel) : null;
  const display = style?.display === "grid" || style?.display === "flex" ? style.display : "block";
  const gap = style?.gap && style.gap !== "normal" ? style.gap : "";
  slides.forEach((slide) => {
    slide.style.display = display;
    if (gap) slide.style.gap = gap;
    if (display === "grid") slide.style.alignContent = "start";
  });
}

function tournamentTabNav(event, activeTab) {
  const tabs = [
    ["overview", "Visão Geral", `#/events/${event.id}`],
    ["jogos", "Jogos", `#/events/${event.id}/jogos`],
    ["estatisticas", "Estatísticas", `#/events/${event.id}/estatisticas`],
    ["mapas", "Mapas", `#/events/${event.id}/mapas`],
    ["agentes", "Agentes", `#/events/${event.id}/agentes`],
  ];
  return `
    <nav class="tournament-page-tabs" aria-label="Abas do campeonato">
      ${tabs.map(([key, label, href]) => `<a class="${activeTab === key ? "active" : ""}" href="${href}" aria-current="${activeTab === key ? "page" : "false"}">${escapeHtml(label)}</a>`).join("")}
      ${activeTab === "overview" ? `<span class="vp-camp-atalhos" data-atalhos></span>` : ""}
    </nav>
  `;
}

function tournamentTabContent(event, matches, standings, activeTab) {
  if (activeTab === "jogos") return tournamentMatchesSection(event, matches);
  if (activeTab === "estatisticas") return tournamentStatsSection(event, matches, standings);
  if (activeTab === "mapas") return tournamentMapsSection(event, matches);
  if (activeTab === "agentes") return tournamentAgentsSection(event, matches);
  if (event.isGeral) return tournamentGeralVisao(event, matches, standings);
  return `
    ${tournamentOverviewSection(event, matches, standings)}
    <div class="tournament-main">
      ${tournamentSwissStandingsSection(event)}
      ${tournamentBracketSection(event, matches)}
    </div>
  `;
}

// O banner fica numa peca so dele, a direita da emenda: o nome do campeonato nunca
// cai em cima da arte, que costuma ter letreiro proprio. Campeonato sem banner
// (23 de 50) mostra o proprio logo apagado no lugar. Os dados moram na ficha da
// Visao Geral.
function tournamentHero(event) {
  const banner = assetPath(event.banner || event.bannerPath || "");
  const logo = assetPath(event.logo || "");
  const status = event.status || "Campeonato";
  const arte = banner
    ? `<img src="${escapeHtml(banner)}" alt="" loading="lazy" onerror="this.remove()" />`
    : logo ? `<img class="vp-camp-arte-logo" src="${escapeHtml(logo)}" alt="" loading="lazy" onerror="this.remove()" />` : "";
  return `
    <header class="vp-hero-camp">
      <div class="vp-camp-arte">${arte}</div>
      ${eventLogo(event, "hero")}
      <div class="vp-camp-id">
        <h1>${escapeHtml(event.name)}</h1>
        <span class="vp-camp-quando">${eventStatusClass(event.status) === "live" ? `<span class="vp-ao-vivo">${escapeHtml(status)}</span>` : escapeHtml(status)}, ${escapeHtml(eventTimeRange(event))}</span>
      </div>
    </header>
  `;
}

// Qual campeonato e qual etapa, pelo cadastro. Antes saia do hifen do nome, e a
// "Copa XV - 6ª edição (2025)" virava uma serie chamada Copa XV.
function tournamentSerie(event) {
  const campeonato = campeonatoDaEtapa(event);
  return campeonato ? { nome: campeonato.nome, etapa: event.etapaNome } : null;
}

// As etapas do mesmo campeonato, na ordem do cadastro. Campeonato sozinho nao tem etapas.
function tournamentEtapas(event) {
  return campeonatoDaEtapa(event)?.etapas || [];
}

// A faixa e a navegacao entre o campeonato inteiro (Geral) e as etapas, em blocos
// com as datas de cada uma (modelo B, escolhido pelo dono em 07/11/2026). Trocar de
// etapa mantem a aba aberta; os filtros de cada aba ficam para tras.
// Faixa de etapas em setas (modelo C, escolha dele em 08/11/2026): a seta diz que da
// para andar por ali, entao a sequencia vai da primeira etapa a ultima (o cadastro
// lista da mais recente). Etapa paralela nao e passo da sequencia: fica no fim, reta.
function tournamentEtapasNav(event, campeonato, activeTab = "overview") {
  const aba = activeTab && activeTab !== "overview" ? `/${activeTab}` : "";
  const bloco = (id, rotulo, quando, extra = "", classe = "") => `<a class="vp-etapa-bloco${classe}" href="#/events/${escapeHtml(id)}${aba}"${id === event.id ? ` aria-current="page"` : ""}><strong>${escapeHtml(rotulo)}${extra}</strong><small>${escapeHtml(quando)}</small></a>`;
  const etapaBloco = (etapa, classe = "") => bloco(etapa.id, etapa.etapaNome, eventDatesShort(etapa), eventStatusClass(etapa.status) === "live" ? `<span class="vp-ao-vivo">Ao vivo</span>` : "", classe);
  const sequencia = campeonato.etapas.filter((etapa) => !campeonato.paralelas.has(etapa.id)).reverse();
  const paralelas = campeonato.etapas.filter((etapa) => campeonato.paralelas.has(etapa.id)).reverse();
  return `
    <nav class="vp-camp-etapas vp-camp-etapas-b vp-camp-etapas-setas" aria-label="${escapeHtml(`Etapas de ${campeonato.nome}`)}">
      ${bloco(campeonato.id, "Geral", `${campeonato.etapas.length} etapas`, "", " vp-etapa-geral")}
      ${sequencia.map((etapa) => etapaBloco(etapa)).join("")}
      ${paralelas.map((etapa, indice) => etapaBloco(etapa, ` vp-etapa-paralela${indice ? "" : " vp-etapa-paralela-primeira"}`)).join("")}
    </nav>
  `;
}

// De qual etapa veio a vaga de cada equipe: a mais recente em que ela se classificou.
function tournamentOrigens(event) {
  const anteriores = tournamentEtapas(event)
    .filter((etapa) => etapa.id !== event.id && (etapa.start || 0) <= (event.start || 0))
    .sort((a, b) => (b.start || 0) - (a.start || 0));
  const origens = new Map();
  (event.teams || []).forEach((teamId) => {
    const etapa = anteriores.find((item) => (item.placements || []).some((row) => (row.id || row.teamId) === teamId && placementIsQualified(placementRawValue(row))));
    if (etapa) origens.set(teamId, tournamentSerie(etapa).etapa);
  });
  return origens;
}

function tournamentPatchLabels(matches) {
  const versions = new Set();
  for (const series of matches || []) {
    const maps = Array.isArray(series.maps) ? series.maps : [series];
    maps.forEach((match) => {
      const label = patchLabel(match?.gameVersion || "");
      if (label && label !== "-") versions.add(label);
    });
  }
  return [...versions].sort((a, b) => a.localeCompare(b, "pt-BR", { numeric: true }));
}

// A coluna da esquerda segue a ordem da Liquipedia, a referencia do dono para esta
// pagina: colocacao e, logo abaixo, quem jogou. A da direita e a ficha, que fica
// presa enquanto couber na tela. Chave e tabela vem depois, na largura toda.
function tournamentOverviewSection(event, matches, standings) {
  return `
    <div class="vp-camp-topo">
      <div class="vp-camp-esq">
        ${tournamentColocacaoSection(event, matches, standings)}
        ${tournamentTeamsSection(event, standings, matches)}
      </div>
      ${tournamentFicha(event, matches)}
    </div>
  `;
}

// Visao Geral do campeonato inteiro: colocacao final, todas as equipes e as etapas.
// Chave e tabela suica ficam em cada etapa, para nao repetir dado.
function tournamentGeralVisao(event, matches, standings) {
  return `
    <div class="vp-camp-topo">
      <div class="vp-camp-esq">
        ${tournamentColocacaoSection(event, matches, standings)}
        ${tournamentTeamsSection(event, standings, matches)}
        ${tournamentEtapasSection(event.campeonato)}
      </div>
      ${tournamentFicha(event, matches)}
    </div>
  `;
}

// O desfecho de cada etapa numa frase: a campea, ou quantas passaram.
function tournamentDesfechoDaEtapa(etapa) {
  const linhas = trophyPlacementRows(etapa);
  const campea = linhas.find((row, indice) => trophyPlacementInfo(row, indice)?.value === 1);
  if (campea) return `Campeã: ${tournamentTeamById(etapa, campea.id || campea.teamId)?.name || "-"}`;
  const vagas = linhas.filter((row) => placementIsQualified(placementRawValue(row))).length;
  if (vagas) return `${vagas} ${vagas === 1 ? "classificada" : "classificadas"}`;
  return etapa.status || "";
}

function tournamentEtapasSection(campeonato) {
  return `
    <section class="tournament-section vp-s-etapas">
      ${sectionHead("Etapas", `${campeonato.etapas.length} etapas`)}
      <div class="vp-geral-etapas">
        ${campeonato.etapas.map((etapa) => {
          const series = matchSeriesForEvent(etapa.id);
          const equipes = Number(etapa.teamCount || 0) || (etapa.teams || []).length;
          return `
            <a class="vp-geral-etapa" href="#/events/${escapeHtml(etapa.id)}">
              <strong>${escapeHtml(etapa.etapaNome)}${campeonato.paralelas.has(etapa.id) ? `<small>Paralela</small>` : ""}</strong>
              <span>${escapeHtml(eventTimeRange(etapa))}</span>
              <span>${escapeHtml(tournamentFormatLabel(etapa, series))}</span>
              <span>${equipes} ${equipes === 1 ? "equipe" : "equipes"}</span>
              <span class="vp-geral-desfecho">${escapeHtml(tournamentDesfechoDaEtapa(etapa))}</span>
            </a>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function tournamentFicha(event, matches) {
  const mapRows = tournamentMapPoolRows(event.mapPool || event.maps || [], matches).sort((a, b) => b.played - a.played);
  const maiorMapa = Math.max(1, ...mapRows.map((map) => map.played));
  const patches = tournamentPatchLabels(matches);
  const premio = String(event.prizePool || "").trim();
  const formato = [tournamentFormatLabel(event, matches), ...(event.format?.details || [])].map((item) => String(item || "").trim().replace(/\.+$/, "")).filter(Boolean).join(". ");
  const linhas = [
    ["Organização", `<span class="vp-ficha-org">${organizerLogo(event, "large")}${escapeHtml(event.organizer || event.source || SITE_NAME)}</span>`],
    ["Tier", event.tier ? eventTierBadge(event) : "A definir"],
    ["Tipo", escapeHtml(event.type || "Evento")],
    ["Datas", escapeHtml(eventTimeRange(event))],
    ["Equipes", escapeHtml(String(event.teamCount || event.teams.length))],
    ["Séries", escapeHtml(String(matches.length))],
    patches.length ? [patches.length > 1 ? "Patches" : "Patch", escapeHtml(patches.join(", "))] : null,
    premio && premio !== "-" ? ["Prêmio", escapeHtml(premio)] : null,
  ].filter(Boolean);
  return `
    <aside class="vp-camp-lado" aria-label="Informações do campeonato">
      <section>
        ${sectionHead("Informações")}
        <dl class="vp-ficha">${linhas.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${valor}</dd></div>`).join("")}</dl>
      </section>
      ${formato ? `<section class="vp-camp-formato"><h3>Formato</h3><p>${escapeHtml(formato)}</p></section>` : ""}
      <section class="vp-camp-pool">
        <h3>Map pool</h3>
        ${mapRows.length ? `<div class="vp-rm-lista">${mapRows.map((map) => tournamentMapPoolBanner(map, maiorMapa)).join("")}</div>` : `<small class="vp-pool-vazio">A definir</small>`}
      </section>
    </aside>
  `;
}

// A pagina e longa, entao os atalhos saem das proprias secoes: o que existe neste
// campeonato (chave, tabela, rodadas) e o que aparece. A ficha mede a propria altura
// para so ficar presa se couber na tela.
function bindVisaoGeralDoCampeonato() {
  const atalhos = document.querySelector("[data-atalhos]");
  if (atalhos) {
    const secoes = [...document.querySelectorAll(".tournament-hub .tournament-section, .tournament-hub .cmt-secao")].filter((secao) => secao.querySelector("h2"));
    atalhos.innerHTML = secoes.map((secao, indice) => `<button type="button" data-atalho="${indice}">${escapeHtml(secao.querySelector("h2").textContent.trim())}</button>`).join("");
    atalhos.addEventListener("click", (clickEvent) => {
      const botao = clickEvent.target.closest("[data-atalho]");
      if (botao) secoes[Number(botao.dataset.atalho)].scrollIntoView({ block: "start" });
    });
  }
  const lado = document.querySelector(".vp-camp-lado");
  lado?.style.setProperty("--lado-altura", `${lado.offsetHeight}px`);
}

// A campanha de cada equipe no campeonato, em series: chave e suico. W.O.
// conta, porque e resultado oficial; quem passou direto nao, porque nao houve
// jogo. Suico sem chave curada recebe uma chave estimada com as ultimas series,
// que ja estao nas rodadas ("Partida 045" la, "Partida 45" aqui): da chave sai
// o numero que o suico ja contou.
function campanhasDoCampeonato(event) {
  const campanhas = new Map();
  const conta = (match) => {
    if (!match?.a || !match?.b) return;
    const vencedor = tournamentBracketMatchWinner(match);
    if (!vencedor) return;
    const perdedor = vencedor === match.a ? match.b : match.a;
    [match.a, match.b].forEach((id) => {
      if (!campanhas.has(id)) campanhas.set(id, [0, 0]);
    });
    campanhas.get(vencedor)[0] += 1;
    campanhas.get(perdedor)[1] += 1;
  };
  const doSuico = new Set();
  (event.swiss?.rounds || []).forEach((round) => (round.matches || []).forEach((match) => {
    const numero = tournamentMatchCodeNumber(match?.code);
    if (Number.isFinite(numero)) doSuico.add(numero);
    conta(match);
  }));
  const jaContada = (match) => doSuico.has(tournamentMatchCodeNumber(match?.code));
  (event.bracket?.regions || []).forEach((region) => (region.columns || []).forEach((column) => (column.matches || []).filter((match) => !jaContada(match)).forEach(conta)));
  return campanhas;
}

// No suico sem chave depois, a tabela logo abaixo ja e a classificacao inteira. Em
// andamento isso ainda nao vale: quem ja saiu aparece aqui, abaixo das vagas abertas.
function tournamentTabelaFechaOCampeonato(event) {
  if (!eventIsDone(event)) return false;
  if (event.swiss?.finalStandings === false) return true;
  return Boolean(event.swiss?.standings?.length) && event.swiss.finalStandings !== true && !event.bracket?.regions?.length;
}

function tournamentRotuloDaColocacao(event, range) {
  const rotulo = tournamentPlacementDisplayLabel(event, range).replace(/ lugar$/, "");
  // "Off Season" e "Practice" sao divisoes, nao posicoes: vale o nome como veio.
  return rotulo === "Colocação não informada" ? String(range) : rotulo;
}

function tournamentCampanhas(event, matches) {
  if (event.isGeral) return campanhasDoGeral(event.campeonato);
  return campanhasDoCampeonato({ ...event, bracket: tournamentBracketDefinition(event, matches) || event.bracket });
}

// A campanha no campeonato inteiro e a soma das etapas. Etapa com chave ou suico
// curados conta pela chave (W.O. incluso, como na pagina dela); etapa sem curadoria
// conta pelas series com arquivo. A chave estimada (as 7 ultimas series) nunca entra:
// no Geral ela juntava series de etapas diferentes e mostrava 2-0 para o campeao.
function campanhasDoGeral(campeonato) {
  const total = new Map();
  campeonato.etapas.forEach((etapa) => {
    const series = matchSeriesForEvent(etapa.id);
    const curada = etapa.bracket?.regions?.length || etapa.swiss?.rounds?.length || etapa.swiss?.groups?.length;
    const daChave = curada ? tournamentCampanhas(etapa, series) : new Map();
    const daTabela = new Map(eventStandings(series).map((row) => [row.id, [row.seriesWins || 0, row.seriesLosses || 0]]));
    new Set([...daChave.keys(), ...daTabela.keys()]).forEach((teamId) => {
      const [vitorias, derrotas] = daChave.get(teamId) || daTabela.get(teamId);
      const atual = total.get(teamId) || [0, 0];
      total.set(teamId, [atual[0] + vitorias, atual[1] + derrotas]);
    });
  });
  return total;
}

// Uma entrada por colocacao, com todas as equipes que dividem a posicao. O podio vem
// antes, com as vagas ainda em aberto, e depois quem ficou pelo caminho.
function tournamentColocacaoGrupos(event, matches, standings) {
  const destaques = tournamentPodiumDisplayRows(event, tournamentPodiumRows(event, standings, matches));
  const vistos = new Set(destaques.map((row) => row.team?.id).filter(Boolean));
  const demais = tournamentTabelaFechaOCampeonato(event)
    ? []
    : tournamentResultRows(event, standings).flatMap((row, index) => {
        const range = row.range || placementLabel(index);
        if (placementIsOngoing(range) && !eventIsDone(event)) return [];
        const team = tournamentTeamById(event, row.id || row.teamId);
        return team && !vistos.has(team.id) ? [{ range, team }] : [];
      });
  const grupos = [];
  [...destaques, ...demais].forEach((row) => {
    const rotulo = tournamentRotuloDaColocacao(event, row.range);
    if (grupos.at(-1)?.rotulo !== rotulo) grupos.push({ rotulo, range: row.range, equipes: [] });
    grupos.at(-1).equipes.push(row.team);
  });
  return grupos;
}

function tournamentColocacaoCor(range) {
  if (placementIsQualified(String(range))) return "vp-col-vaga";
  return { "place-1": "vp-col-ouro", "place-2": "vp-col-prata", "place-3": "vp-col-bronze" }[tournamentPlacementPodiumClass(range)] || "";
}

// A partir de 8 equipes a tabela anda em duas colunas, cortando entre duas colocacoes
// no ponto mais perto da metade: uma colocacao nunca fica dividida. Numa coluna so a
// linha sobraria vazia entre o nome e os numeros.
function tournamentColocacaoColunas(grupos) {
  const total = grupos.reduce((soma, grupo) => soma + grupo.equipes.length, 0);
  if (total < 8) return [grupos];
  let soma = 0;
  let melhor = { corte: 1, distancia: Infinity };
  grupos.forEach((grupo, indice) => {
    soma += grupo.equipes.length;
    const distancia = Math.abs(soma - total / 2);
    if (distancia < melhor.distancia) melhor = { corte: indice + 1, distancia };
  });
  return [grupos.slice(0, melhor.corte), grupos.slice(melhor.corte)].filter((coluna) => coluna.length);
}

function tournamentColocacaoLinha(team, campanhas, dados) {
  if (!team) return `<span class="vp-col-equipe vp-col-aberta"><span class="vp-col-nome"><span class="team-logo clean-logo tiny logo-empty"></span><span>TBD</span></span></span>`;
  const campanha = campanhas.get(team.id);
  const linha = dados.get(team.id);
  const series = campanha ? `${campanha[0]}-${campanha[1]}` : linha ? `${linha.seriesWins}-${linha.seriesLosses}` : "-";
  const jogouMapas = linha && linha.mapWins + linha.mapLosses > 0;
  const mapas = jogouMapas ? `${linha.mapWins}-${linha.mapLosses}` : "-";
  const saldo = jogouMapas ? signed(linha.roundDiff || 0) : "-";
  const miolo = `<span class="vp-col-nome">${teamLogo(team.id, "tiny")}<span title="${escapeHtml(team.name)}">${escapeHtml(team.name)}</span></span><i>${escapeHtml(series)}</i><i class="vp-col-mapas">${escapeHtml(mapas)}</i><i>${escapeHtml(saldo)}</i>`;
  const rotulo = `${team.name}: ${series} em séries, ${mapas} em mapas, saldo de rounds ${saldo}`;
  return team.missing
    ? `<span class="vp-col-equipe" aria-label="${escapeHtml(rotulo)}">${miolo}</span>`
    : `<a class="vp-col-equipe" href="#/teams/${escapeHtml(team.id)}" aria-label="${escapeHtml(rotulo)}">${miolo}</a>`;
}

// O MVP e prêmio individual: fecha a tabela, em linha propria. Vai por PUUID, como o
// resto do prêmio.
function tournamentMvpGrupo(event) {
  const premiado = String(event.mvp || "").trim();
  if (!premiado || !eventIsDone(event)) return "";
  const player = (state.db?.players || []).find((item) => {
    const chaves = playerMvpKeys(item);
    return chaves.has(premiado) || chaves.has(normalizeNameKey(premiado));
  });
  if (!player) return "";
  const team = teamById(player.teamId);
  return `
    <div class="vp-col-grupo vp-col-mvp">
      <b>MVP</b>
      <div class="vp-col-equipes">
        <a class="vp-col-equipe" href="${playerHref(player)}"><span class="vp-col-nome">${team ? teamLogo(team.id, "tiny") : `<span class="team-logo clean-logo tiny logo-empty"></span>`}<span>${escapeHtml(player.nick)}</span></span><small>${escapeHtml(team?.name || "")}</small></a>
      </div>
    </div>
  `;
}

// Uma tabela com uma linha por equipe, como a de premiacao da Liquipedia: a coluna
// que nasce quando os campeonatos apontarem um para o outro (e os premios, quando
// existirem) entra aqui sem mudar o desenho.
function tournamentColocacaoSection(event, matches, standings) {
  const campanhas = tournamentCampanhas(event, matches);
  const dados = new Map(standings.map((row) => [row.id, row]));
  const colunas = tournamentColocacaoColunas(tournamentColocacaoGrupos(event, matches, standings));
  const mvp = tournamentMvpGrupo(event);
  return `
    <section class="vp-s-colocacao">
      ${sectionHead("Colocação")}
      <div class="vp-colocacao">
        ${colunas.map((grupos, indice) => `
          <div class="vp-col-coluna">
            <div class="vp-col-cab" aria-hidden="true"><span>Lugar</span><div class="vp-col-dados"><span>Equipe</span><span>Séries</span><span class="vp-col-mapas">Mapas</span><span>Saldo</span></div></div>
            ${grupos.map((grupo) => `
              <div class="vp-col-grupo ${tournamentColocacaoCor(grupo.range)}">
                <b class="${/^\d/.test(grupo.rotulo) ? "" : "vp-col-texto"}">${escapeHtml(grupo.rotulo)}</b>
                <div class="vp-col-equipes">${grupo.equipes.map((team) => tournamentColocacaoLinha(team, campanhas, dados)).join("")}</div>
              </div>
            `).join("")}
            ${indice === colunas.length - 1 ? mvp : ""}
          </div>
        `).join("")}
      </div>
    </section>
  `;
}

function tournamentMapPoolRows(mapNames, matches) {
  return (mapNames || []).map((name) => {
    const map = mapByName(name) || { id: slugify(name), name, icon: "" };
    const playedMaps = (matches || []).flatMap((series) => series.maps || []).filter((match) => normalize(match.mapName || "") === normalize(name) || match.mapId === map.id);
    return {
      ...map,
      poolName: name,
      played: playedMaps.length,
      rounds: playedMaps.reduce((sum, match) => sum + Number(match.rounds || 0), 0),
    };
  });
}

function tournamentPodiumRows(event, standings, matches = []) {
  if (!eventIsDone(event) && !event.placements?.length) return [];
  const bracketPodium = event.placements?.length ? [] : tournamentPodiumRowsFromBracket(event, matches);
  if (bracketPodium.length) return bracketPodium;
  const source = event.placements?.length ? event.placements : standings;
  const rows = [];
  source.forEach((row, index) => {
    const range = row.range || placementLabel(index);
    if (placementIsOngoing(range) && !eventIsDone(event)) return;
    if (!tournamentPlacementIsFeatured(range, index)) return;
    const id = row.id || row.teamId;
    const team = tournamentTeamById(event, id);
    if (team) rows.push({ range, team });
  });
  return rows;
}

function tournamentPodiumRowsFromBracket(event, matches) {
  const bracket = tournamentBracketDefinition(event, matches);
  const regions = bracket?.regions || [];
  if (regions.length !== 1) return [];
  const columns = regions[0].columns || [];
  const finalMatch = columns.at(-1)?.matches?.at(-1);
  if (!finalMatch?.a || !finalMatch?.b) return [];

  const winnerId = finalMatch.winner || (Number(finalMatch.scoreA) > Number(finalMatch.scoreB) ? finalMatch.a : finalMatch.b);
  const runnerUpId = finalMatch.a === winnerId ? finalMatch.b : finalMatch.a;
  const rows = [
    { range: "1", team: tournamentTeamById(event, winnerId) },
    { range: "2", team: tournamentTeamById(event, runnerUpId) },
  ].filter((row) => row.team);

  const semifinalLosers = (columns.at(-2)?.matches || [])
    .map((match) => {
      const matchWinner = match.winner || (Number(match.scoreA) > Number(match.scoreB) ? match.a : match.b);
      return match.a === matchWinner ? match.b : match.a;
    })
    .filter(Boolean)
    .filter((teamId, index, list) => list.indexOf(teamId) === index && teamId !== winnerId && teamId !== runnerUpId)
    .map((teamId) => tournamentTeamById(event, teamId))
    .filter(Boolean);

  if (semifinalLosers.length >= 2) rows.push(...semifinalLosers.slice(0, 2).map((team) => ({ range: "3-4", team })));
  else if (semifinalLosers.length === 1) rows.push({ range: "3", team: semifinalLosers[0] });

  return rows;
}

// Sem resultado ainda o podio aparece com as vagas em aberto, nao com um aviso.
function tournamentPodiumPlaceholderRows() {
  return ["1", "2", "3"].map((range) => ({ range, team: null }));
}

// Campeonato em andamento com parte do podio decidida (as semis jogadas e a
// final por vir): quem ja tem colocacao aparece, e o 1o e o 2o que faltam
// ficam como vaga em aberto acima. Encerrado, o podio e o que veio.
function tournamentPodiumDisplayRows(event, rows) {
  if (!rows.length) return tournamentPodiumPlaceholderRows();
  if (eventIsDone(event)) return rows;
  const tem = (classe) => rows.some((row) => tournamentPlacementPodiumClass(row.range) === classe);
  const abertas = [
    ["1", "place-1"],
    ["2", "place-2"],
  ]
    .filter(([, classe]) => !tem(classe))
    .map(([range]) => ({ range, team: null }));
  return [...abertas, ...rows];
}

// Como em Partidas: o mapa em cinza, e a arte colorida revelada ate a proporcao de
// jogos. O total de rounds fica na dica.
function tournamentMapPoolBanner(map, maior) {
  const nome = map.name || map.poolName;
  const art = mapBannerSrc(nome);
  return `
    <a class="vp-rm" href="#/maps/${escapeHtml(map.id)}" style="--parte:${(map.played / maior).toFixed(4)}" title="${escapeHtml(`${map.played} ${map.played === 1 ? "jogo" : "jogos"}, ${map.rounds} rounds`)}">
      <span class="vp-rm-arte">${art ? ["vp-rm-cinza", "vp-rm-cor"].map((classe) => `<img class="${classe}" src="${escapeHtml(art.src)}" data-fallback="${escapeHtml(art.fallback)}" alt="" loading="lazy" onerror="mapArtError(this)" />`).join("") : ""}</span>
      <span>${escapeHtml(nome)}</span>
      <b>${map.played}</b>
    </a>
  `;
}

function tournamentDurationLabel(event) {
  if (!event.start || !event.end) return "A definir";
  const dayMs = 24 * 60 * 60 * 1000;
  const days = Math.max(1, Math.ceil((Number(event.end) - Number(event.start)) / dayMs));
  return `${days} dia${days > 1 ? "s" : ""}`;
}

function tournamentTeamById(event, teamId) {
  const team = teamById(teamId);
  const overrideName = event.teamNames?.[teamId];
  // Campeonato de uma fase antiga (Dark UFRJ, hoje Minerva Thunders): escudo e
  // cores da época, como o nome que já vem do teamNames. No Geral vale a época da
  // etapa mais recente em que a equipe jogou com nome antigo (a faixa vem da mais
  // recente para a mais antiga).
  const eventos = event.isGeral ? event.campeonato.etapas.map((etapa) => etapa.id) : [event.id];
  const nomes = team?.profile?.nomes || [];
  const fase = eventos.map((id) => nomes.find((item) => (item.eventos || []).includes(id))).find(Boolean);
  if (team && fase) {
    return { ...team, name: overrideName || fase.nome, tag: fase.tag || team.tag, logo: fase.logo || team.logo, colors: fase.cores?.length ? fase.cores : team.colors, profile: { ...team.profile, logo: fase.logo || team.profile?.logo } };
  }
  if (team) return overrideName ? { ...team, name: overrideName } : team;
  if (!teamId) return null;
  return {
    id: teamId,
    name: overrideName || displayTeamName(teamId),
    tag: teamTag(teamId),
    sourceTag: teamTag(teamId),
    colors: teamColors(teamId),
    matches: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    ranking: { provisional: true },
    missing: true,
  };
}

function tournamentGroupedEvents(event, matches) {
  const stages = tournamentStageRows(event, matches);
  return `
    <section class="tournament-section">
      <div class="tournament-section-head">
        <h2>Grouped events</h2>
        <span>${stages.length} etapas</span>
      </div>
      <div class="tournament-stage-track">
        ${stages.map((stage) => tournamentStageCard(event, stage)).join("")}
      </div>
    </section>
  `;
}

function tournamentStageRows(event, matches) {
  if (Array.isArray(event.stages) && event.stages.length) return event.stages;
  const sorted = matches.slice().sort((a, b) => (a.startedAt || a.sortAt || 0) - (b.startedAt || b.sortAt || 0));
  if (sorted.length < 8) {
    return [{ name: "Evento principal", start: event.start, end: event.end, matches: sorted.length }];
  }
  const middle = Math.ceil(sorted.length / 2);
  const first = sorted.slice(0, middle);
  const second = sorted.slice(middle);
  return [
    { name: "Fase inicial", start: first[0]?.startedAt, end: first[first.length - 1]?.startedAt, matches: first.length },
    { name: "Fase final", start: second[0]?.startedAt, end: second[second.length - 1]?.startedAt, matches: second.length },
  ];
}

function tournamentStageCard(event, stage) {
  const current = !eventIsDone(event) && periodEndIsCurrent(stage.end || event.end);
  const range = stage.start || stage.end ? formatDateRange(stage.start, stage.end, { current, autoCurrent: current }) : eventTimeRange(event);
  return `
    <article class="tournament-stage-card">
      ${eventLogo(event)}
      <span>
        <strong>${escapeHtml(stage.name || "Etapa")}</strong>
        <small>${escapeHtml(range)}</small>
      </span>
      <em>${escapeHtml(String(stage.matches || 0))} partidas</em>
    </article>
  `;
}

// Chave e rodadas podem existir juntas (pontos corridos com playoffs). A chave vem
// antes, porque e a fase que decide. Suico sem chave curada nao usa a estimada:
// ela sairia das mesmas series das rodadas.
function tournamentBracketSection(event, matches) {
  const bracket = tournamentBracketDefinition(event, matches);
  const rodadas = event.swiss?.rounds?.length ? tournamentSwissBracketSection(event) : "";
  const temChave = rodadas ? event.bracket?.regions?.length : bracket?.regions?.length;
  const chave = temChave ? tournamentCuratedBracketSection({ ...event, bracket }) : "";
  if (rodadas || chave) return `${chave}${rodadas}`;
  return `
    <section class="tournament-section">
      ${sectionHead("Chave")}
      <div class="empty-state">A chave aparece quando as partidas forem registradas.</div>
    </section>
  `;
}

// Todas as rodadas a vista, sem seta nem rolagem de lado: ate 7 cabem numa fileira,
// e os campeonatos longos quebram em fileiras iguais.
function tournamentSwissBracketSection(event) {
  const rounds = event.swiss?.rounds || [];
  const porLinha = rounds.length <= 7 ? rounds.length : Math.min(6, Math.ceil(rounds.length / 2));
  return `
    <section class="tournament-section tournament-swiss-section">
      ${sectionHead("Rodadas", event.format?.summary || event.bracket?.title || "Sistema suíço")}
      <div class="tournament-swiss-bracket vp-rodadas" style="--por-linha:${porLinha}">
        ${rounds.map((round, roundIndex) => tournamentSwissRodada(event, round, roundIndex)).join("")}
      </div>
    </section>
  `;
}

function tournamentSwissRodada(event, round, roundIndex) {
  const detalhe = [round.bestOf, round.status].filter(Boolean).join(", ");
  const grupos = tournamentSwissRoundGroups(event, roundIndex)
    .map((group) => `
      ${group.label ? `<h4>${escapeHtml(group.label)}</h4>` : ""}
      <div class="vp-rd-lista">
        ${group.matches.map(({ match, matchIndex }) => tournamentChaveBotao(event, match, tournamentSwissMatchKey(roundIndex, matchIndex, match.code))).join("")}
      </div>
    `)
    .join("");
  return `
    <section class="vp-rd">
      <h3>${escapeHtml(round.title || `Rodada ${roundIndex + 1}`)}${detalhe ? `<small>${escapeHtml(detalhe)}</small>` : ""}</h3>
      ${grupos}
    </section>
  `;
}

function tournamentSwissRoundGroups(event, roundIndex) {
  const round = event.swiss?.rounds?.[roundIndex] || {};
  // Pontos corridos nao pareia por campanha: a tabela de jogos sai inteira no
  // sorteio e vale ate a ultima rodada. Agrupar por campanha ali inventa uma
  // leitura suica que nao existe - na Copa LUCE a Rodada 3 saia com os grupos
  // "1-0 / 0-1" e "0-1 / 1-0", que sao o MESMO confronto lido nas duas ordens,
  // e ainda tirava as partidas da ordem numerada (11 e 12 antes de 9 e 10).
  // Opt-in, como o swiss.stateTables, para nao mexer nos campeonatos suicos.
  if (event.swiss?.roundRobin) {
    const comIndice = (round.matches || []).map((match, matchIndex) => ({ match, matchIndex }));
    // Grupos em pontos corridos (Copa Aliança 2023.2): a rodada mostra um bloco por grupo.
    if (!comIndice.some(({ match }) => match.group)) return [{ label: "", matches: comIndice }];
    const porGrupo = new Map();
    for (const item of comIndice) {
      const rotulo = item.match.group || "";
      if (!porGrupo.has(rotulo)) porGrupo.set(rotulo, []);
      porGrupo.get(rotulo).push(item);
    }
    return [...porGrupo].map(([label, matches]) => ({ label, matches }));
  }
  const records = tournamentSwissRecordsBeforeRound(event, roundIndex);
  const grouped = new Map();
  (round.matches || []).forEach((match, matchIndex) => {
    const label = tournamentSwissMatchScoreLabel(match, records);
    if (!grouped.has(label)) grouped.set(label, []);
    grouped.get(label).push({ match, matchIndex });
  });
  return [...grouped.entries()]
    .map(([label, matches]) => ({ label, matches }))
    .sort((a, b) => tournamentSwissScoreSortValue(b.label) - tournamentSwissScoreSortValue(a.label) || a.label.localeCompare(b.label, "pt-BR", { numeric: true }));
}

function tournamentSwissRecordsBeforeRound(event, roundIndex) {
  const records = new Map((event.teams || []).map((teamId) => [teamId, { wins: 0, losses: 0 }]));
  for (const round of (event.swiss?.rounds || []).slice(0, roundIndex)) {
    for (const match of round.matches || []) {
      tournamentSwissApplyMatchRecord(records, match);
    }
  }
  return records;
}

function tournamentSwissApplyMatchRecord(records, match) {
  if (!tournamentBracketMatchHasResult(match)) return;
  const winnerId = match.winner || (Number(match.scoreA) > Number(match.scoreB) ? match.a : match.b);
  const loserId = match.a === winnerId ? match.b : match.a;
  if (winnerId) tournamentSwissRecordForTeam(records, winnerId).wins += 1;
  if (loserId) tournamentSwissRecordForTeam(records, loserId).losses += 1;
}

function tournamentSwissRecordForTeam(records, teamId) {
  if (!records.has(teamId)) records.set(teamId, { wins: 0, losses: 0 });
  return records.get(teamId);
}

function tournamentSwissMatchScoreLabel(match, records) {
  const aRecord = tournamentSwissRecordForTeam(records, match.a);
  if (!match.b) return tournamentSwissRecordLabel(aRecord);
  const bRecord = tournamentSwissRecordForTeam(records, match.b);
  const aLabel = tournamentSwissRecordLabel(aRecord);
  const bLabel = tournamentSwissRecordLabel(bRecord);
  return aLabel === bLabel ? aLabel : `${aLabel} / ${bLabel}`;
}

function tournamentSwissRecordLabel(record) {
  return `${record.wins || 0}-${record.losses || 0}`;
}

function tournamentSwissScoreSortValue(label) {
  const match = String(label || "").match(/(?<wins>\d+)-(?<losses>\d+)/);
  if (!match?.groups) return -999;
  return Number(match.groups.wins) * 100 - Number(match.groups.losses);
}

function tournamentSwissMatchKey(roundIndex, matchIndex, code) {
  return `swiss-${roundIndex}-${matchIndex}-${slugify(code || "partida")}`;
}

function tournamentSwissStandingsSection(event) {
  const groups = (event.swiss?.groups || []).filter((group) => group?.standings?.length);
  if (!groups.length && !event.swiss?.standings?.length) return "";
  return `
    <section class="tournament-section tournament-swiss-table-section">
      ${sectionHead("Tabela", event.swiss.standingsLabel || "Classificação atual")}
      ${groups.length ? tournamentSwissGroupTables(event, groups) : tournamentSwissGeneralTables(event)}
    </section>
  `;
}

function tournamentSwissGroupTables(event, groups) {
  return `
    <div class="vp-tabelas">
      ${groups.map((group) => tournamentSwissTabela(tournamentSwissStandingRows(event, group.standings), { titulo: escapeHtml(group.title || "Grupo"), estado: tournamentMostraEstado(event) })).join("")}
    </div>
  `;
}

function tournamentSwissGeneralTables(event) {
  const rows = tournamentSwissStandingRows(event, [
    ...(event.swiss.standings || []).map((row) => ({ ...row, status: row.status || "Em disputa" })),
    ...(event.swiss.eliminated || []).map((row) => ({ ...row, status: row.status || "Eliminado" })),
  ]);
  const geral = tournamentSwissTabela(rows, { colunas: 3, estado: tournamentMostraEstado(event) });
  if (!event.swiss.stateTables) return geral;
  return `
    <div class="tournament-swiss-table-wrap">
      <input class="swiss-table-view-mode-input swiss-table-view-mode-general" type="radio" name="swiss-table-view-${escapeHtml(event.id)}" id="swiss-table-view-${escapeHtml(event.id)}-general" checked />
      <input class="swiss-table-view-mode-input swiss-table-view-mode-states" type="radio" name="swiss-table-view-${escapeHtml(event.id)}" id="swiss-table-view-${escapeHtml(event.id)}-states" />
      <div class="swiss-table-view-toggle" aria-label="Modo de exibição da tabela">
        <label class="swiss-table-view-option general" for="swiss-table-view-${escapeHtml(event.id)}-general">Geral</label>
        <label class="swiss-table-view-option states" for="swiss-table-view-${escapeHtml(event.id)}-states">Estados</label>
      </div>
      <div class="swiss-table-view swiss-table-view-general-panel">${geral}</div>
      <div class="swiss-table-view swiss-table-view-states-panel">${tournamentSwissStateTables(rows)}</div>
    </div>
  `;
}

function tournamentSwissStandingRows(event, rows) {
  return (rows || []).map((row, index) => ({
    ...row,
    rank: row.rank || row.range || index + 1,
    status: row.status || "Em disputa",
    team: tournamentTeamById(event, row.id || row.teamId),
  }));
}

// Com tres colunas a ordem desce a primeira e continua nas seguintes, cada uma com o
// proprio cabecalho. Em 1294px uma linha so deixava um vao enorme entre nome e dados.
// O titulo entra como HTML por causa da bandeira do estado: quem chama escapa o texto.
// O estado so e dado do formato no JUBS (uma equipe por estado). Nos outros campeonatos
// a coluna repetia o perfil e tirava 52px do nome.
function tournamentMostraEstado(event) {
  return /^jubs/.test(event?.campeonatoId || event?.id || "");
}

function tournamentSwissTabela(rows, { titulo = "", colunas = 1, estado = true } = {}) {
  if (!rows.length) return "";
  const porColuna = Math.ceil(rows.length / colunas);
  const partes = Array.from({ length: colunas }, (_, indice) => rows.slice(indice * porColuna, (indice + 1) * porColuna)).filter((parte) => parte.length);
  return `
    <div class="vp-tabela${estado ? "" : " vp-sem-uf"}">
      ${titulo ? `<h3>${titulo}</h3>` : ""}
      <div class="vp-tabela-corpo">
        ${partes.map((parte) => `
          <div class="vp-tabela-coluna">
            <div class="vp-tabela-cab" aria-hidden="true"><span>#</span><span></span><span>Equipe</span><span>Estado</span><span>V</span><span>D</span><span>Situação</span></div>
            ${parte.map(tournamentSwissLinha).join("")}
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

function tournamentSwissLinha(row) {
  const status = normalize(row.status);
  const classes = ["vp-tabela-linha", status.includes("eliminado") ? "vp-fora" : "", status.includes("classificad") ? "vp-dentro" : ""].filter(Boolean).join(" ");
  const posicao = String(row.rank).replace(/ lugar$/, "");
  const estado = tournamentSwissStateInfo(row.team);
  const miolo = `
    <b>${escapeHtml(posicao)}</b>
    ${row.team ? teamLogo(row.team.id, "tiny") : `<span class="team-logo clean-logo tiny logo-empty"></span>`}
    <strong>${escapeHtml(row.team?.name || row.id || "-")}</strong>
    <span class="vp-tabela-uf" title="${escapeHtml(estado.label)}">${estado.code || estado.flagSrc ? `${tournamentSwissStateFlag(estado)}<span>${escapeHtml(estado.code)}</span>` : "-"}</span>
    <i>${escapeHtml(String(row.wins ?? 0))}</i>
    <i>${escapeHtml(String(row.losses ?? 0))}</i>
    <small>${escapeHtml(row.status)}</small>
  `;
  return row.team && !row.team.missing
    ? `<a class="${classes}" href="#/teams/${escapeHtml(row.team.id)}">${miolo}</a>`
    : `<span class="${classes}">${miolo}</span>`;
}

function tournamentSwissStateTables(rows) {
  const groups = tournamentSwissStateGroups(rows);
  if (!groups.length) return `<div class="empty-state">Nenhum time encontrado para agrupar por estado.</div>`;
  return `<div class="vp-tabelas">${groups.map((group) => tournamentSwissTabela(group.rows, { titulo: `${tournamentSwissStateFlag(group.state)}${escapeHtml(group.state.label)}` })).join("")}</div>`;
}

function tournamentSwissStateGroups(rows) {
  const grouped = new Map();
  for (const row of rows || []) {
    const state = tournamentSwissStateInfo(row.team);
    const key = `${state.label}|${state.code}|${state.flagSrc}`;
    if (!grouped.has(key)) grouped.set(key, { state, rows: [] });
    grouped.get(key).rows.push(row);
  }
  return [...grouped.values()].sort((a, b) => a.state.label.localeCompare(b.state.label, "pt-BR", { sensitivity: "base" }));
}

function tournamentSwissStateInfo(team) {
  const profile = team?.profile || {};
  const code = profile.state || team?.state || "";
  const label = profile.stateName || team?.stateName || code || "Estado não informado";
  const flagSrc = profile.flag || team?.flag || team?.stateFlag || "";
  return { code, label, flagSrc };
}

function tournamentSwissStateFlag(state) {
  const fallback = escapeHtml(state.code || "UF");
  return state.flagSrc
    ? `<img class="state-flag" src="${escapeHtml(assetPath(state.flagSrc))}" alt="Bandeira ${escapeHtml(state.label)}" loading="lazy" onerror="this.replaceWith(this.nextElementSibling)" /><span class="state-flag placeholder">${fallback}</span>`
    : `<span class="state-flag placeholder">${fallback}</span>`;
}

function tournamentBracketDefinition(event, matches) {
  if (event.bracket?.regions?.length) return event.bracket;
  if (event.swiss?.rounds?.length && event.bracket?.title) return event.bracket;
  return tournamentEstimatedBracket(matches);
}

function tournamentEstimatedBracket(matches) {
  const columns = tournamentBracketColumns(matches);
  if (!columns.length) return null;
  return {
    title: "Bracket oficial",
    regions: [
      {
        name: "Chave principal",
        className: "upper-bracket single-elimination",
        columns: columns.map((column) => ({
          title: column.title,
          matches: column.matches.map(tournamentSeriesBracketMatch),
        })),
      },
    ],
  };
}

function tournamentSeriesBracketMatch(series) {
  const score = matchListScore(series);
  return {
    code: `Partida ${series.seriesCode || series.code || "-"}`,
    bestOf: series.label || seriesFormatLabel(series.maps || []),
    a: series.teamA.id,
    scoreA: score.a,
    b: series.teamB.id,
    scoreB: score.b,
    winner: series.winnerId,
  };
}

const TOURNAMENT_BRACKET_STAGES = [
  { id: "groups", title: "Fase de grupos" },
  { id: "playoffs", title: "Playoffs" },
];

function tournamentCuratedBracketSection(event) {
  const regions = tournamentChaveRegioes(tournamentBracketDisplayRegions(event.bracket.regions.map(tournamentChaveSemFaixa)));
  // Com 8 colunas ou mais o vao entre elas aperta para todas caberem em 1294px.
  const densa = Math.max(0, ...regions.map((region) => tournamentCuratedBracketColumns(event, region).length)) >= 8;
  const stages = tournamentBracketStages(regions);
  // Uma fase so nao ganha titulo proprio: o cabecalho da secao ja diz o que e.
  const body = stages.length
    ? stages.map((stage) => `
        <section class="tournament-bracket-stage">
          <h3 class="tournament-bracket-stage-title">${escapeHtml(stage.title)}</h3>
          <div class="tournament-bracket-stage-body">${tournamentCuratedBracketRegions(event, stage.regions)}</div>
        </section>
      `).join("")
    : tournamentCuratedBracketRegions(event, regions);
  const temBye = regions.some((region) => (region.columns || []).some((column) => (column.matches || []).some(tournamentChaveEhBye)));
  return `
    <section class="tournament-section vp-s-chave">
      ${sectionHead("Chave", event.bracket.title || "Chave oficial")}
      <div class="tournament-curated-bracket vp-chaves${densa ? " vp-chaves-densas" : ""} ${stages.length ? "staged" : tournamentCuratedBracketLayoutClass(regions)}">
        ${body}
      </div>
    </section>
  `;
}

// A grande final vira a ultima coluna da chave superior. Cada partida leva a
// chave da previa calculada na regiao de origem (coluna, partida e codigo),
// entao clicar nela continua abrindo a mesma serie de antes.
function tournamentChaveRegioes(regions) {
  const comChave = regions.map((region) => ({
    ...region,
    columns: (region.columns || []).map((column, columnIndex) => ({
      ...column,
      matches: (column.matches || []).map((match, matchIndex) => ({ ...match, previewKey: tournamentBracketMatchKey(columnIndex, matchIndex, match.code) })),
    })),
  }));
  comChave.forEach((region) => {
    if (region.layout !== "linked" && !String(region.className || "").includes("group-stage")) region.columns = tournamentChaveAlinhaRodadaCurta(region.columns);
  });
  const superior = comChave.find((region) => tournamentBracketRegionKind(region) === "upper-bracket" && region.layout !== "linked");
  const final = comChave.find((region) => tournamentBracketRegionKind(region) === "grand-final" && region.layout !== "linked");
  if (!superior || !final || (superior.stage || "") !== (final.stage || "")) return comChave;
  superior.columns = [...superior.columns, ...final.columns.map((column) => ({ ...column, grandeFinal: true }))];
  superior.name = `${superior.name || "Chave superior"} e grande final`;
  return comChave.filter((region) => region !== final);
}

// Chave encadeada sem faixa gravada caia inteira no topo e sem fio (Aliança 2024,
// CPUE, Qualify do JUBS 2024): vira a chave comum, que centraliza cada partida
// entre as duas que a alimentam. O titulo da coluna perde o nome da regiao repetido.
function tournamentChaveSemFaixa(region) {
  if (region.layout !== "linked") return region;
  const temFaixa = (region.columns || []).some((column) => (column.matches || []).some((match) => match.band != null))
    || (region.terminalColumn?.cards || []).some((card) => card.band != null);
  if (temFaixa) return region;
  const { layout, ...comum } = region;
  // A chave encadeada so mostrava classificados declarados: a troca e so de desenho.
  return {
    ...comum,
    terminalColumn: region.terminalColumn?.cards?.length ? region.terminalColumn : false,
    columns: (region.columns || []).map((column) => ({ ...column, title: String(column.title || "").replace(`${region.name} - `, "") })),
  };
}

// Rodada com menos partidas que a seguinte (os byes nao entram no cadastro, como na
// rodada de 64 da Univava): cada partida vai para a altura da partida que ela
// alimenta e o resto da coluna fica vazio. Se alguma partida nao achar destino, ou
// duas cairem no mesmo, a coluna fica como estava.
function tournamentChaveAlinhaRodadaCurta(columns = []) {
  return columns.map((column, index) => {
    const matches = column.matches || [];
    const seguinte = columns[index + 1]?.matches || [];
    if (!matches.length || matches.length >= seguinte.length) return column;
    const vagas = new Array(seguinte.length).fill(null);
    for (const match of matches) {
      const vencedor = tournamentBracketMatchWinner(match);
      const quem = vencedor ? [vencedor] : [match.a, match.b].filter(Boolean);
      const destino = seguinte.findIndex((proxima) => quem.some((id) => id === proxima.a || id === proxima.b));
      if (destino < 0 || vagas[destino]) return column;
      vagas[destino] = match;
    }
    return { ...column, matches: vagas.map((match) => match || { vazia: true }) };
  });
}

function tournamentBracketStages(regions = []) {
  const buckets = new Map();
  regions.forEach((region) => {
    const stage = region.stage || "";
    if (!buckets.has(stage)) buckets.set(stage, []);
    buckets.get(stage).push(region);
  });
  if (buckets.size < 2 || !TOURNAMENT_BRACKET_STAGES.some((stage) => buckets.has(stage.id))) return [];
  const known = TOURNAMENT_BRACKET_STAGES
    .filter((stage) => buckets.has(stage.id))
    .map((stage) => ({ title: stage.title, regions: buckets.get(stage.id) }));
  const rest = [...buckets.keys()]
    .filter((stage) => !TOURNAMENT_BRACKET_STAGES.some((conhecida) => conhecida.id === stage))
    .map((stage) => ({ title: stage || "Outras chaves", regions: buckets.get(stage) }));
  return [...known, ...rest];
}

function tournamentCuratedBracketLayoutClass(regions = []) {
  const groupRegions = regions.filter((region) => String(region.className || "").includes("group-stage"));
  if (regions.length > 0 && groupRegions.length === regions.length) return "groups-layout";
  if (groupRegions.length) return "has-groups";
  return regions.length === 1 ? "single-region" : "";
}

function tournamentCuratedBracketRegions(event, regions = []) {
  return regions
    .map((region) => (region.layout === "linked"
      ? tournamentLinkedBracketRegion(event, region)
      : tournamentCuratedBracketRegion(event, region)))
    .join("");
}

function tournamentBracketDisplayRegions(regions = []) {
  // Grupos antes das chaves: e a ordem em que o campeonato acontece.
  const priority = { "upper-bracket": 1, "lower-bracket": 2, "grand-final": 3 };
  const peso = (region) => (String(region.className || "").includes("group-stage") ? 0 : priority[tournamentBracketRegionKind(region)] || 10);
  return regions.slice().sort((a, b) => peso(a) - peso(b));
}

function tournamentBracketRegionKind(region = {}) {
  const descriptor = normalize(`${region.className || ""} ${region.name || ""}`);
  if (descriptor.includes("upper bracket") || descriptor.includes("chave superior")) return "upper-bracket";
  if (descriptor.includes("lower bracket") || descriptor.includes("chave inferior")) return "lower-bracket";
  if (descriptor.includes("grand final") || descriptor.includes("grande final")) return "grand-final";
  // A CPUE chama as regioes so de "Upper" e "Lower".
  if (/(^|\s)upper(\s|$)/.test(descriptor)) return "upper-bracket";
  if (/(^|\s)lower(\s|$)/.test(descriptor)) return "lower-bracket";
  return "";
}

function tournamentPlacementBracketRegionKind(row = {}) {
  const explicit = normalize(row.bracket || "");
  const description = normalize([row.note, row.reason].filter(Boolean).join(" "));
  const upper = [explicit, description].some((value) =>
    ["upper", "upper bracket", "superior", "chave superior"].includes(value)
      || value.includes("upper bracket")
      || value.includes("chave superior"));
  const lower = [explicit, description].some((value) =>
    ["lower", "lower bracket", "inferior", "chave inferior"].includes(value)
      || value.includes("lower bracket")
      || value.includes("chave inferior"));
  if (upper === lower) return "";
  return upper ? "upper-bracket" : "lower-bracket";
}

function tournamentClassifiedPlacementCards(event = {}, region = {}) {
  const regionKind = tournamentBracketRegionKind(region);
  if (!regionKind || regionKind === "grand-final") return [];

  const seen = new Set();
  const cards = (event.placements || []).flatMap((row) => {
    const placement = normalize(row.range || placementRawValue(row));
    const id = row.id || row.teamId;
    if (!placement.startsWith("classificad") || !id || tournamentPlacementBracketRegionKind(row) !== regionKind || seen.has(id)) return [];
    seen.add(id);
    return [{ id }];
  });

  const lastMatches = [...(region.columns || [])].reverse().find((column) => column.matches?.length)?.matches || [];
  const winnerOrder = new Map(lastMatches.map((match, index) => [match.winner, index]));
  return cards.sort((a, b) => (winnerOrder.get(a.id) ?? Number.MAX_SAFE_INTEGER) - (winnerOrder.get(b.id) ?? Number.MAX_SAFE_INTEGER));
}

function tournamentCuratedBracketColumns(event = {}, region = {}) {
  const columns = [...(region.columns || [])];
  if (region.terminalColumn === false) return columns;
  // Configuracao explicita fica reservada para formatos excepcionais;
  // classificatorias comuns derivam os cards das colocacoes oficiais.
  const explicitCards = region.terminalColumn?.cards || [];
  const terminalCards = explicitCards.length ? explicitCards : tournamentClassifiedPlacementCards(event, region);
  if (terminalCards.length) {
    columns.push({ title: "Classificados", ...(region.terminalColumn || {}), terminalCards });
  }
  return columns;
}

function tournamentCuratedBracketColumnEntries(column = {}) {
  return column.terminalCards || column.matches || [];
}

function tournamentCuratedBracketRegion(event, region) {
  const columns = tournamentCuratedBracketColumns(event, region);
  // Fase de grupos nao tem chave: as partidas de uma coluna nao alimentam as da
  // seguinte, entao nao ganham fio.
  const semFios = String(region.className || "").includes("group-stage");
  return `
    <section class="tournament-bracket-region vp-chave-regiao ${escapeHtml(region.className || "")}">
      <h3>${escapeHtml(region.name || "Chave")}</h3>
      <div class="vp-chave${semFios ? " vp-sem-fios" : ""}">
        ${columns.map((column, columnIndex) => tournamentChaveRodada(event, column, columns, columnIndex)).join("")}
      </div>
    </section>
  `;
}

// Uma rodada: as celulas dividem a altura da coluna em partes iguais, entao a
// partida da rodada seguinte cai no meio das duas que a alimentam. A junta
// vertical so existe quando a rodada seguinte tem metade das partidas.
function tournamentChaveRodada(event, column, columns, columnIndex) {
  const entries = tournamentCuratedBracketColumnEntries(column);
  const proxima = tournamentCuratedBracketColumnEntries(columns[columnIndex + 1]).length;
  const classes = ["vp-rodada", proxima && entries.length === proxima * 2 ? "vp-pares" : "", column.grandeFinal ? "vp-gf" : "", column.terminalCards ? "vp-classificados" : ""].filter(Boolean).join(" ");
  const celulas = entries
    .map((entry, matchIndex) => (column.terminalCards
      ? `<div class="vp-celula">${tournamentCuratedBracketQualifiedCard(event, entry, { columnIndex, matchIndex, maxMatches: 1, columnMatches: 1 })}</div>`
      : tournamentChaveCelula(event, entry, columnIndex, matchIndex)))
    .join("");
  return `<div class="${classes}"><small>${escapeHtml(column.title || "")}</small><div class="vp-rodada-corpo">${celulas}</div></div>`;
}

// "Sem adversario" e quem passou direto: vira celula vazia, sem fio, e a
// equipe so aparece na rodada seguinte.
function tournamentChaveEhBye(match) {
  if (match?.vazia) return true;
  if (!match || (match.a && match.b)) return false;
  if (normalize(match.status || "") === "bye") return true;
  return [match.aLabel, match.bLabel].some((label) => normalize(label || "").includes("sem advers"));
}

function tournamentChaveCelula(event, match, columnIndex, matchIndex) {
  if (tournamentChaveEhBye(match)) {
    const quem = tournamentTeamById(event, match.a || match.b)?.name || "";
    return `<div class="vp-celula vp-bye"${quem ? ` title="${escapeHtml(`${match.code || "Partida"}: ${quem} passou direto`)}"` : ""}></div>`;
  }
  return `<div class="vp-celula">${tournamentChaveBotao(event, match, match.previewKey || tournamentBracketMatchKey(columnIndex, matchIndex, match.code))}</div>`;
}

// A partida em si, igual na chave, nos grupos e nas rodadas do suico.
function tournamentChaveBotao(event, match, key) {
  const winner = tournamentBracketMatchWinner(match);
  // W.O. e vencedor sem placar levam o status no card: sem ele, a célula sem
  // números pareceria uma partida não jogada.
  const semPlacar = Boolean(winner) && !tournamentBracketMatchHasResult(match) ? match.status || "" : "";
  const wo = (match.status && normalize(match.status).startsWith("w.o") ? match.status : "") || semPlacar;
  const dica = [match.code, match.bestOf, match.status || (tournamentBracketMatchHasResult(match) ? "" : match.label)].filter(Boolean).join(", ");
  return `<button type="button" class="vp-bm" data-tournament-match="${escapeHtml(key)}" title="${escapeHtml(dica)}">${tournamentChaveLado(event, match.a, match.aLabel, match.scoreA, Boolean(winner) && winner === match.a)}${tournamentChaveLado(event, match.b, match.bLabel, match.scoreB, Boolean(winner) && winner === match.b)}${wo ? `<span class="vp-bm-wo">${escapeHtml(wo)}</span>` : ""}</button>`;
}

function tournamentChaveLado(event, teamId, label, score, venceu) {
  const team = teamId ? tournamentTeamById(event, teamId) : null;
  const nome = team?.name || label || "A definir";
  return `<span class="vp-bm-lado${venceu ? " vp-ganhou" : ""}" style="--team-line:${teamId ? teamLineColor(teamId) : TEAM_LINE_SEM_COR}">${teamId ? teamLogo(teamId, "tiny") : `<span class="team-logo clean-logo tiny logo-empty"></span>`}<span class="vp-bm-nome" title="${escapeHtml(nome)}">${escapeHtml(nome)}</span><b>${escapeHtml(String(score ?? ""))}</b></span>`;
}

function tournamentCuratedBracketQualifiedCard(event, card, context = {}) {
  const name = card.label || tournamentTeamById(event, card.id)?.name || card.id || "Equipe";
  const rowStart = tournamentBracketRowStart(card.slot ?? context.matchIndex, context.maxMatches || 1, card.slot == null ? context.columnMatches || 1 : context.maxMatches || 1);
  return `
    <article class="tournament-bracket-match curated-match qualified-card terminal ${card.id ? "" : "pending"}" aria-label="${escapeHtml(`Classificado: ${name}`)}" style="--match-row:${rowStart}">
      ${tournamentBracketQualifiedMeta(card)}
      <span class="tournament-bracket-team winner tournament-bracket-qualified-team">
        ${card.id ? teamLogo(card.id, "tiny") : `<span class="team-logo clean-logo tiny logo-empty"></span>`}
        <strong title="${escapeHtml(name)}">${escapeHtml(name)}</strong>
      </span>
    </article>
  `;
}

function tournamentBracketMatchWinner(match) {
  // Série sem placar, mas com vencedor declarado (a chave mostra quem avançou,
  // como nas séries inferidas da LBEU 2): vale o vencedor.
  if (!tournamentBracketMatchHasResult(match)) return match?.winner && match.a && match.b ? match.winner : "";
  if (match.winner) return match.winner;
  if (Number(match.scoreA) === Number(match.scoreB)) return "";
  return Number(match.scoreA) > Number(match.scoreB) ? match.a : match.b;
}

// O titulo da coluna ja diz "Classificados": o cartao so fala quando tem nota propria.
function tournamentBracketQualifiedMeta(card) {
  return card.note ? `<span class="tournament-bracket-meta"><span>${escapeHtml(card.note)}</span></span>` : "";
}

function tournamentBracketMatchHasResult(match) {
  return match?.scoreA != null && match?.scoreB != null;
}

function tournamentBracketMatchStatusLabel(match, round = null) {
  if (match?.status) return match.status;
  if (tournamentBracketMatchHasResult(match)) return "Concluída";
  return round?.status || "A jogar";
}

function tournamentBracketRowStart(matchIndex, maxMatches, columnMatches) {
  const safeMax = Math.max(maxMatches, 1);
  const safeCount = Math.max(columnMatches, 1);
  return Math.max(1, Math.round(((matchIndex + 0.5) * safeMax * 2) / safeCount - 1) + 1);
}

// Chave encadeada: cada partida declara em que faixa ("band") mora e de quais
// partidas ela vem ("from"). A grade alterna colunas de card e colunas de
// conector, entao a linha que liga dois cards e um item de grade com posicao
// exata em vez de um pseudo-elemento pendurado no card de origem.
const LINKED_BRACKET_UNITS_PER_BAND = 4;

function tournamentLinkedBracketRegion(event, region) {
  const columns = tournamentLinkedBracketColumns(event, region);
  const places = new Map();
  columns.forEach((column, columnIndex) => {
    column.entries.forEach((entry) => places.set(entry.id, { column: columnIndex, band: entry.band }));
  });
  const links = columns.flatMap((column, columnIndex) => column.entries.flatMap((entry) => (entry.from || [])
    .map((sourceId) => places.get(sourceId))
    .filter((source) => source && source.column < columnIndex)
    .map((source) => tournamentLinkedBracketLink(source, { column: columnIndex, band: entry.band }))));
  const template = columns.map(() => "var(--linked-col)").join(" var(--linked-gap) ");
  return `
    <section class="tournament-bracket-region linked-region ${escapeHtml(region.className || "")}">
      <h3>${escapeHtml(region.name || "Chave")}</h3>
      <div class="tournament-linked-bracket" style="--linked-template:${template}">
        ${columns.map((column, columnIndex) => (normalize(column.title || "") === normalize(region.name || "")
          ? ""
          : `<h4 class="linked-bracket-title" style="grid-column:${columnIndex * 2 + 1}; --ordem:${columnIndex * 2}">${escapeHtml(String(column.title || "").replace(`${region.name} - `, ""))}</h4>`)).join("")}
        ${links.join("")}
        ${columns.flatMap((column, columnIndex) => column.entries.map((entry) => entry.render(tournamentLinkedBracketPlacement(columnIndex, entry.band)))).join("")}
      </div>
    </section>
  `;
}

function tournamentLinkedBracketColumns(event, region) {
  const columns = (region.columns || []).map((column, columnIndex) => ({
    title: column.title,
    entries: (column.matches || []).map((match, matchIndex) => ({
      id: match.code,
      band: Number(match.band ?? matchIndex),
      from: match.from,
      render: (placement) => tournamentLinkedBracketMatch(event, match, tournamentBracketMatchKey(columnIndex, matchIndex, match.code), placement),
    })),
  }));
  const cards = region.terminalColumn?.cards || [];
  if (cards.length) {
    columns.push({
      title: region.terminalColumn.title || "Classificados",
      entries: cards.map((card, cardIndex) => ({
        id: `${region.name}::classificado::${cardIndex}`,
        band: Number(card.band ?? cardIndex),
        from: card.from,
        render: (placement) => tournamentLinkedBracketQualifiedCard(event, card, placement),
      })),
    });
  }
  return columns;
}

function tournamentLinkedBracketPlacement(columnIndex, band) {
  const rowStart = 2 + Math.round(band * LINKED_BRACKET_UNITS_PER_BAND);
  return `grid-column:${columnIndex * 2 + 1}; grid-row:${rowStart} / span ${LINKED_BRACKET_UNITS_PER_BAND}; --ordem:${columnIndex * 2 + 1}`;
}

function tournamentLinkedBracketLink(source, target) {
  const first = Math.min(source.band, target.band);
  const last = Math.max(source.band, target.band);
  const rows = Math.round((last - first) * LINKED_BRACKET_UNITS_PER_BAND) + LINKED_BRACKET_UNITS_PER_BAND;
  const center = (band) => `${((((band - first) * LINKED_BRACKET_UNITS_PER_BAND + LINKED_BRACKET_UNITS_PER_BAND / 2) / rows) * 100).toFixed(3)}%`;
  const style = [
    `grid-column:${source.column * 2 + 2} / ${target.column * 2 + 1}`,
    `grid-row:${2 + Math.round(first * LINKED_BRACKET_UNITS_PER_BAND)} / span ${rows}`,
    `--linked-y-from:${center(source.band)}`,
    `--linked-y-to:${center(target.band)}`,
  ].join("; ");
  const straight = source.band === target.band;
  const elbow = straight ? "" : `<span class="linked-link-drop" style="--linked-y-top:${center(first)}; --linked-y-bottom:${center(last)}"></span>`;
  return `<span class="linked-link${straight ? " straight" : ""}" aria-hidden="true" style="${style}">${elbow}</span>`;
}

function tournamentLinkedBracketMatch(event, match, key, placement) {
  return `<div class="linked-match vp-celula" style="${placement}">${tournamentChaveBotao(event, match, key)}</div>`;
}

function tournamentLinkedBracketQualifiedCard(event, card, placement) {
  const name = card.label || tournamentTeamById(event, card.id)?.name || card.id || "Equipe";
  return `
    <div class="linked-match vp-celula" style="${placement}">
      <article class="qualified-card terminal ${card.id ? "" : "pending"}" aria-label="${escapeHtml(`${card.note || "Classificado"}: ${name}`)}">
        ${tournamentBracketQualifiedMeta(card)}
        <span class="tournament-bracket-team winner tournament-bracket-qualified-team">
          ${card.id ? teamLogo(card.id, "tiny") : `<span class="team-logo clean-logo tiny logo-empty"></span>`}
          <strong title="${escapeHtml(name)}">${escapeHtml(name)}</strong>
        </span>
      </article>
    </div>
  `;
}

function tournamentBracketMatchKey(columnIndex, matchIndex, code) {
  return `${columnIndex}-${matchIndex}-${slugify(code || "partida")}`;
}

function tournamentBracketEntries(event, matches) {
  const entries = new Map();
  if (event.swiss?.rounds?.length) {
    event.swiss.rounds.forEach((round, roundIndex) => {
      (round.matches || []).forEach((match, matchIndex) => {
        const key = tournamentSwissMatchKey(roundIndex, matchIndex, match.code);
        entries.set(key, {
          event,
          region: { name: event.bracket?.title || event.format?.summary || "Sistema suíço" },
          column: { title: round.title || `Rodada ${roundIndex + 1}` },
          match: { ...match, bestOf: match.bestOf || round.bestOf },
          series: tournamentSeriesForBracketMatch(matches, match),
        });
      });
    });
  }
  if (!event.bracket?.regions?.length) return entries;
  for (const region of event.bracket.regions) {
    region.columns.forEach((column, columnIndex) => {
      column.matches.forEach((match, matchIndex) => {
        const key = tournamentBracketMatchKey(columnIndex, matchIndex, match.code);
        entries.set(key, { event, region, column, match, series: tournamentSeriesForBracketMatch(matches, match) });
      });
    });
  }
  return entries;
}

function tournamentSeriesForBracketMatch(matches, match) {
  // Avanços diretos não têm partida disputada para abrir nas estatísticas.
  if (!match.a || !match.b) return null;
  const codeNumber = tournamentMatchCodeNumber(match.code);
  // Chaves com referência explícita não podem reutilizar outro encontro do par.
  const candidates = match.seriesCode == null
    ? matches
    : matches.filter((series) => Number(series.seriesCode) === Number(match.seriesCode));
  const ranked = candidates
    .map((series) => ({ series, score: tournamentBracketSeriesFit(series, match, codeNumber) }))
    .filter((candidate) => candidate.score > 0)
    .sort((a, b) => b.score - a.score || Number(b.series.sortAt || 0) - Number(a.series.sortAt || 0));
  return ranked[0]?.series || null;
}

function tournamentBracketSeriesFit(series, match, codeNumber) {
  const hasBothTeams = Boolean(match.a && match.b);
  const sameOrientation = series.teamA.id === match.a && series.teamB.id === match.b;
  const reverseOrientation = series.teamA.id === match.b && series.teamB.id === match.a;
  const samePair = sameOrientation || reverseOrientation;
  const sameCode = Number.isFinite(codeNumber) && Number(series.seriesCode) === codeNumber;

  if (hasBothTeams && !samePair) return 0;
  if (!hasBothTeams && !sameCode) return 0;

  let score = samePair ? 100 : 0;
  if (sameCode) score += 12;
  if (!tournamentBracketMatchHasResult(match)) return sameCode ? score : 0;

  if (sameOrientation && tournamentBracketScoresMatch(series.roundScoreA, series.roundScoreB, match.scoreA, match.scoreB)) score += 80;
  if (reverseOrientation && tournamentBracketScoresMatch(series.roundScoreB, series.roundScoreA, match.scoreA, match.scoreB)) score += 80;
  if (sameOrientation && tournamentBracketScoresMatch(series.scoreA, series.scoreB, match.scoreA, match.scoreB)) score += 70;
  if (reverseOrientation && tournamentBracketScoresMatch(series.scoreB, series.scoreA, match.scoreA, match.scoreB)) score += 70;

  return score;
}

function tournamentBracketScoresMatch(leftA, leftB, rightA, rightB) {
  const values = [leftA, leftB, rightA, rightB].map(Number);
  if (values.some((value) => !Number.isFinite(value))) return false;
  return values[0] === values[2] && values[1] === values[3];
}

function tournamentMatchCodeNumber(code) {
  const match = String(code || "").match(/\d+/);
  return match ? Number(match[0]) : NaN;
}

// Chave e rodadas podem dividir a mesma aba, entao o clique e ouvido no painel.
function bindTournamentBracketPreview(event, matches) {
  const painel = document.querySelector(".tournament-main");
  if (!painel) return;
  const entries = tournamentBracketEntries({ ...event, bracket: tournamentBracketDefinition(event, matches) }, matches);
  painel.addEventListener("click", (clickEvent) => {
    const button = clickEvent.target.closest("[data-tournament-match]");
    if (!button) return;
    const entry = entries.get(button.dataset.tournamentMatch);
    if (!entry) return;
    openTournamentMatchPreview(entry);
  });
}

function bindTournamentTeamPreview(event, matches) {
  const root = document.querySelector("[data-tournament-teams]");
  if (!root) return;
  const fecharElencos = (exceto = null) => root.querySelectorAll(".vp-eq.aberta").forEach((caixa) => {
    if (caixa === exceto) return;
    caixa.classList.remove("aberta");
    caixa.querySelector("[aria-expanded]")?.setAttribute("aria-expanded", "false");
  });
  root.addEventListener("click", (clickEvent) => {
    const detalhes = clickEvent.target.closest("[data-tournament-team-detalhes]");
    if (detalhes) {
      fecharElencos();
      openTournamentTeamPreview(event, matches, detalhes.dataset.tournamentTeamDetalhes);
      return;
    }
    const button = clickEvent.target.closest("[data-tournament-team]");
    if (!button) return;
    // Com mouse o elenco ja desceu no hover e o clique vai direto aos detalhes; no
    // toque o primeiro clique abre o elenco, e os detalhes ficam no botao dele.
    if (window.matchMedia?.("(hover: hover)").matches) {
      openTournamentTeamPreview(event, matches, button.dataset.tournamentTeam);
      return;
    }
    const caixa = button.closest(".vp-eq");
    if (!caixa?.querySelector(".vp-eq-elenco")) return;
    fecharElencos(caixa);
    const aberta = caixa.classList.toggle("aberta");
    button.setAttribute("aria-expanded", String(aberta));
  });
  // Toque fora fecha o elenco aberto. Um ouvinte so, para a pagina inteira.
  if (!bindTournamentTeamPreview.fora) {
    bindTournamentTeamPreview.fora = true;
    document.addEventListener("click", (clickEvent) => {
      if (clickEvent.target.closest?.(".vp-eq-caixa .vp-eq")) return;
      document.querySelectorAll(".vp-eq-caixa .vp-eq.aberta").forEach((caixa) => {
        caixa.classList.remove("aberta");
        caixa.querySelector("[aria-expanded]")?.setAttribute("aria-expanded", "false");
      });
    });
  }
}

function openTournamentMatchPreview(entry) {
  const root = ensureTournamentPreviewRoot();
  if (!root) return;
  root.innerHTML = ligarFasesDaEpoca(tournamentMatchPreviewHtml(entry));
  root.classList.add("open");
  root.querySelector("[data-tournament-preview-close]")?.focus();
}

function ensureTournamentPreviewRoot() {
  if (!document.body || !document.createElement) return null;
  let root = document.getElementById("tournament-match-preview");
  if (!root) {
    root = document.createElement("div");
    root.id = "tournament-match-preview";
    root.className = "tournament-match-preview";
    document.body.appendChild(root);
    root.addEventListener("click", (event) => {
      const openMatchLink = event.target.closest("[data-open-match-tab]");
      if (openMatchLink) {
        closeTournamentMatchPreview();
        return;
      }
      const openTeamLink = event.target.closest("[data-open-team-page]");
      if (openTeamLink) {
        closeTournamentMatchPreview();
        return;
      }
      const openPlayerLink = event.target.closest("[data-open-player-page]");
      if (openPlayerLink) {
        closeTournamentMatchPreview();
        return;
      }
      if (event.target === root || event.target.closest("[data-tournament-preview-close]")) closeTournamentMatchPreview();
    });
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") closeTournamentMatchPreview();
    });
  }
  return root;
}

function closeTournamentMatchPreview() {
  const root = document.getElementById("tournament-match-preview");
  if (!root) return;
  root.classList.remove("open");
  root.innerHTML = "";
}

function openTournamentTeamPreview(event, matches, teamId) {
  const root = ensureTournamentPreviewRoot();
  if (!root) return;
  root.innerHTML = ligarFasesDaEpoca(tournamentTeamPreviewHtml(event, matches, teamId));
  root.classList.add("open");
  root.querySelector("[data-tournament-preview-close]")?.focus();
}

// O menu da equipe: a camisa dela no topo, com a campanha, e o elenco com as fotos. A
// campanha e a mesma conta da Colocacao, para o W.O. nao dar numero diferente. Mapas e
// saldo saem das series: com colocacao parcial, a lista oficial nao tem os finalistas.
function tournamentTeamPreviewHtml(event, matches, teamId) {
  const team = tournamentTeamById(event, teamId);
  const standing = eventStandings(matches).find((row) => row.id === teamId) || {};
  const campanha = tournamentCampanhas(event, matches).get(teamId);
  const lineup = tournamentLineupRows(teamId, matches);
  const teamMatches = tournamentTeamSeriesRows(teamId, matches);
  const origem = tournamentOrigens(event).get(teamId);
  const numeros = [
    ["Séries", campanha ? `${campanha[0]}-${campanha[1]}` : `${standing.seriesWins || 0}-${standing.seriesLosses || 0}`],
    ["Mapas", `${standing.mapWins || 0}-${standing.mapLosses || 0}`],
    ["Saldo", signed(standing.roundDiff || 0)],
  ];
  return `
    <div class="tournament-match-preview-card tournament-lineup-preview-card vp-eq-menu" style="${escapeHtml(teamPlateStyle(team))}" role="dialog" aria-modal="true" aria-label="${escapeHtml(`${team?.name || "Equipe"} em ${event.name}`)}">
      <button type="button" class="preview-close" data-tournament-preview-close aria-label="Fechar">&times;</button>
      <header class="vp-slide vp-menu-topo">
        <span class="vp-slide-campo"><i></i></span>
        ${teamLogo(teamId, "large")}
        <span class="vp-menu-id">
          <small>${escapeHtml(event.name)}</small>
          <h3>${escapeHtml(team?.name || "Equipe")}</h3>
          <small>${escapeHtml([team?.sourceTag || team?.tag || teamId, origem ? `via ${origem}` : ""].filter(Boolean).join(", "))}</small>
        </span>
        <dl class="vp-menu-numeros">${numeros.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${escapeHtml(valor)}</dd></div>`).join("")}</dl>
      </header>
      <div class="tournament-lineup-tabs">
        <input type="radio" name="lineup-tab-${escapeHtml(teamId)}" id="lineup-performance-${escapeHtml(teamId)}" checked />
        <input type="radio" name="lineup-tab-${escapeHtml(teamId)}" id="lineup-matches-${escapeHtml(teamId)}" />
        <div class="lineup-tab-labels">
          <label for="lineup-performance-${escapeHtml(teamId)}">Desempenho</label>
          <label for="lineup-matches-${escapeHtml(teamId)}">Partidas</label>
        </div>
        <div class="lineup-tab-window">
          <div class="lineup-tab-track">
            <section class="lineup-tab-panel">
              ${lineup.length
                ? `<div class="vp-lu-cab" aria-hidden="true"><span>Jogador</span><span>Agentes</span><span>rAAting</span><span>Mapas</span><span>K/D/A</span></div><div class="vp-lu-lista">${lineup.map((row) => tournamentLineupPlayerCard(row, team)).join("")}</div>`
                : `<div class="empty-state">Line-up indisponível para este torneio.</div>`}
            </section>
            <section class="lineup-tab-panel">
              <div class="lineup-match-list vp-lista">
                ${teamMatches.length ? teamMatches.map(matchResultRow).join("") : `<div class="empty-state">Nenhuma partida registrada para esta equipe.</div>`}
              </div>
            </section>
          </div>
        </div>
      </div>
      <div class="preview-actions">
        ${team && !team.missing ? `<a class="action-link primary" href="#/teams/${team.id}" data-open-team-page>Abrir página da equipe</a>` : ""}
      </div>
    </div>
  `;
}

function tournamentTeamSeriesRows(teamId, matches) {
  return (matches || []).filter((series) => seriesHasTeam(series, teamId)).sort(compareSeriesDateDesc);
}

function tournamentLineupRows(teamId, matches) {
  const rows = new Map();
  for (const series of matches || []) {
    for (const match of series.maps || []) {
      for (const player of match.players || []) {
        if (player.teamId !== teamId) continue;
        if (!rows.has(player.id)) {
          rows.set(player.id, {
            id: player.id,
            nick: player.nick,
            handle: player.handle,
            maps: 0,
            rounds: 0,
            kills: 0,
            deaths: 0,
            assists: 0,
            ratingTotal: 0,
            agents: new Map(),
            papeis: new Map(),
          });
        }
        const row = rows.get(player.id);
        row.maps += 1;
        row.rounds += Number(player.rounds || 0);
        row.kills += Number(player.kills || 0);
        row.deaths += Number(player.deaths || 0);
        row.assists += Number(player.assists || 0);
        row.ratingTotal += Number(player.rating || 0) * Number(player.rounds || 0);
        const papel = normalizeRoleKey(player.agentClass || "");
        if (papel) row.papeis.set(papel, (row.papeis.get(papel) || 0) + Number(player.rounds || 0));
        const agentKey = player.agentSlug || player.agent || "agent";
        const agent = row.agents.get(agentKey) || { slug: player.agentSlug, name: player.agent, icon: player.agentIcon, maps: 0 };
        agent.maps += 1;
        row.agents.set(agentKey, agent);
      }
    }
  }
  return [...rows.values()]
    .map((row) => ({ ...row, funcao: [...row.papeis].sort((a, b) => b[1] - a[1])[0]?.[0] || "", rating: row.rounds ? row.ratingTotal / row.rounds : 0, agents: [...row.agents.values()].sort((a, b) => b.maps - a.maps || String(a.name).localeCompare(String(b.name))) }))
    .sort((a, b) => b.maps - a.maps || b.rounds - a.rounds || b.rating - a.rating || a.nick.localeCompare(b.nick));
}

// A tira da pagina de Jogadores: foto e nome na cor 1, dados na cor 2. A figura e a
// mesma do cartao, com a silhueta para quem nao tem foto.
function tournamentLineupPlayerCard(row, team) {
  return `
    <a class="vp-slide vp-lu" href="${playerHref(row.id)}" data-open-player-page>
      <span class="vp-slide-campo"><i></i></span>
      ${playerFigure(playerById(row.id), team)}
      <span class="vp-lu-nome"><strong>${escapeHtml(row.nick)}</strong><small>${escapeHtml(row.handle || "")}</small></span>
      <span class="vp-lu-agentes">${row.agents.slice(0, 4).map(tournamentLineupAgent).join("")}</span>
      <b data-rotulo="rAAting">${escapeHtml(playerRating(row))}</b>
      <b data-rotulo="mapas">${escapeHtml(String(row.maps))}</b>
      <b data-rotulo="K/D/A">${escapeHtml(`${row.kills}/${row.deaths}/${row.assists}`)}</b>
    </a>
  `;
}

function tournamentLineupAgent(agent) {
  const src = assetPath(agent.icon || "");
  const label = agent.name || agent.slug || "Agente";
  return `<span title="${escapeHtml(`${label} - ${agent.maps} mapa(s)`)}">${src ? `<img src="${escapeHtml(src)}" alt="${escapeHtml(label)}" loading="lazy" onerror="this.remove()" />` : escapeHtml(String(label).slice(0, 2).toUpperCase())}</span>`;
}

function tournamentMatchPreviewHtml(entry) {
  const { event, region, column, match, series } = entry;
  const hasResult = tournamentBracketMatchHasResult(match);
  // Série inferida pela chave tem vencedor declarado e nenhum placar.
  const winnerId = hasResult ? match.winner || (Number(match.scoreA) > Number(match.scoreB) ? match.a : match.b) : tournamentBracketMatchWinner(match);
  const decided = hasResult || Boolean(winnerId);
  const teamA = tournamentTeamById(event, match.a);
  const teamB = tournamentTeamById(event, match.b);
  return `
    <div class="tournament-match-preview-card" role="dialog" aria-modal="true" aria-label="Resumo da partida">
      <button type="button" class="preview-close" data-tournament-preview-close aria-label="Fechar">&times;</button>
      <div class="preview-kicker">${escapeHtml(region.name || "Bracket")} - ${escapeHtml(column.title || "Rodada")}</div>
      <h3>${escapeHtml(match.code || "Partida")} ${match.bestOf ? `<span>${escapeHtml(match.bestOf)}</span>` : ""}</h3>
      <div class="preview-scoreboard">
        ${tournamentPreviewTeam(event, teamA, match.scoreA, winnerId === match.a, decided)}
        <span class="preview-score">${escapeHtml(String(match.scoreA ?? "-"))}<small>x</small>${escapeHtml(String(match.scoreB ?? "-"))}</span>
        ${tournamentPreviewTeam(event, teamB, match.scoreB, winnerId === match.b, decided)}
      </div>
      <div class="preview-summary-grid">
        <span><small>${decided ? "Vencedor" : "Status"}</small><strong>${escapeHtml(decided ? tournamentTeamById(event, winnerId)?.name || "Concluída" : tournamentBracketMatchStatusLabel(match))}</strong></span>
        <span><small>Formato</small><strong>${escapeHtml(match.bestOf || series?.label || "MD1")}</strong></span>
        <span><small>Data</small><strong>${escapeHtml(match.playedAt ? formatDate(match.playedAt, "time") : series ? formatDate(series.startedAt, "time") : match.playedOn ? formatDate(match.playedOn) : eventTimeRange(event))}</strong></span>
      </div>
      ${series && match.previewNote ? `<div class="empty-state">${escapeHtml(match.previewNote)}</div>` : ""}
      ${series ? tournamentPreviewSeriesDetails(series) : `<div class="empty-state">${escapeHtml(match.previewNote || "Resumo oficial da chave. Detalhes não disponíveis para essa partida.")}</div>`}
      <div class="preview-actions">
        ${series ? `<a class="action-link primary" href="${matchSeriesHref(series)}" target="_blank" rel="noopener" data-open-match-tab>Ver página da partida</a>` : `<span class="action-link disabled">Página da partida indisponível.</span>`}
      </div>
      <div class="preview-open-status" data-open-match-status hidden><span aria-hidden="true">&#10003;</span>Partida aberta em uma nova aba</div>
    </div>
  `;
}

function tournamentPreviewTeam(event, team, score, won, decided = true) {
  if (!team) return `<span class="preview-team"><span class="team-logo clean-logo logo-empty"></span><strong>Sem adversário</strong><small>${escapeHtml(String(score ?? "-"))}</small></span>`;
  return `
    <span class="preview-team ${won ? "winner" : ""}">
      ${teamLogo(team.id)}
      <strong>${escapeHtml(team.name)}</strong>
      <small>${decided ? (won ? "Vitória" : "Derrota") : "A definir"}</small>
    </span>
  `;
}

function tournamentPreviewSeriesDetails(series) {
  return `
    <div class="preview-series">
      <div class="preview-map-list">
        ${series.maps
          .map((match, index) => {
            const scoreA = scoreForTeamInMatch(match, series.teamA.id);
            const scoreB = scoreForTeamInMatch(match, series.teamB.id);
            return `<span><small>Mapa ${match.mapNumber || index + 1}</small><strong>${escapeHtml(match.mapName)}</strong><em>${scoreA} - ${scoreB}</em></span>`;
          })
          .join("")}
      </div>
      <div class="preview-summary-grid">
        <span><small>Rounds</small><strong>${series.roundScoreA}-${series.roundScoreB}</strong></span>
        <span><small>Mapas</small><strong>${escapeHtml(series.mapNames.join(" / "))}</strong></span>
        <span><small>MVP</small><strong>${escapeHtml(series.mvp?.nick || "-")}</strong></span>
      </div>
    </div>
  `;
}

function tournamentBracketColumns(matches) {
  const sorted = matches.slice().sort((a, b) => (a.startedAt || a.sortAt || 0) - (b.startedAt || b.sortAt || 0)).slice(-7);
  if (!sorted.length) return [];
  if (sorted.length >= 7) {
    return [
      { title: "Quartas de final", matches: sorted.slice(0, 4) },
      { title: "Semifinais", matches: sorted.slice(4, 6) },
      { title: "Grande final", matches: sorted.slice(6, 7) },
    ];
  }
  if (sorted.length >= 3) {
    return [
      { title: "Semifinais", matches: sorted.slice(0, -1) },
      { title: "Grande final", matches: sorted.slice(-1) },
    ];
  }
  return [{ title: sorted.length > 1 ? "Partidas finais" : "Grande final", matches: sorted }];
}

function tournamentResultRows(event, standings) {
  if (event.placements?.length) return tournamentOfficialPlacements(event);
  if (!eventIsDone(event)) return tournamentEliminatedRows(event);
  return standings.slice(0, 16);
}

function tournamentEliminatedRows(event) {
  const rows = event.eliminated || event.swiss?.eliminated || [];
  return rows.map((row) => ({
    ...row,
    note: `${row.wins ?? 0}-${row.losses ?? 0}`,
    reason: row.reason || row.note || "",
    range: row.range || "Eliminado",
  }));
}

function tournamentPlacementIsFeatured(label, index) {
  const normalizedLabel = normalize(String(label || ""));
  if (normalizedLabel.startsWith("classificado")) return true;
  return Boolean(tournamentPlacementPodiumClass(label || placementLabel(index)));
}

function tournamentPlacementPodiumClass(label) {
  const value = String(label || "").trim();
  const normalizedLabel = normalize(value);
  const compactLabel = normalizeNameKey(value);
  if (value === "1" || normalizedLabel === "1st" || compactLabel === "1olugar") return "place-1";
  if (value === "2" || normalizedLabel === "2nd" || compactLabel === "2olugar") return "place-2";
  if (value === "3" || normalizedLabel === "3rd" || compactLabel === "3olugar" || compactLabel.startsWith("3o4") || /^3\D+4/.test(value)) return "place-3";
  return "";
}

// Rotulos como "Classificado" continuam visiveis quando o evento termina;
// "Em andamento" so aparece enquanto a disputa nao acabou.
function tournamentPlacementDisplayLabel(event, rawLabel) {
  if (placementIsOngoing(rawLabel)) return eventIsDone(event) ? String(rawLabel) : "Em andamento";
  return rankingPlacementLabel(rawLabel);
}

function tournamentOfficialPlacements(event) {
  const standingsByTeam = new Map(eventStandings(matchSeriesForEvent(event.id)).map((row) => [row.id, row]));
  return normalizePlacementRowsForDisplay(event.placements).map((row) => ({ ...(standingsByTeam.get(row.id) || {}), ...row }));
}

function placementLabel(index) {
  if (index === 0) return "1st";
  if (index === 1) return "2nd";
  if (index < 4) return "3-4th";
  if (index < 8) return "5-8th";
  if (index < 12) return "9-12th";
  if (index < 16) return "13-16th";
  return `${index + 1}th`;
}

function tournamentRankingSnapshot(event, matches = []) {
  const firstMatchAt = tournamentFirstMatchTimestamp(event, matches);
  if (!firstMatchAt) return latestRankingSnapshot();

  const cutoffAt = Math.max(0, firstMatchAt - 1);
  const cacheKey = `${event.id}:${cutoffAt}`;
  if (state.tournamentRankingCache.has(cacheKey)) return state.tournamentRankingCache.get(cacheKey);

  const snapshot = tournamentCalculatedRankingSnapshot(event, cutoffAt, firstMatchAt) || rankingSnapshotAtTimestamp(cutoffAt);
  state.tournamentRankingCache.set(cacheKey, snapshot);
  return snapshot;
}

function tournamentCalculatedRankingSnapshot(event, cutoffAt, eventDate) {
  if (!state.db || !window.RankingCore?.calculateTeamRankings) return null;
  try {
    const ranking = calculateRankingForCutoff({
      teams: state.db.teams,
      matches: state.db.matches,
      matchSeries: state.db.matchSeries,
      players: state.db.players,
      tournaments: state.db.tournaments,
      rankingWeights: state.db.rankingWeights || {},
      cutoffAt,
    });
    return {
      ...rankingSnapshotShell(cutoffAt, ranking, `Ranking em ${formatDate(eventDate, "date")}`),
      eventDate,
      eventId: event.id,
    };
  } catch (error) {
    console.error("Falha ao calcular ranking historico do campeonato", error);
    return null;
  }
}

function rankingSnapshotAtTimestamp(timestamp) {
  const snapshots = state.db?.rankingSnapshots || [];
  if (!snapshots.length) return null;
  return snapshots
    .filter((snapshot) => Number(snapshot.cutoffAt || 0) <= timestamp)
    .sort((a, b) => Number(b.cutoffAt || 0) - Number(a.cutoffAt || 0))[0] || snapshots.at(-1) || null;
}

function tournamentFirstMatchTimestamp(event, matches = []) {
  const dates = (matches || [])
    .flatMap((series) => [
      Number(series.startedAt || 0),
      Number(series.sortAt || 0),
      ...(series.maps || []).map((match) => Number(match.startedAt || 0)),
    ])
    .filter((value) => Number.isFinite(value) && value > 0)
    .sort((a, b) => a - b);
  return dates[0] || Number(event.start || 0) || null;
}

// Quem jogou, pelo ranking da data do evento. Cada quadrado abre o menu com o elenco
// em fotos, o desempenho e as partidas da equipe.
function tournamentTeamsSection(event, standings, matches = []) {
  const rows = tournamentTeamRows(event, standings, matches);
  const origens = tournamentOrigens(event);
  // Barra do nome com a mesma altura em todos os cartoes: se alguma equipe tem a
  // linha "Via", todas reservam essa linha.
  const temOrigem = rows.some((row) => origens.get(row.team.id));
  return `
    <section class="tournament-section vp-s-equipes">
      ${sectionHead("Equipes Participantes", `${rows.length} ${rows.length === 1 ? "equipe" : "equipes"}`)}
      <div class="vp-eq-grade" style="--por-linha:${tournamentEquipesPorLinha(rows.length)}" data-tournament-teams>
        ${rows.map((row) => tournamentEquipeQuadrado(row, origens.get(row.team.id), row.team.missing ? [] : tournamentLineupRows(row.team.id, matches), temOrigem)).join("") || `<div class="empty-state">Nenhum time detectado.</div>`}
      </div>
    </section>
  `;
}

// Fileiras completas sempre que der: 8 equipes em 4, 10 em 5, 12 em 6. Acima de 20
// vale o quadrado menor, para a secao nao passar de duas telas.
function tournamentEquipesPorLinha(total) {
  if (total > 20) return 6;
  const sobra = (colunas) => (colunas - (total % colunas)) % colunas;
  return [6, 5, 4].reduce((melhor, colunas) => (sobra(colunas) < sobra(melhor) ? colunas : melhor));
}

function tournamentTeamRows(event, standings, matches = []) {
  const statsByTeam = new Map(standings.map((row) => [row.id, row]));
  const orderedTeams = event.teams?.length ? event.teams : standings.map((row) => row.id);
  const rankingSnapshot = tournamentRankingSnapshot(event, matches);
  return orderedTeams
    .map((teamId) => ({
      ...(statsByTeam.get(teamId) || { id: teamId, seriesWins: 0, seriesLosses: 0, mapWins: 0, mapLosses: 0, roundDiff: 0 }),
      team: tournamentTeamById(event, teamId),
      eventRanking: rankingSnapshot?.byTeamId?.[teamId] || null,
      eventRankingDate: rankingSnapshot?.eventDate || rankingSnapshot?.cutoffAt || null,
    }))
    .filter((row) => row.team)
    .sort(compareTournamentTeamByRank);
}

// Ranking oficial na frente (do melhor para o pior); quem ainda esta com rank
// provisorio vai para o fim da lista, em ordem alfabetica entre si.
function compareTournamentTeamByRank(a, b) {
  const rankA = Number(a.eventRanking?.validRank || 0);
  const rankB = Number(b.eventRanking?.validRank || 0);
  if (rankA && rankB) return rankA - rankB;
  if (rankA !== rankB) return rankA ? -1 : 1;
  return String(a.team?.name || "").localeCompare(String(b.team?.name || ""), "pt-BR");
}

// Equipe sem cadastro (nenhuma partida na base, so o nome na chave): o quadrado
// fica so com o nome, sem painel e sem ranking, como a chave ja mostra.
function tournamentEquipeQuadrado(row, origem, elenco = [], temOrigem = false) {
  const team = row.team;
  const campo = `<span class="vp-slide-campo"><i></i></span>`;
  const logo = `<span class="vp-eq-logo">${teamLogo(team.id, "large")}</span>`;
  const texto = `<strong>${escapeHtml(team.name)}</strong>${origem ? `<small>Via ${escapeHtml(origem)}</small>` : temOrigem ? `<small aria-hidden="true">&nbsp;</small>` : ""}`;
  // Os rankings ficam numa faixa acima do quadrado, como a dos Melhores da semana:
  // fora da arte, eles continuam a vista e com o balao quando o elenco abre.
  const cabeca = `<p class="vp-eq-cabeca">${team.missing ? "" : tournamentEquipeRanking(row)}</p>`;
  if (team.missing) return `<div class="vp-eq-caixa">${cabeca}<div class="vp-slide vp-eq vp-eq-sem-perfil" style="${escapeHtml(teamPlateStyle(team))}" title="${escapeHtml(team.name)}">${campo}${logo}<span class="vp-eq-txt">${texto}</span></div></div>`;
  // So a arte abre o elenco; a barra do nome leva ao perfil da equipe.
  return `
    <div class="vp-eq-caixa">
      ${cabeca}
      <div class="vp-slide vp-eq" style="${escapeHtml(teamPlateStyle(team))}">
        ${campo}
        <div class="vp-eq-arte">
          <button type="button" class="vp-eq-abrir" data-tournament-team="${escapeHtml(team.id)}" aria-label="${escapeHtml(`Elenco de ${team.name}`)}" aria-expanded="false">${logo}</button>
        </div>
        <a class="vp-eq-txt" href="#/teams/${escapeHtml(team.id)}">${texto}</a>
        ${tournamentEquipeElenco(team, elenco)}
      </div>
    </div>
  `;
}

// O elenco que aparece sobre a arte do cartao ao passar o mouse, como o cartao de equipe da
// Liquipedia: o icone da funcao que o jogador mais fez no campeonato no lugar da
// bandeira, o nick com link para o perfil e o menu completo em "Ver detalhes". Nunca
// sai do quadrado: as linhas dividem a altura, e elenco grande em cartao baixo vira
// duas colunas.
function tournamentEquipeElenco(team, elenco) {
  const linhas = elenco.map((row) => {
    const funcao = ROLE_ICONS[row.funcao];
    const icone = funcao ? `<i class="vp-eq-funcao" style="--icone:url('${escapeHtml(assetPath(funcao.icon))}')" title="${escapeHtml(funcao.label)}"></i>` : `<i class="vp-eq-funcao vp-eq-funcao-vazia"></i>`;
    return `<a class="vp-eq-jogador" href="${playerHref(row.id)}">${icone}<span>${escapeHtml(row.nick)}</span></a>`;
  }).join("");
  // A classe diz o tamanho do elenco; o CSS decide pela altura da arte quando a
  // coluna unica deixaria a letra abaixo de 12px e abre a segunda.
  const tamanho = elenco.length >= 5 ? ` vp-eq-n${Math.min(elenco.length, 14)}` : "";
  return `
    <div class="vp-eq-elenco">
      <div class="vp-eq-jogadores"><div class="vp-eq-lista${tamanho}" style="--l1:${elenco.length || 1}; --l2:${Math.ceil(elenco.length / 2) || 1}">${linhas}</div></div>
      <button type="button" class="vp-eq-detalhes" data-tournament-team-detalhes="${escapeHtml(team.id)}">Ver detalhes</button>
    </div>
  `;
}

// Um ranking em cada ponta da faixa: o atual a esquerda e o da data do campeonato a
// direita. Quem esta inativa ou provisoria hoje fica so com o do inicio.
function tournamentEquipeRanking(row) {
  const hoje = teamValidRank(row.team);
  return `<span class="vp-eq-atual"${hoje ? ` title="Ranking atual"` : ""}>${hoje ? `#${hoje}` : ""}</span><span title="Ranking no início do Campeonato">${escapeHtml(tournamentTeamRankLabel(row))}</span>`;
}

function tournamentTeamRankLabel(row) {
  const rank = Number(row.eventRanking?.validRank || 0);
  if (rank > 0) return `#${rank}`;
  // Sem nenhuma partida antes do campeonato a equipe estreia nele: e nova, nao
  // inativa. A contagem e a do proprio ranking, que ja soma a heranca de sucessao.
  if (!Number(row.eventRanking?.matches || 0)) return "novo";
  return rankingIsInactive(row.eventRanking) ? "inativa" : "prov";
}

// O nome da fase, sem repetir o que a coluna ja diz: "Chave superior - Rodada 1",
// "Rodada de 32 superior" e "3º lugar" valem sozinhos; "Opening" precisa do grupo.
function tournamentJogoFase(region, column, unica) {
  const nome = region.name || "";
  const coluna = column.title || "";
  if (!coluna || normalize(coluna) === normalize(nome)) return nome || coluna || "Jogos";
  if (unica || /principal/i.test(nome) || /lugar/i.test(coluna)) return coluna;
  const palavras = normalize(coluna).split(/\s+/);
  return palavras.includes(normalize(nome).split(/\s+/).at(-1)) ? coluna : `${nome} - ${coluna}`;
}

// A trilha e cada sequencia que so anda para a frente: as rodadas, ou as colunas de
// uma regiao da chave. As regioes vem na ordem de exibicao, com a final por ultimo.
function tournamentJogosColunas(event) {
  const regioes = tournamentBracketDisplayRegions(event.bracket?.regions || []);
  return [
    ...(event.swiss?.rounds || []).map((round, indice) => ({ trilha: "rodadas", fase: round.title || `Rodada ${indice + 1}`, matches: round.matches || [] })),
    ...regioes.flatMap((region, regiao) => (region.columns || []).map((column) => ({ trilha: regiao, fase: tournamentJogoFase(region, column, regioes.length === 1), matches: column.matches || [] }))),
  ];
}

// Todo confronto do campeonato: as series com estatisticas e os resultados que so
// existem na chave (W.O., partida sem estatisticas). Assim a aba bate com a chave.
function tournamentJogos(event, matches) {
  const usadas = new Set();
  const jogos = [];
  tournamentJogosColunas(event).forEach(({ trilha, fase, matches: confrontos }, ordem) => {
    confrontos.filter((match) => match.a && match.b).forEach((match) => {
      const candidata = tournamentSeriesForBracketMatch(matches, match);
      const series = candidata && !usadas.has(candidata.seriesKey) ? candidata : null;
      if (series) usadas.add(series.seriesKey);
      const quando = series ? series.sortAt || series.startedAt : Date.parse(match.playedAt || match.playedOn || "") || 0;
      const vencedor = series ? series.winnerId : tournamentBracketMatchWinner(match);
      const perdedor = series ? series.loserId : vencedor && (vencedor === match.a ? match.b : match.a);
      jogos.push({ trilha, fase, ordem, match, series, quando, equipes: [match.a, match.b], vencedor, perdedor });
    });
  });
  matches.filter((series) => !usadas.has(series.seriesKey)).forEach((series) => {
    jogos.push({ trilha: "outros", fase: "Outros jogos", ordem: -1, match: null, series, quando: series.sortAt || series.startedAt, equipes: [series.teamA.id, series.teamB.id], vencedor: series.winnerId, perdedor: series.loserId });
  });
  return jogos;
}

function diaEmTexto(valor) {
  const data = new Date(valor);
  return `${data.getFullYear()}-${String(data.getMonth() + 1).padStart(2, "0")}-${String(data.getDate()).padStart(2, "0")}`;
}

function tournamentJogosFiltro() {
  const query = routeQuery();
  return { equipe: query.get("equipe") || "", mapa: query.get("mapa") || "", dia: query.get("dia") || "" };
}

// Cada filtro ignora a si mesmo na hora de contar a propria faceta, como em Partidas.
function tournamentJogoPassa(jogo, filtro, ignorar = "") {
  if (ignorar !== "equipe" && filtro.equipe && !jogo.equipes.includes(filtro.equipe)) return false;
  if (ignorar !== "mapa" && filtro.mapa && !jogo.series?.maps.some((match) => match.mapId === filtro.mapa)) return false;
  if (ignorar !== "dia" && filtro.dia && (!jogo.quando || diaEmTexto(jogo.quando) !== filtro.dia)) return false;
  return true;
}

function maisRecentePrimeiro(a, b) {
  return (b.quando || 0) - (a.quando || 0);
}

// A fase mais recente primeiro. Dentro de uma trilha a ordem nunca volta atras: a
// Rodada 7 fica acima da 6 mesmo com jogo da 6 remarcado para depois. Fase sem data
// (so W.O., ou ainda por jogar) herda da vizinha, e trilha sem data nenhuma, como a
// final por disputar, vai para o topo.
function tournamentJogosPorFase(jogos) {
  const grupos = new Map();
  jogos.slice().sort((a, b) => a.ordem - b.ordem).forEach((jogo) => {
    if (!grupos.has(jogo.fase)) grupos.set(jogo.fase, { titulo: jogo.fase, ordem: jogo.ordem, trilha: jogo.trilha, jogos: [], data: 0 });
    const grupo = grupos.get(jogo.fase);
    grupo.jogos.push(jogo);
    grupo.data = Math.max(grupo.data, jogo.quando || 0);
  });
  const lista = [...grupos.values()];
  const maisNova = Math.max(0, ...lista.map((grupo) => grupo.data));
  [...new Set(lista.map((grupo) => grupo.trilha))].forEach((trilha) => {
    const daTrilha = lista.filter((grupo) => grupo.trilha === trilha);
    const primeira = daTrilha.find((grupo) => grupo.data)?.data || maisNova;
    daTrilha.reduce((anterior, grupo) => {
      grupo.data = Math.max(grupo.data, anterior);
      return grupo.data;
    }, primeira);
  });
  return lista.sort((a, b) => b.data - a.data || b.ordem - a.ordem).map((grupo) => ({ ...grupo, jogos: grupo.jogos.slice().sort(maisRecentePrimeiro) }));
}

// O resultado que so existe na chave: sem pagina de partida, entao nao e link, e sem
// mapa para mostrar. O status por extenso explica por que.
function tournamentJogoSemArquivo(event, jogo) {
  const { match, vencedor } = jogo;
  const status = match.status || (vencedor ? "Sem estatísticas" : eventIsDone(event) ? "Sem resultado" : "A jogar");
  const lado = (teamId) => {
    const nome = tournamentTeamById(event, teamId)?.name || teamId;
    return `<strong title="${escapeHtml(nome)}"><span class="nome-rolante">${escapeHtml(nome)}</span></strong>`;
  };
  const classe = (teamId) => (vencedor && vencedor !== teamId ? " vp-pl-perdeu" : "");
  const numero = (valor, teamId) => `<b${vencedor === teamId ? ' class="vp-venceu"' : ""}>${escapeHtml(String(valor ?? "-"))}</b>`;
  return `
    <div class="vp-pl vp-pl-sem" style="--maps:1">
      <span class="vp-pl-topo">
        <span class="vp-pl-quando">${escapeHtml(jogo.quando ? dataSemAno(jogo.quando) : status)}</span>
        <span class="vp-pl-mapas">${jogo.quando ? `<span class="vp-pl-mapa">${escapeHtml(status)}</span>` : ""}</span>
        <span class="vp-pl-evento"></span>
      </span>
      <span class="vp-pl-lado vp-pl-a${classe(match.a)}">${teamLogo(match.a)}${lado(match.a)}</span>
      <span class="vp-pl-placar">${numero(match.scoreA, match.a)}<i>:</i>${numero(match.scoreB, match.b)}</span>
      <span class="vp-pl-lado vp-pl-b${classe(match.b)}">${lado(match.b)}${teamLogo(match.b)}</span>
    </div>
  `;
}

// Os jogos do campeonato inteiro: os de cada etapa, como a etapa os monta (chave e
// series), marcados com a etapa de onde vieram.
function tournamentJogosDoGeral(campeonato) {
  return campeonato.etapas.flatMap((etapa) => tournamentJogos(etapa, matchSeriesForEvent(etapa.id)).map((jogo) => ({ ...jogo, etapa })));
}

// No Geral a lista anda por etapa, na ordem da faixa, e dentro dela por fase.
function tournamentJogosPorEtapa(campeonato, jogos) {
  return campeonato.etapas
    .map((etapa) => {
      const daEtapa = jogos.filter((jogo) => jogo.etapa === etapa);
      if (!daEtapa.length) return "";
      return `
        <section class="vp-jogos-etapa">
          <h3 class="vp-jogos-etapa-titulo"><a href="#/events/${escapeHtml(etapa.id)}/jogos">${escapeHtml(etapa.etapaNome)}</a><span>${daEtapa.length} ${daEtapa.length === 1 ? "série" : "séries"}</span></h3>
          ${tournamentJogosGrupos(etapa, tournamentJogosPorFase(daEtapa))}
        </section>
      `;
    })
    .join("");
}

function tournamentJogosGrupos(event, grupos) {
  return grupos
    .map((grupo) => `
      <section class="vp-jogos-grupo">
        <h3 class="vp-jogos-titulo">${escapeHtml(grupo.titulo)}<span>${grupo.jogos.length} ${grupo.jogos.length === 1 ? "série" : "séries"}</span></h3>
        <div class="vp-lista">
          ${grupo.jogos.map((jogo) => (jogo.series ? matchResultRow(jogo.series, { semEvento: true, when: "curta" }) : tournamentJogoSemArquivo(event, jogo))).join("")}
        </div>
      </section>
    `)
    .join("");
}

function tournamentJogosMapas(jogos, filtro) {
  const contagem = new Map();
  jogos.filter((jogo) => tournamentJogoPassa(jogo, filtro, "mapa")).forEach((jogo) => {
    (jogo.series?.mapNames || []).filter(Boolean).forEach((nome) => contagem.set(nome, (contagem.get(nome) || 0) + 1));
  });
  return barrasDosMapas(contagem, filtro.mapa ? [filtro.mapa] : [], "data-jogos-mapa");
}

// So os dias com jogo: em campeonato de meses, o eixo corrido deixaria barras de 2px.
function tournamentJogosDias(jogos, filtro) {
  const dias = [...new Set(jogos.filter((jogo) => jogo.quando).map((jogo) => diaEmTexto(jogo.quando)))].sort();
  if (dias.length < 2) return "";
  const contagem = new Map();
  jogos.filter((jogo) => jogo.quando && tournamentJogoPassa(jogo, filtro, "dia")).forEach((jogo) => {
    const dia = diaEmTexto(jogo.quando);
    contagem.set(dia, (contagem.get(dia) || 0) + 1);
  });
  const rotulo = (dia) => `${contagem.get(dia) || 0} em ${formatDate(dateInputToStart(dia), "date")}`;
  const maior = Math.max(1, ...contagem.values());
  const pico = dias.reduce((melhor, dia) => ((contagem.get(dia) || 0) > (contagem.get(melhor) || 0) ? dia : melhor), dias[0]);
  const leitura = rotulo(filtro.dia || pico);
  return `
    <section class="vp-resumo-bloco vp-meses vp-jogos-dias" aria-label="Partidas por dia">
      <h3>Partidas por dia <span data-resumo-leitura data-padrao="${escapeHtml(leitura)}">${escapeHtml(leitura)}</span></h3>
      <div class="vp-rt${filtro.dia ? " vp-rt-marcado" : ""}">
        ${dias.map((dia) => `<button type="button" class="vp-rt-mes" data-jogos-dia="${dia}" data-rotulo="${escapeHtml(rotulo(dia))}" aria-label="${escapeHtml(rotulo(dia))}" aria-pressed="${filtro.dia === dia}" style="--altura:${((contagem.get(dia) || 0) / maior).toFixed(4)}"><i></i></button>`).join("")}
      </div>
      <div class="vp-rt-eixo"><span>${escapeHtml(formatDate(dateInputToStart(dias[0]), "date"))}</span><span>${escapeHtml(formatDate(dateInputToStart(dias.at(-1)), "date"))}</span></div>
    </section>
  `;
}

function tournamentJogosResumo(event, jogos, filtro) {
  const ids = [...new Set(jogos.flatMap((jogo) => jogo.equipes))];
  const equipes = ids.map((id) => tournamentTeamById(event, id)).filter(Boolean).sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  const team = filtro.equipe ? teamById(filtro.equipe) : null;
  const daEquipe = team ? jogos.filter((jogo) => tournamentJogoPassa(jogo, filtro)).map((jogo) => ({ winnerId: jogo.vencedor, loserId: jogo.perdedor })) : [];
  const ativo = filtro.equipe || filtro.mapa || filtro.dia;
  const mapas = tournamentJogosMapas(jogos, filtro);
  return `
    <aside class="vp-resumo" aria-label="Filtros dos jogos">
      <section class="vp-resumo-bloco vp-jogos-filtro">
        <h3>Equipe ${ativo ? `<button type="button" class="vp-filtros-limpar" data-jogos-limpar>Limpar filtros</button>` : ""}</h3>
        <select data-jogos-equipe aria-label="Filtrar por equipe">
          <option value="">Todas as equipes</option>
          ${equipes.map((item) => `<option value="${escapeHtml(item.id)}"${item.id === filtro.equipe ? " selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}
        </select>
      </section>
      ${team && daEquipe.length ? cartaoDaEquipe(daEquipe, team) : ""}
      ${mapas ? `<div class="vp-jogos-mapas">${sectionHead("Mapas jogados")}${mapas}</div>` : ""}
      ${tournamentJogosDias(jogos, filtro)}
    </aside>
  `;
}

function tournamentMatchesSection(event, matches) {
  const filtro = tournamentJogosFiltro();
  const jogos = event.isGeral ? tournamentJogosDoGeral(event.campeonato) : tournamentJogos(event, matches);
  const visiveis = jogos.filter((jogo) => tournamentJogoPassa(jogo, filtro));
  const total = jogos.length;
  const comDados = jogos.filter((jogo) => jogo.series).length;
  const contagem = visiveis.length < total
    ? `${visiveis.length} de ${total} séries`
    : `${total} ${total === 1 ? "série" : "séries"}${comDados < total ? `, ${comDados} com estatísticas` : ""}`;
  const lista = event.isGeral ? tournamentJogosPorEtapa(event.campeonato, visiveis) : tournamentJogosGrupos(event, tournamentJogosPorFase(visiveis));
  return `
    <section class="tournament-section vp-jogos">
      <div class="vp-jogos-lista">
        ${sectionHead("Jogos", contagem)}
        ${visiveis.length ? lista : `<div class="empty-state">Nenhum jogo com esses filtros. Tire um filtro para ver mais.</div>`}
      </div>
      ${tournamentJogosResumo(event, jogos, filtro)}
    </section>
  `;
}

// O filtro mora na URL: da para compartilhar o link com a equipe ja marcada.
function bindJogosDoCampeonato() {
  const pagina = document.querySelector(".vp-jogos");
  if (!pagina) return;
  const resumo = pagina.querySelector(".vp-resumo");
  resumo?.style.setProperty("--resumo-altura", `${resumo.offsetHeight}px`);
  const aplica = (mudanca, foco) => {
    const query = routeQuery();
    mudanca(query);
    pushFilterState(routePath().slice(2), query, foco);
  };
  const alterna = (chave, valor, foco) => aplica((query) => {
    if (query.get(chave) === valor) query.delete(chave);
    else query.set(chave, valor);
  }, foco);
  pagina.querySelector("[data-jogos-equipe]")?.addEventListener("change", (event) => {
    aplica((query) => {
      if (event.target.value) query.set("equipe", event.target.value);
      else query.delete("equipe");
    }, "[data-jogos-equipe]");
  });
  pagina.addEventListener("click", (event) => {
    const mapa = event.target.closest("[data-jogos-mapa]");
    const dia = event.target.closest("[data-jogos-dia]");
    if (mapa) alterna("mapa", mapa.dataset.jogosMapa, `[data-jogos-mapa="${mapa.dataset.jogosMapa}"]`);
    if (dia) alterna("dia", dia.dataset.jogosDia, `[data-jogos-dia="${dia.dataset.jogosDia}"]`);
    if (event.target.closest("[data-jogos-limpar]")) aplica((query) => ["equipe", "mapa", "dia"].forEach((chave) => query.delete(chave)), "[data-jogos-equipe]");
  });
  const leitura = pagina.querySelector("[data-resumo-leitura]");
  if (!leitura) return;
  ["mouseover", "focusin"].forEach((tipo) => pagina.addEventListener(tipo, (event) => {
    const dia = event.target.closest("[data-jogos-dia]");
    if (dia) leitura.textContent = dia.dataset.rotulo;
  }));
  ["mouseout", "focusout"].forEach((tipo) => pagina.addEventListener(tipo, (event) => {
    if (event.target.closest("[data-jogos-dia]")) leitura.textContent = leitura.dataset.padrao;
  }));
}

function tournamentEstFiltro() {
  const query = routeQuery();
  return { equipe: query.get("equipe") || "", mapa: query.get("mapa") || "", rounds: Number.parseInt(query.get("rounds") || "0", 10) || 0 };
}

// Com um mapa so nao existe serie: cada mapa filtrado conta como uma partida isolada.
function tournamentSerieDoMapa(match) {
  const venceuA = match.winnerId === match.teamA.id;
  return { teamA: match.teamA, teamB: match.teamB, scoreA: venceuA ? 1 : 0, scoreB: venceuA ? 0 : 1, roundScoreA: match.teamA.score, roundScoreB: match.teamB.score, winnerId: match.winnerId };
}

function tournamentEstDados(event, matches, standings, filtro) {
  const mapMatches = filtro.mapa ? tournamentFilteredMapMatches(matches, filtro.mapa) : tournamentStatMapMatches(matches);
  const todos = aggregateMatchPlayers(mapMatches).filter((player) => Number(player.rounds || 0) > 0).sort(tournamentPlayerStatSort);
  const daEquipe = filtro.equipe ? todos.filter((player) => player.teamId === filtro.equipe) : todos;
  // Trocar de equipe ou mapa pode baixar o teto: o minimo acompanha para a lista nunca zerar.
  const maximo = daEquipe.reduce((maior, player) => Math.max(maior, Number(player.rounds || 0)), 0);
  const minimo = Math.min(Math.max(filtro.rounds, 0), maximo);
  const players = daEquipe.filter((player) => Number(player.rounds || 0) >= minimo);
  const series = filtro.mapa ? mapMatches.map(tournamentSerieDoMapa) : matches;
  const teams = tournamentTeamStatRows(event, series, standings, todos)
    .filter((row) => (!filtro.equipe || row.id === filtro.equipe) && (!filtro.mapa || row.seriesPlayed));
  return { players, teams, maximo, minimo };
}

function tournamentEstCategorias() {
  const fkFd = (player) => Number(player.firstKills || 0) - Number(player.firstDeaths || 0);
  return [
    { rotulo: "rAAting", valor: (player) => Number(officialRatingValue(player) || 0), texto: (player) => playerRating(player) },
    { rotulo: "ACS", valor: (player) => Number(player.acs || 0), texto: (player) => fmt(player.acs, 0) },
    { rotulo: "K/D", valor: (player) => Number(player.kd || 0), texto: (player) => fmt(player.kd) },
    { rotulo: "KAST", valor: (player) => Number(player.kast || 0), texto: (player) => pct(player.kast) },
    { rotulo: "ADR", valor: (player) => Number(player.adr || 0), texto: (player) => fmt(player.adr, 0) },
    { rotulo: "FK-FD", valor: fkFd, texto: (player) => signed(fkFd(player)) },
    { rotulo: "HS%", valor: (player) => Number(player.hs || 0), texto: (player) => pct(player.hs) },
  ];
}

function tournamentEstCamisa(player, categoria, ativa) {
  const team = teamById(player.teamId);
  const mapas = Number(player.matches || player.maps || 0);
  return plateCard({
    classe: "vp-slide",
    team,
    href: playerHref(player),
    nome: player.nick,
    figura: playerFigure(playerById(player.id) || player, team, "vp-slide-foto"),
    rotulo: `Melhor ${categoria.rotulo}`,
    tag: team?.sourceTag || team?.tag || player.teamTag || "",
    valor: categoria.texto(player),
    apoio: `${mapas} ${mapas === 1 ? "mapa" : "mapas"}`,
    atributos: ativa ? "" : " inert",
  });
}

// O melhor em cada numero, com um cartao por categoria lado a lado num trilho: clicar
// na linha desliza ate o cartao dela, no mesmo tempo das trocas de conteudo do site.
// Empate fica com o melhor rAAting, porque a lista ja vem nessa ordem.
function tournamentEstLideres(players, rotulo = "Líderes do campeonato") {
  const lideres = tournamentEstCategorias().map((categoria) => ({
    categoria,
    jogador: players.reduce((melhor, player) => (categoria.valor(player) > categoria.valor(melhor) ? player : melhor), players[0]),
  }));
  const atual = state.tournamentEstLider || 0;
  return `
    <aside class="vp-resumo" aria-label="${escapeHtml(rotulo)}">
      <div class="vp-est-cartas">
        <div class="vp-est-trilho" style="--atual:${atual}">
          ${lideres.map(({ categoria, jogador }, indice) => tournamentEstCamisa(jogador, categoria, indice === atual)).join("")}
        </div>
      </div>
      <div class="vp-lideres">
        ${lideres.map(({ categoria, jogador }, indice) => `
          <button type="button" class="vp-lider" data-est-lider="${indice}" aria-pressed="${indice === atual}">
            <small>${escapeHtml(categoria.rotulo)}</small>
            <span>${jogador.teamId ? teamLogo(jogador.teamId, "tiny") : ""}<strong title="${escapeHtml(jogador.nick)}">${escapeHtml(jogador.nick)}</strong></span>
            <b>${escapeHtml(categoria.texto(jogador))}</b>
          </button>
        `).join("")}
      </div>
    </aside>
  `;
}

function tournamentEstFiltros(event, matches, filtro, maximo, minimo, rotulo = "Rounds mínimos", chave = "rounds") {
  const ids = [...new Set(matches.flatMap((series) => [series.teamA?.id, series.teamB?.id]).filter(Boolean))];
  const equipes = ids.map((id) => tournamentTeamById(event, id)).filter(Boolean).sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  const mapas = tournamentFilterMapOptions(matches);
  return `
    <div class="vp-est-filtros">
      <select data-est-equipe aria-label="Filtrar por equipe">
        <option value="">Todas as equipes</option>
        ${equipes.map((team) => `<option value="${escapeHtml(team.id)}"${team.id === filtro.equipe ? " selected" : ""}>${escapeHtml(team.name)}</option>`).join("")}
      </select>
      <select data-est-mapa aria-label="Filtrar por mapa">
        <option value="">Todos os mapas</option>
        ${mapas.map((map) => `<option value="${escapeHtml(map.id)}"${map.id === filtro.mapa ? " selected" : ""}>${escapeHtml(map.name)} (${map.count})</option>`).join("")}
      </select>
      <label class="vp-est-rounds" style="--cheio:${maximo ? (minimo / maximo) * 100 : 0}%">
        <span>${escapeHtml(rotulo)}</span>
        <input type="range" min="0" max="${maximo}" step="1" value="${minimo}" data-est-rounds data-est-chave="${escapeHtml(chave)}">
        <b data-est-rounds-valor>${minimo}</b>
      </label>
      ${filtro.equipe || filtro.mapa || filtro.rounds || filtro.usos || filtro.agente ? `<button type="button" class="vp-filtros-limpar" data-est-limpar>Limpar filtros</button>` : ""}
    </div>
  `;
}

// Uma pagina da lista, com o proprio paginador: cada tabela guarda a sua na URL.
function tournamentEstPagina(event, rows, chave, porPagina) {
  const query = routeQuery();
  const total = Math.max(1, Math.ceil(rows.length / porPagina));
  const pagina = Math.min(total, Math.max(1, Number.parseInt(query.get(chave) || "1", 10) || 1));
  query.delete(chave);
  const inicio = (pagina - 1) * porPagina;
  return {
    linhas: rows.slice(inicio, inicio + porPagina),
    paginador: paginacaoDaLista(routePath().slice(2), pagina, total, query, chave),
  };
}

function tournamentEstTabela(event, { table, titulo, descricao = "", antes = "", vazio = "", rows, columns, fallback, chave, porPagina, detalhe = false }) {
  if (!rows.length && !antes) return "";
  if (!rows.length) return `<article class="vp-est-bloco"><h3>${escapeHtml(titulo)}</h3>${antes}<p class="vp-est-vazio">${escapeHtml(vazio)}</p></article>`;
  const ordenadas = tournamentSortedStatRows(table, rows, columns, fallback);
  const { linhas, paginador } = tournamentEstPagina(event, ordenadas, chave, porPagina);
  const visiveis = detalhe ? columns.filter((column) => column.curta) : columns;
  return `
    <article class="vp-est-bloco">
      <h3>${escapeHtml(titulo)}${descricao ? `<span>${escapeHtml(descricao)}</span>` : ""}</h3>
      ${antes}
      ${tabelaComRotulos(`<div class="table-wrap tournament-stats-table-wrap">
        <table class="tournament-stats-table">
          <thead><tr>${visiveis.map((column) => tournamentStatsHeaderCell(table, column)).join("")}${detalhe ? `<th aria-label="Mais números"></th>` : ""}</tr></thead>
          <tbody>
            ${linhas.map((row) => tournamentEstLinha(row, visiveis, detalhe, columns)).join("")}
          </tbody>
        </table>
      </div>`)}
      ${paginador}
    </article>
  `;
}

// O que nao coube na tabela abre numa linha logo abaixo do jogador.
function tournamentEstLinha(row, columns, detalhe, todas) {
  const celulas = columns.map((column) => column.celula(row)).join("");
  if (!detalhe) return `<tr>${celulas}</tr>`;
  const resto = todas.filter((column) => !column.curta && !["kills", "deaths", "assists"].includes(column.key));
  return `
    <tr>${celulas}<td class="vp-est-abre"><button type="button" data-est-detalhe aria-expanded="false" aria-label="${escapeHtml(`Mais números de ${row.nick || row.name || "esta composição"}`)}"><i></i></button></td></tr>
    <tr class="vp-est-detalhe" hidden><td colspan="${columns.length + 1}"><dl>${resto.map((column) => `<div><dt>${escapeHtml(column.label)}</dt><dd>${escapeHtml(column.texto(row))}</dd></div>`).join("")}</dl></td></tr>
  `;
}

function tournamentStatsSection(event, matches, standings) {
  const filtro = tournamentEstFiltro();
  const { players, teams, maximo, minimo } = tournamentEstDados(event, matches, standings, filtro);
  const colunasDeEquipe = tournamentTeamStatColumns().filter((column) => !filtro.mapa || column.key !== "seriesWins");
  const contagem = `${players.length} ${players.length === 1 ? "jogador" : "jogadores"}, ${teams.length} ${teams.length === 1 ? "equipe" : "equipes"}`;
  return `
    <section class="tournament-section tournament-stats-section vp-est">
      <div class="vp-est-lista">
        ${sectionHead("Estatísticas", contagem)}
        ${tournamentEstFiltros(event, matches, filtro, maximo, minimo)}
        ${players.length || teams.length ? "" : `<div class="empty-state">Nenhuma estatística com esses filtros. Tire um filtro para ver mais.</div>`}
        ${tournamentEstTabela(event, { table: "players", titulo: "Jogadores", rows: players, columns: tournamentPlayerStatColumns(), fallback: tournamentPlayerStatSort, chave: "pagina", porPagina: 10, detalhe: true })}
        ${tournamentEstTabela(event, { table: "teams", titulo: "Equipes", rows: teams, columns: colunasDeEquipe, fallback: tournamentTeamStatSort, chave: "pagina-equipes", porPagina: 20 })}
      </div>
      ${players.length ? tournamentEstLideres(players) : ""}
    </section>
  `;
}

function bindEstatisticasDoCampeonato() {
  const pagina = document.querySelector(".vp-est");
  if (!pagina) return;
  const resumo = pagina.querySelector(".vp-resumo");
  resumo?.style.setProperty("--resumo-altura", `${resumo.offsetHeight}px`);
  const aplica = (mudanca, foco) => {
    const query = routeQuery();
    mudanca(query);
    ["pagina", "pagina-equipes", "pagina-comps"].forEach((chave) => query.delete(chave));
    pushFilterState(routePath().slice(2), query, foco);
  };
  [["data-est-equipe", "equipe"], ["data-est-mapa", "mapa"], ["data-est-rounds", "rounds"]].forEach(([atributo, chave]) => {
    pagina.querySelector(`[${atributo}]`)?.addEventListener("change", (event) => {
      const campo = event.target.dataset.estChave || chave;
      aplica((query) => {
        if (event.target.value && event.target.value !== "0") query.set(campo, event.target.value);
        else query.delete(campo);
      }, `[${atributo}]`);
    });
  });
  // A lista so refaz ao soltar: refazer durante o arraste trocaria o controle na mao.
  pagina.querySelector("[data-est-rounds]")?.addEventListener("input", (event) => {
    const { value, max } = event.target;
    event.target.parentElement.style.setProperty("--cheio", `${Number(max) ? (Number(value) / Number(max)) * 100 : 0}%`);
    pagina.querySelector("[data-est-rounds-valor]").textContent = value;
  });
  pagina.addEventListener("click", (event) => {
    if (event.target.closest("[data-est-limpar]")) aplica((query) => ["equipe", "mapa", "rounds", "usos", "agente", "agentes"].forEach((chave) => query.delete(chave)), "[data-est-equipe]");
    if (event.target.closest("[data-ag-limpar]")) {
      const query = routeQuery();
      ["agente", "agentes", "pagina-comps"].forEach((chave) => query.delete(chave));
      pushFilterState(routePath().slice(2), query, "[data-ag-grade]");
    }
    // Escolher agente (na grade ou no nome da tabela) mantem a pagina da lista de
    // agentes: so as composicoes mudam. Ate 5; o sexto e ignorado.
    const agente = event.target.closest("[data-agente]");
    if (agente && !agente.disabled) {
      const query = routeQuery();
      const atuais = tournamentAgFiltro().agentes;
      const id = agente.dataset.agente;
      const novos = atuais.includes(id) ? atuais.filter((item) => item !== id) : [...atuais, id];
      if (novos.length <= TOURNAMENT_AG_MAXIMO) {
        query.delete("agente");
        if (novos.length) query.set("agentes", novos.join(","));
        else query.delete("agentes");
        query.delete("pagina-comps");
        const daGrade = agente.hasAttribute("data-ag-grade");
        pushFilterState(routePath().slice(2), query, `[data-agente="${id}"]${daGrade ? "[data-ag-grade]" : ":not([data-ag-grade])"}`);
      }
    }
    const lider = event.target.closest("[data-est-lider]");
    if (lider) {
      const indice = Number(lider.dataset.estLider);
      state.tournamentEstLider = indice;
      pagina.querySelector(".vp-est-trilho").style.setProperty("--atual", indice);
      pagina.querySelectorAll(".vp-est-trilho > a").forEach((cartao, posicao) => {
        cartao.inert = posicao !== indice;
      });
      pagina.querySelectorAll("[data-est-lider]").forEach((botao) => botao.setAttribute("aria-pressed", String(botao === lider)));
    }
    const botao = event.target.closest("[data-est-detalhe]");
    if (!botao) return;
    const aberto = botao.getAttribute("aria-expanded") !== "true";
    botao.setAttribute("aria-expanded", String(aberto));
    botao.closest("tr").nextElementSibling.hidden = !aberto;
  });
}

// Os numeros de cada mapa do campeonato, com as somas que o cartao usa.
function tournamentMapasDados(event, matches) {
  return tournamentMapAnalyticsRows(event, tournamentStatMapMatches(matches)).map((row) => ({
    ...row,
    mapa: mapById(row.id) || { id: row.id, name: row.name, icon: row.icon },
    soma: somaDoMapa(matches, row.id),
    prorrogacoes: tournamentFilteredMapMatches(matches, row.id).filter((match) => Number(match.rounds || 0) > 24).length,
  }));
}

function tournamentMapasArte(mapa) {
  const art = mapArtAttrs(mapa);
  return art ? `<img src="${escapeHtml(art.src)}" data-fallback="${escapeHtml(art.fallback)}" alt="" loading="lazy" onerror="mapArtError(this)" />` : "";
}

// A faixa e a Camisa do mapa deitada: a emenda fica na proporcao entre ataque e defesa.
function tournamentMapasLinha(row, indice, atual) {
  const ataque = taxaInteira(row.soma.attackWins, row.soma.attackRounds);
  const arte = tournamentMapasArte(row.mapa);
  return `
    <button type="button" class="vp-ml" data-mapa-linha="${indice}" data-mapa-id="${escapeHtml(row.id)}" aria-pressed="${indice === atual}">
      <span class="vp-ml-faixa" style="--ataque:${ataque}">
        <span class="vp-mapa-peca vp-mapa-atk">${arte}</span>
        <span class="vp-mapa-peca vp-mapa-def">${arte}</span>
        <strong>${escapeHtml(row.name)}</strong>
        <b class="vp-ml-a">${ataque}%</b>
        <b class="vp-ml-d">${100 - ataque}%</b>
      </span>
      <span class="vp-ml-num" data-rotulo="Mapas">${row.matches}</span>
      <span class="vp-ml-num" data-rotulo="Média de rounds">${escapeHtml(fmt(row.rounds / row.matches, 1))}</span>
      <span class="vp-ml-num" data-rotulo="Prorrogações">${row.prorrogacoes}</span>
    </button>
  `;
}

function tournamentMapsSection(event, matches) {
  const linhas = tournamentMapasDados(event, matches);
  const totalMapas = linhas.reduce((sum, row) => sum + row.matches, 0);
  const totalRounds = linhas.reduce((sum, row) => sum + row.rounds, 0);
  const cabeca = sectionHead("Mapas", `${totalMapas} ${totalMapas === 1 ? "mapa" : "mapas"}, ${totalRounds} rounds`);
  if (!linhas.length) {
    return `<section class="tournament-section">${cabeca}<div class="empty-state">Nenhum mapa registrado para este campeonato.</div></section>`;
  }
  const atual = Math.max(0, linhas.findIndex((row) => row.id === state.tournamentMapaLinha));
  const fora = tournamentMapPoolRows(event.mapPool || [], matches).filter((map) => !map.played);
  return `
    <section class="tournament-section vp-est vp-mapas">
      <div class="vp-est-lista">
        ${cabeca}
        <div class="vp-ml-corpo">
          <div class="vp-ml-cab" aria-hidden="true"><span><span>Ataque</span><span>Defesa</span></span><span>Mapas</span><span>Média de rounds</span><span>Prorrogações</span></div>
          <div class="vp-ml-lista">${linhas.map((row, indice) => tournamentMapasLinha(row, indice, atual)).join("")}</div>
          ${fora.length ? `<p class="vp-ml-fora">Não jogados: ${escapeHtml(fora.map((map) => map.name || map.poolName).join(", "))}</p>` : ""}
        </div>
      </div>
      <aside class="vp-resumo" aria-label="Dados do mapa">
        <div class="vp-est-cartas">
          <div class="vp-est-trilho" style="--atual:${atual}">
            ${linhas.map((row, indice) => mapaCamisa(row.mapa, row.soma, null, "Neste campeonato", indice === atual ? "" : " inert")).join("")}
          </div>
        </div>
      </aside>
      ${tournamentMapAgentPickrateTable(linhas, tournamentMapAgentColumns(linhas))}
    </section>
  `;
}

// Clicar numa faixa desliza o trilho ate o cartao do mapa, como os lideres de Estatisticas.
function bindMapasDoCampeonato() {
  const pagina = document.querySelector(".vp-mapas");
  if (!pagina) return;
  pagina.addEventListener("click", (event) => {
    const linha = event.target.closest("[data-mapa-linha]");
    if (!linha) return;
    const indice = Number(linha.dataset.mapaLinha);
    state.tournamentMapaLinha = linha.dataset.mapaId;
    pagina.querySelector(".vp-est-trilho").style.setProperty("--atual", indice);
    pagina.querySelectorAll(".vp-est-trilho > *").forEach((cartao, posicao) => {
      cartao.inert = posicao !== indice;
    });
    pagina.querySelectorAll("[data-mapa-linha]").forEach((botao) => botao.setAttribute("aria-pressed", String(botao === linha)));
    // Numa coluna so o cartao fica acima da lista: sem isso a troca aconteceria fora da tela.
    if (window.matchMedia("(max-width: 1180px)").matches) pagina.querySelector(".vp-resumo").scrollIntoView({ block: "nearest", behavior: "smooth" });
  });
}

function tournamentMapAnalyticsRows(event, mapMatches) {
  const rows = new Map();
  const ensure = (match) => {
    const meta = mapById(match.mapId) || mapByName(match.mapName) || {};
    const id = meta.id || match.mapId || normalizeNameKey(match.mapName || "mapa");
    if (!rows.has(id)) {
      rows.set(id, {
        id,
        name: meta.name || match.mapName || displayEntityName(id),
        icon: meta.icon || match.mapIcon || "",
        matches: 0,
        rounds: 0,
        sideRounds: 0,
        attackWins: 0,
        defenseWins: 0,
        totalPicks: 0,
        pickOpportunities: 0,
        agents: new Map(),
        poolIndex: (event.mapPool || event.maps || []).findIndex((name) => normalizeNameKey(name) === normalizeNameKey(meta.name || match.mapName || id)),
      });
    }
    return rows.get(id);
  };

  for (const match of mapMatches || []) {
    const row = ensure(match);
    row.matches += 1;
    row.pickOpportunities += 2;
    row.rounds += Number(match.rounds || match.roundResults?.length || 0);
    if (match.sideSummary && !(match.roundResults || []).length) {
      // roundResults podados do database.json; usa o resumo pré-computado.
      row.attackWins += Number(match.sideSummary.attackWins || 0);
      row.defenseWins += Number(match.sideSummary.defenseWins || 0);
      row.sideRounds += Number(match.sideSummary.attackWins || 0) + Number(match.sideSummary.defenseWins || 0);
    } else {
      for (const round of match.roundResults || []) {
        if (round.winningTeamRole === "Attacker") {
          row.attackWins += 1;
          row.sideRounds += 1;
        } else if (round.winningTeamRole === "Defender") {
          row.defenseWins += 1;
          row.sideRounds += 1;
        }
      }
    }
    for (const player of match.players || []) {
      const key = agentStatsKey(player);
      const agent = row.agents.get(key) || {
        slug: player.agentSlug || key,
        name: displayAgentName(player.agent, player.agentSlug || key),
        role: player.agentClass || "",
        icon: player.agentIcon || "",
        picks: 0,
      };
      agent.picks += 1;
      row.totalPicks += 1;
      row.agents.set(key, agent);
    }
  }

  return [...rows.values()]
    .map((row) => ({
      ...row,
      attackRate: row.sideRounds ? pctValue(row.attackWins, row.sideRounds) : 0,
      defenseRate: row.sideRounds ? pctValue(row.defenseWins, row.sideRounds) : 0,
      agentRates: new Map([...row.agents.entries()].map(([key, agent]) => [key, { ...agent, rate: pctValue(agent.picks, row.pickOpportunities) }])),
    }))
    .sort((a, b) => b.matches - a.matches || (a.poolIndex < 0 ? 999 : a.poolIndex) - (b.poolIndex < 0 ? 999 : b.poolIndex) || a.name.localeCompare(b.name, "pt-BR"));
}

function tournamentMapAgentColumns(rows) {
  const agents = new Map();
  for (const row of rows || []) {
    for (const [key, agent] of row.agents.entries()) {
      const current = agents.get(key) || { ...agent, picks: 0 };
      current.picks += agent.picks;
      agents.set(key, current);
    }
  }
  return [...agents.entries()]
    .map(([key, agent]) => ({ key, ...agent }))
    .sort((a, b) => b.picks - a.picks || roleSortOrder(a.role) - roleSortOrder(b.role) || String(a.name || a.key).localeCompare(String(b.name || b.key), "pt-BR"));
}

// Cinco degraus, do escuro ao claro: a cor mostra o tamanho e o numero, o valor exato.
const TOURNAMENT_MAPA_DEGRAUS = [[1, 19], [20, 39], [40, 59], [60, 79], [80, 100]];

function tournamentMapAgentPickrateTable(rows, agentColumns) {
  const totalRow = tournamentMapTotalAgentRow(rows, agentColumns);
  return `
    <article class="vp-est-bloco vp-ma-bloco">
      <h3>Agentes por mapa</h3>
      <div class="vp-ma-chave">
        <small>Pouco usado</small>
        ${TOURNAMENT_MAPA_DEGRAUS.map(([minimo, maximo], indice) => `<span class="vp-ma-n${indice + 1}">${minimo}-${maximo}%</span>`).join("")}
        <small>Muito usado</small>
      </div>
      <table class="vp-ma">
        <thead>
          <tr>
            <th scope="col">Mapa</th>
            <th scope="col" title="Mapas jogados">#</th>
            ${agentColumns.map((agent) => `<th scope="col" title="${escapeHtml(`${agent.name || agent.key}${agent.role ? ` - ${roleDisplayInfo(agent.role).label}` : ""}`)}">${tournamentAgentLogo(agent)}</th>`).join("")}
          </tr>
        </thead>
        <tbody>
          ${totalRow ? tournamentMapAgentPickrateRow(totalRow, agentColumns, true) : ""}
          ${rows.map((row) => tournamentMapAgentPickrateRow(row, agentColumns)).join("")}
        </tbody>
      </table>
    </article>
  `;
}

function tournamentMapTotalAgentRow(rows, agentColumns) {
  if (!rows.length) return null;
  const total = {
    id: "all",
    name: "Todos",
    matches: rows.reduce((sum, row) => sum + row.matches, 0),
    sideRounds: rows.reduce((sum, row) => sum + row.sideRounds, 0),
    attackWins: rows.reduce((sum, row) => sum + row.attackWins, 0),
    defenseWins: rows.reduce((sum, row) => sum + row.defenseWins, 0),
    totalPicks: rows.reduce((sum, row) => sum + row.totalPicks, 0),
    pickOpportunities: rows.reduce((sum, row) => sum + row.pickOpportunities, 0),
    agentRates: new Map(),
  };
  total.attackRate = total.sideRounds ? pctValue(total.attackWins, total.sideRounds) : 0;
  total.defenseRate = total.sideRounds ? pctValue(total.defenseWins, total.sideRounds) : 0;
  for (const agent of agentColumns || []) {
    const picks = rows.reduce((sum, row) => sum + Number(row.agents.get(agent.key)?.picks || 0), 0);
    total.agentRates.set(agent.key, { ...agent, picks, rate: pctValue(picks, total.pickOpportunities) });
  }
  return total;
}

function tournamentMapAgentPickrateRow(row, agentColumns, summary = false) {
  const nome = summary
    ? `<span class="vp-ma-nome"><span>${escapeHtml(row.name)}</span></span>`
    : `<a class="vp-ma-nome" href="#/maps/${escapeHtml(row.id)}">${tournamentMapasArte(row.mapa)}<span>${escapeHtml(row.name)}</span></a>`;
  return `
    <tr class="${summary ? "vp-ma-todos" : ""}">
      <td class="vp-ma-mapa">${nome}</td>
      <td class="vp-ma-n">${escapeHtml(String(row.matches || 0))}</td>
      ${agentColumns.map((agent) => tournamentMapAgentPickrateCell(agent, row.agentRates.get(agent.key)?.rate || 0)).join("")}
    </tr>
  `;
}

// Quem foi usado aparece com pelo menos 1%, para nao se confundir com quem ficou de
// fora. No bloco do celular cada numero leva o icone, porque o cabecalho some, e os
// mais usados vem primeiro.
function tournamentMapAgentPickrateCell(agent, rate) {
  const valor = rate > 0 ? Math.max(1, Math.round(clamp(rate, 0, 100))) : 0;
  if (!valor) return `<td class="vp-ma-zero">-</td>`;
  const degrau = TOURNAMENT_MAPA_DEGRAUS.findIndex(([, maximo]) => valor <= maximo) + 1;
  return `<td class="vp-ma-taxa vp-ma-n${degrau}" style="--ordem:${100 - valor}" title="${escapeHtml(agent.name || agent.key)}">${tournamentAgentLogo(agent)}<span>${valor}%</span></td>`;
}

function tournamentStatMapMatches(matches) {
  return (matches || [])
    .flatMap((series) => series.maps || [])
    .filter((match) => Array.isArray(match.players) && match.players.length);
}

function tournamentSelectedMapFilter(eventId, scope) {
  return state.tournamentMapFilters?.[`${eventId}:${scope}`] || "all";
}

function tournamentFilteredMapMatches(matches, mapFilter) {
  const maps = tournamentStatMapMatches(matches);
  if (!mapFilter || mapFilter === "all") return maps;
  return maps.filter((match) => match.mapId === mapFilter || normalizeNameKey(match.mapName) === normalizeNameKey(mapFilter));
}

function tournamentMapFilterControl(eventId, matches, scope) {
  const selected = tournamentSelectedMapFilter(eventId, scope);
  const maps = tournamentFilterMapOptions(matches);
  if (maps.length <= 1) return "";
  return `
    <label class="tournament-stat-filter">
      <span>Mapa</span>
      <select class="filter-control" data-tournament-map-filter="${escapeHtml(scope)}">
        <option value="all"${selected === "all" ? " selected" : ""}>Todos os mapas</option>
        ${maps.map((map) => `<option value="${escapeHtml(map.id)}"${selected === map.id ? " selected" : ""}>${escapeHtml(map.name)} (${map.count})</option>`).join("")}
      </select>
    </label>
  `;
}

function tournamentFilterMapOptions(matches) {
  const rows = new Map();
  for (const match of tournamentStatMapMatches(matches)) {
    const meta = mapById(match.mapId) || mapByName(match.mapName) || { id: match.mapId || normalizeNameKey(match.mapName), name: match.mapName || "Mapa" };
    const id = meta.id || normalizeNameKey(meta.name);
    if (!rows.has(id)) rows.set(id, { id, name: meta.name || match.mapName || id, count: 0 });
    rows.get(id).count += 1;
  }
  return [...rows.values()].sort((a, b) => a.name.localeCompare(b.name, "pt-BR", { numeric: true }));
}

function tournamentPlayerStatSort(a, b) {
  return Number(officialRatingValue(b) || 0) - Number(officialRatingValue(a) || 0) || Number(b.rounds || 0) - Number(a.rounds || 0) || Number(b.kills || 0) - Number(a.kills || 0) || String(a.nick || "").localeCompare(String(b.nick || ""), "pt-BR");
}

function tournamentTeamStatRows(event, matches, standings, players = []) {
  const rows = new Map();
  const ensure = (teamId) => {
    if (!teamId) return null;
    if (!rows.has(teamId)) {
      rows.set(teamId, {
        id: teamId,
        team: tournamentTeamById(event, teamId),
        placement: "",
        standingIndex: Number.POSITIVE_INFINITY,
        seriesPlayed: 0,
        seriesWins: 0,
        seriesLosses: 0,
        mapWins: 0,
        mapLosses: 0,
        roundsFor: 0,
        roundsAgainst: 0,
        roundDiff: 0,
        playerRounds: 0,
        ratingTotal: 0,
        acsTotal: 0,
        adrTotal: 0,
        kprTotal: 0,
        kastTotal: 0,
      });
    }
    return rows.get(teamId);
  };

  (event.teams || []).forEach(ensure);
  standings.forEach((standing, index) => {
    const teamId = standing.id || standing.teamId;
    const row = ensure(teamId);
    if (!row) return;
    const placement = teamEventPlacementResult(teamId, event);
    row.placement = row.placement || (placement.placementStatus === "unknown" ? "" : placement.placementLabel) || standing.range || "";
    row.standingIndex = Math.min(row.standingIndex, index);
  });

  for (const series of matches || []) {
    [series.teamA?.id, series.teamB?.id].filter(Boolean).forEach((teamId) => tournamentAddSeriesTeamStats(ensure(teamId), series, teamId));
  }

  for (const player of players) {
    const row = ensure(player.teamId);
    if (!row) continue;
    const rounds = Number(player.rounds || 0);
    row.playerRounds += rounds;
    row.ratingTotal += Number(player.rating || 0) * rounds;
    row.acsTotal += Number(player.acs || 0) * rounds;
    row.adrTotal += Number(player.adr || 0) * rounds;
    row.kprTotal += Number(player.kpr || 0) * rounds;
    row.kastTotal += Number(player.kast || 0) * rounds;
  }

  return [...rows.values()]
    .map((row) => {
      const placement = row.placement || teamEventPlacementResult(row.id, event).placementLabel;
      return {
        ...row,
        placement: placement === "Colocação não informada" ? "" : placement,
        mapsPlayed: row.mapWins + row.mapLosses,
        rating: row.playerRounds ? row.ratingTotal / row.playerRounds : 0,
        acs: row.playerRounds ? row.acsTotal / row.playerRounds : 0,
        adr: row.playerRounds ? row.adrTotal / row.playerRounds : 0,
        kpr: row.playerRounds ? row.kprTotal / row.playerRounds : 0,
        kast: row.playerRounds ? row.kastTotal / row.playerRounds : 0,
      };
    })
    .sort(tournamentTeamStatSort);
}

function tournamentAddSeriesTeamStats(row, series, teamId) {
  if (!row) return;
  const score = seriesScoreForTeam(series, teamId);
  const won = series.winnerId === teamId || score.mapsFor > score.mapsAgainst;
  row.seriesPlayed += 1;
  row.seriesWins += won ? 1 : 0;
  row.seriesLosses += won ? 0 : 1;
  row.mapWins += score.mapsFor;
  row.mapLosses += score.mapsAgainst;
  row.roundsFor += score.roundsFor;
  row.roundsAgainst += score.roundsAgainst;
  row.roundDiff += score.roundsFor - score.roundsAgainst;
}

function tournamentTeamStatSort(a, b) {
  return b.seriesWins - a.seriesWins || b.mapWins - a.mapWins || b.roundDiff - a.roundDiff || a.seriesLosses - b.seriesLosses || a.standingIndex - b.standingIndex || String(a.team?.name || a.id).localeCompare(String(b.team?.name || b.id), "pt-BR");
}

function tournamentTeamRatingLabel(row) {
  return row.playerRounds ? fmt(row.rating) : "-";
}

function tournamentPlayerStatColumns() {
  const numero = (texto) => (row) => `<td class="numeric">${escapeHtml(texto(row))}</td>`;
  const fkFd = (player) => Number(player.firstKills || 0) - Number(player.firstDeaths || 0);
  const coluna = (key, label, value, texto, opcoes = {}) => ({ key, label, value, texto, celula: numero(texto), ...opcoes });
  return [
    {
      key: "player", label: "Jogador", value: (player) => player.nick || player.handle || "", type: "text", direction: "asc", curta: true,
      celula: (player) => `<td><a class="tournament-stats-player-cell" href="${playerHref(player)}"><span class="tournament-player-logo-pair">${playerLogo(player.id, "tournament-stat-avatar")}${player.teamId ? teamLogo(player.teamId, "tournament-player-team-logo") : ""}</span><span><strong>${escapeHtml(player.nick || player.handle || "Jogador")}</strong><small>${escapeHtml(tournamentPlayerTeamLabel(player))}</small></span></a></td>`,
    },
    { key: "agents", label: "Agentes", value: (player) => player.agentList?.[0]?.name || player.agent || "", type: "text", direction: "asc", curta: true, celula: (player) => `<td>${agentStack(player)}</td>` },
    coluna("rounds", "Rnd", (player) => Number(player.rounds || 0), (player) => String(player.rounds || 0), { curta: true }),
    coluna("maps", "Mapas", (player) => Number(player.matches || player.maps || 0), (player) => String(player.matches || player.maps || 0), { curta: true }),
    coluna("rating", "rAAting", (player) => Number(officialRatingValue(player) || 0), (player) => playerRating(player), { curta: true }),
    coluna("acs", "ACS", (player) => Number(player.acs || 0), (player) => fmt(player.acs, 0), { curta: true }),
    coluna("kd", "K:D", (player) => Number(player.kd || 0), (player) => fmt(player.kd), { curta: true }),
    coluna("kast", "KAST", (player) => Number(player.kast || 0), (player) => pct(player.kast), { curta: true }),
    coluna("adr", "ADR", (player) => Number(player.adr || 0), (player) => fmt(player.adr, 0), { curta: true }),
    coluna("swing", "Swing/R", (player) => Number(playerSwingPerRound(player) || 0), (player) => formatMaybeSwing(player), { curta: true, celula: (player) => `<td class="numeric ${escapeHtml(directionalTone(playerSwingPerRound(player)))}">${escapeHtml(formatMaybeSwing(player))}</td>` }),
    coluna("kpr", "KPR", (player) => Number(player.kpr || 0), (player) => fmt(player.kpr)),
    coluna("apr", "APR", (player) => Number(player.apr || 0), (player) => fmt(player.apr)),
    coluna("hs", "HS%", (player) => Number(player.hs || 0), (player) => pct(player.hs), { curta: true }),
    coluna("kills", "K", (player) => Number(player.kills || 0), (player) => String(player.kills || 0)),
    coluna("deaths", "D", (player) => Number(player.deaths || 0), (player) => String(player.deaths || 0)),
    coluna("assists", "A", (player) => Number(player.assists || 0), (player) => String(player.assists || 0)),
    coluna("kda", "K/D/A", (player) => Number(player.kills || 0), (player) => `${player.kills || 0}/${player.deaths || 0}/${player.assists || 0}`, { curta: true }),
    coluna("fkFdDiff", "FK-FD", fkFd, (player) => signed(fkFd(player)), { curta: true, celula: (player) => `<td class="numeric ${escapeHtml(signedTone(fkFd(player)))}">${escapeHtml(signed(fkFd(player)))}</td>` }),
    coluna("firstKills", "FK", (player) => Number(player.firstKills || 0), (player) => String(player.firstKills || 0)),
    coluna("fkpr", "FKPR", (player) => (player.rounds ? player.firstKills / player.rounds : 0), (player) => fmt(player.rounds ? player.firstKills / player.rounds : 0)),
    coluna("fdpr", "FDPR", (player) => (player.rounds ? player.firstDeaths / player.rounds : 0), (player) => fmt(player.rounds ? player.firstDeaths / player.rounds : 0)),
  ];
}

function tournamentTeamStatColumns() {
  const numero = (texto) => (row) => `<td class="numeric">${escapeHtml(texto(row))}</td>`;
  return [
    { key: "lugar", label: "Lugar", value: (row) => Math.min(row.standingIndex, 9999), direction: "asc", celula: (row) => `<td class="vp-est-lugar">${escapeHtml(String(row.placement || "-").replace(/ lugar$/, ""))}</td>` },
    {
      key: "team", label: "Equipe", value: (row) => row.team?.name || displayTeamName(row.id), type: "text", direction: "asc",
      celula: (row) => {
        const tag = row.team?.missing ? "span" : "a";
        const href = row.team?.missing ? "" : ` href="#/teams/${escapeHtml(row.id)}"`;
        return `<td><${tag} class="tournament-stats-team-cell"${href}>${teamLogo(row.id, "tournament-stat-logo")}<span><strong>${escapeHtml(row.team?.name || displayTeamName(row.id))}</strong></span></${tag}></td>`;
      },
    },
    { key: "seriesWins", label: "Séries", value: (row) => Number(row.seriesWins || 0) - Number(row.seriesLosses || 0) / 100, celula: numero((row) => `${row.seriesWins}-${row.seriesLosses}`) },
    { key: "mapWins", label: "Mapas", value: (row) => Number(row.mapWins || 0) - Number(row.mapLosses || 0) / 100, celula: numero((row) => `${row.mapWins}-${row.mapLosses}`) },
    { key: "roundsFor", label: "Rounds", value: (row) => Number(row.roundsFor || 0) - Number(row.roundsAgainst || 0) / 1000, celula: numero((row) => `${row.roundsFor}-${row.roundsAgainst}`) },
    { key: "roundDiff", label: "Saldo", value: (row) => Number(row.roundDiff || 0), celula: numero((row) => signed(row.roundDiff)) },
    { key: "winrate", label: "Win%", value: (row) => (row.seriesPlayed ? pctValue(row.seriesWins, row.seriesPlayed) : 0), celula: numero((row) => pct(row.seriesPlayed ? pctValue(row.seriesWins, row.seriesPlayed) : 0)) },
    { key: "rating", label: "rAAting", value: (row) => Number(row.rating || 0), celula: numero(tournamentTeamRatingLabel) },
    { key: "acs", label: "ACS", value: (row) => Number(row.acs || 0), celula: numero((row) => (row.playerRounds ? fmt(row.acs, 0) : "-")) },
    { key: "adr", label: "ADR", value: (row) => Number(row.adr || 0), celula: numero((row) => (row.playerRounds ? fmt(row.adr, 0) : "-")) },
  ];
}

function tournamentStatsSortState(table) {
  const fallback = table === "teams" ? { key: "lugar", direction: "asc" } : table === "agents" || table === "compositions" ? { key: "picks", direction: "desc" } : { key: "rating", direction: "desc" };
  return state.tournamentStatsSort?.[table] || fallback;
}

function tournamentSortedStatRows(table, rows, columns, fallbackSort) {
  const current = tournamentStatsSortState(table);
  const column = columns.find((item) => item.key === current.key) || columns[0];
  const direction = current.direction === "asc" ? 1 : -1;
  return rows.slice().sort((a, b) => {
    const valueA = column.value(a);
    const valueB = column.value(b);
    let comparison = 0;
    if (column.type === "text") comparison = String(valueA || "").localeCompare(String(valueB || ""), "pt-BR", { numeric: true });
    else comparison = Number(valueA || 0) - Number(valueB || 0);
    if (comparison !== 0) return comparison * direction;
    return fallbackSort(a, b);
  });
}

function tournamentStatsHeaderCell(table, column) {
  const current = tournamentStatsSortState(table);
  const active = current.key === column.key;
  const direction = active ? current.direction : "";
  const indicator = direction === "asc" ? "▲" : direction === "desc" ? "▼" : "";
  const className = column.type === "text" ? "" : "numeric";
  return `
    <th class="${escapeHtml(className)}" aria-sort="${direction === "asc" ? "ascending" : direction === "desc" ? "descending" : "none"}">
      <button type="button" class="tournament-stat-sort ${active ? "active" : ""}" data-tournament-stat-sort="${escapeHtml(`${table}:${column.key}`)}">
        <span>${escapeHtml(column.label)}</span><i aria-hidden="true">${escapeHtml(indicator)}</i>
      </button>
    </th>
  `;
}

function tournamentStatsTableExpanded(eventId, table) {
  return Boolean(state.tournamentStatsExpanded?.[`${eventId}:${table}`]);
}

function tournamentStatsExpandButton(table, totalRows, expanded) {
  if (totalRows <= 10) return "";
  return `<button type="button" class="tournament-stat-expand" data-tournament-stat-expand="${escapeHtml(table)}">${expanded ? "Mostrar menos" : `Exibir tudo (${totalRows})`}</button>`;
}

function bindTournamentStatsControls(eventId) {
  const root = document.querySelector(".tournament-stats-section");
  if (!root) return;
  root.addEventListener("click", (event) => {
    const sortButton = event.target.closest("[data-tournament-stat-sort]");
    if (sortButton) {
      const [table, key] = String(sortButton.dataset.tournamentStatSort || "").split(":");
      const columns = table === "teams" ? tournamentTeamStatColumns() : table === "agents" ? tournamentAgentStatColumns() : table === "compositions" ? tournamentCompositionStatColumns() : tournamentPlayerStatColumns();
      const column = columns.find((item) => item.key === key);
      if (!column) return;
      const current = tournamentStatsSortState(table);
      const defaultDirection = column.direction || "desc";
      const direction = current.key === key ? (current.direction === "desc" ? "asc" : "desc") : defaultDirection;
      state.tournamentStatsSort = { ...state.tournamentStatsSort, [table]: { key, direction } };
      renderTournamentDetail(eventId);
      return;
    }

    const expandButton = event.target.closest("[data-tournament-stat-expand]");
    if (expandButton) {
      const table = expandButton.dataset.tournamentStatExpand;
      const key = `${eventId}:${table}`;
      state.tournamentStatsExpanded = { ...state.tournamentStatsExpanded, [key]: !state.tournamentStatsExpanded?.[key] };
      renderTournamentDetail(eventId);
      return;
    }

  });
}

function tournamentStatValueCell(display) {
  return `<td class="numeric tournament-stat-value">${escapeHtml(display)}</td>`;
}

function tournamentPlayerTeamLabel(player) {
  const team = teamById(player.teamId);
  return team?.sourceTag || team?.tag || player.teamTag || player.teamId || "Sem equipe";
}

