// Ate 5 agentes em `agentes` (jett,omen,sova). O `agente` sozinho dos links antigos vale como um.
const TOURNAMENT_AG_MAXIMO = 5;

function tournamentAgFiltro() {
  const query = routeQuery();
  const agentes = [...new Set((query.get("agentes") || query.get("agente") || "").split(",").map((id) => id.trim()).filter(Boolean))].slice(0, TOURNAMENT_AG_MAXIMO);
  return { equipe: query.get("equipe") || "", mapa: query.get("mapa") || "", agentes, agente: agentes.join(","), usos: Number.parseInt(query.get("usos") || "0", 10) || 0 };
}

// Junta o que a tabela do site pede as colunas da aba, que tambem servem ao perfil do jogador.
function tournamentAgColunas(colunas, textos, curtas, celulas, extras) {
  const texto = (column) => textos[column.key] || ((row) => String(column.value(row) ?? ""));
  return [
    ...colunas.map((column) => ({
      ...column,
      texto: texto(column),
      curta: curtas.includes(column.key),
      celula: celulas[column.key] || ((row) => `<td class="numeric">${escapeHtml(texto(column)(row))}</td>`),
    })),
    ...extras,
  ];
}

function tournamentAgenteColunas(ativos = []) {
  const textos = {
    pickRate: (row) => pct(row.pickRate),
    winRate: tournamentAgentNonMirroredWinRate,
    rating: (row) => fmt(row.rating),
    acs: (row) => fmt(row.acs, 0),
    kd: (row) => fmt(row.kd),
    kast: (row) => pct(row.kast),
    adr: (row) => fmt(row.adr, 0),
    kpr: (row) => fmt(row.kpr),
    apr: (row) => fmt(row.apr),
    fkpr: (row) => fmt(row.rounds ? row.firstKills / row.rounds : 0),
    fdpr: (row) => fmt(row.rounds ? row.firstDeaths / row.rounds : 0),
    hs: (row) => pct(row.hs),
  };
  const celulas = {
    agent: (row) => `<td><button type="button" class="vp-ag-nome" data-agente="${escapeHtml(row.id)}" aria-pressed="${ativos.includes(row.id)}" title="Ver as composições com ${escapeHtml(row.name)}">${tournamentAgentLogo(row)}<span><strong>${escapeHtml(row.name)}</strong><small>${escapeHtml(roleDisplayInfo(row.role).label)}</small></span></button></td>`,
  };
  const extras = [
    { key: "semEspelho", label: "Mapas sem espelho", texto: (row) => `${row.nonMirroredWins}-${row.nonMirroredLosses}` },
    { key: "kda", label: "K/D/A", texto: (row) => `${row.kills}/${row.deaths}/${row.assists}` },
  ];
  const rotulos = { winRate: "Win%", rating: "rAAting" };
  const colunas = tournamentAgentStatColumns().map((column) => ({ ...column, label: rotulos[column.key] || column.label }));
  return tournamentAgColunas(colunas, textos, ["agent", "picks", "pickRate", "winRate", "rating", "acs", "kd", "kast", "adr"], celulas, extras);
}

function tournamentComposicaoColunas() {
  const textos = {
    pickRate: (row) => pct(row.pickRate),
    winRate: (row) => pct(row.winRate),
    maps: (row) => `${row.mapWins}-${row.mapLosses}`,
    roundDiff: (row) => signed(row.roundDiff),
    rating: (row) => fmt(row.rating),
    acs: (row) => fmt(row.acs, 0),
    kd: (row) => fmt(row.kd),
    kast: (row) => pct(row.kast),
    adr: (row) => fmt(row.adr, 0),
    kpr: (row) => fmt(row.kpr),
    apr: (row) => fmt(row.apr),
    fkpr: (row) => fmt(row.playerRounds ? row.firstKills / row.playerRounds : 0),
    fdpr: (row) => fmt(row.playerRounds ? row.firstDeaths / row.playerRounds : 0),
    hs: (row) => pct(row.hs),
  };
  const celulas = {
    composition: (row) => `<td><span class="tournament-composition-cell">${tournamentCompositionAgentStack(row.agents)}<small>${escapeHtml(tournamentCompositionLabel(row))}</small></span></td>`,
  };
  const rotulos = { pickRate: "Uso%", rating: "rAAting" };
  const colunas = tournamentCompositionStatColumns().map((column) => ({ ...column, label: rotulos[column.key] || column.label }));
  return tournamentAgColunas(colunas, textos, ["composition", "picks", "pickRate", "winRate", "maps", "roundDiff", "rating", "acs"], celulas, []);
}

// A formacao conta quantos agentes de cada funcao a composicao levou. O que passa dos
// cinco primeiros vira uma linha so, para a soma continuar fechando 100%.
const TOURNAMENT_FORMACAO_PAPEIS = ["duelista", "iniciador", "controlador", "sentinela"];

function tournamentFormacoes(composicoes) {
  const usos = new Map();
  composicoes.forEach((row) => {
    const chave = TOURNAMENT_FORMACAO_PAPEIS.map((papel) => row.agents.filter((agent) => normalizeRoleKey(agent.role) === papel).length).join("-");
    usos.set(chave, (usos.get(chave) || 0) + row.picks);
  });
  const total = [...usos.values()].reduce((soma, valor) => soma + valor, 0);
  const linhas = [...usos.entries()].sort((a, b) => b[1] - a[1]).map(([chave, valor]) => ({ chave, valor, parte: total ? valor / total : 0 }));
  const resto = linhas.slice(5);
  return {
    linhas: linhas.slice(0, 5),
    outras: resto.reduce((soma, linha) => soma + linha.parte, 0),
    variantes: resto.length,
  };
}

function tournamentFormacaoLinha({ chave, parte }) {
  const contagem = chave.split("-").map(Number);
  const icones = TOURNAMENT_FORMACAO_PAPEIS.flatMap((papel, indice) => Array(contagem[indice]).fill(papel));
  const titulo = TOURNAMENT_FORMACAO_PAPEIS.map((papel, indice) => (contagem[indice] ? `${contagem[indice]} ${ROLE_ICONS[papel].label.toLowerCase()}` : "")).filter(Boolean).join(", ");
  return `
    <div class="vp-fo" style="--parte:${parte.toFixed(4)}" title="${escapeHtml(titulo)}">
      <span>${icones.map((papel) => `<img src="${escapeHtml(assetPath(ROLE_ICONS[papel].icon))}" alt="${escapeHtml(ROLE_ICONS[papel].label)}" loading="lazy" />`).join("")}</span>
      <b>${Math.round(parte * 100)}%</b>
    </div>
  `;
}

function tournamentAgenteCamisa(agente, escolhido) {
  const papel = roleDisplayInfo(agente.role).label;
  const valor = pct(agente.pickRate);
  const arte = assetPath(agente.icon || "");
  return plateCard({
    classe: `vp-slide vp-camisa-equipe${valor.length > 4 ? " vp-valor-longo" : ""}`,
    team: { colors: AGENT_CORES[agente.id] || [] },
    href: escapeHtml(window.location.hash),
    nome: agente.name,
    figura: arte ? `<span class="vp-camisa-logo"><img src="${escapeHtml(arte)}" alt="" onerror="this.parentElement.remove()" /></span>` : "",
    rotulo: escolhido ? "Selecionado" : "Mais usado",
    tag: papel,
    valor,
    apoio: `${agente.picks} ${agente.picks === 1 ? "pick" : "picks"}`,
  });
}

function tournamentAgenteResumo(agente, escolhido, composicoes) {
  const { linhas, outras, variantes } = tournamentFormacoes(composicoes);
  const dados = [
    ["Vitórias", agente.nonMirroredPicks ? `<b>${escapeHtml(pct(agente.winRateNM))}</b> em ${agente.nonMirroredPicks} ${agente.nonMirroredPicks === 1 ? "mapa" : "mapas"}` : "Sempre espelhado"],
    ["rAAting", `<b>${escapeHtml(fmt(agente.rating))}</b>`],
    ["ACS", `<b>${escapeHtml(fmt(agente.acs, 0))}</b>`],
    ["K:D", `<b>${escapeHtml(fmt(agente.kd))}</b>`],
    ["Quem usou", `<b>${agente.uniquePlayers}</b> ${agente.uniquePlayers === 1 ? "jogador" : "jogadores"}, <b>${agente.uniqueTeams}</b> ${agente.uniqueTeams === 1 ? "equipe" : "equipes"}`],
  ];
  return `
    <aside class="vp-resumo" aria-label="Agente e formações">
      <div class="vp-mapa-resumo">
        ${tournamentAgenteCamisa(agente, escolhido)}
        <dl class="vp-mapa-dados">${dados.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${valor}</dd></div>`).join("")}</dl>
      </div>
      <div class="vp-resumo-bloco">
        <h3>Formações</h3>
        <div class="vp-fo-lista">
          ${linhas.map(tournamentFormacaoLinha).join("")}
          ${variantes ? `<div class="vp-fo vp-fo-outras" style="--parte:${outras.toFixed(4)}"><span>Outras ${variantes}</span><b>${Math.round(outras * 100)}%</b></div>` : ""}
        </div>
      </div>
    </aside>
  `;
}

function tournamentAgentsSection(event, matches) {
  const filtro = tournamentAgFiltro();
  const mapas = filtro.mapa ? tournamentFilteredMapMatches(matches, filtro.mapa) : tournamentStatMapMatches(matches);
  const agentes = tournamentAgentRows(mapas, filtro.equipe);
  const todas = tournamentCompositionRows(mapas, filtro.equipe);
  const escolhidos = filtro.agentes.map((id) => agentes.find((row) => row.id === id)).filter(Boolean);
  const ids = escolhidos.map((row) => row.id);
  const comAgente = todas.filter((row) => tournamentComposicaoTem(row, ids));
  // Trocar de equipe, mapa ou agente pode baixar o teto: o minimo acompanha.
  const maximo = comAgente.reduce((maior, row) => Math.max(maior, row.picks), 0);
  const minimo = Math.min(filtro.usos, maximo);
  const composicoes = comAgente.filter((row) => row.picks >= minimo);
  const picks = agentes.reduce((sum, row) => sum + row.picks, 0);
  const contagem = `${agentes.length} ${agentes.length === 1 ? "agente" : "agentes"}, ${picks} picks, ${todas.length} ${todas.length === 1 ? "composição" : "composições"}`;
  // O resumo da direita mostra o ultimo agente escolhido.
  const destaque = escolhidos.at(-1) || agentes[0];
  return `
    <section class="tournament-section tournament-stats-section vp-est vp-ag-aba">
      <div class="vp-est-lista">
        ${sectionHead("Agentes", contagem)}
        ${tournamentEstFiltros(event, matches, filtro, maximo, minimo, "Usos mínimos das composições", "usos")}
        ${agentes.length ? "" : `<div class="empty-state">Nenhum agente com esses filtros. Tire um filtro para ver mais.</div>`}
        ${tournamentEstTabela(event, { table: "agents", titulo: "Agentes", rows: agentes, columns: tournamentAgenteColunas(ids), fallback: tournamentAgentStatSort, chave: "pagina", porPagina: 10, detalhe: true })}
        ${agentes.length ? tournamentEstTabela(event, { table: "compositions", titulo: "Composições", antes: tournamentAgGrade(agentes, ids, todas), vazio: "Nenhuma composição com esses agentes.", rows: composicoes, columns: tournamentComposicaoColunas(), fallback: tournamentCompositionStatSort, chave: "pagina-comps", porPagina: 10, detalhe: true }) : ""}
      </div>
      ${destaque ? tournamentAgenteResumo(destaque, escolhidos.length > 0, todas) : ""}
    </section>
  `;
}

function tournamentComposicaoTem(row, ids) {
  return ids.every((id) => row.agents.some((agent) => (agent.slug || agent.name) === id));
}

// O procurador das composicoes (modelo A, escolha dele em 08/11/2026): todos os
// agentes do campeonato a vista, por funcao. Um clique escolhe ou desfaz, ate 5.
// Quem nao forma composicao com os ja escolhidos, ou sobra depois do quinto, apaga.
function tournamentAgGrade(agentes, ids, composicoes) {
  const cheio = ids.length >= TOURNAMENT_AG_MAXIMO;
  const grupos = ["duelista", "iniciador", "controlador", "sentinela", ""].map((papel) => ({
    papel,
    linhas: agentes.filter((row) => (normalizeRoleKey(row.role) || "") === papel).sort((a, b) => String(a.name).localeCompare(String(b.name), "pt-BR")),
  })).filter((grupo) => grupo.linhas.length);
  const botao = (row) => {
    const escolhido = ids.includes(row.id);
    const combina = escolhido || (!cheio && composicoes.some((comp) => tournamentComposicaoTem(comp, [...ids, row.id])));
    return `<button type="button" class="vp-ag-escolha" data-agente="${escapeHtml(row.id)}" data-ag-grade aria-pressed="${escolhido}" title="${escapeHtml(row.name)}"${combina ? "" : " disabled"}>${tournamentAgentLogo(row)}</button>`;
  };
  const funcao = (papel) => papel ? `<i class="vp-ag-funcao" style="--icone:url('${escapeHtml(assetPath(ROLE_ICONS[papel].icon))}')" title="${escapeHtml(ROLE_ICONS[papel].label)}"></i>` : "";
  return `
    <div class="vp-ag-grade" role="group" aria-label="Escolher agentes das composições">
      ${grupos.map((grupo) => `<span class="vp-ag-grupo">${funcao(grupo.papel)}${grupo.linhas.map(botao).join("")}</span>`).join("")}
      <span class="vp-ag-conta">${ids.length ? `<span>${ids.length} de ${TOURNAMENT_AG_MAXIMO}</span><button type="button" data-ag-limpar>Limpar</button>` : ""}</span>
    </div>
  `;
}

function tournamentAgentRows(mapMatches, teamId = "") {
  const rows = new Map();
  const mapas = (mapMatches || []).filter((match) => !teamId || match.teamA?.id === teamId || match.teamB?.id === teamId);
  const pickOpportunities = mapas.length * (teamId ? 1 : 2);

  for (const match of mapas) {
    for (const player of match.players || []) {
      if (teamId && agentStatsTeamId(match, player) !== teamId) continue;
      const key = agentStatsKey(player);
      if (!rows.has(key)) rows.set(key, tournamentAgentEmptyRow(key, player));
      updateTournamentAgentRow(rows.get(key), player, match);
    }
  }

  return [...rows.values()].map((row) => tournamentFinalizeAgentRow(row, pickOpportunities)).sort(tournamentAgentStatSort);
}

function agentStatsKey(player = {}) {
  const agentId = String(player.agentId || "");
  return player.agentSlug || AGENT_API_SLUGS[agentId] || slugify(player.agent || agentId || "agent");
}

function agentStatsTeamId(match, player = {}) {
  if (player.teamId) return player.teamId;
  if (player.teamColor && player.teamColor === match?.teamA?.color) return match.teamA.id;
  if (player.teamColor && player.teamColor === match?.teamB?.color) return match.teamB.id;
  return "";
}

function isMirroredAgentPick(match, player) {
  const agentKey = agentStatsKey(player);
  const teamId = agentStatsTeamId(match, player);
  if (!agentKey || !teamId) return false;
  const opponentId = teamId === match?.teamA?.id ? match?.teamB?.id : teamId === match?.teamB?.id ? match?.teamA?.id : "";
  return (match?.players || []).some((other) => {
    if (other === player || agentStatsKey(other) !== agentKey) return false;
    const otherTeamId = agentStatsTeamId(match, other);
    return opponentId ? otherTeamId === opponentId : Boolean(otherTeamId && otherTeamId !== teamId);
  });
}

function agentStatsHasCompleteOpponentLineup(match, player) {
  const teamId = agentStatsTeamId(match, player);
  const opponentId = teamId === match?.teamA?.id ? match?.teamB?.id : teamId === match?.teamB?.id ? match?.teamA?.id : "";
  if (!opponentId) return false;
  return (match?.players || []).filter((other) => {
    const hasAgent = Boolean(other.agentSlug || other.agentId || other.agent);
    return hasAgent && agentStatsTeamId(match, other) === opponentId;
  }).length === 5;
}

function updateTournamentAgentRow(row, player, match) {
  const rounds = Number(player.rounds || match.rounds || 0);
  row.picks += 1;
  row.rounds += rounds;
  row.score += Number(player.score || 0);
  row.kills += Number(player.kills || 0);
  row.deaths += Number(player.deaths || 0);
  row.assists += Number(player.assists || 0);
  row.damage += Number(player.damage || 0);
  row.firstKills += Number(player.firstKills || 0);
  row.firstDeaths += Number(player.firstDeaths || 0);
  row.kastRounds += Number(player.kastRounds || 0);
  row.impactTotal += Number(player.impactTotal || 0);
  addRaatingAggregateFields(row, player);
  row.headshots += Number(player.headshots || 0);
  row.bodyshots += Number(player.bodyshots || 0);
  row.legshots += Number(player.legshots || 0);
  const teamId = agentStatsTeamId(match, player);
  const matchTeamIds = [match?.teamA?.id, match?.teamB?.id];
  const hasResolvedOutcome = Boolean(teamId && match?.winnerId && matchTeamIds.includes(teamId) && matchTeamIds.includes(match.winnerId));
  const won = match.winnerId === teamId;
  row.mapWins += hasResolvedOutcome && won ? 1 : 0;
  row.mapLosses += hasResolvedOutcome && !won ? 1 : 0;
  if (isMirroredAgentPick(match, player)) {
    row.mirroredPicks += 1;
  } else if (!hasResolvedOutcome || !agentStatsHasCompleteOpponentLineup(match, player)) {
    row.unknownMirrorPicks += 1;
  } else {
    row.nonMirroredWins += won ? 1 : 0;
    row.nonMirroredLosses += won ? 0 : 1;
  }
  if (player.id) row.players.add(player.id);
  if (player.teamId) row.teams.add(player.teamId);
  if (match.mapId || match.mapName) row.maps.add(match.mapId || normalizeNameKey(match.mapName));
}

function tournamentAgentEmptyRow(key, player) {
  return {
    id: key,
    slug: player.agentSlug || key,
    name: displayAgentName(player.agent, player.agentSlug || key),
    role: player.agentClass || "Classe",
    icon: player.agentIcon || "",
    picks: 0,
    rounds: 0,
    score: 0,
    kills: 0,
    deaths: 0,
    assists: 0,
    damage: 0,
    firstKills: 0,
    firstDeaths: 0,
    kastRounds: 0,
    impactTotal: 0,
    ...emptyRaatingAggregateFields(),
    headshots: 0,
    bodyshots: 0,
    legshots: 0,
    mapWins: 0,
    mapLosses: 0,
    mirroredPicks: 0,
    unknownMirrorPicks: 0,
    nonMirroredWins: 0,
    nonMirroredLosses: 0,
    players: new Set(),
    teams: new Set(),
    maps: new Set(),
  };
}

function tournamentFinalizeAgentRow(row, pickOpportunities) {
  row.acs = row.rounds ? row.score / row.rounds : 0;
  row.adr = row.rounds ? row.damage / row.rounds : 0;
  row.kpr = row.rounds ? row.kills / row.rounds : 0;
  row.dpr = row.rounds ? row.deaths / row.rounds : 0;
  row.apr = row.rounds ? row.assists / row.rounds : 0;
  row.kd = row.deaths ? row.kills / row.deaths : row.kills;
  row.kastFrac = row.rounds ? row.kastRounds / row.rounds : 0;
  row.kast = row.kastFrac * 100;
  row.impactRound = row.rounds ? row.impactTotal / row.rounds : 0;
  row.impactRoundLegacy = row.rounds ? Number(row.impactTotalLegacy || 0) / row.rounds : 0;
  row.kastLegacyFrac = row.rounds ? Number(row.kastLegacyRounds || 0) / row.rounds : row.kastFrac;
  row.kastLegacy = row.kastLegacyFrac * 100;
  const shots = row.headshots + row.bodyshots + row.legshots;
  row.hs = shots ? (row.headshots / shots) * 100 : 0;
  applyRaatingFields(row);
  row.pickOpportunities = Number(pickOpportunities || 0);
  row.pickRate = pctValue(row.picks, row.pickOpportunities);
  row.nonMirroredPicks = row.nonMirroredWins + row.nonMirroredLosses;
  row.winRateNM = pctValue(row.nonMirroredWins, row.nonMirroredPicks);
  row.winRate = row.winRateNM;
  row.uniquePlayers = row.players.size;
  row.uniqueTeams = row.teams.size;
  row.uniqueMaps = row.maps.size;
  return row;
}

function tournamentAgentStatSort(a, b) {
  return b.picks - a.picks || b.rounds - a.rounds || b.rating - a.rating || a.name.localeCompare(b.name, "pt-BR");
}

function tournamentAgentNonMirroredWinRate(row) {
  return row.nonMirroredPicks ? pct(row.winRateNM) : "-";
}

function tournamentAgentStatsTable(eventId, agents, columns = tournamentAgentStatColumns()) {
  const sortedRows = tournamentSortedStatRows("agents", agents, columns, tournamentAgentStatSort);
  const expanded = tournamentStatsTableExpanded(eventId, "agents");
  const visibleRows = expanded ? sortedRows : sortedRows.slice(0, 10);
  return `
    <article class="tournament-stat-card tournament-stat-table-card">
      <div class="tournament-stat-card-head">
        <span>
          <strong>Tabela de agentes</strong>
          <small>Uso, aproveitamento sem mapas espelhados e desempenho agregado</small>
        </span>
        ${tournamentStatsExpandButton("agents", sortedRows.length, expanded)}
      </div>
      ${tabelaComRotulos(`<div class="table-wrap tournament-stats-table-wrap">
        <table class="tournament-stats-table tournament-agent-stats-table">
          <thead>
            <tr>
              ${columns.map((column) => tournamentStatsHeaderCell("agents", column)).join("")}
            </tr>
          </thead>
          <tbody>
            ${visibleRows.length ? visibleRows.map((row) => tournamentAgentStatsRow(row, columns)).join("") : `<tr><td colspan="${columns.length}"><div class="empty-state compact-empty">Nenhum agente com estatísticas disponíveis.</div></td></tr>`}
          </tbody>
        </table>
      </div>`)}
    </article>
  `;
}

function tournamentAgentStatColumns() {
  return [
    { key: "agent", label: "Agente", value: (row) => row.name || row.slug || "", type: "text", direction: "asc" },
    { key: "picks", label: "Picks", value: (row) => Number(row.picks || 0) },
    { key: "pickRate", label: "Pick%", value: (row) => Number(row.pickRate || 0) },
    { key: "winRate", label: "Win% (NM)", value: (row) => Number(row.winRateNM || 0) },
    { key: "rounds", label: "RND", value: (row) => Number(row.rounds || 0) },
    { key: "uniquePlayers", label: "Jogadores", value: (row) => Number(row.uniquePlayers || 0) },
    { key: "uniqueTeams", label: "Equipes", value: (row) => Number(row.uniqueTeams || 0) },
    { key: "uniqueMaps", label: "Mapas", value: (row) => Number(row.uniqueMaps || 0) },
    { key: "rating", label: "rAAting 3.0", value: (row) => Number(row.rating || 0) },
    { key: "acs", label: "ACS", value: (row) => Number(row.acs || 0) },
    { key: "kd", label: "K:D", value: (row) => Number(row.kd || 0) },
    { key: "kast", label: "KAST", value: (row) => Number(row.kast || 0) },
    { key: "adr", label: "ADR", value: (row) => Number(row.adr || 0) },
    { key: "kpr", label: "KPR", value: (row) => Number(row.kpr || 0) },
    { key: "apr", label: "APR", value: (row) => Number(row.apr || 0) },
    { key: "fkpr", label: "FKPR", value: (row) => (row.rounds ? row.firstKills / row.rounds : 0) },
    { key: "fdpr", label: "FDPR", value: (row) => (row.rounds ? row.firstDeaths / row.rounds : 0) },
    { key: "hs", label: "HS%", value: (row) => Number(row.hs || 0) },
    { key: "kills", label: "K", value: (row) => Number(row.kills || 0) },
    { key: "deaths", label: "D", value: (row) => Number(row.deaths || 0) },
    { key: "assists", label: "A", value: (row) => Number(row.assists || 0) },
    { key: "firstKills", label: "FK", value: (row) => Number(row.firstKills || 0) },
    { key: "firstDeaths", label: "FD", value: (row) => Number(row.firstDeaths || 0) },
  ];
}

function tournamentAgentStatsRow(row, columns = tournamentAgentStatColumns()) {
  return `
    <tr>
      ${columns.map((column) => tournamentAgentStatCell(row, column)).join("")}
    </tr>
  `;
}

function tournamentAgentStatCell(row, column) {
  const key = column.key;
  if (key === "agent") {
    return `
      <td>
        <span class="tournament-agent-cell">
          ${tournamentAgentLogo(row, "tournament-agent-table-logo")}
          <span><strong>${escapeHtml(row.name)}</strong>${rolePill(row.role, "compact")}</span>
        </span>
      </td>
    `;
  }
  if (key === "picks") return `<td class="numeric">${escapeHtml(String(row.picks || 0))}</td>`;
  if (key === "pickRate") return tournamentStatValueCell(pct(row.pickRate));
  if (key === "winRate") return tournamentStatValueCell(tournamentAgentNonMirroredWinRate(row));
  if (key === "rounds") return `<td class="numeric">${escapeHtml(String(row.rounds || 0))}</td>`;
  if (key === "uniquePlayers") return `<td class="numeric">${escapeHtml(String(row.uniquePlayers || 0))}</td>`;
  if (key === "uniqueTeams") return `<td class="numeric">${escapeHtml(String(row.uniqueTeams || 0))}</td>`;
  if (key === "uniqueMaps") return `<td class="numeric">${escapeHtml(String(row.uniqueMaps || 0))}</td>`;
  if (key === "rating") return tournamentStatValueCell(fmt(row.rating));
  if (key === "acs") return tournamentStatValueCell(fmt(row.acs, 0));
  if (key === "kd") return tournamentStatValueCell(fmt(row.kd));
  if (key === "kast") return tournamentStatValueCell(pct(row.kast));
  if (key === "adr") return tournamentStatValueCell(fmt(row.adr, 0));
  if (key === "kpr") return tournamentStatValueCell(fmt(row.kpr));
  if (key === "apr") return tournamentStatValueCell(fmt(row.apr));
  if (key === "fkpr") return tournamentStatValueCell(fmt(row.rounds ? row.firstKills / row.rounds : 0));
  if (key === "fdpr") return tournamentStatValueCell(fmt(row.rounds ? row.firstDeaths / row.rounds : 0));
  if (key === "hs") return tournamentStatValueCell(pct(row.hs));
  if (key === "kills") return `<td class="numeric">${escapeHtml(String(row.kills || 0))}</td>`;
  if (key === "deaths") return `<td class="numeric">${escapeHtml(String(row.deaths || 0))}</td>`;
  if (key === "assists") return `<td class="numeric">${escapeHtml(String(row.assists || 0))}</td>`;
  if (key === "firstKills") return `<td class="numeric">${escapeHtml(String(row.firstKills || 0))}</td>`;
  if (key === "firstDeaths") return `<td class="numeric">${escapeHtml(String(row.firstDeaths || 0))}</td>`;
  const value = column.value ? column.value(row) : "";
  if (column.type === "text") return `<td>${escapeHtml(String(value || ""))}</td>`;
  return tournamentStatValueCell(fmt(Number(value || 0)));
}

function tournamentAgentLogo(row, extra = "") {
  const label = displayAgentName(row.name, row.slug).slice(0, 2).toUpperCase();
  const src = assetPath(row.icon || "");
  return `<span class="tournament-agent-logo ${escapeHtml(extra)}">${src ? `<img src="${escapeHtml(src)}" alt="${escapeHtml(row.name || label)}" loading="lazy" onerror="this.remove()" />` : `<span>${escapeHtml(label)}</span>`}</span>`;
}

function tournamentCompositionRows(mapMatches, soEquipe = "") {
  const rows = new Map();
  let totalPicks = 0;
  for (const match of mapMatches || []) {
    for (const side of [match.teamA, match.teamB]) {
      const teamId = side?.id;
      if (!teamId || (soEquipe && teamId !== soEquipe)) continue;
      const players = (match.players || []).filter((player) => player.teamId === teamId);
      if (!players.length) continue;
      const agents = players.map(tournamentCompositionAgentFromPlayer).filter(Boolean).sort(tournamentCompositionAgentSort);
      if (!agents.length) continue;
      const key = agents.map((agent) => agent.slug || agent.name).sort().join("|");
      if (!rows.has(key)) rows.set(key, tournamentCompositionEmptyRow(key, agents));
      const row = rows.get(key);
      const roundsFor = scoreForTeamInMatch(match, teamId);
      const roundsAgainst = Number(match.teamA?.id === teamId ? match.teamB?.score : match.teamA?.score) || 0;
      totalPicks += 1;
      row.picks += 1;
      row.mapWins += match.winnerId === teamId ? 1 : 0;
      row.mapLosses += match.winnerId === teamId ? 0 : 1;
      row.rounds += Number(match.rounds || roundsFor + roundsAgainst || 0);
      row.roundsFor += roundsFor;
      row.roundsAgainst += roundsAgainst;
      row.roundDiff += roundsFor - roundsAgainst;
      if (teamId) row.teams.add(teamId);
      if (match.mapId || match.mapName) row.maps.add(match.mapId || normalizeNameKey(match.mapName));

      for (const player of players) tournamentAddPlayerStatsToComposition(row, player);
    }
  }
  return [...rows.values()].map((row) => tournamentFinalizeCompositionRow(row, totalPicks)).sort(tournamentCompositionStatSort);
}

function tournamentCompositionAgentFromPlayer(player) {
  const slug = player.agentSlug || slugify(player.agent || "");
  const name = displayAgentName(player.agent, slug);
  if (!slug && !name) return null;
  return {
    slug: slug || normalizeNameKey(name),
    name,
    role: player.agentClass || "",
    icon: player.agentIcon || "",
  };
}

function tournamentCompositionAgentSort(a, b) {
  return roleSortOrder(a.role) - roleSortOrder(b.role) || String(a.name || a.slug).localeCompare(String(b.name || b.slug), "pt-BR");
}

function roleSortOrder(role) {
  const order = { duelista: 1, iniciador: 2, controlador: 3, sentinela: 4 };
  return order[normalizeRoleKey(role)] || 9;
}

function tournamentCompositionEmptyRow(key, agents) {
  return {
    id: key,
    agents,
    picks: 0,
    rounds: 0,
    roundsFor: 0,
    roundsAgainst: 0,
    roundDiff: 0,
    mapWins: 0,
    mapLosses: 0,
    playerRounds: 0,
    score: 0,
    kills: 0,
    deaths: 0,
    assists: 0,
    damage: 0,
    firstKills: 0,
    firstDeaths: 0,
    kastRounds: 0,
    impactTotal: 0,
    ...emptyRaatingAggregateFields(),
    headshots: 0,
    bodyshots: 0,
    legshots: 0,
    teams: new Set(),
    maps: new Set(),
  };
}

function tournamentAddPlayerStatsToComposition(row, player) {
  const rounds = Number(player.rounds || 0);
  row.playerRounds += rounds;
  row.score += Number(player.score || 0);
  row.kills += Number(player.kills || 0);
  row.deaths += Number(player.deaths || 0);
  row.assists += Number(player.assists || 0);
  row.damage += Number(player.damage || 0);
  row.firstKills += Number(player.firstKills || 0);
  row.firstDeaths += Number(player.firstDeaths || 0);
  row.kastRounds += Number(player.kastRounds || 0);
  row.impactTotal += Number(player.impactTotal || 0);
  addRaatingAggregateFields(row, player);
  row.headshots += Number(player.headshots || 0);
  row.bodyshots += Number(player.bodyshots || 0);
  row.legshots += Number(player.legshots || 0);
}

function tournamentFinalizeCompositionRow(row, totalPicks) {
  row.pickRate = totalPicks ? pctValue(row.picks, totalPicks) : 0;
  row.winRate = row.picks ? pctValue(row.mapWins, row.picks) : 0;
  row.uniqueTeams = row.teams.size;
  row.uniqueMaps = row.maps.size;
  row.acs = row.playerRounds ? row.score / row.playerRounds : 0;
  row.adr = row.playerRounds ? row.damage / row.playerRounds : 0;
  row.kpr = row.playerRounds ? row.kills / row.playerRounds : 0;
  row.dpr = row.playerRounds ? row.deaths / row.playerRounds : 0;
  row.apr = row.playerRounds ? row.assists / row.playerRounds : 0;
  row.kd = row.deaths ? row.kills / row.deaths : row.kills;
  row.kastFrac = row.playerRounds ? row.kastRounds / row.playerRounds : 0;
  row.kast = row.kastFrac * 100;
  row.impactRound = row.playerRounds ? row.impactTotal / row.playerRounds : 0;
  row.impactRoundLegacy = row.playerRounds ? Number(row.impactTotalLegacy || 0) / row.playerRounds : 0;
  row.kastLegacyFrac = row.playerRounds ? Number(row.kastLegacyRounds || 0) / row.playerRounds : row.kastFrac;
  row.kastLegacy = row.kastLegacyFrac * 100;
  const shots = row.headshots + row.bodyshots + row.legshots;
  row.hs = shots ? (row.headshots / shots) * 100 : 0;
  applyRaatingFields(row);
  return row;
}

function tournamentCompositionStatSort(a, b) {
  return b.picks - a.picks || b.winRate - a.winRate || b.roundDiff - a.roundDiff || tournamentCompositionLabel(a).localeCompare(tournamentCompositionLabel(b), "pt-BR");
}

function tournamentCompositionLabel(row) {
  return (row.agents || []).map((agent) => agent.name || agent.slug).join(" / ");
}

function tournamentCompositionStatColumns() {
  return [
    { key: "composition", label: "Composição", value: tournamentCompositionLabel, type: "text", direction: "asc" },
    { key: "picks", label: "Usos", value: (row) => Number(row.picks || 0) },
    { key: "pickRate", label: "Pick%", value: (row) => Number(row.pickRate || 0) },
    { key: "winRate", label: "Win%", value: (row) => Number(row.winRate || 0) },
    { key: "maps", label: "Mapas", value: (row) => Number(row.mapWins || 0) - Number(row.mapLosses || 0) / 100 },
    { key: "rounds", label: "RND", value: (row) => Number(row.rounds || 0) },
    { key: "roundDiff", label: "+/-", value: (row) => Number(row.roundDiff || 0) },
    { key: "uniqueTeams", label: "Equipes", value: (row) => Number(row.uniqueTeams || 0) },
    { key: "uniqueMaps", label: "Mapas únicos", value: (row) => Number(row.uniqueMaps || 0) },
    { key: "rating", label: "rAAting 3.0", value: (row) => Number(row.rating || 0) },
    { key: "acs", label: "ACS", value: (row) => Number(row.acs || 0) },
    { key: "kd", label: "K:D", value: (row) => Number(row.kd || 0) },
    { key: "kast", label: "KAST", value: (row) => Number(row.kast || 0) },
    { key: "adr", label: "ADR", value: (row) => Number(row.adr || 0) },
    { key: "kpr", label: "KPR", value: (row) => Number(row.kpr || 0) },
    { key: "apr", label: "APR", value: (row) => Number(row.apr || 0) },
    { key: "fkpr", label: "FKPR", value: (row) => (row.playerRounds ? row.firstKills / row.playerRounds : 0) },
    { key: "fdpr", label: "FDPR", value: (row) => (row.playerRounds ? row.firstDeaths / row.playerRounds : 0) },
    { key: "hs", label: "HS%", value: (row) => Number(row.hs || 0) },
  ];
}

function tournamentCompositionAgentStack(agents = []) {
  return `<span class="tournament-composition-stack">${agents.map((agent) => tournamentAgentLogo(agent, "tournament-composition-agent")).join("")}</span>`;
}

function tournamentStandingsRows(event, matches) {
  if (event.placements?.length) return tournamentOfficialPlacements(event);
  const rows = eventStandings(matches);
  const seen = new Set(rows.map((row) => row.id));
  for (const teamId of event.teams) {
    if (!seen.has(teamId)) rows.push({ id: teamId, seriesWins: 0, seriesLosses: 0, mapWins: 0, mapLosses: 0, roundDiff: 0 });
  }
  return rows;
}

function tournamentFormatLabel(event, matches) {
  if (typeof event.format === "string") return event.format;
  if (event.format?.summary) return event.format.summary;
  return dominantSeriesFormat(matches);
}

function dominantSeriesFormat(matches) {
  if (!matches.length) return "A definir";
  const counts = matches.reduce((map, series) => {
    const label = series.label || seriesFormatLabel(series.maps);
    map.set(label, (map.get(label) || 0) + 1);
    return map;
  }, new Map());
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0] || "A definir";
}

function renderTeamDetail(id) {
  const team = teamById(id);
  if (!team) return renderNotFound("Equipe");
  id = team.id;
  const todasAsSeries = matchSeriesForTeam(id);
  // Cada nome da linha do tempo e um perfil. O atual e a pagina da equipe com a
  // historia inteira; um nome antigo (`?fase=dark_ufrj`) troca a pagina toda para
  // aquela epoca: nome, escudo, cores, quem jogou, trofeus, ranking e abas.
  const fases = teamFases(team, todasAsSeries);
  const pedida = teamFaseAtiva(fases, team);
  const fase = pedida && !pedida.atual ? pedida : null;
  state.faseDaPagina = fase ? { teamId: team.id, nome: fase.nome, logo: fase.logo } : null;
  const naFase = (eventId) => !fase || fase.eventos.has(eventId);
  const matches = todasAsSeries.filter((series) => naFase(series.eventId));
  const perfil = teamPerfilDaFase(team, fase, matches);
  const currentLineup = fase ? [] : team.currentLineup || [];
  const observedPlayers = state.db.players
    .filter((player) => player.observedTeamId === id && player.matches > 0)
    .sort((a, b) => Number(officialRatingValue(playerStatsForTeam(b, id)) || 0) - Number(officialRatingValue(playerStatsForTeam(a, id)) || 0));
  const quemJogou = teamQuemJogou(team, matches);
  const naEpoca = new Set(quemJogou.map((player) => player.id));
  const historicalPlayers = teamHistoricalPlayers(team)
    .filter((player) => !currentLineup.some((entry) => entry.playerId === player.id))
    .filter((player) => !fase || naEpoca.has(player.id));
  const trophies = teamTrophyAchievements(team).filter((trophy) => naFase(trophy.event.id));
  const tournaments = teamCampeonatos(team, matches, trophies).filter((event) => naFase(event.id));
  const jogos = teamJogos(team, tournaments, matches);
  const abas = teamAbasVisiveis({ currentLineup, quemJogou, historicalPlayers, jogos, matches });
  const activeTab = abas.includes(route().tab) ? route().tab : "resumo";
  const tabSlide = panelSlideSnapshot("team-tabs", {
    selector: ".team-tab-panel",
    scope: team.id,
    key: `${activeTab}:${fase?.id || ""}`,
    order: TEAM_TAB_KEYS.flatMap((tab) => ["", ...fases.map((item) => item.id)].map((item) => `${tab}:${item}`)),
  });
  Shell(`
    <section class="team-page" ${teamAccentStyle(perfil)}>
      ${teamFasesNav(team, fases, fase, activeTab)}
      <div class="vp-capa-cabeca">
        ${teamCapa(perfil, { currentLineup, quemJogou, trophies })}
        <nav class="team-tabs" aria-label="Abas da equipe">
          ${abas.map((tab) => teamTabLink(team, tab, TEAM_TAB_ROTULOS[tab], activeTab, fase)).join("")}
        </nav>
      </div>
      <section class="team-tab-panel">
        ${renderTeamTab(activeTab, perfil, { matches, currentLineup, observedPlayers, historicalPlayers, quemJogou, tournaments, trophies, jogos })}
      </section>
      ${window.Comments ? window.Comments.shell("team", team.id) : ""}
    </section>
  `);
  if (fase) document.title = `${perfil.name} - UNIVLR`;
  window.Comments?.montar("team", team.id);
  ajustaTituloDaEquipe();
  bindAbaDaEquipe(team.id);
  playPanelSlide(tabSlide);
}

const TEAM_TAB_KEYS = ["resumo", "roster", "matches", "tournaments", "stats"];
const TEAM_TAB_ROTULOS = { resumo: "Visão Geral", roster: "Elenco", matches: "Partidas", tournaments: "Campeonatos", stats: "Estatísticas" };

// Aba sem dado nao aparece: 15 equipes so existem na inscricao de um campeonato,
// e nelas Partidas, Elenco e Estatisticas abririam vazias.
function teamAbasVisiveis({ currentLineup, quemJogou, historicalPlayers, jogos, matches }) {
  return TEAM_TAB_KEYS.filter((tab) => {
    if (tab === "roster") return Boolean(currentLineup.length || quemJogou.length || historicalPlayers.length);
    if (tab === "matches") return jogos.length > 0;
    if (tab === "stats") return matches.length > 0;
    return true;
  });
}

function renderTeamTab(activeTab, team, context) {
  const renderers = {
    resumo: () => teamResumoTab(team, context),
    roster: () => teamRosterTab(team, context),
    matches: () => teamMatchesTab(team, context.jogos),
    tournaments: () => teamTournamentsTab(team, context),
    stats: () => teamStatsTab(team, context.matches),
  };
  return (renderers[activeTab] || renderers.resumo)();
}

// A faixa de fotos, como a da HLTV, vestida nas duas cores da equipe. Embaixo, so
// o que identifica a equipe e a posicao dela, e a fila de trofeus: quem abre a
// pagina ve elenco, ranking e conquistas sem rolar.
function teamCapa(team, { currentLineup, quemJogou, trophies }) {
  const elenco = teamCapaElenco(team, currentLineup, quemJogou);
  return `
    <header class="vp-capa">
      ${elenco.length ? `
        <div class="vp-slide vp-capa-fotos" style="${escapeHtml(teamPlateStyle(team))};--n:${elenco.length}" aria-label="${escapeHtml(`Elenco ${team.name}`)}">
          <span class="vp-slide-campo"><i></i></span>
          ${elenco.map(({ entry, player }) => teamCapaJogador(team, entry, player)).join("")}
        </div>
      ` : ""}
      <div class="vp-capa-id">
        ${teamProfileLogo(team)}
        <div class="vp-equipe-id">
          <h1>${escapeHtml(team.name)}</h1>
          <span class="vp-equipe-onde">${teamCapaOnde(team)}</span>
        </div>
        <span class="vp-equipe-acoes">${window.Favorites ? window.Favorites.botao("team", team.id) : ""}${teamSocialLinks(team)}</span>
        ${teamCapaNumeros(team)}
      </div>
      ${teamCapaTrofeus(trophies)}
    </header>
  `;
}

// Quem jogou pela equipe, de quem tem mais mapas para quem tem menos, lido do placar
// de cada mapa. `observedTeamId` so guarda a equipe principal de cada jogador: nas
// equipes B e nas de um campeonato so, ele deixava a formacao com 2 de 5.
function teamQuemJogou(team, matches) {
  const mapas = new Map();
  matches.forEach((series) => (series.maps || []).forEach((match) => (match.players || []).forEach((row) => {
    if (row.teamId === team.id) mapas.set(row.id, (mapas.get(row.id) || 0) + 1);
  })));
  return [...mapas.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([id]) => playerById(id))
    .filter(Boolean);
}

// O elenco curado manda. Equipe sem elenco cadastrado mostra quem mais jogou por ela.
function teamCapaElenco(team, currentLineup, quemJogou) {
  const cadastrados = currentLineup.map((entry) => ({ entry, player: entry.playerId ? playerById(entry.playerId) : null }));
  if (cadastrados.length) {
    const escolhidos = new Set(rankingRosterTopFive(team, currentLineup));
    return cadastrados.filter((row) => escolhidos.has(row.entry));
  }
  return quemJogou.slice(0, 5).map((player) => ({ entry: { playerId: player.id, name: player.nick }, player }));
}

function teamCapaJogador(team, entry, player) {
  const nome = player?.nick || entry?.name || "Jogador";
  const corpo = `${playerFigure(player, team, "vp-capa-foto")}<span class="vp-capa-nick">${escapeHtml(nome)}</span>`;
  return playerTemPerfil(player) ? `<a class="vp-capa-jog" href="${playerHref(player)}">${corpo}</a>` : `<span class="vp-capa-jog">${corpo}</span>`;
}

// So o que foi cadastrado: o aviso de campo vazio em 1 de cada 3 equipes era ruido.
function teamCapaOnde(team) {
  const instituicao = teamInstitutionLabel(team);
  return [
    `<b class="vp-equipe-tag">${escapeHtml(team.sourceTag || team.tag || team.id)}</b>`,
    team.profile?.stateName ? teamStateBadge(team) : "",
    /n[aã]o informad/i.test(instituicao) ? "" : `<span>${escapeHtml(instituicao)}</span>`,
  ].filter(Boolean).join("");
}

function teamGanhouSerie(series, teamId) {
  const placar = seriesScoreForTeam(series, teamId);
  return series.winnerId === teamId || (!series.winnerId && placar.mapsFor > placar.mapsAgainst);
}

function teamCapaNumeros(team) {
  const valida = teamValidRank(team);
  const itens = [
    { valor: teamCanonicalRankLabel(team), rotulo: "Ranking", classe: valida ? "" : "vp-capa-texto" },
    valida ? { valor: fmt(team.ranking?.score ?? team.rankingScore ?? 0, 1), rotulo: "Nota" } : null,
  ].filter(Boolean);
  return `<dl class="vp-capa-numeros">${itens.map((item) => `<div><dd class="${item.classe || ""}">${escapeHtml(item.valor)}</dd><dt>${escapeHtml(item.rotulo)}</dt></div>`).join("")}</dl>`;
}

// A fila de trofeus leva a cada campeonato. Quem tem mais do que cabe numa linha
// anda pelas setas, numa lista que se repete: as copias antes e depois dos originais
// dao a volta sem salto. Sem setas, elas ficam escondidas pelo CSS.
// O texto do trofeu. A etapa que decide da o titulo do campeonato inteiro
// ("Campeão, JUBS 2026 - Goiás"); as outras etapas levam o nome delas ("Campeão da
// Off Season, LBEU 2025 - 1º Split"). O MVP segue a etapa em que foi dado.
function rotuloDoTrofeu(trophy) {
  const event = trophy.event;
  const campeonato = campeonatoDaEtapa(event);
  if (!campeonato) return { titulo: trophy.placementLabel || "", campeonato: event?.name || "Campeonato" };
  if (campeonato.decide.id === event.id) return { titulo: trophy.placementLabel || "", campeonato: campeonato.nome };
  return { titulo: `${trophy.placementLabel || ""} ${campeonato.artigos.get(event.id) || "da"} ${event.etapaNome}`, campeonato: campeonato.nome };
}

function rotuloDoTrofeuEmTexto(trophy) {
  const { titulo, campeonato } = rotuloDoTrofeu(trophy);
  return `${titulo}, ${campeonato}`;
}

function teamCapaTrofeus(trophies) {
  if (!trophies.length) return "";
  const item = (trophy, copia) => {
    const rotulo = escapeHtml(rotuloDoTrofeuEmTexto(trophy));
    return `<a class="vp-capa-trofeu" href="#/tournaments/${escapeHtml(trophy.event.id)}" title="${rotulo}" aria-label="${rotulo}"${copia ? ` data-copia aria-hidden="true" tabindex="-1"` : ""}>${trophyVisual(trophy)}</a>`;
  };
  const copias = trophies.map((trophy) => item(trophy, true)).join("");
  return `
    <div class="vp-capa-trofeus" data-trofeus="${trophies.length}">
      <button type="button" class="vp-trofeus-seta" data-trofeus-seta="-1" aria-label="Troféus anteriores" hidden><i></i></button>
      <div class="vp-trofeus-janela"><div class="vp-trofeus-trilho">${copias}${trophies.map((trophy) => item(trophy, false)).join("")}${copias}</div></div>
      <button type="button" class="vp-trofeus-seta vp-trofeus-prox" data-trofeus-seta="1" aria-label="Próximos troféus" hidden><i></i></button>
    </div>
  `;
}

function bindTrofeusDaCapa() {
  const faixa = document.querySelector(".vp-capa-trofeus");
  if (!faixa) return;
  const trilho = faixa.querySelector(".vp-trofeus-trilho");
  const total = Number(faixa.dataset.trofeus);
  let posicao = 0;
  let ultima = 0;
  const porLinha = () => Number(getComputedStyle(faixa).getPropertyValue("--por-linha")) || 14;
  const mover = (valor, anima) => {
    trilho.style.transition = anima ? "" : "none";
    trilho.style.setProperty("--pos", valor);
    posicao = valor;
  };
  const ajusta = () => {
    if (porLinha() === ultima) return;
    ultima = porLinha();
    const rola = total > ultima;
    faixa.classList.toggle("com-setas", rola);
    faixa.querySelectorAll("[data-trofeus-seta]").forEach((seta) => {
      seta.hidden = !rola;
    });
    mover(rola ? total : 0, false);
  };
  new ResizeObserver(ajusta).observe(faixa);
  ajusta();
  faixa.addEventListener("click", (event) => {
    const seta = event.target.closest("[data-trofeus-seta]");
    if (!seta) return;
    // Antes de andar, volta para a copia equivalente, sem animar: e o que faz a
    // lista parecer sem fim. O passo nunca mostra alem das copias.
    if (posicao >= total * 2) mover(posicao - total, false);
    else if (posicao < total) mover(posicao + total, false);
    trilho.getBoundingClientRect();
    const passo = Math.max(1, Math.min(ultima - 2, total - ultima));
    mover(posicao + Number(seta.dataset.trofeusSeta) * passo, true);
  });
}

// A aba de entrada responde "como esta a equipe": a forma, o que vem por ai e o
// ranking com a nota. Cada bloco leva para a aba que o aprofunda. Equipe pequena
// fica so com o que tem, sem caixa vazia: 130 nao tem historico de ranking.
const TEAM_RESUMO_PARTIDAS = 5;

function teamResumoTab(team, context) {
  const historico = teamRankingCanonicalHistory(team);
  const nota = teamSuccessionNote(team);
  const proximos = context.jogos.filter((jogo) => !jogo.series && !jogo.vencedor && !jogo.match?.status && !eventIsDone(jogo.event));
  const sucedida = Boolean(team.ranking?.succeededBy);
  return `
    <div class="vp-equipe-corpo">
      <div class="vp-equipe-principal">
        ${teamForma(team, context.jogos)}
        ${proximos.length ? `
          <section class="vp-s-proximas">
            ${sectionHead(proximos.length === 1 ? "Próxima partida" : "Próximas partidas")}
            <div class="vp-lista">${proximos.map((jogo) => tournamentJogoSemArquivo(jogo.event, jogo)).join("")}</div>
          </section>
        ` : ""}
        ${historico.length || nota ? `
          <section class="vp-s-ranking-equipe">
            ${sectionHead("Histórico do ranking")}
            ${nota}
            ${historico.length ? teamRankingChart(historico, Math.min(...context.matches.map((series) => dateValue(series.startedAt)).filter(Boolean)), teamRankingHistory(team).filter((row) => row.provisorio), teamLineDaEpoca(team)) : ""}
          </section>
        ` : ""}
        ${historico.length && !sucedida ? `<section class="team-ranking-explainer">${rankingExplanationPanel(team, null, null, { recolhido: true })}</section>` : ""}
      </div>
      <aside class="vp-equipe-trilho">
        ${teamFicha(team, context)}
        ${teamCampanhasRecentes(team, context)}
      </aside>
    </div>
  `;
}

// Os ultimos resultados como a fila de logos da HLTV: o adversario, o placar e o
// resultado, do mais recente para o mais antigo. Resultado que so existe na chave
// entra tambem, mas sem link, porque nao tem pagina de partida.
function teamForma(team, jogos) {
  const ultimas = jogos.filter((jogo) => jogo.vencedor).sort(maisRecentePrimeiro).slice(0, TEAM_RESUMO_PARTIDAS);
  if (!ultimas.length) return "";
  return `
    <section class="vp-s-forma">
      ${sectionHead(ultimas.length === 1 ? "Última partida" : "Últimas partidas", "", `teams/${team.id}/matches`, `Ver as ${jogos.length}`)}
      <div class="vp-forma">${ultimas.map((jogo) => teamFormaItem(team, jogo)).join("")}</div>
    </section>
  `;
}

function teamFormaPlacar(team, { series, match }) {
  if (series) {
    const placar = seriesScoreForTeam(series, team.id);
    return [placar.mapsFor, placar.mapsAgainst];
  }
  return (match.a === team.id ? [match.scoreA, match.scoreB] : [match.scoreB, match.scoreA]).map((valor) => valor ?? "-");
}

function teamFormaItem(team, jogo) {
  const rivalId = teamJogoRival(jogo, team);
  const nome = teamById(rivalId)?.name || displayTeamName(rivalId);
  const [nosso, deles] = teamFormaPlacar(team, jogo);
  const venceu = jogo.vencedor === team.id;
  const resultado = venceu ? "Vitória" : jogo.vencedor ? "Derrota" : "Sem vencedor";
  const corpo = `
    ${teamLogo(rivalId, "large")}
    <strong title="${escapeHtml(nome)}"><span class="nome-rolante">${escapeHtml(nome)}</span></strong>
    <b>${escapeHtml(nosso)}<i>:</i>${escapeHtml(deles)}</b>
    <small>${escapeHtml([resultado, jogo.quando ? dataSemAno(jogo.quando) : jogo.match?.status].filter(Boolean).join(", "))}</small>
  `;
  const classe = `vp-forma-item${venceu ? " vp-forma-v" : ""}`;
  return jogo.series
    ? `<a class="${classe}" href="${matchSeriesHref(jogo.series)}" aria-label="${escapeHtml(`${resultado} contra ${nome}, ${nosso} a ${deles}`)}">${corpo}</a>`
    : `<span class="${classe}">${corpo}</span>`;
}

function teamFicha(team, { matches, tournaments }) {
  const datas = matches.map((series) => dateValue(series.startedAt)).filter(Boolean);
  const linhas = [
    datas.length ? ["Primeira partida", formatDate(Math.min(...datas), "date")] : null,
    datas.length ? ["Última partida", formatDate(Math.max(...datas), "date")] : null,
    ["Campeonatos", String(tournaments.length)],
    team.matches ? ["Mapas", `${team.wins}-${team.losses}`] : null,
    team.matches ? ["Saldo de rounds", signed(team.roundDiff)] : null,
    team.matches ? ["Ataque", pct(team.attackWinRate)] : null,
    team.matches ? ["Defesa", pct(team.defenseWinRate)] : null,
    team.matches ? ["Pistol", pct(team.pistolWinRate)] : null,
  ].filter(Boolean);
  return `
    <section>
      ${sectionHead("Informações")}
      <dl class="vp-ficha">${linhas.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${escapeHtml(valor)}</dd></div>`).join("")}</dl>
    </section>
  `;
}

function teamCampanhasRecentes(team, { tournaments, trophies }) {
  const linhas = teamCampanhas(team, tournaments, trophies);
  if (!linhas.length) return "";
  return `
    <section>
      ${sectionHead("Últimas campanhas", "", `teams/${team.id}/tournaments`, `Ver as ${linhas.length}`)}
      <div class="vp-campanhas">
        ${linhas.slice(0, 5).map(({ event, colocacao }) => `
          <a class="vp-campanha" href="#/tournaments/${escapeHtml(event.id)}">
            ${eventLogo(event, "tiny")}
            <strong title="${escapeHtml(event.name)}"><span class="nome-rolante">${escapeHtml(event.name)}</span></strong>
            <span class="team-placement-badge ${escapeHtml(colocacao.tom)}"><strong>${escapeHtml(colocacao.valor)}</strong></span>
          </a>
        `).join("")}
      </div>
    </section>
  `;
}

// O simbolo de cada rede, na cor do texto. O nome fica no aria-label e no title.
const TEAM_REDES = {
  website: ["Site", `<circle cx="12" cy="12" r="9.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="M2.5 12h19M12 2.5c3 3 3.8 6 3.8 9.5s-.8 6.5-3.8 9.500c-3-3-3.8-6-3.8-9.500S9 5.5 12 2.500z" fill="none" stroke="currentColor" stroke-width="2"/>`],
  instagram: ["Instagram", `<rect x="2.5" y="2.5" width="19" height="19" rx="5.5" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="4.5" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="17.5" cy="6.5" r="1.3" fill="currentColor"/>`],
  x: ["X", `<path fill="currentColor" d="M18.244 2.250h3.308l-7.227 8.260 8.502 11.240H16.170l-5.214-6.817L4.990 21.750H1.680l7.730-8.835L1.254 2.250H8.080l4.713 6.231zm-1.161 17.520h1.833L7.084 4.126H5.117z"/>`],
  twitch: ["Twitch", `<path fill="currentColor" d="M2.149 0l-1.612 4.119v16.836h5.731v3.045h3.224l3.045-3.045h4.657l6.269-6.269V0H2.149zm19.164 13.612l-3.582 3.582H12l-3.045 3.045v-3.045H4.119V2.149h17.194v11.463zm-3.582-7.343v6.262h-2.149V6.269h2.149zm-5.731 0v6.262H9.851V6.269H12z"/>`],
  youtube: ["YouTube", `<path fill="currentColor" d="M23.5 6.200a3 3 0 0 0-2.1-2.100C19.5 3.6 12 3.6 12 3.600s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2 31 31 0 0 0 0 12a31 31 0 0 0 .5 5.8 3 3 0 0 0 2.1 2.100c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.100A31 31 0 0 0 24 12a31 31 0 0 0-.5-5.800zM9.6 15.600V8.400l6.2 3.600z"/>`],
  discord: ["Discord", `<path fill="currentColor" d="M20.317 4.370a19.791 19.791 0 0 0-4.885-1.515.074.074 0 0 0-.079.037c-.21.375-.444.864-.608 1.250a18.270 18.270 0 0 0-5.487 0 12.640 12.640 0 0 0-.617-1.250.077.077 0 0 0-.079-.037A19.736 19.736 0 0 0 3.677 4.370a.07.07 0 0 0-.032.027C.533 9.046-.32 13.580.099 18.057a.082.082 0 0 0 .031.057 19.9 19.9 0 0 0 5.993 3.030.078.078 0 0 0 .084-.028 14.090 14.090 0 0 0 1.226-1.994.076.076 0 0 0-.041-.106 13.107 13.107 0 0 1-1.872-.892.077.077 0 0 1-.008-.128 10.2 10.2 0 0 0 .372-.292.074.074 0 0 1 .077-.01c3.928 1.793 8.180 1.793 12.062 0a.074.074 0 0 1 .078.01c.12.098.246.198.373.292a.077.077 0 0 1-.006.127 12.299 12.299 0 0 1-1.873.892.077.077 0 0 0-.041.107c.36.698.772 1.362 1.225 1.993a.076.076 0 0 0 .084.028 19.839 19.839 0 0 0 6.002-3.030.077.077 0 0 0 .032-.054c.5-5.177-.838-9.674-3.549-13.660a.061.061 0 0 0-.031-.03zM8.020 15.330c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.956-2.419 2.157-2.419 1.210 0 2.176 1.096 2.157 2.420 0 1.333-.956 2.418-2.157 2.418zm7.975 0c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.210 0 2.176 1.096 2.157 2.420 0 1.333-.946 2.418-2.157 2.418z"/>`],
};

// So as redes que a equipe cadastrou. Os seis icones apagados de "nao informado"
// sairam do topo, e o nome de cada rede deu lugar ao simbolo.
function teamSocialLinks(team) {
  const socials = team.profile?.socials || {};
  return Object.entries(TEAM_REDES)
    .filter(([key]) => socials[key])
    .map(([key, [rotulo, desenho]]) => `<a class="vp-equipe-rede" href="${escapeHtml(socials[key])}" target="_blank" rel="noopener noreferrer" title="${rotulo}" aria-label="${rotulo}"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false">${desenho}</svg></a>`)
    .join("");
}

// Os trofeus soltos no trilho: a medalha do campeonato e, ao lado, a colocacao
// e o campeonato com o mes. Serve para equipe e jogador.
function trofeusLista(trophies) {
  if (!trophies.length) return "";
  return `<div class="vp-trofeus">${trophies
    .map((trophy) => {
      const { titulo, campeonato } = rotuloDoTrofeu(trophy);
      return `<a class="vp-trofeu" href="#/tournaments/${escapeHtml(trophy.event.id)}">${trophyVisual(trophy)}<span><strong>${escapeHtml(titulo)}</strong><small>${escapeHtml([campeonato, trophy.detail || trophyMonthLabel(trophy.date)].filter(Boolean).join(", "))}</small></span></a>`;
    })
    .join("")}</div>`;
}

function trophyMonthLabel(value) {
  const quando = dateValue(value);
  if (!quando) return "";
  return new Date(quando).toLocaleDateString("pt-BR", { month: "short", year: "numeric" }).replace(".", "");
}

function teamTabLink(team, tab, label, activeTab, fase = null) {
  const query = fase ? `?fase=${encodeURIComponent(fase.id)}` : "";
  return `<a class="team-tab ${activeTab === tab ? "active" : ""}" href="#/teams/${team.id}/${tab}${query}">${escapeHtml(label)}</a>`;
}

// Os nomes que a mesma line usou, do mais antigo ao atual (Dark UFRJ, depois
// Minerva Thunders). As fases antigas vêm de `nomes` no team-profiles.json, gravado
// quando a sucessão virou uma equipe só; cada uma lista os campeonatos que jogou com
// aquele nome, e o resto é da fase atual. Equipe que nunca trocou de nome não tem fase.
function teamFases(team, matches) {
  const antigas = (team.profile?.nomes || []).filter((fase) => fase?.id && fase.nome);
  if (!antigas.length) return [];
  const dasAntigas = new Set(antigas.flatMap((fase) => fase.eventos || []));
  const atuais = matches.filter((series) => !dasAntigas.has(series.eventId));
  const quando = (lista) => lista.map((series) => Number(series.sortAt || series.startedAt || 0)).filter(Boolean);
  const datasAtuais = quando(atuais);
  // "2026-04-01" sozinho e meia-noite UTC, que no Brasil ainda e o dia 31 do mes
  // anterior: o dia gravado e lido ao meio-dia local.
  const dia = (texto) => (/^\d{4}-\d{2}-\d{2}$/.test(String(texto || "")) ? Date.parse(`${texto}T12:00:00`) : Date.parse(texto));
  return [
    ...antigas.map((fase) => ({
      id: fase.id,
      nome: fase.nome,
      tag: fase.tag || "",
      logo: fase.logo || "",
      cores: fase.cores || [],
      eventos: new Set(fase.eventos || []),
      desde: dia(fase.desde),
      ate: dia(fase.ate),
    })),
    {
      id: team.id,
      nome: team.name,
      logo: team.profile?.logo || team.logo || "",
      cores: team.colors || [],
      eventos: new Set(atuais.map((series) => series.eventId)),
      atual: true,
      desde: datasAtuais.length ? Math.min(...datasAtuais) : 0,
      ate: datasAtuais.length ? Math.max(...datasAtuais) : 0,
    },
  ].sort((a, b) => (a.atual ? 1 : 0) - (b.atual ? 1 : 0) || a.desde - b.desde)
    .map((fase, indice, lista) => ({ ...fase, proxima: lista[indice + 1]?.desde }));
}

// A equipe vestida como na epoca de uma fase antiga: nome, sigla, escudo e cores
// daquele nome, sem redes (sao as de hoje) e com o ranking da semana em que a fase
// acabou. Sem fase, e a propria equipe.
function teamPerfilDaFase(team, fase, series = []) {
  if (!fase) return team;
  // O nome vale ate o proximo estrear: a Canis seguiu ranqueada ate fev/26 sem
  // jogar. A capa mostra a ultima posicao valida dessa janela.
  const limite = Number.isFinite(fase.proxima) ? fase.proxima : Infinity;
  const semanas = (state.db?.rankingSnapshots || [])
    .filter((semana) => Number(semana.cutoffAt || 0) >= fase.desde && Number(semana.cutoffAt || 0) < limite && semana.byTeamId?.[team.id]?.matches)
    .sort((a, b) => Number(b.cutoffAt || 0) - Number(a.cutoffAt || 0));
  const fim = semanas.find((semana) => rankingIsValid(semana.byTeamId[team.id])) || semanas[0];
  const ranking = fim?.byTeamId?.[team.id] || { inactive: true };
  // A ficha (mapas, saldo, ataque, defesa, pistol) conta so os mapas da fase.
  const soma = { matches: 0, wins: 0, losses: 0, roundDiff: 0, attackWins: 0, attackRounds: 0, defenseWins: 0, defenseRounds: 0, pistolWins: 0, pistolRounds: 0 };
  series.forEach((item) => (item.maps || []).forEach((match) => {
    const nosso = match.teamA?.id === team.id ? match.teamA : match.teamB?.id === team.id ? match.teamB : null;
    if (!nosso) return;
    const deles = nosso === match.teamA ? match.teamB : match.teamA;
    const venceu = match.winnerId === team.id;
    const rounds = match.teamStats?.[team.id] || {};
    soma.matches += 1;
    soma.wins += venceu ? 1 : 0;
    soma.losses += venceu ? 0 : 1;
    soma.roundDiff += Number(nosso.score || 0) - Number(deles?.score || 0);
    ["attackWins", "attackRounds", "defenseWins", "defenseRounds", "pistolWins", "pistolRounds"].forEach((chave) => { soma[chave] += Number(rounds[chave] || 0); });
  }));
  return {
    ...team,
    ...soma,
    attackWinRate: pctValue(soma.attackWins, soma.attackRounds),
    defenseWinRate: pctValue(soma.defenseWins, soma.defenseRounds),
    pistolWinRate: pctValue(soma.pistolWins, soma.pistolRounds),
    rankingJanela: [fase.desde, Math.min(limite - 1, Number(semanas[0]?.cutoffAt || fase.ate))],
    name: fase.nome,
    tag: fase.tag || team.tag,
    sourceTag: fase.tag || team.sourceTag,
    logo: fase.logo || team.logo,
    colors: fase.cores?.length ? fase.cores : team.colors,
    currentLineup: [],
    ranking,
    rankingScore: ranking.score ?? 0,
    validRank: ranking.validRank ?? null,
    rankingSemana: fim?.cutoffAt || null,
    profile: { ...team.profile, logo: fase.logo || team.profile?.logo, socials: {} },
  };
}

// A fase da URL (`?fase=dark_ufrj`). O id da equipe também vale, e é a fase atual.
// O id antigo na rota (`#/teams/dark_ufrj`) abre a mesma página já naquela fase, e
// o endereço passa a ser o da equipe atual com `?fase=`, como se tivesse clicado no
// nome da linha do tempo.
function teamFaseAtiva(fases, team = null) {
  const query = routeQuery();
  const pedida = query.get("fase");
  if (pedida) return fases.find((fase) => fase.id === pedida) || null;
  const naRota = decodeURIComponent(route().id || "");
  const daRota = team && naRota !== team.id ? fases.find((fase) => !fase.atual && fase.id === naRota) : null;
  if (daRota && typeof history !== "undefined" && typeof history.replaceState === "function") {
    query.set("fase", daRota.id);
    const aba = route().tab ? `/${route().tab}` : "";
    history.replaceState(history.state, "", `#/teams/${team.id}${aba}?${query.toString()}`);
  }
  return daRota || null;
}

const TEAM_FASE_MESES = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"];

function teamFaseMes(valor) {
  const data = new Date(valor);
  return `${TEAM_FASE_MESES[data.getMonth()]}/${String(data.getFullYear()).slice(2)}`;
}

function teamFasePeriodo(fase) {
  if (!fase.desde) return "";
  const inicio = teamFaseMes(fase.desde);
  const fim = teamFaseMes(fase.ate || fase.desde);
  return inicio === fim ? inicio : `${inicio} - ${fim}`;
}

// A linha do tempo no topo da pagina, acima da capa, no desenho das etapas do
// campeonato. Cada nome e um perfil: o atual e a pagina sem `fase`, e um antigo
// troca a pagina inteira para aquela epoca, mantendo a aba aberta.
function teamFasesNav(team, fases, ativa, activeTab) {
  if (fases.length < 2) return "";
  const aba = activeTab && activeTab !== "resumo" ? `/${activeTab}` : "";
  return `
    <nav class="vp-camp-etapas vp-equipe-fases" aria-label="${escapeHtml(`Nomes de ${team.name}`)}">
      ${fases.map((fase, indice) => {
        const marcada = fase.atual ? !ativa : ativa?.id === fase.id;
        const href = `#/teams/${team.id}${aba}${fase.atual ? "" : `?fase=${encodeURIComponent(fase.id)}`}`;
        const src = assetPath(fase.logo);
        const logo = src ? `<span class="team-logo clean-logo vp-fase-logo"><img src="${escapeHtml(src)}" alt="" loading="lazy" onerror="this.closest('.team-logo').remove()" /></span>` : "";
        return `${indice ? `<span class="vp-fase-seta" aria-hidden="true">&rarr;</span>` : ""}<a href="${escapeHtml(href)}"${marcada ? ` aria-current="page"` : ""}>${logo}<span>${escapeHtml(fase.nome)}</span><small>${escapeHtml(teamFasePeriodo(fase))}</small></a>`;
      }).join("")}
    </nav>
  `;
}

// Sucessao de equipe (ver rankingSuccessionAliases): a pagina da antiga diz para
// onde a nota foi, e a da nova, de quem ela herdou. As partidas e os trofeus de
// cada uma continuam na propria pagina.
function teamSuccessionNote(team) {
  const ranking = team.ranking || {};
  const link = (id) => {
    const other = teamById(id);
    return other ? `<a href="#/teams/${other.id}">${escapeHtml(other.name)}</a>` : escapeHtml(id);
  };
  if (ranking.succeededBy) {
    return `<p class="ranking-note">Desde ${escapeHtml(formatDate(ranking.succeededAt))}, ${ranking.performanceOnly ? "o desempenho desta formação conta" : "a nota desta equipe conta"} para a ${link(ranking.succeededBy)}. ${ranking.performanceOnly ? "Títulos e colocações não são transferidos. " : ""}As partidas e os troféus continuam nesta página.</p>`;
  }
  if (ranking.inherits?.length) {
    const partial = new Set(ranking.performanceInherits || []);
    const fullParts = ranking.inherits.filter((id) => !partial.has(id)).map(link);
    const partialParts = ranking.inherits.filter((id) => partial.has(id)).map(link);
    return `<p class="ranking-note">${fullParts.length ? `A nota inclui partidas e colocações de ${fullParts.join(" e ")}. ` : ""}${partialParts.length ? `O desempenho inclui partidas de ${partialParts.join(" e ")}, sem transferir títulos ou colocações. ` : ""}As campanhas antigas permanecem com as equipes que as disputaram.</p>`;
  }
  if (team.profile?.competitiveStatus === "dissolved") return `<p class="ranking-note">Equipe encerrada, sem sucessora. Suas partidas e campanhas permanecem neste perfil.</p>`;
  if (team.profile?.continuity === "none") return `<p class="ranking-note">Equipe histórica independente, sem continuidade coletiva em outra equipe.</p>`;
  return "";
}

function teamRankingCanonicalHistory(team) {
  return teamRankingHistory(team)
    .filter((row) => Number.isFinite(Number(row.rank)) && Number(row.rank) > 0)
    .sort((a, b) => dateValue(b.date) - dateValue(a.date));
}

// O eixo das posicoes e igual para todas as equipes, de #1 ao teto do ranking em
// dezenas: uma linha colada no topo ou no fundo diz a mesma coisa em qualquer perfil.
// O eixo do tempo e o da propria equipe, da primeira partida ao ultimo ranking.
function rankingTetoGeral(rows = []) {
  const fotos = state.db?.rankingSnapshots || [];
  const maior = Math.max(
    10,
    ...fotos.flatMap((foto) => Object.values(foto.byTeamId || {}).map((row) => Number(row.validRank) || 0)),
    ...rows.map((row) => Number(row.rank) || 0),
  );
  return Math.ceil(maior / 10) * 10;
}

function rankingChartTicks(teto) {
  const redondos = [25, 50, 75, 100, 125, 150].filter((valor) => valor <= teto - 10);
  return [1, ...redondos, teto];
}

// Um rotulo por mes do periodo, o do comeco incluso mesmo se ele comecar no meio do mes.
function mesesDoPeriodo(inicio, fim) {
  const meses = [];
  const data = new Date(inicio);
  data.setDate(1);
  data.setHours(0, 0, 0, 0);
  data.setMonth(data.getMonth() + 1);
  // Comeco a menos de duas semanas do mes seguinte colaria nos dois rotulos.
  if (data.getTime() - inicio >= 14 * DAY_MS || data.getTime() > fim) meses.push(inicio);
  while (data.getTime() <= fim) {
    meses.push(data.getTime());
    data.setMonth(data.getMonth() + 1);
  }
  return meses;
}

// Quem jogava pela equipe em cada semana do ranking, como no grafico da HLTV: os
// jogadores do ultimo mapa ate aquela data. Mapa de uma equipe herdada, ou de um nome
// antigo da mesma line, diz tambem por qual equipe eles jogavam.
function teamLineDaEpoca(team) {
  const herdadas = team.ranking?.inherits || [];
  const fases = teamFases(teamById(team.id) || team, matchSeriesForTeam(team.id)).filter((fase) => !fase.atual);
  const mapas = [team.id, ...herdadas]
    .flatMap((id) => matchSeriesForTeam(id).flatMap((series) => (series.maps || []).map((match) => ({
      quando: dateValue(match.startedAt || series.startedAt),
      teamId: id,
      eventId: series.eventId,
      jogadores: (match.players || []).filter((row) => row.teamId === id).map((row) => ({ id: playerById(row.id)?.id || row.id, nick: playerById(row.id)?.nick || row.name || "Jogador" })),
    }))))
    .filter((mapa) => mapa.quando && mapa.jogadores.length)
    .sort((a, b) => a.quando - b.quando);
  const estilos = new Map();
  return (data) => {
    const limite = dateValue(data) + DAY_MS;
    let ultimo = null;
    for (const mapa of mapas) {
      if (mapa.quando > limite) break;
      ultimo = mapa;
    }
    if (!ultimo) return null;
    const fase = ultimo.teamId === team.id ? fases.find((item) => item.eventos.has(ultimo.eventId)) : null;
    // A equipe como era naquela semana: nome, logo e cores da Camisa.
    const daEpoca = ultimo.teamId !== team.id
      ? teamById(ultimo.teamId) || { id: ultimo.teamId, name: displayTeamName(ultimo.teamId) }
      : fase ? { name: fase.nome, logo: fase.logo, colors: fase.cores, profile: { logo: fase.logo } } : team;
    const chave = daEpoca.id || daEpoca.name;
    if (!estilos.has(chave)) estilos.set(chave, teamPlateStyle(daEpoca));
    const src = assetPath(daEpoca.profile?.logo || daEpoca.logo || "");
    return {
      jogadores: ultimo.jogadores,
      equipe: daEpoca.name || team.name,
      estilo: estilos.get(chave),
      logo: src ? `<span class="team-logo clean-logo vp-rc-logo"><img src="${escapeHtml(src)}" alt="" loading="lazy" onerror="this.closest('.team-logo').remove()" /></span>` : "",
    };
  };
}

function teamRankingChart(history, primeiraPartida = 0, provisorias = [], lineDaEpoca = null) {
  const validas = history
    .slice()
    .sort((a, b) => dateValue(a.date) - dateValue(b.date))
    .filter((row) => Number.isFinite(Number(row.rank)) && Number(row.rank) > 0);
  if (!validas.length) return "";
  // As semanas provisorias entram no desenho e no hover, mas nao nos numeros de cima.
  const rows = [...validas, ...provisorias.map((row) => ({ ...row, rank: row.provisorio }))].sort((a, b) => dateValue(a.date) - dateValue(b.date));
  const width = 760;
  const height = 250;
  const pad = { top: 12, right: 14, bottom: 52, left: 38 };
  const plotWidth = width - pad.left - pad.right;
  const plotHeight = height - pad.top - pad.bottom;
  const teto = rankingTetoGeral(validas);
  // "Todos" e o mesmo eixo para todas as equipes: do primeiro ao ultimo ranking.
  const todos = routeQuery().get("periodo") === "todos";
  const semanas = (state.db?.rankingSnapshots || []).map((foto) => Number(foto.cutoffAt || 0)).filter(Boolean);
  const primeira = dateValue(rows[0].date);
  // "Ativo" comeca na primeira partida, mas nunca antes da primeira semana de ranking:
  // com a Alianca 2023.2 (set/2023) ele ficava mais largo que "Todos" (jul/2024),
  // com dez meses vazios no comeco.
  const primeiraSemana = semanas.length ? Math.min(...semanas) : 0;
  const inicio = todos && semanas.length ? primeiraSemana : Math.max(primeiraPartida ? Math.min(primeiraPartida, primeira) : primeira, primeiraSemana);
  // Equipe com poucas semanas ainda precisa de eixo: um mes de largura, no minimo.
  const fim = todos && semanas.length ? Math.max(...semanas) : Math.max(dateValue(rows[rows.length - 1].date), inicio + 30 * DAY_MS);
  const span = fim - inicio;
  const x = (date) => pad.left + ((dateValue(date) - inicio) / span) * plotWidth;
  const y = (rank) => pad.top + ((clamp(Number(rank), 1, teto) - 1) / (teto - 1)) * plotHeight;
  // Semana inativa interrompe a linha. A provisoria continua, pontilhada, e o trecho
  // que muda de tipo comeca no ultimo ponto do anterior para as duas se tocarem.
  const trechos = rows.reduce((lista, row, indice) => {
    const anterior = rows[indice - 1];
    const seguida = indice && dateValue(row.date) - dateValue(anterior.date) <= 8 * DAY_MS;
    const tipo = row.provisorio ? "provisorio" : "valido";
    if (seguida && lista.at(-1).tipo === tipo) lista.at(-1).pontos.push(row);
    else lista.push({ tipo, pontos: seguida ? [anterior, row] : [row] });
    return lista;
  }, []);
  const pontos = (trecho) => (trecho.length > 1 ? trecho : [trecho[0], trecho[0]]).map((row) => `${fmt(x(row.date), 2)},${fmt(y(row.rank), 2)}`).join(" ");
  const yTicks = rankingChartTicks(teto);
  const latest = validas[validas.length - 1];
  // Equipe que saiu do ranking (inativa, ou sucedida por outra) tem como ultimo
  // ponto uma semana passada; chamar isso de posicao atual seria falso.
  const latestCutoff = Number(latestRankingSnapshot()?.cutoffAt || 0);
  const latestIsCurrent = !latestCutoff || dateValue(latest.date) >= latestCutoff;
  const best = Math.min(...validas.map((row) => Number(row.rank)));
  // Sem bolinha fixa: so a linha. O ponto de cada semana aparece ao passar o mouse.
  // A caixa do grafico tem altura FIXA em px, entao o SVG e esticado
  // (preserveAspectRatio="none"). Por isso so a linha e as reguas moram dentro
  // dele - com `vector-effect` a espessura sobrevive ao esticamento. Rotulo de eixo
  // e area de hover ficam em HTML posicionado por porcentagem.
  // Cada semana e uma coluna que vai ate o meio do caminho para a vizinha: em
  // qualquer altura, o mouse pega a semana mais proxima, e o ponto cai embaixo dele.
  // Eram circulos de 28px sobrepostos, e o ultimo da pilha ganhava, sempre ao lado.
  const colunas = rows.map((row) => (x(row.date) / width) * 100);
  const pointHotspots = rows
    .map((row, indice) => {
      const left = colunas[indice];
      const top = (y(row.rank) / height) * 100;
      const esquerda = indice ? Math.max((colunas[indice - 1] + left) / 2, left - 2) : left - 1;
      const direita = indice < rows.length - 1 ? Math.min((colunas[indice + 1] + left) / 2, left + 2) : left + 1;
      const detail = [`Nota ${row.points === "" ? "-" : fmt(row.points, 1)}`, row.note || ""].filter(Boolean).join(" - ");
      const epoca = lineDaEpoca?.(row.date);
      // Nas pontas o balao centrado sairia da tela: ele tem ate 260px, e num
      // grafico de 328px (celular de 360) so o terco do meio tem 130px livres
      // dos dois lados. Fora dele, o balao cresce para dentro do grafico.
      return `
        <span class="ranking-chart-hotspot${left < 35 ? " na-esquerda" : left > 65 ? " na-direita" : ""}" style="--esq:${fmt(esquerda, 3)};--larg:${fmt(direita - esquerda, 3)};--c:${fmt(((left - esquerda) / (direita - esquerda)) * 100, 2)};--y:${fmt(top, 2)}" tabindex="0" aria-label="${escapeHtml(`${formatDate(row.date)} ${rankingHistoryRankLabel(row.rank)}`)}">
          ${epoca ? `
            <span class="ranking-chart-tooltip vp-rc-balao" style="${escapeHtml(epoca.estilo)}">
              <span class="vp-rc-cabeca">
                <span class="vp-rc-topo"><strong>${escapeHtml(rankingHistoryRankLabel(row.rank))}</strong><span>${escapeHtml(formatDate(row.date))}</span>${row.provisorio ? `<small>Provisório</small>` : ""}</span>
                <span class="vp-rc-nota"><span>Nota ${escapeHtml(row.points === "" ? "-" : fmt(row.points, 1))} -</span>${epoca.logo}<b>${escapeHtml(epoca.equipe)}</b></span>
              </span>
              <span class="vp-rc-line">${epoca.jogadores.map((jogador) => `<span class="vp-rc-jog">${playerLogo(jogador.id, "vp-rc-foto")}<b>${escapeHtml(jogador.nick)}</b></span>`).join("")}</span>
            </span>
          ` : `
            <span class="ranking-chart-tooltip">
              <strong>${escapeHtml(rankingHistoryRankLabel(row.rank))}</strong>
              <span>${escapeHtml(formatDate(row.date))}</span>
              <small>${escapeHtml(detail)}</small>
            </span>
          `}
        </span>
      `;
    })
    .join("");
  return `
    <div class="ranking-chart-card">
      <dl class="ranking-chart-kpis">
        <div><dd>${rankingHistoryRankLabel(latest.rank)}</dd><dt>${latestIsCurrent ? "Posição atual" : "Última posição"}</dt></div>
        <div><dd>#${best}</dd><dt>Melhor</dt></div>
        <div><dd>${validas.length}</dd><dt>${validas.length === 1 ? "Semana válida" : "Semanas válidas"}</dt></div>
      </dl>
      <div class="vp-eq-escolha ranking-chart-periodo" role="group" aria-label="Período">
        <button type="button" data-eq-periodo="" aria-pressed="${!todos}">Ativo</button>
        <button type="button" data-eq-periodo="todos" aria-pressed="${todos}">Todos</button>
      </div>
      <div class="ranking-chart-stage">
        <svg class="ranking-line-chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="${escapeHtml(`Histórico de ranking canônico, escala de #1 a #${teto}`)}">
          <g class="ranking-chart-grid">
            ${yTicks.map((tick) => `<line x1="${pad.left}" x2="${width - pad.right}" y1="${fmt(y(tick), 2)}" y2="${fmt(y(tick), 2)}"></line>`).join("")}
          </g>
          ${trechos.map((trecho) => `<polyline class="ranking-chart-line${trecho.tipo === "provisorio" ? " provisorio" : ""}" points="${pontos(trecho.pontos)}"></polyline>`).join("")}
        </svg>
        <div class="ranking-chart-axis" aria-hidden="true">
          ${yTicks.map((tick) => `<span style="--t:${fmt((y(tick) / height) * 100, 2)}">#${tick}</span>`).join("")}
        </div>
        <div class="ranking-chart-dates vp-meses-verticais" aria-hidden="true">
          ${mesesDoPeriodo(inicio, fim).map((mes) => `<span style="--t:${fmt((x(mes) / width) * 100, 2)}">${escapeHtml(chartDateLabel(mes))}</span>`).join("")}
        </div>
        <div class="ranking-chart-hotspots" style="--n:${rows.length}">${pointHotspots}</div>
      </div>
    </div>
  `;
}

function chartDateLabel(value) {
  const date = new Date(value);
  return date.toLocaleDateString("pt-BR", { month: "short", year: "2-digit" }).replace(".", "");
}

function dateValue(value) {
  const timestamp = value instanceof Date ? value.getTime() : Number(value) || Date.parse(value);
  return Number.isFinite(timestamp) ? timestamp : 0;
}

// Uma tabela por assunto, como a Roster da HLTV: quem esta, a linha do tempo e quem
// passou. Os numeros de cada linha sao do jogador por ESTA equipe, nao da carreira.
function teamRosterTab(team, { matches, currentLineup, historicalPlayers, observedPlayers, quemJogou }) {
  const passagens = teamPassagens(team, matches);
  const linhas = teamLinhaDoTempo(team, passagens);
  const titularidade = teamTitularidade(team, linhas, passagens);
  const semElenco = !currentLineup.length;
  const atuais = new Set(currentLineup.map((entry) => entry.playerId));
  // Parte de quem jogou, e nao do cadastro: jogador com a coluna de equipe vazia
  // na planilha nao tem `teamHistory`, e sumia daqui mesmo com 31 mapas (AZR ice).
  const candidatos = [...new Map([...quemJogou, ...observedPlayers, ...historicalPlayers].map((player) => [player.id, player])).values()]
    .filter((player) => !atuais.has(player.id) && !passagens.standins.has(player.id));
  // Saida mais recente primeiro: a pergunta que a lista responde e "quem acabou
  // de sair". Sem elenco, quem mais jogou vem antes.
  const ex = candidatos
    .map((player) => ({ player, resumo: teamPassagemDoJogador(team, player, passagens) }))
    .sort((a, b) => (semElenco ? b.resumo.mapas - a.resumo.mapas : b.resumo.fim - a.resumo.fim) || a.player.nick.localeCompare(b.player.nick, "pt-BR"));
  const movimentos = teamMovimentos(linhas, passagens);
  return `
    <div class="${movimentos.length ? "vp-equipe-corpo" : "vp-eq-coluna"}">
      <div class="vp-equipe-principal">
        ${semElenco ? "" : `
          <section>
            ${sectionHead("Elenco atual")}
            ${teamElencoTabela(team, currentLineup, passagens)}
          </section>
        `}
        ${titularidade.length ? `
          <section class="vp-s-linha-do-tempo">
            ${sectionHead("Linha do tempo")}
            ${lineupTimelineChart(team, titularidade)}
          </section>
        ` : ""}
        ${ex.length ? `
          <section>
            ${sectionHead(semElenco ? "Jogadores" : "Ex-membros")}
            ${teamPassagensTabela(team, ex)}
          </section>
        ` : ""}
      </div>
      ${movimentos.length ? `
        <aside class="vp-equipe-trilho">
          <section>
            ${sectionHead("Entradas e saídas")}
            <div class="vp-movimentos">${movimentos.map((movimento) => teamMovimentoLinha(movimento, team)).join("")}</div>
          </section>
        </aside>
      ` : ""}
    </div>
  `;
}

// Uma passagem so termina quando o jogador fica de fora por um intervalo grande com
// a equipe jogando sem ele. Mes parado da equipe inteira nao conta, e reserva que
// perde dois mapas tambem nao: 60 dias e 3 mapas separam 150 saidas reais nos dados.
//
// Stand-in nao e parte da equipe, e o filtro olha cada passagem, nao o jogador: o
// Stockao fez 4 e 8 mapas como stand-in e depois 19 e 25 como titular. A passagem
// conta com 10 mapas, ou 40% dos mapas da equipe quando ela jogou pouco, porque em
// equipe de 12 mapas quem jogou 5 estava no time. Quem esta no elenco atual sempre
// conta. Quem nao fica com nenhuma passagem e stand-in: some de Elenco e aparece so
// em Estatisticas, onde os mapas dele continuam contando.
const TEAM_PASSAGEM_DIAS = 60;
const TEAM_PASSAGEM_MAPAS = 3;
const TEAM_PASSAGEM_MINIMA = 10;
const TEAM_PASSAGEM_PARTE = 0.4;
// Ou 75% dos mapas da equipe entre o primeiro e o ultimo mapa da pessoa, com pelo
// menos 3 (regra de 08/11): quem jogou o campeonato inteiro era da equipe.
const TEAM_PASSAGEM_PERIODO_MAPAS = 3;
const TEAM_PASSAGEM_PERIODO_PARTE = 0.75;

// A linha do tempo mostra a titularidade, e por isso 60 dias fora ja abrem um vao.
// Entradas e saidas mostram o elenco: quem ficou 84 dias no banco continuou na equipe.
// So um intervalo de 4 meses, mais que um semestre de campeonatos parado, e saida.
const TEAM_ELENCO_DIAS = 120;

function teamPassagensDeElenco(trechos) {
  return trechos.reduce((juntos, trecho) => {
    const ultimo = juntos.at(-1);
    if (ultimo && trecho.inicio - ultimo.fim < TEAM_ELENCO_DIAS * DAY_MS) {
      juntos[juntos.length - 1] = { ...ultimo, fim: trecho.fim, mapas: ultimo.mapas + trecho.mapas, eventos: new Set([...ultimo.eventos, ...trecho.eventos]) };
    } else {
      juntos.push(trecho);
    }
    return juntos;
  }, []);
}

function teamPassagens(team, matches) {
  const mapas = matches
    .flatMap((series) => (series.maps || []).map((match) => ({ match, eventId: series.eventId, quando: dateValue(match.startedAt || series.startedAt) })))
    .filter((mapa) => mapa.quando)
    .sort((a, b) => a.quando - b.quando);
  const jogadores = new Map();
  mapas.forEach(({ match, eventId, quando }, indice) => {
    (match.players || []).forEach((row) => {
      if (row.teamId !== team.id) return;
      const id = playerById(row.id)?.id || row.id;
      if (!jogadores.has(id)) jogadores.set(id, []);
      const trechos = jogadores.get(id);
      const ultimo = trechos.at(-1);
      const afastou = ultimo && quando - ultimo.fim >= TEAM_PASSAGEM_DIAS * DAY_MS && indice - ultimo.indice - 1 >= TEAM_PASSAGEM_MAPAS;
      if (!ultimo || afastou) trechos.push({ inicio: quando, fim: quando, primeiro: indice, indice, mapas: 0, eventos: new Set() });
      const trecho = trechos.at(-1);
      trecho.fim = quando;
      trecho.indice = indice;
      trecho.mapas += 1;
      if (eventId) trecho.eventos.add(eventId);
    });
  });
  const minimo = Math.min(TEAM_PASSAGEM_MINIMA, Math.ceil(mapas.length * TEAM_PASSAGEM_PARTE));
  const atuais = new Set((team.currentLineup || []).map((entry) => playerById(entry.playerId)?.id || entry.playerId));
  const validas = new Map();
  const totais = new Map();
  const standins = new Set();
  jogadores.forEach((trechos, id) => {
    totais.set(id, trechos.reduce((soma, trecho) => soma + trecho.mapas, 0));
    // Quem jogou quase todos os mapas da equipe no seu periodo era a equipe naquele
    // periodo, mesmo com poucos mapas: o suvas fez os 9 da CEUB no Kickoff e saiu.
    const doPeriodo = (trecho) => trecho.mapas >= TEAM_PASSAGEM_PERIODO_MAPAS && trecho.mapas / (trecho.indice - trecho.primeiro + 1) >= TEAM_PASSAGEM_PERIODO_PARTE;
    const ficam = trechos.filter((trecho, indice) => trecho.mapas >= minimo || doPeriodo(trecho) || (atuais.has(id) && indice === trechos.length - 1));
    if (ficam.length) validas.set(id, ficam);
    else standins.add(id);
  });
  return { jogadores: validas, totais, standins, atuais, minimo, ultimoMapa: mapas.at(-1)?.quando || 0 };
}

function dataCurta(valor) {
  return new Date(dateValue(valor)).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit", year: "2-digit" });
}

function teamTrechoTexto(trecho, atual) {
  return `${dataCurta(trecho.inicio)} - ${atual ? "Atual" : dataCurta(trecho.fim)}`;
}

function teamResumoDosTrechos(trechos, atual, mapas) {
  const dias = trechos.reduce((soma, trecho) => soma + Math.max(DAY_MS, trecho.fim - trecho.inicio), 0);
  return {
    periodos: trechos.map((trecho, indice) => teamTrechoTexto(trecho, atual && indice === trechos.length - 1)),
    duracao: formatTenureDuration(0, dias),
    mapas,
    eventos: new Set(trechos.flatMap((trecho) => [...trecho.eventos])).size,
    fim: trechos.at(-1).fim,
  };
}

// Quem nao aparece em nenhum mapa da equipe cai no registro do elenco.
function teamPassagemDoJogador(team, player, passagens, atual = false) {
  const trechos = passagens.jogadores.get(player.id);
  if (trechos) return teamResumoDosTrechos(teamPassagensDeElenco(trechos), atual, passagens.totais.get(player.id));
  const tenure = playerTeamTenure(team, player);
  return { periodos: [tenure.range], duracao: tenure.duracao || "-", mapas: tenure.mapas || 0, eventos: tenure.eventos.length, fim: tenure.end || 0 };
}

// As linhas do registro de elenco, com os intervalos tirados dos mapas, mais quem
// jogou e nao esta no registro.
function teamLinhaDoTempo(team, passagens) {
  const vistos = new Set();
  const linhas = lineupTimelineRows(team).filter((row) => !passagens.standins.has(row.playerId)).map((row) => {
    const trechos = passagens.jogadores.get(row.playerId);
    vistos.add(row.playerId);
    if (!trechos) return row;
    return { ...row, start: trechos[0].inicio, end: trechos.at(-1).fim, matches: trechos.reduce((soma, trecho) => soma + trecho.mapas, 0), trechos };
  });
  passagens.jogadores.forEach((trechos, id) => {
    if (vistos.has(id)) return;
    const player = playerById(id);
    linhas.push({ key: id, playerId: id, name: player?.nick || "Jogador", handle: player?.handle || "", start: trechos[0].inicio, end: trechos.at(-1).fim, matches: trechos.reduce((soma, trecho) => soma + trecho.mapas, 0), current: passagens.atuais.has(id), trechos });
  });
  return linhas;
}

// A linha do tempo e a titularidade ao longo dos anos: reserva do elenco atual so
// entra com as passagens em que jogou de verdade.
function teamTitularidade(team, linhas, passagens) {
  const reservas = new Set((team.currentLineup || []).filter((entry) => entry.role && entry.role !== "titular").map((entry) => playerById(entry.playerId)?.id || entry.playerId));
  return linhas
    .map((row) => (reservas.has(row.playerId) && row.trechos ? { ...row, trechos: row.trechos.filter((trecho) => trecho.mapas >= passagens.minimo) } : row))
    .filter((row) => !row.trechos || row.trechos.length);
}

// Mesma ordem dos blocos antigos: titulares, formacao recente quando a funcao nao
// foi confirmada, reservas, comissao e o restante do cadastro.
function teamElencoGrupos(team, roster) {
  const destaque = rankingRosterTopFive(team, roster);
  const recente = teamRecentRosterCounts(team).size > 0;
  return [
    [(entry) => entry.role === "titular", "Titular"],
    [(entry) => !entry.role && destaque.includes(entry), recente ? "Formação recente" : "Cadastrado"],
    [(entry) => entry.role === "reserva", "Reserva"],
    [(entry) => entry.role === "comissao", "Comissão"],
    [(entry) => !entry.role && !destaque.includes(entry), "Cadastrado"],
  ].flatMap(([pertence, funcao]) => roster.filter(pertence).map((entry) => ({ entry, funcao })));
}

function teamElencoIdentidade(player, nome, handle) {
  return `<span class="vp-elenco-foto">${player ? playerLogo(player.id) : ""}</span><span class="vp-et-nome"><b>${escapeHtml(nome)}</b>${handle ? `<small>${escapeHtml(handle)}</small>` : ""}</span>`;
}

// O desempenho do jogador pela equipe, somando as passagens dele aqui.
function teamElencoNumeros(player, team) {
  const stats = playerTemPerfil(player) ? playerStatsForTeam(player, team.id) : null;
  const jogou = Boolean(stats?.matches);
  const celula = (rotulo, valor, classe = "") => `<span class="vp-et-n ${classe}" data-rotulo="${rotulo}">${escapeHtml(jogou ? valor(stats) : "-")}</span>`;
  return [
    celula("rAAting", playerRating, jogou ? `vp-et-nota ${playerRatingTone(stats)}` : ""),
    celula("ACS", (row) => fmt(row.acs, 0)),
    celula("K:D", (row) => fmt(row.kd)),
  ].join("");
}

function teamElencoTabela(team, roster, passagens) {
  const linhas = teamElencoGrupos(team, roster).map(({ entry, funcao }) => {
    const player = entry.playerId ? playerById(entry.playerId) : null;
    const comPerfil = playerTemPerfil(player);
    const resumo = comPerfil ? teamPassagemDoJogador(team, player, passagens, true) : null;
    const pool = comPerfil ? teamPlayerAgentPool(team, player) : [];
    const miolo = `
      ${teamElencoIdentidade(player, player?.nick || entry.name || "Jogador", player?.handle || "")}
      <span class="vp-et-c" data-rotulo="Função">${escapeHtml(funcao)}</span>
      <span class="vp-et-n" data-rotulo="Na equipe">${escapeHtml(resumo?.duracao || "-")}</span>
      <span class="vp-et-n" data-rotulo="Mapas">${escapeHtml(String(resumo?.mapas || 0))}</span>
      ${teamElencoNumeros(player, team)}
      <span class="vp-et-agentes" data-rotulo="Agentes">${teamStatsAgentCell(pool)}</span>
    `;
    return comPerfil ? `<a class="vp-et vp-et-atual" href="${playerHref(player)}">${miolo}</a>` : `<span class="vp-et vp-et-atual">${miolo}</span>`;
  });
  return `
    <div class="vp-elenco-tabela">
      <div class="vp-et vp-et-atual vp-et-cab" aria-hidden="true"><span></span><span>Jogador</span><span>Função</span><span>Na equipe</span><span>Mapas</span><span>rAAting</span><span>ACS</span><span>K:D</span><span>Agentes</span></div>
      ${linhas.join("")}
    </div>
  `;
}

function teamPassagensTabela(team, ex) {
  const linhas = ex.map(({ player, resumo }) => `
    <a class="vp-et vp-et-ex" href="${playerHref(player)}">
      ${teamElencoIdentidade(player, player.nick, player.handle)}
      <span class="vp-et-c vp-et-periodos" data-rotulo="Período">${resumo.periodos.map((periodo) => `<span>${escapeHtml(periodo)}</span>`).join("")}</span>
      <span class="vp-et-n" data-rotulo="Na equipe">${escapeHtml(resumo.duracao)}</span>
      <span class="vp-et-n" data-rotulo="Mapas">${escapeHtml(String(resumo.mapas))}</span>
      ${teamElencoNumeros(player, team)}
      <span class="vp-et-n" data-rotulo="Eventos">${resumo.eventos}</span>
    </a>
  `);
  return `
    <div class="vp-elenco-tabela">
      <div class="vp-et vp-et-ex vp-et-cab" aria-hidden="true"><span></span><span>Jogador</span><span>Período</span><span>Na equipe</span><span>Mapas</span><span>rAAting</span><span>ACS</span><span>K:D</span><span>Eventos</span></div>
      ${linhas.join("")}
    </div>
  `;
}

// O equivalente das transferencias da HLTV: quem entrou e saiu do ELENCO, nao quem
// ganhou ou perdeu a vaga de titular.
// Quem estava no primeiro mapa da equipe nao "entrou": ela comecou com essa pessoa.
// Do mesmo jeito, quem jogou ate o ultimo mapa nao "saiu": foi a equipe que parou.
function teamMovimentos(linhas, passagens) {
  if (!linhas.length) return [];
  const comeco = Math.min(...linhas.map((row) => row.start));
  const fim = Math.max(passagens.ultimoMapa, ...linhas.map((row) => row.end));
  const folga = 14 * DAY_MS;
  return linhas
    .flatMap((row) => teamPassagensDeElenco(row.trechos || [{ inicio: row.start, fim: row.end, mapas: 0, eventos: new Set() }]).flatMap((trecho, indice, trechos) => [
      indice ? { tipo: "Voltou", data: trecho.inicio, row } : trecho.inicio - comeco > folga ? { tipo: "Entrou", data: trecho.inicio, row } : null,
      (row.current && indice === trechos.length - 1) || fim - trecho.fim <= folga ? null : { tipo: "Saiu", data: trecho.fim, row },
    ]))
    .filter(Boolean)
    .sort((a, b) => b.data - a.data)
    .slice(0, 12);
}

// A equipe de cada serie do jogador, da mais antiga para a mais recente.
function playerEquipesNoTempo(playerId) {
  const cache = (playerEquipesNoTempo.cache ||= { db: null, porJogador: new Map() });
  if (cache.db !== state.db) Object.assign(cache, { db: state.db, porJogador: new Map() });
  if (!cache.porJogador.has(playerId)) {
    cache.porJogador.set(playerId, matchSeriesForPlayer(playerId)
      .map((series) => ({ quando: dateValue(series.startedAt), teamId: playerSeriesTeamId(series, playerId) }))
      .filter((item) => item.quando && item.teamId)
      .sort((a, b) => a.quando - b.quando));
  }
  return cache.porJogador.get(playerId);
}

// De onde o jogador veio, ou para onde foi: a outra equipe da serie mais proxima do
// outro lado da data, ate um ano. Serie por esta mesma equipe (stand-in antes de
// entrar) e pulada. Sem nenhuma, "Sem equipe".
const TEAM_MOVIMENTO_DIAS = 365;

function teamMovimentoOutraEquipe(teamId, playerId, data, tipo) {
  if (!playerId) return "";
  const series = playerEquipesNoTempo(playerId);
  const lista = tipo === "Saiu" ? series.filter((item) => item.quando > data) : series.filter((item) => item.quando < data).reverse();
  const outra = lista.find((item) => item.teamId !== teamId);
  return outra && Math.abs(outra.quando - data) <= TEAM_MOVIMENTO_DIAS * DAY_MS ? outra.teamId : "";
}

function teamMovimentoLinha({ tipo, data, row }, team) {
  const player = row.playerId ? playerById(row.playerId) : null;
  const outra = teamMovimentoOutraEquipe(team.id, player?.id, data, tipo);
  const nomeOutra = outra ? teamById(outra)?.name || displayTeamName(outra) : "Sem equipe";
  const corpo = `
    <span class="vp-elenco-foto">${player ? playerLogo(player.id) : ""}</span>
    <span class="vp-et-nome"><b>${escapeHtml(row.name)}</b><small>${escapeHtml(formatDate(data, "date"))}</small></span>
    <span class="vp-mov-lado">
      <span class="vp-mov-tipo${tipo === "Saiu" ? "" : " vp-mov-entrou"}">${escapeHtml(tipo === "Saiu" ? "Saiu para" : `${tipo} de`)}</span>
      <span class="vp-mov-equipe${outra ? "" : " vp-mov-sem"}">${outra ? teamLogo(outra) : ""}<span title="${escapeHtml(nomeOutra)}"><span class="nome-rolante">${escapeHtml(nomeOutra)}</span></span></span>
    </span>
  `;
  return playerTemPerfil(player) ? `<a class="vp-movimento" href="${playerHref(player)}">${corpo}</a>` : `<span class="vp-movimento">${corpo}</span>`;
}


// Os campeonatos da equipe: a inscricao, as series e os trofeus herdados de quem
// ela sucedeu, que nao constam na inscricao.
function teamCampeonatos(team, matches, trophies) {
  const ids = new Set([...matches.map((series) => series.eventId), ...trophies.map((trophy) => trophy.event.id)]);
  return visibleTournaments().filter((event) => event.teams.includes(team.id) || ids.has(event.id));
}

// Todo confronto da equipe, como na aba Jogos do campeonato: as series com
// estatisticas e o que so existe na chave (W.O., sem estatisticas, a jogar). As
// series de campeonato oculto continuam aqui: a partida existe, so a pagina dele nao.
function teamJogos(team, tournaments, matches) {
  const eventos = new Map(tournaments.map((event) => [event.id, event]));
  matches.forEach((series) => {
    if (eventos.has(series.eventId)) return;
    const oculto = state.db.tournaments.find((event) => event.id === series.eventId);
    if (oculto) eventos.set(oculto.id, oculto);
  });
  return [...eventos.values()].flatMap((event) => tournamentJogos(event, matchSeriesForEvent(event.id))
    .filter((jogo) => (jogo.series ? seriesHasTeam(jogo.series, team.id) : jogo.equipes.includes(team.id)))
    .map((jogo) => ({ ...jogo, event })));
}

function teamPartidasFiltro() {
  const query = routeQuery();
  return { evento: query.get("evento") || "", rival: query.get("rival") || "", mapa: query.get("mapa") || "", resultado: query.get("resultado") || "" };
}

function teamJogoRival(jogo, team) {
  return jogo.equipes.find((id) => id !== team.id) || "";
}

// Cada filtro ignora a si mesmo na hora de contar a propria faceta, como em Partidas.
function teamJogoPassa(jogo, team, filtro, ignorar = "") {
  if (ignorar !== "evento" && filtro.evento && jogo.event.id !== filtro.evento) return false;
  if (ignorar !== "rival" && filtro.rival && teamJogoRival(jogo, team) !== filtro.rival) return false;
  if (ignorar !== "mapa" && filtro.mapa && !jogo.series?.maps.some((match) => match.mapId === filtro.mapa)) return false;
  if (ignorar !== "resultado" && filtro.resultado === "v" && jogo.vencedor !== team.id) return false;
  if (ignorar !== "resultado" && filtro.resultado === "d" && jogo.perdedor !== team.id) return false;
  return true;
}

// O campeonato mais recente primeiro, e dentro dele a ordem das partidas. Jogo sem
// data, ainda por disputar, sobe junto do campeonato em andamento.
function teamJogosPorCampeonato(jogos) {
  const grupos = new Map();
  jogos.forEach((jogo) => {
    if (!grupos.has(jogo.event.id)) grupos.set(jogo.event.id, { event: jogo.event, jogos: [] });
    grupos.get(jogo.event.id).jogos.push(jogo);
  });
  const peso = (grupo) => (eventIsDone(grupo.event) ? 0 : 1);
  const data = (grupo) => Math.max(0, ...grupo.jogos.map((jogo) => jogo.quando || 0));
  return [...grupos.values()]
    .sort((a, b) => peso(b) - peso(a) || data(b) - data(a))
    .map((grupo) => ({ ...grupo, jogos: grupo.jogos.slice().sort((a, b) => Number(Boolean(a.quando)) - Number(Boolean(b.quando)) || maisRecentePrimeiro(a, b)) }));
}

// Uma linha por serie, como a lista da HLTV: a equipe se repete em todas, entao so o
// adversario, o placar e os mapas aparecem. Cada linha tem 44px, contra 74 da linha
// geral, e a coluna tem os 550px da lista da home.
function teamJogoLinha(team, jogo, kd = "") {
  const rivalId = teamJogoRival(jogo, team);
  const nome = teamById(rivalId)?.name || displayTeamName(rivalId);
  const [nosso, deles] = teamFormaPlacar(team, jogo);
  const decidido = Boolean(jogo.vencedor);
  const venceu = jogo.vencedor === team.id;
  const mapas = jogo.series ? (jogo.series.mapNames || []).filter(Boolean).join(", ") : jogo.match?.status || (decidido ? "Sem estatísticas" : "A jogar");
  // A pagina de uma fase antiga chega com o nome da epoca.
  const nossoNome = team.name || teamById(team.id)?.name || displayTeamName(team.id);
  const corpo = `
    <span class="vp-jl-data">${escapeHtml(jogo.quando ? dataCurta(jogo.quando).slice(0, 5) : "-")}</span>
    <span class="vp-jl-rival vp-jl-nossa">${teamLogo(team.id)}<strong title="${escapeHtml(nossoNome)}"><span class="nome-rolante">${escapeHtml(nossoNome)}</span></strong></span>
    <span class="vp-jl-placar${decidido ? (venceu ? " vp-jl-v" : " vp-jl-d") : ""}"><b>${escapeHtml(nosso)}</b><i>:</i><b>${escapeHtml(deles)}</b></span>
    <span class="vp-jl-rival">${teamLogo(rivalId)}<strong title="${escapeHtml(nome)}"><span class="nome-rolante">${escapeHtml(nome)}</span></strong></span>
    ${kd ? `<span class="vp-jl-kd" title="Abates e mortes">${escapeHtml(kd)}</span>` : ""}
    <span class="vp-jl-mapas" title="${escapeHtml(mapas)}"><span class="nome-rolante">${escapeHtml(mapas)}</span></span>
  `;
  return jogo.series ? `<a class="vp-jl" href="${matchSeriesHref(jogo.series)}">${corpo}</a>` : `<span class="vp-jl">${corpo}</span>`;
}

function teamJogosGrupos(team, grupos, linha = (jogo) => teamJogoLinha(team, jogo)) {
  const visiveis = new Set(visibleTournaments().map((event) => event.id));
  return grupos
    .map((grupo) => {
      const titulo = `${eventLogo(grupo.event, "tiny")}${escapeHtml(grupo.event.name)}`;
      return `
        <section class="vp-jogos-grupo">
          <h3 class="vp-jogos-titulo">${visiveis.has(grupo.event.id) ? `<a href="#/tournaments/${escapeHtml(grupo.event.id)}">${titulo}</a>` : `<span class="vp-jogos-oculto">${titulo}</span>`}<span>${grupo.total} ${grupo.total === 1 ? "série" : "séries"}</span></h3>
          <div class="vp-jl-lista">${grupo.jogos.map(linha).join("")}</div>
        </section>
      `;
    })
    .join("");
}

function teamPartidasNumeros(team, jogos) {
  const vitorias = jogos.filter((jogo) => jogo.vencedor === team.id).length;
  const derrotas = jogos.filter((jogo) => jogo.perdedor === team.id).length;
  const soma = jogos.filter((jogo) => jogo.series).reduce((total, jogo) => {
    const placar = seriesScoreForTeam(jogo.series, team.id);
    total.mapas += placar.mapsFor;
    total.contra += placar.mapsAgainst;
    total.saldo += placar.roundsFor - placar.roundsAgainst;
    return total;
  }, { mapas: 0, contra: 0, saldo: 0 });
  const linhas = [
    ["Séries", `${vitorias}-${derrotas}`],
    ["Aproveitamento", pct(vitorias + derrotas ? (vitorias / (vitorias + derrotas)) * 100 : 0)],
    ["Mapas", `${soma.mapas}-${soma.contra}`],
    ["Saldo de rounds", signed(soma.saldo)],
  ];
  return `<dl class="vp-ficha">${linhas.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${escapeHtml(valor)}</dd></div>`).join("")}</dl>`;
}

function teamOpcoes(valores, escolhido) {
  return valores.map(({ id, nome }) => `<option value="${escapeHtml(id)}"${id === escolhido ? " selected" : ""}>${escapeHtml(nome)}</option>`).join("");
}

function teamPartidasFiltros(team, jogos, filtro) {
  const eventos = [...new Map(jogos.filter((jogo) => teamJogoPassa(jogo, team, filtro, "evento")).map((jogo) => [jogo.event.id, jogo.event])).values()]
    .sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  const rivais = [...new Set(jogos.filter((jogo) => teamJogoPassa(jogo, team, filtro, "rival")).map((jogo) => teamJogoRival(jogo, team)).filter(Boolean))]
    .map((id) => ({ id, nome: teamById(id)?.name || displayTeamName(id) }))
    .sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"));
  const paraResultado = jogos.filter((jogo) => teamJogoPassa(jogo, team, filtro, "resultado"));
  const ativo = filtro.evento || filtro.rival || filtro.mapa || filtro.resultado;
  const botao = (valor, rotulo, quantos) => `<button type="button" data-eq-alterna="resultado" data-valor="${valor}" aria-pressed="${filtro.resultado === valor}">${rotulo} <b>${quantos}</b></button>`;
  return `
    <aside class="vp-resumo" aria-label="Filtros das partidas">
      <section class="vp-resumo-bloco vp-jogos-filtro">
        <h3>Filtros ${ativo ? `<button type="button" class="vp-filtros-limpar" data-eq-limpar>Limpar filtros</button>` : ""}</h3>
        <select data-eq-filtro="evento" aria-label="Filtrar por campeonato"><option value="">Todos os campeonatos</option>${teamOpcoes(eventos.map((event) => ({ id: event.id, nome: event.name })), filtro.evento)}</select>
        <select data-eq-filtro="rival" aria-label="Filtrar por adversário"><option value="">Todos os adversários</option>${teamOpcoes(rivais, filtro.rival)}</select>
        <div class="vp-eq-escolha">
          ${botao("v", "Vitórias", paraResultado.filter((jogo) => jogo.vencedor === team.id).length)}
          ${botao("d", "Derrotas", paraResultado.filter((jogo) => jogo.perdedor === team.id).length)}
        </div>
      </section>
      ${teamPartidasNumeros(team, jogos.filter((jogo) => teamJogoPassa(jogo, team, filtro)))}
    </aside>
  `;
}

function teamPartidasMapas(jogos, filtro) {
  const contagem = new Map();
  jogos.forEach((jogo) => {
    (jogo.series?.mapNames || []).filter(Boolean).forEach((nome) => contagem.set(nome, (contagem.get(nome) || 0) + 1));
  });
  const mapas = barrasDosMapas(contagem, filtro.mapa ? [filtro.mapa] : [], "data-eq-mapa");
  return mapas ? `<aside class="vp-resumo" aria-label="Mapas jogados"><div class="vp-jogos-mapas">${sectionHead("Mapas jogados")}${mapas}</div></aside>` : "<span></span>";
}

const TEAM_MATCH_PAGINA = 20;

// A lista e paginada para nao passar de duas telas, e o campeonato que quebra entre
// paginas repete o titulo.
function jogosNaPagina(visiveis) {
  const ordenados = teamJogosPorCampeonato(visiveis).flatMap((grupo) => grupo.jogos.map((jogo) => ({ jogo, grupo })));
  const query = routeQuery();
  const paginas = Math.max(1, Math.ceil(ordenados.length / TEAM_MATCH_PAGINA));
  const pagina = Math.min(paginas, Math.max(1, Number.parseInt(query.get("pagina") || "1", 10) || 1));
  query.delete("pagina");
  const trecho = ordenados.slice((pagina - 1) * TEAM_MATCH_PAGINA, pagina * TEAM_MATCH_PAGINA);
  return {
    grupos: [...new Map(trecho.map(({ grupo }) => [grupo.event.id, { event: grupo.event, total: grupo.jogos.length, jogos: trecho.filter((linha) => linha.grupo === grupo).map((linha) => linha.jogo) }])).values()],
    paginador: paginacaoDaLista(routePath().slice(2), pagina, paginas, query),
  };
}

// As tres colunas da home e de Partidas: filtros, lista e mapas.
function teamMatchesTab(team, jogos) {
  const filtro = teamPartidasFiltro();
  const visiveis = jogos.filter((jogo) => teamJogoPassa(jogo, team, filtro));
  const { grupos, paginador } = jogosNaPagina(visiveis);
  const contagem = visiveis.length < jogos.length ? `${visiveis.length} de ${jogos.length} séries` : `${jogos.length} ${jogos.length === 1 ? "série" : "séries"}`;
  return `
    <section class="vp-eq-aba vp-eq-partidas vp-jogos">
      ${teamPartidasFiltros(team, jogos, filtro)}
      <div class="vp-jogos-lista">
        ${sectionHead("Partidas", contagem)}
        ${grupos.length ? teamJogosGrupos(team, grupos) : `<div class="empty-state">Nenhuma partida com esses filtros. Tire um filtro para ver mais.</div>`}
        ${paginador}
      </div>
      ${teamPartidasMapas(jogos.filter((jogo) => teamJogoPassa(jogo, team, filtro, "mapa")), filtro)}
    </section>
  `;
}

// Tres estados, na ordem que faz sentido para cada um: o que esta rolando, o que
// vem do mais proximo ao mais distante, e o historico do mais recente ao mais antigo.
const TEAM_TOURNAMENT_GROUPS = [
  { key: "live", title: "Em andamento" },
  { key: "scheduled", title: "Próximos" },
  { key: "done", title: "Finalizados" },
];

function teamCampanhas(team, tournaments, trophies) {
  const ordem = { live: 0, scheduled: 1, done: 2 };
  return tournaments
    .map((event) => {
      const estado = eventStatusClass(event.status);
      const trofeu = trophies.find((trophy) => trophy.event.id === event.id) || null;
      const campaign = teamEventCampaign(trofeu?.originalTeamId || team.id, event);
      return { event, estado: estado in ordem ? estado : "live", trofeu, campaign, colocacao: teamTournamentPlacementBlock(event, campaign), data: dateValue(event.end || event.start) };
    })
    .sort((a, b) => ordem[a.estado] - ordem[b.estado] || (a.estado === "scheduled" ? a.data - b.data : b.data - a.data));
}

function teamCampeonatosFiltro() {
  const query = routeQuery();
  return { colocacao: query.get("colocacao") || "", tier: query.get("tier") || "", ano: query.get("ano") || "" };
}

function teamCampanhaTier(event) {
  return String(event.tier || "").replace(/^tier\s*/i, "").trim().toUpperCase();
}

function teamCampanhaAno(event) {
  const data = dateValue(event.start || event.end);
  return data ? String(new Date(data).getFullYear()) : "";
}

function teamCampanhaPassa(linha, filtro, ignorar = "") {
  const classe = linha.trofeu ? String(Math.floor(linha.trofeu.placement)) : "";
  if (ignorar !== "colocacao" && filtro.colocacao === "mvp") return Boolean(linha.mvp) && teamCampanhaPassa(linha, filtro, "colocacao");
  if (ignorar !== "colocacao" && filtro.colocacao === "podio" && !classe) return false;
  if (ignorar !== "colocacao" && filtro.colocacao && filtro.colocacao !== "podio" && classe !== filtro.colocacao) return false;
  if (ignorar !== "tier" && filtro.tier && teamCampanhaTier(linha.event) !== filtro.tier) return false;
  if (ignorar !== "ano" && filtro.ano && teamCampanhaAno(linha.event) !== filtro.ano) return false;
  return true;
}

// Quem foi melhor pela equipe naquele campeonato. So conta quem jogou pelo menos
// metade dos mapas de quem mais jogou: reserva de um mapa so nao vira destaque.
function teamCampanhaDestaque(teamId, event) {
  const series = matchSeriesForEvent(event.id).filter((item) => seriesHasTeam(item, teamId));
  const jogadores = teamEstJogadores({ id: teamId }, series);
  const maisMapas = Math.max(0, ...jogadores.map((player) => Number(player.matches || 0)));
  return jogadores.find((player) => Number(player.matches || 0) * 2 >= maisMapas) || null;
}

function teamCampanhaLinha(team, { event, trofeu, campaign, colocacao, estado }) {
  const agendado = estado === "scheduled";
  const origem = trofeu && trofeu.originalTeamId !== team.id ? teamById(trofeu.originalTeamId)?.name : "";
  const destaque = agendado ? null : teamCampanhaDestaque(trofeu?.originalTeamId || team.id, event);
  return `
    <a class="vp-cp" href="#/tournaments/${escapeHtml(event.id)}">
      ${eventLogo(event, "vp-cp-logo")}
      <span class="vp-cp-nome"><strong title="${escapeHtml(event.name)}"><span class="nome-rolante">${escapeHtml(event.name)}</span></strong><small>${escapeHtml([eventTimeRange(event), origem ? `Como ${origem}` : ""].filter(Boolean).join(", "))}</small></span>
      <span class="vp-cp-tier" data-rotulo="Tier">${event.tier ? eventTierBadge(event) : ""}</span>
      <span class="vp-cp-lugar" data-rotulo="Colocação"><span class="team-placement-badge ${escapeHtml(colocacao.tom)}"><strong>${escapeHtml(colocacao.valor)}</strong><small>${escapeHtml(colocacao.rotulo)}</small></span>${trofeu ? trophyVisual(trofeu) : ""}</span>
      <span class="vp-cp-destaque" data-rotulo="Destaque">${destaque ? `${playerLogo(destaque.id, "vp-cp-foto")}<span><b>${escapeHtml(destaque.nick)}</b><small>${escapeHtml(playerRating(destaque))} de rAAting</small></span>` : ""}</span>
      <span class="vp-cp-n" data-rotulo="Séries">${agendado ? "-" : `${campaign.seriesWins}-${campaign.seriesLosses}`}</span>
      <span class="vp-cp-n" data-rotulo="Mapas">${agendado ? "-" : `${campaign.mapWins}-${campaign.mapLosses}`}</span>
      <span class="vp-cp-n" data-rotulo="Saldo">${agendado ? "-" : escapeHtml(signed(campaign.roundDiff))}</span>
    </a>
  `;
}

// Os trofeus sao o filtro: cada linha mostra quantos e, ao clicar, deixa so aqueles.
function teamCampeonatosResumo(linhas, filtro) {
  const paraColocacao = linhas.filter((linha) => teamCampanhaPassa(linha, filtro, "colocacao"));
  const quantos = (classe) => paraColocacao.filter((linha) => (classe === "mvp" ? linha.mvp : linha.trofeu && String(Math.floor(linha.trofeu.placement)) === classe)).length;
  const opcoes = [["mvp", "MVP"], ["1", "Campeão"], ["2", "Vice-campeão"], ["3", "3º lugar"]].filter(([classe]) => quantos(classe));
  const tiers = [...new Set(linhas.filter((linha) => teamCampanhaPassa(linha, filtro, "tier")).map((linha) => teamCampanhaTier(linha.event)).filter(Boolean))].sort();
  const anos = [...new Set(linhas.filter((linha) => teamCampanhaPassa(linha, filtro, "ano")).map((linha) => teamCampanhaAno(linha.event)).filter(Boolean))].sort().reverse();
  const ativo = filtro.colocacao || filtro.tier || filtro.ano;
  return `
    <aside class="vp-resumo" aria-label="Filtros dos campeonatos">
      <section class="vp-resumo-bloco vp-jogos-filtro">
        <h3>Filtros ${ativo ? `<button type="button" class="vp-filtros-limpar" data-eq-limpar>Limpar filtros</button>` : ""}</h3>
        ${tiers.length ? `<select data-eq-filtro="tier" aria-label="Filtrar por tier"><option value="">Todos os tiers</option>${teamOpcoes(tiers.map((tier) => ({ id: tier, nome: `Tier ${tier}` })), filtro.tier)}</select>` : ""}
        ${anos.length > 1 ? `<select data-eq-filtro="ano" aria-label="Filtrar por ano"><option value="">Todos os anos</option>${teamOpcoes(anos.map((ano) => ({ id: ano, nome: ano })), filtro.ano)}</select>` : ""}
      </section>
      ${opcoes.length ? `
        <section class="vp-resumo-bloco vp-cp-trofeus">
          <h3>Troféus</h3>
          ${opcoes.map(([classe, rotulo]) => `<button type="button" data-eq-alterna="colocacao" data-valor="${classe}" aria-pressed="${filtro.colocacao === classe}"><span>${escapeHtml(rotulo)}</span><b>${quantos(classe)}</b></button>`).join("")}
        </section>
      ` : ""}
    </aside>
  `;
}

function teamTournamentsTab(team, { tournaments, trophies }) {
  const filtro = teamCampeonatosFiltro();
  const linhas = teamCampanhas(team, tournaments, trophies);
  const visiveis = linhas.filter((linha) => teamCampanhaPassa(linha, filtro));
  const contagem = visiveis.length < linhas.length ? `${visiveis.length} de ${linhas.length} campeonatos` : `${linhas.length} ${linhas.length === 1 ? "campeonato" : "campeonatos"}`;
  const grupos = TEAM_TOURNAMENT_GROUPS.map((grupo) => ({ ...grupo, linhas: visiveis.filter((linha) => linha.estado === grupo.key) })).filter((grupo) => grupo.linhas.length);
  return `
    <section class="vp-eq-aba vp-jogos">
      <div class="vp-jogos-lista">
        ${sectionHead("Campeonatos", contagem)}
        ${grupos.length ? `<div class="vp-cp-cab" aria-hidden="true"><span></span><span>Campeonato</span><span>Tier</span><span>Colocação</span><span>Destaque</span><span>Séries</span><span>Mapas</span><span>Saldo</span></div>` : `<div class="empty-state">Nenhum campeonato com esses filtros. Tire um filtro para ver mais.</div>`}
        ${grupos.map((grupo) => `
          <section class="vp-jogos-grupo">
            <h3 class="vp-jogos-titulo">${escapeHtml(grupo.title)}<span>${grupo.linhas.length}</span></h3>
            <div class="vp-cp-lista">${grupo.linhas.map((linha) => teamCampanhaLinha(team, linha)).join("")}</div>
          </section>
        `).join("")}
      </div>
      ${teamCampeonatosResumo(linhas, filtro)}
    </section>
  `;
}

function teamTournamentPlacementBlock(event, campaign) {
  const estado = eventStatusClass(event.status);
  if (estado === "scheduled") {
    return { valor: "A começar", rotulo: teamTournamentCountdown(event), tom: "scheduled" };
  }
  if (campaign.placementStatus === "qualified") {
    return { valor: "Classificado", rotulo: campaign.placementNote || "Avançou de fase", tom: "qualified" };
  }
  if (campaign.placementStatus === "defined") {
    // Ouro so para 1o cravado. "1o-4o lugar" tem placement 1 e ganhava a mesma
    // cor de titulo que uma final vencida - a faixa e um resultado bom, nao um
    // titulo, e a cor nao pode dizer que foi.
    const faixa = /\d+º\s*-\s*\d+º/.test(campaign.placementLabel || "");
    return {
      valor: campaign.placementLabel,
      rotulo: `de ${campaign.size || event.teams.length} equipes`,
      tom: !faixa && campaign.placement && campaign.placement <= 3 ? `podium p${campaign.placement}` : "defined",
    };
  }
  if (estado === "done") {
    // Sem linha de colocacao na fonte. Em vez de "Colocação não informada", a
    // campanha em series - que e dado medido e nao um vazio disfarcado.
    return { valor: `${campaign.seriesWins}-${campaign.seriesLosses}`, rotulo: "Campanha em séries", tom: "unknown" };
  }
  return { valor: "Em disputa", rotulo: campaign.placementNote || `${campaign.seriesWins}-${campaign.seriesLosses} até aqui`, tom: "ongoing" };
}

function teamTournamentCountdown(event) {
  const inicio = dateValue(event.start);
  if (!inicio) return "Data a definir";
  const dias = Math.ceil((inicio - Date.now()) / DAY_MS);
  if (dias <= 0) return "Começa hoje";
  if (dias === 1) return "Começa amanhã";
  return `Em ${dias} dias`;
}

function teamEventCampaign(teamId, event) {
  const eventSeries = matchSeriesForEvent(event.id);
  const standings = eventStandings(eventSeries);
  const achievement = teamById(teamId)?.ranking?.achievements?.find((row) => row.eventId === event.id);
  const placementResult = teamEventPlacementResult(teamId, event, achievement);
  const teamSeries = eventSeries.filter((series) => seriesHasTeam(series, teamId));
  const campaign = teamSeries.reduce(
    (total, series) => {
      const score = seriesScoreForTeam(series, teamId);
      const won = series.winnerId === teamId || score.mapsFor > score.mapsAgainst;
      total.seriesWins += won ? 1 : 0;
      total.seriesLosses += won ? 0 : 1;
      total.mapWins += score.mapsFor;
      total.mapLosses += score.mapsAgainst;
      total.roundDiff += score.roundsFor - score.roundsAgainst;
      return total;
    },
    { seriesWins: 0, seriesLosses: 0, mapWins: 0, mapLosses: 0, roundDiff: 0 },
  );
  return {
    ...campaign,
    placement: placementResult.placement,
    placementLabel: placementResult.placementLabel,
    placementStatus: placementResult.placementStatus,
    placementNote: placementResult.placementNote || "",
    size: achievement?.size || standings.length || event.teams.length,
  };
}

function eventStandings(eventSeries) {
  const rows = new Map();
  const ensure = (team) => {
    if (!rows.has(team.id)) rows.set(team.id, { id: team.id, seriesWins: 0, seriesLosses: 0, mapWins: 0, mapLosses: 0, roundDiff: 0 });
    return rows.get(team.id);
  };
  for (const series of eventSeries) {
    if (!series.teamA?.id || !series.teamB?.id) continue;
    const a = ensure(series.teamA);
    const b = ensure(series.teamB);
    const scoreA = seriesScoreForTeam(series, series.teamA.id);
    const scoreB = seriesScoreForTeam(series, series.teamB.id);
    const aWon = series.winnerId === series.teamA.id || scoreA.mapsFor > scoreA.mapsAgainst;
    a.seriesWins += aWon ? 1 : 0;
    a.seriesLosses += aWon ? 0 : 1;
    b.seriesWins += aWon ? 0 : 1;
    b.seriesLosses += aWon ? 1 : 0;
    a.mapWins += scoreA.mapsFor;
    a.mapLosses += scoreA.mapsAgainst;
    b.mapWins += scoreB.mapsFor;
    b.mapLosses += scoreB.mapsAgainst;
    a.roundDiff += scoreA.roundsFor - scoreA.roundsAgainst;
    b.roundDiff += scoreB.roundsFor - scoreB.roundsAgainst;
  }
  return [...rows.values()].sort((a, b) => b.seriesWins - a.seriesWins || b.mapWins - a.mapWins || b.roundDiff - a.roundDiff || a.seriesLosses - b.seriesLosses || a.id.localeCompare(b.id));
}

function seriesScoreForTeam(series, teamId) {
  const isA = series.teamA.id === teamId;
  const isB = series.teamB.id === teamId;
  if (!isA && !isB) return { mapsFor: 0, mapsAgainst: 0, roundsFor: 0, roundsAgainst: 0 };
  return {
    mapsFor: isA ? Number(series.statisticalScoreA ?? series.scoreA ?? 0) : Number(series.statisticalScoreB ?? series.scoreB ?? 0),
    mapsAgainst: isA ? Number(series.statisticalScoreB ?? series.scoreB ?? 0) : Number(series.statisticalScoreA ?? series.scoreA ?? 0),
    roundsFor: isA ? Number(series.roundScoreA || 0) : Number(series.roundScoreB || 0),
    roundsAgainst: isA ? Number(series.roundScoreB || 0) : Number(series.roundScoreA || 0),
  };
}

// O pool de agentes que o jogador usou COM ESTA equipe, contado mapa a mapa.
// `player.agentStats` existe mas e global: um jogador que passou por duas
// equipes traria aqui os agentes da outra.
function teamPlayerAgentPool(team, player, limite = 3) {
  const contagem = new Map();
  let total = 0;
  for (const series of matchSeriesForPlayer(player.id)) {
    for (const match of series.maps || []) {
      const linha = (match.players || []).find((row) => row.id === player.id && row.teamId === team.id);
      if (!linha?.agent) continue;
      total += 1;
      const chave = linha.agentSlug || linha.agent;
      const atual = contagem.get(chave) || { agent: linha.agent, agentSlug: linha.agentSlug, agentIcon: linha.agentIcon, agentClass: linha.agentClass, picks: 0 };
      atual.picks += 1;
      contagem.set(chave, atual);
    }
  }
  return [...contagem.values()]
    .sort((a, b) => b.picks - a.picks || a.agent.localeCompare(b.agent, "pt-BR"))
    .slice(0, limite)
    .map((linha) => ({ ...linha, rate: total ? (linha.picks / total) * 100 : 0 }));
}

// Com os filtros vinculados vale o de cima para todos os blocos. Desvinculados
// (`?separado=1`), cada bloco le os seus, com prefixo: `jog-evento`, `map-de`...
const TEAM_EST_BLOCOS = ["jog", "map", "ag", "comp", "conf"];

function teamEstFiltro(prefixo = "") {
  const query = routeQuery();
  const valor = (chave) => query.get(`${prefixo}${chave}`) || "";
  return { evento: valor("evento"), de: valor("de"), ate: valor("ate"), rounds: Number.parseInt(valor("rounds") || "0", 10) || 0 };
}

function teamEstSeparado() {
  return routeQuery().get("separado") === "1";
}

function teamEstSeries(matches, filtro) {
  const inicio = filtro.de ? dateValue(dateInputToStart(filtro.de)) : 0;
  const fim = filtro.ate ? dateValue(dateInputToStart(filtro.ate)) + DAY_MS : Infinity;
  return matches.filter((series) => {
    const quando = dateValue(series.startedAt);
    return (!filtro.evento || series.eventId === filtro.evento) && quando >= inicio && quando < fim;
  });
}

// So as linhas da equipe em cada mapa: quem jogou pelos dois lados de um confronto
// em epocas diferentes nao soma os numeros da outra equipe.
function teamEstJogadores(team, series) {
  const mapas = tournamentStatMapMatches(series).map((match) => ({ ...match, players: match.players.filter((player) => player.teamId === team.id) }));
  return aggregateMatchPlayers(mapas).filter((player) => Number(player.rounds || 0) > 0).sort(tournamentPlayerStatSort);
}

// Ataque e defesa da equipe nao somam 100, entao aqui nao cabe a faixa dividida do
// campeonato: cada lado tem a propria coluna, como na tabela de mapas do VLR.
function teamEstMapas(team, series) {
  return tournamentFilterMapOptions(series)
    .map((opcao) => {
      const mapa = mapById(opcao.id) || mapByName(opcao.name) || { id: opcao.id, name: opcao.name };
      const partidas = tournamentFilteredMapMatches(series, opcao.id);
      return { mapa, soma: somaDoMapa(series, opcao.id, team.id), composicoes: tournamentCompositionRows(partidas, team.id) };
    })
    .filter((linha) => linha.soma.mapas)
    .sort((a, b) => b.soma.mapas - a.soma.mapas || taxaInteira(b.soma.vitorias, b.soma.mapas) - taxaInteira(a.soma.vitorias, a.soma.mapas));
}

// A faixa do campeonato com os numeros da equipe. Aqui ataque e defesa nao somam 100,
// entao a emenda fica na proporcao entre os dois, como no cartao do mapa.
function teamMapaFaixa({ mapa, soma }, indice, atual) {
  const ataque = taxaInteira(soma.attackWins, soma.attackRounds);
  const defesa = taxaInteira(soma.defenseWins, soma.defenseRounds);
  const emenda = ataque + defesa ? Math.round((ataque / (ataque + defesa)) * 100) : 50;
  const arte = tournamentMapasArte(mapa);
  return `
    <button type="button" class="vp-ml" data-mapa-linha="${indice}" data-mapa-id="${escapeHtml(mapa.id)}" aria-pressed="${indice === atual}">
      <span class="vp-ml-faixa" style="--ataque:${emenda}">
        <span class="vp-mapa-peca vp-mapa-atk">${arte}</span>
        <span class="vp-mapa-peca vp-mapa-def">${arte}</span>
        <strong>${escapeHtml(mapa.name)}</strong>
        <b class="vp-ml-a">${ataque}%</b>
        <b class="vp-ml-d">${defesa}%</b>
      </span>
      <span class="vp-ml-num" data-rotulo="Mapas">${soma.mapas}</span>
      <span class="vp-ml-num" data-rotulo="V-D">${soma.vitorias}-${soma.derrotas}</span>
      <span class="vp-ml-num" data-rotulo="Vitórias">${taxaInteira(soma.vitorias, soma.mapas)}%</span>
    </button>
  `;
}

// Mesmo calculo de Agentes por mapa do campeonato, mas cada mapa tem uma escolha so,
// a da equipe ou a do jogador: la sao duas, e a taxa aqui sairia pela metade.
function agentesPorMapa(mapas) {
  const rows = tournamentMapAnalyticsRows({}, mapas).map((row) => ({
    ...row,
    mapa: mapById(row.id) || { id: row.id, name: row.name, icon: row.icon },
    pickOpportunities: row.matches,
    agentRates: new Map([...row.agents.entries()].map(([key, agent]) => [key, { ...agent, rate: pctValue(agent.picks, row.matches) }])),
  }));
  return rows.length ? tournamentMapAgentPickrateTable(rows, tournamentMapAgentColumns(rows)) : "";
}

function teamAgentesPorMapa(team, series) {
  return agentesPorMapa(tournamentStatMapMatches(series).map((match) => ({ ...match, players: match.players.filter((player) => player.teamId === team.id) })));
}

function teamEstBlocoVazio(titulo, antes, vazio) {
  return antes ? `<section class="vp-eq-bloco vp-est"><div class="vp-est-lista"><article class="vp-est-bloco"><h3>${escapeHtml(titulo)}</h3>${antes}<p class="vp-est-vazio">${escapeHtml(vazio)}</p></article></div></section>` : "";
}

function teamMapasBloco(team, series, antes = "", vazio = "") {
  const linhas = teamEstMapas(team, series);
  if (!linhas.length) return teamEstBlocoVazio("Mapas", antes, vazio);
  const atual = Math.max(0, linhas.findIndex((linha) => linha.mapa.id === state.tournamentMapaLinha));
  return `
    <section class="vp-eq-bloco vp-est vp-mapas">
      <div class="vp-est-lista">
        <article class="vp-est-bloco">
          <h3>Mapas</h3>
          ${antes}
          <div class="vp-ml-corpo">
            <div class="vp-ml-cab" aria-hidden="true"><span><span>Ataque</span><span>Defesa</span></span><span>Mapas</span><span>V-D</span><span>Vitórias</span></div>
            <div class="vp-ml-lista">${linhas.map((linha, indice) => teamMapaFaixa(linha, indice, atual)).join("")}</div>
          </div>
        </article>
      </div>
      <aside class="vp-resumo" aria-label="Dados do mapa">
        <div class="vp-est-cartas">
          <div class="vp-est-trilho" style="--atual:${atual}">
            ${linhas.map((linha, indice) => mapaCamisa(linha.mapa, linha.soma, team, "Neste filtro", indice === atual ? "" : " inert")).join("")}
          </div>
        </div>
      </aside>
      ${teamAgentesPorMapa(team, series)}
    </section>
  `;
}

function teamAgentesBloco(team, series, seriesComp = series, linhas = null, vazio = "") {
  const ativoId = routeQuery().get("agente") || "";
  const mapas = tournamentStatMapMatches(series);
  const mapasComp = tournamentStatMapMatches(seriesComp);
  // No campeonato o Win% tira os mapas com o mesmo agente nos dois lados, porque um
  // dos lados sempre ganha. Aqui so uma equipe conta: valem todos os mapas dela.
  const agentes = tournamentAgentRows(mapas, team.id).map((row) => ({ ...row, nonMirroredPicks: row.picks, nonMirroredWins: row.mapWins, nonMirroredLosses: row.mapLosses, winRateNM: pctValue(row.mapWins, row.picks) }));
  if (!agentes.length && !linhas) return "";
  const todas = tournamentCompositionRows(mapasComp, team.id);
  const ativo = agentes.find((row) => row.id === ativoId) || null;
  const composicoes = ativo ? todas.filter((row) => row.agents.some((agent) => (agent.slug || agent.name) === ativo.id)) : todas;
  return `
    <section class="vp-eq-bloco vp-est vp-ag-aba">
      <div class="vp-est-lista">
        ${tournamentEstTabela(null, { table: "agents", titulo: "Agentes", antes: linhas?.ag || "", vazio, rows: agentes, columns: tournamentAgenteColunas(ativo?.id), fallback: tournamentAgentStatSort, chave: "pagina-agentes", porPagina: 10, detalhe: true })}
        ${tournamentEstTabela(null, { table: "compositions", titulo: "Composições", descricao: ativo ? `Só as que usaram ${ativo.name}` : "", antes: linhas?.comp || "", vazio, rows: composicoes, columns: tournamentComposicaoColunas(), fallback: tournamentCompositionStatSort, chave: "pagina-comps", porPagina: 10, detalhe: true })}
      </div>
      ${agentes.length ? tournamentAgenteResumo(ativo || agentes[0], Boolean(ativo), todas) : ""}
    </section>
  `;
}

function teamConfrontos(team, series) {
  const rivais = new Map();
  series.forEach((item) => {
    const rival = item.teamA.id === team.id ? item.teamB : item.teamA;
    if (!rivais.has(rival.id)) rivais.set(rival.id, { id: rival.id, nome: rival.name, vitorias: 0, derrotas: 0, mapas: 0, contra: 0, saldo: 0 });
    const linha = rivais.get(rival.id);
    const placar = seriesScoreForTeam(item, team.id);
    linha[teamGanhouSerie(item, team.id) ? "vitorias" : "derrotas"] += 1;
    linha.mapas += placar.mapsFor;
    linha.contra += placar.mapsAgainst;
    linha.saldo += placar.roundsFor - placar.roundsAgainst;
  });
  return [...rivais.values()].sort((a, b) => b.vitorias + b.derrotas - (a.vitorias + a.derrotas) || b.vitorias - a.vitorias || a.nome.localeCompare(b.nome, "pt-BR"));
}

// O resumo dos confrontos: quem a equipe mais enfrentou e os extremos com pelo menos
// 3 series, para um jogo so nao virar "melhor retrospecto".
function teamConfrontosResumo(linhas) {
  const jogos = (linha) => linha.vitorias + linha.derrotas;
  const taxa = (linha) => linha.vitorias / jogos(linha);
  const com3 = linhas.filter((linha) => jogos(linha) >= 3).sort((a, b) => taxa(b) - taxa(a) || jogos(b) - jogos(a));
  const texto = (linha) => `${linha.nome}, ${linha.vitorias}-${linha.derrotas}`;
  const itens = [
    ["Mais enfrentado", texto(linhas[0])],
    com3.length ? ["Melhor retrospecto", texto(com3[0])] : null,
    com3.length > 1 ? ["Pior retrospecto", texto(com3.at(-1))] : null,
  ].filter(Boolean);
  return `<aside class="vp-resumo" aria-label="Resumo dos confrontos"><dl class="vp-ficha vp-eq-confronto">${itens.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${escapeHtml(valor)}</dd></div>`).join("")}</dl></aside>`;
}

function teamConfrontosTabela(team, linhas, antes = "", vazio = "") {
  if (!linhas.length) return teamEstBlocoVazio("Confrontos", antes, vazio);
  const { linhas: pagina, paginador } = tournamentEstPagina(null, linhas, "pagina-rivais", 10);
  const numero = (valor) => `<td class="numeric">${escapeHtml(valor)}</td>`;
  return `
    <section class="vp-eq-bloco vp-est">
      <div class="vp-est-lista">
        <article class="vp-est-bloco">
          <h3>Confrontos<span>${linhas.length} ${linhas.length === 1 ? "adversário" : "adversários"}</span></h3>
          ${antes}
          ${tabelaComRotulos(`<div class="table-wrap tournament-stats-table-wrap">
            <table class="tournament-stats-table">
              <thead><tr><th>Adversário</th><th class="numeric">Séries</th><th class="numeric">V-D</th><th class="numeric">Win%</th><th class="numeric">Mapas</th><th class="numeric">Saldo</th></tr></thead>
              <tbody>
                ${pagina.map((linha) => `
                  <tr>
                    <td><a class="tournament-stats-team-cell" href="#/teams/${escapeHtml(team.id)}/matches?rival=${encodeURIComponent(linha.id)}">${teamLogo(linha.id, "tournament-stat-logo")}<span><strong>${escapeHtml(linha.nome)}</strong></span></a></td>
                    ${numero(String(linha.vitorias + linha.derrotas))}
                    ${numero(`${linha.vitorias}-${linha.derrotas}`)}
                    ${numero(`${taxaInteira(linha.vitorias, linha.vitorias + linha.derrotas)}%`)}
                    ${numero(`${linha.mapas}-${linha.contra}`)}
                    ${numero(signed(linha.saldo))}
                  </tr>
                `).join("")}
              </tbody>
            </table>
          </div>`)}
          ${paginador}
        </article>
      </div>
      ${linhas.length ? teamConfrontosResumo(linhas) : ""}
    </section>
  `;
}

function teamEstFiltros(matches, filtro, { maximo = 0, minimo = 0, prefixo = "", vincular = null } = {}) {
  const eventos = [...new Set(matches.map((series) => series.eventId))]
    .map((id) => state.db.tournaments.find((event) => event.id === id))
    .filter(Boolean)
    .sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  const ativo = filtro.evento || filtro.de || filtro.ate || filtro.rounds;
  const chave = (nome) => `${prefixo}${nome}`;
  const limpar = prefixo ? `<button type="button" class="vp-filtros-limpar" data-eq-limpar-bloco="${prefixo}">Limpar filtros</button>` : `<button type="button" class="vp-filtros-limpar" data-eq-limpar>Limpar filtros</button>`;
  const campos = vincular === false ? "" : `
      <select data-eq-filtro="${chave("evento")}" aria-label="Filtrar por campeonato"><option value="">Todos os campeonatos</option>${teamOpcoes(eventos.map((event) => ({ id: event.id, nome: event.name })), filtro.evento)}</select>
      <label class="vp-eq-data"><span>De</span><input type="date" data-eq-filtro="${chave("de")}" value="${escapeHtml(filtro.de)}"></label>
      <label class="vp-eq-data"><span>Até</span><input type="date" data-eq-filtro="${chave("ate")}" value="${escapeHtml(filtro.ate)}"></label>
      ${maximo ? `
        <label class="vp-est-rounds" style="--cheio:${(minimo / maximo) * 100}%">
          <span>Rounds mínimos</span>
          <input type="range" min="0" max="${maximo}" step="1" value="${minimo}" data-eq-filtro="${chave("rounds")}" data-eq-rounds>
          <b data-est-rounds-valor>${minimo}</b>
        </label>
      ` : ""}
      ${ativo ? limpar : ""}
  `;
  const chaveGeral = vincular === null ? "" : `<label class="vp-eq-vincular"><input type="checkbox" data-eq-vincular${vincular ? " checked" : ""}><span>Vincular filtros</span></label>`;
  return `<div class="vp-est-filtros${prefixo ? " vp-est-filtros-bloco" : ""}">${campos}${chaveGeral}</div>`;
}

// Os mesmos blocos das abas Estatisticas, Mapas e Agentes do campeonato, em sequencia
// e sob o mesmo filtro: lista de 922px e, ao lado, o cartao de quem esta em destaque.
// A tabela de jogadores e a do campeonato, sem a coluna de equipe.
function teamStatsTab(team, matches) {
  const separado = teamEstSeparado();
  const geral = teamEstFiltro();
  // Cada bloco com o seu filtro e as suas series; vinculados, todos usam o de cima.
  const blocos = Object.fromEntries(TEAM_EST_BLOCOS.map((bloco) => {
    const filtro = separado ? teamEstFiltro(`${bloco}-`) : geral;
    return [bloco, { filtro, series: teamEstSeries(matches, filtro), prefixo: `${bloco}-` }];
  }));
  const linha = (bloco, extra = {}) => (separado ? teamEstFiltros(matches, blocos[bloco].filtro, { ...extra, prefixo: blocos[bloco].prefixo }) : "");
  const todos = teamEstJogadores(team, blocos.jog.series);
  // Como no campeonato: o minimo acompanha o teto para a lista nunca zerar.
  const maximo = todos.reduce((maior, player) => Math.max(maior, Number(player.rounds || 0)), 0);
  const minimo = Math.min(blocos.jog.filtro.rounds, maximo);
  const jogadores = todos.filter((player) => Number(player.rounds || 0) >= minimo);
  const colunas = tournamentPlayerStatColumns().map((coluna) => (coluna.key === "player" ? { ...coluna, celula: teamEstCelulaJogador } : coluna));
  const series = blocos.jog.series;
  const contagem = separado ? `${matches.length} ${matches.length === 1 ? "série" : "séries"}` : `${series.length} de ${matches.length} ${matches.length === 1 ? "série" : "séries"}`;
  const vazio = "Nenhuma partida com esses filtros.";
  return `
    <div class="vp-eq-coluna vp-eq-est">
      <div>
        ${sectionHead("Estatísticas", contagem)}
        ${separado ? teamEstFiltros(matches, geral, { vincular: false }) : teamEstFiltros(matches, geral, { maximo, minimo, vincular: true })}
      </div>
      ${separado || series.length ? "" : `<div class="empty-state">Nenhuma partida com esses filtros. Tire um filtro para ver mais.</div>`}
      ${jogadores.length || separado ? `
        <section class="vp-eq-bloco vp-est">
          <div class="vp-est-lista">
            ${tournamentEstTabela(null, { table: "players", titulo: "Jogadores", antes: linha("jog", { maximo, minimo }), vazio, rows: jogadores, columns: colunas, fallback: tournamentPlayerStatSort, chave: "pagina", porPagina: 10, detalhe: true })}
          </div>
          ${jogadores.length ? tournamentEstLideres(jogadores, "Líderes da equipe") : ""}
        </section>
      ` : ""}
      ${teamMapasBloco(team, blocos.map.series, linha("map"), vazio)}
      ${teamAgentesBloco(team, blocos.ag.series, blocos.comp.series, separado ? { ag: linha("ag"), comp: linha("comp") } : null, vazio)}
      ${teamConfrontosTabela(team, teamConfrontos(team, blocos.conf.series), linha("conf"), vazio)}
    </div>
  `;
}

function teamEstCelulaJogador(player) {
  return `<td><a class="tournament-stats-player-cell" href="${playerHref(player)}">${playerLogo(player.id, "tournament-stat-avatar")}<span><strong>${escapeHtml(player.nick || player.handle || "Jogador")}</strong><small>${escapeHtml(player.handle || "")}</small></span></a></td>`;
}

// Clicar numa categoria ou num mapa desliza o cartao do proprio bloco.
function teamDeslizaCartao(bloco, indice, botoes, atual) {
  bloco.querySelector(".vp-est-trilho").style.setProperty("--atual", indice);
  bloco.querySelectorAll(".vp-est-trilho > *").forEach((cartao, posicao) => {
    cartao.inert = posicao !== indice;
  });
  bloco.querySelectorAll(botoes).forEach((botao) => botao.setAttribute("aria-pressed", String(botao === atual)));
}

// Um ouvinte so para as abas da equipe e do jogador. O filtro mora na URL, e trocar um
// filtro volta a lista para o comeco.
function bindAbaDaEquipe(id, refaz = renderTeamDetail) {
  bindTrofeusDaCapa();
  const pagina = document.querySelector(".team-tab-panel");
  if (!pagina) return;
  pagina.querySelectorAll(".vp-resumo").forEach((resumo) => resumo.style.setProperty("--resumo-altura", `${resumo.offsetHeight}px`));
  const aplica = (mudanca, foco) => {
    const query = routeQuery();
    mudanca(query);
    ["pagina", "pagina-rivais", "pagina-agentes", "pagina-comps", "pagina-mapas"].forEach((chave) => query.delete(chave));
    pushFilterState(routePath().slice(2), query, foco);
  };
  const alterna = (chave, valor, foco) => aplica((query) => {
    if (query.get(chave) === valor) query.delete(chave);
    else query.set(chave, valor);
  }, foco);
  pagina.querySelectorAll("[data-eq-filtro]").forEach((campo) => {
    campo.addEventListener("change", () => {
      const chave = campo.dataset.eqFiltro;
      aplica((query) => {
        if (campo.value && campo.value !== "0") query.set(chave, campo.value);
        else query.delete(chave);
      }, `[data-eq-filtro="${chave}"]`);
    });
  });
  // O numero ao lado da barra acompanha o arraste; a lista so refaz ao soltar.
  pagina.querySelectorAll("[data-eq-rounds]").forEach((barra) => barra.addEventListener("input", (event) => {
    const { value, max } = event.target;
    event.target.parentElement.style.setProperty("--cheio", `${Number(max) ? (Number(value) / Number(max)) * 100 : 0}%`);
    event.target.parentElement.querySelector("[data-est-rounds-valor]").textContent = value;
  }));
  // Desvincular comeca cada bloco com o filtro que estava valendo; vincular de novo
  // volta ao filtro de cima e apaga os dos blocos.
  pagina.querySelector("[data-eq-vincular]")?.addEventListener("change", (event) => aplica((query) => {
    const chaves = ["evento", "de", "ate", "rounds"];
    if (event.target.checked) {
      query.delete("separado");
      TEAM_EST_BLOCOS.forEach((bloco) => chaves.forEach((chave) => query.delete(`${bloco}-${chave}`)));
      return;
    }
    query.set("separado", "1");
    TEAM_EST_BLOCOS.forEach((bloco) => chaves.forEach((chave) => {
      if (query.get(chave) && (chave !== "rounds" || bloco === "jog")) query.set(`${bloco}-${chave}`, query.get(chave));
    }));
    chaves.forEach((chave) => query.delete(chave));
  }, "[data-eq-vincular]"));
  pagina.addEventListener("click", (event) => {
    const mapa = event.target.closest("[data-eq-mapa]");
    if (mapa) return alterna("mapa", mapa.dataset.eqMapa, `[data-eq-mapa="${mapa.dataset.eqMapa}"]`);
    const escolha = event.target.closest("[data-eq-alterna]");
    if (escolha) return alterna(escolha.dataset.eqAlterna, escolha.dataset.valor, `[data-eq-alterna="${escolha.dataset.eqAlterna}"][data-valor="${escolha.dataset.valor}"]`);
    const periodo = event.target.closest("[data-eq-periodo]");
    if (periodo) {
      const query = routeQuery();
      if (periodo.dataset.eqPeriodo) query.set("periodo", periodo.dataset.eqPeriodo);
      else query.delete("periodo");
      return pushFilterState(routePath().slice(2), query, `[data-eq-periodo="${periodo.dataset.eqPeriodo}"]`);
    }
    const limparBloco = event.target.closest("[data-eq-limpar-bloco]");
    if (limparBloco) {
      const prefixo = limparBloco.dataset.eqLimparBloco;
      return aplica((query) => ["evento", "de", "ate", "rounds"].forEach((chave) => query.delete(`${prefixo}${chave}`)), `[data-eq-filtro="${prefixo}evento"]`);
    }
    if (event.target.closest("[data-eq-limpar]")) {
      return aplica((query) => ["evento", "rival", "equipe", "mapa", "resultado", "colocacao", "tier", "ano", "de", "ate", "agente", "rounds"].forEach((chave) => query.delete(chave)), "[data-eq-filtro]");
    }
    const ordenar = event.target.closest("[data-tournament-stat-sort]");
    if (ordenar) {
      const [table, key] = String(ordenar.dataset.tournamentStatSort || "").split(":");
      const colunas = table === "agents" ? tournamentAgenteColunas() : table === "compositions" ? tournamentComposicaoColunas() : table === "maps" ? playerMapaColunas() : tournamentPlayerStatColumns();
      const column = colunas.find((item) => item.key === key);
      if (!column) return;
      const atual = tournamentStatsSortState(table);
      const direction = atual.key === key ? (atual.direction === "desc" ? "asc" : "desc") : column.direction || "desc";
      state.tournamentStatsSort = { ...state.tournamentStatsSort, [table]: { key, direction } };
      refaz(id);
      return;
    }
    // Trocar de agente mantem a pagina da lista de agentes: so as composicoes mudam.
    const agente = event.target.closest("[data-agente]");
    if (agente) {
      const query = routeQuery();
      if (agente.getAttribute("aria-pressed") === "true") query.delete("agente");
      else query.set("agente", agente.dataset.agente);
      query.delete("pagina-comps");
      pushFilterState(routePath().slice(2), query, `[data-agente="${agente.dataset.agente}"]`);
      return;
    }
    const lider = event.target.closest("[data-est-lider]");
    if (lider) {
      state.tournamentEstLider = Number(lider.dataset.estLider);
      teamDeslizaCartao(lider.closest(".vp-eq-bloco"), state.tournamentEstLider, "[data-est-lider]", lider);
      return;
    }
    const faixa = event.target.closest("[data-mapa-linha]");
    if (faixa) {
      state.tournamentMapaLinha = faixa.dataset.mapaId;
      const bloco = faixa.closest(".vp-eq-bloco");
      teamDeslizaCartao(bloco, Number(faixa.dataset.mapaLinha), "[data-mapa-linha]", faixa);
      // Numa coluna so o cartao fica fora da tela: sem isso a troca passaria batida.
      if (window.matchMedia("(max-width: 1180px)").matches) bloco.querySelector(".vp-resumo").scrollIntoView({ block: "nearest", behavior: "smooth" });
      return;
    }
    const seta = event.target.closest("[data-est-detalhe]");
    if (!seta) return;
    const aberto = seta.getAttribute("aria-expanded") !== "true";
    seta.setAttribute("aria-expanded", String(aberto));
    seta.closest("tr").nextElementSibling.hidden = !aberto;
  });
}

// O corpo do nome desce ate o nome INTEIRO caber na caixa do titulo. Sao dois
// limites diferentes, e so o primeiro estava sendo verificado ate 30/08/2026:
//
//   largura - uma palavra mais larga que a coluna vaza. Medido nas 97 equipes,
//   a maior e "Naotemclutch" (354px a 56px) contra uma coluna de 208px.
//
//   altura  - o titulo tem `-webkit-line-clamp: 2`, entao um nome que precisa
//   de tres linhas perde a terceira com reticencia. "Green Owls Noctua" cabia
//   na largura (208 de 208) e pedia 164px de altura numa caixa de 105: virava
//   "Green Owls...". Nenhuma palavra estourava, e por isso o ajuste anterior
//   nao via nada errado.
//
// A largura sai do canvas (numero exato, sem reflow); a altura sai do DOM, num
// laco que desce 1px por vez - e o proprio navegador quebrando as linhas, e
// nao uma simulacao de quebra que poderia discordar dele. Na pratica o laco
// roda poucas voltas, porque a conta da largura ja chega perto.
const TITULO_EQUIPE_MINIMO = 22;

// O corpo do nome desce ate o nome INTEIRO caber no espaco reservado ao titulo.
// O que fica travado e a ALTURA, nao o numero de linhas: o orcamento e o de
// duas linhas no corpo cheio (~105px), e quantas linhas cabem ali depende do
// corpo. Tres linhas a 35px ocupam a mesma altura que duas a 56px.
//
// Ate 30/08/2026 o limite era "no maximo 2 linhas" fixo, e isso cortava nomes
// de tres palavras. Dois casos medidos:
//   "Green Owls Noctua"          - cabia na largura e pedia 3 linhas: o
//                                  `-webkit-line-clamp: 2` comia "Noctua".
//   "PUCGO Sistematica Academy"  - pede 3 linhas mesmo no menor corpo, entao
//                                  nenhum tamanho satisfazia a regra antiga.
//
// A busca e binaria porque a condicao e monotonica (corpo menor nunca produz
// mais altura), o que da ~6 medicoes em vez de dezenas de descidas de 1px.
function ajustaTituloDaEquipe() {
  const titulo = document.querySelector(".team-page .vp-equipe-id h1");
  if (!titulo) return;
  // Zera antes de medir: sem isso, a chamada que roda depois do `fonts.ready`
  // leria como base o corpo que a primeira ja reduziu, e o titulo so poderia
  // encolher de novo - nunca voltar aos 56px quando a fonte certa chega.
  titulo.style.fontSize = "";
  titulo.style.webkitLineClamp = "";
  const nome = titulo.textContent.trim();
  if (!titulo.clientWidth || !nome) return;
  const base = Number.parseFloat(getComputedStyle(titulo).fontSize) || 56;
  const orcamento = 2 * (Number.parseFloat(getComputedStyle(titulo).lineHeight) || base);

  const medir = (corpo) => {
    titulo.style.fontSize = `${corpo}px`;
    const alturaDeLinha = Number.parseFloat(getComputedStyle(titulo).lineHeight) || corpo;
    const permitidas = Math.max(2, Math.floor(orcamento / alturaDeLinha));
    titulo.style.webkitLineClamp = "unset";
    const linhas = Math.floor(titulo.scrollHeight / alturaDeLinha);
    const vazaNaLargura = titulo.scrollWidth > titulo.clientWidth + 1;
    titulo.style.webkitLineClamp = "";
    return { cabe: !vazaNaLargura && linhas <= permitidas, permitidas };
  };

  let melhor = medir(base);
  if (!melhor.cabe) {
    let baixo = TITULO_EQUIPE_MINIMO;
    let alto = base - 1;
    let escolhido = TITULO_EQUIPE_MINIMO;
    melhor = medir(TITULO_EQUIPE_MINIMO);
    while (baixo <= alto) {
      const meio = Math.floor((baixo + alto) / 2);
      const teste = medir(meio);
      if (teste.cabe) {
        escolhido = meio;
        melhor = teste;
        baixo = meio + 1;
      } else {
        alto = meio - 1;
      }
    }
    titulo.style.fontSize = `${escolhido}px`;
  } else {
    titulo.style.fontSize = "";
  }
  // O clamp acompanha o corpo escolhido: sem isso, um nome de tres linhas em
  // corpo menor continuaria sendo cortado pelo limite de duas do CSS.
  titulo.style.webkitLineClamp = String(melhor.permitidas);
}

// A primeira medicao pode cair na fonte de fallback se o Barlow Condensed
// ainda nao chegou; as metricas mudam e o titulo ficaria no corpo errado.
if (typeof document !== "undefined" && document.fonts?.ready) {
  document.fonts.ready.then(() => ajustaTituloDaEquipe());
}

function teamProfileLogo(team) {
  return `<span class="team-logo-frame">${teamLogo(team.id, "large")}</span>`;
}

const TEAM_INK_CLARO = "#f5f1f2";
const TEAM_INK_ESCURO = "#040306";
const TEAM_ROW_SURFACE = [11, 11, 16];
const TEAM_INK_CONTRASTE_MINIMO = 4.5;

// Luminancia relativa (WCAG). Existe porque quando o fundo da linha vira a cor
// da equipe nao da para escolher a tinta do texto no chute: das 97 equipes, as
// mais claras sao branco puro e as mais escuras sao preto puro. A mesma tinta
// nao serve para as duas.
function relativeLuminance(rgb) {
  const canal = (v) => {
    const x = v / 255;
    return x <= 0.03928 ? x / 12.92 : ((x + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * canal(rgb[0]) + 0.7152 * canal(rgb[1]) + 0.0722 * canal(rgb[2]);
}

function hexToRgb(value) {
  const match = /^#([0-9a-f]{6})$/i.exec(String(value).trim());
  if (!match) return null;
  const n = parseInt(match[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function contrastRatio(a, b) {
  const [la, lb] = [relativeLuminance(a), relativeLuminance(b)];
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

// A tinta escura entra so quando a COR PRINCIPAL da equipe e branca ou muito
// clara - a cor2 nao vota. Antes quem decidia era o pior dos dois tons, e uma
// cor2 clara virava o nome inteiro para preto mesmo com a cor1 escura.
//
// 0,45 de luminancia relativa e onde a lista tem a maior folga: de um lado
// unirio_krakens (#53c5f1, 0,481) e tigre_branco (#b9b9b9, 0,485), do outro
// pucc_canaries (#cca900, 0,412). Acima do corte ficam 14 das 97 - os dois
// brancos puros, os dois UFU Saints, os amarelos fortes e os azuis lavados.
//
// Nao e o cruzamento matematico das duas tintas, que fica em 0,171: naquele
// ponto 36 equipes virariam preto, incluindo azul medio como #037aff, que nao
// e "muito claro" por nenhuma leitura razoavel.
const TEAM_INK_LIMIAR = 0.45;

function teamInkFor(cor1) {
  const cor = hexToRgb(cor1);
  if (!cor) return TEAM_INK_CLARO;
  return relativeLuminance(cor) >= TEAM_INK_LIMIAR ? TEAM_INK_ESCURO : TEAM_INK_CLARO;
}

function piorContraste(tinta, ...tons) {
  const alvo = hexToRgb(tinta);
  return Math.min(...tons.filter(Boolean).map((tom) => contrastRatio(alvo, tom)));
}

// A trama alterna dois tons e o texto atravessa os dois. A tinta ja foi
// escolhida pela cor1; aqui os dois tons caminham juntos ate ela fechar 4,5:1
// nos dois - para o branco se a tinta e escura, para a superficie da linha se
// e clara. Vermelho e azul de saturacao media sao os que mais andam: nem
// branco nem preto fecham 4,5:1 contra #e90101 ou #037aff sem ajuda.
const TEAM_WASH_MISTURA = 0.4;
// Piso de separacao entre os dois tons da trama. Sem ele a trama sumia nas
// equipes de cor1 e cor2 parecidas: visto na tela, a `faixa` do Azure Bears
// (#037aff / #67afff, 1,29:1) lia como azul chapado, enquanto o `chevron` do
// UFU Saints (1,86:1) aparecia inteiro. Nao adianta escolher geometria mais
// forte quando nao ha diferenca de cor para a geometria mostrar.
const TEAM_TOM_SEPARACAO_MINIMA = 1.55;

// Afasta o segundo tom do primeiro ate os dois se distinguirem, sem perder os
// 4,5:1 do texto que o passeio anterior garantiu.
//
// Testa as duas direcoes em vez de deduzir uma. Deduzir falhou duas vezes:
// escolhendo pela tinta, o UFU Saints mandava empurrar #fefefe para o branco, e
// branco nao clareia; escolhendo pela cor1, os tons medios com tinta clara
// tinham de clarear e a guarda de contraste barrava no primeiro passo. Os dois
// criterios brigam em cor media - entao mede os dois e fica com o melhor.
function afastaSegundoTom(primeiro, segundo, tinta) {
  const alvoDaTinta = hexToRgb(tinta);
  let melhor = segundo;
  let melhorSeparacao = contrastRatio(primeiro, segundo);
  for (const destino of [[0, 0, 0], [255, 255, 255]]) {
    for (let passo = 2; passo <= 100; passo += 2) {
      const f = passo / 100;
      const tom = segundo.map((c, i) => Math.round(c * (1 - f) + destino[i] * f));
      if (contrastRatio(alvoDaTinta, tom) < TEAM_INK_CONTRASTE_MINIMO) break;
      const separacao = contrastRatio(primeiro, tom);
      if (separacao > melhorSeparacao) {
        melhorSeparacao = separacao;
        melhor = tom;
      }
      if (separacao >= TEAM_TOM_SEPARACAO_MINIMA) break;
    }
    if (melhorSeparacao >= TEAM_TOM_SEPARACAO_MINIMA) break;
  }
  return melhor;
}

function teamWashFor(accent, accent2) {
  const cor = hexToRgb(accent);
  if (!cor) return { fundo: accent, fundo2: accent2, tinta: TEAM_INK_CLARO };
  const segunda = hexToRgb(accent2) || cor;
  // A cor2 nunca entra pura na trama: puxada 40% para dentro da cor1, ela
  // aparece como variacao da mesma familia em vez de listra de outro time.
  const par = segunda.map((c, i) => c * TEAM_WASH_MISTURA + cor[i] * (1 - TEAM_WASH_MISTURA));

  const tinta = teamInkFor(accent);
  const destino = tinta === TEAM_INK_ESCURO ? [255, 255, 255] : TEAM_ROW_SURFACE;
  for (let passo = 0; passo <= 100; passo += 1) {
    const f = passo / 100;
    // Arredonda ANTES de medir: a conta em float garantia 4,50:1 num valor que
    // depois virava #rrggbb e caia para 4,48:1. O que vale e a cor emitida.
    const a = cor.map((c, i) => Math.round(c * (1 - f) + destino[i] * f));
    const b = par.map((c, i) => Math.round(c * (1 - f) + destino[i] * f));
    if (piorContraste(tinta, a, b) >= TEAM_INK_CONTRASTE_MINIMO || passo === 100) {
      // A separacao vem por ultimo: o passeio acima move os dois tons juntos e
      // comprime a diferenca entre eles. Separar antes dele era desperdicio -
      // medido, 19 das 97 voltavam para baixo do piso.
      const segundoTom = contrastRatio(a, b) < TEAM_TOM_SEPARACAO_MINIMA ? afastaSegundoTom(a, b, tinta) : b;
      return { fundo: rgbToHex(a), fundo2: rgbToHex(segundoTom), tinta };
    }
  }
  return { fundo: accent, fundo2: accent2, tinta: TEAM_INK_CLARO };
}

function rgbToHex(rgb) {
  return `#${rgb.map((c) => Math.max(0, Math.min(255, Math.round(c))).toString(16).padStart(2, "0")).join("")}`;
}

// Cinco tramas, escolhidas pelo jeito que as duas cores da equipe conversam.
// A regra e explicita de proposito: o insumo e a separacao entre os dois tons
// (contraste de um contra o outro) e a distancia de matiz. Quanto mais as duas
// brigam, menos area a segunda ganha - senao a linha vira bandeira listrada.
//
// Catorze degrades, escolhidos pelo jeito que as duas cores da equipe
// conversam. Sao so degrades e fades - nenhuma listra, bolinha, xadrez ou
// malha. O que distingue um do outro e a direcao, a origem e quantas paradas de
// cor tem, nao geometria repetida.
//
// Os insumos sao a separacao entre os dois tons ja ajustados e a distancia de
// matiz das cores ORIGINAIS da planilha - depois da mistura o matiz da cor2 e
// puxado para dentro do da cor1 e a conta perde sentido.
//
// Os cortes sao os septis medidos nas 97 depois que o piso de separacao entrou
// (1,56 / 1,58 / 1,63 / 1,80 / 2,09 / 2,76). Sete faixas x dois matizes dao
// catorze celulas, todas povoadas.
//
// A ordem nao e arbitraria: quanto maior a separacao, MENOS area a cor2 ganha.
// Duas cores que brigam dividindo a linha ao meio viram bandeira de dois
// times; a mesma cor2 so na borda vira acabamento.
const TEAM_PATTERN_TABELA = [
  { limite: 1.56, perto: "horizonte", longe: "diagonal" },
  { limite: 1.58, perto: "bordas", longe: "lateral" },
  { limite: 1.63, perto: "nascente", longe: "canto" },
  { limite: 1.8, perto: "nucleo", longe: "mare" },
  { limite: 2.09, perto: "cinta", longe: "varredura" },
  { limite: 2.76, perto: "aurora", longe: "deriva" },
  { limite: Infinity, perto: "vinheta", longe: "brilho" },
];

function hueOf(rgb) {
  const [r, g, b] = rgb.map((c) => c / 255);
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  if (max === min) return 0;
  const d = max - min;
  let h;
  if (max === r) h = ((g - b) / d) % 6;
  else if (max === g) h = (b - r) / d + 2;
  else h = (r - g) / d + 4;
  return ((h * 60) % 360 + 360) % 360;
}

// tom1/tom2 sao os tons ja ajustados por contraste (o que aparece na tela) e
// definem a separacao; cor1/cor2 sao os da planilha e definem o matiz.
function teamPatternFor(tom1, tom2, cor1, cor2) {
  const a = hexToRgb(tom1);
  const b = hexToRgb(tom2);
  if (!a || !b) return "tecido";
  const separacao = contrastRatio(a, b);
  const origem1 = hexToRgb(cor1) || a;
  const origem2 = hexToRgb(cor2) || b;
  const bruto = Math.abs(hueOf(origem1) - hueOf(origem2));
  const matiz = Math.min(bruto, 360 - bruto);
  const faixa = TEAM_PATTERN_TABELA.find((linha) => separacao < linha.limite);
  return matiz < 40 ? faixa.perto : faixa.longe;
}

function teamAccentStyle(team) {
  const [primary, secondary] = team.colors || [];
  const accent = safeCssColor(primary, "#f6132a");
  const accent2 = safeCssColor(secondary, "#2ad4c1");
  const { fundo, fundo2, tinta } = teamWashFor(accent, accent2);
  const trama = teamPatternFor(fundo, fundo2, accent, accent2);
  const campo = teamFieldPalette(accent, accent2);
  const deriva = teamFieldMotion(team.id);
  const linha = teamChartInk(accent, accent2);
  return `data-trama="${trama}" style="--team-accent:${accent};--team-accent-2:${accent2};--team-wash:${fundo};--team-wash-2:${fundo2};--team-ink:${tinta};--team-field-bg:${campo.fundo};--team-field-focus:${campo.foco};--team-field-second:${campo.segunda};--team-line:${linha};${teamFieldMotionVars(deriva)}"`;
}

// O campo do heroi e gerado das DUAS cores da planilha, e ele se move. Tres
// regras seguram isso de pe nas 97 equipes:
//
// 1. O campo e sempre escuro, porque o texto do heroi e branco. Cada tom entra
//    com a LUMINANCIA travada em vez da cor crua: 0,085 no fundo, 0,26 no foco
//    e 0,20 na segunda familia. No pior matiz (amarelo puro) o foco ainda da
//    6,6:1 para o branco - cor crua nao daria: #cca900 sozinho da 2,6:1.
// 2. A cor2 so vira segunda familia quando ela AGREGA. Medido na planilha: 18
//    equipes tem cor2 quase preta (#020103, #040101 - preto de contorno de
//    logo, nao cor) e 1 tem cor2 igual a cor1. Nesses casos a cor2 viraria um
//    borrao invisivel, entao o lugar dela e ocupado por um giro de matiz da
//    propria cor1: o campo continua com duas familias se movendo.
// 3. Saturacao nao tem piso. Equipe de identidade cinza fica com campo grafite
//    de proposito - inventar matiz para ela seria pintar dado que a planilha
//    nao tem.
const TEAM_FIELD_LUZ_FUNDO = 0.085;
const TEAM_FIELD_LUZ_FOCO = 0.26;
const TEAM_FIELD_LUZ_SEGUNDA = 0.2;
const TEAM_FIELD_SAT_MAX = 0.86;
// Cromaticidade e nao saturacao HSL: para #fefeff a saturacao HSL passa de
// 0,9 e diria "branco muito saturado", o que faria o campo do Azure Bears
// ganhar um azul-violeta que a planilha nunca pediu.
const TEAM_FIELD_CROMA_MINIMA = 0.12;
const TEAM_FIELD_LUZ_MINIMA_COR2 = 0.06;
const TEAM_FIELD_MATIZ_MINIMO = 18;
// 26 graus e nao 46: girando 46 a partir do vermelho da AAEU Cerberus o campo
// ganhava um oliva que a equipe nao tem em lugar nenhum. Em 26, com a saturacao
// caindo para 62%, o segundo tom le como SOMBRA da cor1 - ainda separa o
// movimento sem inventar uma segunda marca.
const TEAM_FIELD_GIRO = 26;
const TEAM_FIELD_GIRO_SAT = 0.62;
const TEAM_PLACA_SEM_COR = "#3a3d48";
const TEAM_PLACA_LUZ_MINIMA = 0.012;
const TEAM_PLACA_CONTRASTE = 4.5;

function chromaOf(rgb) {
  return (Math.max(...rgb) - Math.min(...rgb)) / 255;
}

function rgbToHsl(rgb) {
  const [r, g, b] = rgb.map((c) => c / 255);
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  if (max === min) return [0, 0, l];
  const d = max - min;
  return [hueOf(rgb), l > 0.5 ? d / (2 - max - min) : d / (max + min), l];
}

// hslToRgb() ja existe neste arquivo e recebe s/l em PORCENTO. rgbToHsl acima
// devolve em 0..1 porque e assim que os alvos de luminancia sao escritos, entao
// a conversao mora aqui, num lugar so.
function hslFracToRgb(h, s, l) {
  return hslToRgb(((h % 360) + 360) % 360, clamp(s, 0, 1) * 100, clamp(l, 0, 1) * 100);
}

function teamFieldPalette(accent, accent2) {
  const cor1 = hexToRgb(accent) || [246, 19, 42];
  const cor2 = hexToRgb(accent2);
  const [h1, s1] = rgbToHsl(cor1);
  const tom = (h, s, l) => rgbToHex(hslFracToRgb(h, Math.min(Math.max(s, 0), TEAM_FIELD_SAT_MAX), l));
  let h2 = h1 + TEAM_FIELD_GIRO;
  let s2 = s1 * TEAM_FIELD_GIRO_SAT;
  if (cor2) {
    const [hc2, sc2, lc2] = rgbToHsl(cor2);
    const bruto = Math.abs(h1 - hc2);
    // Matiz de cor acromatica nao quer dizer nada: hueOf(#000000) devolve 0, e
    // com isso o vermelho #fc1143 da IME Wolves Red (matiz 349, distancia 11)
    // era recusado por "estar perto" de um preto que nao tem matiz nenhum.
    const matiz = chromaOf(cor1) < TEAM_FIELD_CROMA_MINIMA ? 360 : Math.min(bruto, 360 - bruto);
    if (chromaOf(cor2) >= TEAM_FIELD_CROMA_MINIMA && lc2 >= TEAM_FIELD_LUZ_MINIMA_COR2 && matiz >= TEAM_FIELD_MATIZ_MINIMO) {
      h2 = hc2;
      s2 = sc2;
    } else if (chromaOf(cor2) < TEAM_FIELD_CROMA_MINIMA && lc2 > 0.6) {
      // Cor2 branca ou cinza-claro (Azure Bears, UFU Saints): a segunda familia
      // vira um cinza da propria familia da cor1. Girar o matiz aqui pintaria
      // uma cor que a equipe nao tem.
      h2 = h1;
      s2 = Math.min(s1 * 0.22, 0.18);
    }
  }
  return {
    fundo: tom(h1, s1 * 0.9, TEAM_FIELD_LUZ_FUNDO),
    foco: teamFieldToneGuard(h1, s1, TEAM_FIELD_LUZ_FOCO),
    segunda: teamFieldToneGuard(h2, s2, TEAM_FIELD_LUZ_SEGUNDA),
  };
}

// Luminancia fixa nao basta: em matiz oliva (#7b7209, homem_passaro) o alvo de
// 0,26 dava 4,41:1 contra a tinta clara #f5f1f2 e reprovava por pouco. O tom
// desce de 1% em 1% ate fechar 4,5:1, entao o piso e medido e nao estimado.
function teamFieldToneGuard(h, s, luz) {
  const sat = Math.min(Math.max(s, 0), TEAM_FIELD_SAT_MAX);
  for (let passo = 0; passo <= 24; passo += 1) {
    const tom = hslFracToRgb(h, sat, Math.max(0.04, luz - passo / 100));
    if (contrastRatio(tom, hexToRgb(TEAM_INK_CLARO)) >= TEAM_INK_CONTRASTE_MINIMO) return rgbToHex(tom);
  }
  return rgbToHex(hslFracToRgb(h, sat, 0.04));
}

// A deriva do campo e semeada no id da equipe: duracoes, fase e angulo saem de
// um hash, entao as 97 equipes tem o mesmo sistema e nenhuma tem o mesmo
// movimento. As tres duracoes sao primas entre si de proposito - o ciclo
// composto passa de duas horas e a pessoa nunca ve o loop fechar.
function teamFieldMotion(id) {
  let h = 2166136261;
  for (const ch of String(id || "")) {
    h ^= ch.charCodeAt(0);
    h = Math.imul(h, 16777619);
  }
  const n = (deslocamento, mod) => (h >>> deslocamento) % mod;
  return {
    a: 41 + n(0, 13),
    b: 59 + n(4, 17),
    c: 73 + n(8, 19),
    atraso: -n(12, 40),
    giro: 90 + n(16, 120),
    x1: 4 + n(20, 22),
    y1: -18 + n(22, 26),
    x2: 44 + n(24, 28),
    y2: -10 + n(26, 30),
  };
}

function teamFieldMotionVars(deriva) {
  return `--fa:${deriva.a}s;--fb:${deriva.b}s;--fc:${deriva.c}s;--fdelay:${deriva.atraso}s;--fgiro:${deriva.giro}deg;--fx1:${deriva.x1};--fy1:${deriva.y1};--fx2:${deriva.x2};--fy2:${deriva.y2};`;
}

// Tinta da linha do grafico de ranking. O painel do grafico e #0b0b10; a cor da
// equipe sobe ou desce ate fechar 4,5:1 contra ele. Sem esse passeio, as 18
// equipes de cor1 escura desenhariam uma linha invisivel, e o vermelho da marca
// - que era o que estava ali - contraria a regra de que vermelho e identidade,
// nunca dado.
const TEAM_CHART_PAINEL = [11, 11, 16];
const TEAM_CHART_CONTRASTE_MINIMO = 4.5;

function teamChartInk(accent, accent2) {
  const candidatos = [hexToRgb(accent), hexToRgb(accent2)].filter(Boolean);
  if (!candidatos.length) return "#f5f1f2";
  const base = candidatos.find((cor) => chromaOf(cor) >= TEAM_FIELD_CROMA_MINIMA) || candidatos[0];
  const [h, s] = rgbToHsl(base);
  // Sobe a luminosidade em degraus e para no primeiro que fecha 4,5:1. Comeca
  // em 0,42 porque abaixo disso nenhuma cor saturada passa contra #0b0b10.
  for (let l = 42; l <= 92; l += 2) {
    const tom = hslFracToRgb(h, Math.min(s, 0.82), l / 100);
    if (contrastRatio(tom, TEAM_CHART_PAINEL) >= TEAM_CHART_CONTRASTE_MINIMO) return rgbToHex(tom);
  }
  return "#f5f1f2";
}

function safeCssColor(value, fallback) {
  const text = String(value || "").trim();
  if (/^#[0-9a-f]{3,8}$/i.test(text)) return text;
  if (/^(rgb|hsl)a?\([0-9.,% -]+\)$/i.test(text)) return text;
  return fallback;
}

function teamStateBadge(team) {
  const profile = team.profile || {};
  const stateLabel = profile.state ? `${profile.stateName || profile.state}` : profile.stateName || "Estado não informado";
  const flag = profile.flag
    ? `<img class="state-flag" src="${escapeHtml(assetPath(profile.flag))}" alt="Bandeira ${escapeHtml(stateLabel)}" loading="lazy" onerror="this.replaceWith(this.nextElementSibling)" /><span class="state-flag placeholder">${escapeHtml(profile.state || "UF")}</span>`
    : `<span class="state-flag placeholder">${escapeHtml(profile.state || "UF")}</span>`;
  return `<span class="state-badge">${flag}<span>${escapeHtml(stateLabel)}</span></span>`;
}

function teamTrophyAchievements(team, { includeInherited = true } = {}) {
  if (!team?.id) return [];
  const rows = [];
  const inherited = includeInherited ? rankingSuccessionAliases(state.db?.teams || [], state.db?.matches || [], Date.now()) : new Map();
  const origins = new Set([team.id, ...[...inherited].filter(([, row]) => row.to === team.id).map(([id]) => id)]);
  for (const event of visibleTournaments()) {
    if (!eventIsDone(event)) continue;
    const placements = trophyPlacementRows(event);
    placements.forEach((row, index) => {
      const teamId = row.id || row.teamId;
      if (!origins.has(teamId)) return;
      const placement = trophyPlacementInfo(row, index);
      if (!placement) return;
      const trophy = {
        event,
        placement: placement.value,
        placementLabel: placement.label,
        trophyKey: placement.trophyKey,
        podiumClass: placement.podiumClass,
        date: Number(event.end || event.start || 0),
        originalTeamId: teamId,
      };
      const existing = rows.findIndex((item) => item.event.id === event.id);
      if (existing < 0) rows.push(trophy);
      else if (trophy.placement < rows[existing].placement) rows[existing] = trophy;
    });
  }
  return rows.sort((a, b) => b.date - a.date || a.placement - b.placement || String(a.event.name || "").localeCompare(String(b.event.name || ""), "pt-BR"));
}

function trophyPlacementRows(event) {
  if (event.placements?.length) return normalizePlacementRowsForDisplay(event.placements);
  const configured = state.db?.rankingWeights?.tournaments?.[event.id]?.placements || [];
  return normalizePlacementRowsForDisplay(configured);
}

function trophyPlacementInfo(row, index) {
  const raw = placementRawValue(row) || placementLabel(index);
  if (placementIsOngoing(raw)) return null;
  const text = String(raw || "").trim();
  const normalized = normalize(text);
  const compact = normalizeNameKey(text);
  const number = Number(row.placement || text);
  if (number === 1 || text === "1" || compact === "1olugar" || normalized === "1st") {
    return { value: 1, label: "Campeão", trophyKey: "champion", podiumClass: "place-1" };
  }
  if (number === 2 || text === "2" || compact === "2olugar" || normalized === "2nd") {
    return { value: 2, label: "Vice-campeão", trophyKey: "runnerUp", podiumClass: "place-2" };
  }
  if (number === 3 || text === "3" || compact === "3olugar" || normalized === "3rd") {
    return { value: 3, label: "3º lugar", trophyKey: "third", podiumClass: "place-3" };
  }
  if (normalized.startsWith("3-4") || normalized.startsWith("3/4") || compact.startsWith("34")) {
    return { value: 3.5, label: "3º/4º lugar", trophyKey: "third", podiumClass: "place-3" };
  }
  return null;
}

function trophyVisual(trophy) {
  const candidates = trophyImageCandidates(trophy.event, trophy.trophyKey).map(assetPath).filter(Boolean);
  const src = candidates[0] || assetPath(TROPHY_GENERIC_ASSETS[trophy.trophyKey] || TROPHY_GENERIC_ASSETS.third);
  const fallbacks = candidates.slice(1).join("|");
  return `
    <span class="trophy-visual ${trophyImageIsGeneric(src) ? "generic-trophy" : ""} ${trophy.trophyKey === "mvp" ? "mvp-trophy" : ""}" aria-hidden="true">
      <img class="trophy-image" src="${escapeHtml(src)}" alt="" loading="lazy" data-trophy-fallbacks="${escapeHtml(fallbacks)}" onload="trophyImageLoaded(this)" onerror="trophyImageFallback(this)" />
      ${eventLogo(trophy.event, "trophy-event-logo")}
    </span>
  `;
}

function trophyImageCandidates(event, trophyKey) {
  const suffix =
    trophyKey === "champion" ? "campeao" : trophyKey === "runnerUp" ? "vice" : trophyKey === "mvp" ? "mvp" : "terceiro";
  const eventKeys = [...new Set([event?.id, slugify(event?.name || ""), normalizeNameKey(event?.name || "")].filter(Boolean))];
  const possiveis = [
    ...eventKeys.flatMap((key) => [`${key}-${suffix}.png`, `${key}_${suffix}.png`]),
    // `<id>.png` e a arte do trofeu DAQUELE campeonato, e vale so para podio.
    // Num MVP ela venceria o mvp.png e o premio individual apareceria com a
    // taca do evento - foi o que aconteceu com a arte da RivvalsGG.
    ...(trophyKey === "mvp" ? [] : eventKeys.map((key) => `${key}.png`)),
  ];
  // So entra na fila o arquivo que o manifesto diz existir. Sem este filtro,
  // cada podio disparava de tres a seis requisicoes que davam 404 antes de o
  // onerror chegar no generico.
  return [
    ...possiveis.filter((nome) => TROPHY_ART_FILES.has(nome)).map((nome) => `${TROPHY_ASSET_ROOT}/${nome}`),
    TROPHY_GENERIC_ASSETS[trophyKey] || TROPHY_GENERIC_ASSETS.third,
  ];
}

function trophyImageFallback(image) {
  const fallbacks = String(image?.dataset?.trophyFallbacks || "").split("|").filter(Boolean);
  const next = fallbacks.shift();
  if (!next) {
    image?.remove();
    return;
  }
  image.dataset.trophyFallbacks = fallbacks.join("|");
  image.closest(".trophy-visual")?.classList.toggle("generic-trophy", trophyImageIsGeneric(next));
  image.src = next;
}

function trophyImageLoaded(image) {
  const src = image?.currentSrc || image?.getAttribute("src") || "";
  image?.closest(".trophy-visual")?.classList.toggle("generic-trophy", trophyImageIsGeneric(src));
}

function trophyImageIsGeneric(src) {
  return /(?:^|\/)(?:campeao|vice|terceiro)-generico\.png(?:$|\?)/i.test(String(src || "").replaceAll("\\", "/"));
}

// So as semanas do ranking oficial. O historico cadastrado a mao e a conta por pontos
// que existiam aqui nao eram o ranking oficial, e nenhuma equipe chegava neles.
function teamRankingHistory(team) {
  const historico = teamRankingSnapshotHistory(team.id);
  // Perfil de uma fase antiga: so as semanas daquele nome.
  if (!team.rankingJanela) return historico;
  const [inicio, fim] = team.rankingJanela;
  return historico.filter((row) => dateValue(row.date) >= inicio && dateValue(row.date) <= fim);
}

function teamRankingSnapshotHistory(teamId) {
  return (state.db?.rankingSnapshots || [])
    .map((snapshot) => {
      const row = snapshot.byTeamId?.[teamId];
      if (!row || !row.matches) return null;
      return {
        date: snapshot.cutoffAt,
        rank: row.validRank || null,
        // Semana provisoria tem a posicao entre todas as equipes, desenhada pontilhada.
        provisorio: !row.validRank && row.provisional && !rankingIsInactive(row) && Number(row.rank) > 0 ? Number(row.rank) : null,
        points: row.score,
        note: rankingIsValid(row) ? snapshot.label : `${snapshot.label} - ${rankingStatusLabel(row).toLowerCase()}`,
      };
    })
    .filter(Boolean);
}

function rankingHistoryRankLabel(rank) {
  const value = Number(rank);
  return Number.isFinite(value) && value > 0 ? `#${value}` : "Provisório";
}

function teamHistoricalPlayers(team) {
  const registeredLineup = team.currentLineup || [];
  const lineupIds = new Set(registeredLineup.map((entry) => entry.playerId).filter(Boolean));
  const lineupNameKeys = new Set(registeredLineup.map((entry) => normalizeNameKey(entry.name)).filter(Boolean));
  return state.db.players
    .filter(playerTemPerfil)
    .filter((player) => {
      if (!(player.teamHistory || []).includes(team.id)) return false;
      if (!registeredLineup.length) return player.currentTeam !== team.id;
      if (lineupIds.has(player.id) || playerLookupKeys(player).some((key) => lineupNameKeys.has(key))) return false;
      return player.currentTeam !== team.id;
    })
    .sort((a, b) => a.nick.localeCompare(b.nick));
}

function lineupTimelineRows(team) {
  const segments = team.profile?.lineupHistory || [];
  const currentIds = new Set((team.currentLineup || []).map((entry) => entry.playerId).filter(Boolean));
  const currentKeys = new Set((team.currentLineup || []).map((entry) => entry.playerId || normalizeNameKey(entry.name || entry.handle)).filter(Boolean));
  const rows = new Map();
  for (const segment of segments) {
    for (const entry of segment.players || []) {
      const key = entry.playerId || normalizeNameKey(entry.name || entry.handle);
      if (!key) continue;
      const current = currentIds.has(entry.playerId) || currentKeys.has(key);
      const start = dateValue(entry.firstSeenAt || segment.from || segment.firstSeenAt);
      const end = dateValue(entry.lastSeenAt || segment.to || segment.lastSeenAt) || start;
      const player = entry.playerId ? playerById(entry.playerId) : null;
      const row = rows.get(key) || {
        key,
        playerId: entry.playerId || "",
        name: player?.nick || entry.name || entry.handle || "Jogador",
        handle: player?.handle || entry.handle || "",
        start: start || end,
        end: end || start,
        matches: 0,
        rounds: 0,
        current: false,
      };
      row.playerId = row.playerId || entry.playerId || "";
      row.name = player?.nick || row.name;
      row.handle = player?.handle || row.handle;
      row.start = Math.min(row.start || start, start || row.start);
      row.end = Math.max(row.end || end, end || row.end);
      row.matches += Number(entry.matches || 0);
      row.rounds += Number(entry.rounds || 0);
      row.current = row.current || current;
      rows.set(key, row);
    }
  }
  return [...rows.values()]
    .filter((row) => row.start && row.end)
    .sort((a, b) => Number(b.current) - Number(a.current) || a.start - b.start || a.name.localeCompare(b.name));
}

// Os campeonatos que a equipe jogou dentro da janela da linha do tempo. Sao
// eles que dao sentido a linha: sem marco, o grafico responde "quem estava
// aqui em junho"; com marco, ele responde "quem jogou o JUBS" - que e a
// pergunta que alguem abre a aba de elenco para responder.
function lineupTimelineEvents(team, min, max) {
  return visibleTournaments()
    .filter((event) => event.teams.includes(team.id))
    .map((event) => ({ event, at: dateValue(event.start) }))
    .filter((row) => row.at >= min && row.at <= max)
    .sort((a, b) => a.at - b.at);
}

function lineupTimelineChart(team, rows = lineupTimelineRows(team)) {
  if (!rows.length) return `<div class="empty-state">Sem histórico de elenco suficiente para montar a linha do tempo.</div>`;
  const min = Math.min(...rows.map((row) => row.start));
  const max = Math.max(...rows.map((row) => row.end));
  const span = Math.max(DAY_MS, max - min);
  const ticks = mesesDoPeriodo(min, max);
  const eventos = lineupTimelineEvents(team, min, max);
  return `
    <div class="lineup-timeline-chart">
      <div class="lineup-timeline-axis">
        <span></span>
        <div class="lineup-axis-track vp-meses-verticais">
          ${ticks.map((tick) => `<span style="left:${timelinePct(tick, min, max)}%">${escapeHtml(chartDateLabel(tick))}</span>`).join("")}
          ${eventos
            .map(
              (row) => `
                <a class="lineup-timeline-event" href="#/tournaments/${row.event.id}" style="left:${fmt(timelinePct(row.at, min, max), 2)}%" title="${escapeHtml(`${row.event.name} - início ${formatDate(row.event.start)}`)}">
                  ${eventLogo(row.event, "lineup-timeline-event-logo")}
                </a>
              `,
            )
            .join("")}
        </div>
        <span></span>
      </div>
      <div class="lineup-timeline-rows">
        ${eventos
          .map((row) => `<span class="lineup-timeline-marker" style="--t:${fmt(timelinePct(row.at, min, max) / 100, 4)}" aria-hidden="true"></span>`)
          .join("")}
        ${rows
          .map((row) => {
            const comPerfil = playerTemPerfil(playerById(row.playerId));
            const href = comPerfil ? `href="${playerHref(row.playerId)}"` : "";
            const tag = comPerfil ? "a" : "span";
            // Uma faixa por passagem: quem saiu e voltou fica com um vao no meio.
            const trechos = row.trechos || [{ inicio: row.start, fim: row.end }];
            const periodos = trechos.map((trecho, indice) => teamTrechoTexto(trecho, row.current && indice === trechos.length - 1));
            return `
              <div class="lineup-timeline-row">
                <${tag} class="lineup-timeline-name" ${href}>
                  ${row.playerId ? playerLogo(row.playerId, "timeline-photo") : `<span class="timeline-photo logo round">${escapeHtml(row.name.slice(0, 2).toUpperCase())}</span>`}
                  <span><strong>${escapeHtml(row.name)}</strong>${row.current ? `<small>Atual</small>` : ""}</span>
                </${tag}>
                <div class="lineup-timeline-track">
                  ${trechos.map((trecho, indice) => {
                    const start = timelinePct(trecho.inicio, min, max);
                    const width = clamp(((trecho.fim - trecho.inicio) / span) * 100, 1, 100 - start);
                    return `<span class="lineup-timeline-bar ${row.current && indice === trechos.length - 1 ? "current" : ""}" style="--start:${fmt(start, 2)};--width:${fmt(width, 2)}" title="${escapeHtml(`${row.name}: ${periodos[indice]}`)}"></span>`;
                  }).join("")}
                </div>
              </div>
            `;
          })
          .join("")}
      </div>
    </div>
  `;
}

function timelineTicks(min, max) {
  const span = Math.max(DAY_MS, max - min);
  return [0, 0.33, 0.66, 1].map((ratio) => min + span * ratio);
}

function timelinePct(value, min, max) {
  return clamp(((value - min) / Math.max(DAY_MS, max - min)) * 100, 0, 100);
}

// O que o jogador de fato jogou COM esta equipe, lido mapa a mapa pelo
// `teamId` de cada linha do placar. E a fonte de verdade para quem nao esta no
// lineupHistory: Dante e jotave apareciam como "Periodo nao informado" mesmo
// tendo 2 e 1 mapas registrados pelo CEUB Octopus.
function playerObservedStintForTeam(team, player) {
  const datas = [];
  const eventos = new Set();
  let mapas = 0;
  for (const series of matchSeriesForPlayer(player.id)) {
    for (const match of series.maps || []) {
      if (!(match.players || []).some((row) => row.id === player.id && row.teamId === team.id)) continue;
      mapas += 1;
      const quando = dateValue(match.startedAt || series.startedAt);
      if (quando) datas.push(quando);
      if (series.eventId) eventos.add(series.eventId);
    }
  }
  if (!datas.length) return null;
  return { start: Math.min(...datas), end: Math.max(...datas), mapas, eventos: [...eventos] };
}

function playerTeamTenure(team, player) {
  const rows = lineupTimelineRows(team);
  const key = normalizeNameKey(player.nick || player.handle);
  const row = rows.find((item) => item.playerId === player.id || normalizeNameKey(item.name) === key || normalizeNameKey(item.handle) === key);
  const observado = playerObservedStintForTeam(team, player);
  // O registro de elenco manda quando existe (ele conhece o dia da troca);
  // o observado entra quando nao ha registro nenhum. So sobra "sem periodo"
  // para quem nao tem nem um nem outro - e nesse caso o texto diz por que.
  const inicio = row ? row.start : observado?.start;
  const fim = row ? row.end : observado?.end;
  const atual = Boolean(row?.current);
  const mapas = Number(row?.matches || 0) || Number(observado?.mapas || 0);
  const eventos = observado?.eventos || [];
  if (!inicio && !fim) {
    return { range: "Passagem sem partida registrada", detail: "Consta no elenco, sem mapa oficial", duracao: "", mapas: 0, eventos };
  }
  const volume = mapas ? `${mapas} ${mapas === 1 ? "mapa" : "mapas"}` : "participação registrada";
  return {
    range: formatDateRange(inicio, fim, { current: atual }),
    detail: `${formatTenureDuration(inicio, fim)} - ${volume}`,
    duracao: formatTenureDuration(inicio, fim),
    mapas,
    eventos,
    end: fim,
  };
}

function formatDateRange(start, end, options = {}) {
  const startAt = dateValue(start);
  const endAt = dateValue(end);
  const from = startAt || endAt;
  const to = endAt || startAt;
  if (!from && !to) return "Período não informado";
  const endLabel = formatPeriodEndDate(to, options);
  if (endLabel === "Atualmente" && from) return `${formatDate(from)} - ${endLabel}`;
  if (!to || Math.abs(to - from) < DAY_MS) return formatDate(from || to);
  return `${formatDate(from)} - ${endLabel}`;
}

function formatPeriodEndDate(end, options = {}) {
  return periodEndIsCurrent(end, options) ? "Atualmente" : formatDate(end);
}

function periodEndIsCurrent(end, options = {}) {
  if (options.current) return true;
  if (options.autoCurrent === false) return false;
  const endDay = dayKey(end);
  if (!endDay) return false;
  return currentPeriodEndDays().has(endDay);
}

function currentPeriodEndDays() {
  const days = new Set();
  [Date.now(), latestRankingSnapshot()?.cutoffAt, latestKnownDataTimestamp()].forEach((value) => {
    const key = dayKey(value);
    if (key) days.add(key);
  });
  return days;
}

function latestKnownDataTimestamp() {
  const candidates = [
    ...(state.db?.matches || []).map((match) => match.startedAt),
    ...(state.db?.matchSeries || []).flatMap((series) => [series.sortAt, series.startedAt, ...(series.maps || []).map((match) => match.startedAt)]),
  ]
    .map(dateValue)
    .filter(Boolean);
  return candidates.length ? Math.max(...candidates) : 0;
}

function dayKey(value) {
  const timestamp = dateValue(value);
  if (!timestamp) return "";
  const date = new Date(timestamp);
  date.setHours(0, 0, 0, 0);
  return String(date.getTime());
}

function formatTenureDuration(start, end) {
  const days = Math.max(1, Math.round((Math.max(start, end) - Math.min(start, end)) / DAY_MS) + 1);
  if (days < 31) return `${days} ${days === 1 ? "dia" : "dias"}`;
  const months = Math.max(1, Math.round(days / 30));
  if (months < 12) return `${months} ${months === 1 ? "mês" : "meses"}`;
  const years = Math.floor(months / 12);
  const rest = months % 12;
  return rest ? `${years}a ${rest}m` : `${years} ${years === 1 ? "ano" : "anos"}`;
}

// Os agentes mais escolhidos, com a taxa de escolha no title. Sao tres icones
// e nao uma coluna de texto: e o dado que diz o que a pessoa joga, e ele nao
// cabe em numero.
function teamStatsAgentCell(pool) {
  if (!pool?.length) return `<span class="team-stats-agents empty">-</span>`;
  return `
    <span class="team-stats-agents">
      ${pool
        .map(
          (linha) => `
            <span class="team-stats-agent" title="${escapeHtml(`${linha.agent} - ${fmt(linha.rate, 0)}% dos mapas`)}">
              ${linha.agentIcon ? `<img src="${escapeHtml(assetPath(linha.agentIcon))}" alt="${escapeHtml(linha.agent)}" loading="lazy" />` : escapeHtml(linha.agent.slice(0, 2))}
            </span>
          `,
        )
        .join("")}
    </span>
  `;
}

// Na tela estreita a tabela de estatísticas vira blocos, sem rolagem lateral, e
// cada número precisa do nome da coluna ao lado dele.
function tabelaComRotulos(html) {
  const molde = document.createElement("template");
  molde.innerHTML = html;
  const tabela = molde.content?.querySelector("table");
  if (!tabela) return html;
  const colunas = [...tabela.querySelectorAll("thead th")];
  const nomes = colunas.map((th) => (th.querySelector("span") || th).textContent.trim());
  tabela.querySelectorAll("tbody tr").forEach((linha) => {
    [...linha.children].forEach((celula, indice) => {
      if (nomes[indice] && celula.colSpan === 1) celula.dataset.label = nomes[indice];
      // Coluna identificada só por imagem, como a de agente: a imagem vai junto.
      if (!nomes[indice] && colunas[indice]?.firstElementChild) {
        const rotulo = document.createElement("span");
        rotulo.className = "rotulo-imagem";
        rotulo.append(colunas[indice].firstElementChild.cloneNode(true));
        celula.prepend(rotulo);
      }
    });
  });
  return molde.innerHTML;
}

function renderPlayerDetail(id) {
  const player = playerById(id);
  if (!playerTemPerfil(player)) return renderNotFound("Jogador");
  const matches = matchSeriesForPlayer(player.id);
  const team = playerPrimaryTeam(player);
  const jogos = playerJogos(player, matches);
  // Sem equipe atual, o jogador veste a cor da ultima, como na lista de Jogadores.
  const cor = team || teamById(jogos[0]?.nossa) || teamById(player.teamId) || null;
  const tournamentRows = playerTournamentRows(player, matches);
  const teamRows = playerTeamHistoryRows(player, matches, tournamentRows);
  const trophies = playerTrophyAchievements(player, tournamentRows);
  const abas = playerAbasVisiveis(matches, tournamentRows);
  const pedida = normalizePlayerTab(route().tab);
  const activeTab = abas.includes(pedida) ? pedida : "resumo";
  const tabSlide = panelSlideSnapshot("player-tabs", {
    selector: ".team-tab-panel",
    scope: player.id,
    key: activeTab,
    order: PLAYER_TAB_KEYS,
  });
  Shell(`
    <section class="team-page vp-perfil" ${playerAccentStyle(cor)}>
      <div class="vp-capa-cabeca">
        ${playerCapa(player, team, cor, trophies)}
        <nav class="team-tabs" aria-label="Abas do jogador">
          ${abas.map((tab) => playerTabLink(player, tab, PLAYER_TAB_ROTULOS[tab], activeTab)).join("")}
        </nav>
      </div>
      <section class="team-tab-panel">
        ${renderPlayerTab(activeTab, player, { matches, team, jogos, teamRows, tournamentRows, trophies })}
      </section>
      ${window.Comments ? window.Comments.shell("player", playerRouteId(player.id)) : ""}
    </section>
  `);
  window.Comments?.montar("player", playerRouteId(player.id));
  bindAbaDaEquipe(player.id, renderPlayerDetail);
  playPanelSlide(tabSlide);
}

const PLAYER_TAB_KEYS = ["resumo", "carreira", "partidas", "campeonatos", "estatisticas"];
const PLAYER_TAB_ROTULOS = { resumo: "Visão Geral", carreira: "Carreira", partidas: "Partidas", campeonatos: "Campeonatos", estatisticas: "Estatísticas" };

// Os enderecos das sete abas antigas continuam abrindo o assunto certo.
function normalizePlayerTab(tab) {
  if (tab === "carreira" || tab === "equipes" || tab === "teams") return "carreira";
  if (tab === "partidas" || tab === "matches") return "partidas";
  if (tab === "campeonatos" || tab === "resultados" || tab === "results" || tab === "trofeus" || tab === "troféus" || tab === "trophies") return "campeonatos";
  if (tab === "estatisticas" || tab === "agentes" || tab === "agents" || tab === "mapas" || tab === "maps") return "estatisticas";
  return "resumo";
}

// Aba sem dado nao aparece. Serie de campeonato oculto conta em Partidas, mas nao em
// Campeonatos: quem so jogou um deles fica sem a aba.
function playerAbasVisiveis(matches, tournamentRows) {
  return PLAYER_TAB_KEYS.filter((tab) => {
    if (tab === "campeonatos") return tournamentRows.length > 0;
    if (tab === "partidas" || tab === "estatisticas") return matches.length > 0;
    return true;
  });
}

function playerTabLink(player, tab, label, activeTab) {
  return `<a class="team-tab ${activeTab === tab ? "active" : ""}" href="${playerHref(player, tab)}">${escapeHtml(label)}</a>`;
}

function renderPlayerTab(activeTab, player, context) {
  const renderers = {
    resumo: () => playerSummaryTab(player, context),
    carreira: () => playerCarreiraTab(player, context),
    partidas: () => playerPartidasTab(player, context.jogos),
    campeonatos: () => playerCampeonatosTab(context),
    estatisticas: () => playerStatsTab(player, context.matches),
  };
  return (renderers[activeTab] || renderers.resumo)();
}

function playerPrimaryTeam(player) {
  if (player.currentTeam) return teamById(player.currentTeam);
  return (state.db?.teams || []).find((team) => (team.currentLineup || []).some((entry) => entry.playerId === player.id)) || null;
}

function playerAccentStyle(team) {
  if (team) return teamAccentStyle(team);
  return `style="--team-accent:#d8323c;--team-accent-2:#009a96;"`;
}

function playerNicksAnteriores(player) {
  return [...new Set((player.nickHistory || []).filter(Boolean))].filter((nick) => nick !== player.handle && nick !== player.nick);
}

// O topo do jogador e um Camisa grande: a pessoa e a identificacao na cor 1, os cinco
// numeros principais na cor 2 e os trofeus embaixo, so para quem tem. Cerca de 93% dos
// perfis nao tem foto: a silhueta e o logo apagado da equipe seguram a capa.
function playerCapa(player, team, cor, trophies) {
  const role = playerDominantRole(player);
  const anteriores = playerNicksAnteriores(player);
  const link = (time, texto) => `<a class="vp-cj-equipe" href="#/teams/${escapeHtml(time.id)}">${teamLogo(time.id)}<span>${escapeHtml(texto)}</span></a>`;
  const equipe = team ? link(team, team.name) : cor ? link(cor, `Última: ${cor.name}`) : `<span class="vp-cj-equipe">Sem equipe</span>`;
  const numeros = [
    [fmt(player.acs, 0), "ACS"],
    [fmt(player.adr, 0), "ADR"],
    [fmt(player.kd), "K/D"],
    [String(player.matches || 0), "Mapas"],
  ];
  return `
    <header class="vp-capa">
      <div class="vp-slide vp-cj" style="${escapeHtml(teamPlateStyle(cor))}">
        <span class="vp-slide-campo"><i></i></span>
        ${playerFigure(player, cor)}
        <div class="vp-cj-id">
          ${role ? `<span class="vp-cj-funcao" title="${escapeHtml(role.rounds ? `${role.label}, ${role.rounds} rounds` : role.label)}">${roleMiniIcon(role)}${escapeHtml(role.label)}</span>` : ""}
          <h1${player.nick.length > 12 ? ` class="vp-cj-longo"` : ""}>${escapeHtml(player.nick)}</h1>
          <span class="vp-cj-riot">${escapeHtml(player.handle || player.nick)}${anteriores.length ? `, antes ${escapeHtml(anteriores.slice(0, 2).join(", "))}` : ""}</span>
          <span class="vp-cj-acoes">${equipe}${window.Favorites ? window.Favorites.botao("player", playerRouteId(player.id)) : ""}</span>
        </div>
        <dl class="vp-cj-numeros">
          <div class="vp-cj-nota"><dd>${escapeHtml(playerRating(player))}</dd><dt>rAAting 3.0</dt></div>
          ${numeros.map(([valor, rotulo]) => `<div><dd>${escapeHtml(valor)}</dd><dt>${escapeHtml(rotulo)}</dt></div>`).join("")}
        </dl>
      </div>
      ${teamCapaTrofeus(trophies)}
    </header>
  `;
}

// O link so aparece quando a aba tem mais do que a Visao Geral ja mostra.
function playerSecaoComLink(titulo, player, aba, rotulo, temMais) {
  return temMais ? sectionHead(titulo, "", playerPath(player, aba), rotulo) : sectionHead(titulo);
}

// A aba de entrada responde "como esta o jogador": a forma, o que vem por ai, os
// numeros da carreira e os ultimos campeonatos. Quem jogou pouco fica so com o que tem.
function playerSummaryTab(player, context) {
  const { jogos, team } = context;
  const proximos = playerProximos(team);
  const campanhas = playerCampanhas(context.tournamentRows, context.trophies);
  const soma = aggregateMatchPlayers(playerEstMapas(player, context.matches, {}))[0];
  return `
    <div class="vp-equipe-corpo">
      <div class="vp-equipe-principal">
        ${playerForma(player, jogos)}
        ${proximos.length ? `
          <section class="vp-s-proximas">
            ${sectionHead(proximos.length === 1 ? "Próxima partida" : "Próximas partidas")}
            <div class="vp-lista">${proximos.map((jogo) => tournamentJogoSemArquivo(jogo.event, jogo)).join("")}</div>
          </section>
        ` : ""}
        ${soma ? `<section>${sectionHead("Números")}${fichaJogador(soma)}</section>` : ""}
        ${campanhas.length ? `
          <section>
            ${playerSecaoComLink("Últimos campeonatos", player, "campeonatos", `Ver os ${campanhas.length}`, campanhas.length > 5)}
            ${playerCampanhasLista(campanhas.slice(0, 5))}
          </section>
        ` : ""}
      </div>
      <aside class="vp-equipe-trilho">
        ${playerInformacoes(player, context)}
        <section class="vp-s-agentes">
          ${playerSecaoComLink("Agentes", player, "estatisticas", `Ver os ${(player.agentStats || []).length}`, (player.agentStats || []).length > 5)}
          ${agentesTrilho(player)}
        </section>
        <section class="vp-s-pormapa">
          ${playerSecaoComLink("Mapas", player, "estatisticas", `Ver os ${(player.mapStats || []).length}`, (player.mapStats || []).length > 5)}
          ${porMapaPlaca(player)}
        </section>
      </aside>
    </div>
  `;
}

// Uma linha por serie que o jogador jogou, no formato dos jogos da equipe. `nossa` e a
// equipe dele naquela serie: quem trocou de equipe tem as duas na mesma lista.
function playerJogos(player, matches) {
  return matches.map((series) => {
    const nossa = playerSeriesTeamId(series, player.id);
    const rival = series.teamA.id === nossa ? series.teamB.id : series.teamA.id;
    const placar = seriesScoreForTeam(series, nossa);
    const vencedor = series.winnerId || (placar.mapsFor > placar.mapsAgainst ? nossa : placar.mapsFor < placar.mapsAgainst ? rival : "");
    const event = state.db.tournaments.find((item) => item.id === series.eventId) || { id: series.eventId, name: series.eventName || "Outros jogos" };
    return { series, event, nossa, match: null, quando: series.sortAt || series.startedAt, equipes: [nossa, rival], vencedor, perdedor: vencedor && (vencedor === nossa ? rival : nossa) };
  });
}

function playerForma(player, jogos) {
  const ultimas = jogos.filter((jogo) => jogo.vencedor).slice(0, TEAM_RESUMO_PARTIDAS);
  if (!ultimas.length) return "";
  return `
    <section class="vp-s-forma">
      ${playerSecaoComLink(ultimas.length === 1 ? "Última partida" : "Últimas partidas", player, "partidas", `Ver as ${jogos.length}`, jogos.length > ultimas.length)}
      <div class="vp-forma">${ultimas.map((jogo) => teamFormaItem({ id: jogo.nossa }, jogo)).join("")}</div>
    </section>
  `;
}

// O que a equipe atual ainda vai jogar. A escalacao de uma partida futura nao existe,
// entao vale a equipe.
function playerProximos(team) {
  if (!team) return [];
  const series = matchSeriesForTeam(team.id);
  const emAberto = teamCampeonatos(team, series, []).filter((event) => !eventIsDone(event));
  return teamJogos(team, emAberto, series).filter((jogo) => !jogo.series && !jogo.vencedor && !jogo.match?.status && !eventIsDone(jogo.event));
}

// Campeonato com 1 ou 2 mapas nao entra: a nota dele diz mais do acaso que do jogador.
const PLAYER_EVOLUCAO_MAPAS = 3;
// A escala e igual para todos, como a do ranking, e cobre 98% das notas por campeonato.
const PLAYER_EVOLUCAO_TETO = 1.6;
const PLAYER_EVOLUCAO_PISO = 0.6;
const PLAYER_EVOLUCAO_REGUA = [0.6, 0.8, 1, 1.2, 1.4, 1.6];

// O rAAting por campeonato, do mais antigo ao mais recente. Cada campeonato ocupa a
// mesma largura, porque etapas da mesma semana cairiam uma em cima da outra num eixo
// de datas, e o logo embaixo diz qual e cada ponto.
function playerEvolucao(tournamentRows) {
  const rows = tournamentRows.filter((row) => row.principal && row.rating && row.maps >= PLAYER_EVOLUCAO_MAPAS).reverse();
  if (rows.length < 2) return "";
  const width = 760;
  const height = 250;
  const pad = { top: 12, right: 14, bottom: 12, left: 38 };
  const plotWidth = width - pad.left - pad.right;
  const x = (indice) => pad.left + ((indice + 0.5) / rows.length) * plotWidth;
  const y = (nota) => pad.top + ((PLAYER_EVOLUCAO_TETO - clamp(Number(nota), PLAYER_EVOLUCAO_PISO, PLAYER_EVOLUCAO_TETO)) / (PLAYER_EVOLUCAO_TETO - PLAYER_EVOLUCAO_PISO)) * (height - pad.top - pad.bottom);
  const colunas = rows.map((row, indice) => (x(indice) / width) * 100);
  const metade = (plotWidth / rows.length / width) * 50;
  const melhor = Math.max(...rows.map((row) => row.rating));
  const pontos = rows.map((row, indice) => `${fmt(x(indice), 2)},${fmt(y(row.rating), 2)}`).join(" ");
  // Os mapas de cada campeonato em barras no pe do grafico, ate 40% da altura, atras da linha.
  const chao = height - pad.bottom;
  const maisMapas = Math.max(...rows.map((row) => row.maps), 1);
  const larguraBarra = (plotWidth / rows.length) * 0.56;
  const barras = rows.map((row, indice) => {
    const alto = (row.maps / maisMapas) * (chao - pad.top) * 0.4;
    return `<rect x="${fmt(x(indice) - larguraBarra / 2, 2)}" y="${fmt(chao - alto, 2)}" width="${fmt(larguraBarra, 2)}" height="${fmt(alto, 2)}"></rect>`;
  }).join("");
  return `
    <section>
      ${sectionHead("rAAting por campeonato")}
      <div class="ranking-chart-card vp-evolucao">
        <dl class="ranking-chart-kpis">
          <div><dd>${escapeHtml(fmt(rows.at(-1).rating))}</dd><dt>Último</dt></div>
          <div><dd>${escapeHtml(fmt(melhor))}</dd><dt>Melhor</dt></div>
          <div><dd>${rows.length}</dd><dt>Campeonatos</dt></div>
        </dl>
        <div class="ranking-chart-stage">
          <svg class="ranking-line-chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="rAAting por campeonato">
            <g class="ranking-chart-grid">
              ${PLAYER_EVOLUCAO_REGUA.map((nota) => `<line${nota === 1 ? ` class="vp-ev-media"` : ""} x1="${pad.left}" x2="${width - pad.right}" y1="${fmt(y(nota), 2)}" y2="${fmt(y(nota), 2)}"></line>`).join("")}
            </g>
            <g class="vp-ev-barras">${barras}</g>
            <polyline class="ranking-chart-line" points="${pontos}"></polyline>
          </svg>
          <div class="ranking-chart-axis" aria-hidden="true">
            ${PLAYER_EVOLUCAO_REGUA.map((nota) => `<span style="--t:${fmt((y(nota) / height) * 100, 2)}">${escapeHtml(fmt(nota))}</span>`).join("")}
          </div>
          <div class="ranking-chart-hotspots" style="--n:${rows.length}">
            ${rows.map((row, indice) => `
              <a class="ranking-chart-hotspot${colunas[indice] < 35 ? " na-esquerda" : colunas[indice] > 65 ? " na-direita" : ""}" href="#/tournaments/${escapeHtml(row.event.id)}" style="--esq:${fmt(colunas[indice] - metade, 3)};--larg:${fmt(metade * 2, 3)};--c:50;--y:${fmt((y(row.rating) / height) * 100, 2)}" aria-label="${escapeHtml(`${row.event.name}, rAAting ${fmt(row.rating)}`)}">
                <span class="ranking-chart-tooltip">
                  <strong>${escapeHtml(fmt(row.rating))}</strong>
                  <span>${escapeHtml(row.event.name)}</span>
                  <small>${row.maps} ${row.maps === 1 ? "mapa" : "mapas"}</small>
                </span>
              </a>
            `).join("")}
          </div>
        </div>
        <div class="vp-ev-logos" aria-hidden="true">
          ${rows.map((row, indice) => `<a href="#/tournaments/${escapeHtml(row.event.id)}" style="--t:${fmt(colunas[indice], 3)}" title="${escapeHtml(row.event.name)}" tabindex="-1">${eventLogo(row.event, "tiny")}</a>`).join("")}
        </div>
      </div>
    </section>
  `;
}

function playerInformacoes(player, { matches, jogos, teamRows, tournamentRows, trophies }) {
  const datas = matches.map((series) => dateValue(series.startedAt)).filter(Boolean);
  const vitorias = jogos.filter((jogo) => jogo.vencedor === jogo.nossa).length;
  const derrotas = jogos.filter((jogo) => jogo.perdedor === jogo.nossa).length;
  const titulos = trophies.filter((trophy) => trophy.trophyKey === "champion").length;
  const mvps = matches.flatMap((series) => series.maps || []).filter((match) => (match.mvp?.id || match.mvp) === player.id).length;
  const linhas = [
    datas.length ? ["Primeira partida", formatDate(Math.min(...datas), "date")] : null,
    datas.length ? ["Última partida", formatDate(Math.max(...datas), "date")] : null,
    ["Séries", `${vitorias}-${derrotas}`],
    ["Aproveitamento", pct(vitorias + derrotas ? (vitorias / (vitorias + derrotas)) * 100 : 0)],
    ["Campeonatos", String(tournamentRows.filter((row) => row.principal).length)],
    ["Equipes", String(teamRows.length)],
    titulos ? ["Títulos", String(titulos)] : null,
    mvps ? ["MVP de mapa", String(mvps)] : null,
  ].filter(Boolean);
  return `
    <section>
      ${sectionHead("Informações")}
      <dl class="vp-ficha">${linhas.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${escapeHtml(valor)}</dd></div>`).join("")}</dl>
    </section>
  `;
}

// Os numeros do jogador: os seis principais em destaque e o resto em tabelas por
// assunto, nas linhas de Informacoes. As metricas da rAAting 3.0 entram so quando
// existe valor: quem so tem partida antiga fica sem a coluna.
function fichaJogador(player) {
  const rounds = Number(player.rounds || 0);
  const kMenosD = Number(player.kills || 0) - Number(player.deaths || 0);
  const fkFd = Number(player.firstKills || 0) - Number(player.firstDeaths || 0);
  const swing = playerSwingPerRound(player);
  const tom = (valor) => (valor > 0 ? "vp-bom" : valor < 0 ? "vp-ruim" : "");
  const destaque = [
    ["rAAting 3.0", playerRating(player)],
    ["K/D", fmt(player.kd)],
    ["ACS", fmt(player.acs, 0)],
    ["ADR", fmt(player.adr, 0)],
    ["KAST", pct(player.kast)],
    ["Swing/R", formatMaybeSwing(player), Number.isFinite(swing) ? tom(swing) : ""],
  ];
  const metricas = [
    ["eKPR", formatMaybeMetric(player, "ekpr")],
    ["eDPR", formatMaybeMetric(player, "edpr")],
    ["eADR", formatMaybeMetric(player, "eadr", 0)],
    ["eKAST", formatMaybePercent(player, "ekast")],
    ["MK/R", formatMaybeMetric(player, "mk_per_r")],
  ];
  const grupos = [
    ["Geral", [["Mapas", player.matches || 0], ["Rounds", rounds], ["Kills", player.kills || 0], ["Deaths", player.deaths || 0], ["Assists", player.assists || 0], ["K-D", signed(kMenosD), tom(kMenosD)], ["HS%", pct(player.hs)]]],
    ["Por round", [["KPR", fmt(player.kpr)], ["DPR", fmt(player.dpr)], ["APR", fmt(player.apr)], ["FKPR", fmt(rounds ? Number(player.firstKills || 0) / rounds : 0)], ["FDPR", fmt(rounds ? Number(player.firstDeaths || 0) / rounds : 0)]]],
    ["Abertura e trades", [
      ["First kills", player.firstKills || 0],
      ["First deaths", player.firstDeaths || 0],
      ["FK-FD", signed(fkFd), tom(fkFd)],
      ["Trade kills", formatMaybeMetric(player, "tradeKills", 0)],
      ["Mortes tradadas", formatMaybeMetric(player, "tradedDeaths", 0)],
      ["Mortes sem trade", formatMaybeMetric(player, "failedTradeDeaths", 0)],
      ["Trade denials", formatMaybeMetric(player, "tradeDenials", 0)],
      ["Saves em derrota", formatMaybeMetric(player, "savedLossRounds", 0)],
      ["Sobrev. em vitória", formatMaybeMetric(player, "survivedWinRounds", 0), "", "Sobrevivências em rounds vencidos."],
    ]],
    metricas.some(([, valor]) => valor !== "-") ? ["Métricas rAAting 3.0", metricas] : null,
  ].filter(Boolean);
  const valor = (classe, texto) => `<dd${classe ? ` class="${classe}"` : ""}>${escapeHtml(String(texto))}</dd>`;
  return `
    <div class="vp-nm">
      <dl class="vp-nm-topo">${destaque.map(([rotulo, texto, classe = ""]) => `<div>${valor(classe, texto)}<dt>${escapeHtml(rotulo)}</dt></div>`).join("")}</dl>
      <div class="vp-nm-colunas" style="--n:${grupos.length}">
        ${grupos.map(([titulo, itens]) => `
          <div class="vp-nm-col">
            <h3>${escapeHtml(titulo)}</h3>
            <dl class="vp-ficha">${itens.map(([rotulo, texto, classe = "", dica = ""]) => `<div${dica ? ` title="${escapeHtml(dica)}"` : ""}><dt>${escapeHtml(rotulo)}</dt>${valor(classe, texto)}</div>`).join("")}</dl>
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

// Abates e mortes do jogador na serie inteira, somando os mapas. As linhas de
// jogador de cada mapa existem mesmo antes de o detalhe da partida carregar.
function kdDoJogadorNaSerie(player, series) {
  const linhas = (series?.maps || []).map((mapa) => (mapa.players || []).find((linha) => linha.id === player.id)).filter(Boolean);
  if (!linhas.length) return null;
  return [linhas.reduce((soma, linha) => soma + Number(linha.kills || 0), 0), linhas.reduce((soma, linha) => soma + Number(linha.deaths || 0), 0)];
}

// Os cinco agentes mais jogados, nas linhas de Informacoes: mapas e parte do total.
function agentesTrilho(player) {
  const agentes = (player.agentStats || []).slice(0, 5);
  if (!agentes.length) return `<div class="empty-state">Sem agentes registrados.</div>`;
  return `
    <div class="vp-campanhas">
      ${agentes.map((agente) => {
        const picks = Number(agente.picks || 0);
        const icone = agente.icon || agente.agentIcon || "";
        return `
          <div class="vp-campanha vp-agl">
            ${icone ? `<img src="${escapeHtml(assetPath(icone))}" alt="" loading="lazy" onerror="this.style.visibility='hidden'" />` : "<span></span>"}
            <strong>${escapeHtml(agente.name || agente.agent || "Agente")}<small>${escapeHtml(agente.role || agente.agentClass || "")}</small></strong>
            <span class="vp-agl-n"><b>${picks}</b> ${picks === 1 ? "mapa" : "mapas"}</span>
            <span class="vp-agl-n"><b>${escapeHtml(pct(agente.rate))}</b></span>
          </div>
        `;
      }).join("")}
    </div>
  `;
}

// Os cinco mapas mais jogados, nas linhas de Informacoes, com a arte do mapa ao lado.
function porMapaPlaca(player) {
  const mapas = (player.mapStats || []).slice().sort((a, b) => Number(b.matches || 0) - Number(a.matches || 0)).slice(0, 5);
  if (!mapas.length) return `<div class="empty-state">Sem mapas registrados.</div>`;
  const tom = (nota) => (nota >= 1.1 ? "vp-bom" : nota < 0.9 ? "vp-ruim" : "");
  return `
    <div class="vp-campanhas">
      <div class="vp-mpl vp-mpl-cab" aria-hidden="true"><span></span><span>Mapa</span><span>Mapas</span><span>rAAting</span><span>ACS</span></div>
      ${mapas.map((row) => {
        const arte = matchMapAsset({ mapName: row.name });
        return `
          <a class="vp-campanha vp-mpl" href="#/maps/${escapeHtml(slugify(row.name))}">
            ${arte.src ? `<img src="${escapeHtml(arte.src)}" data-fallback="${escapeHtml(arte.fallback)}" alt="" loading="lazy" onerror="mapArtError(this)" />` : "<span></span>"}
            <strong>${escapeHtml(row.name)}</strong>
            <span>${escapeHtml(String(row.matches || 0))}</span>
            <span class="vp-pm-nota ${tom(Number(row.rating))}">${escapeHtml(fmt(row.rating))}</span>
            <span>${escapeHtml(fmt(row.acs, 0))}</span>
          </a>
        `;
      }).join("")}
    </div>
  `;
}

function ratingComponentDefinitions() {
  return [
    { key: "kill_rating", label: "KillRating", description: "Produção de kills ajustada por economia e contexto." },
    { key: "damage_rating", label: "DamageRating", description: "Dano efetivo ajustado por economia." },
    { key: "round_swing_rating", label: "RoundSwingRating", description: "Impacto médio do jogador na chance de vitória dos rounds." },
    { key: "survival_rating", label: "SurvivalRating", description: "Qualidade de sobrevivência e mortes, incluindo trades, opening deaths e saves em derrota." },
    { key: "kast_rating", label: "KASTRating", description: "Participação útil em rounds: kill, assistência, sobrevivência em round vencido ou morte tradada." },
    { key: "multi_kill_rating", label: "MultiKillRating", description: "Explosividade em rounds com 2K, 3K, 4K ou 5K." },
  ];
}

// A aba Carreira: as faixas sao a titularidade e a tabela e o elenco, com as mesmas
// regras da pagina de equipe, para os dois lados contarem a mesma historia.
function playerCarreiraTab(player, { teamRows, tournamentRows }) {
  const linhas = playerPassagens(player, teamRows);
  const movimentos = playerMovimentos(linhas);
  const nicks = playerNicksAnteriores(player);
  return `
    <div class="vp-equipe-corpo">
      <div class="vp-equipe-principal">
        <section class="vp-s-linha-do-tempo">
          ${sectionHead("Linha do tempo")}
          ${playerTeamTimelineChart(linhas)}
        </section>
        <section>
          ${sectionHead("Equipes", `${linhas.length} ${linhas.length === 1 ? "equipe" : "equipes"}`)}
          ${playerPassagensTabela(player, linhas)}
        </section>
        ${playerEvolucao(tournamentRows)}
      </div>
      <aside class="vp-equipe-trilho">
        ${movimentos.length ? `<section>${sectionHead("Entradas e saídas")}<div class="vp-movimentos">${movimentos.map(playerMovimentoLinha).join("")}</div></section>` : ""}
        ${nicks.length ? `<section>${sectionHead("Nicks anteriores")}<ul class="vp-pf-nicks">${nicks.map((nick) => `<li>${escapeHtml(nick)}</li>`).join("")}</ul></section>` : ""}
      </aside>
    </div>
  `;
}

// Quem nao fica com nenhuma passagem na equipe e stand-in dela, mas a carreira dele
// mostra essa partida do mesmo jeito: a faixa vem das datas dos mapas que ele jogou.
function playerPassagens(player, teamRows) {
  return teamRows.map((row) => {
    const passagens = row.team ? teamPassagens(row.team, matchSeriesForTeam(row.teamId)) : null;
    const validos = passagens?.jogadores.get(player.id) || null;
    const trechos = validos || (row.start && row.end ? [{ inicio: row.start, fim: row.end, mapas: row.maps, eventos: new Set() }] : []);
    const elenco = teamPassagensDeElenco(trechos);
    return {
      ...row,
      trechos,
      elenco,
      standin: Boolean(row.maps && !validos),
      ultimoMapa: passagens?.ultimoMapa || 0,
      resumo: trechos.length ? teamResumoDosTrechos(elenco, row.current, passagens?.totais.get(player.id) || row.maps) : null,
    };
  });
}

function playerPassagensTabela(player, linhas) {
  return `
    <div class="vp-elenco-tabela">
      <div class="vp-et vp-et-car vp-et-cab" aria-hidden="true"><span></span><span>Equipe</span><span>Período</span><span>Tempo</span><span>Mapas</span><span>Séries</span><span>rAAting</span><span>ACS</span><span>K:D</span><span>Troféus</span></div>
      ${linhas.map((linha) => {
        const nome = linha.team?.name || linha.teamId;
        const nota = linha.current ? "Equipe atual" : linha.standin ? "Stand-in" : "";
        const miolo = `
          ${teamLogo(linha.teamId, "vp-et-logo")}
          <span class="vp-et-nome"><b>${escapeHtml(nome)}</b>${nota ? `<small>${escapeHtml(nota)}</small>` : ""}</span>
          <span class="vp-et-c vp-et-periodos" data-rotulo="Período">${(linha.resumo?.periodos || ["-"]).map((periodo) => `<span>${escapeHtml(periodo)}</span>`).join("")}</span>
          <span class="vp-et-n" data-rotulo="Tempo">${escapeHtml(linha.resumo?.duracao || "-")}</span>
          <span class="vp-et-n" data-rotulo="Mapas">${linha.maps}</span>
          <span class="vp-et-n" data-rotulo="Séries">${linha.series}</span>
          ${teamElencoNumeros(player, { id: linha.teamId })}
          <span class="vp-et-n" data-rotulo="Troféus">${linha.trophies.length}</span>
        `;
        return linha.team ? `<a class="vp-et vp-et-car" href="#/teams/${escapeHtml(linha.teamId)}">${miolo}</a>` : `<span class="vp-et vp-et-car">${miolo}</span>`;
      }).join("")}
    </div>
  `;
}

// Na mesma regra da equipe: saiu do elenco so quem ficou 4 meses sem jogar, e quem
// jogou ate o fim da equipe nao "saiu", foi ela que parou.
function playerMovimentos(linhas) {
  const folga = 14 * DAY_MS;
  return linhas
    .filter((linha) => !linha.standin)
    .flatMap((linha) => linha.elenco.flatMap((trecho, indice, trechos) => [
      { tipo: indice ? "Voltou" : "Entrou", data: trecho.inicio, linha },
      (linha.current && indice === trechos.length - 1) || linha.ultimoMapa - trecho.fim <= folga ? null : { tipo: "Saiu", data: trecho.fim, linha },
    ]))
    .filter(Boolean)
    .sort((a, b) => b.data - a.data);
}

function playerMovimentoLinha({ tipo, data, linha }) {
  const corpo = `
    ${teamLogo(linha.teamId, "vp-et-logo")}
    <span class="vp-et-nome"><b>${escapeHtml(linha.team?.name || linha.teamId)}</b><small>${escapeHtml(formatDate(data, "date"))}</small></span>
    <span class="vp-mov-tipo${tipo === "Saiu" ? "" : " vp-mov-entrou"}">${escapeHtml(tipo)}</span>
  `;
  return linha.team ? `<a class="vp-movimento" href="#/teams/${escapeHtml(linha.teamId)}">${corpo}</a>` : `<span class="vp-movimento">${corpo}</span>`;
}

function playerPartidasFiltro() {
  const query = routeQuery();
  return { evento: query.get("evento") || "", equipe: query.get("equipe") || "", mapa: query.get("mapa") || "", resultado: query.get("resultado") || "" };
}

// Cada filtro ignora a si mesmo na hora de contar a propria faceta, como em Partidas.
function playerJogoPassa(jogo, filtro, ignorar = "") {
  if (ignorar !== "evento" && filtro.evento && jogo.event.id !== filtro.evento) return false;
  if (ignorar !== "equipe" && filtro.equipe && jogo.nossa !== filtro.equipe) return false;
  if (ignorar !== "mapa" && filtro.mapa && !jogo.series.maps.some((match) => match.mapId === filtro.mapa)) return false;
  if (ignorar !== "resultado" && filtro.resultado === "v" && jogo.vencedor !== jogo.nossa) return false;
  if (ignorar !== "resultado" && filtro.resultado === "d" && jogo.perdedor !== jogo.nossa) return false;
  return true;
}

function playerJogoLinha(player, jogo) {
  const kd = kdDoJogadorNaSerie(player, jogo.series);
  return teamJogoLinha({ id: jogo.nossa }, jogo, kd ? kd.join("-") : "-");
}

function playerPartidasNumeros(player, jogos) {
  const vitorias = jogos.filter((jogo) => jogo.vencedor === jogo.nossa).length;
  const derrotas = jogos.filter((jogo) => jogo.perdedor === jogo.nossa).length;
  const soma = jogos.reduce((total, jogo) => {
    const placar = seriesScoreForTeam(jogo.series, jogo.nossa);
    const kd = kdDoJogadorNaSerie(player, jogo.series) || [0, 0];
    return { mapas: total.mapas + placar.mapsFor, contra: total.contra + placar.mapsAgainst, kills: total.kills + kd[0], deaths: total.deaths + kd[1] };
  }, { mapas: 0, contra: 0, kills: 0, deaths: 0 });
  const linhas = [
    ["Séries", `${vitorias}-${derrotas}`],
    ["Aproveitamento", pct(vitorias + derrotas ? (vitorias / (vitorias + derrotas)) * 100 : 0)],
    ["Mapas", `${soma.mapas}-${soma.contra}`],
    ["Abates e mortes", `${soma.kills}-${soma.deaths}`],
  ];
  return `<dl class="vp-ficha">${linhas.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${escapeHtml(valor)}</dd></div>`).join("")}</dl>`;
}

function playerPartidasFiltros(player, jogos, filtro) {
  const eventos = [...new Map(jogos.filter((jogo) => playerJogoPassa(jogo, filtro, "evento")).map((jogo) => [jogo.event.id, jogo.event])).values()]
    .sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  const equipes = [...new Set(jogos.filter((jogo) => playerJogoPassa(jogo, filtro, "equipe")).map((jogo) => jogo.nossa).filter(Boolean))]
    .map((id) => ({ id, nome: teamById(id)?.name || displayTeamName(id) }))
    .sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"));
  const paraResultado = jogos.filter((jogo) => playerJogoPassa(jogo, filtro, "resultado"));
  const ativo = filtro.evento || filtro.equipe || filtro.mapa || filtro.resultado;
  const botao = (valor, rotulo, quantos) => `<button type="button" data-eq-alterna="resultado" data-valor="${valor}" aria-pressed="${filtro.resultado === valor}">${rotulo} <b>${quantos}</b></button>`;
  return `
    <aside class="vp-resumo" aria-label="Filtros das partidas">
      <section class="vp-resumo-bloco vp-jogos-filtro">
        <h3>Filtros ${ativo ? `<button type="button" class="vp-filtros-limpar" data-eq-limpar>Limpar filtros</button>` : ""}</h3>
        <select data-eq-filtro="evento" aria-label="Filtrar por campeonato"><option value="">Todos os campeonatos</option>${teamOpcoes(eventos.map((event) => ({ id: event.id, nome: event.name })), filtro.evento)}</select>
        ${equipes.length > 1 || filtro.equipe ? `<select data-eq-filtro="equipe" aria-label="Filtrar por equipe"><option value="">Todas as equipes</option>${teamOpcoes(equipes, filtro.equipe)}</select>` : ""}
        <div class="vp-eq-escolha">
          ${botao("v", "Vitórias", paraResultado.filter((jogo) => jogo.vencedor === jogo.nossa).length)}
          ${botao("d", "Derrotas", paraResultado.filter((jogo) => jogo.perdedor === jogo.nossa).length)}
        </div>
      </section>
      ${playerPartidasNumeros(player, jogos.filter((jogo) => playerJogoPassa(jogo, filtro)))}
    </aside>
  `;
}

function playerPartidasTab(player, jogos) {
  const filtro = playerPartidasFiltro();
  const visiveis = jogos.filter((jogo) => playerJogoPassa(jogo, filtro));
  const { grupos, paginador } = jogosNaPagina(visiveis);
  const contagem = visiveis.length < jogos.length ? `${visiveis.length} de ${jogos.length} séries` : `${jogos.length} ${jogos.length === 1 ? "série" : "séries"}`;
  return `
    <section class="vp-eq-aba vp-eq-partidas vp-jogos vp-pf-partidas">
      ${playerPartidasFiltros(player, jogos, filtro)}
      <div class="vp-jogos-lista">
        ${sectionHead("Partidas", contagem)}
        ${grupos.length ? teamJogosGrupos(null, grupos, (jogo) => playerJogoLinha(player, jogo)) : `<div class="empty-state">Nenhuma partida com esses filtros. Tire um filtro para ver mais.</div>`}
        ${paginador}
      </div>
      ${teamPartidasMapas(jogos.filter((jogo) => playerJogoPassa(jogo, filtro, "mapa")), filtro)}
    </section>
  `;
}

// As campanhas do jogador, no formato das da equipe: o trofeu fica na linha do
// campeonato, e o premio de MVP, que e so dele, ao lado.
function playerCampanhas(tournamentRows, trophies) {
  const ordem = { live: 0, scheduled: 1, done: 2 };
  return tournamentRows
    .map((row) => {
      const estado = eventStatusClass(row.event.status);
      const doCampeonato = trophies.filter((trophy) => trophy.event.id === row.event.id && (!trophy.teamId || trophy.teamId === row.teamId));
      return {
        ...row,
        estado: estado in ordem ? estado : "live",
        trofeu: doCampeonato.find((trophy) => trophy.trophyKey !== "mvp") || null,
        mvp: doCampeonato.find((trophy) => trophy.trophyKey === "mvp") || null,
        colocacao: teamTournamentPlacementBlock(row.event, row.campaign),
      };
    })
    .sort((a, b) => ordem[a.estado] - ordem[b.estado]);
}

function playerCampanhaLinha({ event, team, trofeu, mvp, colocacao, series, maps, rating, acs }) {
  return `
    <a class="vp-cp vp-cp-jog" href="#/tournaments/${escapeHtml(event.id)}">
      ${eventLogo(event, "vp-cp-logo")}
      <span class="vp-cp-nome"><strong title="${escapeHtml(event.name)}"><span class="nome-rolante">${escapeHtml(event.name)}</span></strong><small>${escapeHtml([eventTimeRange(event), team?.name].filter(Boolean).join(", "))}</small></span>
      <span class="vp-cp-tier" data-rotulo="Tier">${event.tier ? eventTierBadge(event) : ""}</span>
      <span class="vp-cp-lugar" data-rotulo="Colocação"><span class="team-placement-badge ${escapeHtml(colocacao.tom)}"><strong>${escapeHtml(colocacao.valor)}</strong><small>${escapeHtml(colocacao.rotulo)}</small></span><span class="vp-cp-premios">${trofeu ? trophyVisual(trofeu) : ""}${mvp ? trophyVisual(mvp) : ""}</span></span>
      <span class="vp-cp-n" data-rotulo="Séries">${series}</span>
      <span class="vp-cp-n" data-rotulo="Mapas">${maps}</span>
      <span class="vp-cp-n" data-rotulo="rAAting">${rating ? escapeHtml(fmt(rating)) : "-"}</span>
      <span class="vp-cp-n" data-rotulo="ACS">${acs ? escapeHtml(fmt(acs, 0)) : "-"}</span>
    </a>
  `;
}

function playerCampanhasCabeca() {
  return `<div class="vp-cp-cab vp-cp-jog" aria-hidden="true"><span></span><span>Campeonato</span><span>Tier</span><span>Colocação</span><span>Séries</span><span>Mapas</span><span>rAAting</span><span>ACS</span></div>`;
}

function playerCampanhasLista(linhas) {
  return `${playerCampanhasCabeca()}<div class="vp-cp-lista">${linhas.map(playerCampanhaLinha).join("")}</div>`;
}

function playerCampeonatosTab({ tournamentRows, trophies }) {
  const filtro = teamCampeonatosFiltro();
  const linhas = playerCampanhas(tournamentRows, trophies);
  const visiveis = linhas.filter((linha) => teamCampanhaPassa(linha, filtro));
  const distintos = (rows) => new Set(rows.map((linha) => linha.event.id)).size;
  const total = distintos(linhas);
  const contagem = distintos(visiveis) < total ? `${distintos(visiveis)} de ${total} campeonatos` : `${total} ${total === 1 ? "campeonato" : "campeonatos"}`;
  const grupos = TEAM_TOURNAMENT_GROUPS.map((grupo) => ({ ...grupo, linhas: visiveis.filter((linha) => linha.estado === grupo.key) })).filter((grupo) => grupo.linhas.length);
  return `
    <section class="vp-eq-aba vp-jogos">
      <div class="vp-jogos-lista">
        ${sectionHead("Campeonatos", contagem)}
        ${grupos.length ? playerCampanhasCabeca() : `<div class="empty-state">Nenhum campeonato com esses filtros. Tire um filtro para ver mais.</div>`}
        ${grupos.map((grupo) => `
          <section class="vp-jogos-grupo">
            <h3 class="vp-jogos-titulo">${escapeHtml(grupo.title)}<span>${grupo.linhas.length}</span></h3>
            <div class="vp-cp-lista">${grupo.linhas.map(playerCampanhaLinha).join("")}</div>
          </section>
        `).join("")}
      </div>
      ${teamCampeonatosResumo(linhas, filtro)}
    </section>
  `;
}

function playerSeriesTeamId(series, playerId) {
  const counts = new Map();
  for (const match of series?.maps || []) {
    const entry = playerInMatchTeam(match, playerId);
    if (!entry?.teamId) continue;
    counts.set(entry.teamId, (counts.get(entry.teamId) || 0) + 1);
  }
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])))[0]?.[0] || "";
}

function playerMapEmptyRow(key, map) {
  return {
    id: key,
    name: map.name || "Mapa",
    icon: map.icon || "",
    banner: mapArtAttrs(map)?.src || "",
    mapsPlayed: 0,
    rounds: 0,
    score: 0,
    kills: 0,
    deaths: 0,
    assists: 0,
    damage: 0,
    firstKills: 0,
    firstDeaths: 0,
    kastRounds: 0,
    impactTotal: 0,
    ...emptyRaatingAggregateFields(),
    headshots: 0,
    bodyshots: 0,
    legshots: 0,
    mapWins: 0,
    mapLosses: 0,
  };
}

function updatePlayerMapRow(row, player, match) {
  const rounds = Number(player.rounds || match.rounds || 0);
  if (!row.banner) {
    const asset = matchMapAsset(match);
    row.banner = asset.src || "";
  }
  row.mapsPlayed += 1;
  row.rounds += rounds;
  row.score += Number(player.score || 0);
  row.kills += Number(player.kills || 0);
  row.deaths += Number(player.deaths || 0);
  row.assists += Number(player.assists || 0);
  row.damage += Number(player.damage || 0);
  row.firstKills += Number(player.firstKills || 0);
  row.firstDeaths += Number(player.firstDeaths || 0);
  row.kastRounds += Number(player.kastRounds || 0);
  row.impactTotal += Number(player.impactTotal || 0);
  addRaatingAggregateFields(row, player);
  row.headshots += Number(player.headshots || 0);
  row.bodyshots += Number(player.bodyshots || 0);
  row.legshots += Number(player.legshots || 0);
  row.mapWins += match.winnerId === player.teamId ? 1 : 0;
  row.mapLosses += match.winnerId === player.teamId ? 0 : 1;
}

function playerFinalizeMapRow(row) {
  row.acs = row.rounds ? row.score / row.rounds : 0;
  row.adr = row.rounds ? row.damage / row.rounds : 0;
  row.kpr = row.rounds ? row.kills / row.rounds : 0;
  row.dpr = row.rounds ? row.deaths / row.rounds : 0;
  row.apr = row.rounds ? row.assists / row.rounds : 0;
  row.kd = row.deaths ? row.kills / row.deaths : row.kills;
  row.kastFrac = row.rounds ? row.kastRounds / row.rounds : 0;
  row.kast = row.kastFrac * 100;
  row.impactRound = row.rounds ? row.impactTotal / row.rounds : 0;
  row.impactRoundLegacy = row.rounds ? Number(row.impactTotalLegacy || 0) / row.rounds : 0;
  row.kastLegacyFrac = row.rounds ? Number(row.kastLegacyRounds || 0) / row.rounds : row.kastFrac;
  row.kastLegacy = row.kastLegacyFrac * 100;
  const shots = row.headshots + row.bodyshots + row.legshots;
  row.hs = shots ? (row.headshots / shots) * 100 : 0;
  applyRaatingFields(row);
  row.winRate = row.mapsPlayed ? pctValue(row.mapWins, row.mapsPlayed) : 0;
  return row;
}

function playerMapStatSort(a, b) {
  return b.rating - a.rating || b.mapsPlayed - a.mapsPlayed || b.rounds - a.rounds || a.name.localeCompare(b.name, "pt-BR");
}

function playerEstFiltro() {
  const query = routeQuery();
  return { ano: query.get("ano") || "", evento: query.get("evento") || "", equipe: query.get("equipe") || "", mapa: query.get("mapa") || "" };
}

function playerSerieAno(series) {
  const data = dateValue(series.startedAt);
  return data ? String(new Date(data).getFullYear()) : "";
}

// So a linha do jogador em cada mapa, sob os filtros da aba. Sem filtro, a soma desses
// mapas e o proprio perfil: e a mesma conta do numero da capa.
function playerEstMapas(player, matches, filtro) {
  const series = matches.filter((item) => (!filtro.evento || item.eventId === filtro.evento) && (!filtro.ano || playerSerieAno(item) === filtro.ano));
  const mapas = filtro.mapa ? tournamentFilteredMapMatches(series, filtro.mapa) : tournamentStatMapMatches(series);
  return mapas
    .map((match) => ({ ...match, players: (match.players || []).filter((row) => row.id === player.id && (!filtro.equipe || row.teamId === filtro.equipe)) }))
    .filter((match) => match.players.length);
}

function playerEstFiltros(jogos, matches, filtro) {
  const eventos = [...new Map(jogos.map((jogo) => [jogo.event.id, jogo.event])).values()].sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  const equipes = [...new Set(jogos.map((jogo) => jogo.nossa).filter(Boolean))].map((id) => ({ id, nome: teamById(id)?.name || displayTeamName(id) })).sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"));
  const anos = [...new Set(matches.map(playerSerieAno).filter(Boolean))].sort().reverse();
  const mapas = tournamentFilterMapOptions(matches);
  return `
    <div class="vp-est-filtros">
      ${anos.length > 1 ? `<select data-eq-filtro="ano" aria-label="Filtrar por ano"><option value="">Todos os anos</option>${teamOpcoes(anos.map((ano) => ({ id: ano, nome: ano })), filtro.ano)}</select>` : ""}
      <select data-eq-filtro="evento" aria-label="Filtrar por campeonato"><option value="">Todos os campeonatos</option>${teamOpcoes(eventos.map((event) => ({ id: event.id, nome: event.name })), filtro.evento)}</select>
      ${equipes.length > 1 ? `<select data-eq-filtro="equipe" aria-label="Filtrar por equipe"><option value="">Todas as equipes</option>${teamOpcoes(equipes, filtro.equipe)}</select>` : ""}
      <select data-eq-filtro="mapa" aria-label="Filtrar por mapa"><option value="">Todos os mapas</option>${teamOpcoes(mapas.map((mapa) => ({ id: mapa.id, nome: mapa.name })), filtro.mapa)}</select>
      ${filtro.ano || filtro.evento || filtro.equipe || filtro.mapa ? `<button type="button" class="vp-filtros-limpar" data-eq-limpar>Limpar filtros</button>` : ""}
    </div>
  `;
}

// A nota de 1,00 fica no meio da barra: para a direita o que puxa a rAAting para cima.
function playerComposicao(soma) {
  const linhas = ratingComponentDefinitions()
    .map((item) => ({ ...item, nota: metricValue(soma, item.key) }))
    .filter((item) => Number.isFinite(item.nota));
  if (!linhas.length) return "";
  return `
    <section class="vp-resumo-bloco">
      <h3>Composição da rAAting 3.0</h3>
      <div class="vp-cm">
        ${linhas.map(({ label, description, nota }) => `
          <div class="vp-cm-linha" title="${escapeHtml(description)}">
            <span>${escapeHtml(label.replace("Rating", ""))}</span>
            <i class="${nota >= 1 ? "vp-cm-mais" : "vp-cm-menos"}" style="--v:${fmt(clamp(Math.abs(nota - 1) * 2, 0, 1) * 50, 1)}%"></i>
            <b>${escapeHtml(fmt(nota))}</b>
          </div>
        `).join("")}
      </div>
    </section>
  `;
}

function playerMultiKills(soma) {
  const itens = [["2K", soma.twoKills], ["3K", soma.threeKills], ["4K", soma.fourKills], ["5K", soma.fiveKills]];
  return `
    <section class="vp-resumo-bloco">
      <h3>Multi-kills</h3>
      <dl class="vp-mk">${itens.map(([rotulo, valor]) => `<div><dd>${Number(valor || 0)}</dd><dt>${rotulo}</dt></div>`).join("")}</dl>
    </section>
  `;
}

// O Win% do campeonato tira os mapas espelhados porque la os dois lados contam.
// Aqui so existe o lado do jogador, e cada mapa e uma escolha dele.
function playerAgentRows(mapas) {
  return tournamentAgentRows(mapas).map((row) => ({ ...row, pickRate: pctValue(row.picks, mapas.length), nonMirroredPicks: row.picks, nonMirroredWins: row.mapWins, nonMirroredLosses: row.mapLosses, winRateNM: pctValue(row.mapWins, row.picks) }));
}

function playerAgentesBloco(mapas) {
  const ativoId = routeQuery().get("agente") || "";
  const agentes = playerAgentRows(mapas);
  if (!agentes.length) return "";
  const ativo = agentes.find((row) => row.id === ativoId) || null;
  const destaque = ativo || agentes[0];
  const dados = [
    ["Vitórias", `<b>${escapeHtml(pct(destaque.winRateNM))}</b> em ${destaque.picks} ${destaque.picks === 1 ? "mapa" : "mapas"}`],
    ["rAAting", `<b>${escapeHtml(fmt(destaque.rating))}</b>`],
    ["ACS", `<b>${escapeHtml(fmt(destaque.acs, 0))}</b>`],
    ["K:D", `<b>${escapeHtml(fmt(destaque.kd))}</b>`],
  ];
  const colunas = tournamentAgenteColunas(ativo?.id).filter((column) => !["uniquePlayers", "uniqueTeams", "semEspelho"].includes(column.key));
  return `
    <section class="vp-eq-bloco vp-est vp-ag-aba">
      <div class="vp-est-lista">
        ${tournamentEstTabela(null, { table: "agents", titulo: "Agentes", rows: agentes, columns: colunas, fallback: tournamentAgentStatSort, chave: "pagina-agentes", porPagina: 10, detalhe: true })}
      </div>
      <aside class="vp-resumo" aria-label="Agente em destaque">
        <div class="vp-mapa-resumo">
          ${tournamentAgenteCamisa(destaque, Boolean(ativo))}
          <dl class="vp-mapa-dados">${dados.map(([rotulo, valor]) => `<div><dt>${escapeHtml(rotulo)}</dt><dd>${valor}</dd></div>`).join("")}</dl>
        </div>
      </aside>
    </section>
  `;
}

function playerMapaColunas() {
  const coluna = (key, label, value, texto, opcoes = {}) => ({ key, label, value, texto, curta: true, celula: (row) => `<td class="numeric">${escapeHtml(texto(row))}</td>`, ...opcoes });
  return [
    {
      key: "map", label: "Mapa", value: (row) => row.name, type: "text", direction: "asc", curta: true,
      texto: (row) => row.name,
      celula: (row) => `<td><a class="vp-mj" href="#/maps/${escapeHtml(row.id)}">${row.banner ? `<img src="${escapeHtml(row.banner)}" alt="" loading="lazy" onerror="this.remove()" />` : ""}<strong>${escapeHtml(row.name)}</strong></a></td>`,
    },
    coluna("mapsPlayed", "Mapas", (row) => row.mapsPlayed, (row) => String(row.mapsPlayed)),
    coluna("mapWins", "V-D", (row) => row.mapWins, (row) => `${row.mapWins}-${row.mapLosses}`),
    coluna("winRate", "Win%", (row) => row.winRate, (row) => pct(row.winRate)),
    coluna("rounds", "Rnd", (row) => row.rounds, (row) => String(row.rounds), { curta: false }),
    coluna("rating", "rAAting", (row) => row.rating, (row) => fmt(row.rating)),
    coluna("acs", "ACS", (row) => row.acs, (row) => fmt(row.acs, 0)),
    coluna("kd", "K:D", (row) => row.kd, (row) => fmt(row.kd)),
    coluna("kast", "KAST", (row) => row.kast, (row) => pct(row.kast)),
    coluna("adr", "ADR", (row) => row.adr, (row) => fmt(row.adr, 0)),
    coluna("kpr", "KPR", (row) => row.kpr, (row) => fmt(row.kpr), { curta: false }),
    coluna("fkpr", "FKPR", (row) => (row.rounds ? row.firstKills / row.rounds : 0), (row) => fmt(row.rounds ? row.firstKills / row.rounds : 0), { curta: false }),
    coluna("fdpr", "FDPR", (row) => (row.rounds ? row.firstDeaths / row.rounds : 0), (row) => fmt(row.rounds ? row.firstDeaths / row.rounds : 0), { curta: false }),
    coluna("hs", "HS%", (row) => row.hs, (row) => pct(row.hs), { curta: false }),
  ];
}

function playerMapRows(playerId, mapas) {
  const rows = new Map();
  for (const match of mapas) {
    const player = (match.players || []).find((row) => row.id === playerId);
    if (!player) continue;
    const meta = mapById(match.mapId) || mapByName(match.mapName) || { id: match.mapId || normalizeNameKey(match.mapName), name: match.mapName || "Mapa" };
    const key = meta.id || normalizeNameKey(meta.name);
    if (!rows.has(key)) rows.set(key, playerMapEmptyRow(key, meta));
    updatePlayerMapRow(rows.get(key), player, match);
  }
  return [...rows.values()].map(playerFinalizeMapRow).sort(playerMapStatSort);
}

function playerMapasBloco(player, mapas) {
  const rows = playerMapRows(player.id, mapas);
  if (!rows.length) return "";
  const agentes = new Set(mapas.map((match) => agentStatsKey(match.players[0])));
  return `
    <section class="vp-eq-bloco vp-est vp-mapas vp-pf-mapas">
      <div class="vp-est-lista">
        ${tournamentEstTabela(null, { table: "maps", titulo: "Mapas", rows, columns: playerMapaColunas(), fallback: playerMapStatSort, chave: "pagina-mapas", porPagina: 20, detalhe: true })}
      </div>
      ${rows.length > 1 && agentes.size > 1 ? agentesPorMapa(mapas) : ""}
    </section>
  `;
}

// Os blocos das abas Estatisticas, Agentes e Mapas do campeonato sob o mesmo filtro.
function playerStatsTab(player, matches) {
  const filtro = playerEstFiltro();
  const jogos = playerJogos(player, matches);
  const todos = tournamentStatMapMatches(matches).filter((match) => (match.players || []).some((row) => row.id === player.id));
  const mapas = playerEstMapas(player, matches, filtro);
  const soma = aggregateMatchPlayers(mapas)[0];
  return `
    <div class="vp-eq-coluna vp-eq-est">
      <div>
        ${sectionHead("Estatísticas", `${mapas.length} de ${todos.length} ${todos.length === 1 ? "mapa" : "mapas"}`)}
        ${playerEstFiltros(jogos, matches, filtro)}
      </div>
      ${soma ? `
        <section class="vp-eq-bloco vp-est">
          <div class="vp-est-lista">
            <article class="vp-est-bloco">
              <h3>Números</h3>
              ${fichaJogador(soma)}
            </article>
          </div>
          <aside class="vp-resumo" aria-label="Composição da rAAting">
            ${playerComposicao(soma)}
            ${playerMultiKills(soma)}
          </aside>
        </section>
      ` : `<div class="empty-state">Nenhuma estatística com esses filtros. Tire um filtro para ver mais.</div>`}
      ${playerAgentesBloco(mapas)}
      ${playerMapasBloco(player, mapas)}
    </div>
  `;
}

function playerTeamHistoryRows(player, matches = matchSeriesForPlayer(player.id), tournamentRows = playerTournamentRows(player, matches)) {
  const matchBuckets = playerTeamMatchBuckets(player.id, matches);
  const tournamentTeamIds = tournamentRows.map((row) => row.teamId).filter(Boolean);
  const ids = [...new Set([player.teamId, player.observedTeamId, ...(player.teamHistory || []), ...matchBuckets.keys(), ...tournamentTeamIds].filter(Boolean))];
  return ids
    .map((teamId, index) => {
      const team = teamById(teamId);
      const timeline = team ? playerTimelineEntryForTeam(team, player) : null;
      const bucket = matchBuckets.get(teamId) || {};
      const start = minPositive(timeline?.start, bucket.start);
      const end = maxPositive(timeline?.end, bucket.end, start);
      const trophies = playerTeamTrophies(teamId, tournamentRows.filter((row) => row.principal));
      const current = teamId === playerPrimaryTeam(player)?.id;
      const range = start || end ? formatDateRange(start, end, { current }) : "Período não informado";
      const duration = start || end ? formatTenureDuration(start || end, end || start) : "Duração indisponível";
      return {
        teamId,
        team,
        index,
        start,
        end,
        range,
        duration,
        current,
        series: Number(bucket.series || 0),
        maps: Number(bucket.maps || timeline?.matches || 0),
        rounds: Number(bucket.rounds || timeline?.rounds || 0),
        trophies,
      };
    })
    .sort((a, b) => Number(b.current) - Number(a.current) || (b.end || 0) - (a.end || 0) || a.index - b.index);
}

function playerTimelineEntryForTeam(team, player) {
  const rows = lineupTimelineRows(team);
  const key = normalizeNameKey(player.nick || player.handle);
  return rows.find((item) => item.playerId === player.id || normalizeNameKey(item.name) === key || normalizeNameKey(item.handle) === key) || null;
}

function playerTeamMatchBuckets(playerId, matches) {
  const buckets = new Map();
  for (const series of matches) {
    const teamsInSeries = new Set();
    for (const match of series.maps || []) {
      const entry = playerInMatchTeam(match, playerId);
      if (!entry?.teamId) continue;
      const bucket = buckets.get(entry.teamId) || { teamId: entry.teamId, series: 0, maps: 0, rounds: 0, start: 0, end: 0 };
      bucket.maps += 1;
      bucket.rounds += Number(entry.player.rounds || 0);
      bucket.start = minPositive(bucket.start, match.startedAt || series.startedAt);
      bucket.end = maxPositive(bucket.end, match.startedAt || series.startedAt);
      buckets.set(entry.teamId, bucket);
      teamsInSeries.add(entry.teamId);
    }
    teamsInSeries.forEach((teamId) => {
      const bucket = buckets.get(teamId);
      if (bucket) bucket.series += 1;
    });
  }
  return buckets;
}

function playerInMatchTeam(match, playerId) {
  const player = (match.players || []).find((row) => row.id === playerId);
  if (!player) return null;
  const teamId = match.teamA.color === player.teamColor ? match.teamA.id : match.teamB.id;
  return { player, teamId };
}

function playerTeamTimelineChart(linhas) {
  const rows = linhas.filter((row) => row.trechos.length);
  if (!rows.length) return `<div class="empty-state">Sem datas suficientes para montar a linha do tempo.</div>`;
  const min = Math.min(...rows.map((row) => row.trechos[0].inicio));
  const max = Math.max(...rows.map((row) => row.trechos.at(-1).fim));
  const span = Math.max(DAY_MS, max - min);
  return `
    <div class="lineup-timeline-chart">
      <div class="lineup-timeline-axis">
        <span></span>
        <div class="lineup-axis-track vp-meses-verticais">
          ${mesesDoPeriodo(min, max).map((tick) => `<span style="left:${timelinePct(tick, min, max)}%">${escapeHtml(chartDateLabel(tick))}</span>`).join("")}
        </div>
        <span></span>
      </div>
      <div class="lineup-timeline-rows">
        ${rows
          .map((row) => {
            const name = row.team?.name || row.teamId;
            return `
              <div class="lineup-timeline-row">
                <a class="lineup-timeline-name" href="#/teams/${escapeHtml(row.teamId)}">
                  ${teamLogo(row.teamId)}
                  <span><strong>${escapeHtml(name)}</strong>${row.current ? `<small>Atual</small>` : ""}</span>
                </a>
                <div class="lineup-timeline-track">
                  ${row.trechos.map((trecho, indice) => {
                    const start = timelinePct(trecho.inicio, min, max);
                    const width = clamp(((trecho.fim - trecho.inicio) / span) * 100, 1, 100 - start);
                    const atual = row.current && indice === row.trechos.length - 1;
                    return `<span class="lineup-timeline-bar ${atual ? "current" : ""}" style="--start:${fmt(start, 2)};--width:${fmt(width, 2)}" title="${escapeHtml(`${name}: ${teamTrechoTexto(trecho, atual)}`)}"></span>`;
                  }).join("")}
                </div>
              </div>
            `;
          })
          .join("")}
      </div>
    </div>
  `;
}

function playerTournamentRows(player, matches = matchSeriesForPlayer(player.id)) {
  const visibleEvents = new Map(visibleTournaments().map((event) => [event.id, event]));
  // Uma linha por equipe: quem jogou o campeonato por duas lines tem cada campanha
  // com os proprios mapas. `principal` e a equipe com mais series no campeonato:
  // trofeu, contagem de campeonatos e evolucao contam o evento uma vez, por ela.
  const byCampaign = new Map();
  for (const series of matches) {
    const event = visibleEvents.get(series.eventId);
    if (!event) continue;
    const seriesTeams = new Set();
    for (const match of series.maps || []) {
      const entry = playerInMatchTeam(match, player.id);
      if (!entry?.teamId) continue;
      const key = `${event.id}|${entry.teamId}`;
      const row = byCampaign.get(key) || { event, teamId: entry.teamId, series: 0, maps: 0, rounds: 0, start: 0, end: 0, ratingTotal: 0, acsTotal: 0 };
      const rounds = Number(entry.player.rounds || 0);
      row.maps += 1;
      row.rounds += rounds;
      row.ratingTotal += Number(entry.player.rating || 0) * rounds;
      row.acsTotal += Number(entry.player.acs || 0) * rounds;
      row.start = minPositive(row.start, match.startedAt || series.startedAt);
      row.end = maxPositive(row.end, match.startedAt || series.startedAt);
      byCampaign.set(key, row);
      if (!seriesTeams.has(key)) row.series += 1;
      seriesTeams.add(key);
    }
  }
  const campaignsByEvent = new Map();
  for (const row of byCampaign.values()) campaignsByEvent.set(row.event.id, [...(campaignsByEvent.get(row.event.id) || []), row]);
  for (const rows of campaignsByEvent.values()) {
    rows.sort((a, b) => b.series - a.series || a.teamId.localeCompare(b.teamId)).forEach((row, index) => {
      row.principal = index === 0;
    });
  }
  return [...byCampaign.values()]
    .map((row) => {
      const { teamId, ratingTotal, acsTotal, ...campos } = row;
      const team = teamById(teamId);
      const campaign = team ? teamEventCampaign(teamId, row.event) : {};
      const onlyTeam = campaignsByEvent.get(row.event.id).length === 1;
      const eventStats = onlyTeam ? player.eventStats?.find((stats) => stats.eventId === row.event.id) : null;
      return {
        ...campos,
        teamId,
        team,
        placement: campaign.placement || 0,
        placementLabel: campaign.placementLabel || "Colocação indisponível",
        placementStatus: campaign.placementStatus || "unknown",
        campaign,
        size: campaign.size || row.event.teams.length,
        rating: onlyTeam ? eventStats?.rating || 0 : row.rounds ? ratingTotal / row.rounds : 0,
        acs: onlyTeam ? eventStats?.acs || 0 : row.rounds ? acsTotal / row.rounds : 0,
      };
    })
    .sort((a, b) => Number(b.event.end || b.end || b.event.start || 0) - Number(a.event.end || a.end || a.event.start || 0) || String(a.event.name || "").localeCompare(String(b.event.name || ""), "pt-BR"));
}

// Premio individual do campeonato. Ao contrario do podio, que sai da colocacao
// da EQUIPE, este e nominal: o campeonato aponta um PUUID em `mvp` e so aquele
// jogador recebe. `placement: 0` poe o premio na frente do podio do mesmo dia -
// quem foi campeao e MVP ve primeiro o que e dele sozinho.
// Um jogador pode ter mais de uma conta (`accounts`), entao o premio casa por
// qualquer PUUID dele - e tambem por nick normalizado, para quem preferir
// escrever o nick no override.
function playerMvpKeys(player) {
  return new Set([
    ...[player?.id, player?.puuid, ...(player?.accounts || []).map((conta) => conta?.puuid || conta)].filter(
      (valor) => typeof valor === "string" && valor
    ),
    ...playerLookupKeys(player),
  ]);
}

function playerMvpAwards(player, tournamentRows = playerTournamentRows(player)) {
  const chaves = playerMvpKeys(player);
  const rows = [];
  for (const event of visibleTournaments()) {
    if (!eventIsDone(event)) continue;
    const premiado = String(event.mvp || "").trim();
    if (!premiado) continue;
    if (!chaves.has(premiado) && !chaves.has(normalizeNameKey(premiado))) continue;
    const doJogador = tournamentRows.find((row) => row.principal && row.event?.id === event.id);
    rows.push({
      event,
      placement: 0,
      placementLabel: "MVP",
      trophyKey: "mvp",
      podiumClass: "place-mvp",
      date: Number(event.end || event.start || 0),
      teamId: doJogador?.teamId || "",
      team: doJogador?.team || null,
    });
  }
  return rows;
}

function playerTrophyAchievements(player, tournamentRows = playerTournamentRows(player)) {
  return [
    ...tournamentRows.filter((row) => row.principal).flatMap((row) => playerTeamTrophies(row.teamId, [row]).map((trophy) => ({ ...trophy, teamId: row.teamId, team: row.team, playerMaps: row.maps, playerSeries: row.series }))),
    ...playerMvpAwards(player, tournamentRows),
  ].sort((a, b) => b.date - a.date || a.placement - b.placement || String(a.event.name || "").localeCompare(String(b.event.name || ""), "pt-BR"));
}

function playerTeamTrophies(teamId, tournamentRows) {
  const team = teamById(teamId);
  if (!team) return [];
  const eventIds = new Set((tournamentRows || []).filter((row) => row.teamId === teamId).map((row) => row.event.id));
  return teamTrophyAchievements(team, { includeInherited: false }).filter((trophy) => eventIds.has(trophy.event.id));
}

function minPositive(...values) {
  const nums = values.map(Number).filter((value) => Number.isFinite(value) && value > 0);
  return nums.length ? Math.min(...nums) : 0;
}

function maxPositive(...values) {
  const nums = values.map(Number).filter((value) => Number.isFinite(value) && value > 0);
  return nums.length ? Math.max(...nums) : 0;
}

function isOfficialRatingSample(player) {
  return (player?.sample_status || player?.sampleStatus) === "OK";
}

function playerRankingRows(players) {
  const rows = state.playerSort === "rating" ? players.filter(isOfficialRatingSample) : players.slice();
  return rows.sort((a, b) => {
    const valueA = state.playerSort === "rating" ? officialRatingValue(a) : state.playerSort === "swing" ? playerSwingPerRound(a) : a[state.playerSort];
    const valueB = state.playerSort === "rating" ? officialRatingValue(b) : state.playerSort === "swing" ? playerSwingPerRound(b) : b[state.playerSort];
    const valueDiff = Number(valueB || 0) - Number(valueA || 0);
    if (valueDiff) return valueDiff;
    if (state.playerSort === "rating") return Number(b.rounds || 0) - Number(a.rounds || 0) || a.nick.localeCompare(b.nick, "pt-BR");
    return a.nick.localeCompare(b.nick, "pt-BR");
  });
}

function renderMapDetail(id) {
  const map = mapById(id);
  if (!map) return renderNotFound("Mapa");
  const matches = matchSeriesForMap(id);
  Shell(`
    <section class="profile-header">
      ${mapLogo(map.id, "large")}
      <div>
        <span class="eyebrow">Mapa competitivo</span>
        <h1>${escapeHtml(map.name)}</h1>
        <p class="muted">${map.matches} partidas - ${map.rounds} rounds jogados</p>
      </div>
      <div class="profile-actions">
        <a class="action-link" href="#/matches">Partidas</a>
      </div>
    </section>
    <div class="layout-grid">
      <div class="stack">
        <section class="section-band">
          ${sectionHead("Partidas neste mapa")}
          <div class="match-list">${matches.map(matchCard).join("")}</div>
        </section>
        <section class="section-band">
          ${sectionHead("Equipes por aproveitamento")}
          <div class="card-grid">${map.teamStats.map((row) => teamCard(teamById(row.teamId))).join("")}</div>
        </section>
      </div>
      <aside class="side-rail">
        <section class="data-panel dark">
          <div class="section-head"><h2>Resumo</h2></div>
          <div class="stats-grid">
            ${stat(map.matches, "Partidas")}
            ${stat(map.rounds, "Rounds")}
            ${stat(map.teamStats.length, "Equipes")}
            ${stat(map.agentStats[0]?.name || "-", "Agente mais usado")}
          </div>
        </section>
        <section class="data-panel">
          <div class="section-head"><h2>Agentes</h2></div>
          ${agentBars(map.agentStats.slice(0, 8), { showPickRate: true })}
        </section>
        <section class="data-panel">
          <div class="section-head"><h2>Win rate por equipe</h2></div>
          ${bars(map.teamStats.map((item) => [teamById(item.teamId).name, item.winRate, `${item.wins}-${item.matches - item.wins}`]))}
        </section>
      </aside>
    </div>
  `);
}

// panelTitle e sectionHead devolvem a mesma peca do visual Placar: titulo
// condensado grande, o contexto curto ao lado e o link na ponta direita.
function panelTitle(title, routeName, linkLabel) {
  return sectionHead(title, "", routeName, linkLabel);
}

function panelFooterLink(routeName, label) {
  return `<a class="panel-footer-link" href="#/${routeName}">${escapeHtml(label)}</a>`;
}

function eventIsVisible(event) {
  return !event?.hidden;
}

function visibleTournaments() {
  return (state.db?.tournaments || []).filter(eventIsVisible);
}

// Marca cada etapa cadastrada com o campeonato e compoe o nome que o site mostra.
// So o cliente (e o build_home, que pinta a home) chama: o database.json guarda o
// nome de antes, e o ranking nunca ve o nome composto. Chamar de novo sobre um
// banco ja marcado nao recompoe (o resumo da home chega com o nome pronto).
function aplicarCampeonatos(db) {
  cacheDosCampeonatos.db = null;
  const porId = new Map((db?.tournaments || []).map((event) => [event.id, event]));
  for (const campeonato of CAMPEONATOS_COM_ETAPAS) {
    for (const etapa of campeonato.etapas) {
      const event = porId.get(etapa.id);
      if (!event) continue;
      const composto = `${campeonato.nome}${SEPARADOR_DE_ETAPA}${etapa.nome}`;
      event.campeonatoId = campeonato.id;
      event.etapaNome = etapa.nome;
      if (event.name === composto) continue;
      if (!event.nomeOriginal) event.nomeOriginal = event.name;
      event.name = composto;
    }
  }
}

const cacheDosCampeonatos = { db: null, porId: new Map() };

function agregadoDoCampeonato(campeonato, porId) {
  const etapas = campeonato.etapas.map((etapa) => porId.get(etapa.id)).filter((event) => event && eventIsVisible(event));
  if (!etapas.length) return null;
  const decide = etapas.find((event) => event.id === campeonato.decide) || etapas[0];
  const aoVivo = etapas.find((event) => eventStatusClass(event.status) === "live");
  const comCapa = [decide, ...etapas.slice().sort((a, b) => (b.start || 0) - (a.start || 0))].find((event) => event.banner || event.bannerPath);
  const inicios = etapas.map((event) => Number(event.start || 0)).filter((value) => value > 0);
  const fins = etapas.map((event) => Number(event.end || event.start || 0)).filter((value) => value > 0);
  const equipes = new Set();
  etapas.forEach((event) => (event.teams || []).forEach((team) => equipes.add(typeof team === "string" ? team : team?.id)));
  equipes.delete(undefined);
  return {
    isCampeonato: true,
    id: campeonato.id,
    nome: campeonato.nome,
    name: campeonato.nome,
    nomesAntigos: campeonato.nomesAntigos || [],
    etapas,
    decide,
    paralelas: new Set(campeonato.etapas.filter((etapa) => etapa.paralela).map((etapa) => etapa.id)),
    niveis: new Map(campeonato.etapas.map((etapa) => [etapa.id, etapa.nivel])),
    artigos: new Map(campeonato.etapas.map((etapa) => [etapa.id, etapa.artigo || "da"])),
    start: inicios.length ? Math.min(...inicios) : decide.start,
    end: fins.length ? Math.max(...fins) : decide.end,
    status: (aoVivo || decide).status,
    tier: decide.tier,
    logo: decide.logo,
    banner: comCapa ? comCapa.banner || comCapa.bannerPath : "",
    organizer: decide.organizer,
    type: decide.type,
    prizePool: decide.prizePool,
    format: { summary: `${etapas.length} etapas`, details: [] },
    teams: [...equipes],
    matches: etapas.reduce((soma, event) => soma + Number(event.matches || 0), 0),
  };
}

function agregadosDosCampeonatos() {
  if (cacheDosCampeonatos.db !== state.db) {
    const porId = new Map((state.db?.tournaments || []).map((event) => [event.id, event]));
    cacheDosCampeonatos.porId = new Map();
    for (const campeonato of CAMPEONATOS_COM_ETAPAS) {
      const agregado = agregadoDoCampeonato(campeonato, porId);
      if (agregado) cacheDosCampeonatos.porId.set(campeonato.id, agregado);
    }
    cacheDosCampeonatos.db = state.db;
  }
  return cacheDosCampeonatos.porId;
}

function campeonatoPorId(id) {
  return agregadosDosCampeonatos().get(id) || null;
}

function campeonatoDaEtapa(event) {
  if (!event?.campeonatoId) return null;
  const agregado = campeonatoPorId(event.campeonatoId);
  return agregado && agregado.etapas.some((etapa) => etapa.id === event.id) ? agregado : null;
}

// Colocacao do campeonato inteiro. Primeiro a da etapa que decide; depois quem nao
// chegou la, pelo degrau em que caiu, do mais alto para o mais baixo. Degrau de uma
// etapa so segue os grupos da colocacao dela, na ordem dela, mas com a faixa contada
// a partir de onde o degrau de cima parou: "Off Season" e "Practice" (o suico do
// LBEU manda as eliminadas para as divisoes) viram numeros, e quem jogou sem linha
// de colocacao (ou se classificou e nao jogou a etapa seguinte) vem no fim do degrau.
// Degrau de varias etapas (as classificatorias) vira um grupo so. Cada equipe aparece uma vez, no degrau mais
// alto que alcancou, e paralela nao entra. Quem ainda disputa a etapa que decide fica
// fora ate ter colocacao, como na propria etapa (o podio mostra as vagas em aberto).
function colocacaoFinal(campeonato) {
  const linhas = [];
  const reservadas = new Set();
  // Quem jogou a etapa: tem serie com arquivo ou colocacao oficial nela. A colocacao
  // conta sozinha porque ha equipe com todos os jogos sem estatistica (Uninassau no
  // suico da Aliança 2024.1) ou so com W.O. (UFSCar Fire na Classificatória 3 do
  // UNIVAVÁ), e a pagina da etapa ja mostra as duas na colocacao.
  const equipesDaEtapa = (etapa) => {
    const ids = new Set();
    matchSeriesForEvent(etapa.id).forEach((series) => [series.teamA?.id, series.teamB?.id].forEach((id) => id && ids.add(id)));
    trophyPlacementRows(etapa).forEach((row) => (row.id || row.teamId) && ids.add(row.id || row.teamId));
    return ids;
  };
  const snapshot = tournamentRankingSnapshot({ id: campeonato.id, start: campeonato.start, teams: campeonato.teams }, matchSeriesForEvent(campeonato.id));
  const linhaDeOrdem = (id) => ({ eventRanking: snapshot?.byTeamId?.[id] || null, team: teamById(id) || { name: id } });
  const porRanking = (a, b) => compareTournamentTeamByRank(linhaDeOrdem(a), linhaDeOrdem(b));
  const grupoContado = (ids, etapaId) => {
    // Conta as vagas ja tomadas, nao as linhas: com a final por jogar, 1º e 2º ainda
    // nao tem linha, mas as duas finalistas ja estao acima de todo mundo.
    const n = reservadas.size;
    const range = ids.length === 1 ? String(n + 1) : `${n + 1}-${n + ids.length}`;
    ids.sort(porRanking).forEach((id) => {
      linhas.push({ range, id, etapaId });
      reservadas.add(id);
    });
  };

  const decide = campeonato.decide;
  trophyPlacementRows(decide).forEach((row) => {
    const id = row.id || row.teamId;
    if (!id || reservadas.has(id)) return;
    reservadas.add(id);
    linhas.push({ ...row, range: row.range, id, etapaId: decide.id });
  });
  equipesDaEtapa(decide).forEach((id) => reservadas.add(id));

  const niveis = [...new Set(campeonato.etapas.map((etapa) => campeonato.niveis.get(etapa.id)))].filter((nivel) => nivel > 1).sort((a, b) => a - b);
  niveis.forEach((nivel) => {
    const etapas = campeonato.etapas.filter((etapa) => !campeonato.paralelas.has(etapa.id) && campeonato.niveis.get(etapa.id) === nivel);
    const doNivel = new Set();
    etapas.forEach((etapa) => equipesDaEtapa(etapa).forEach((id) => !reservadas.has(id) && doNivel.add(id)));
    if (!doNivel.size) return;
    if (etapas.length === 1) {
      const grupos = [];
      const vistas = new Set();
      trophyPlacementRows(etapas[0]).forEach((row) => {
        const id = row.id || row.teamId;
        if (!doNivel.has(id) || vistas.has(id) || placementIsQualified(placementRawValue(row))) return;
        vistas.add(id);
        if (grupos.at(-1)?.rotulo !== row.range) grupos.push({ rotulo: row.range, ids: [] });
        grupos.at(-1).ids.push(id);
      });
      grupos.forEach((grupo) => grupoContado(grupo.ids, etapas[0].id));
      const sobra = [...doNivel].filter((id) => !vistas.has(id));
      if (sobra.length) grupoContado(sobra, etapas[0].id);
    } else {
      grupoContado([...doNivel], "");
    }
    doNivel.forEach((id) => reservadas.add(id));
  });
  return linhas;
}

// O campeonato inteiro como um evento so: as abas da pagina recebem isto e a uniao
// das series das etapas (matchSeriesForEvent ja entende o id do campeonato).
function eventoDoGeral(campeonato) {
  const decide = campeonato.decide;
  const nomesDasEquipes = {};
  campeonato.etapas.slice().reverse().forEach((etapa) => Object.assign(nomesDasEquipes, etapa.teamNames || {}));
  const mapas = new Map();
  campeonato.etapas.forEach((etapa) => (etapa.mapPool || etapa.maps || []).forEach((nome) => {
    if (!mapas.has(normalize(nome))) mapas.set(normalize(nome), nome);
  }));
  return {
    id: campeonato.id,
    name: campeonato.nome,
    isGeral: true,
    campeonato,
    organizer: decide.organizer,
    organizerLogo: decide.organizerLogo,
    source: decide.source,
    logo: campeonato.logo,
    banner: campeonato.banner,
    tier: campeonato.tier,
    type: decide.type,
    status: campeonato.status,
    start: campeonato.start,
    end: campeonato.end,
    startAt: campeonato.etapas.map((etapa) => etapa.startAt).filter(Boolean).sort()[0] || decide.startAt,
    endAt: campeonato.etapas.map((etapa) => etapa.endAt).filter(Boolean).sort().at(-1) || decide.endAt,
    teams: campeonato.teams,
    teamCount: campeonato.teams.length,
    teamNames: nomesDasEquipes,
    mapPool: [...mapas.values()],
    matches: campeonato.matches,
    placements: colocacaoFinal(campeonato),
    prizePool: decide.prizePool,
    mvp: decide.mvp,
    format: { summary: `${campeonato.etapas.length} etapas`, details: [] },
  };
}

function sortedEvents(sortKey = "end") {
  return visibleTournaments().slice().sort((a, b) => {
    const diff = eventSortValue(b, sortKey) - eventSortValue(a, sortKey);
    if (diff) return diff;
    return String(a.name || "").localeCompare(String(b.name || ""), "pt-BR", { sensitivity: "base" });
  });
}

function eventSortValue(event, sortKey = "end") {
  if (sortKey === "start") return Number(event.start || event.end || 0);
  if (sortKey === "recent") return Math.max(Number(event.end || 0), Number(event.start || 0));
  return Number(event.end || event.start || 0);
}

function allMatchSeries() {
  return state.db.matchSeries || state.db.matches.map((match) => createMatchSeriesSummary([match]));
}

function compareSeriesDateDesc(a, b) {
  return (b.startedAt || b.sortAt || 0) - (a.startedAt || a.sortAt || 0);
}

function isMatchSeriesItem(item) {
  return Array.isArray(item?.maps);
}

function normalizeMatchItem(item) {
  if (isMatchSeriesItem(item)) return item;
  return allMatchSeries().find((series) => series.seriesKey === item.seriesKey) || createMatchSeriesSummary([item]);
}

function matchSeriesRoute(item) {
  const series = normalizeMatchItem(item);
  return `matches/${series.primaryMatchId}${series.mapCount > 1 || series.officialResultNote ? "/all" : ""}`;
}

function matchSeriesHref(item) {
  return `#/${matchSeriesRoute(item)}`;
}

function seriesHasTeam(series, teamId) {
  return series.teamA.id === teamId || series.teamB.id === teamId;
}

function seriesHasMap(series, mapId) {
  return series.maps.some((match) => match.mapId === mapId);
}

function seriesHasPlayer(series, playerId) {
  return series.maps.some((match) => match.players.some((player) => player.id === playerId));
}

// O id de um campeonato com etapas (ex.: "univava") devolve as series de todas as
// etapas visiveis dele: e isso que faz o Geral funcionar nas abas sem mudar cada uma.
function matchSeriesForEvent(eventId) {
  const campeonato = state.db ? campeonatoPorId(eventId) : null;
  const ids = campeonato ? new Set(campeonato.etapas.map((etapa) => etapa.id)) : null;
  return allMatchSeries().filter((series) => (ids ? ids.has(series.eventId) : series.eventId === eventId)).sort(compareSeriesDateDesc);
}

function matchSeriesForTeam(teamId) {
  return allMatchSeries().filter((series) => seriesHasTeam(series, teamId)).sort(compareSeriesDateDesc);
}

function matchSeriesForMap(mapId) {
  return allMatchSeries().filter((series) => seriesHasMap(series, mapId)).sort(compareSeriesDateDesc);
}

function matchSeriesForPlayer(playerId) {
  return allMatchSeries().filter((series) => seriesHasPlayer(series, playerId)).sort(compareSeriesDateDesc);
}

// `ignorar` tira um filtro da conta: o resumo ao lado da lista conta os mapas
// sem o filtro de mapa e os meses sem o de data.
function filteredMatches({ ignorar = "" } = {}) {
  ensureResultFilterDefaults();
  const from = ignorar === "datas" ? null : dateInputToStart(state.matchDateFrom);
  const to = ignorar === "datas" ? null : dateInputToEnd(state.matchDateTo);
  // Tres de tres marcados nao vira `includes`: seriesBestOf le o numero do
  // rotulo da serie, entao um formato que ainda nao existe no banco (MD2, MD7)
  // sumiria da lista sem nenhum filtro ligado. Com todos marcados o filtro sai
  // do caminho, que e o que "Todos" sempre significou aqui.
  const todosOsFormatos = !state.matchBestOfs.length || state.matchBestOfs.length === MELHOR_DE_OPCOES.length;
  // Sem campeonato marcado continua valendo a lista dos visiveis: o filtro desligado
  // nao pode trazer de volta o que o site esconde.
  const eventos = new Set(state.matchTournaments.length ? state.matchTournaments : visibleTournaments().map((event) => event.id));
  return allMatchSeries()
    .filter((series) => todosOsFormatos || state.matchBestOfs.includes(seriesBestOf(series)))
    .filter((series) => ignorar === "mapas" || !state.matchMaps.length || state.matchMaps.some((mapId) => seriesHasMap(series, mapId)))
    .filter((series) => state.matchTeams.every((teamId) => seriesHasTeam(series, teamId)))
    .filter((series) => eventos.has(series.eventId))
    .filter((series) => !from || (series.sortAt || series.startedAt) >= from)
    .filter((series) => !to || series.startedAt <= to)
    .sort(compareSeriesDateDesc);
}

function seriesBestOf(series) {
  const label = String(series.label || seriesFormatLabel(series.maps || []));
  const match = label.match(/\d+/);
  return match ? match[0] : "1";
}

function dateInputToStart(value) {
  if (!value) return null;
  const date = new Date(`${value}T00:00:00`);
  return Number.isNaN(date.getTime()) ? null : date.getTime();
}

function dateInputToEnd(value) {
  if (!value) return null;
  const date = new Date(`${value}T23:59:59.999`);
  return Number.isNaN(date.getTime()) ? null : date.getTime();
}

function bindMatchFilters() {
  const sidebar = document.querySelector(".match-filter-sidebar");
  sidebar?.querySelectorAll(".filter-dropdown").forEach((details) => {
    details.addEventListener("toggle", () => {
      const group = details.dataset.filterGroup;
      if (group) state.resultFilterOpen[group] = details.open;
    });
  });
  sidebar?.addEventListener("click", (event) => {
    // Trocar a ordem nao muda o resultado da busca, so a ordem da lista de
    // opcoes - entao ela repinta no lugar, como a busca de equipe faz. Uma
    // re-render aqui fecharia a gaveta e jogaria o foco fora do botao.
    const ordem = event.target.closest("[data-tournament-order]");
    if (ordem) {
      trocarOrdemDeCampeonato(sidebar, ordem.dataset.tournamentOrder);
      return;
    }
    const button = event.target.closest("[data-match-filter]");
    if (!button) return;
    const filter = button.dataset.matchFilter;
    const value = button.dataset.value || "all";
    // devolve o foco ao mesmo controle depois da re-renderizacao
    const foco = `[data-match-filter="${filter}"]` + (button.dataset.value ? `[data-value="${button.dataset.value}"]` : "");
    if (filter === "reset") {
      resetResultFilters();
      // Sem filtro ativo o botao some, entao o foco vai para o primeiro filtro.
      pushFilterState("matches", new URLSearchParams(), ".vp-filtros summary");
      return;
    }
    if (filter === "bestOf") toggleResultFilterValue("matchBestOfs", value);
    if (filter === "map") toggleResultFilterValue("matchMaps", value);
    if (filter === "tournament") toggleResultFilterValue("matchTournaments", value);
    if (filter === "team") toggleResultFilterValue("matchTeams", value);
    pushFilterState("matches", matchFiltersToQuery(), foco);
  });
  // `change` e nao `input`: o seletor de data dispara `input` a cada digito do
  // ano, e cada disparo empurraria uma entrada no historico do navegador.
  sidebar?.querySelectorAll("[data-match-date]").forEach((campo) => {
    campo.addEventListener("change", () => {
      const alvo = campo.dataset.matchDate === "from" ? "matchDateFrom" : "matchDateTo";
      state[alvo] = campo.value || "";
      // Inverteu o intervalo: em vez de devolver lista vazia sem explicacao, a
      // outra ponta acompanha.
      if (state.matchDateFrom && state.matchDateTo && state.matchDateFrom > state.matchDateTo) {
        if (alvo === "matchDateFrom") state.matchDateTo = state.matchDateFrom;
        else state.matchDateFrom = state.matchDateTo;
      }
      pushFilterState("matches", matchFiltersToQuery(), `[data-match-date="${campo.dataset.matchDate}"]`);
    });
  });
  document.getElementById("match-team-query")?.addEventListener("input", (event) => {
    state.matchTeamQuery = event.target.value;
    const options = document.querySelector("[data-team-options]");
    if (options) options.innerHTML = matchTeamOptionsHtml();
  });
}

function trocarOrdemDeCampeonato(sidebar, ordem) {
  if (!ordem || state.matchTournamentOrder === ordem) return;
  state.matchTournamentOrder = ordem;
  const opcoes = sidebar.querySelector("[data-event-options]");
  if (opcoes) opcoes.innerHTML = campeonatosDoFiltro().map(eventFilterButton).join("");
  sidebar.querySelectorAll("[data-tournament-order]").forEach((botao) => {
    const ativo = botao.dataset.tournamentOrder === ordem;
    botao.classList.toggle("active", ativo);
    botao.setAttribute("aria-pressed", ativo ? "true" : "false");
  });
}

function toggleResultFilterValue(key, value) {
  const current = Array.isArray(state[key]) ? state[key] : [];
  state[key] = current.includes(value) ? current.filter((item) => item !== value) : [...current, value];
}

// Lista vazia e sem filtro: tudo comeca desmarcado e o primeiro marcado ja deixa
// so ele. Antes tudo comecava marcado, e filtrar um mapa pedia desmarcar doze.
function resetResultFilters() {
  state.matchBestOfs = [];
  state.matchMaps = [];
  state.matchTournaments = [];
  state.matchTeams = [];
  state.matchTeamQuery = "";
  state.matchDateFrom = "";
  state.matchDateTo = "";
  state.resultFilterOpen = {
    bestOf: false,
    maps: false,
    tournaments: false,
    datas: false,
    teams: false,
  };
}

function nomesDaBusca(player) {
  return [player.nick, player.handle, ...(player.nickHistory || [])].filter(Boolean);
}

function temTextoInteiro(player, busca) {
  return nomesDaBusca(player).some((nome) => normalize(nome).includes(busca));
}

// As letras na ordem, mesmo com outras no meio: "kmz" acha "kmyzth". Nick e tag
// sao testados separados, senao o z de um e o m do outro somariam um falso acerto.
function temLetrasEmOrdem(player, busca) {
  return nomesDaBusca(player).flatMap((nome) => nome.split("#")).some((parte) => {
    let achadas = 0;
    for (const letra of normalize(parte)) if (letra === busca[achadas]) achadas += 1;
    return achadas === busca.length;
  });
}

function filteredPlayers() {
  const nameQuery = normalize(state.playerQuery);
  const rows = state.db.players
    .filter(playerTemPerfil)
    .filter((player) => !nameQuery || temTextoInteiro(player, nameQuery) || temLetrasEmOrdem(player, nameQuery))
    .filter((player) => state.playerTeam === "all" || player.teamId === state.playerTeam || player.observedTeamId === state.playerTeam)
    .filter((player) => !state.playerComEquipe || playerPrimaryTeam(player));
  const porNome = (a, b) => String(a.nick || "").localeCompare(String(b.nick || ""), "pt-BR", { numeric: true, sensitivity: "base" }) || String(a.handle || "").localeCompare(String(b.handle || ""), "pt-BR", { numeric: true, sensitivity: "base" });
  const sinal = state.playerOrdemInversa ? -1 : 1;
  const comparar = {
    nome: (a, b) => sinal * porNome(a, b),
    equipe: (a, b) => sinal * String(playerPrimaryTeam(a)?.name || "\uffff").localeCompare(String(playerPrimaryTeam(b)?.name || "\uffff"), "pt-BR", { sensitivity: "base" }) || porNome(a, b),
    mapas: (a, b) => sinal * (Number(b.matches || 0) - Number(a.matches || 0)) || porNome(a, b),
    eventos: (a, b) => sinal * ((b.eventStats || []).length - (a.eventStats || []).length) || porNome(a, b),
  };
  const ordenados = rows.sort(comparar[state.playerOrdem] || comparar.mapas);
  if (!nameQuery) return ordenados;
  // Quem tem o texto inteiro vem antes de quem so tem as letras espalhadas.
  return [...ordenados.filter((player) => temTextoInteiro(player, nameQuery)), ...ordenados.filter((player) => !temTextoInteiro(player, nameQuery))];
}

function bindPlayerFilters() {
  document.getElementById("player-query")?.addEventListener("input", (event) => {
    state.playerQuery = event.target.value;
    atualizarBuscaDeJogadores();
  });
  document.getElementById("player-team-query")?.addEventListener("input", (event) => {
    document.querySelector("[data-player-team-options]").innerHTML = playerTeamOptionsHtml(event.target.value);
  });
  // A busca redesenha as opcoes, entao o clique fica no conteiner.
  document.querySelector("[data-player-team-options]")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-player-team-filter]");
    if (!button) return;
    state.playerTeam = button.dataset.playerTeamFilter || "all";
    pushFilterState("players", playerFiltersToQuery(), `[data-player-team-filter="${state.playerTeam}"]`);
  });
  document.getElementById("player-team")?.addEventListener("change", (event) => {
    state.playerTeam = event.target.value;
    pushFilterState("players", playerFiltersToQuery(), "#player-team");
  });
}

function playerFigure(player, team, extra = "") {
  // Toda celula da faixa mostra um rosto no mesmo lugar: quem nao tem foto
  // recebe a silhueta, entao a linha dos olhos nao pula de um card para o
  // outro e o retangulo nunca aparece vazio.
  const accent = team ? teamAccentStyle(team) : "";
  const photo = player?.photo ? assetPath(player.photo) : "";
  if (!photo) {
    return `<span class="player-figure is-silhouette ${escapeHtml(extra)}" ${accent}><img src="${escapeHtml(assetPath(PLAYER_FALLBACK_PHOTO))}" alt="" loading="lazy" onerror="this.onerror=null; this.remove()" /></span>`;
  }
  return `<span class="player-figure ${escapeHtml(extra)}" ${accent}><img src="${escapeHtml(photo)}" alt="" loading="lazy" onerror="playerFigureError(this)" /></span>`;
}

function playerFigureError(image) {
  const figure = image?.closest(".player-figure");
  if (!figure) return;
  // Trocar o src em vez de remover a imagem: a silhueta ocupa o mesmo espaco
  // da foto que falhou, entao a altura da celula nao muda depois do carregamento.
  figure.classList.add("is-silhouette");
  image.onerror = null;
  image.src = assetPath(PLAYER_FALLBACK_PHOTO);
}

// Enquanto o banco completo não chegou, os líderes vêm prontos do home.json.
// O `category` sintético devolve o valor já formatado no build, então
// weekLeadCard e weekTile não precisam saber de onde veio.
function homeSummaryLeaders() {
  return (state.homeSummary?.leaders || []).map((leader) => ({
    category: {
      key: leader.key,
      label: leader.label,
      statLabel: leader.statLabel,
      format: () => leader.value,
      support: leader.support,
    },
    player: leader.player,
    windowLabel: leader.windowLabel,
  }));
}

// Melhores da semana: um lider por vez, deslizando para o lado, como o
// carrossel de antes de agosto. O cartao troca no fim de cada tracinho
// (PLAYER_OF_WEEK_INTERVAL_MS, vindo pelo --vp-passo) e o primeiro vai clonado
// no fim, para a volta do ultimo ao primeiro seguir para a frente em vez de
// rebobinar os nove. As setas e as bolinhas de 7px sairam em agosto por serem
// pequenas para o dedo; cada tracinho tem 22px de area de clique.
function weekHighlights() {
  const leaders = state.homeSummary ? homeSummaryLeaders() : playerOfWeekLeaders();
  if (!leaders.length) {
    return `
      <section class="vp-semana vp-semana-vazia" aria-labelledby="week-board-title">
        <header class="vp-sec"><h2 id="week-board-title">Melhores da semana</h2></header>
        <p class="empty-state">Nenhum jogador atingiu o mínimo de ${PLAYER_OF_WEEK_MIN_MAPS} mapas nesta janela.</p>
      </section>
    `;
  }
  return `
    <section class="vp-semana" aria-roledescription="carrossel" aria-labelledby="week-board-title">
      <header class="vp-sec"><h2 id="week-board-title">Melhores da semana</h2></header>
      <div class="vp-semana-cartao" tabindex="0" style="--vp-passo:${PLAYER_OF_WEEK_INTERVAL_MS}ms">
        <p class="vp-semana-cabeca"><span>${escapeHtml(leaders[0].windowLabel)}</span><span>Mínimo de ${PLAYER_OF_WEEK_MIN_MAPS} mapas</span></p>
        <div class="vp-semana-trilho">${leaders.map((leader) => weekSlide(leader, false)).join("")}${weekSlide(leaders[0], true)}</div>
        <div class="vp-passos">${leaders.map(({ category }) => `<button type="button" class="vp-passo" aria-label="${escapeHtml(category.label)}"><i></i></button>`).join("")}</div>
      </div>
    </section>
  `;
}

// As duas pecas do cartao, como uma camisa: a cor1 da planilha chapada atras da
// foto e a cor2 chapada atras do texto, sem degrade e sem preto no meio.
//
// 1. Cor1 quase preta nao vira cartao preto: entra o tom de grafico da equipe,
//    que ja escolhe a cor com croma entre as duas.
// 2. O campo escurece so o bastante para a tinta dar 4,5:1 em texto de 12px. O
//    azul do Azure Bears, cru, da 4,2:1.
// 3. A cor2 so vira peca quando agrega (mesmo corte do campo do heroi: cor2 de
//    contorno de logo ou igual a cor1 nao conta). Sem ela, a peca e um tom bem
//    claro do proprio campo, para as duas pecas continuarem separadas.
function teamPlateStyle(team) {
  const [primary, secondary] = team?.colors || [];
  const cru = hexToRgb(safeCssColor(primary, TEAM_PLACA_SEM_COR)) || hexToRgb(TEAM_PLACA_SEM_COR);
  const segunda = hexToRgb(safeCssColor(secondary, "")) || null;
  const quasePreta = relativeLuminance(cru) < TEAM_PLACA_LUZ_MINIMA && chromaOf(cru) < TEAM_FIELD_CROMA_MINIMA;
  const base = quasePreta ? hexToRgb(teamChartInk(rgbToHex(cru), rgbToHex(segunda || cru))) : cru;
  const misturar = (a, b, f) => a.map((c, i) => Math.round(c * (1 - f) + b[i] * f));

  const tinta = hexToRgb(teamInkFor(rgbToHex(base)));
  let campo = base;
  const clara = relativeLuminance(tinta) > 0.5;
  for (let passo = 0; passo < 40 && contrastRatio(campo, tinta) < TEAM_PLACA_CONTRASTE; passo += 1) {
    campo = misturar(campo, clara ? [0, 0, 0] : [255, 255, 255], 0.03);
  }

  const agrega = segunda && relativeLuminance(segunda) > TEAM_FIELD_LUZ_MINIMA_COR2 && contrastRatio(campo, segunda) >= 1.5;
  const peca = agrega ? segunda : clara ? misturar(campo, [255, 255, 255], 0.86) : misturar(campo, tinta, 0.16);
  const tintas = [TEAM_INK_CLARO, TEAM_INK_ESCURO].map(hexToRgb);
  const tintaPeca = contrastRatio(peca, tintas[0]) >= contrastRatio(peca, tintas[1]) ? tintas[0] : tintas[1];
  const numero = contrastRatio(peca, campo) >= 3 ? campo : tintaPeca;
  const logo = assetPath(team?.profile?.logo || team?.logo || "");

  return [
    `--placa-campo:${rgbToHex(campo)}`,
    `--placa-silhueta:${rgbToHex(misturar(campo, tinta, 0.34))}`,
    `--placa-peca:${rgbToHex(peca)}`,
    `--placa-tinta:${rgbToHex(tintaPeca)}`,
    `--placa-campo-tinta:${rgbToHex(tinta)}`,
    // Os simbolos de funcao sao brancos e sumiriam numa peca clara.
    `--placa-icone:${relativeLuminance(tintaPeca) > 0.5 ? "brightness(0) invert(1)" : "brightness(0)"}`,
    `--placa-numero:${rgbToHex(numero)}`,
    `--placa-campo-icone:${clara ? "brightness(0) invert(1)" : "brightness(0)"}`,
    logo ? `--placa-logo:url('${logo}')` : "",
    // Logo branco sumiria em campo branco: ali entra so a forma dele, em preto.
    relativeLuminance(campo) > 0.7 ? "--placa-logo-filtro:brightness(0) opacity(0.55)" : "",
    // No cartao de equipe o logo aparece inteiro, com as cores dele: um contorno
    // separa do campo claro o que for branco, sem apagar as outras cores.
    relativeLuminance(campo) > 0.7 ? `--placa-logo-contorno:${[[1.5, 0], [-1.5, 0], [0, 1.5], [0, -1.5]].map(([x, y]) => `drop-shadow(${x}px ${y}px 0 ${rgbToHex(tinta)})`).join(" ")}` : "",
  ].filter(Boolean).join(";");
}

// O cartao Camisa: quem e o assunto pisa na emenda das duas pecas, com o numero
// na cor da equipe. Serve aos melhores da semana, ao melhor da partida e a equipe
// filtrada em #/matches, onde o logo faz o papel da foto.
function plateCard({ classe, team, href, nome, figura, rotulo, tag, valor, apoio, atributos = "" }) {
  return `
    <a class="${classe}" href="${href}" style="${escapeHtml(teamPlateStyle(team))}"${atributos}>
      <span class="vp-slide-campo"><i></i></span>
      ${figura}
      <span class="vp-slide-txt">
        <small>${escapeHtml(rotulo)}</small>
        <strong class="vp-slide-nick" title="${escapeHtml(nome)}"><span class="nome-rolante">${escapeHtml(nome)}</span></strong>
        <span class="vp-slide-equipe">${escapeHtml(tag)}</span>
        <b class="vp-slide-valor">${escapeHtml(valor)}</b>
        <small>${escapeHtml(apoio)}</small>
      </span>
    </a>
  `;
}

// Um cartao do carrossel. O clone do fim sai da arvore de acessibilidade e da
// ordem de Tab.
function weekSlide({ category, player }, clone) {
  const team = teamById(player.teamId);
  const valor = category.format(player);
  return plateCard({
    classe: "vp-slide",
    team,
    href: playerHref(player),
    nome: player.nick,
    figura: playerFigure(player, team, "vp-slide-foto"),
    rotulo: category.label,
    tag: team?.sourceTag || team?.tag || player.teamTag || "",
    valor,
    apoio: `${player.matches} mapas, ${player.rounds} rounds`,
    atributos: clone ? ` aria-hidden="true" tabindex="-1"` : ` aria-label="${escapeHtml(`${category.label}: ${player.nick}, ${valor}`)}"`,
  });
}

// Liga o carrossel que o weekHighlights desenhou. Nao ha timer: quem avanca e o
// fim da animacao do tracinho atual, entao pausar no hover ou no foco por
// teclado (CSS) tambem pausa a troca, e aba em segundo plano nao acumula
// trocas. Foco por clique nao pausa: clicar num tracinho pararia o carrossel
// de vez.
function bindWeekCarousel() {
  const cartao = document.querySelector(".vp-semana-cartao");
  if (!cartao) return;
  const trilho = cartao.querySelector(".vp-semana-trilho");
  const passos = [...cartao.querySelectorAll(".vp-passo")];
  const total = passos.length;
  if (!trilho || total < 2) return;
  let indice = 0;
  const pintar = () => {
    const visivel = indice % total;
    passos.forEach((passo, i) => {
      passo.classList.toggle("vp-feito", i < visivel);
      passo.removeAttribute("aria-current");
      // Recriar o atributo depois de um reflow faz a animacao do tracinho
      // recomecar do zero quando a pessoa volta para um que ja estava cheio.
      if (i === visivel) {
        void passo.offsetWidth;
        passo.setAttribute("aria-current", "true");
      }
    });
  };
  const ir = (destino, animar = true) => {
    indice = destino;
    trilho.classList.toggle("vp-sem-animacao", !animar);
    trilho.style.transform = `translateX(-${indice * 100}%)`;
    pintar();
  };
  const proximo = () => ir(indice >= total ? 1 : indice + 1);
  const anterior = () => ir(((indice % total) - 1 + total) % total);
  trilho.addEventListener("transitionend", (evento) => {
    if (evento.target === trilho && evento.propertyName === "transform" && indice === total) ir(0, false);
  });
  cartao.querySelector(".vp-passos").addEventListener("animationend", proximo);
  passos.forEach((passo, i) => passo.addEventListener("click", () => ir(i)));
  cartao.addEventListener("keydown", (evento) => {
    if (evento.key === "ArrowRight") {
      evento.preventDefault();
      proximo();
    } else if (evento.key === "ArrowLeft") {
      evento.preventDefault();
      anterior();
    }
  });
  let inicioX = null;
  cartao.addEventListener("pointerdown", (evento) => {
    inicioX = evento.clientX;
  });
  cartao.addEventListener("pointerup", (evento) => {
    if (inicioX === null) return;
    const dx = evento.clientX - inicioX;
    inicioX = null;
    if (Math.abs(dx) > 40) (dx < 0 ? proximo : anterior)();
  });
  ir(0, false);
}

function playerOfWeekLeaders() {
  const { players, start, end } = playerOfWeekWindow();
  if (!players.length) return [];
  const windowLabel = `${playerWeekDateLabel(start)} - ${playerWeekDateLabel(end)}`;
  return PLAYER_OF_WEEK_CATEGORIES
    .map((category) => {
      const player = playerOfWeekLeader(players, category);
      return player ? { category, player, windowLabel } : null;
    })
    .filter(Boolean);
}

function playerOfWeekWindow() {
  const cutoffAt = Number(latestRankingSnapshot()?.cutoffAt || rankingTuesdayStartOnOrBefore(Date.now()));
  const allMatches = state.db?.matches || [];
  const earliestMatchAt = allMatches.reduce((earliest, match) => {
    const startedAt = Number(match.startedAt || 0);
    return startedAt && startedAt <= cutoffAt ? Math.min(earliest, startedAt) : earliest;
  }, Infinity);
  let start = cutoffAt - WEEK_MS;

  while (true) {
    const matches = allMatches.filter((match) => {
      const startedAt = Number(match.startedAt || 0);
      return startedAt >= start && startedAt <= cutoffAt;
    });
    const players = weeklyPlayerRows(matches);
    const reachedFirstMatch = Number.isFinite(earliestMatchAt) ? start <= earliestMatchAt : true;
    if (players.length || reachedFirstMatch) return { start, end: cutoffAt, matches, players };
    start -= WEEK_MS;
  }
}

function weeklyPlayerRows(matches) {
  const rows = new Map();
  for (const match of matches || []) {
    for (const player of match.players || []) {
      if (!player.id) continue;
      const base = playerById(player.id) || player;
      const teamId = match.teamA?.color === player.teamColor ? match.teamA.id : match.teamB?.id;
      const row = rows.get(player.id) || {
        id: player.id,
        puuid: player.puuid || base.puuid || player.id,
        nick: base.nick || player.nick || "Jogador",
        handle: base.handle || player.handle || player.nick || "Jogador",
        photo: base.photo || player.photo || "",
        currentTeam: base.currentTeam || "",
        teams: new Map(),
        matches: 0,
        rounds: 0,
        kills: 0,
        deaths: 0,
        assists: 0,
        score: 0,
        damage: 0,
        firstKills: 0,
        firstDeaths: 0,
        kastRounds: 0,
        impactTotal: 0,
        ...emptyRaatingAggregateFields(),
      };
      row.matches += 1;
      row.rounds += Number(player.rounds || 0);
      row.kills += Number(player.kills || 0);
      row.deaths += Number(player.deaths || 0);
      row.assists += Number(player.assists || 0);
      row.score += Number(player.score || 0);
      row.damage += Number(player.damage || 0);
      row.firstKills += Number(player.firstKills || 0);
      row.firstDeaths += Number(player.firstDeaths || 0);
      row.kastRounds += Number(player.kastRounds || 0);
      row.impactTotal += Number(player.impactTotal || 0);
      addRaatingAggregateFields(row, player);
      if (teamId) row.teams.set(teamId, (row.teams.get(teamId) || 0) + 1);
      rows.set(player.id, row);
    }
  }

  return [...rows.values()]
    .map((player) => {
      const observedTeamId = [...player.teams.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] || player.currentTeam || "";
      player.teamId = observedTeamId;
      player.teamTag = teamById(observedTeamId)?.sourceTag || teamById(observedTeamId)?.tag || observedTeamId;
      player.acs = player.rounds ? player.score / player.rounds : 0;
      player.adr = player.rounds ? player.damage / player.rounds : 0;
      player.kpr = player.rounds ? player.kills / player.rounds : 0;
      player.dpr = player.rounds ? player.deaths / player.rounds : 0;
      player.apr = player.rounds ? player.assists / player.rounds : 0;
      player.kd = player.deaths ? player.kills / player.deaths : player.kills;
      player.kastFrac = player.rounds ? player.kastRounds / player.rounds : 0;
      player.kast = player.kastFrac * 100;
      player.impactRound = player.rounds ? player.impactTotal / player.rounds : 0;
      player.impactRoundLegacy = player.rounds ? Number(player.impactTotalLegacy || 0) / player.rounds : 0;
      player.kastLegacyFrac = player.rounds ? Number(player.kastLegacyRounds || 0) / player.rounds : player.kastFrac;
      player.kastLegacy = player.kastLegacyFrac * 100;
      applyRaatingFields(player);
      return player;
    })
    .filter((player) => player.rounds > 0 && player.matches >= PLAYER_OF_WEEK_MIN_MAPS);
}

function playerOfWeekLeader(players, category) {
  return players.slice().sort((a, b) => {
    const valueA = Number(category.value(a) || 0);
    const valueB = Number(category.value(b) || 0);
    const metricDiff = category.lowIsBetter ? valueA - valueB : valueB - valueA;
    if (metricDiff !== 0) return metricDiff;
    return b.rounds - a.rounds || Number(officialRatingValue(b) || 0) - Number(officialRatingValue(a) || 0) || a.nick.localeCompare(b.nick, "pt-BR");
  })[0] || null;
}

function playerWeekDateLabel(value) {
  return new Date(value).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" }).replace(".", "");
}

// A capa so e baixada quando o ponteiro chega na linha: nenhum byte cobrado de
// quem nunca passa o mouse pelo painel. Depois da primeira vez a classe fica, e
// entrar e sair da linha vira so opacidade - sem novo pedido, sem piscada.
// O `img.onload` existe para nao acender a camada em cima de um buraco: o veu
// escuro sozinho parece um bug ate a arte chegar.
function bindEventCovers(painel, linha) {
  // Espelha o @media do CSS: sem ponteiro fino nao ha o que revelar, entao nem
  // o download acontece.
  if (!window.matchMedia?.("(hover: hover) and (pointer: fine)").matches) return;
  const panel = document.querySelector(painel);
  if (!panel) return;
  const revelar = (row) => {
    const capa = row?.dataset?.cover;
    if (!capa) return;
    const reserva = row.dataset.coverCheia || "";
    delete row.dataset.cover;
    delete row.dataset.coverCheia;
    const aplicar = (url) => {
      row.style.setProperty("--event-capa", `url("${url}")`);
      row.classList.add("tem-capa");
    };
    const img = new Image();
    img.onload = () => aplicar(capa);
    // Sem este ramo a falha era muda: o derivado de linha faltando significava
    // simplesmente nenhuma capa, sem erro em lugar nenhum. Agora cai na capa
    // cheia e avisa qual arquivo falta - o aviso e o que faz o passo esquecido
    // aparecer, ja que o resultado visivel passa a estar correto.
    img.onerror = () => {
      if (!reserva || reserva === capa) return;
      console.warn(`[capas] falta ${capa} - usando a capa cheia. Rode: python scripts/build_event_row_banners.py`);
      const cheia = new Image();
      cheia.onload = () => aplicar(reserva);
      cheia.src = reserva;
    };
    img.src = capa;
  };
  panel.addEventListener("pointerover", (event) => revelar(event.target.closest(linha)));
  panel.addEventListener("focusin", (event) => revelar(event.target.closest(linha)));
}

function bindHomeRankingPanel() {
  const panel = document.querySelector(".ranking-panel");
  panel?.addEventListener("click", (event) => {
    if (event.defaultPrevented) return;
    if (event.target.closest("a, button, input, select, textarea")) return;
    window.location.hash = "#/ranking";
  });
}

function compactRankingRow(team) {
  const score = team.rankingScore ?? team.points;
  const snapshot = latestRankingSnapshot();
  const ranking = snapshot?.byTeamId?.[team.id] || team.ranking;
  // Uma linha da Placa do ranking. Ela vive numa .vp-placa-rk, que e uma grade
  // so com as linhas em subgrade: a coluna do nome tem o tamanho do nome mais
  // longo e a nota cola no "N partidas", em vez de ir para a ponta do quadro.
  return `
    <a class="vp-rk pintura-de-equipe" href="#/ranking/${escapeHtml(team.id)}" data-home-ranking-team="${escapeHtml(team.id)}" ${teamAccentStyle(team)}>
      <span class="vp-rk-pos">${escapeHtml(teamShortRankLabel(team).replace(/^#/, ""))}</span>
      ${rankingPositionChangeBadge({ team, ranking, snapshot }, "vp-rk-delta")}
      ${teamLogo(team.id)}
      <span class="vp-rk-nome" title="${escapeHtml(team.name)}">${escapeHtml(team.name)}</span>
      <span class="vp-rk-partidas">${team.matches || team.wins + team.losses} partidas</span>
      <span class="vp-rk-nota">${fmt(score, 1)}</span>
    </a>
  `;
}

function matchListScore(item) {
  const series = normalizeMatchItem(item);
  if (series.mapCount > 1 || series.officialResultNote) {
    return {
      a: series.scoreA,
      b: series.scoreB,
      label: series.label,
      detail: series.mapNames.join(" / "),
    };
  }
  const match = series.maps[0];
  return {
    a: match.teamA.score,
    b: match.teamB.score,
    label: match.mapName,
    detail: match.mapName,
  };
}

function matchSeriesMetaLabel(item) {
  const series = normalizeMatchItem(item);
  if (series.mapCount > 1) return `${series.mapCount} mapas: ${series.mapNames.join(" / ")}`;
  return `MVP: ${series.mvp ? series.mvp.nick : "-"}`;
}

// A linha de partida: o modelo antigo, mais baixo (pedido do dono em 24/10).
// Escudo grande de cada lado, nome ao lado do escudo, placar grande no meio
// com o vencedor em verde. Em cima, uma linha so de contexto: a hora, os nomes
// dos mapas no meio, cada um sobre a propria fatia de arte, e o campeonato na
// ponta direita. A arte cobre a linha inteira, com uma fatia por mapa.
// Opcoes num objeto de proposito: `.map(matchResultRow)` passa o indice no
// segundo argumento, e um numero nao tem `.when` nem `.kd`. Assim as listas que
// chamam pelo `.map` cru recebem exatamente o padrao (a data) sem precisar
// saber que o indice chega ali. Quem agrupa por dia pede `{ when: "hour" }`,
// porque la o dia ja e o cabecalho do grupo. A pagina do jogador pede
// `{ kd: [abates, mortes] }` para a coluna do K / D dele na serie.
function dataSemAno(valor) {
  return formatDate(valor).replace(/ de \d{4}$/, "");
}

function matchResultRow(item, options) {
  const opts = options && typeof options === "object" ? options : {};
  const series = normalizeMatchItem(item);
  const score = matchListScore(series);
  const event = state.db.tournaments.find((row) => row.id === series.eventId);
  const when = opts.when === "hour" ? formatDate(series.startedAt, "hour") : opts.when === "curta" ? dataSemAno(series.startedAt) : formatDate(series.startedAt);
  const nomeDoEvento = event?.name || "Evento";
  const nomes = (series.mapNames || []).filter(Boolean);
  const mapas = nomes.length
    ? `<span class="vp-pl-mapas">${nomes.map((nome) => `<span class="vp-pl-mapa">${escapeHtml(nome)}</span>`).join("")}</span>`
    : "";
  const numero = (valor, contra) => `<b${Number(valor) > Number(contra) ? ' class="vp-venceu"' : ""}>${escapeHtml(valor)}</b>`;
  const lado = (team) => `<strong title="${escapeHtml(team.name)}"><span class="nome-rolante">${escapeHtml(team.name)}</span></strong>`;
  const kd = Array.isArray(opts.kd) ? `<span class="vp-kd"><b>${escapeHtml(opts.kd[0])} / ${escapeHtml(opts.kd[1])}</b><small>K / D</small></span>` : "";
  return `
    <a class="vp-pl${kd ? " vp-pl-kd" : ""}" style="--maps:${nomes.length || 1}" href="${matchSeriesHref(series)}">
      ${matchMapBanner(series)}
      <span class="vp-pl-topo">
        <span class="vp-pl-quando">${escapeHtml(when)}${window.Comments ? window.Comments.selo("match", series.seriesKey) : ""}</span>
        ${mapas}
        ${opts.semEvento
          ? `<span class="vp-pl-evento"></span>`
          : `<span class="vp-pl-evento" title="${escapeHtml(nomeDoEvento)}"><span class="vp-pl-evento-nome"><span class="nome-rolante">${escapeHtml(nomeDoEvento)}</span></span>${event ? eventLogo(event, "tiny") : ""}</span>`}
      </span>
      <span class="vp-pl-lado vp-pl-a">${teamLogo(series.teamA.id)}${lado(series.teamA)}</span>
      <span class="vp-pl-placar">${numero(score.a, score.b)}<i>:</i>${numero(score.b, score.a)}</span>
      <span class="vp-pl-lado vp-pl-b">${lado(series.teamB)}${teamLogo(series.teamB.id)}</span>
      ${kd}
    </a>
  `;
}

// A cor de risco, barra e banho de uma equipe: a mesma --team-line que o
// teamAccentStyle calcula (teamChartInk, 4,5:1 contra o painel), sem montar o
// resto do estilo, que pesa numa lista de 50 linhas. Equipe sem cor cadastrada
// fica num cinza neutro, e nao no vermelho de reserva do teamAccentStyle:
// vermelho e marca, nunca dado. O cache vive na propria funcao porque ela pode
// rodar antes de o init() terminar, e uma const de topo depois dele cairia na
// zona morta temporal.
function teamLineColor(teamId) {
  const cache = (teamLineColor.cache ||= new Map());
  if (cache.has(teamId)) return cache.get(teamId);
  const team = teamById(teamId);
  const [primary, secondary] = team?.colors || [];
  if (!primary) return TEAM_LINE_SEM_COR;
  const cor = teamChartInk(safeCssColor(primary, TEAM_LINE_SEM_COR), safeCssColor(secondary || primary, TEAM_LINE_SEM_COR));
  cache.set(teamId, cor);
  return cor;
}

// O nome do campeonato tem 84px na ponta direita da faixa de meta da home (ver
// --ponta-da-faixa no styles.css). Antes ele nao encolhia: a faixa de nomes de
// mapa e absoluta, entao sai do fluxo do flex e nunca espremia o nome - so
// passava por baixo dele. Com o teto, "JUBS Goias 2026 - Etapa Presencial"
// (174,6px) passou a ser cortado, e cortado ele nao se le. Entao o que sobrou
// de fora vai ate o fim e volta.
// A medida vive aqui e nao no CSS porque so o navegador sabe quantos pixels
// ficaram para fora; o CSS recebe deslocamento e duracao em variaveis e cuida
// do ritmo (para, vai, para, volta).
// Vale para qualquer `.nome-rolante`: campeonato na faixa de meta e nome de
// equipe no placar das listas cheias.
// Duas saidas para "o texto e maior que a caixa", e a escolha e por elemento:
// `.nome-rolante` vai e volta (nome de campeonato, nome de equipe no placar) e
// `.nome-encolhe` diminui a fonte ate caber (apelido na faixa da semana). A
// primeira preserva o tamanho do texto e gasta tempo; a segunda preserva o
// tempo e gasta tamanho. Onde o texto e legenda de um numero, encolher le
// melhor do que ficar em movimento ao lado dele.
function ajustarTextosVariaveis(raiz) {
  const escopo = raiz && raiz.querySelectorAll ? raiz : document;
  // As fontes sao locais (assets/fonts) e chegam depois do primeiro layout.
  // Medir antes disso e medir a largura do texto na fonte do sistema, que e
  // outra - o texto caberia ou nao caberia por engano. Na segunda render a
  // promessa ja esta resolvida e o then roda como microtarefa, antes de pintar.
  Promise.resolve(document.fonts?.ready).then(() => {
    if (!escopo.isConnected && escopo !== document) return;
    // A ordem e o que faz as tres saidas conviverem:
    // 1. encolher, porque o texto que couber com a fonte menor nem vira
    //    candidato a rolagem (so o `.nome-encolhe` da faixa da semana);
    // 2. embrulhar o que o CSS esta cortando agora, para virar candidato;
    // 3. medir e rolar tudo que sobrou de fora.
    escopo.querySelectorAll(".nome-encolhe").forEach(medirNomeQueEncolhe);
    embrulharTextosCortados(escopo);
    const rolantes = [...escopo.querySelectorAll(".nome-rolante")];
    const encolhem = [...escopo.querySelectorAll(".nome-encolhe")];
    if (!rolantes.length && !encolhem.length) return;
    observarTextosVariaveis([...rolantes, ...encolhem], true);
    rolantes.forEach(medirNomeRolante);
  });
}

// A fonte cai na proporcao exata do que faltou: largura de texto e linear no
// corpo da fonte, entao uma passada basta. Medir com Range e nao com
// scrollWidth porque scrollWidth arredonda para inteiro, e 1px de erro num
// texto de 10px vira meia letra.
function medirNomeQueEncolhe(nome) {
  if (!nome.isConnected) return;
  nome.style.removeProperty("font-size");
  const caixa = nome.clientWidth;
  if (!caixa) return;
  // Mede o texto, e nao a caixa interna. O `.nome-rolante` que vive aqui dentro
  // e um bloco: em repouso ele preenche o pai, entao um Range sobre o conteudo
  // do PAI devolveria a largura da caixa e o nome nunca encolheria. Um Range
  // sobre o conteudo dele devolve a linha de texto de verdade.
  const alcance = document.createRange();
  alcance.selectNodeContents(nome.querySelector(".nome-rolante") || nome);
  const texto = alcance.getBoundingClientRect().width;
  if (!texto || texto <= caixa) return;
  const base = Number.parseFloat(getComputedStyle(nome).fontSize) || 13;
  const alvo = Math.max(NOME_FONTE_MINIMA, Math.floor((base * caixa) / texto * 10) / 10);
  nome.style.fontSize = `${alvo}px`;
}

function medirNomeRolante(nome) {
  if (!nome.isConnected) return;
  const caixa = nome.parentElement;
  if (!caixa) return;
  // Sempre do zero: entre uma medida e outra a caixa pode ter mudado de largura,
  // e um nome que rolava passa a caber (ou o contrario). Tirar a classe tambem
  // derruba a animacao, entao a medida abaixo pega o texto parado.
  caixa.classList.remove("tem-rolagem");
  caixa.style.removeProperty("--rolagem-fim");
  caixa.style.removeProperty("--rolagem-tempo");
  // scrollWidth do texto contra clientWidth da janela: sem a classe o
  // .nome-rolante e um bloco que preenche o pai, entao offsetWidth devolveria a
  // largura da janela e o transbordo daria sempre zero. E scrollWidth ignora o
  // transform, que getBoundingClientRect traria junto.
  // Numa lista com o dia recolhido os dois dao 0 e a diferenca fica em zero -
  // linha escondida nao anima.
  const transbordo = Math.round(nome.scrollWidth - caixa.clientWidth);
  if (transbordo < ROLAGEM_MINIMO) return;
  const bruto = (transbordo / ROLAGEM_VELOCIDADE) * ROLAGEM_CICLO;
  const tempo = Math.min(ROLAGEM_TEMPO_MAX, Math.max(ROLAGEM_TEMPO_MIN, bruto));
  caixa.style.setProperty("--rolagem-fim", `${-transbordo}px`);
  caixa.style.setProperty("--rolagem-tempo", `${tempo.toFixed(2)}s`);
  caixa.classList.add("tem-rolagem");
}

// A caixa muda de largura sem a rota mudar: janela redimensionada, breakpoint
// cruzado, barra de rolagem que aparece. render() sozinho so cobriria troca de
// pagina, entao quem avisa e o observador.
// Ele reconecta a cada render porque segura referencia forte ao que observa, e
// os elementos da render anterior morrem junto com o HTML antigo. O callback
// nao reobserva nada - se reobservasse, a notificacao inicial do observe()
// realimentaria o proprio callback para sempre. E a classe que medirNomeRolante
// liga so entra quando a caixa ja esta presa no max-width, e o max-content que
// ela da ao texto e o mesmo que ele ja contribuia - a caixa observada nao muda
// de tamanho, entao o trabalho dele tambem nao volta como evento.
// A regra "nunca corte, nunca reticencia" nao pode depender de alguem lembrar
// de embrulhar cada texto na mao: sao dezenas de pontos hoje e todo texto novo
// seria uma chance de esquecer. Entao quem procura e o codigo - varre a pagina
// atras de texto que o CSS ESTA cortando neste momento e devolve o corte em
// movimento. O que ja vem embrulhado da marcacao (nome de campeonato, de
// equipe, de mapa) passa direto: ja tem `.nome-rolante` dentro.
//
// O teste tem cinco condicoes, e cada uma existe para descartar um falso
// positivo medido:
//  - so folha com texto: elemento com filho elemento nao e caixa de texto;
//  - clientWidth > 0: elemento `inline` tem clientWidth zero, entao TODO span
//    de texto passaria no teste de transbordo. Isso tambem descarta o que esta
//    escondido (dia recolhido da lista de partidas, gaveta fechada);
//  - nowrap/pre: texto que quebra linha nao esta sendo cortado na horizontal;
//  - overflow-x hidden/clip: `auto`/`scroll` e rolagem de verdade, e a pessoa
//    ja pode alcancar o resto;
//  - nem flex nem grid: ali o texto solto e um item anonimo, e transforma-lo em
//    item de verdade mudaria o alinhamento da caixa.
// Podados pela raiz. Sao os elementos onde um <span> dentro nao e decoracao, e
// sim outra coisa: em TEXTAREA/OPTION o texto E o valor do controle, e em SVG a
// marcacao e de outro namespace. BUTTON ficou de FORA desta lista de proposito -
// podar botao apagava da varredura justamente os nomes de equipe e campeonato
// das gavetas de filtro, que sao botoes.
const ROLAGEM_FORA = new Set(["TEXTAREA", "SELECT", "OPTION", "SVG", "PATH"]);

function embrulharTextosCortados(escopo) {
  const raiz = escopo && escopo.nodeType ? escopo : document;
  // TreeWalker, e nao querySelectorAll("*"), por causa do REJECT: ele poda a
  // subarvore inteira. Medido no /ranking, que e a pagina mais pesada da casa:
  // 10.956 elementos, 4.427 folhas de texto - e 3.838 delas dentro dos 44
  // paineis fechados da sanfona, marcados com `inert`. Ler geometria ali dentro
  // obriga o navegador a diagramar conteudo que ele estava pulando: a varredura
  // custava 178ms. Podando, sobram 589 folhas e o custo cai para poucos ms.
  // Painel fechado tambem nao tem o que consertar - ninguem esta vendo.
  const passeio = document.createTreeWalker(raiz, NodeFilter.SHOW_ELEMENT, {
    acceptNode(el) {
      if (el.hasAttribute("inert") || el.hasAttribute("hidden")) return NodeFilter.FILTER_REJECT;
      if (ROLAGEM_FORA.has(el.tagName)) return NodeFilter.FILTER_REJECT;
      // SKIP desce nos filhos; so quem e folha COM texto vira candidato.
      return !el.firstElementChild && el.firstChild ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
    },
  });
  // Tres passadas separadas de proposito: le geometria, le estilo, escreve.
  // Intercalar escrita com leitura obrigaria um recalculo por elemento.
  const candidatos = [];
  for (let el = passeio.nextNode(); el; el = passeio.nextNode()) {
    const largura = el.clientWidth;
    // ROLAGEM_CAIXA_MINIMA descarta caixa que nao e caixa de leitura. O caso
    // real: o <h1 class="sr-only">UNIVLR</h1> de cada pagina, escondido pela
    // tecnica classica de 1x1px com overflow hidden - para a medida ele parece
    // texto cortado, e passava a animar em toda rota, invisivel e a toa.
    // Abaixo de 16px nao ha nome que se leia, entao nao ha o que revelar.
    if (largura < ROLAGEM_CAIXA_MINIMA) continue;
    // Um `.nome-rolante` longo ainda nao medido parece texto cortado. Embrulhado
    // de novo, a caixa de fora muda de largura a cada medida, o observador dispara
    // uma vez por segundo e a animacao reinicia antes de sair do lugar.
    if (el.classList.contains("nome-rolante")) continue;
    if (el.scrollWidth > largura + 0.5) candidatos.push(el);
  }
  if (!candidatos.length) return;
  const embrulhar = candidatos.filter((el) => {
    const cs = getComputedStyle(el);
    if (!/^(nowrap|pre)$/.test(cs.whiteSpace)) return false;
    if (!/^(hidden|clip)$/.test(cs.overflowX)) return false;
    return !/flex|grid/.test(cs.display) && cs.display !== "inline";
  });
  embrulhar.forEach((el) => {
    const caixa = document.createElement("span");
    caixa.className = "nome-rolante";
    while (el.firstChild) caixa.appendChild(el.firstChild);
    el.appendChild(caixa);
  });
}

function observarTextosVariaveis(nomes, reconectar) {
  if (typeof ResizeObserver !== "function") return;
  if (!rolagemObserver) {
    rolagemObserver = new ResizeObserver(() => {
      clearTimeout(rolagemAdiada);
      rolagemAdiada = setTimeout(remedirTextosVariaveis, 120);
    });
  }
  // Na troca de pagina o observador larga tudo: ele segura referencia forte ao
  // que observa, e os elementos da render anterior morrem com o HTML antigo.
  // No redimensionamento NAO se desconecta - reobservar os mesmos elementos
  // dispararia a notificacao inicial de cada um e o callback se chamaria de
  // novo. Por isso o WeakSet: so entra quem ainda nao estava.
  if (reconectar) {
    rolagemObserver.disconnect();
    rolagemObservados = new WeakSet();
  }
  // O `.nome-encolhe` e a propria caixa (a fonte muda nele); o `.nome-rolante`
  // mora dentro da caixa que corta, entao quem muda de tamanho e o pai.
  nomes.forEach((nome) => {
    const alvo = nome.classList.contains("nome-encolhe") ? nome : nome.parentElement;
    if (!alvo || rolagemObservados.has(alvo)) return;
    rolagemObservados.add(alvo);
    rolagemObserver.observe(alvo);
  });
}

// Mudou de largura sem trocar de pagina (janela redimensionada, breakpoint
// cruzado): refaz o ciclo inteiro, inclusive a varredura - o que passou a
// cortar agora precisa ser embrulhado, e o que voltou a caber tem a rolagem
// desligada por medirNomeRolante.
function remedirTextosVariaveis() {
  document.querySelectorAll(".nome-encolhe").forEach(medirNomeQueEncolhe);
  embrulharTextosCortados(document);
  const rolantes = [...document.querySelectorAll(".nome-rolante")];
  observarTextosVariaveis([...rolantes, ...document.querySelectorAll(".nome-encolhe")], false);
  rolantes.forEach(medirNomeRolante);
}

// Arte do mapa em versao web: 640x360 WebP (~20 KB) em vez do PNG de origem
// 1600x900 (~500 KB, e 2 MB no caso do summit). O uso mais largo e o fundo da
// linha de partida, que passa de 640px nas listas largas, mas a 20% de opacidade
// e numa tira de 68px de altura a perda nao aparece, entao o PNG grande seria so
// download grande.
// O original fica no data-fallback e entra se o WebP faltar, para um mapa novo
// que ainda nao passou pela conversao nao aparecer sem arte nenhuma.
function mapArtAttrs(map, preferred) {
  const original = assetPath(preferred || map?.icon || "");
  const web = map?.id ? assetPath(`assets/maps/web/${map.id}.webp`) : "";
  if (!web && !original) return null;
  const src = web || original;
  const fallback = web && original && original !== web ? original : "";
  return { src, fallback };
}

function mapArtError(image) {
  if (!image) return;
  const fallback = image.dataset?.fallback;
  // Marca no elemento em vez de comparar `image.src` com o fallback: o getter
  // devolve URL absoluta e assetPath guarda caminho relativo, entao a
  // comparacao era sempre verdadeira - o handler reatribuia o mesmo src para
  // sempre e o ramo de limpeza abaixo nunca era alcancado.
  if (fallback && !image.dataset.artFallbackUsed) {
    image.dataset.artFallbackUsed = "1";
    image.src = fallback;
    return;
  }
  image.onerror = null;
  image.closest(".result-map-tile")?.classList.remove("has-banner");
  image.closest(".map-perf-tile")?.classList.remove("has-art");
  image.closest(".tournament-map-banner")?.classList.remove("has-image");
  image.closest(".tournament-map-agent-banner")?.classList.remove("has-banner");
  image.closest(".search-match-map-image")?.classList.add("missing-image");
  // A fatia vazia fica: e ela que segura a largura da coluna. Removendo o <i>,
  // as fatias restantes se redistribuiriam e os nomes acima sairiam do lugar.
  image.remove();
}

function mapBannerSrc(name) {
  return mapArtAttrs(mapByName(name));
}

// O fundo de mapas da linha de partida: uma fatia por mapa, na ordem
// jogada, cortada em diagonal. Numa md3 a serie inteira aparece de uma vez, em
// vez de escolhermos um mapa "representativo" e esconder os outros.
function matchMapBanner(item) {
  const series = normalizeMatchItem(item);
  const names = (series.mapNames || []).filter(Boolean);
  // Uma fatia por NOME, e nao por arte encontrada: numa md3 com um mapa novo
  // fora da base, filtrar as que nao resolvem deixaria tres nomes sobre duas
  // fatias. A fatia sem arte entra vazia e segura a coluna.
  const slices = names.map((name) => mapBannerSrc(name));
  if (!slices.some(Boolean)) return "";
  return `<span class="vp-pl-artes" aria-hidden="true">${slices
    .map((art) =>
      art
        ? `<i><img src="${escapeHtml(art.src)}" data-fallback="${escapeHtml(art.fallback)}" alt="" loading="lazy" onerror="mapArtError(this)" /></i>`
        : "<i></i>",
    )
    .join("")}</span>`;
}

// A capa de hero e pesada demais para hover: 121 KB de media, 315 KB no pior
// caso, e por isso ela ja estava fora do aquecimento de cache. A variante de
// linha sai de scripts/build_event_row_banners.py e mora em row/ - 17 KB de
// media, recortada em 646x260, que e 2x a maior linha medida (323x130).
function eventRowCoverPath(event) {
  const banner = String(event?.banner || "").trim();
  if (!banner) return "";
  const nome = banner.split("/").pop().replace(/\.[^.]+$/, "");
  return nome ? `assets/tournament-banners/row/${nome}.webp` : "";
}

function atributosDaCapa(event) {
  const capa = eventRowCoverPath(event);
  // A capa cheia viaja junto como reserva. O derivado de linha e gerado por um
  // script a parte (scripts/build_event_row_banners.py) e nada obriga ele a
  // rodar quando um campeonato novo entra - foi o que aconteceu com a Copa LUCE
  // Inters, que tinha capa e nao mostrava nada. Com a reserva, campeonato novo
  // sempre revela capa; o que se perde sem o derivado e peso, nao a capa.
  const capaCheia = String(event?.banner || "").trim();
  return `${capa ? ` data-cover="${escapeHtml(assetPath(capa))}"` : ""}${capaCheia ? ` data-cover-cheia="${escapeHtml(assetPath(capaCheia))}"` : ""}`;
}

function eventListRow(event) {
  // Linha da Placa de campeonatos. Encerrado nao repete "Finalizado": o normal
  // nao precisa de selo, so o em andamento ganha o ponto vermelho de ao vivo.
  const situacao = eventStatusClass(event.status);
  // Campeonato com etapas diz qual etapa esta rolando.
  const etapaAoVivo = event.isCampeonato ? event.etapas.find((etapa) => eventStatusClass(etapa.status) === "live") : null;
  const aoVivo = etapaAoVivo ? `${etapaAoVivo.etapaNome} em andamento` : "Em andamento";
  const marca = situacao === "live" ? `<span class="vp-ao-vivo">${escapeHtml(aoVivo)}</span> ` : situacao === "scheduled" ? `${escapeHtml(event.status)}, ` : "";
  return `
    <a class="vp-evrow" href="#/events/${event.id}"${atributosDaCapa(event)}>
      ${eventLogo(event, "small")}
      <span class="vp-evrow-txt"><strong class="vp-evrow-nome" title="${escapeHtml(event.name)}">${escapeHtml(event.name)}</strong><span class="vp-evrow-quando">${marca}${escapeHtml(eventDatesShort(event))}${window.Comments ? window.Comments.selo("event", event.id) : ""}</span></span>
      ${eventTierBadge(event)}
      <span class="vp-evrow-tam">${event.matches} partidas<br>${event.teams.length} equipes</span>
    </a>
  `;
}

// As datas curtas das listas: sem o ano e sem repetir o mes ("17 - 18 de out",
// "27 de set - 4 de out", "10 de out"). Campeonato em andamento diz ate quando
// vai, ou desde quando, se o fim ainda e a ultima data com jogo; com as duas
// datas, o texto cortava no trilho de 340px.
function eventDatesShort(event) {
  const mes = (date) => date.toLocaleDateString("pt-BR", { month: "short" }).replace(".", "");
  const dia = (value) => {
    const date = new Date(value);
    return `${date.getDate()} de ${mes(date)}`;
  };
  if (!event?.start && !event?.end) return "";
  if (eventStatusClass(event.status) === "live") {
    if (!event.end || periodEndIsCurrent(event.end)) return event.start ? `desde ${dia(event.start)}` : "";
    return `até ${dia(event.end)}`;
  }
  if (!event.start || !event.end) return dia(event.start || event.end);
  const inicio = new Date(event.start);
  const fim = new Date(event.end);
  if (dayKey(event.start) === dayKey(event.end)) return dia(event.start);
  if (inicio.getMonth() === fim.getMonth() && inicio.getFullYear() === fim.getFullYear()) return `${inicio.getDate()} - ${dia(event.end)}`;
  return `${dia(event.start)} - ${dia(event.end)}`;
}

// O tier e a unica hierarquia entre campeonatos que o site publica, e ate aqui
// so aparecia dentro da pagina do evento. Cada nivel ganha cor propria - nunca
// o vermelho, que neste site e marca e nao dado.
function eventTierBadge(event) {
  const tier = String(event?.tier || "")
    .trim()
    .replace(/^tier\s*/i, "")
    .toUpperCase();
  if (!tier) return "";
  const key = /^[SABCD]$/.test(tier) ? tier.toLowerCase() : "other";
  // Letra grande e solta no vao que sobrava entre o nome e as contagens. Sem
  // caixa: o selo com contorno foi reprovado por parecer feito por IA, e um
  // dado de um caractere nao precisa de moldura para ser lido - o tamanho e a
  // cor ja o separam de tudo em volta. O nome inteiro fica no rotulo acessivel.
  // vp-tier e a cor do degrau no visual Placar; event-tier fica enquanto as
  // listas que ainda nao trocaram de marcacao usarem o desenho de antes.
  return `<span class="event-tier tier-${key} vp-tier vp-tier-${key}" title="Tier ${escapeHtml(tier)}" aria-label="Tier ${escapeHtml(tier)}" role="img">${escapeHtml(tier)}</span>`;
}

// Comentarios do campeonato inteiro: a conversa do Geral e as de cada etapa. A
// linha de Eventos e uma so, entao o selo soma tudo.
function conversasDoCampeonato(campeonato) {
  const contar = (id) => Number(window.Community?.contagem("event", id) || 0);
  return [campeonato.id, ...campeonato.etapas.map((etapa) => etapa.id)].reduce((soma, id) => soma + contar(id), 0);
}

// As etapas escritas na propria linha do campeonato, cada uma levando a etapa.
function etapasNaLinha(campeonato) {
  return `<span class="event-row-etapas">${campeonato.etapas.map((etapa) => `<a href="#/events/${escapeHtml(etapa.id)}">${escapeHtml(etapa.etapaNome)}</a>`).join("")}</span>`;
}

// A linha de um campeonato com etapas nao pode ser um <a> so: as etapas sao links
// dentro dela. O nome leva ao campeonato e cobre a linha inteira (::after), e as
// etapas ficam por cima, na coluna do formato (modelo B, escolha do dono em 07/11).
function eventDirectoryRowCampeonato(campeonato) {
  const decide = campeonato.decide;
  const teamTotal = campeonato.teams.length;
  const featuredTeams = eventFeaturedTeamIds(decide, matchSeriesForEvent(decide.id), 4)
    .map((teamId) => tournamentTeamById(decide, teamId))
    .filter(Boolean);
  return `
    <div class="event-row event-row-rich event-row-camp"${atributosDaCapa(campeonato)}>
      <span class="event-row-identity">
        ${eventLogo(campeonato, "small")}
        <span class="row-main event-row-title">
          <a class="event-row-link" href="#/events/${escapeHtml(campeonato.id)}"><strong>${escapeHtml(campeonato.nome)}</strong></a>
          <small>${escapeHtml(eventTimeRange(campeonato))}</small>
          <span class="event-status ${eventStatusClass(campeonato.status)}">${escapeHtml(campeonato.status || "Evento")}</span>${window.Comments ? window.Comments.selo("event", campeonato.id, conversasDoCampeonato(campeonato)) : ""}
        </span>
      </span>
      ${eventTierCell(campeonato)}
      ${eventCell(eventPremioTexto(campeonato), "Prizepool", "premio")}
      ${eventCell(teamTotal, "Times", "numeric")}
      ${eventCell(campeonato.type || "-", "Tipo")}
      <span class="event-cell event-cell-etapas" data-rotulo="Etapas">${etapasNaLinha(campeonato)}</span>
      <span class="event-row-participants" data-rotulo="Equipes">
        ${eventParticipantStack(featuredTeams, teamTotal)}
        <small class="sr-only">Equipes participantes</small>
      </span>
    </div>
  `;
}

function eventDirectoryRow(event) {
  if (event.isCampeonato) return eventDirectoryRowCampeonato(event);
  const matches = matchSeriesForEvent(event.id);
  const teamTotal = Number(event.teamCount || 0) || event.teams.length;
  // Quatro escudos cabem na coluna de 170px. Com oito o mosaico media 322px numa trilha de 232 e
  // os dois primeiros vazavam 90px para a ESQUERDA, por cima da coluna Formato
  // - transbordo que scrollWidth nao ve, porque ele so mede para a direita.
  const featuredTeams = eventFeaturedTeamIds(event, matches, 4)
    .map((teamId) => tournamentTeamById(event, teamId))
    .filter(Boolean);
  return `
    <a class="event-row event-row-rich" href="#/events/${event.id}"${atributosDaCapa(event)}>
      <span class="event-row-identity">
        ${eventLogo(event, "small")}
        <span class="row-main event-row-title">
          <strong>${escapeHtml(event.name)}</strong>
          <small>${escapeHtml(eventTimeRange(event))}</small>
          <span class="event-status ${eventStatusClass(event.status)}">${escapeHtml(event.status || "Evento")}</span>${window.Comments ? window.Comments.selo("event", event.id) : ""}
        </span>
      </span>
      ${eventTierCell(event)}
      ${eventCell(eventPremioTexto(event), "Prizepool", "premio")}
      ${eventCell(teamTotal, "Times", "numeric")}
      ${eventCell(event.type || "-", "Tipo")}
      ${eventCell(eventFormatoLabel(event) || tournamentFormatLabel(event, matches), "Formato")}
      <span class="event-row-participants" data-rotulo="Equipes">
        ${eventParticipantStack(featuredTeams, teamTotal)}
        <small class="sr-only">Equipes participantes</small>
      </span>
    </a>
  `;
}

// Celula da tabela. O rotulo nao e impresso no desktop - ele vive no cabecalho,
// que e o que torna a coisa uma tabela e nao uma linha de fatos rotulados. Fica
// no data-rotulo porque no celular a linha desempilha em cartao e ai o rotulo
// precisa voltar, via ::before no CSS.
function eventCell(valor, rotulo, extra = "") {
  const texto = String(valor === undefined || valor === null || valor === "" ? "-" : valor);
  return `
    <span class="event-cell ${escapeHtml(extra)}" data-rotulo="${escapeHtml(rotulo)}" title="${escapeHtml(texto)}">
      <span>${escapeHtml(texto)}</span>
    </span>
  `;
}

// "-" e o que a planilha grava quando nao ha premiacao (11 dos 18, mais 2
// nulos). Na tabela isso vira travessao tipografico apagado em vez de sumir,
// porque numa coluna alinhada a celula vazia tem de existir para a linha nao
// desalinhar - diferente da linha em fluxo, onde ela era so peso morto.
function eventPremioTexto(event) {
  const bruto = String(event?.prizePool || event?.prize || "").trim();
  if (!bruto || bruto === "-" || /^a definir$/i.test(bruto)) return "-";
  return bruto;
}

function eventTableHead() {
  return `
    <div class="event-table-head" role="row">
      <span class="event-head-dupla">
        ${eventSortHeader("nome", "Campeonato")}
        ${eventSortHeader("data", "Data")}
      </span>
      ${eventSortHeader("tier", "Tier", "is-tier")}
      ${eventSortHeader("premio", "Prizepool")}
      ${eventSortHeader("times", "Times", "numeric")}
      ${eventSortHeader("tipo", "Tipo")}
      ${eventSortHeader("formato", "Formato")}
      <span class="event-head-static">Equipes</span>
    </div>
  `;
}

// A coluna de equipes nao tem cabecalho clicavel de proposito: teamCount e
// teams.length sao o mesmo numero nos 18 campeonatos, entao ordenar por ela
// seria ordenar por "Times" com outro nome. Ela mostra QUEM joga, que e o que
// "Times" nao mostra.
// Fechada, a gaveta diz o que esta valendo - mesmo contrato dos resumos de
// /partidas. Sem isso, filtro escondido vira filtro esquecido: a pessoa nao
// lembra por que a lista encolheu.
function eventFilterResumo(selecionados, vazio) {
  if (!selecionados.length) return vazio;
  if (selecionados.length <= 2) return selecionados.join(", ");
  return `${selecionados.length} selecionados`;
}

function eventFilterGrupo(chave, rotulo, valores, ler, resumoVazio) {
  const f = state.eventFilters || {};
  const sel = f[chave] || [];
  const eventos = visibleTournaments();
  const contagens = valores.map((v) => ({ ...v, n: eventos.filter((e) => (ler(e) || "sem") === v.id).length })).filter((v) => v.n);
  // A barra de cada linha e a fatia que aquela opcao ocupa do total. Isso e o
  // que faz a linha usar a largura inteira dizendo algo: sem ela, esticar o
  // botao ate a borda seria so caixa maior. Escala pelo MAIOR valor, nao pelo
  // total, senao "Presencial 1" viraria um fio invisivel ao lado de "Online 13".
  const maior = Math.max(...contagens.map((v) => v.n), 1);
  const opcoes = contagens
    .map((v, i) => {
      const ativo = sel.includes(v.id);
      const fatia = Math.round((v.n / maior) * 100);
      return `<button type="button" class="event-filter-row${ativo ? " active" : ""}" data-event-filter="${escapeHtml(chave)}" data-valor="${escapeHtml(v.id)}" aria-pressed="${ativo ? "true" : "false"}" style="--i:${i};--fatia:${fatia}%">
        <span class="event-filter-row-nome">${escapeHtml(v.label)}</span>
        <span class="event-filter-row-conta">${v.n}</span>
      </button>`;
    })
    .join("");
  if (!opcoes) return "";
  return `
    <details class="filter-dropdown event-filter-drop${sel.length ? " tem-selecao" : ""}" data-event-group="${escapeHtml(chave)}"${state.eventFilterOpen?.[chave] ? " open" : ""}>
      <summary>${filterIcon()}<span>${escapeHtml(rotulo)}</span><strong>${escapeHtml(eventFilterResumo(sel.map((id) => valores.find((v) => v.id === id)?.label || id), resumoVazio))}</strong>${chevronIcon()}</summary>
      <div class="filter-dropdown-body">
        <div class="event-filter-rows">${opcoes}</div>
      </div>
    </details>
  `;
}

function eventFilterBar() {
  const f = state.eventFilters || {};
  const eventos = visibleTournaments();
  const tiers = ["S", "A", "B", "C", "D"].map((t) => ({ id: t, label: t })).concat([{ id: "sem", label: "Sem tier" }]);
  const tipos = ["Online", "Híbrido", "Presencial"].map((t) => ({ id: t, label: t })).concat([{ id: "sem", label: "Sem tipo" }]);
  const formatos = [...new Set(eventos.map(eventFormatoLabel).filter(Boolean))]
    .sort((a, b) => a.localeCompare(b, "pt-BR"))
    .map((t) => ({ id: t, label: t }));

  return `
    <section class="event-filter-bar" aria-label="Filtros de campeonato">
      ${eventFilterGrupo("tier", "Tier", tiers, eventTierChave, "Todos")}
      ${eventFilterGrupo("tipo", "Tipo", tipos, eventTipoGrupo, "Todos")}
      ${eventFilterGrupo("formato", "Formato", formatos, eventFormatoLabel, "Todos")}
      ${eventFilterGrupo("premio", "Prizepool", EVENT_PREMIO_OPCOES, eventPremioChave, "Todos")}
      ${eventFiltrosAtivos() ? `<button type="button" class="event-filter-toggle" data-event-filter-reset>Limpar filtros</button>` : ""}
    </section>
  `;
}

// Funcao nomeada de proposito: bindEventTable roda a cada render, e registrar
// o MESMO referencia no document e no-op para o navegador. Uma arrow inline
// acumularia um listener por render.
function fecharGavetasDeEvento(evento) {
  const dentro = evento.target?.closest?.("[data-event-group]");
  document.querySelectorAll("[data-event-group]").forEach((gaveta) => {
    if (gaveta !== dentro && gaveta.open) gaveta.open = false;
  });
}

function bindEventTable() {
  document.querySelectorAll("[data-event-group]").forEach((gaveta) => {
    gaveta.addEventListener("toggle", () => {
      const chave = gaveta.dataset.eventGroup;
      if (!chave) return;
      state.eventFilterOpen = state.eventFilterOpen || {};
      // So uma gaveta aberta por vez: elas ficam lado a lado e os popovers se
      // sobrepoem, entao duas abertas escondem uma a outra.
      if (gaveta.open) {
        Object.keys(state.eventFilterOpen).forEach((k) => {
          if (k !== chave) state.eventFilterOpen[k] = false;
        });
        document.querySelectorAll("[data-event-group]").forEach((outra) => {
          if (outra !== gaveta) outra.open = false;
        });
      }
      state.eventFilterOpen[chave] = gaveta.open;
    });
  });
  // Clique fora fecha. Sem isso a gaveta so fecha clicando de novo no proprio
  // resumo, que nao e o que se espera de um popover.
  document.addEventListener("click", fecharGavetasDeEvento);
  document.querySelectorAll("[data-event-sort]").forEach((botao) => {
    botao.addEventListener("click", () => {
      cycleEventSort(botao.dataset.eventSort || "");
      pushFilterState("events", eventFiltersToQuery(), `[data-event-sort="${botao.dataset.eventSort}"]`);
    });
  });
  document.querySelectorAll("[data-event-filter]").forEach((botao) => {
    botao.addEventListener("click", () => {
      const chave = botao.dataset.eventFilter;
      const valor = botao.dataset.valor;
      const f = state.eventFilters || {};
      const atual = f[chave] || [];
      f[chave] = atual.includes(valor) ? atual.filter((v) => v !== valor) : atual.concat(valor);
      state.eventFilters = f;
      pushFilterState("events", eventFiltersToQuery(), `[data-event-filter="${chave}"][data-valor="${valor}"]`);
    });
  });
  document.querySelector("[data-event-filter-reset]")?.addEventListener("click", () => {
    state.eventFilters = { tier: [], tipo: [], formato: [], premio: [] };
    pushFilterState("events", eventFiltersToQuery());
  });
}

// --- Eixos de ordenacao e filtro da tabela de /eventos -----------------------
// Cada eixo abaixo foi medido nos 18 campeonatos antes de virar coluna; os
// comentarios guardam a distribuicao, porque ela e o que decide se a coluna
// discrimina ou so ocupa largura.

// Tier: A=9, B=5, S=1, C=1, sem=2. Ordinal, entao ordenar por ordem alfabetica
// poria B antes de S. Sem tier vai para o fim nas duas direcoes.
const EVENT_TIER_ORDEM = { S: 5, A: 4, B: 3, C: 2, D: 1 };

function eventTierChave(event) {
  const t = String(event?.tier || "").trim().replace(/^tier\s*/i, "").toUpperCase();
  return /^[SABCD]$/.test(t) ? t : "";
}

function eventTierValor(event) {
  return EVENT_TIER_ORDEM[eventTierChave(event)] || 0;
}

// Tipo: o campo bruto tem 8 valores distintos para 18 campeonatos - quatro
// deles com um unico membro ("Online - Torneio Local", "Online + Final
// presencial"...). Filtrar por 8 opcoes onde metade separa uma linha nao ajuda
// ninguem, entao o filtro agrupa por onde se joga: Online 13, Hibrido 2,
// Presencial 1. A coluna continua mostrando o texto original.
function eventTipoGrupo(event) {
  const t = String(event?.type || "").trim();
  if (!t) return "";
  const online = /online/i.test(t);
  const presencial = /presencial/i.test(t);
  if (online && presencial) return "Híbrido";
  if (presencial) return "Presencial";
  return "Online";
}

// Formato nao e string: e um objeto { summary, details, standings }. Ler
// event.format direto devolve "[object Object]".
// A lista e o filtro usam o nome curto: 16 resumos diferentes eram 6 formatos na
// pratica. O resumo inteiro e os detalhes ficam em Informacoes, no campeonato.
function eventFormatoLabel(event) {
  const resumo = String(event?.format?.summary || (typeof event?.format === "string" ? event.format : "")).trim();
  if (!resumo) return "";
  const suico = /su[ií][çc]/i.test(resumo);
  if (suico && /\+|classificat|elimina|playoff/i.test(resumo)) return "Suíço + playoffs";
  if (suico) return "Sistema suíço";
  if (/grupo|gsl|pontos corridos.*playoff/i.test(resumo)) return "Grupos + playoffs";
  if (/pontos corridos/i.test(resumo)) return "Pontos corridos";
  if (/elimina[çc][ãa]o dupla/i.test(resumo)) return "Eliminação dupla";
  if (/elimina[çc][ãa]o simples|vagas/i.test(resumo)) return "Eliminação simples";
  return resumo;
}

// Prizepool: 11 dos 18 gravam "-", 2 gravam nulo, 3 tem "R$1.000", 1 tem
// "R$2.000" e 1 tem "5x Monitores AGON CS24A/P", que e premio de verdade mas
// nao e dinheiro. Ordenar por valor puro jogaria o premio em produto junto dos
// 13 zeros, entao ele entra acima deles e abaixo de qualquer quantia.
function eventPremioValor(event) {
  const bruto = String(event?.prizePool || event?.prize || "").trim();
  if (!bruto || bruto === "-" || /^a definir$/i.test(bruto)) return 0;
  const numero = bruto.replace(/[^\d,.]/g, "").replace(/\./g, "").replace(",", ".");
  const valor = Number.parseFloat(numero);
  return Number.isFinite(valor) && valor > 0 ? valor : 0.5;
}

function eventTemPremio(event) {
  return eventPremioValor(event) > 0;
}

const EVENT_PREMIO_OPCOES = [{ id: "com", label: "Com premiação" }, { id: "sem", label: "Sem premiação" }];

function eventPremioChave(event) {
  return eventTemPremio(event) ? "com" : "sem";
}

function eventTimesTotal(event) {
  return Number(event?.teamCount || 0) || (event?.teams || []).length;
}

const EVENT_ORDENAVEL = {
  nome: (e) => String(e.name || ""),
  // Data ordena pelo TERMINO. O seletor "ordenar por inicio" saiu: eram duas
  // perguntas competindo pelo mesmo eixo, e o cabecalho ja da as duas direcoes.
  data: (e) => Number(e.end || e.start || 0),
  tier: eventTierValor,
  premio: eventPremioValor,
  times: eventTimesTotal,
  tipo: (e) => eventTipoGrupo(e),
  formato: eventFormatoLabel,
};

// Mesmo ciclo do /ranking: padrao -> desc -> asc -> padrao.
function cycleEventSort(key) {
  if (!key) return;
  const atual = state.eventTableSort || { key: "", direction: "default" };
  if (atual.key !== key || atual.direction === "default") state.eventTableSort = { key, direction: "desc" };
  else if (atual.direction === "desc") state.eventTableSort = { key, direction: "asc" };
  else state.eventTableSort = { key: "", direction: "default" };
}

function eventSortHeader(key, label, extra = "") {
  const sort = state.eventTableSort || {};
  const ativo = sort.key === key && sort.direction !== "default";
  const direcao = ativo ? sort.direction : "default";
  const titulo = direcao === "desc" ? "Ordenado decrescente" : direcao === "asc" ? "Ordenado crescente" : "Ordenação padrão";
  return `
    <button class="event-sort-header ${extra} ${ativo ? "active" : ""}" type="button" data-event-sort="${escapeHtml(key)}" data-sort-direction="${direcao}" aria-label="${escapeHtml(`${label}: ${titulo}`)}" title="${escapeHtml(titulo)}">
      <span>${escapeHtml(label)}</span>
      <i aria-hidden="true">${direcao === "desc" ? "↓" : direcao === "asc" ? "↑" : ""}</i>
    </button>
  `;
}

function eventFiltrosAtivos() {
  const f = state.eventFilters || {};
  return (f.tier || []).length + (f.tipo || []).length + (f.formato || []).length + (f.premio || []).length;
}

// Uma entrada por campeonato: cada etapa vira o campeonato dela, na posicao da
// primeira etapa que aparece; as outras etapas do mesmo campeonato saem.
function listaDeCampeonatos(eventos) {
  const vistos = new Set();
  const lista = [];
  (eventos || []).forEach((event) => {
    const campeonato = campeonatoDaEtapa(event);
    if (!campeonato) return lista.push(event);
    if (vistos.has(campeonato.id)) return;
    vistos.add(campeonato.id);
    lista.push(campeonato);
  });
  return lista;
}

// Os filtros olham as etapas: o campeonato entra se qualquer etapa passou.
function eventsFiltrados() {
  const f = state.eventFilters || {};
  let lista = listaDeCampeonatos(sortedEvents("end").filter((e) => {
    if ((f.tier || []).length && !f.tier.includes(eventTierChave(e) || "sem")) return false;
    if ((f.tipo || []).length && !f.tipo.includes(eventTipoGrupo(e) || "sem")) return false;
    if ((f.formato || []).length && !f.formato.includes(eventFormatoLabel(e) || "sem")) return false;
    if ((f.premio || []).length && !f.premio.includes(eventPremioChave(e))) return false;
    return true;
  }));
  const sort = state.eventTableSort || {};
  if (sort.key && sort.direction !== "default" && EVENT_ORDENAVEL[sort.key]) {
    const ler = EVENT_ORDENAVEL[sort.key];
    const sinal = sort.direction === "asc" ? 1 : -1;
    lista = lista.slice().sort((a, b) => {
      const va = ler(a);
      const vb = ler(b);
      let d;
      if (typeof va === "number" && typeof vb === "number") d = va - vb;
      else d = String(va).localeCompare(String(vb), "pt-BR", { sensitivity: "base" });
      // Empate mantem a ordem por data, que e a ordem natural da pagina.
      return d ? d * sinal : 0;
    });
  }
  return lista;
}

function eventFiltersToQuery() {
  const p = new URLSearchParams();
  const f = state.eventFilters || {};
  if ((f.tier || []).length) p.set("tier", f.tier.join(LISTA_SEP));
  if ((f.tipo || []).length) p.set("tipo", f.tipo.join(LISTA_SEP));
  if ((f.formato || []).length) p.set("formato", f.formato.join(LISTA_SEP));
  if ((f.premio || []).length) p.set("premio", f.premio.join(LISTA_SEP));
  const sort = state.eventTableSort || {};
  if (sort.key && sort.direction !== "default") p.set("ord", sort.key + ":" + sort.direction);
  return p;
}

function applyEventFiltersFromQuery(params) {
  const ler = (chave) => {
    const v = params.get(chave);
    return v ? v.split(LISTA_SEP).filter(Boolean) : [];
  };
  state.eventFilters = {
    tier: ler("tier"),
    tipo: ler("tipo"),
    formato: ler("formato"),
    // "1" era o link do antigo botao "Com premiacao".
    premio: params.get("premio") === "1" ? ["com"] : ler("premio"),
  };
  const ord = String(params.get("ord") || "");
  const [chave, direcao] = ord.split(":");
  state.eventTableSort = EVENT_ORDENAVEL[chave] && (direcao === "asc" || direcao === "desc")
    ? { key: chave, direction: direcao }
    : { key: "", direction: "default" };
}

// O tier sai de dentro de .event-row-facts e vira trilha propria da linha. Duas
// razoes: como fato rotulado ele saia em tinta de 14px, identico ao "8" de
// Times - a unica pagina que lista tier era a unica que nao usava a escala de
// cor que ja existe em :root. E, na fila dos fatos, ele vinha depois de "N
// Times", cuja largura varia entre 8, 26 e 40: a letra caia num x diferente por
// linha. Em trilha propria ela fica na mesma coluna nas 18.
//
// Os dois campeonatos sem tier (Pre-JUBS e LPE) devolvem a celula vazia em vez
// de string vazia: sem o elemento, o proximo item herdaria a trilha e a linha
// inteira sairia deslocada.
function eventTierCell(event) {
  const selo = eventTierBadge(event);
  return selo || `<span class="event-tier" aria-hidden="true"></span>`;
}

// "-" e o que a planilha grava quando nao ha premiacao, e isso vale para 11 dos
// 18 campeonatos (mais 2 com o campo nulo). Um fato rotulado cujo valor e um
// travessao gasta uma trilha inteira para dizer nada, entao o Prizepool so
// aparece quando ha premio de verdade.
function eventPrizeFact(event) {
  const bruto = String(event?.prizePool || event?.prize || "").trim();
  if (!bruto || bruto === "-" || /^a definir$/i.test(bruto)) return "";
  return eventFact(bruto, "Prizepool");
}

function eventFact(value, label, extra = "") {
  return `
    <span class="event-fact ${escapeHtml(extra)}" title="${escapeHtml(String(value || "-"))}">
      <strong>${escapeHtml(String(value || "-"))}</strong>
      <small>${escapeHtml(label)}</small>
    </span>
  `;
}

function eventFeaturedTeamIds(event, matches = [], limit = 8) {
  const ids = [];
  const seen = new Set();
  const add = (teamId) => {
    if (!teamId || seen.has(teamId)) return;
    seen.add(teamId);
    ids.push(teamId);
  };

  if (event.placements?.length) {
    normalizePlacementRowsForDisplay(event.placements)
      .slice()
      .sort((a, b) => (a.placementStart || 999) - (b.placementStart || 999) || a.originalIndex - b.originalIndex)
      .forEach((row) => add(row.id || row.teamId));
  }

  if (ids.length < limit) {
    eventStandings(matches).forEach((row) => add(row.id));
  }

  if (ids.length < limit) {
    (event.teams || [])
      .map((teamId) => tournamentTeamById(event, teamId))
      .filter(Boolean)
      .sort(compareTeamsByCanonicalRank)
      .forEach((team) => add(team.id));
  }

  return ids.slice(0, limit);
}

function eventParticipantStack(teams, teamTotal) {
  if (!teams.length) return `<span class="event-team-stack muted">Sem equipes</span>`;
  const remaining = Math.max(0, teamTotal - teams.length);
  return `
    <span class="event-team-stack" aria-label="${escapeHtml(teams.map((team) => team.name).join(", "))}">
      ${teams.map((team) => `<span class="event-team-badge" title="${escapeHtml(team.name)}">${teamLogo(team.id, "event-participant-logo")}</span>`).join("")}
      ${remaining ? `<span class="event-team-extra" title="${escapeHtml(`${remaining} equipes restantes`)}">+${remaining}</span>` : ""}
    </span>
  `;
}

function playerDirectoryName(player) {
  return player?.nick || player?.apiNick || player?.handle || "Jogador";
}

function playerCurrentNick(player) {
  const nicks = (player?.nickHistory || []).filter(Boolean);
  return player?.handle || nicks[nicks.length - 1] || player?.apiNick || player?.nick || "Nick em atualização";
}

function bindSearch() {
  const input = document.getElementById("global-search");
  const results = document.getElementById("search-results");
  if (!input || !results) return;

  const renderResults = () => {
    state.search = input.value;
    const query = normalize(input.value);
    if (!query) {
      state.searchOpen = false;
      results.classList.remove("open");
      results.innerHTML = "";
      return;
    }
    const rows = filtrarBusca(query);
    state.searchOpen = true;
    results.classList.add("open");
    input.setAttribute("aria-expanded", "true");
    results.innerHTML = rows.length
      ? rows.map((item, index) => renderSearchResult(item, index)).join("")
      : `<div class="empty-state">Nenhuma entidade encontrada.</div>`;
    anunciar(rows.length);
    ativo = -1;
    sincronizarAtivo();
    results.querySelectorAll("[data-path]").forEach((button) => {
      button.addEventListener("click", () => abrir(button));
    });
  };

  const status = document.getElementById("search-status");
  let ativo = -1;

  const anunciar = (n) => {
    if (!status) return;
    status.textContent = n === 0 ? "Nenhum resultado." : n === 1 ? "1 resultado." : `${n} resultados.`;
  };

  const opcoes = () => [...results.querySelectorAll("[data-path]")];

  const sincronizarAtivo = () => {
    const lista = opcoes();
    lista.forEach((el, i) => {
      const marcado = i === ativo;
      el.setAttribute("aria-selected", String(marcado));
      el.classList.toggle("is-active", marcado);
      if (marcado) el.scrollIntoView({ block: "nearest" });
    });
    if (ativo >= 0 && lista[ativo]) input.setAttribute("aria-activedescendant", lista[ativo].id);
    else input.removeAttribute("aria-activedescendant");
  };

  const mover = (passo) => {
    const lista = opcoes();
    if (!lista.length) return;
    const n = lista.length;
    if (ativo === -1) ativo = passo > 0 ? 0 : n - 1;
    else {
      ativo += passo;
      if (ativo < 0) ativo = n - 1;
      else if (ativo >= n) ativo = 0;
    }
    sincronizarAtivo();
  };

  const fechar = () => {
    state.searchOpen = false;
    results.classList.remove("open");
    input.setAttribute("aria-expanded", "false");
    input.removeAttribute("aria-activedescendant");
    ativo = -1;
  };

  function abrir(button) {
    state.search = "";
    fechar();
    window.location.hash = `#/${button.dataset.path}`;
  }

  input.addEventListener("input", renderResults);
  input.addEventListener("focus", renderResults);

  input.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown") { event.preventDefault(); mover(1); return; }
    if (event.key === "ArrowUp") { event.preventDefault(); mover(-1); return; }
    if (event.key === "Enter") {
      const lista = opcoes();
      if (ativo >= 0 && lista[ativo]) { event.preventDefault(); abrir(lista[ativo]); }
      return;
    }
    if (event.key === "Escape") { event.preventDefault(); fechar(); input.blur(); }
  });

  // O selo "/" ao lado do campo prometia este atalho desde sempre.
  if (!state.searchHotkeyBound) {
    state.searchHotkeyBound = true;
    document.addEventListener("keydown", (event) => {
      if (event.key !== "/" || event.ctrlKey || event.metaKey || event.altKey) return;
      const alvo = event.target;
      const digitando = alvo && (alvo.isContentEditable || /^(input|textarea|select)$/i.test(alvo.tagName));
      if (digitando) return;
      const campo = document.getElementById("global-search");
      if (!campo || campo.disabled) return;
      event.preventDefault();
      campo.focus();
      campo.select();
    });
  }

  document.addEventListener("click", (event) => {
    if (!event.target.closest(".global-search")) fechar();
  });
  renderResults();
}

function searchEntities() {
  const db = state.db;
  return [
    ...resultadosDeCampeonato(),
    ...db.teams.map(searchTeamResult),
    ...db.teams.flatMap(searchTeamPhaseResults),
    ...db.maps.map((map) => ({
      type: "map",
      path: `maps/${map.id}`,
      label: map.name,
      meta: `${map.matches} partidas`,
      entity: map,
      searchText: map.name,
      visual: mapLogo(map.id),
      colors: map.colors,
      mark: map.name.slice(0, 3).toUpperCase(),
    })),
    ...db.players.filter(playerTemPerfil).map(searchPlayerResult),
    ...(window.Community?.usuariosParaBusca() || []).map(searchUserResult),
    ...allMatchSeries().map((series) => {
      const score = matchListScore(series);
      const event = state.db?.tournaments.find((row) => row.id === series.eventId);
      const patch = matchSearchPatchLabel(series);
      return {
        type: "match",
        path: matchSeriesRoute(series),
        label: `${series.teamA.name} ${score.a} x ${score.b} ${series.teamB.name}`,
        meta: `${score.label} - ${score.detail} - ${formatDate(series.startedAt, "time")} - ${event?.name || "Campeonato"}${patch ? ` - ${patch}` : ""}`,
        entity: series,
        searchText: matchSearchText(series, score, event, patch),
        colors: ["#181715", "#d8323c"],
        mark: score.label.slice(0, 3).toUpperCase(),
      };
    }),
  ];
}

// Usuario da comunidade. Sem isso, a unica forma de chegar a um perfil era
// achar um comentario da pessoa - uma mencao @fulano nao tinha caminho de volta.
function searchUserResult(u) {
  return {
    type: "user",
    path: `u/${u.username}`,
    label: u.username,
    meta: u.role === "admin" ? "Administrador" : "Usuário",
    entity: u,
    searchText: `${u.username} usuario perfil`,
  };
}

function searchTeamResult(team) {
  const tag = teamSearchTagLabel(team);
  const stateLabel = teamStateSearchLabel(team);
  const institution = teamInstitutionLabel(team);
  return {
    type: "team",
    path: `teams/${team.id}`,
    label: team.name,
    meta: `${tag} - ${stateLabel} - ${institution}`,
    entity: team,
    searchText: `${team.name} ${team.id} ${tag} ${team.shortTag || ""} ${stateLabel} ${institution}`,
  };
}

// Cada nome antigo da linha do tempo (CAASO Hogs, Dark UFRJ...) continua achavel
// na busca e abre o perfil da equipe atual ja naquela fase.
function searchTeamPhaseResults(team) {
  const stateLabel = teamStateSearchLabel(team);
  const institution = teamInstitutionLabel(team);
  return (team.profile?.nomes || []).filter((fase) => fase?.id && fase.nome).map((fase) => {
    const tag = fase.tag || teamSearchTagLabel(team);
    return {
      type: "team",
      path: `teams/${team.id}?fase=${encodeURIComponent(fase.id)}`,
      label: fase.nome,
      meta: `${tag} - ${stateLabel} - ${institution}`,
      entity: team,
      fase,
      searchText: `${fase.nome} ${fase.id} ${tag} ${stateLabel} ${institution}`,
    };
  });
}

function searchPlayerResult(player) {
  const team = playerPrimaryTeam(player);
  const teamName = team?.name || "Sem time";
  const teamTag = team ? teamSearchTagLabel(team) : "";
  return {
    type: "player",
    path: playerPath(player),
    label: player.nick,
    meta: `${player.handle || player.nick} - atual: ${teamName}`,
    entity: player,
    searchText: `${player.nick} ${player.handle || ""} ${(player.nickHistory || []).join(" ")} ${teamName} ${teamTag}`,
  };
}

// Um resultado por campeonato, pelo nome dele e pelos nomes antigos. A etapa so
// aparece sozinha quando a busca vai alem do nome do campeonato: "univava" acha o
// campeonato; "classificatoria 2" e "univava classificatoria 2" acham a etapa.
function resultadosDeCampeonato() {
  const itens = [];
  listaDeCampeonatos(sortedEvents("end")).forEach((item) => {
    if (!item.isCampeonato) {
      itens.push(searchTournamentResult(item));
      return;
    }
    const nomes = [item.nome, ...item.nomesAntigos].join(" ");
    const nomesNormalizados = normalize(nomes);
    itens.push({ ...searchTournamentResult(item), searchText: nomes });
    item.etapas.forEach((etapa) => {
      itens.push({
        ...searchTournamentResult(etapa),
        searchText: `${etapa.name} ${etapa.nomeOriginal || ""}`,
        mostrarSe: (query) => !nomesNormalizados.includes(query),
      });
    });
  });
  return itens;
}

// O filtro da barra de busca: o texto inteiro dentro do pesquisavel do item, e a
// regra propria do item quando ele tem uma.
function filtrarBusca(query) {
  return searchEntities()
    .filter((item) => normalize(item.searchText || `${item.label} ${item.meta || ""}`).includes(query) && (!item.mostrarSe || item.mostrarSe(query)))
    .slice(0, 10);
}

function searchTournamentResult(event) {
  const start = tournamentSearchStartLabel(event);
  const tier = tournamentTierSearchLabel(event);
  return {
    type: "tournament",
    path: `tournaments/${event.id}`,
    label: event.name,
    meta: `${tier} - ${start} - ${event.status || "Status a definir"} - ${event.matches} partidas`,
    entity: event,
    searchText: event.name,
  };
}

function matchSearchText(series, score, event, patch) {
  const teamA = matchSearchTeamAliases(series.teamA);
  const teamB = matchSearchTeamAliases(series.teamB);
  const primaryA = teamA[0] || series.teamA.name;
  const primaryB = teamB[0] || series.teamB.name;
  const scoreVariants = matchSearchScoreVariants(score.a, score.b);
  const reverseScoreVariants = matchSearchScoreVariants(score.b, score.a);
  const scorePhrases = scoreVariants.flatMap((scoreText) => [
    scoreText,
    `${primaryA} ${scoreText} ${primaryB}`,
    `${primaryA} ${scoreText}`,
    `${scoreText} ${primaryB}`,
  ]);
  const reverseScorePhrases = reverseScoreVariants.flatMap((scoreText) => [
    `${primaryB} ${scoreText} ${primaryA}`,
    `${primaryB} ${scoreText}`,
    `${scoreText} ${primaryA}`,
  ]);
  return [
    `${primaryA} ${score.a} x ${score.b} ${primaryB}`,
    ...teamA,
    ...teamB,
    ...scorePhrases,
    ...reverseScorePhrases,
    score.label,
    score.detail,
    event?.name || "",
    formatDate(series.startedAt, "time"),
    patch,
  ].filter(Boolean).join(" ");
}

function matchSearchTeamAliases(team) {
  const dbTeam = teamById(team?.id);
  return [...new Set([
    team?.name,
    dbTeam?.name,
    dbTeam ? teamSearchTagLabel(dbTeam) : "",
    team?.tag,
    dbTeam?.tag,
    dbTeam?.shortTag,
    dbTeam?.sourceTag,
    team?.id,
  ].filter(Boolean))];
}

function matchSearchScoreVariants(a, b) {
  return [
    `${a} x ${b}`,
    `${a}x${b}`,
    `${a} : ${b}`,
    `${a}:${b}`,
    `${a} - ${b}`,
    `${a}-${b}`,
  ];
}

function renderSearchResult(item, index = 0) {
  searchResultIndex = index;
  const renderers = {
    team: renderTeamSearchResult,
    player: renderPlayerSearchResult,
    tournament: renderTournamentSearchResult,
    match: renderMatchSearchResult,
    map: renderMapSearchResult,
    user: renderUserSearchResult,
  };
  return (renderers[item.type] || renderGenericSearchResult)(item);
}

function renderSearchButton(item, content, index = 0) {
  const type = item.type || "generic";
  const pos = index || searchResultIndex;
  return `<button class="search-result search-result-${escapeHtml(type)}" type="button" role="option" id="search-option-${pos}" aria-selected="false" data-path="${escapeHtml(item.path)}" aria-label="${escapeHtml(`Abrir ${item.label}`)}">${content}</button>`;
}

function renderTeamSearchResult(item) {
  const team = item.entity;
  const fase = item.fase || null;
  const tag = fase?.tag || teamSearchTagLabel(team);
  const stateLabel = teamStateSearchLabel(team);
  const institution = teamInstitutionLabel(team);
  // Nome antigo: escudo da epoca quando ela tem um, e o periodo para separar de
  // uma equipe de mesmo nome (a UFRJ Canis de 2026 e a fase de 2025 da Thunders).
  const faseLogo = fase?.logo ? assetPath(fase.logo) : "";
  const visual = faseLogo
    ? `<span class="team-logo clean-logo search-entity-logo"><img src="${escapeHtml(faseLogo)}" alt="${escapeHtml(`Logo ${fase.nome}`)}" loading="lazy" onerror="this.closest('.team-logo').classList.add('logo-empty'); this.remove()" /></span>`
    : teamLogo(team.id, "search-entity-logo");
  const periodo = fase?.desde ? teamFasePeriodo({ desde: new Date(`${fase.desde}T12:00:00`).getTime(), ate: fase.ate ? new Date(`${fase.ate}T12:00:00`).getTime() : 0 }) : "";
  return renderSearchButton(
    item,
    `
      <span class="search-result-visual">${visual}</span>
      <span class="search-result-content">
        <span class="search-result-kicker">Time</span>
        <strong class="search-result-title">${escapeHtml(fase?.nome || team.name)}</strong>
        <span class="search-result-meta">${escapeHtml(periodo ? `${institution} - ${periodo}` : institution)}</span>
        <span class="search-team-facts">
          <span class="search-team-tag">${escapeHtml(tag)}</span>
          <span class="search-team-state">${teamSearchStateFlag(team)}<span>${escapeHtml(stateLabel)}</span></span>
        </span>
      </span>
    `,
  );
}

function renderPlayerSearchResult(item) {
  const player = item.entity;
  const team = playerPrimaryTeam(player);
  return renderSearchButton(
    item,
    `
      <span class="search-result-visual">${playerLogo(player.id, "search-player-photo")}</span>
      <span class="search-result-content">
        <span class="search-result-kicker">Jogador</span>
        <strong class="search-result-title">${escapeHtml(player.nick)}</strong>
        <span class="search-player-handle">${escapeHtml(player.handle || player.nick)}</span>
        <span class="search-player-team-line">
          ${team ? teamLogo(team.id, "search-player-team-logo") : `<span class="team-logo clean-logo logo-empty search-player-team-logo" aria-label="Sem time"></span>`}
          <span>${escapeHtml(team?.name || "Sem time")}</span>
          ${team ? `<em>${escapeHtml(teamSearchTagLabel(team))}</em>` : ""}
        </span>
      </span>
    `,
  );
}

function renderTournamentSearchResult(item) {
  const event = item.entity;
  return renderSearchButton(
    item,
    `
      <span class="search-result-visual">${eventLogo(event, "search-event-logo")}</span>
      <span class="search-result-content">
        <span class="search-result-kicker">Campeonato</span>
        <strong class="search-result-title">${escapeHtml(event.name)}</strong>
        <span class="search-tournament-facts">
          <span>${escapeHtml(tournamentTierSearchLabel(event))}</span>
          <span>${escapeHtml(tournamentSearchStartLabel(event))}</span>
          <span>${escapeHtml(event.status || "Status a definir")}</span>
          <span>${escapeHtml(`${event.matches} partidas`)}</span>
        </span>
      </span>
    `,
  );
}

function renderMatchSearchResult(item) {
  const series = item.entity;
  const score = matchListScore(series);
  const event = state.db?.tournaments.find((row) => row.id === series.eventId);
  return renderSearchButton(
    item,
    `
      ${matchSearchMapVisual(series)}
      <span class="search-result-content">
        <span class="search-result-kicker">Partida</span>
        <strong class="search-match-score-line">
          <span class="search-match-team search-match-team-a">
            ${teamLogo(series.teamA.id, "search-match-team-logo")}
            <span>${escapeHtml(series.teamA.name)}</span>
          </span>
          <b><span class="${scoreNumberClass(score.a, score.b)}">${escapeHtml(String(score.a))}</span><i>:</i><span class="${scoreNumberClass(score.b, score.a)}">${escapeHtml(String(score.b))}</span></b>
          <span class="search-match-team search-match-team-b">
            <span>${escapeHtml(series.teamB.name)}</span>
            ${teamLogo(series.teamB.id, "search-match-team-logo")}
          </span>
        </strong>
        <span class="search-match-event-line">
          ${event ? eventLogo(event, "search-match-event-logo") : ""}
          <span>${escapeHtml(event?.name || "Campeonato")}</span>
        </span>
        <span class="search-match-facts">
          <span>${escapeHtml(formatDate(series.startedAt, "time"))}</span>
          ${matchSearchPatchLabel(series) ? `<span>${escapeHtml(matchSearchPatchLabel(series))}</span>` : ""}
          <span>${escapeHtml(matchSearchMapLabel(series, score))}</span>
        </span>
      </span>
    `,
  );
}

function matchSearchMapVisual(series) {
  const maps = series.maps || [];
  const mapCount = Math.max(maps.length, 1);
  const countClass = mapCount > 1 ? "multi" : "single";
  return `
    <span class="search-result-visual search-match-map-visual ${countClass}" style="--search-match-map-count:${mapCount}" aria-label="${escapeHtml(matchSearchMapLabel(series, matchListScore(series)))}">
      ${maps.map(searchMatchMapImage).join("")}
    </span>
  `;
}

function searchMatchMapImage(match, index) {
  const asset = matchMapAsset(match);
  const label = asset.name || match?.mapName || `Mapa ${index + 1}`;
  return `
    <span class="search-match-map-image ${asset.src ? "" : "missing-image"}" title="${escapeHtml(label)}">
      ${asset.src ? `<img src="${escapeHtml(asset.src)}" data-fallback="${escapeHtml(asset.fallback)}" alt="${escapeHtml(label)}" loading="lazy" onerror="mapArtError(this)" />` : ""}
      <span>${escapeHtml(label.slice(0, 3).toUpperCase())}</span>
    </span>
  `;
}

function matchSearchMapLabel(series, score = matchListScore(series)) {
  if (series.mapCount > 1) return `${score.label} - ${score.detail}`;
  return score.detail || score.label || "Mapa";
}

function matchSearchPatchLabel(series) {
  const patches = [...new Set((series.maps || []).map((match) => patchLabel(match?.gameVersion || "")).filter((label) => label && label !== "-"))];
  if (!patches.length) return "";
  return `Patch ${patches.slice(0, 3).join(" / ")}${patches.length > 3 ? ` +${patches.length - 3}` : ""}`;
}

function mapSearchMatches(map) {
  const mapId = String(map?.id || "");
  const mapNameKey = normalizeNameKey(map?.name || "");
  const mapIdKey = normalizeNameKey(mapId);
  return (state.db?.matches || []).filter((match) => {
    const matchMapNameKey = normalizeNameKey(match.mapName || "");
    const matchMapIdKey = normalizeNameKey(match.mapId || "");
    return (mapId && match.mapId === mapId) || (mapNameKey && matchMapNameKey === mapNameKey) || (mapIdKey && matchMapIdKey === mapIdKey);
  });
}

function mapSearchPatchLabel(map) {
  const patches = [...new Set(mapSearchMatches(map).map((match) => patchLabel(match?.gameVersion || "")).filter((label) => label && label !== "-"))];
  if (!patches.length) return "";
  return `Patch ${patches.slice(0, 4).join(" / ")}${patches.length > 4 ? ` +${patches.length - 4}` : ""}`;
}

function mapSearchTournaments(map) {
  const tournamentsById = new Map((state.db?.tournaments || []).map((event) => [event.id, event]));
  const eventIds = [...new Set(mapSearchMatches(map).map((match) => match.eventId).filter(Boolean))];
  return eventIds.map((eventId) => tournamentsById.get(eventId)).filter(Boolean);
}

function mapSearchTournamentLogos(map) {
  const events = mapSearchTournaments(map);
  const visibleEvents = events.slice(0, 5);
  const extra = events.length - visibleEvents.length;
  if (!events.length) return `<span class="search-map-events search-map-events-empty">Sem campeonatos</span>`;
  return `
    <span class="search-map-events" aria-label="${escapeHtml(`${events.length} campeonatos`)}">
      ${visibleEvents.map((event) => eventLogo(event, "search-map-event-logo")).join("")}
      ${extra ? `<span class="search-map-event-extra">+${extra}</span>` : ""}
    </span>
  `;
}

function mapSearchBanner(map) {
  const art = mapArtAttrs(map);
  const label = map?.name || "Mapa";
  return `
    <span class="search-result-visual search-map-banner ${art ? "" : "missing-image"}" aria-label="${escapeHtml(label)}">
      ${art ? `<img src="${escapeHtml(art.src)}" data-fallback="${escapeHtml(art.fallback)}" alt="${escapeHtml(`Mapa ${label}`)}" loading="lazy" onerror="mapArtError(this)" />` : ""}
      <span>${escapeHtml(label.slice(0, 3).toUpperCase())}</span>
    </span>
  `;
}

function renderMapSearchResult(item) {
  const map = item.entity;
  return renderSearchButton(
    item,
    `
      ${mapSearchBanner(map)}
      <span class="search-result-content">
        <span class="search-result-kicker">Mapa</span>
        <strong class="search-result-title">${escapeHtml(map.name)}</strong>
        <span class="search-map-stats">${escapeHtml(`${map.matches} partidas - ${map.rounds} rounds`)}</span>
        <span class="search-map-facts">
          ${mapSearchPatchLabel(map) ? `<span>${escapeHtml(mapSearchPatchLabel(map))}</span>` : ""}
          ${mapSearchTournamentLogos(map)}
        </span>
      </span>
    `,
  );
}

function renderUserSearchResult(item) {
  return renderSearchButton(
    item,
    `
      <span class="search-result-visual">${window.Comments ? window.Comments.avatar(item.label) : ""}</span>
      <span class="search-result-content">
        <span class="search-result-kicker">${escapeHtml(item.meta)}</span>
        <strong class="search-result-title">${escapeHtml(item.label)}</strong>
        <span class="search-result-meta">Perfil no UNIVLR</span>
      </span>
    `,
  );
}

function renderGenericSearchResult(item) {
  const visual = item.visual || logo(item.mark || "?", item.colors || ["#181715", "#d8323c"], "search-entity-logo");
  return renderSearchButton(
    item,
    `
      <span class="search-result-visual">${visual}</span>
      <span class="search-result-content">
        <span class="search-result-kicker">Resultado</span>
        <strong class="search-result-title">${escapeHtml(item.label)}</strong>
        <span class="search-result-meta">${escapeHtml(item.meta || "")}</span>
      </span>
    `,
  );
}

function teamSearchTagLabel(team) {
  return team?.sourceTag || team?.tag || team?.shortTag || team?.id || "Sem tag";
}

function teamStateSearchLabel(team) {
  return teamStateSearchInfo(team).label;
}

function teamStateSearchInfo(team) {
  const profile = team?.profile || {};
  const code = profile.state || team?.state || "";
  const name = profile.stateName || team?.stateName || "";
  const flag = profile.flag || team?.flag || team?.stateFlag || "";
  const label = code && name && normalize(name) !== normalize(code) ? `${name} - ${code}` : name || code || "Estado não informado";
  return { code, name, flag, label };
}

function teamSearchStateFlag(team) {
  const state = teamStateSearchInfo(team);
  const fallback = escapeHtml(state.code || "UF");
  return state.flag
    ? `<img class="search-state-flag" src="${escapeHtml(assetPath(state.flag))}" alt="Bandeira ${escapeHtml(state.label)}" loading="lazy" onerror="this.replaceWith(this.nextElementSibling)" /><span class="search-state-flag placeholder">${fallback}</span>`
    : `<span class="search-state-flag placeholder">${fallback}</span>`;
}

function teamInstitutionLabel(team) {
  const profile = team?.profile || {};
  return profile.org || team?.org || profile.orgTag || team?.orgTag || "Instituição não informada";
}

function tournamentSearchStartLabel(event) {
  return event?.start ? `Início ${formatDate(event.start)}` : "Início a definir";
}

function tournamentTierSearchLabel(event) {
  const tier = String(event?.tier || "").trim();
  if (!tier) return "Tier a definir";
  return /^tier\b/i.test(tier) ? tier : `Tier ${tier}`;
}

function metric(value, label) {
  return `<div class="metric-tile"><span class="metric-value">${value}</span><span class="metric-label">${escapeHtml(label)}</span></div>`;
}

function sectionHead(title, desc, routeName, linkLabel) {
  return `<header class="vp-sec"><h2>${escapeHtml(title)}</h2>${desc ? `<span class="vp-sec-aside">${escapeHtml(desc)}</span>` : ""}${routeName ? `<a class="vp-sec-more" href="#/${routeName}">${escapeHtml(linkLabel)}</a>` : ""}</header>`;
}

function matchCard(item) {
  const series = normalizeMatchItem(item);
  const score = matchListScore(series);
  const event = state.db?.tournaments.find((row) => row.id === series.eventId);
  return `
    <a class="match-card" href="${matchSeriesHref(series)}">
      <div class="team-side">${teamLogo(series.teamA.id)}<strong>${escapeHtml(series.teamA.name)}</strong></div>
      <div class="score-box"><strong>${score.a} : ${score.b}</strong><span>${escapeHtml(score.label)}</span></div>
      <div class="team-side right"><strong>${escapeHtml(series.teamB.name)}</strong>${teamLogo(series.teamB.id)}</div>
      <div class="match-meta">
        ${event ? eventLogo(event, "tiny") : ""}
        <span>${escapeHtml(formatDate(series.startedAt, "time"))}</span>
        <span>${escapeHtml(event?.name || series.seriesCode || "Campeonato")}</span>
        <span>${escapeHtml(matchSeriesMetaLabel(series))}</span>
      </div>
    </a>
  `;
}

function teamCard(team) {
  if (!team) return "";
  const lineupCount = team.currentLineup?.length || team.lineup?.length || 0;
  return `
    <a class="entity-card" href="#/teams/${team.id}">
      <div class="entity-row">${teamLogo(team.id)}<span class="entity-main"><strong>${escapeHtml(team.name)}</strong><span>tag: ${escapeHtml(team.sourceTag || team.id)} - nota ${fmt(team.rankingScore ?? team.points, 1)} - ${team.wins}-${team.losses}</span></span></div>
      <div class="chip-row"><span class="chip red">${teamCanonicalRankLabel(team)}</span><span class="chip">${pct(team.winRate)} WR</span><span class="chip">${lineupCount} lineup</span>${!teamIsRankingValid(team) && !rankingIsInactive(team.ranking) ? `<span class="chip">prov</span>` : ""}</div>
    </a>
  `;
}

function tournamentRow(event) {
  return `<a class="simple-row" href="#/tournaments/${event.id}">${eventLogo(event)}<span><strong>${escapeHtml(event.name)}</strong><br><span class="tiny">${escapeHtml(eventTimeRange(event))} - ${event.matches} partidas - ${event.teams.length} equipes</span></span><span class="chip event-chip ${eventStatusClass(event.status)}">${escapeHtml(event.status)}</span></a>`;
}

// Campeonato e sempre exibido por dia (sem horario); o horario continua valendo
// so para partidas, que acontecem em um horario especifico.
function eventTimeRange(event) {
  if (!event?.start && !event?.end) return "Sem janela definida";
  if (!event?.start) return `Termina ${formatDate(event.end)}`;
  if (!event?.end) return `Início ${formatDate(event.start)}`;
  const endLabel = !eventIsDone(event) && periodEndIsCurrent(event.end) ? "Atualmente" : formatDate(event.end);
  if (formatDate(event.start) === endLabel) return formatDate(event.start);
  return `${formatDate(event.start)} - ${endLabel}`;
}

function eventStatusClass(status) {
  // "Agendado" nao e "ao vivo": antes os dois caiam na mesma classe e um
  // campeonato marcado para daqui a um mes usava o selo de partida rolando.
  const value = String(status || "").toLowerCase();
  if (value.includes("finalizado")) return "done";
  if (value.includes("agendad") || value.includes("em breve")) return "scheduled";
  return "live";
}

function eventIsDone(event) {
  return eventStatusClass(event?.status) === "done";
}

function scoreNumberClass(value, opponent) {
  if (value > opponent) return "score-number win";
  if (value < opponent) return "score-number loss";
  return "score-number";
}

function playerTable(players) {
  return `
    <div class="table-wrap">
      <table>
        <thead><tr><th class="numeric">#</th><th>Jogador</th><th>Equipe</th><th class="numeric">rAAting 3.0</th><th class="numeric">Rounds</th><th class="numeric">Mapas</th><th class="numeric">ACS</th><th class="numeric">K/D</th><th class="numeric">ADR</th><th class="numeric">KAST</th><th class="numeric">Swing/R</th><th class="numeric">FK-FD</th></tr></thead>
        <tbody>${players.map((player, index) => {
          const team = teamById(player.teamId);
          const fkFdDiff = Number(player.firstKills || 0) - Number(player.firstDeaths || 0);
          return `<tr><td class="numeric">${index + 1}</td><td>${entityLink("players", player.id, player.nick)}<br><span class="tiny">${escapeHtml(player.handle)}</span>${sampleStatusChip(player)}</td><td>${team ? entityLink("teams", team.id, team.tag) : "-"}</td><td class="numeric rating-cell ${playerRatingTone(player)}">${playerRating(player)}</td><td class="numeric">${player.rounds}</td><td class="numeric">${player.matches}</td><td class="numeric">${fmt(player.acs, 0)}</td><td class="numeric">${fmt(player.kd)}</td><td class="numeric">${fmt(player.adr, 0)}</td><td class="numeric">${pct(player.kast)}</td><td class="numeric ${directionalTone(playerSwingPerRound(player))}">${formatMaybeSwing(player)}</td><td class="numeric ${signedTone(fkFdDiff)}">${signed(fkFdDiff)}</td></tr>`;
        }).join("")}</tbody>
      </table>
    </div>
  `;
}

function agentBadge(agent) {
  const name = agent?.agent || agent?.name || "Agente";
  const role = agent?.agentClass || agent?.role || "";
  const icon = agent?.agentIcon || agent?.icon || "";
  const slug = agent?.agentSlug || agent?.slug || name;
  const fallback = displayAgentName(name, slug).slice(0, 3).toUpperCase();
  const image = icon
    ? `<span class="agent-icon"><span>${escapeHtml(fallback)}</span><img src="${escapeHtml(assetPath(icon))}" alt="${escapeHtml(name)}" loading="lazy" onerror="this.remove()" /></span>`
    : `<span class="agent-icon"><span>${escapeHtml(fallback)}</span></span>`;
  return `<span class="agent-badge">${image}<span><strong>${escapeHtml(name)}</strong>${role ? `<small>${escapeHtml(role)}</small>` : ""}</span></span>`;
}

function aggregateTeamStatsForMatches(matches, teamId) {
  return matches.reduce((total, match) => {
    const stats = match.teamStats[teamId] || emptyTeamRoundStats();
    for (const key of Object.keys(total)) {
      total[key] += stats[key] || 0;
    }
    return total;
  }, emptyTeamRoundStats());
}

function agentBars(rows, options = {}) {
  if (!rows.length) return `<div class="empty-state">Sem agentes registrados.</div>`;
  return `
    <div class="bars">
      ${rows
        .map(
          (agent) => `
            <div class="bar-row agent-bar">
              <span>${agentBadge(agent)}</span>
              <div class="bar-track"><div class="bar-fill" style="width:${clamp(agent.rate, 0, 100)}%"></div></div>
              <span class="numeric">${options.showPickRate ? escapeHtml(`${agent.picks || 0} picks · ${pct(agent.rate)}`) : `${escapeHtml(String(agent.rounds))} rounds`}</span>
            </div>
          `,
        )
        .join("")}
    </div>
  `;
}

function bars(rows) {
  return `<div class="bars">${rows.map(([label, value, note]) => `<div class="bar-row"><span>${escapeHtml(String(label))}</span><div class="bar-track"><div class="bar-fill" style="width:${clamp(value, 0, 100)}%"></div></div><span class="numeric">${note ? escapeHtml(String(note)) : pct(value)}</span></div>`).join("")}</div>`;
}

function stat(value, label, title = "") {
  const titleAttr = title ? ` title="${escapeHtml(title)}"` : "";
  return `<div class="stat-card"${titleAttr}><strong>${escapeHtml(String(value))}</strong><span>${escapeHtml(label)}</span></div>`;
}

function entityLink(type, id, text) {
  const routeId = type === "players" ? playerRouteId(id) : id;
  return `<a class="subtle-link" href="#/${escapeHtml(type)}/${escapeHtml(routeId)}">${escapeHtml(text)}</a>`;
}

function logo(label, colors, extra = "") {
  return `<span class="logo ${extra}" style="background:linear-gradient(135deg, ${colors[0]}, ${colors[1]})">${escapeHtml(label)}</span>`;
}

function imageLogo(src, label, colors, extra = "", alt = "") {
  const safeSrc = assetPath(src);
  if (!safeSrc) return logo(label, colors, extra);
  return `
    <span class="logo image-logo ${extra}" style="background:linear-gradient(135deg, ${colors[0]}, ${colors[1]})">
      <span class="logo-fallback">${escapeHtml(label)}</span>
      <img src="${escapeHtml(safeSrc)}" alt="${escapeHtml(alt || label)}" loading="lazy" onerror="this.remove()" />
    </span>
  `;
}

function eventLogo(event, extra = "") {
  const label = event?.mark || eventAcronym(event?.name || event?.id || "EV");
  const src = assetPath(event?.logo || "");
  const classes = `event-logo clean-logo ${extra}`.trim();
  const alt = `Logo ${event?.name || label}`;
  if (!src) return `<span class="${escapeHtml(`${classes} logo-empty`)}" aria-label="${escapeHtml(alt)}"></span>`;
  return `<span class="${escapeHtml(classes)}"><img src="${escapeHtml(src)}" alt="${escapeHtml(alt)}" loading="lazy" onerror="this.closest('.event-logo').classList.add('logo-empty'); this.remove()" /></span>`;
}

function organizerLogo(event, extra = "") {
  const label = event?.organizer || "Organizador";
  const src = assetPath(event?.organizerLogo || event?.organizerLogoPath || "");
  const classes = `organizer-logo clean-logo ${extra}`.trim();
  const alt = `Logo ${label}`;
  if (!src) return `<span class="${escapeHtml(`${classes} logo-empty`)}" aria-label="${escapeHtml(alt)}"></span>`;
  return `<span class="${escapeHtml(classes)}"><img src="${escapeHtml(src)}" alt="${escapeHtml(alt)}" loading="lazy" onerror="this.closest('.organizer-logo').classList.add('logo-empty'); this.remove()" /></span>`;
}

// Os eventos da pagina aberta, para o escudo de epoca: a etapa, ou as etapas do
// campeonato no Geral (da mais recente para a mais antiga). Fora de campeonato, nada.
function eventosDaRota(section, id) {
  if ((section !== "events" && section !== "tournaments") || !id) return null;
  const campeonato = state.db ? campeonatoPorId(id) : null;
  return campeonato ? campeonato.etapas.map((etapa) => etapa.id) : [id];
}

// Na pagina de um campeonato, o link da equipe que jogou ali com um nome antigo
// abre o perfil ja naquela fase (`?fase=`), como o escudo e o nome da epoca.
// Link que ja traz query fica como esta.
function ligarFasesDaEpoca(html) {
  const eventos = state.eventoDaPagina || [];
  if (!eventos.length || !html) return html;
  return String(html).replace(/href="#\/teams\/([^"/?]+)((?:\/[^"/?]+)?)"/g, (inteiro, id, aba) => {
    const team = teamById(decodeURIComponent(id));
    const nomes = team?.profile?.nomes || [];
    const fase = eventos.map((eventId) => nomes.find((item) => (item.eventos || []).includes(eventId))).find(Boolean);
    return fase ? `href="#/teams/${team.id}${aba}?fase=${encodeURIComponent(fase.id)}"` : inteiro;
  });
}

function teamLogo(id, extra = "") {
  const team = teamById(id);
  const nomes = team?.profile?.nomes || [];
  const fase = (state.faseDaPagina?.teamId === team?.id && state.faseDaPagina) ||
    (state.eventoDaPagina || []).map((eventId) => nomes.find((item) => (item.eventos || []).includes(eventId))).find(Boolean);
  const src = assetPath(fase?.logo || team?.profile?.logo || team?.logo || "");
  const label = `Logo ${fase?.nome || team?.name || id}`;
  if (!src) return `<span class="team-logo clean-logo logo-empty ${escapeHtml(extra)}" aria-label="${escapeHtml(label)}"></span>`;
  return `<span class="team-logo clean-logo ${escapeHtml(extra)}"><img src="${escapeHtml(src)}" alt="${escapeHtml(label)}" loading="lazy" onerror="this.closest('.team-logo').classList.add('logo-empty'); this.remove()" /></span>`;
}

function playerLogo(id, extra = "") {
  const player = playerById(id);
  const src = playerPhotoSrc(player);
  // Marca quem esta na silhueta. So 9,6% dos jogadores tem foto, entao a
  // silhueta e a regra e nao a excecao - e onde ela aparece grande (a parede
  // da capa) ela precisa recuar para nao virar o assunto da imagem.
  const semFoto = player?.photo ? "" : " no-photo";
  const classes = `logo image-logo player-avatar round ${extra}${semFoto}`.trim();
  return `<span class="${escapeHtml(classes)}"><img src="${escapeHtml(src)}" alt="${escapeHtml(`Foto ${player?.nick || "Jogador"}`)}" loading="lazy" onerror="playerPhotoError(this)" /></span>`;
}

function playerPhotoSrc(player) {
  return assetPath(player?.photo || PLAYER_FALLBACK_PHOTO);
}

function playerPhotoError(image) {
  if (!image) return;
  image.onerror = null;
  image.src = assetPath(PLAYER_FALLBACK_PHOTO);
}

function mapLogo(id, extra = "") {
  const map = mapById(id);
  const label = (map?.name || id).slice(0, 3).toUpperCase();
  // O maior lugar onde este logo aparece tem 82px; o PNG de origem tem 1600px
  // de largura. Se o WebP faltar, imageLogo ja cai no monograma de tres letras
  // que fica atras da imagem, entao nao precisa de cadeia de fallback aqui.
  const art = mapArtAttrs(map);
  return imageLogo(art?.src || "", label, map?.colors || mapColors(id), `map-logo ${extra}`.trim(), `Mapa ${map?.name || id}`);
}

const HISTORICAL_TEAM_ROUTE_ALIASES = {
  "utfpr_azure_bears_pr_2024": "azure_bears_golden",
  "fametro_codify_team_am_2024": "fametro_berserkers",
  "ufg_eagles_black_7712cb48_2024": "ufg_eagles",
  "unicamp_tritons_2024": "unicamp_tritons_black",
  "macklogic_2024": "macklogic_red",
  "udf_thunder_fusion_df_2024": "rahnag",
  "unirv_e_sports_go_2024": "unirv_rushone",
  "eng_ufes_es_2024": "castor_vai",
  "cyber_kongs_dourada_2024": "cyberkongs",
  "ufg_eagles_black_2024": "ufg_eagles_blue",
  "maua_esports_imt_e15688a9_2024": "maua_blue",
  "maua_esports_imt_2024": "maua_b",
  "fei_esports_valorant_2024": "fei_darkowls",
  "team_valorant_cybers_2024": "unesa_cyborgs",
  "calango_team_fametro_am_668459eb_2024": "calango_team_fametro_am_2024",
  "aufa_line_a_2024": "aufa_faesa",
  "burning_bunnies_ufpr_white_2024": "ufpr_bbn",
  "ibtec_2024": "ibmec_sharks",
  "inatel_white": "inatel",
  "minerva_esports_misto_2024": "ufrj_minerva",
  "minerva_esports_ufrj_inclusivo_2024": "minerva_artemis",
  "poli_plague_gold_2024": "poli_plague",
  "stings_ba_valorant_2024": "stings_yellow",
  "stings_belas_artes_2024": "stings_yellow",
  "ufrn_rn_2024": "ufrn_tirana",
  "caap_void_2024": "caap_hellhounds_black_2024",
  "axis_anteaters_valorant_2024": "axis_anteaters",
  "axis_anteaters_black_valorant_2024": "axis_anteaters",
  "axis_anteaters_shadow": "axis_anteaters",
  "axis_ego": "caap_momentum",
  "ufpe_virtus": "incinera_esports",
  "dark_ufrj": "minerva_thunders",
  "ufrn_carcaras": "ufrn_tirana",
  "ufu_saints_trigons": "ufu_saints_onyx",
  "caaso_hogs_usp_2024": "usp_stars",
  "usp_caaso_hogs_jubs_2024": "usp_stars",
  "undb_reapers": "undbala",
  "estacio_cybers_rj_2024": "unesa_cyborgs"
};

function teamById(id) {
  const canonicalId = HISTORICAL_TEAM_ROUTE_ALIASES[id] || id;
  return state.db?.teams.find((team) => team.id === canonicalId);
}

const HISTORICAL_PLAYER_ROUTE_ALIASES = {
  "japa918": "greinzera",
  "wow": "raap",
  "yanf99": "falcao",
  "registered-yanf99": "falcao",
  "sweepzz": "swpz",
  "balalov3-s2": "balalov3",
  "harry-kane-9": "suvas",
};

function playerById(id) {
  const requested = String(id || "");
  const alias = HISTORICAL_PLAYER_ROUTE_ALIASES[requested];
  // Se uma conta reaparecer num mapa ainda nao confirmado, seu perfil
  // pendente tem prioridade sobre o redirecionamento dos mapas ja unidos.
  const hasOwnProfile = alias && state.db?.players.some((player) => player.id === requested || player.routeSlug === requested);
  const key = (hasOwnProfile ? requested : alias) || requested;
  if (!key) return null;
  const routeKey = slugify(key);
  const players = state.db?.players;
  // Conta emprestada também entra nas contas de quem jogou nela, então o dono
  // do perfil vem antes da busca por conta.
  return players?.find((player) => player.id === key || player.puuid === key) ||
    players?.find((player) => (player.accounts || []).some((account) => account.puuid === key) || player.routeSlug === routeKey);
}

// Jogador sem nenhum mapa fica fora do site (lista, busca e rota), mas segue no
// elenco como nome sem link. O perfil aparece sozinho no primeiro mapa.
function playerTemPerfil(player) {
  return Number(player?.matches || 0) > 0;
}

function playerRouteId(playerOrId) {
  const player = resolvePlayerRouteTarget(playerOrId);
  return player?.routeSlug || player?.id || String(playerOrId || "");
}

function resolvePlayerRouteTarget(playerOrId) {
  if (!playerOrId || typeof playerOrId !== "object") return playerById(playerOrId);
  return playerById(playerOrId.id || playerOrId.puuid || playerOrId.playerId) || playerOrId;
}

function playerPath(playerOrId, tab = "") {
  const id = playerRouteId(playerOrId);
  return `players/${id}${tab ? `/${tab}` : ""}`;
}

function playerHref(playerOrId, tab = "") {
  return `#/${playerPath(playerOrId, tab)}`;
}

function mapById(id) {
  return state.db?.maps.find((map) => map.id === id);
}

function mapByName(name) {
  return state.db?.maps.find((map) => map.name === name);
}

function updateDocumentTitle() {
  document.title = formatDocumentTitle(documentTitleForRoute(route()));
}

function formatDocumentTitle(title) {
  const segment = cleanDocumentTitleSegment(title);
  return segment ? `${segment} - ${SITE_NAME}` : SITE_NAME;
}

function documentTitleForRoute(currentRoute) {
  const { section, id, tab } = currentRoute;
  if (!state.ready || !state.db) return STATIC_DOCUMENT_TITLES[section] || STATIC_DOCUMENT_TITLES.home;

  if (section === "matches" && id) return matchDocumentTitle(id, tab);
  if ((section === "events" || section === "tournaments") && id) return tournamentDocumentTitle(id);
  if (section === "players" && id) return playerDocumentTitle(id);
  if (section === "teams" && id) return teamDocumentTitle(id);
  if (section === "maps" && id) return mapDocumentTitle(id);
  if (section === "news" && id) return window.News?.porSlug(id)?.titulo || STATIC_DOCUMENT_TITLES.news;

  return STATIC_DOCUMENT_TITLES[section] || STATIC_DOCUMENT_TITLES.home;
}

function matchDocumentTitle(id, tab) {
  const match = state.db.matches.find((item) => item.id === id);
  if (!match) return STATIC_DOCUMENT_TITLES.matches;
  const series = matchSeries(match);
  const aggregateMode = tab === "all" && (series.length > 1 || normalizeMatchItem(match).officialResultNote);
  const selectedMatches = aggregateMode ? series : [match];
  const score = matchDisplayScore(match, selectedMatches, aggregateMode);
  return `${matchTitleTeamTag(match.teamA)} ${score.a} x ${score.b} ${matchTitleTeamTag(match.teamB)}`;
}

function matchTitleTeamTag(side) {
  const team = teamById(side.id) || side;
  const candidates = [team.sourceTag, team.tag, side.sourceTag, side.tag, team.shortTag, side.shortTag];
  const preferred = candidates.find((value) => value && value !== side.id && value !== team.id);
  return preferred || (team.id ? teamTag(team.id) : "") || team.name || side.name || side.id;
}

function tournamentDocumentTitle(id) {
  return campeonatoPorId(id)?.nome || visibleTournaments().find((event) => event.id === id)?.name || STATIC_DOCUMENT_TITLES.events;
}

function playerDocumentTitle(id) {
  const player = playerById(id);
  if (!playerTemPerfil(player)) return STATIC_DOCUMENT_TITLES.players;
  return player.nick || player.handle || STATIC_DOCUMENT_TITLES.players;
}

function teamDocumentTitle(id) {
  return teamById(id)?.name || STATIC_DOCUMENT_TITLES.teams;
}

function mapDocumentTitle(id) {
  return mapById(id)?.name || STATIC_DOCUMENT_TITLES.maps;
}

function cleanDocumentTitleSegment(value) {
  return String(value || "").trim().replace(/\s+/g, " ");
}

function route() {
  const hash = window.location.hash.replace(/^#\/?/, "");
  // o estado de filtro viaja depois do "?", entao o caminho para de ler ali
  const [caminho] = hash.split("?");
  const [section = "home", id, tab] = caminho.split("/");
  return { section, id, tab };
}

function routeQuery() {
  const hash = window.location.hash.replace(/^#\/?/, "");
  const i = hash.indexOf("?");
  return new URLSearchParams(i >= 0 ? hash.slice(i + 1) : "");
}

function routePath() {
  return "#/" + window.location.hash.replace(/^#\/?/, "").split("?")[0];
}

// A chave de rota ignora a query de proposito: trocar um filtro nao e mudar de
// pagina, entao nao deve jogar a rolagem para o topo.
function currentRouteKey() {
  return routePath();
}

function scrollToRouteTop(routeChanged) {
  if (!routeChanged || typeof window.scrollTo !== "function") return;
  window.requestAnimationFrame(() => window.scrollTo({ top: 0, left: 0, behavior: "auto" }));
}

function resolveMapMeta(apiMapId, fallbackSlug, metadata) {
  const apiSlug = MAP_API_SLUGS[apiMapId] || slugify(fallbackSlug || apiMapFallbackName(apiMapId));
  const registered = metadata.mapsBySlug.get(apiSlug) || metadata.mapsByName.get(normalizeNameKey(fallbackSlug || ""));
  const slug = registered?.slug || apiSlug || slugify(fallbackSlug || apiMapId || "mapa");
  return {
    slug,
    name: displayEntityName(registered?.name || slug),
    icon: assetPath(registered?.icon || ""),
  };
}

function apiMapFallbackName(apiMapId) {
  const parts = String(apiMapId || "").split("/").filter(Boolean);
  return parts[parts.length - 1] || "";
}

function resolveAgentMeta(characterId, metadata) {
  const apiSlug = AGENT_API_SLUGS[characterId] || "";
  const registered = metadata.agentsBySlug.get(apiSlug);
  const slug = registered?.slug || apiSlug || characterId || "";
  return {
    slug,
    name: displayAgentName(registered?.name || slug, slug, characterId),
    role: displayEntityName(registered?.role || ""),
    icon: assetPath(registered?.icon || ""),
  };
}

function displayAgentName(name, slug, characterId) {
  if (slug === "kayo") return "KAY/O";
  if (!name && characterId) return `Agente ${characterId.slice(0, 8)}`;
  return displayEntityName(name || slug);
}

function displayEntityName(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  if (text === text.toLowerCase() || text.includes("_") || text.includes("-")) return displayText(text);
  return text;
}

function assetPath(path) {
  const value = String(path || "").trim().replaceAll("\\", "/");
  if (!value) return "";
  if (/^https?:\/\//i.test(value)) return value;
  return value.replace(/^\/+/, "");
}

function displayTeamName(id) {
  return id
    .split("_")
    .map((part) => (KNOWN_ACRONYMS.has(part) ? part.toUpperCase() : part.charAt(0).toUpperCase() + part.slice(1)))
    .join(" ");
}

function teamTag(id) {
  const parts = id.split("_");
  const acronymParts = parts.filter((part) => KNOWN_ACRONYMS.has(part));
  if (acronymParts.length) return acronymParts.map((part) => part.toUpperCase()).join("").slice(0, 5);
  return parts.map((part) => part[0]).join("").toUpperCase().slice(0, 5);
}

function displayText(id) {
  return id.split("_").map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(" ");
}

function teamColors(id) {
  const key = String(id || "").toLowerCase();
  const overrides = {
    macklogic_red: ["#ef101a", "#270407"],
    macklogic_white: ["#f5f1f2", "#ef101a"],
    macklogic_rainbow: ["#ef101a", "#6d2fff"],
    ceub_octopus: ["#8e1b8f", "#ef5ad4"],
    azure_bears_golden: ["#19a7ff", "#f4c64a"],
    azure_bears_black: ["#19a7ff", "#101820"],
  };
  return overrides[key] || colorPair(id);
}

function eventColorPair(event = {}) {
  if (Array.isArray(event.colors) && event.colors.length >= 2) return event.colors.slice(0, 2);
  return colorPair(`event-${event.id || event.name || "campeonato"}`);
}

function eventAcronym(value) {
  const clean = String(value || "EV").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const compact = clean.replace(/[^a-zA-Z0-9]/g, "");
  if (compact.length <= 5) return compact.toUpperCase();
  const stopWords = new Set(["de", "da", "do", "das", "dos", "e"]);
  const parts = clean
    .split(/[^a-zA-Z0-9]+/)
    .filter((part) => part && !stopWords.has(part.toLowerCase()));
  return (parts.map((part) => part[0]).join("") || compact.slice(0, 3)).toUpperCase().slice(0, 5);
}

function mapColors(name) {
  return colorPair(`map-${name}`);
}

// A paleta gerada sai em hex, nao em hsl(). Ate 26/08/2026 saia em hsl e o
// preco era silencioso: hexToRgb() so aceita #rrggbb, entao teamWashFor()
// abortava na primeira linha e devolvia tinta clara sobre a cor crua, sem o
// passeio que garante 4,5:1 - a Sixa Eaters, unica das 98 equipes que nao esta
// em dados_excel/teams_infos.xlsx, ficava em 2,93:1. teamPatternFor() falhava
// junto, no mesmo hexToRgb, e caia no "tecido" para toda equipe gerada.
// Mesmas cores, notacao que as guardas conseguem ler.
function colorPair(seed) {
  let hash = 0;
  for (let index = 0; index < seed.length; index += 1) hash = seed.charCodeAt(index) + ((hash << 5) - hash);
  const hue = Math.abs(hash) % 360;
  const hue2 = (hue + 145) % 360;
  return [rgbToHex(hslToRgb(hue, 64, 38)), rgbToHex(hslToRgb(hue2, 58, 22))];
}

function hslToRgb(h, s, l) {
  const sat = s / 100;
  const lum = l / 100;
  const c = (1 - Math.abs(2 * lum - 1)) * sat;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = lum - c / 2;
  const [r, g, b] =
    h < 60 ? [c, x, 0] :
    h < 120 ? [x, c, 0] :
    h < 180 ? [0, c, x] :
    h < 240 ? [0, x, c] :
    h < 300 ? [x, 0, c] : [c, 0, x];
  return [r, g, b].map((canal) => Math.round((canal + m) * 255));
}

function slugify(value) {
  return String(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

function normalize(value) {
  return slugify(value).replace(/-/g, " ");
}

function normalizeNameKey(value) {
  return normalize(value).replace(/\s+/g, "");
}

function pctValue(value, total) {
  return total ? (value / total) * 100 : 0;
}

function pct(value) {
  return `${fmt(value, 0)}%`;
}

function fmt(value, digits = 2) {
  return Number(value || 0).toFixed(digits);
}

function signed(value) {
  return value > 0 ? `+${value}` : String(value);
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function formatDate(value, mode = "date") {
  if (!value) return "-";
  const date = new Date(value);
  // "hour" existe para a lista agrupada por dia: o dia ja e o cabecalho do
  // grupo, entao a linha so precisa da hora.
  if (mode === "hour") return date.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
  const options =
    mode === "time"
      ? { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }
      : { day: "2-digit", month: "short", year: "numeric" };
  return date.toLocaleDateString("pt-BR", options).replace(".", "");
}

function formatDuration(ms) {
  if (!ms) return "-";
  const minutes = Math.floor(ms / 60000);
  const seconds = Math.floor((ms % 60000) / 1000);
  return `${minutes}m ${String(seconds).padStart(2, "0")}s`;
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

// Cada entidade carrega o proprio genero e o proprio caminho de volta: antes
// era `${entity} não encontrado.` para todas, produzindo "Equipe nao
// encontrado." e "Partida nao encontrado.", e sem nenhuma saida - num produto
// que se espalha por link colado, o link velho era um beco sem saida.
const NOT_FOUND_ENTITIES = {
  Partida: { frase: "Partida não encontrada", volta: "#/matches", voltaLabel: "Ver todas as partidas" },
  Campeonato: { frase: "Campeonato não encontrado", volta: "#/events", voltaLabel: "Ver todos os campeonatos" },
  Equipe: { frase: "Equipe não encontrada", volta: "#/ranking", voltaLabel: "Ver o ranking de equipes" },
  Jogador: { frase: "Jogador não encontrado", volta: "#/players", voltaLabel: "Ver todos os jogadores" },
  Mapa: { frase: "Mapa não encontrado", volta: "#/home", voltaLabel: "Voltar para a inicial" },
  Recurso: { frase: "Página não encontrada", volta: "#/home", voltaLabel: "Voltar para a inicial" },
};

function renderNotFound(entity) {
  const info = NOT_FOUND_ENTITIES[entity] || NOT_FOUND_ENTITIES.Recurso;
  Shell(`
    <div class="boot-state" role="alert">
      <strong>${escapeHtml(info.frase)}</strong>
      <p>O link pode estar velho, ou o item pode ter saído do site desde que ele foi compartilhado.</p>
      <a class="boot-retry" href="${info.volta}">${escapeHtml(info.voltaLabel)}</a>
    </div>
  `);
}
